window.POEM_NOTES = {
  "关雎|佚名": {
    y: "雎鸠鸟在河中小洲上关关和鸣。文静美好的姑娘，是君子理想的伴侣。长短不齐的荇菜，她左右采摘；醒着睡着都在思念她，翻来覆去难以入眠。",
    s: "《诗经》开篇之作。以雎鸠和鸣起兴，引出君子对淑女的爱慕，情感真挚而克制，「乐而不淫，哀而不伤」，奠定了中国爱情诗的基调。",
    b: "出自《诗经·周南》，是西周初年至春秋中叶的民间乐歌，后经孔子删订列入「诗三百」。"
  },
  "蒹葭|佚名": {
    y: "芦苇苍苍，白露成霜。我思念的那个人，在河水的另一方。逆流而上去寻她，道路险阻又漫长；顺流而下去寻她，她仿佛就在水中央。",
    s: "全诗三章复沓，营造出水雾迷茫、可望而不可即的意境。「伊人」究竟是谁——爱人、理想还是道——千百年来引人无限遐想，是含蓄美的极致。",
    b: "出自《诗经·秦风》，春秋时期流传于今陕西一带的民歌。"
  },
  "观沧海|曹操": {
    y: "东行登上碣石山，眺望苍茫的大海。海水浩荡，山岛耸立；树木丛生，百草丰茂。秋风吹来，巨浪涌起。日月星辰，仿佛都从这海中运行升起。",
    s: "中国现存第一首完整的山水诗。曹操以大海自况，吞吐日月、包蕴星汉的气象，正是他囊括天下的胸襟写照。",
    b: "建安十二年（207年）曹操北征乌桓，得胜回师途经碣石山时所作，是组诗《步出夏门行》的首章。"
  },
  "龟虽寿|曹操": {
    y: "神龟虽能长寿，终有死亡之时；腾蛇虽能乘雾，终究化为土灰。年老的千里马伏在马槽旁，雄心仍在千里驰骋；有志之士即使到了晚年，壮志也不会消沉。",
    s: "「老骥伏枥，志在千里」成为千古名言。诗人不服老、不信命，把生命的长度交给天，把生命的价值握在自己手里，慷慨激昂。",
    b: "写于北征乌桓之后，曹操时年五十三岁，正值事业巅峰却已感到岁月紧迫。"
  },
  "饮酒·其五|陶渊明": {
    y: "在尘世中建屋居住，却听不到车马的喧闹。为何能如此？心远离了世俗，居所自然偏远。东篱下采菊，悠然望见南山。山气日夕美好，飞鸟结伴归还，其中自有真意，想要分辨却已忘了言语。",
    s: "「采菊东篱下，悠然见南山」是田园诗的巅峰意象。物我两忘、得意忘言，把隐居生活的闲适与人生真谛融为一炉。",
    b: "陶渊明辞去彭泽县令后归隐田园，《饮酒》组诗二十首写于归隐之后，此为其五。"
  },
  "木兰诗|佚名": {
    y: "织布声一声接一声，木兰对着门织布，听不见机杼声，只听见她的叹息。原来可汗大点兵，父亲在名册上，木兰决定女扮男装、替父从军。十二年后凯旋，她谢绝高官，只求还乡，脱下战袍重着女儿装，同行伙伴这才惊觉：木兰竟是女郎。",
    s: "北朝民歌的压卷之作，与《孔雀东南飞》并称「乐府双璧」。详写战前准备与战后还乡，略写十年征战，剪裁大胆；木兰既是英雄又是普通女儿，形象亲切丰满。",
    b: "产生于北朝时期，记录了北方民族尚武的社会风气，「安能辨我是雄雌」成为挑战性别成见的千古一问。"
  },
  "长歌行|佚名": {
    y: "园中葵菜青青，朝露等待阳光晒干。春天把恩惠洒遍大地，万物生机焕发。常怕秋天来到，花叶枯黄衰败。百川东流入海，何时能再西归？年少时不努力，年老只能空自悲伤。",
    s: "由园中葵起兴，经四季流转、百川东去，自然引出「少壮不努力，老大徒伤悲」的千古劝诫，形象与哲理浑然一体。",
    b: "汉乐府民歌，属《相和歌辞》，是汉代无名氏作品。"
  },
  "送杜少府之任蜀州|王勃": {
    y: "三秦之地拱卫着长安，遥望蜀地，风烟渺茫。与你离别，同是宦游之人。四海之内有知心朋友，即使远在天边也如近邻。不要在岔路口像小儿女一样泪湿衣巾。",
    s: "一扫送别诗的悲切，「海内存知己，天涯若比邻」以豁达的胸襟写友情，境界阔大，成为送别诗的千古绝唱。",
    b: "王勃在长安任职时，送友人杜某赴蜀州任县尉所作，是初唐五律的成熟之作。"
  },
  "登幽州台歌|陈子昂": {
    y: "向前看不见古代的贤君，向后望不到后世的明主。想到天地悠悠无穷无尽，不禁独自悲伤，潸然泪下。",
    s: "仅二十二个字，把个人遭际放到无穷的时间与空间里对照，孤独感惊天动地。语言苍劲奔放，一扫齐梁绮靡诗风。",
    b: "陈子昂随武攸宜北征契丹，屡献奇计不被采纳，反遭贬斥，登蓟北楼（幽州台）慨然作歌。"
  },
  "次北固山下|王湾": {
    y: "行舟于青山绿水之间，潮水涨满，江面开阔，顺风行船，船帆高悬。海上的太阳在残夜里升起，江上的新春闯入旧年。家书何处送达？希望北归的大雁捎到洛阳。",
    s: "「海日生残夜，江春入旧年」蕴含新旧交替的自然理趣，气象恢宏，被宰相张说题于政事堂，作为诗文的典范。",
    b: "王湾进士及第前漫游江南，途经镇江北固山时触景生情而作。"
  },
  "使至塞上|王维": {
    y: "轻车简从出使边塞，途经居延。如飘飞的蓬草出了汉塞，如北归的大雁飞入胡天。大漠中一缕孤烟笔直上升，黄河上一轮落日浑圆。在萧关遇到侦察骑兵，得知都护还在前线。",
    s: "「大漠孤烟直，长河落日圆」以几何般简练的线条勾勒出塞外奇景，被王国维称为「千古壮观」，诗中有画的典范。",
    b: "开元二十五年，王维以监察御史身份奉使凉州，慰问河西节度副大使崔希逸，此诗写于赴边途中。"
  },
  "山居秋暝|王维": {
    y: "空山新雨过后，秋意初凉。明月照在松林间，清泉在石上流淌。竹林喧响是洗衣女子归来，莲叶摇动是渔舟顺流而下。春日的芳华任它消逝，秋天的山中自可久留。",
    s: "「明月松间照，清泉石上流」动静相生、光影交错，构成一幅有声有色的山居秋夜图，寄托了诗人高洁的情怀与归隐的志趣。",
    b: "王维晚年隐居辋川别墅期间所作，是他山水田园诗的代表作。"
  },
  "九月九日忆山东兄弟|王维": {
    y: "独自在异乡做客，每逢佳节就加倍思念亲人。遥想兄弟们今日登高插茱萸时，会发现少了我一个人。",
    s: "「每逢佳节倍思亲」道尽了天下游子的共同心事。后两句不直写自己思亲，而是想象兄弟们登高时发现缺少自己，曲折见情，更为动人。",
    b: "王维十七岁时客居长安，适逢九九重阳节，思念蒲州（今山西永济）的兄弟而作。"
  },
  "静夜思|李白": {
    y: "明亮的月光洒在床前，地上仿佛铺了一层白霜。抬头仰望天上的明月，低头思念远方的故乡。",
    s: "二十个字，一个举头一个低头，把千古游子共通的月夜乡愁写得自然天成。明白如话却意境深远，是传唱度最高的唐诗。",
    b: "作于唐玄宗开元十四年，李白二十六岁旅居扬州旅舍，秋夜望月思乡。"
  },
  "望庐山瀑布|李白": {
    y: "阳光照耀香炉峰升起紫色云烟，远远望去瀑布像长河悬挂在山前。飞流直下三千尺，让人怀疑是银河从九天倾泻而下。",
    s: "「飞流直下三千尺，疑是银河落九天」以极度夸张和瑰丽想象写瀑布气势，是李白浪漫主义的标志性画面。",
    b: "李白漫游庐山时所作，共两首，这是第二首七言绝句。"
  },
  "早发白帝城|李白": {
    y: "清晨辞别彩云缭绕的白帝城，千里之外的江陵一天就可到达。两岸猿声还在耳边不停啼叫，轻快的小舟已穿过万重青山。",
    s: "全诗节奏如江水奔流，「轻舟已过万重山」既是写实又暗喻劫后余生的畅快，景中寓情，快人快语。",
    b: "乾元二年李白因永王李璘案流放夜郎，行至白帝城遇赦东归，惊喜交加写下此诗。"
  },
  "黄鹤楼送孟浩然之广陵|李白": {
    y: "老朋友在西边的黄鹤楼向我告别，在烟花三月的美好时节东下扬州。孤帆的影子渐渐消失在碧空尽头，只看见长江水向天边奔流。",
    s: "不写离愁写目送：帆影消失后仍久久伫立，眼中只剩长江天际流。深情全部藏在「孤帆远影碧空尽」的画面里。",
    b: "开元年间，李白在黄鹤楼送别比他年长十二岁的诗友孟浩然前往扬州，时二人交谊正笃。"
  },
  "望天门山|李白": {
    y: "天门山被长江从中劈开，碧绿的江水到此回旋澎湃。两岸青山相对耸立，一片孤帆从日边驶来。",
    s: "山因水而开，水因山而回，山水相映成势。末句孤帆远来，为壮丽的山水画卷点上灵动一笔。",
    b: "开元十三年，二十五岁的李白初出巴蜀，乘船东下途经天门山，豪情满怀而作。"
  },
  "闻王昌龄左迁龙标遥有此寄|李白": {
    y: "杨花落尽、杜鹃哀啼的时节，听说你被贬龙标，要跋涉过五溪。我把满腔愁心托付给明月，让它随风伴你一直到夜郎以西。",
    s: "「我寄愁心与明月，随君直到夜郎西」——明月本无情，诗人偏要它做信使，想象奇绝而情真意切。",
    b: "王昌龄因「不护细行」被贬龙标县尉，李白闻讯写下此诗遥寄同情与慰藉。"
  },
  "行路难|李白": {
    y: "金杯美酒、玉盘珍馐摆在面前，我却放下杯筷无心下咽。想渡黄河冰封塞川，想登太行大雪满山。闲来在碧溪上垂钓，忽又梦见乘船经过日月旁边。行路难啊，多歧路，如今身在何处？总有一天我要乘长风破万里浪，高挂云帆横渡沧海！",
    s: "从停杯投箸的苦闷到直挂云帆的呐喊，情感的跌宕转折一气呵成。「长风破浪会有时，直挂云帆济沧海」成为逆境中自我激励的第一名句。",
    b: "天宝三载，李白被唐玄宗「赐金放还」，离京前朋友设宴饯行，愤懑与希望交织而作。"
  },
  "望岳|杜甫": {
    y: "泰山究竟如何雄伟？走出齐鲁大地依然可见它青翠的峰峦。大自然把神奇秀丽都赋予了它，山南山北判若晨昏。层云生起荡涤心胸，睁大眼睛目送归鸟入山。一定要登上最高峰，那时俯瞰群山，都会觉得渺小。",
    s: "「会当凌绝顶，一览众山小」写尽青年杜甫的凌云壮志。全诗无一「望」字却句句写望，由远及近，层层递进。",
    b: "开元二十四年起杜甫漫游齐赵，途经泰山所作，是现存杜诗中最早的作品之一。"
  },
  "春望|杜甫": {
    y: "国都沦陷，山河依旧；春天来到，城中草木丛生。感伤时事，见花也落泪；怅恨离别，闻鸟也惊心。战火连续三个月，一封家信抵得上万两黄金。满头白发越挠越短，几乎插不住簪子了。",
    s: "「感时花溅泪，恨别鸟惊心」——花鸟本娱人，因人心悲伤而溅泪惊心。国破之痛与思家之情层层交织，沉郁顿挫。",
    b: "至德二载春，杜甫身陷安史叛军占领的长安，目睹都城残破景象而作。"
  },
  "蜀相|杜甫": {
    y: "诸葛丞相的祠堂何处寻？锦官城外柏树森森。碧草自绿阶前，黄鹂空自鸣叫。三顾茅庐论天下大计，辅佐先帝后主两代老臣。出兵未捷身先死，长使千古英雄泪满襟。",
    s: "「出师未捷身先死，长使英雄泪满襟」写尽壮志未酬的千古遗恨，既是悼诸葛亮，也是自伤怀抱。",
    b: "乾元三年杜甫定居成都后，探访武侯祠，追慕诸葛亮功业，有感于自身报国无门而作。"
  },
  "闻官军收河南河北|杜甫": {
    y: "剑门外忽传收复蓟北的喜讯，初闻时泪水沾满衣裳。回头看妻儿，愁云一扫而空；胡乱卷起诗书，欣喜若狂。白日放歌须纵酒，趁着大好春光启程还乡。即从巴峡穿巫峡，再下襄阳直奔洛阳。",
    s: "杜甫「生平第一快诗」。忽传、初闻、却看、漫卷，一连串动作写狂喜；尾联四句四个地名一泻千里，归心似箭。",
    b: "广德元年春，延续八年的安史之乱终告平定，流寓梓州的杜甫闻讯喜极而作。"
  },
  "春夜喜雨|杜甫": {
    y: "好雨仿佛懂得时节，正当春天就及时降临。随风悄悄潜入夜空，细细密密滋润万物。野外云黑路暗，江船渔火独明。清晨再看那带雨的红花，定是沉甸甸开满锦官城。",
    s: "一个「知」字把雨写活了。「润物细无声」既状春雨之柔，又暗喻潜移默化的教化之功，体贴入微。",
    b: "上元二年春，杜甫定居成都草堂，亲自耕作养花，对春雨润物有真切体会。"
  },
  "茅屋为秋风所破歌|杜甫": {
    y: "八月秋风怒号，卷走我屋顶上几层茅草，茅草飞过江去，有的挂树梢，有的沉塘坳。南村群童欺我年老，公然抱茅入竹去。夜里屋漏床湿，孩子把被里都蹬破了，长夜难眠。何时能有千万间广厦，庇护天下寒士，让他们都开颜欢笑？那时即使我的茅屋被吹破、自己受冻而死，也心甘情愿！",
    s: "从自家屋漏之痛推及天下寒士，「安得广厦千万间，大庇天下寒士俱欢颜」展现了推己及人的博大胸怀，是杜甫人道主义精神的最强音。",
    b: "上元二年秋，杜甫成都草堂的茅屋被秋风吹破，连夜屋漏，有感而作。"
  },
  "登鹳雀楼|王之涣": {
    y: "夕阳依傍群山慢慢沉落，黄河向着大海滔滔奔流。想要看得更远，就要再登上一层楼。",
    s: "前两句写眼前壮阔山河，后两句翻出不凡哲理。「欲穷千里目，更上一层楼」成为进取精神的通用语，景、情、理水乳交融。",
    b: "王之涣早年漫游时登临蒲州鹳雀楼所作，是唐代五绝的压卷之作。"
  },
  "凉州词|王之涣": {
    y: "黄河仿佛从白云间奔流而来，一座孤城坐落在万丈高山之中。羌笛何必吹奏哀怨的《折杨柳》？春风本来就吹不到玉门关外。",
    s: "「春风不度玉门关」既写边地苦寒，又暗讽朝廷不恤戍卒。悲壮苍凉而气韵沉雄，被推为唐人七绝压卷之作之一。",
    b: "唐代边塞诗名篇，写戍守凉州将士的乡思，「旗亭画壁」的典故即由此诗而来。"
  },
  "出塞|王昌龄": {
    y: "依旧是秦汉时的明月、秦汉时的边关，万里征战的将士至今未还。倘若飞将军李广还在，绝不会让敌人的战马越过阴山。",
    s: "「秦时明月汉时关」一句互文，把千年边患的历史纵深感拉到眼前。被明代李攀龙推为唐人七绝压卷之作。",
    b: "王昌龄早年赴边塞时所作，慨叹边将无能、征人未还，寄托对良将安边的期盼。"
  },
  "芙蓉楼送辛渐|王昌龄": {
    y: "寒雨连江，夜入吴地，清晨在芙蓉楼送你北归，眼前只剩楚山孤影。洛阳的亲友如果问起我，就说我的心仍像玉壶中的冰一样纯洁。",
    s: "「一片冰心在玉壶」以玉壶冰自喻清白坚贞的品格，送别诗不写离愁写操守，立意高远。",
    b: "王昌龄时任江宁县丞，遭人非议，借送别友人辛渐表明心迹。"
  },
  "别董大|高适": {
    y: "黄云千里使日光昏暗，北风吹雁、大雪纷飞。不必忧愁前路没有知己，天下还有谁不认识您呢？",
    s: "「莫愁前路无知己，天下谁人不识君」在凄寒背景中喊出豪迈之声，慰藉中见风骨，是送别诗中别具一格的壮语。",
    b: "高适与著名琴师董庭兰相遇时同处困顿，离别时以诗相赠共勉。"
  },
  "白雪歌送武判官归京|岑参": {
    y: "北风卷地吹折白草，胡天八月就下起了雪。忽然如一夜春风吹来，千树万树梨花开。雪落珠帘湿了罗幕，狐裘不暖锦被也薄。将军角弓冻得拉不开，都护铁衣冷得难穿上。瀚海冰封百丈，愁云惨淡万里。中军设酒饯行，胡琴琵琶羌笛齐奏。傍晚大雪落满辕门，红旗冻僵在风里不能翻卷。轮台东门送你离去，雪满天山路，山回路转不见你，雪上只留下马蹄的印迹。",
    s: "「忽如一夜春风来，千树万树梨花开」以春景写冬雪，奇绝壮美。全诗以雪为线索串起送别，气势磅礴又情韵悠长。",
    b: "岑参第二次出塞，任安西北庭节度使封常清幕僚，在轮台送同僚武某返京时作。"
  },
  "黄鹤楼|崔颢": {
    y: "昔人已乘黄鹤离去，此地只留下黄鹤楼。黄鹤一去不再回来，千百年来只见白云悠悠。晴日里汉阳树木清晰可见，鹦鹉洲上芳草茂盛。傍晚时分何处是故乡？江面烟波使人忧愁。",
    s: "前四句打破格律、一气呵成，后四句严整工丽，古律相间而气象浑成。传说李白登楼见此诗而搁笔：「眼前有景道不得，崔颢题诗在上头。」",
    b: "崔颢登武昌黄鹤楼吊古怀乡而作，被严羽《沧浪诗话》推为唐人七律第一。"
  },
  "春晓|孟浩然": {
    y: "春夜酣睡不知不觉天已亮，到处听见鸟儿的啼鸣。想起昨夜风声雨声，不知有多少花儿被吹落。",
    s: "从听觉落笔写春天：鸟啼是晴，风雨是昨，花落是惜。二十字里有春天的生机与怜惜，天然浑成。",
    b: "孟浩然早年隐居鹿门山时所作，是流传最广的唐诗之一。"
  },
  "过故人庄|孟浩然": {
    y: "老朋友备下饭菜，邀我到田家做客。绿树环绕村庄，青山斜倚城郭。开窗面对谷场菜园，把酒闲谈农事。等到九九重阳节，还要再来赏菊饮酒。",
    s: "「绿树村边合，青山郭外斜」对仗自然如口语，全诗如话家常，田园的恬静与友情的醇厚水乳交融。",
    b: "孟浩然隐居襄阳时，应邀到农村老友家做客，归后所作。"
  },
  "咏柳|贺知章": {
    y: "高高的柳树像用碧玉妆扮而成，万千枝条垂下如绿色丝带。这细细的叶子是谁裁剪出来的？二月的春风就像一把剪刀。",
    s: "把无形的春风比作有形的剪刀，构思新奇。「不知细叶谁裁出，二月春风似剪刀」赋予春风创造性的人格。",
    b: "贺知章晚年告老还乡时所作，借咏柳赞美春天的创造力。"
  },
  "回乡偶书|贺知章": {
    y: "年少离家，到老了才回来，乡音虽未改变，鬓发已经疏落。孩子们见了都不认识，笑着问：客人您从哪里来？",
    s: "「少小离家老大回」人人心中有、个个笔下无。儿童的笑问天真无邪，却反衬出久客伤老的无限感慨。",
    b: "天宝三载，八十六岁的贺知章辞官还乡，距他离乡已五十余年。"
  },
  "赋得古原草送别|白居易": {
    y: "原野上的草一年一枯荣。野火烧不尽它，春风吹来又复生。远芳侵入古道，晴翠连接荒城。又送友人离去，萋萋芳草满含离别之情。",
    s: "「野火烧不尽，春风吹又生」写野草顽强的生命力，成为赞美坚韧精神的千古名句，赋得体而能自出新意。",
    b: "相传是白居易十六岁应考习作，以此诗谒见名士顾况，顾况读后叹服：「有句如此，居天下亦不难。」"
  },
  "钱唐湖春行|白居易": {
    y: "从孤山寺北、贾亭西出发，春水初涨与岸齐平，白云低垂与湖相连。早来的黄莺争抢向阳的树，新来的燕子啄泥筑巢。缤纷的春花渐渐迷乱人眼，浅浅的春草刚能没过马蹄。最爱湖东一带美景，绿杨阴里的白沙堤，怎么走也不够。",
    s: "以游踪为线，莺燕花草皆是早春「初、早、新、渐」的情态，「乱花渐欲迷人眼，浅草才能没马蹄」体物入微。",
    b: "长庆年间白居易任杭州刺史时，春日游览西湖（钱塘湖）所作。"
  },
  "暮江吟|白居易": {
    y: "一道残阳铺洒在江面上，半江碧绿半江绯红。最可爱的是九月初三的夜晚，露水像珍珠，新月像弯弓。",
    s: "「半江瑟瑟半江红」——受光的半江红，背光的半江碧，色彩对照如画；末以真珠、弯弓设喻，夜景清丽可爱。",
    b: "长庆二年白居易自请外放，赴杭州刺史任途中，心情轻松畅快，见暮色江景而作。"
  },
  "江雪|柳宗元": {
    y: "千山之中没有飞鸟的踪迹，万条路上没有行人的踪影。只有一叶孤舟上，披蓑戴笠的老翁，独自在寒冷的江雪中垂钓。",
    s: "前两句以「绝」「灭」造出极端寂静的天地，后两句孤舟独钓的渔翁正是诗人孤高傲岸、不屈于厄运的自我写照。",
    b: "柳宗元因永贞革新失败被贬永州司马，政治失意中借寒江独钓寄寓坚守之志。"
  },
  "山行|杜牧": {
    y: "沿着弯曲的石子小路上寒山，在白云升起的地方隐约有人家。停下车来只因喜爱这枫林晚景，经霜的枫叶比二月的春花还要红艳。",
    s: "「霜叶红于二月花」一反悲秋传统，把深秋枫叶写得比春花更热烈，英爽俊拔，理趣与画意兼备。",
    b: "杜牧秋日山行即景之作，展现其对自然之美的敏锐发现。"
  },
  "清明|杜牧": {
    y: "清明时节细雨纷纷，路上行人神情凄迷。请问哪里有酒家？牧童遥遥指向杏花深处的村庄。",
    s: "雨纷纷、欲断魂，写尽清明特有的凄迷氛围；末句牧童遥指，画面一转，留下悠长余味，是节日诗中传诵最广的一首。",
    b: "杜牧任池州刺史时逢清明细雨，触景而作。"
  },
  "泊秦淮|杜牧": {
    y: "烟雾笼罩寒水，月光笼罩沙滩，夜晚停船在秦淮河靠近酒家的地方。歌女不懂亡国之恨，隔着江水还在唱《玉树后庭花》。",
    s: "「商女不知亡国恨，隔江犹唱后庭花」借陈后主亡国之音，讽刺晚唐统治者醉生梦死，曲笔写忧愤，警策深沉。",
    b: "杜牧夜泊金陵秦淮河，眼见统治者奢靡享乐、国势日衰，有感而作。"
  },
  "夜雨寄北|李商隐": {
    y: "你问我归期，我也说不好何时能回。今夜巴山夜雨涨满秋池。什么时候能和你倚坐西窗剪烛夜话，那时再向你讲述今夜巴山听雨的心情。",
    s: "「何当共剪西窗烛，却话巴山夜雨时」——从今夜之雨预想他日重逢夜话，时空回环往复，语浅情深，是李商隐最温情的诗。",
    b: "李商隐滞留巴蜀时，寄赠远在长安的妻子（一说友人）之作。"
  },
  "无题|李商隐": {
    y: "相见难，离别更难，何况在东风无力的暮春。春蚕到死才吐尽丝，蜡烛烧成灰才干泪。晨起对镜只怕鬓发变白，夜吟应觉月光清寒。蓬莱山不远，请青鸟替我去探望她。",
    s: "「春蚕到死丝方尽，蜡炬成灰泪始干」以谐音双关（丝/思）写至死不渝的思念，缠绵悱恻，成为爱情诗的顶级名句。",
    b: "李商隐《无题》组诗多写爱情，本事难考，正因其朦胧而意蕴无穷。"
  },
  "锦瑟|李商隐": {
    y: "锦瑟为什么有五十根弦？一弦一柱都让我想起逝去的年华。庄周梦蝶，望帝化鹃。沧海月明，鲛人泪落成珠；蓝田日暖，美玉升起烟霭。这份情怀岂是今天回忆时才怅惘？当时就已惘然了。",
    s: "全诗意象华美而旨趣朦胧，悼亡、自伤、咏物诸说并存，「此情可待成追忆，只是当时已惘然」道尽追忆之美与惘然之痛。",
    b: "约作于李商隐晚年，是义山诗中最难解也最负盛名的一篇。"
  },
  "游子吟|孟郊": {
    y: "慈爱的母亲手中穿针引线，为即将远行的儿子缝制衣衫。临行前一针针缝得细密，担心儿子迟迟不归。谁说小草般微弱的孝心，报答得了春天阳光般的母爱？",
    s: "「谁言寸草心，报得三春晖」以小草与春晖设喻，写尽母爱的博大与孝心的难报，千年来唤起无数人的共鸣。",
    b: "孟郊五十岁任溧阳县尉，接母亲同住，感念半生漂泊中母亲的牵挂而作，题下自注「迎母溧上作」。"
  },
  "乌衣巷|刘禹锡": {
    y: "朱雀桥边长满野草野花，乌衣巷口夕阳西斜。从前在王谢堂前筑巢的燕子，如今飞进了普通百姓家。",
    s: "不著一字议论，只写桥边野草、巷口夕阳、堂前旧燕，六朝的繁华与眼前的冷落自在对照之中，「旧时王谢堂前燕，飞入寻常百姓家」是咏史的妙笔。",
    b: "宝历二年刘禹锡由和州返洛阳途经金陵，作《金陵五题》，此为第二首。"
  },
  "酬乐天扬州初逢席上见赠|刘禹锡": {
    y: "在巴山楚水这些凄凉之地，我被贬置了二十三年。怀念旧友只能吟诵闻笛之赋，回乡恍如隔世之人。沉船旁边有千帆竞发，病树前头是万木逢春。今日听你高歌一曲，且借这杯酒振作精神。",
    s: "「沉舟侧畔千帆过，病树前头万木春」以沉舟病树自况却毫不颓唐，翻出新旧更替的昂扬哲理，是逆境诗的巅峰。",
    b: "宝历二年，刘禹锡结束二十三年贬谪北返，在扬州与白居易相遇，酬答白的赠诗而作。"
  },
  "元日|王安石": {
    y: "爆竹声中旧的一年过去，春风送暖，人们畅饮屠苏酒。千家万户被朝阳照得明亮，都忙着把旧桃符换成新桃符。",
    s: "爆竹、屠苏、新桃符，三个年俗意象写出万象更新的春节气象，也寄托了诗人推行新政、除旧布新的政治抱负。",
    b: "王安石初拜相、推行新法之时，见新年气象联想到变法图强，欣然命笔。"
  },
  "泊船瓜洲|王安石": {
    y: "京口与瓜洲只隔一江水，钟山也不过数重山之遥。春风又一次吹绿了江南两岸，明月什么时候才能照着我回家？",
    s: "「春风又绿江南岸」的「绿」字历经十数次改定，由形容词活用为动词，一字传神，是炼字的千古范例。",
    b: "熙宁八年王安石二次拜相，自江宁赴京途中泊船瓜洲，眷恋故里而作。"
  },
  "饮湖上初晴后雨|苏轼": {
    y: "晴天时西湖波光潋滟正美，雨天时山色空濛也很奇妙。若把西湖比作西施，无论淡妆还是浓抹，都那么相宜。",
    s: "「欲把西湖比西子，淡妆浓抹总相宜」以西施喻西湖，从此西湖有了「西子湖」的别称，是咏西湖诗的绝唱。",
    b: "熙宁六年苏轼任杭州通判时所作，同题共二首，此为第二首。"
  },
  "题西林壁|苏轼": {
    y: "正面看是山岭，侧面看是山峰；远近高低，姿态各不相同。看不清庐山的真面目，只因为自己就站在这山里面。",
    s: "「不识庐山真面目，只缘身在此山中」借观山说理：当局者迷，旁观者清。写景与哲理浑然一体，是宋诗理趣的代表。",
    b: "元丰七年苏轼由黄州改贬汝州，途经庐山，题诗于西林寺壁。"
  },
  "水调歌头|苏轼": {
    y: "明月从什么时候开始有的？举杯问苍天。不知天上宫阙，今晚是哪一年。想乘风归去，又怕琼楼玉宇太高太冷。起舞弄着清影，何似在人间。月光转过朱楼，低照绮窗，照着无眠的我。月亮不该有恨，为何总在离别时圆？人有悲欢离合，月有阴晴圆缺，此事自古难全。只愿人长久，即使相隔千里，也能共赏这一轮明月。",
    s: "中秋词的千古绝唱。从问天到问月，从出世之想到入世之情，最后落在「但愿人长久，千里共婵娟」的旷达祝愿上，清雄旷达，历来被推为中秋词第一。",
    b: "熙宁九年中秋，苏轼在密州任上，怀念七年未见的弟弟苏辙，大醉而作此词。"
  },
  "游山西村|陆游": {
    y: "莫笑农家腊月酿的酒浑浊，丰收年景待客的菜肴很丰盛。山峦重叠、水道弯弯，正怀疑无路可走，忽然柳暗花明，又出现一个村庄。箫鼓声近，春社日将临，村民衣冠简朴古风犹存。从今若得闲乘月出游，我还要拄杖随时来叩门。",
    s: "「山重水复疑无路，柳暗花明又一村」写尽绝处逢生的境界，既是山村行旅的实景，又蕴含人生哲理，流传极广。",
    b: "乾道三年，陆游罢官闲居山阴老家，游镜湖旁山西村有感而作。"
  },
  "示儿|陆游": {
    y: "我本就知道人死后万事皆空，唯一痛心的是没能亲眼看到国家统一。等到大宋军队收复中原那一天，家祭时别忘了把这个消息告诉你们的父亲。",
    s: "绝笔之作，临终念念不忘的不是家事而是国事。「王师北定中原日，家祭无忘告乃翁」九百年后读来仍令人动容。",
    b: "嘉定二年冬，八十五岁的陆游临终前写给儿子们的遗嘱诗，是他一生爱国情怀的最后凝结。"
  },
  "十一月四日风雨大作|陆游": {
    y: "僵卧在孤村里并不自哀，还想着为国家戍守边疆。深夜躺着听风吹雨打，梦中仿佛骑着披铁甲的战马跨过冰封的河流。",
    s: "「夜阑卧听风吹雨，铁马冰河入梦来」——现实的僵卧与梦中的征战形成强烈对照，六十八岁老诗人的报国之志跃然纸上。",
    b: "绍熙三年，陆游退居山阴，风雨之夜触景生情，写下这组诗（此为其二）。"
  },
  "破阵子|辛弃疾": {
    y: "醉里挑亮油灯看宝剑，梦中回到号角连营。八百里牛肉分给部下，五十弦乐器奏出悲壮军乐，沙场秋点兵。战马像的卢一样飞快，弓弦如霹雳般震响。本想完成君王收复中原的大业，赢得生前身后名，可惜如今已是满头白发！",
    s: "前九句一路壮怀激烈，结句「可怜白发生」猛然跌落，理想与现实的巨大落差喷薄而出，是辛词悲壮风格的代表。",
    b: "辛弃疾失意闲居江西时，寄赠志同道合的好友陈亮（字同甫）之作。"
  },
  "西江月|辛弃疾": {
    y: "明月升上枝头惊起喜鹊，清风半夜送来蝉鸣。稻花香里谈论着丰收年景，听取蛙声一片。七八个星星挂在天边，两三点雨落在山前。从前熟悉的茅店还在社林边，拐了个弯，忽然就出现在眼前。",
    s: "全词用白描写乡村夏夜：月、鹊、风、蝉、稻香、蛙声、疏星、微雨，平淡景物中满是丰收的喜悦与生活的热爱。",
    b: "辛弃疾闲居上饶带湖期间，夜行黄沙岭道中所见所感。"
  },
  "小池|杨万里": {
    y: "泉眼无声，仿佛吝惜那涓涓细流；树阴映水，喜爱这晴日的柔光。小荷刚露出尖尖的角，早就有蜻蜓立在上头了。",
    s: "「小荷才露尖尖角，早有蜻蜓立上头」捕捉刹那间的生机，小巧玲珑又意蕴悠长，成为新生事物最经典的写照。",
    b: "杨万里「诚斋体」小诗的代表，写日常生活里随处可见的小景，清新自然。"
  },
  "晓出净慈寺送林子方|杨万里": {
    y: "到底是六月的西湖，风光与别的季节不同。满湖的莲叶一直铺到天边，碧绿无穷；荷花映着朝阳，红得格外鲜艳。",
    s: "「接天莲叶无穷碧，映日荷花别样红」用夸张与对仗写尽六月西湖的浓烈色彩，碧绿与别样红形成强烈视觉冲击。",
    b: "淳熙十四年，杨万里清晨出杭州净慈寺送别赴福州任职的友人林子方而作。"
  },
  "春日|朱熹": {
    y: "风和日丽在泗水边踏青，无边风光焕然一新。人人都认得春风的面容——万紫千红的花开，就是春天的样子。",
    s: "「等闲识得东风面，万紫千红总是春」表面写游春，实寓求道：圣人之道如春风化雨，万紫千红皆其化育。",
    b: "泗水在宋时已沦陷于金，朱熹未曾亲至，此诗实为借景言志的哲理诗。"
  },
  "观书有感|朱熹": {
    y: "半亩大的方形池塘像一面打开的镜子，天光云影在水中徘徊。池塘里的水为什么这样清澈？因为有源头不断送来活水。",
    s: "「问渠那得清如许，为有源头活水来」借池塘清澈喻心智开明：不断学习新知识，思想才能常新，是说理诗的典范。",
    b: "朱熹读书有感而作，以形象喻抽象哲理，同题共二首，此为其一。"
  },
  "满江红|岳飞": {
    y: "怒发冲冠，凭栏处，一场急雨刚停。仰天长啸，壮怀激烈。三十年的功名如尘土，八千里的征程伴云月。莫等闲，白了少年头，空悲切！靖康之耻还未洗雪，臣子之恨何时能灭？定要驾长车，踏破贺兰山缺。壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头收拾旧山河，朝天阙！",
    s: "千古忠愤第一词。「莫等闲、白了少年头，空悲切」既是自励也是励人，全词字字掷地有声，成为中华民族爱国精神的符号。",
    b: "约作于绍兴年间岳飞北伐前后，抒发收复中原、洗雪国耻的壮志。"
  },
  "过零丁洋|文天祥": {
    y: "回想我由科举入仕历尽艰辛，战火中已度过四年。山河破碎如风中的柳絮，身世浮沉如雨打的浮萍。惶恐滩头诉说惶恐，零丁洋里叹息零丁。人生自古以来谁能不死？留取一颗丹心照耀史册！",
    s: "「人生自古谁无死？留取丹心照汗青」以死明志，气贯长虹，成为中华民族舍生取义精神的千古绝唱。",
    b: "祥兴二年，文天祥兵败被俘，元军押他经过零丁洋，他以此诗明志拒降。"
  },
  "天净沙|马致远": {
    y: "枯藤缠绕的老树上栖息着黄昏的乌鸦，小桥下流水旁有人家，荒凉的古道上，一匹瘦马顶着西风前行。夕阳向西落下，伤心的旅人还漂泊在天涯。",
    s: "二十八字，九个名词意象叠加成画，无一动词而萧瑟自现，被誉为「秋思之祖」，是元人小令的巅峰。",
    b: "马致远长期漂泊不得志，秋日旅途中触景生情而作。"
  },
  "山坡羊|张养浩": {
    y: "峰峦如聚，波涛如怒，山河表里潼关路。遥望西都，意踌躇。伤心秦汉宫殿都化作了尘土。兴，百姓苦；亡，百姓苦。",
    s: "结尾「兴，百姓苦；亡，百姓苦」八个字一针见血：无论王朝兴亡，苦难都落在百姓头上，立意远超一般怀古之作。",
    b: "天历二年陕西大旱，张养浩赴任赈灾，途经潼关怀古伤今而作。"
  },
  "石灰吟|于谦": {
    y: "石灰石经过千锤万凿才从深山开采出来，烈火焚烧视若等闲。粉身碎骨也毫不惧怕，只为把清白留在人间。",
    s: "托物言志的典范。石灰的锤炼过程正是人格的修炼过程，「要留清白在人间」是于谦一生的写照。",
    b: "相传为于谦少年时观石灰烧制有感而作，后来他果然以清白忠烈践行了此诗。"
  },
  "竹石|郑燮": {
    y: "竹子紧紧咬住青山毫不放松，根深深扎进岩石缝中。经历千磨万击依然坚劲，任凭你东西南北刮什么风。",
    s: "「千磨万击还坚劲，任尔东西南北风」以岩竹自喻，写尽刚正不阿、不屈不挠的骨气，是题画诗中的名篇。",
    b: "郑板桥为自画竹石图所题的诗，画中竹、诗中志、人中品三者合一。"
  },
  "己亥杂诗|龚自珍": {
    y: "要使中国大地重新焕发生气，必须依靠疾风迅雷般的变革。社会沉闷到极点，终究令人悲哀。我劝上天重新振作精神，不拘一格地降下各种人才。",
    s: "「我劝天公重抖擞，不拘一格降人才」喊出对变革与人才的渴望，是近代思想启蒙的先声。",
    b: "道光十九年（己亥年），龚自珍辞官南归，途中作大型组诗三百一十五首，此为其一百二十五，过镇江时见祭神场面有感。"
  },
  "沁园春|毛泽东": {
    y: "北国风光，千里冰封，万里雪飘。望长城内外只剩莽莽一片，大河上下顿时失去滔滔。山如银蛇飞舞，高原如白象奔驰，都想与老天比高。待到晴天，看红妆素裹，分外妖娆。江山如此多娇，引无数英雄竞折腰。可惜秦皇汉武文采稍逊，唐宗宋祖风骚略差，一代天骄成吉思汗，只识弯弓射大雕。都过去了，数风流人物，还看今朝。",
    s: "上阕写北国雪景，气象万千；下阕评点千古帝王，落到「数风流人物，还看今朝」的万丈豪情，是现代词坛的巅峰之作。",
    b: "1936年2月，毛泽东率红军东征途中，在陕北清涧见大雪而作；1945年重庆谈判期间公开发表，轰动一时。"
  },
  "七律·长征|毛泽东": {
    y: "红军不怕远征的艰难，把万水千山只看作平常。五岭逶迤如细小的波浪，乌蒙磅礴像滚动的泥丸。金沙江拍打着云崖变暖，大渡河的铁索桥令人胆寒。更喜岷山千里雪，三军过后个个笑开颜。",
    s: "「红军不怕远征难，万水千山只等闲」开篇即定下豪迈基调，五岭作细浪、乌蒙为泥丸的夸张，写尽革命英雄主义气概。",
    b: "1935年10月，中央红军长征胜利在望，毛泽东回顾征程而作。"
  },
  "滕王阁序|王勃": {
    y: "这里是汉代的豫章旧郡、今日的洪都新府。天上对应翼、轸二星，地上连接衡山与庐山……雨过天晴，落霞与孤鹜一同飞翔，秋水与长天融为一色。傍晚渔船上传来歌声，响彻鄱阳湖畔；雁阵惊觉寒意，鸣声消失在衡阳水边。",
    s: "「落霞与孤鹜齐飞，秋水共长天一色」是骈文史上最著名的句子。全文四六对仗、典故琳琅而不滞涩，由盛宴之乐转入身世之悲，再振起于青云之志，跌宕起伏。",
    b: "上元二年，王勃南下探父途经南昌，适逢都督阎公重修滕王阁大宴宾客，即席挥毫写成此序，时年二十六岁（一说十四岁）。"
  },
  "岳阳楼记|范仲淹": {
    y: "庆历四年春，滕子京被贬到岳州做知州。到第二年，政事顺利、百姓和乐，各种荒废的事业都兴办起来，于是重修岳阳楼，嘱托我写篇文章记述此事……古时仁人的心境不同于常人：不因外物而喜，不因己身而悲；在朝廷做官就忧虑百姓，退处江湖就忧虑君主。那么何时才快乐呢？他们一定说：「在天下人忧之前先忧，在天下人乐之后才乐。」",
    s: "「先天下之忧而忧，后天下之乐而乐」是全文灵魂。文章借景写情、以情衬理，把迁客骚人的悲喜与古仁人的境界两相对照，立意高远，成为士人精神的千年标杆。",
    b: "庆历六年，范仲淹因「庆历新政」失败被贬邓州，应同样被贬的好友滕子京之请，看图作文写就此记。"
  },
  "醉翁亭记|欧阳修": {
    y: "环绕滁州的都是山。西南方向的山峰，树林和山谷尤其秀美……醉翁的意趣不在酒上，而在山水之间。山水的乐趣，领会在心里，寄托在酒上……人们只知道跟从太守游玩的快乐，却不知道太守以他们的快乐为快乐啊。",
    s: "全文连用二十一个「也」字，一唱三叹，摇曳生姿。「醉翁之意不在酒，在乎山水之间也」早已化入日常语言，山水之乐、宴饮之乐、与民同乐层层递进。",
    b: "庆历五年，欧阳修因支持庆历新政被贬滁州知州，寄情山水、与民同乐，自号「醉翁」而作。"
  },
  "出师表|诸葛亮": {
    y: "先帝开创大业未及一半就中途去世，如今天下三分，益州疲敝，这实在是危急存亡的时刻……我本是一介平民，在南阳亲自耕种，只求在乱世中保全性命，不求在诸侯间显达。先帝不嫌我身份低微，三次到草庐中看望我，向我询问天下大事，我因此感奋，答应为先帝奔走效劳……如今南方已经平定，军备已经充足，应当激励全军，北上平定中原。这是我报答先帝、效忠陛下的职责本分。",
    s: "全文不用典故、不事雕琢，一片赤诚从肺腑流出。「鞠躬尽瘁，死而后已」的精神写照，陆游赞曰：「出师一表真名世，千载谁堪伯仲间。」",
    b: "建兴五年，诸葛亮决定北上伐魏，临行前上表后主刘禅，劝勉他亲贤远佞，并剖白自己的心迹。"
  },
  "桃花源记|陶渊明": {
    y: "晋朝太元年间，武陵有个以捕鱼为生的人。一天他沿溪而行，忘记了路程远近，忽然遇到一片桃花林……村里人自己说，先辈为躲避秦时战乱，带领妻子儿女和乡邻来到这与世隔绝的地方，从此不再出去，就和外界隔绝了。他们问现在是什么朝代，竟然不知道有过汉朝，更不用说魏和晋了。",
    s: "以渔人行踪为线索，把虚构的桃源写得宛然在目。「桃花源」从此成为中国人心中理想社会的代名词，影响及于诗歌、绘画乃至东亚文化圈。",
    b: "约作于南朝宋永初二年，时值晋宋易代、战乱频仍，陶渊明借虚构的乐土寄托对和平安定生活的向往。"
  },
  "陋室铭|刘禹锡": {
    y: "山不在于高，有仙人就出名；水不在于深，有蛟龙就显灵。这是间简陋的屋子，只因我的品德美好就不觉简陋。苔痕碧绿长到阶上，草色青葱映入帘中。谈笑往来的都是博学之士，没有无学问的人。可以弹素朴的琴，读佛经。没有奏乐声扰乱耳朵，没有公文劳累身心。好比南阳诸葛亮的草庐、西蜀扬子云的玄亭。孔子说：有什么简陋的呢？",
    s: "全文八十一字，以「惟吾德馨」为眼目，山水起兴、人事作陪、圣言作结，把安贫乐道的君子之风写得铿锵雅致，是铭文体的绝唱。",
    b: "刘禹锡因参加永贞革新被贬和州，知县故意刁难、三迁其居，他愤然写下此文置于门上。"
  },
  "爱莲说|周敦颐": {
    y: "水上陆上各种草木的花，值得喜爱的很多。晋代陶渊明只爱菊花，自唐朝以来世人大多爱牡丹。我唯独爱莲花从淤泥中长出却不被沾染，经清水洗涤却不显得妖媚，茎内空外直，不蔓不枝，香气越远越清，洁净地挺立，可以远远观赏却不能轻慢地玩弄。",
    s: "「出淤泥而不染，濯清涟而不妖」是全文之眼。以菊衬隐逸、以牡丹衬富贵、以莲喻君子，托物言志，成为君子人格的千古定义。",
    b: "嘉祐八年，周敦颐任虔州通判时所作，是宋明理学开山鼻祖借花明志的名篇。"
  },
  "记承天寺夜游|苏轼": {
    y: "元丰六年十月十二日夜里，我解衣欲睡，月光照进门来，于是高兴地起身出门。想到没有可以同乐的人，就到承天寺找张怀民。怀民也没睡，我们便一起在庭院中散步。庭院里像积满了清水一样澄澈，水中藻荇交错，原来是竹子和柏树的影子。哪个夜晚没有月亮？哪里没有竹子和柏树？只是缺少像我们两个这样的闲人罢了。",
    s: "八十四字，叙事、写景、抒情浑然一体。「但少闲人如吾两人者耳」——贬谪中的自嘲里透着旷达，是苏轼小品文的极致。",
    b: "元丰六年，苏轼因「乌台诗案」被贬黄州已四年，与同样谪居的张怀民夜游赏月而作。"
  },
  "氓|佚名": {
    y: "憨厚农家小伙子，怀抱布匹来换丝。其实不是真换丝，找个机会谈婚事。送郎送过淇水西，到了顿丘情依依。不是我愿误佳期，你无媒人失礼仪。望郎休要发脾气，秋天到了来迎娶。\n爬上那垛破土墙，遥向复关凝神望。复关远在云雾中，不见情郎泪千行。情郎即从复关来，又说又笑喜洋洋。你去卜卦求神仙，没有凶兆心欢畅。赶着你的车子来，为我搬运好嫁妆。\n桑树叶子未落时，缀满枝头绿萋萋。嘘嘘那些斑鸠儿，别把桑葚吃嘴里。哎呀年轻姑娘们，别对男人情依依。男人若是恋上你，要丢便丢太容易。女人若是恋男子，要想解脱难挣离。\n桑树叶子落下了，枯黄憔悴任飘摇。自从嫁到你家来，三年穷苦受煎熬。淇水茫茫送我归，水溅车帷湿又潮。我做妻子没差错，是你男人太奸刁。反覆无常没准则，变心缺德耍花招。\n婚后三年守妇道，繁重家务不辞劳。起早睡晚不嫌苦，忙里忙外非一朝。谁知家业已成后，渐渐对我施凶暴。兄弟不知我处境，个个见我哈哈笑。静下心来细细想，独自伤神泪暗抛。\n当年发誓偕白头，如今未老心先忧。淇水滔滔终有岸，沼泽虽宽有尽头。回想少时多欢乐，谈笑之间露温柔。海誓山盟犹在耳，哪料反目竟成仇。莫再回想背盟事，既已终结便罢休！",
    s: "《氓》是《诗经》中最著名的叙事诗之一，以一位弃妇的口吻，讲述了从恋爱、结婚到被遗弃的完整过程。诗中女主人公从天真痴情到清醒决绝，形象鲜明生动。“桑之未落，其叶沃若”与“桑之落矣，其黄而陨”的比喻，将女子青春与衰老的对比写得入木三分。全诗是中国文学史上最早的女性觉醒之作。"
  },
  "离骚|屈原": {
    y: "我是古帝高阳氏的子孙，我已去世的父亲字伯庸。\n岁星在寅那年的孟春月，正当庚寅日那天我降生。\n父亲仔细揣测我的生辰，于是赐给我相应的美名。\n父亲把我的名取为正则，同时把我的字叫作灵均。\n天赋给我很多良好素质，我不断加强自己的修养。\n我把江离芷草披在肩上，把秋兰结成索佩挂身旁。\n光阴似箭我好像跟不上，岁月不等待人令我心慌。\n早晨我在大坡采集木兰，傍晚在小洲中摘取宿莽。\n时光迅速逝去不能久留，四季更相代谢变化有常。\n我想到草木已由盛到衰，恐怕自己身体逐渐衰老。\n何不利用盛时扬弃秽政，为何还不改变这些法度？\n乘上千里马纵横驰骋吧，来呀我在前面引导开路！",
    s: "《离骚》是屈原的代表作，也是中国古代最长的抒情诗，共373句。这里节选的是开篇部分，诗人自叙身世、生辰和名字，表达了自己的高洁品质和对国家的忧虑。“路漫漫其修远兮，吾将上下而求索”的精神贯穿全诗，奠定了中国浪漫主义文学的传统，对后世影响深远。"
  },
  "迢迢牵牛星|佚名": {
    y: "在银河东南牵牛星遥遥可见，在银河之西织女星明亮皎洁。\n织女正摆动柔长洁白的双手，织布机札札地响个不停。\n一整天也没织成一段布，哭泣的眼泪如同下雨般零落。\n这银河看起来又清又浅，两岸相隔又有多远呢？\n虽然只相隔了一条银河，但也只能含情脉脉相视无言。",
    s: "《迢迢牵牛星》是《古诗十九首》中的名篇，借牛郎织女的神话传说，抒发了男女之间的相思离别之苦。全诗通篇使用叠字，“迢迢”“皎皎”“纤纤”“札札”“盈盈”“脉脉”，音韵和谐，意境优美。最后两句“盈盈一水间，脉脉不得语”，将咫尺天涯的哀怨写得含蓄深沉，是五言诗的杰作。"
  },
  "短歌行|曹操": {
    y: "一边喝酒一边高歌，人生短促日月如梭。\n好比晨露转瞬即逝，失去的时日实在太多！\n席上歌声激昂慷慨，忧郁长久填满心窝。\n靠什么来排解忧闷？唯有狂饮方可解脱。\n那穿着青领的学子哟，你们令我朝夕思慕。\n只是因为您的缘故，让我沉痛吟诵至今。\n阳光下鹿群呦呦欢鸣，悠然自得啃食在绿坡。\n一旦四方贤才光临舍下，我将奏瑟吹笙宴请嘉宾。\n当空悬挂的皓月哟，什么时候才可以拾到。\n我久蓄于怀的忧愤哟，突然喷涌而出汇成长河。\n远方宾客踏着田间小路，一个个屈驾前来探望我。\n彼此久别重逢谈心宴饮，争着将往日的情谊诉说。\n月光明亮星光稀疏，一群寻巢乌鹊向南飞去。\n绕树飞了三周却没敛翅，哪里才有它们的栖身之所？\n高山不辞土石才见巍峨，大海不弃涓流才见壮阔。\n我愿如周公一般礼贤下士，愿天下的英杰真心归顺于我。",
    s: "《短歌行》是曹操的代表作，全诗抒发了诗人求贤若渴的心情和统一天下的雄心壮志。开头“对酒当歌，人生几何”感叹时光易逝，继而引用《诗经》成句表达对贤才的渴望，最后以“周公吐哺，天下归心”作结，气魄宏大。全诗情感跌宕，用典自然，是建安风骨的典范之作。"
  },
  "归园田居·其一|陶渊明": {
    y: "年轻时就没有适应世俗的性格，生来就喜爱大自然的风物。\n错误地陷落到仕途罗网，转眼间远离田园已十余年。\n笼子里的鸟儿怀念以前生活的森林，池子里的鱼儿思念原来嬉戏的深潭。\n我愿到南边的原野里去开荒，依着愚拙的心性回家耕种田园。\n绕房宅方圆有十余亩地，还有那茅屋草舍八九间。\n榆树柳树成荫遮盖了后屋檐，桃树李树整齐的栽种在屋前。\n远处的邻村屋舍依稀可见，村落上方飘荡着袅袅炊烟。\n深深的街巷中传来了几声狗吠，桑树顶有雄鸡不停啼唤。\n庭院内没有世俗琐杂的事情烦扰，静室里有的是安适悠闲。\n久困于樊笼里毫无自由，我今日总算又归返林山。",
    s: "《归园田居》是陶渊明辞官归隐后的组诗，这是第一首。诗中描写了田园生活的宁静美好，表达了对官场的厌恶和对自由的向往。“羁鸟恋旧林，池鱼思故渊”以鸟鱼自比，“久在樊笼里，复得返自然”点明主旨。全诗语言朴素自然，意境悠远，开创了中国田园诗派。"
  },
  "杜少府之任蜀州|王勃": {
    y: "三秦之地护卫着巍巍长安，透过那风云烟雾遥望着蜀川。\n和你离别心中怀着无限情意，因为我们同是在宦海中浮沉。\n四海之内有知心朋友，即使远在天边也如近在比邻。\n绝不要在岔路口上分手之时，像多情的少年男女那样悲伤得泪湿衣巾。",
    s: "这是王勃送别友人的名作，一反传统送别诗的伤感低沉，以“海内存知己，天涯若比邻”的豁达胸襟，表达了真挚深厚的友情。全诗格调高昂，气势雄健，是初唐送别诗的代表作，也是千古传诵的名篇。"
  },
  "春江花月夜|张若虚": {
    y: "春天的江潮水势浩荡，与大海连成一片，一轮明月从海面升起，仿佛跟着潮水一同涌现。\n月光照耀着春江，波光粼粼绵延千万里，所有地方的春江，都沐浴在明亮的月色里。\n江水曲折地绕过开满花草的原野，月光洒在花林上，像撒了一层细碎的雪珠。\n月色如霜在空中流淌，却感觉不到霜飞，江边的白沙和月色融为一体，看不分明。\n江水与天空连成一色，没有一丝尘埃，只有一轮皎洁的孤月高悬空中。\n江边是什么人，最先看见了月亮？江上的月亮，又是哪一年最初照耀着人间？\n人生一代又一代无穷无尽，而江上的月亮，年年看上去都没有变化。\n不知道江上的月亮在等待着什么人，只见长江水不断地向前奔流。\n一片白云悠然飘远，青枫浦上的游子，满是说不尽的忧愁。\n今晚谁家的游子坐着小船漂泊？何处的思妇在明月照耀的楼上思念远方的人？\n可怜那楼上徘徊的月光，应该正照在离人的梳妆台上。\n月光照进珠帘，卷也卷不走；落在捣衣砧上，拂去了又还来。\n此刻一同望着月亮，却听不到彼此的声音，我愿追随着月光，流照到你的身边。\n鸿雁飞得再远，也飞不出月光；鱼龙跃出水面，只激起阵阵波纹。\n昨夜梦见花落闲潭，可惜春天已经过半，人还没能回家。\n江水带着春光流走，快要耗尽；江潭上的落月，又向西边倾斜。\n斜月沉沉藏在海雾里，碣石与潇湘相隔万里，路途遥远。\n不知道有几人能乘着月光回家，落月的余晖摇曳着，洒满了江边的树林。",
    s: "《春江花月夜》被闻一多誉为“诗中的诗，顶峰上的顶峰”，素有“孤篇盖全唐”的美誉。全诗以春、江、花、月、夜为核心意象，将写景、抒情、哲理完美融合，既有宇宙永恒的苍茫追问，又有人生相思的细腻柔情，意境空灵悠远，是唐诗美学的极致代表。"
  },
  "辋川集·鹿柴|王维": {
    y: "幽静的山谷里看不见人，只听到人说话的声音。\n落日的影晕映入了深林，又照在幽暗处的青苔上。",
    s: "《鹿柴》是王维《辋川集》中的名篇，全诗仅二十字，却营造出一种空寂幽深的意境。“空山不见人，但闻人语响”以有声衬无声，“返景入深林，复照青苔上”以光亮写幽暗，充满禅意，体现了王维“诗佛”的艺术特色。"
  },
  "渭城曲|王维": {
    y: "渭城早晨一场春雨沾湿了轻尘，客舍周围柳树的枝叶翠嫩一新。\n老朋友请你再干一杯美酒，向西出了阳关就难以遇到故旧亲人。",
    s: "《送元二使安西》又名《渭城曲》，是王维最著名的送别诗，后被谱成《阳关三叠》，广为传唱。“劝君更尽一杯酒，西出阳关无故人”两句，将依依惜别之情浓缩在一杯酒中，含蓄深沉，余味无穷，是唐诗中最动人的送别名句。"
  },
  "望洞庭湖赠张丞相|孟浩然": {
    y: "秋水盛涨几乎与岸平，水天含混迷茫与天空浑然一体。\n云梦大泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。\n想要渡水却没有船只，闲居不仕，有愧于圣明天子。\n坐看垂钓之人多么悠闲自在，可惜只能空怀一片羡鱼之情。",
    s: "这是孟浩然写给张九龄的干谒诗，希望得到引荐出仕。前四句写洞庭湖的壮阔景象，“气蒸云梦泽，波撼岳阳城”气势磅礴，是写洞庭湖的千古名句。后四句以“欲济无舟楫”“羡鱼情”委婉表达出仕的愿望，不卑不亢，含蓄得体。"
  },
  "凉州词二首”·一|王之涣": {
    y: "黄河好像从白云间奔流而来，玉门关孤独地耸峙在高山中。\n何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！",
    s: "《凉州词》是王之涣的代表作，也是唐代边塞诗的绝唱。前两句写塞外壮阔苍凉的景象，“黄河远上白云间”气势宏大；后两句借羌笛吹奏《折杨柳》曲，委婉表达戍边将士的思乡之情，“春风不度玉门关”一语双关，既写自然气候，又暗喻朝廷的恩泽不及边塞，含蓄深沉。"
  },
  "出塞二首·一|王昌龄": {
    y: "依旧是秦汉时期的明月和边关，守边御敌鏖战万里征夫未回还。\n倘若龙城的飞将李广如今还在，一定不会让敌人的铁蹄踏过阴山。",
    s: "《出塞》被明人李攀龙推为唐人七绝压卷之作。“秦时明月汉时关”以互文手法，将秦汉以来的漫长历史浓缩在一句之中，营造出苍茫悠远的时空感。后两句借怀念李广，表达对良将的渴望和对边塞安宁的期盼，气势雄浑，寓意深远。"
  },
  "芙蓉楼送辛渐二首·一|王昌龄": {
    y: "冷雨连夜洒遍吴地江天，清晨送走你后，独自面对着楚山离愁无限！\n到了洛阳，如果洛阳亲友问起我来，就请转告他们，我的心依然像玉壶里的冰那样晶莹纯洁！",
    s: "这是王昌龄送别友人的名作，“一片冰心在玉壶”是千古名句，以冰在玉壶之中比喻自己品格的高洁清白，既是对亲友的告慰，也是对自身操守的坚守。全诗意境凄清而不失高洁，情感真挚而含蓄。"
  },
  "从军行七首·四|王昌龄": {
    y: "青海湖上乌云密布，遮得连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。\n守边将士身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。",
    s: "《从军行》是王昌龄边塞诗的代表作，“黄沙百战穿金甲，不破楼兰终不还”两句，以铿锵的音调、坚定的语气，写出了戍边将士誓死报国的英雄气概，是唐诗中最具豪情壮志的名句之一。"
  },
  "燕歌行|高适": {
    y: "唐朝东北边境战事又起，将军离家前去征讨贼寇。\n战士们本来在战场上就所向无敌，皇帝又特别给予他们丰厚的赏赐。\n军队擂击金鼓，浩浩荡荡开出山海关外，旌旗连锦不断，飘扬在碣石山间。\n校尉紧急传羽书，飞奔浩瀚之沙海，匈奴单于举猎火光照已到我狼山。\n山河荒芜多萧条，满目凄凉到边土，胡人骑兵仗威力兵器声里夹风雨。\n战士拼斗军阵前半数死去半生还，美人却在营帐中还是歌来还是舞。\n时值深秋大沙漠塞外百草尽凋枯，孤城一片映落日战卒越斗越稀少。\n身受皇家深恩义常思报国轻寇敌，边塞之地尽力量尚未破除匈奴围。\n身穿铁甲守边远疆场辛勤已长久，珠泪纷落挂双目丈夫远去独啼哭。\n少妇孤单住城南泪下凄伤欲断肠，远征军人驻蓟北依空仰望频回头。\n边境飘渺多遥远怎可轻易来奔赴，绝远之地尽苍茫更是人烟何所有。\n杀气春夏秋三季腾起阵前似乌云，一夜寒风声声里如泣更声惊耳鼓。\n互看白刃乱飞舞夹杂着鲜血纷飞，从来死节为报国难道还求著功勋？\n你没看见拼杀在沙场战斗多惨苦，现在还在思念有勇有谋的李将军。",
    s: "《燕歌行》是高适的代表作，也是唐代边塞诗的杰作。全诗以一次战役为线索，揭露了军中苦乐不均的现实——“战士军前半死生，美人帐下犹歌舞”，对将领的骄奢轻敌进行了尖锐批判，同时对士兵的英勇牺牲表示深切同情。全诗气势雄浑，笔力苍劲，思想深刻。"
  },
  "别董大二首·一|高适": {
    y: "千里黄云遮天蔽日，天气阴沉，北风送走雁群又吹来纷扬大雪。\n不要担心前路茫茫没有知己，天下还有谁不认识你呢？",
    s: "《别董大》是高适送别友人董庭兰的名作，一反送别诗的伤感低沉，以“莫愁前路无知己，天下谁人不识君”的豪迈之语激励友人，充满信心和力量。全诗意境开阔，格调高昂，是送别诗中的佳作。"
  },
  "逢入京使|岑参": {
    y: "向东遥望长安家园路途遥远，思乡之泪沾湿双袖难擦干。\n在马上匆匆相逢没有纸和笔，只有托你捎个口信，给家人报平安。",
    s: "《逢入京使》是岑参西行途中所作，写在路上偶遇入京使者，托他捎口信回家报平安的情景。“马上相逢无纸笔，凭君传语报平安”两句，语言朴素自然，却将游子的思乡之情和对家人的牵挂写得真挚动人，是唐诗中最感人的思乡名篇之一。"
  },
  "将进酒|李白": {
    y: "你难道看不见，黄河之水从天上奔腾而来，波涛翻滚直奔东海，再也不会回流。\n你难道看不见，年迈的父母对着明镜悲叹白发，早晨还是青丝般的黑发，傍晚就变得如雪般洁白。\n人生得意之时就应当纵情欢乐，不要让金杯空对着皎洁的明月。\n上天造就了我这样的人才，就一定有我的用处，黄金千两一挥而尽，也还会重新得来。\n烹羊宰牛姑且尽情享乐，今日相逢，应当一口气喝上三百杯。\n岑夫子、丹丘生，快喝酒吧，不要停下酒杯。\n我为你们唱一首歌，请你们为我侧耳倾听。\n钟鸣鼎食的荣华富贵都不值得珍贵，只希望长久沉醉，再也不愿清醒。\n自古以来的圣贤都寂然无名，只有善饮的人才能留下美名。\n当年陈王曹植在平乐观大摆酒宴，一斗酒价值万钱，却恣意纵情欢饮。\n主人怎么说钱不够了呢？只管去买酒来和我对饮。\n名贵的五花马、价值千金的狐裘，快叫孩子拿去换美酒，让我们一同消解这万古的长愁。",
    s: "《将进酒》是李白豪放诗的巅峰之作，以黄河奔涌起兴，以时光易逝落笔，将怀才不遇的愤懑与人生旷达的豪情融为一体。全诗气势磅礴、情感跌宕，“天生我材必有用”更是成为千古励志名句，是中国人最熟悉的唐诗代表作之一。"
  },
  "相和歌辞·蜀道难|李白": {
    y: "唉呀呀！多么高峻伟岸！蜀道难以攀越，简直难于上青天。\n传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。\n从那时至今约有四万八千年了吧，秦蜀被秦岭所阻从不沟通往返。\n西边太白山高峻无路只有飞鸟可通行，飞鸟可以直通峨眉山巅。\n山崩地裂，埋葬了五位开山英雄壮士，这样高险的山路和栈道才相互勾连。\n蜀中上有挡住太阳神六龙车的山巅，下有激浪排空曲折的大川。\n善于高飞的黄鹤尚且无法飞过，即使猢狲要想翻过也愁于攀援。\n青泥岭的泥路曲曲弯弯，百步九折萦绕着山峦。\n屏住呼吸仰头就可触摸参星和井星，紧张得透不过气来，用手抚胸惊恐不已徒长吁短叹。\n好朋友呵请问你西游何时回还？可怕的岩山栈道实在难以登攀！\n只见那悲鸟在古树上哀鸣啼叫，雄雌相随飞翔在树丛之间。\n月夜又听到杜鹃凄凉悲啼，在空山中传响令人愁思绵绵。\n蜀道难以攀越呵简直难于上青天，使人听到这些怎么不脸色突变？\n山峰座座相连离天还不到一尺，枯松老枝倒挂倚贴在绝壁之间。\n漩涡飞转瀑布飞泻争相喧闹着，飞流撞击着巨石在山谷中滚动像万壑鸣雷一般。\n这样危险的地方，唉呀呀你这个远方而来的客人，为什么非要来这里不可呀？\n剑阁所在崇峻巍峨高入云端，只要一人把守千军万马难攻占。\n驻守的官员倘若不是可信赖的人，难免要变为豺狼，据险作乱。\n每日每夜都要躲避猛虎和长蛇，它们磨牙吮血，杀人如麻。\n锦官城虽然说是个快乐的所在，如此险恶还不如早早地把家还。\n蜀道难以攀越呵简直难于上青天，侧身西望令人不免感慨与长叹！",
    s: "《蜀道难》是李白浪漫主义诗歌的代表作，以雄奇奔放的笔调描绘了蜀道的艰险壮丽。全诗以“蜀道之难，难于上青天”为主旋律，三次反复出现，一唱三叹，气势磅礴。诗人运用夸张、想象、神话传说等手法，将蜀道的奇险写得惊心动魄，是唐诗中最具想象力的杰作。"
  },
  "望庐山瀑布水二首·二|李白": {
    y: "香炉峰在阳光的照射下生起紫色烟霞，从远处看去瀑布好似白色绢绸悬挂山前。\n高崖上飞腾直落的瀑布好像有几千尺，让人怀疑是银河从天上泻落到人间。",
    s: "《望庐山瀑布》是李白山水诗的代表作，“飞流直下三千尺，疑是银河落九天”以极度夸张的手法和奇特的想象，将庐山瀑布的雄伟壮丽写得淋漓尽致，是中国诗歌史上最著名的咏瀑名句。全诗气势磅礴，想象奇绝，充分体现了李白浪漫主义的诗风。"
  },
  "赠汪伦|李白": {
    y: "李白乘舟将要远行离去，忽听岸上传来踏歌之声。\n即使桃花潭水深至千尺，也比不上汪伦送我之情。",
    s: "《赠汪伦》是李白写给友人汪伦的赠别诗，“桃花潭水深千尺，不及汪伦送我情”以潭水之深比喻友情之深，形象生动，情感真挚。全诗语言朴素自然，充满生活气息，是唐诗中最脍炙人口的赠别名篇。"
  },
  "行路难三首·一|李白": {
    y: "金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。\n心中郁闷，我放下杯筷不愿进餐；拔出宝剑环顾四周，心里一片茫然。\n想渡黄河，冰雪却冻封了河川；想登太行山，莽莽风雪早已封山。\n像姜尚垂钓溪，闲待东山再起；又像伊尹做梦，他乘船经过日边。\n人生道路多么艰难，多么艰难；歧路纷杂，如今又身在何处？\n相信乘风破浪的时机总会到来，到时定要扬起征帆，横渡沧海！",
    s: "《行路难》是李白在仕途受挫时所作，全诗情感跌宕起伏，从“停杯投箸不能食”的苦闷茫然，到“长风破浪会有时，直挂云帆济沧海”的豪迈自信，展现了诗人虽身处逆境却依然乐观进取的精神。结尾两句是千古传诵的励志名句。"
  },
  "梦游天姥吟留别|李白": {
    y: "听海外来客们谈起瀛洲，在烟波浩渺的遥远地方，实在难以找到。\n越中来人说起天姥山，在云霞的明灭掩映之间有时候能看见。\n天姥山高耸入云，连着天际，横向天外；山势高峻超过五岳，遮掩过赤城山。\n天姥山极为高峻，就连四万八千丈高的天台山，面对着它好像要向东南倾斜拜倒一样。\n我想根据越人说的话梦游到吴越，一天夜晚飞渡过明月映照下的镜湖。\n镜湖上的月光照着我的身影，一直送我到剡溪。\n谢灵运住的地方如今还在，清澈的湖水荡漾，猿猴清啼。\n我脚上穿着谢公当年特制的木鞋，攀登直上云霄的山路。\n上到半山腰就看见了从海上升起的太阳，空中传来天鸡报晓的啼鸣之声。\n无数山岩重叠，道路盘旋弯曲，方向不定，迷恋着花，依倚着石头，不觉天色已晚。\n熊在怒吼，龙在长鸣，岩中的泉水在震响，使深林战栗，使层巅震惊。\n云层黑沉沉的，像是要下雨，水波动荡生起了薄薄的烟雾。\n电光闪闪，雷声轰鸣，山峰好像要被崩塌似的。\n仙府的石门，訇的一声从中间打开。\n洞中蔚蓝的天空广阔无际，看不到尽头，日月照耀着金银做的宫阙。\n用彩虹做衣裳，将风作为马来乘，云中的神仙们纷纷下来。\n老虎弹奏着琴瑟，鸾鸟拉着车。仙人们排成列，多如密麻。\n忽然魂魄惊动，我猛然惊醒，不禁长声叹息。\n醒来时身边只有枕席，刚才梦中所见的烟雾云霞全都消失了。\n人世间的欢乐也是像梦中的幻境这样，自古以来万事都像东流的水一样一去不复返。\n告别诸位朋友远去东鲁啊，什么时候才能回来？暂且把白鹿放牧在青崖间，等到要远行时就骑上它访名山。\n岂能卑躬屈膝去侍奉权贵，让自己不能有舒心畅意的笑颜！",
    s: "《梦游天姥吟留别》是李白浪漫主义诗歌的代表作，通过梦游天姥山的奇幻经历，描绘了一个瑰丽多彩的神仙世界。全诗想象奇绝，气势磅礴，结尾“安能摧眉折腰事权贵，使我不得开心颜”点明主旨，表达了诗人蔑视权贵、追求自由的崇高品格。"
  },
  "独坐敬亭山|李白": {
    y: "山中群鸟一只只高飞远去，天空中的最后一片白云也悠然飘走。\n敬亭山和我对视着，谁都看不够，看不厌，看来理解我的只有这敬亭山了。",
    s: "《独坐敬亭山》是李白晚年所作，以拟人手法写人与山的相知相惜。“相看两不厌，只有敬亭山”将山人格化，表达了诗人在孤独中寻求慰藉的心境，含蓄深沉，余味无穷。全诗意境清幽，是李白五绝的代表作。"
  },
  "秋浦歌十七首·十五|李白": {
    y: "白发长达三千丈，是因为愁才长得这样长。\n不知在明镜之中，是何处的秋霜落在了我的头上？",
    s: "《秋浦歌》以“白发三千丈”的极度夸张开篇，将愁思之深之长写得惊心动魄。“缘愁似个长”点明白发因愁而生，后两句以问语作结，含蓄深沉。全诗仅二十字，却将怀才不遇的悲愤写得淋漓尽致，是李白浪漫主义夸张手法的典范。"
  },
  "客中行|李白": {
    y: "兰陵美酒甘醇醉人散发着郁金的香气，盛满玉碗色泽如琥珀般清莹秀彻。\n只要主人同我一道尽兴畅饮，一醉方休，我哪管这里是故乡还是异乡呢！",
    s: "《客中行》一反游子思乡的传统主题，以豁达豪迈的笔调写客中之乐。“但使主人能醉客，不知何处是他乡”表达了诗人随遇而安、四海为家的豪迈胸襟，全诗色彩明丽，情调欢快，是李白七绝中的佳作。"
  },
  "登高|杜甫": {
    y: "风势迅急，天空高远，猿猴的啼声十分哀切；水清沙白的洲渚上，鸟儿在空中盘旋飞翔。\n无边无际的树叶萧萧飘落，奔流不息的长江滚滚而来。\n漂泊万里，常年客居他乡，更添悲秋情绪；一生多病，今日独自登上高台。\n历尽艰难困苦，白发长满了双鬓；穷困潦倒，偏偏又刚刚停下了浇愁的酒杯。",
    s: "《登高》被后世称为“古今七言律诗第一”，全诗四联皆对，格律严整却浑然天成。前四句写景，雄浑苍凉；后四句抒情，沉郁顿挫，将身世飘零、老病孤愁与家国动荡融为一体，是杜甫“沉郁顿挫”诗风的集中体现。"
  },
  "登岳阳楼|杜甫": {
    y: "以前就听说洞庭湖波澜壮阔，今日终于如愿登上岳阳楼。\n浩瀚的湖水把吴楚两地分隔开来，整个天地仿似在湖中日夜浮动。\n亲朋好友们音信全无，年老多病只有一只船孤零零的陪伴自己。\n关山以北战争烽火仍未止息，凭栏遥望胸怀家国泪水横流。",
    s: "《登岳阳楼》是杜甫晚年漂泊湖南时所作，“吴楚东南坼，乾坤日夜浮”写洞庭湖的壮阔，气象万千，与孟浩然“气蒸云梦泽，波撼岳阳城”并为咏洞庭绝唱。后四句由景入情，将个人身世之悲与国家战乱之忧融为一体，沉郁顿挫，感人至深。"
  },
  "江畔独步寻花七绝句·六|杜甫": {
    y: "黄四娘家周围的小路旁开满了鲜花，千朵万朵鲜花把枝条都压得低垂了。\n嬉闹的彩蝶恋恋不舍地盘旋飞舞，自由自在的小黄莺在花间不断欢唱。",
    s: "《江畔独步寻花》是杜甫在成都草堂时的组诗，这一首描写了春日繁花似锦、蝶舞莺啼的美好景象。全诗语言明快，色彩明丽，充满生活气息，展现了杜甫诗歌中轻松愉悦的一面，是描写春景的名篇。"
  },
  "绝句四首·三|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，全诗四句四景，“两个黄鹂鸣翠柳，一行白鹭上青天”色彩明丽，“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗对仗工整，是杜甫七绝的代表作。"
  },
  "石壕吏|杜甫": {
    y: "日暮时投宿石壕村，夜里有差役来强征兵。\n老翁越墙逃走，老妇出门应付。\n差役喊叫得是那样凶狠，老妇人啼哭得是那样悲伤。\n我听到老妇上前说：我的三个儿子去参加邺城之战。\n其中一个儿子捎信回来，说另外两个儿子刚刚战死。\n活着的人姑且活一天算一天，死去的人就永远不会复生了！\n家里再也没有别的男人了，只有个正在吃奶的小孙子。\n因为有小孙子在，他母亲还没有离去，但进进出出连一件完好的衣裳都没有。\n老妇虽然年老力衰，但请允许我跟从你连夜赶回营去。\n赶快到河阳去应征，还能够为部队准备早餐。\n夜深了，说话的声音逐渐消失，隐隐约约听到低微断续的哭泣声。\n天亮后我继续赶路，只能与返回家中的那个老翁告别。",
    s: "《石壕吏》是杜甫“三吏三别”之一，通过作者亲眼所见的石壕吏乘夜捉人的故事，揭露了封建统治者的残暴，反映了安史之乱给人民带来的深重灾难。全诗以白描手法叙事，情感深沉，是杜甫现实主义诗歌的杰作，被称为“诗史”。"
  },
  "赠花卿|杜甫": {
    y: "锦官城里每日音乐声轻柔悠扬，一半随着江风飘去，一半飘入了云端。\n这样的乐曲只应该天上有，人世间芸芸众生哪里能听见几回？",
    s: "《赠花卿》表面上赞美乐曲的美妙，“此曲只应天上有，人间能得几回闻”是千古传诵的名句。实际上，花卿是武将，却僭用天子礼乐，杜甫此诗暗含讽喻，意在言外，含蓄委婉，是杜诗中“寓讽于颂”的佳作。"
  },
  "长恨歌|白居易": {
    y: "唐明皇爱好女色一心想要得到绝世美人，登基多年却始终未能求得。\n杨家有个女儿刚刚长大，十分娇艳，养在深闺中，外人不知她美丽绝伦。\n天生丽质让她很难埋没世间，终于有一天被选到皇帝身边。\n她回眸一笑时，千姿百态、娇媚横生；六宫妃嫔，一个个都黯然失色。\n春寒料峭时，皇上赐她到华清池沐浴，温润的泉水洗涤着凝脂一般的肌肤。\n侍女搀扶她，如出水芙蓉软弱娉婷，由此开始得到皇帝恩宠。\n鬓发如云颜脸似花，头戴着金步摇。温暖的芙蓉帐里，与皇上共度春宵。\n春宵苦短，一觉睡到太阳高高升起，从此君王再也不早朝了。\n承欢侍宴，忙碌得没有片刻闲暇，春日陪皇上一起出游，晚上夜夜侍寝。\n后宫中妃嫔不下三千人，却只有她独享皇帝的恩宠。\n金屋中梳妆打扮，夜夜撒娇不离君王；玉楼上酒酣宴罢，醉意更添几许风韵。\n兄弟姐妹都因她列土封侯，杨家门楣光耀令人羡慕。\n于是使得天下的父母都改变了心意，不重视生男孩，只重视生女孩。\n骊山上华清宫内玉宇琼楼高耸入云，清风过处仙乐飘向四面八方。\n轻歌曼舞多合拍，管弦旋律尽传神，君王终日观看，却百看不厌。\n渔阳叛乱的战鼓震耳欲聋，宫中的霓裳羽衣曲被惊破。\n九重宫殿霎时尘土飞扬，君王带着大批臣工美眷向西南逃亡。\n车队走走停停，西出长安才百余里。\n六军停滞不前，要求赐死杨玉环，君王无可奈何，只得在马嵬坡下缢杀杨玉环。\n贵妃头上的饰品，抛撒满地无人收拾。翠翘金雀玉搔头，珍贵头饰一根根。\n君王欲救不能，掩面而泣，回头看贵妃惨死的场景，血泪止不住地流。\n秋风萧索扫落叶，黄土尘埃已消遁，回环曲折穿栈道，车队踏上了剑阁古道。\n峨眉山下行人稀少，旌旗无色，日月无光。\n蜀地山清水秀，引得君王相思情。行宫里望月满目凄然，雨夜听曲声声带悲。\n叛乱平息后，君王重返长安，路过马嵬坡，睹物思人，徘徊不前。\n马嵬坡下荒凉的泥土中，不见美人，空留她死去的地方。\n君臣相顾，泪湿衣衫，东望京都，信马由缰回到宫中。\n回来一看，池苑依旧，太液池的芙蓉，未央宫的垂柳。\n芙蓉像她的脸，柳叶像她的眉，面对此景怎么能不落泪。\n春风吹开桃李花的日子，秋雨打落梧桐叶的时候。\n西宫南苑长满秋草，落叶满阶也无人打扫。\n梨园弟子新添了白发，椒房的宫女也已老去。\n夜晚殿上萤火虫飞过，思绪悄然，孤灯挑尽也无法入眠。\n钟鼓声迟迟响起，夜才刚刚开始，银河耿耿，天快亮了。\n鸳鸯瓦上结了厚厚的霜，翡翠被里谁与我共眠。\n生死离别已经一年，你的魂魄却不曾入我梦来。\n有个临邛道士客居长安，能用精诚招来亡魂。\n感念君王辗转反侧的思念，于是让方士殷勤寻觅。\n驾驭云气如闪电般奔驰，升上天入地下到处寻找。\n上到九天，下到黄泉，两处茫茫都不见。\n忽然听说海上有座仙山，山在虚无缥缈之间。\n玲珑楼阁在五彩云中升起，其中有许多风姿绰约的仙子。\n其中有一人字太真，雪肤花貌，仿佛就是她。\n金阙西厢叩响玉门，转告小玉、双成去通报。\n听说汉家天子派来使者，九华帐里梦魂惊醒。\n披上衣服推开枕头起身徘徊，珠帘银屏一路打开。\n云鬓半偏，刚睡醒，花冠不整就走下堂来。\n风吹衣袖飘飘举起，还像当年跳霓裳羽衣舞。\n玉容寂寞，泪水纵横，像一枝春天带雨的梨花。\n含情凝视，感谢君王，一别之后音容两渺茫。\n昭阳殿里的恩爱已经断绝，蓬莱宫中的岁月漫长。\n回头下望人间，看不见长安，只见尘雾。\n只能用旧物表达深情，把钿合金钗捎去。\n钗留一股，盒留一扇，掰开黄金钗，分开钿合。\n只要心像金钿一样坚贞，天上人间终会相见。\n临别时又殷勤寄语，话中有誓言只有两人知道。\n七月七日长生殿，夜半无人私语时。\n在天上愿做比翼双飞鸟，在地上愿做连理并生枝。\n天长地久也有穷尽的时候，这遗恨却永远没有尽头。",
    s: "《长恨歌》是白居易最著名的长篇叙事诗，以唐玄宗和杨贵妃的爱情故事为主线，将历史与传说、写实与浪漫融为一体。“在天愿作比翼鸟，在地愿为连理枝”“天长地久有时尽，此恨绵绵无绝期”成为千古传诵的爱情名句。全诗叙事曲折，抒情缠绵，语言优美，是中国古典诗歌中最伟大的爱情诗篇。"
  },
  "琵琶引|白居易": {
    y: "秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。\n我下马和客人在船上饯别设宴，举起酒杯要饮却无助兴的管弦。\n酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。\n忽听得江面上传来琵琶清脆声，我忘却了回归客人也不想动身。\n循身轻轻探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。\n我们移船靠近邀请她出来相见，叫下人添酒回灯重新摆起酒宴。\n千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。\n转紧琴轴拨动琴弦试弹了几声，尚未成曲调那形态就非常有情。\n弦弦凄楚悲切声音隐含着沉思，似乎在诉说着她平生的不得志。\n她低着头随手连续地弹个不停，用琴声把心中无限的往事说尽。\n轻轻抚拢慢慢捻滑抹了又加挑，初弹霓裳羽衣曲接着再弹六幺。\n大弦浑宏悠长嘈嘈如暴风骤雨，小弦和缓幽细切切如有人私语。\n嘈嘈声切切声互为交错地弹奏，就像大珠小珠一串串掉落玉盘。\n琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉。\n水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。\n像另有一种愁思幽恨暗暗滋生，此时闷闷无声却比有声更动人。\n突然间好像银瓶撞破水浆四溅，又好像铁甲骑兵厮杀刀枪齐鸣。\n一曲终了她对准琴弦中心划拨，四弦一声轰鸣好像撕裂了布帛。\n东船西舫人们都静悄悄地聆听，只见江心之中映着白白秋月影。\n她沉吟着收起拨片插在琴弦中，整顿衣裳依然显出庄重的颜容。\n她说我原是京城负有盛名的歌女，老家住在长安城东南的虾蟆陵。\n弹奏琵琶技艺十三岁就已学成，教坊乐团第一队中列有我姓名。\n每曲弹罢都令艺术大师们叹服，每次妆成都被同行歌妓们嫉妒。\n京都豪富子弟争先恐后来献彩，弹完一曲收来的红绡不知其数。\n钿头银篦打节拍常常断裂粉碎，红色罗裙被酒渍染污也不后悔。\n年复一年都在欢笑打闹中度过，秋去春来美好的时光白白消磨。\n兄弟从军姊妹死家道已经破败，暮去朝来我也渐渐地年老色衰。\n门前车马减少光顾者落落稀稀，青春已逝我只得嫁给商人为妻。\n商人重利不重情常常轻易别离，上个月他去浮梁做茶叶的生意。\n他去了留下我在江口孤守空船，秋月与我作伴绕舱的秋水凄寒。\n更深夜阑常梦少年时作乐狂欢，梦中哭醒纵横了泪水和脂粉。\n我听了琵琶声早已摇头叹息，又听到她这番诉说更加歔欷。\n同样都是天涯沦落的可怜人，今日相逢何必问是否曾经相识！\n自从去年我离开繁华长安京城，被贬居住在浔阳江畔常常卧病。\n浔阳这地方荒凉偏僻没有音乐，一年到头也听不到管弦的乐器声。\n住在湓江附近低洼潮湿的地方，黄芦和苦竹绕着宅第丛生。\n在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。\n春江花朝秋江月夜那样好光景，也无可奈何常常取酒独酌独饮。\n难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。\n今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。\n请你不要推辞坐下来再弹一曲，我要为你创作一首新诗琵琶行。\n被我的话所感动她站立了好久，回身坐下再转紧琴弦拨出急声。\n凄凄切切不再像刚才那种声音，在座的人重听都掩面哭泣不停。\n要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！",
    s: "《琵琶行》是白居易贬官江州时所作，通过描写琵琶女的高超技艺和不幸身世，抒发了自己被贬的愤懑之情。“同是天涯沦落人，相逢何必曾相识”是千古传诵的名句，将诗人与琵琶女的命运联系在一起，感人至深。诗中对琵琶音乐的描写更是出神入化，“大珠小珠落玉盘”“此时无声胜有声”等句成为描写音乐的经典。"
  },
  "忆江南·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "新乐府·卖炭翁\t苦官市也|白居易": {
    y: "有位卖炭的老翁，整年在南山里砍柴烧炭。\n他满脸灰尘，显出被烟熏火燎的颜色，两鬓头发灰白，十个手指也被炭烧得很黑。\n卖炭得到的钱用来干什么？买身上穿的衣裳和嘴里吃的食物。\n可怜他身上只穿着单薄的衣服，心里却担心炭卖不出去，还希望天更寒冷。\n夜里城外下了一尺厚的大雪，清晨，老翁驾着炭车碾轧冰冻的车轮印往集市上赶去。\n牛累了，人饿了，但太阳已经升得很高了，他们就在集市南门外泥泞中歇息。\n那得意忘形的骑着两匹马的人是谁啊？是皇宫内的太监和太监的手下。\n太监手里拿着文书，嘴里却说是皇帝的命令，吆喝着牛朝皇宫拉去。\n一车的炭，一千多斤，太监差役们硬是要赶着走，老翁是百般不舍，但又无可奈何。\n那些人把半匹红纱和一丈绫，朝牛头上一挂，就充当炭的价钱了。",
    s: "《卖炭翁》是白居易《新乐府》中的名篇，通过卖炭翁的遭遇，深刻揭露了宫市制度的罪恶，对劳动人民寄予深切同情。“可怜身上衣正单，心忧炭贱愿天寒”将老人矛盾的心理写得入木三分，是白居易现实主义诗歌的代表作。"
  },
  "金陵五题·乌衣巷|刘禹锡": {
    y: "朱雀桥边冷落荒凉，野草丛生，开出了野花；乌衣巷口断壁残垣，正是夕阳西斜。\n当年王导、谢安檐下的燕子，如今已飞进寻常百姓家中。",
    s: "《乌衣巷》是刘禹锡《金陵五题》中最著名的一首，通过乌衣巷的今昔对比，抒发了对世事沧桑、富贵无常的感慨。“旧时王谢堂前燕，飞入寻常百姓家”以燕子的变迁写尽历史兴亡，含蓄深沉，是咏史怀古诗的杰作。"
  },
  "望洞庭|刘禹锡": {
    y: "洞庭湖水色与月光互相辉映，湖面风平浪静，犹如未磨的铜镜。\n远远眺望洞庭湖山水苍翠如墨，好似白银盘里托着一枚青螺。",
    s: "《望洞庭》以奇特的比喻描绘了洞庭湖的秋夜美景，“白银盘里一青螺”将洞庭湖比作白银盘，将君山比作青螺，想象奇特，形象生动。全诗意境优美，格调清新，是描写洞庭湖的名篇。"
  },
  "雁门太守行|李贺": {
    y: "敌兵滚滚而来，犹如黑云翻卷，想要摧倒城墙；战士们的铠甲在阳光照射下金光闪烁。\n号角声响彻秋夜的长空，边塞上将士的血迹在寒夜中凝为紫色。\n红旗半卷，援军赶赴易水；夜寒霜重，鼓声郁闷低沉。\n为了报答国君的赏赐和厚爱，手操宝剑甘愿为国血战到死。",
    s: "《雁门太守行》是李贺的代表作，“黑云压城城欲摧”以夸张手法渲染敌军兵临城下的紧张气氛，“甲光向日金鳞开”写守军的严阵以待。全诗色彩浓烈，意境悲壮，“报君黄金台上意，提携玉龙为君死”表达了将士誓死报国的决心，是李贺诗风的典型体现。"
  },
  "李凭箜篌引|李贺": {
    y: "在深秋的夜晚，弹奏起吴丝蜀桐制成精美的箜篌。听到美妙的乐声，天空的白云凝聚起来不再飘游。\n湘娥把泪珠洒满斑竹，九天素女也牵动满腔忧愁。出现这种情况，是由于乐工李凭在京城弹奏箜篌。\n乐声清脆动听得就像昆仑山美玉击碎，凤凰鸣叫；时而使芙蓉在露水中饮泣，时而使香兰开怀欢笑。\n清脆的乐声，融和了长安城十二门前的清冷光气。二十三根弦丝高弹轻拨，打动了高高在上的天帝。\n高亢的乐声直冲云霄，冲上女娲炼石补过的天际。好似补天的五彩石被击破，逗落了漫天绵绵秋雨。\n幻觉中仿佛乐工进入了神山，把技艺向女仙传授；老鱼兴奋得在波中跳跃，瘦蛟也翩翩起舞乐悠悠。\n月宫中吴刚被乐声吸引，彻夜不眠在桂树下逗留。桂树下的兔子也伫立聆听，不顾露珠斜飞寒飕飕！",
    s: "《李凭箜篌引》是李贺描写音乐的名篇，与白居易《琵琶行》、韩愈《听颖师弹琴》并为唐诗中写音乐的三大杰作。诗人以奇特的想象和夸张的手法，将箜篌声的美妙写得惊心动魄，“昆山玉碎凤凰叫”“石破天惊逗秋雨”等句想象奇绝，充分体现了李贺“诗鬼”的艺术特色。"
  },
  "乐游原|李商隐": {
    y: "傍晚时分我心情不太好，独自驱车登上了乐游原。\n这夕阳晚景的确十分美好，只不过已是黄昏。",
    s: "《登乐游原》仅二十字，却蕴含着深沉的哲理。“夕阳无限好，只是近黄昏”既写出了夕阳的美丽，又感叹好景不长，既有对美好事物的珍惜，又有对时光流逝的无奈，成为千古传诵的名句。"
  },
  "常娥|李商隐": {
    y: "云母屏风上烛影暗淡，银河渐渐斜落，晨星也隐没低沉。\n嫦娥应该后悔偷取了长生不老之药，如今空对碧海青天夜夜孤寂。",
    s: "《嫦娥》借嫦娥奔月的神话故事，抒发了诗人孤寂清高的心境。“嫦娥应悔偷灵药，碧海青天夜夜心”以嫦娥的孤独比喻自己的处境，含蓄深沉，意境悠远，是李商隐七绝中的佳作。"
  },
  "阿房宫赋|杜牧": {
    y: "六国灭亡，四海统一；蜀地的山变得光秃秃了，阿房宫建造出来了。它从渭南到咸阳覆盖了三百多里地，宫殿高耸，遮天蔽日。它从骊山北边建起，折而向西，一直通到咸阳。渭水、樊川浩浩荡荡的，流进宫墙里边。五步一座楼，十步一个阁；走廊如绸带般萦回，牙齿般排列的飞檐像鸟嘴向高处啄着。楼阁各依地势的高低倾斜而建筑，低处的屋角钩住高处的屋心，并排相向的屋角彼此相斗。盘结交错，曲折回旋，远观鸟瞰，建筑群如密集的蜂房，如旋转的水涡，高高地耸立着，不知道它有几千万座。没有起云，为什么有龙？原来是一座长桥躺在水波上。不是雨过天晴，为什么出虹？原来是天桥在空中行走。房屋忽高忽低，幽深迷离，使人不能分辨东西。歌台上由于歌声响亮而充满暖意，有如春光融和；舞殿上由于舞袖飘拂而充满寒意，有如风雨凄凉。一天里边，一座宫殿中间，气候却不一样。\n六国的宫妃、王子王孙，辞别六国的宫楼，走下六国的宫殿，坐着辇车来到秦国。他们早上歌唱，晚上奏乐，成为秦国的宫人。明亮的星星晶莹闪烁，这是宫妃们打开了梳妆的镜子；乌青的云朵纷纷扰扰，这是宫妃们在梳理晨妆的发髻；渭水涨起一层油腻，这是宫妃们抛弃了的胭脂水；烟霭斜斜上升，云雾横绕空际，这是宫中在焚烧椒、兰制的香料；雷霆突然震响，这是宫车驶过去了；辘辘的车声越听越远，无影无踪，不知道它去到什么地方。每一片肌肤，每一种容颜，都美丽娇媚得无以复加。宫妃们久久地站着，远远地探视，盼着皇帝来临。有的宫女竟整整三十六年没能见到皇帝。\n燕赵、韩魏收藏的金玉珍宝，齐楚精华的财富，是多少代多少年，从人民那里抢来的，堆叠得像山一样。一旦国家灭亡，不能占有了，统统运进了阿房宫。把宝鼎当作铁锅，把美玉当作石头，把黄金当作土块，把珍珠当作沙石，随意丢弃，秦人看见了也不觉得可惜。\n唉！一个人的想法和千万人的想法是一样的。秦始皇喜爱奢侈，老百姓也顾念自己的家业。为什么搜刮老百姓的财物一分一厘都不放过，挥霍时却像泥沙一样毫不珍惜呢？让那承担栋梁的柱子，比田地里的农夫还多；架在梁上的椽子，比织机上的女工还多；梁柱上的钉头光彩耀目，比粮仓里的粟粒还多；瓦楞长短不一，比全身的丝缕还多；或直或横的栏杆，比九州的城郭还多；管弦的声音嘈杂，比市民的言语还多。使天下的人民，口里不敢说，心里却敢愤怒。可是失尽人心的秦始皇，一天天更加骄傲顽固。结果戍边的陈胜、吴广一声呼喊，函谷关被攻下，楚兵一把大火，可惜阿房宫化为一片焦土。\n唉！灭亡六国的是六国自己，不是秦国啊。消灭秦王朝的是秦王朝自己，不是天下的人啊。可叹呀！假使六国各自爱护它的人民，就完全可以依靠人民来抵抗秦国。假使秦王朝又爱护六国的人民，那么皇位就可以传到三世还可以传到万世做皇帝，谁能够族灭它呢？秦人来不及哀悼自己，而后人替他们哀伤；如果后人哀悼他却不把他作为鉴戒吸取教训，也只会使更后的人又来哀悼这后人啊。",
    s: "《阿房宫赋》是杜牧的代表作，借秦王朝因奢侈荒淫而亡国的历史教训，讽喻当时的统治者。“灭六国者六国也，非秦也；族秦者秦也，非天下也”“后人哀之而不鉴之，亦使后人而复哀后人也”是千古传诵的名句，寓意深刻。全文辞藻华丽，气势磅礴，是唐代文赋的典范。"
  },
  "赤壁|杜牧": {
    y: "赤壁的泥沙中，埋着一枚未锈尽的断戟。自己磨洗后发现这是当年赤壁之战的遗留之物。\n倘若不是东风给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。",
    s: "《赤壁》是杜牧咏史诗的代表作，借赤壁之战的历史事件，以“东风不与周郎便，铜雀春深锁二乔”的假设，表达了对历史兴亡的独特见解。全诗以小见大，含蓄深沉，是咏史诗中的杰作。"
  },
  "江南春绝句|杜牧": {
    y: "辽阔的江南，到处莺歌燕舞，绿树红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的许多座古寺，如今有多少笼罩在这蒙胧烟雨之中。",
    s: "《江南春》以极简练的笔触描绘了江南春天的美丽景象，“千里莺啼绿映红”从听觉和视觉写江南春景，“南朝四百八十寺，多少楼台烟雨中”在写景中融入历史兴亡的感慨，意境深远，是描写江南春景的千古名篇。"
  },
  "枫桥夜泊|张继": {
    y: "月亮已落下乌鸦啼叫寒气满天，江边枫树与船上渔火，难抵我独自傍愁而眠。\n姑苏城外那寂寞清静寒山古寺，半夜里敲钟的声音传到了客船。",
    s: "《枫桥夜泊》是张继最著名的诗作，描写了夜泊枫桥的所见所闻所感。“月落乌啼霜满天”渲染了凄清的氛围，“姑苏城外寒山寺，夜半钟声到客船”以钟声衬托夜的寂静和诗人的愁思，意境悠远，是唐诗中最著名的羁旅诗之一，寒山寺也因此诗名扬天下。"
  },
  "题都城南庄|崔护": {
    y: "去年的这个时候，我从这扇门里望去，只见那美丽的脸庞和桃花彼此相互映衬的绯红。\n今日再来此地，那佳人已不知所踪，只有桃花依旧，含笑怒放春风之中。",
    s: "《题都城南庄》以“人面”“桃花”为线索，通过去年与今年的对比，抒发了物是人非的惆怅。“人面不知何处去，桃花依旧笑春风”成为千古传诵的名句，全诗意境优美，情感含蓄，是唐诗中最脍炙人口的作品之一。"
  },
  "古风二首·二|李绅": {
    y: "盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？",
    s: "《悯农》是李绅最著名的诗作，“谁知盘中餐，粒粒皆辛苦”以朴素的语言道出了粮食的来之不易，告诫人们珍惜粮食、尊重劳动。全诗语言浅近，寓意深刻，是中国流传最广的诗篇之一。"
  },
  "离思五首·四|元稹": {
    y: "经历过波澜壮阔的大海，别处的水再也不值得一观。陶醉过巫山的云雨的梦幻，别处的风景就不称之为云雨了。\n即使身处万花丛中，我也懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。",
    s: "《离思》是元稹悼念亡妻韦丛所作，“曾经沧海难为水，除却巫山不是云”以沧海之水和巫山之云比喻爱情的深广与美好，表达了对亡妻的忠贞不渝。全诗情感真挚，意境深远，是中国文学史上最著名的悼亡诗之一。"
  },
  "菊花|元稹": {
    y: "一丛一丛的秋菊环绕着房屋，好似到了陶渊明的家。绕着篱笆观赏菊花，不知不觉太阳已经快落山了。\n不是因为百花中偏爱菊花，只是因为菊花开过之后，再不能够看到好花了。",
    s: "《菊花》是元稹咏菊的名篇，“不是花中偏爱菊，此花开尽更无花”点明了爱菊的原因，既写出了菊花在深秋独放的特点，也暗含了对菊花坚贞品格的赞美。全诗语言朴素，构思巧妙，是咏菊诗中的佳作。"
  },
  "凉州词二首·一|王翰": {
    y: "酒筵上甘醇的葡萄美酒盛满在夜光杯之中，正要畅饮时，马上琵琶也声声响起，仿佛催人出征。\n如果醉卧在沙场上，也请你不要笑话，古来出外打仗的能有几人返回家乡？",
    s: "《凉州词》是王翰的代表作，描写了边塞将士在出征前开怀畅饮的场景。“醉卧沙场君莫笑，古来征战几人回”以豪迈旷达的语气写出了战争的残酷和将士们视死如归的气概，全诗格调苍凉而豪放，是唐代边塞诗的名篇。"
  },
  "回乡偶书二首·一|贺知章": {
    y: "年少时离乡老年才归家，我的乡音虽未改变，但鬓角的毛发却已经疏落。\n家乡的儿童们看见我，没有一个认识我。他们笑着询问我：你是从哪里来的呀？",
    s: "《回乡偶书》是贺知章八十多岁告老还乡时所作，“少小离家老大回，乡音无改鬓毛衰”写出了久客他乡的感慨，“儿童相见不相识，笑问客从何处来”以儿童的天真提问，反衬出诗人的沧桑与悲凉，全诗语言朴素，情感深沉，是唐诗中最感人的思乡名篇。"
  },
  "惠崇春江晚景|苏轼": {
    y: "竹林外两三枝桃花初放，水中嬉戏的鸭子最先察觉到初春江水的回暖。\n河滩上长满了蒌蒿，芦苇也长出短短的新芽，而河豚此时正要逆流而上，从大海回游到江河里来了。",
    s: "《惠崇春江晚景》是苏轼为僧人惠崇的画所作的题画诗，“春江水暖鸭先知”既写出了画中鸭子戏水的情景，又蕴含着实践出真知的哲理。全诗将画面与想象结合，生动再现了江南早春的景象，是题画诗的典范。"
  },
  "六月二十七日望湖楼醉书|苏轼": {
    y: "乌云上涌，就如墨汁泼下，却又在天边露出一段山峦，明丽清新，大雨激起的水花如白珠碎石，飞溅入船。\n忽然间狂风卷地而来，吹散了满天的乌云，而那西湖的湖水碧波如镜，明媚温柔。",
    s: "《六月二十七日望湖楼醉书》描写了西湖夏日暴雨的景象，“黑云翻墨未遮山，白雨跳珠乱入船”以“翻墨”“跳珠”的比喻，将乌云和白雨写得生动形象，“卷地风来忽吹散，望湖楼下水如天”写雨过天晴的开阔，全诗节奏明快，是苏轼写景诗的佳作。"
  },
  "书愤|陆游": {
    y: "年轻时哪里知道世事如此艰难，北望中原，收复故土的豪迈气概坚定如山。\n记得在瓜州渡痛击金兵，雪夜里飞奔着楼船战舰。秋风中跨战马纵横驰骋，收复了大散关捷报频传。\n我当初自比万里长城，立壮志为祖国扫除边患。到如今垂垂老鬓发如霜，盼北伐盼恢复都成空谈。\n出师表真可谓名不虚传，有谁像诸葛亮鞠躬尽瘁，率三军复汉室北定中原！",
    s: "《书愤》是陆游晚年的代表作，追述了早年的抗金经历，抒发了壮志未酬的悲愤。“楼船夜雪瓜洲渡，铁马秋风大散关”以六个名词组合，勾勒出两幅壮阔的战争画面，是宋诗中的名句。全诗感情沉郁，气壮山河，是陆游爱国诗的杰作。"
  },
  "登飞来峰|王安石": {
    y: "登上飞来峰顶高高的塔，听说每天鸡鸣时分在这可以看到旭日升起。\n不怕层层浮云遮挡我远望的视线，只因为如今我站在最高层。",
    s: "《登飞来峰》是王安石青年时期的作品，“不畏浮云遮望眼，自缘身在最高层”由登塔望远悟出哲理：只要站得高、看得远，就不怕被浮云遮住视线，表达了诗人高瞻远瞩、不畏艰难的政治抱负，是宋诗中著名的哲理诗。"
  },
  "四时田园杂兴·其三十一|范成大": {
    y: "白天去田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树荫下学着种瓜。",
    s: "《四时田园杂兴》是范成大田园诗的代表作，描写了农村夏日的劳动场景。“童孙未解供耕织，也傍桑阴学种瓜”以儿童学种瓜的细节，写出了农村劳动的代代相传，充满生活气息，全诗语言朴素，意境清新，是宋代田园诗的佳作。"
  },
  "游园不值|叶绍翁": {
    y: "也许是园主担心我的木屐踩坏他那爱惜的青苔，我轻轻地敲打柴门久久不开。\n满园子的春色是关不住的，开得正旺的红杏有一枝枝条伸到墙外来了。",
    s: "《游园不值》写诗人游园不遇，却从出墙的一枝红杏感受到满园春色。“春色满园关不住，一枝红杏出墙来”既写出了春天的蓬勃生机，又蕴含着新生事物不可阻挡的哲理，成为千古传诵的名句。"
  },
  "己亥杂诗·其五|龚自珍": {
    y: "离别京都的愁思浩如水波向着日落西斜的远处延伸，马鞭向东一挥，感觉就是人在天涯一般。\n从枝头上掉下来的落花不是无情之物，即使化作春泥，也甘愿培育美丽的春花成长。",
    s: "《己亥杂诗》是龚自珍辞官南归时所作，“落红不是无情物，化作春泥更护花”以落花自喻，表达了虽已辞官，却依然心系国家、愿为国家培养人才的奉献精神，成为千古传诵的名句。"
  },
  "咏鹅|骆宾王": {
    y: "鹅呀，鹅呀，鹅呀，弯曲着脖子对天高歌。\n一身雪白的羽毛浮于绿水之上，红色的脚掌拨动着清澈的水波。",
    s: "《咏鹅》是骆宾王七岁时的作品，也是中国流传最广的儿童启蒙诗。全诗以白描手法描绘了鹅的形态和动作，“曲项”“白毛”“红掌”“绿水”色彩鲜明，画面生动，语言浅近，是小学生最熟悉的古诗之一。"
  },
  "古朗月行|李白": {
    y: "小时候不认识月亮，把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。\n月中的仙人是垂着双脚吗？月中的桂树为什么长得圆圆的？\n白兔捣成的仙药，到底是给谁吃的呢？",
    s: "《古朗月行》是李白借古题写的诗，前四句以儿童的视角描写月亮，充满童趣；后四句引用月亮神话，表达了对月亮的好奇与想象。全诗想象丰富，语言明快，是小学课本中的经典篇目。"
  },
  "风|李峤": {
    y: "风能吹落秋天金黄的树叶，能吹开春天美丽的鲜花。\n刮过江面能掀千尺巨浪，吹进竹林能使万竿倾斜。",
    s: "《风》是一首咏物诗，全诗没有一个“风”字，却处处在写风。“解落三秋叶，能开二月花”写风的力量，“过江千尺浪，入竹万竿斜”写风的气势，构思巧妙，是小学课本中的经典篇目。"
  },
  "渔父歌·一|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "和张仆射塞下曲·三|卢纶": {
    y: "死寂之夜，乌云遮月，天边大雁惊飞，单于的军队想要趁着夜色悄悄潜逃。\n正想要带领轻骑兵一路追赶，大雪纷纷扬扬落满了身上的弓刀。",
    s: "《塞下曲》是卢纶的边塞诗名作，“月黑雁飞高，单于夜遁逃”写敌军夜逃，“欲将轻骑逐，大雪满弓刀”写将士追击，全诗没有直接写战斗，却充满紧张的战斗氛围，气势雄浑，是唐代边塞诗的佳作。"
  },
  "浪淘沙九首·一|刘禹锡": {
    y: "弯弯曲曲的黄河，挟带着泥沙，波涛滚滚如巨风掀簸来自天涯。\n如今好像要直飞上高空的银河，请你带上我一起去寻访牛郎织女的家。",
    s: "《浪淘沙》是刘禹锡的组诗，这一首描写黄河的雄伟景象。“九曲黄河万里沙”写出黄河的蜿蜒与泥沙，“如今直上银河去，同到牵牛织女家”由黄河联想到银河，想象奇特，充满浪漫主义色彩。"
  },
  "忆江南词三首·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "池上二绝·二|白居易": {
    y: "小娃撑着小船，偷偷地从池塘里采了白莲回来。\n他不懂得掩藏自己的行踪，浮萍被船儿荡开，水面上留下了一条长长的水线。",
    s: "《池上》是白居易描写儿童生活的小诗，“小娃撑小艇，偷采白莲回”写出了小孩的天真淘气，“不解藏踪迹，浮萍一道开”以浮萍被分开的细节，将小孩的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "小儿垂钓|胡令能": {
    y: "一个头发蓬乱、面孔青嫩的小孩在河边学钓鱼，侧身坐在青苔上绿草映衬着他的身影。\n听到有过路的人问路，小孩漠不关心地摆了摆手，不敢回应路人生怕惊动了鱼儿。",
    s: "《小儿垂钓》是胡令能的名作，描写了一个小孩钓鱼的场景。“蓬头稚子学垂纶”写出小孩的天真，“路人借问遥招手，怕得鱼惊不应人”以小孩的动作和心理，将钓鱼时的专注写得生动传神。全诗充满生活气息，是小学课本中的经典篇目。"
  },
  "寻隐者不遇|贾岛": {
    y: "苍松下询问年少的学童，他说他的师傅已经去山中采药了。\n只知道就在这座大山里，可山中云雾缭绕不知道他的行踪。",
    s: "《寻隐者不遇》是贾岛的名作，以问答形式写寻访隐者不遇的情景。“松下问童子，言师采药去”写问答，“只在此山中，云深不知处”以景结情，将隐者的高洁与寻访的怅惘写得含蓄深沉。全诗语言朴素，意境悠远，是唐诗五绝的精品。"
  },
  "蜂|罗隐": {
    y: "无论是在平地，还是在山峰，极其美好的风景都被蜜蜂占有。\n蜜蜂啊，你采尽百花酿成了花蜜，到底为谁付出辛苦，又想让谁品尝香甜？",
    s: "《蜂》是罗隐的咏物诗，以蜜蜂采花酿蜜的现象，发出“为谁辛苦为谁甜”的追问，既赞美了蜜蜂的勤劳，又暗含对劳动者的同情和对不劳而获者的讽刺。全诗寓意深刻，是小学课本中的经典篇目。"
  },
  "书湖阴先生壁|王安石": {
    y: "茅草房庭院经常打扫，洁净得没有一丝青苔。花草树木成行成垄，都是主人亲手栽种。\n庭院外一条小河护卫环绕着园田，将绿苗紧紧环绕；两座青山打开门来为人们送来绿色。",
    s: "《书湖阴先生壁》是王安石题在邻居杨德逢屋壁上的诗，“一水护田将绿绕，两山排闼送青来”以拟人手法写山水，“护”字和“排闼”将山水写得有情有义，构思巧妙，是王安石写景诗的佳作。"
  },
  "夏日绝句|李清照": {
    y: "活着就要当人中的俊杰，死了也要做鬼中的英雄。\n人们到现在还思念项羽，只因他不肯苟且偷生，退回江东。",
    s: "《夏日绝句》是李清照的名作，“生当作人杰，死亦为鬼雄”以铿锵有力的语言，表达了对英雄气概的赞美和对南宋朝廷偏安一隅的讽刺。全诗借项羽不肯过江东的典故，抒发了爱国情怀，是李清照少有的豪放之作。"
  },
  "三衢道中|曾几": {
    y: "梅子成熟的时候，天天都是晴朗的好天气，乘小船走到小溪的尽头，再走山间小路。\n山路上古树苍翠，与水路上的风景相比也毫不逊色，深林丛中传来几声黄鹂的欢鸣声，更增添了些幽趣。",
    s: "《三衢道中》是曾几的名作，描写了初夏时节在三衢山中行走的所见所闻。“绿阴不减来时路，添得黄鹂四五声”以绿荫和黄鹂声写出了山路的幽静与生机，全诗语言清新，意境优美，是小学课本中的经典篇目。"
  },
  "秋夜将晓出篱门迎凉有感|陆游": {
    y: "三万里长的黄河奔腾向东流入大海，五千仞高的华山耸入云霄触青天。\n中原人民在胡人压迫下眼泪已流尽，他们盼望王师北伐盼了一年又一年。",
    s: "《秋夜将晓出篱门迎凉有感》是陆游的名作，“三万里河东入海，五千仞岳上摩天”以夸张手法写祖国山河的壮丽，“遗民泪尽胡尘里，南望王师又一年”写中原百姓对王师的期盼，全诗气势雄浑，情感深沉，是陆游爱国诗的代表作。"
  },
  "观书有感·其一|朱熹": {
    y: "半亩大的方形池塘像一面镜子一样打开，清澈明净，天光、云影在水面上闪耀浮动。\n要问池塘里的水为何这样清澈呢？是因为有永不枯竭的源头源源不断地为它输送活水。",
    s: "《观书有感》是朱熹的哲理诗，“问渠那得清如许？为有源头活水来”以池塘清澈因为有源头活水，比喻读书学习要不断汲取新知识，才能保持思想的清新与活力。全诗寓理于景，是宋诗中著名的哲理诗。"
  },
  "题临安邸|林升": {
    y: "西湖四周青山绵延楼阁望不见头，湖面游船上的歌舞几时才能停休？\n温暖馥郁的香风把人吹得醉醺醺的，简直是把杭州当成了那汴州。",
    s: "《题临安邸》是林升的讽喻诗，“山外青山楼外楼，西湖歌舞几时休”描写了南宋朝廷偏安江南、醉生梦死的景象，“暖风熏得游人醉，直把杭州作汴州”讽刺了统治者忘记国耻、苟且偷安的行为，是南宋讽喻诗的名作。"
  },
  "乡村四月|翁卷": {
    y: "山坡田野间草木茂盛，稻田里的水色与天光相辉映。天空中烟雨蒙蒙，杜鹃声声啼叫，大地一片欣欣向荣的景象。\n四月到了，没有人闲着，刚刚结束了蚕桑的事又要插秧了。",
    s: "《乡村四月》是翁卷的名作，描写了江南农村四月的繁忙景象。“绿遍山原白满川，子规声里雨如烟”写乡村美景，“乡村四月闲人少，才了蚕桑又插田”写农民的忙碌，全诗色彩明丽，充满生活气息，是小学课本中的经典篇目。"
  },
  "墨梅|王冕": {
    y: "我家洗砚池边有一棵梅树，朵朵开放的梅花都像是用淡淡的墨汁点染而成。\n它不需要别人夸奖颜色多么好看，只是要将清香之气弥漫在天地之间。",
    s: "《墨梅》是王冕的题画诗，以墨梅自喻，“不要人夸好颜色，只留清气满乾坤”表达了诗人不慕虚荣、坚守高洁品格的精神。全诗语言朴素，寓意深刻，是小学课本中的经典篇目。"
  },
  "所见|袁枚": {
    y: "牧童骑在黄牛背上，嘹亮的歌声在树林里回荡。\n忽然想要捕捉树上鸣叫的知了，就马上停止唱歌，一声不响地站立在树旁。",
    s: "《所见》是袁枚的名作，描写了牧童放牛的场景。“牧童骑黄牛，歌声振林樾”写牧童的天真快乐，“意欲捕鸣蝉，忽然闭口立”以牧童的动作变化，将儿童的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "终南别业|王维": {
    y: "中年以后存有较浓的好道之心，直到晚年才安家于终南山边陲。\n兴趣浓时常常独来独往去游玩，有快乐的事自我欣赏自我陶醉。\n间或走到水的尽头去寻求源流，间或坐看上升的云雾千变万化。\n偶然在林间遇见个把乡村父老，偶与他谈笑聊天每每忘了还家。",
    s: "《终南别业》是王维的代表作，“行到水穷处，坐看云起时”是抖音上极火的诗句，表达了随遇而安、豁达从容的人生态度。全诗描写了隐居终南山的悠闲生活，意境悠远，充满禅意，是王维山水诗的精品。"
  },
  "南园十三首·五|李贺": {
    y: "男子汉大丈夫为什么不腰带武器，去收复黄河南北被割据的关塞河山五十州呢？\n请你暂且登上那凌烟阁去看一看，又有哪一个书生曾被封为食邑万户的列侯？",
    s: "《南园十三首·其五》是李贺的名作，“男儿何不带吴钩，收取关山五十州”是抖音上最火的“杀气诗词”之一，充满少年人的意气风发和报国豪情。全诗语言刚劲，气势磅礴，表达了诗人渴望建功立业的雄心壮志。"
  },
  "山园小梅·其一|林逋": {
    y: "百花凋零，独有梅花迎着寒风昂然盛开，那明媚艳丽的景色把小园的风光占尽。\n稀疏的影儿，横斜在清浅的水中，清幽的芬芳浮动在黄昏的月光之下。\n寒雀想飞落下来时，先偷看梅花一眼；蝴蝶如果知道梅花的妍美，定会消魂失魄。\n幸喜我能低声吟诵，和梅花亲近，不用敲着檀板唱歌，执着金杯饮酒来欣赏它了。",
    s: "《山园小梅》是林逋的代表作，“疏影横斜水清浅，暗香浮动月黄昏”是咏梅的千古绝唱，2026年春晚后在抖音上爆火。这两句以极简练的笔墨写出了梅花的姿态和香气，意境清雅，被誉为咏梅诗的巅峰之作。"
  },
  "沁园春·长沙|毛泽东": {
    y: "深秋季节，我独自站立在橘子洲头，望着滔滔的湘水向北奔流。万千山峰全都变成了红色，层层树林好像染过颜色一样；江水清澈澄碧，一艘艘大船乘风破浪，争先恐后。鹰在广阔的天空里飞，鱼在清澈的水里游，万物都在秋光中争着过自由自在的生活。面对广阔的宇宙惆怅感慨：这旷远苍茫大地的盛衰沉浮，该由谁来主宰呢？\n曾经我和我的同学，经常携手结伴来到这里漫游。在一起商讨国家大事，那无数不平凡的岁月至今还萦绕在我的心头。同学们正值青春年少，风华正茂；大家踌躇满志，意气奔放，劲头正足。评论国家大事，写出这些激浊扬清的文章，把当时那些军阀官僚看得如同粪土。可曾记得，那时我们在江水深急的地方游泳，那激起的浪花几乎挡住了疾驰而来的行船？",
    s: "《沁园春·长沙》是毛泽东的代表作，“怅寥廓，问苍茫大地，谁主沉浮”是抖音上极火的词句，气势磅礴，充满青年革命者的豪情壮志。全词上阕写景，下阕抒情，将个人抱负与国家命运融为一体，是中国现代诗词的巅峰之作。"
  },
  "临江仙·滚滚长江东逝水|杨慎": {
    y: "滚滚长江向东流去，不再回头，多少英雄像翻飞的浪花般消逝。争什么是与非、成功与失败，到头来都是一场空。只有青山依然存在，依然的日升日落。\n江上白发渔翁，早已习惯于四时的变化。和朋友难得见了面，痛快地畅饮一杯酒。古往今来的纷纷扰扰，都成为下酒闲谈的材料。",
    s: "《临江仙·滚滚长江东逝水》是杨慎的代表作，因《三国演义》电视剧主题曲而家喻户晓，也是抖音上极火的诗词。“古今多少事，都付笑谈中”表达了对历史兴亡的旷达态度，全词意境雄浑，情感深沉，是中国古典诗词中的千古绝唱。"
  },
  "登科后|孟郊": {
    y: "以往在生活上的困顿与思想上的局促不安再不值得一提了，今朝金榜题名，郁结的闷气已如风吹云散，心上真有说不尽的畅快，真想拥抱一下这大自然。\n策马奔驰于春花烂漫的长安道上，今日的马蹄格外轻盈，不知不觉中早已把长安的繁荣花朵看完了。",
    s: "《登科后》是孟郊进士及第后所作，“春风得意马蹄疾，一日看尽长安花”是抖音上极火的诗句，描写了金榜题名后的狂喜心情。全诗节奏明快，情感奔放，“春风得意”也成为成语，形容事业顺利、心情舒畅。"
  },
  "行行重行行|佚名": {
    y: "走啊走啊走，一直在不停的走，就这样与你活生生的分离。\n从此你我之间相距千万里，我在天这头你就在天那头。\n路途那样艰险又那样遥远，要见面可知道是什么时候？\n北马南来仍然依恋着北风，南鸟北飞筑巢还在南枝头。\n彼此分离的时间越长越久，衣服越发宽大人越发消瘦。\n飘荡的浮云遮住了太阳，游子却还不想回家。\n只因为想你使我都变老了，又是一年很快地到了年关。\n还有许多心里话都不说了，只愿你多保重切莫受饥寒。",
    s: "《行行重行行》是《古诗十九首》的首篇，“思君令人老，岁月忽已晚”是抖音上极火的诗句，道尽了相思之苦和岁月之叹。全诗以朴素的语言描写了思妇对远行丈夫的思念，情感真挚，是五言诗的典范之作。"
  },
  "望月怀远|张九龄": {
    y: "茫茫的海上升起一轮明月，你我相隔天涯却共赏月亮。\n多情的人都怨恨月夜漫长，整夜里不眠而把亲人怀想。\n熄灭蜡烛怜爱这满屋月光，我披衣徘徊深感夜露寒凉。\n不能把美好的月色捧给你，只望能够与你相见在梦乡。",
    s: "《望月怀远》是张九龄的代表作，“海上生明月，天涯共此时”是千古传诵的中秋名句，也是抖音上极火的诗句。全诗以明月起兴，描写了对远方亲人的思念，意境开阔，情感深沉，是唐诗中最著名的望月诗之一。"
  },
  "感遇十二首·一|张九龄": {
    y: "兰草逢春，枝叶繁盛；桂花到秋，皎洁芬芳。\n世间万物都顺应季节，生机勃勃，欣欣向荣。\n谁知那些山林中的隐士，闻到兰桂的芬芳，心生爱慕。\n草木散发香气本是天性，哪里是为了求美人折取呢？",
    s: "《感遇》是张九龄的组诗，这一首以兰桂自喻，“草木有本心，何求美人折”表达了诗人坚守本心、不慕荣利的高洁品格。全诗托物言志，语言清雅，是盛唐五言古诗的代表作。"
  },
  "在岳咏蝉|骆宾王": {
    y: "深秋季节寒蝉叫个不停，蝉声把我这囚徒的愁绪带到远方。\n怎么能忍受这秋蝉扇动乌黑双翅，对我一头斑斑白发，不尽不止地长吟。\n秋露浓重，蝉儿纵使展开双翼也难以高飞，寒风瑟瑟，轻易地把它的鸣唱淹没。\n虽然蝉儿居高食洁，又有谁能相信我的清白，代我表述内心的沉冤？",
    s: "《在狱咏蝉》是骆宾王被诬下狱时所作，以蝉自喻，“无人信高洁，谁为表予心”表达了诗人品行高洁却不被理解的悲愤。全诗托物言志，情感深沉，是初唐咏物诗的代表作。"
  },
  "代悲白头吟|刘希夷": {
    y: "洛阳城东的桃花李花，飘来飘去落在谁家？\n洛阳女子有着美丽的容颜，坐在落花边长声叹息。\n今年花谢了容颜也改了，明年花开时还有谁在呢？\n已经看见松柏被摧折为柴薪，又听说桑田变成了大海。\n古人不再到洛城东了，今人还对着落花的春风。\n年年岁岁花还是相似的，岁岁年年人却不同了。",
    s: "《代悲白头翁》是刘希夷的代表作，“年年岁岁花相似，岁岁年年人不同”是千古传诵的名句，也是抖音上极火的诗句，道尽了时光流逝、物是人非的感慨。全诗以落花起兴，抒发了对青春易逝、人生无常的感叹，是初唐七言歌行的杰作。"
  },
  "渡汉江|宋之问": {
    y: "客居岭外与家里音信断绝，经过了一个冬天又到了春天。\n离故乡越近心中越胆怯，不敢询问从家那边过来的人。",
    s: "《渡汉江》是宋之问从泷州贬所逃归洛阳时所作，“近乡情更怯，不敢问来人”是千古传诵的名句，将游子归乡时的复杂心理写得入木三分。全诗仅二十字，却将思乡之情写得真挚深沉，是唐诗五绝的精品。"
  },
  "杂诗三首·二|王维": {
    y: "您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？",
    s: "《杂诗》是王维的名作，以询问故乡窗前梅花是否开花的细节，表达了对故乡的深切思念。“来日绮窗前，寒梅著花未”以小见大，将思乡之情写得含蓄深沉。全诗语言朴素，情感真挚，是唐诗五绝的精品。"
  },
  "相思|王维": {
    y: "红豆生长在阳光明媚的南方，每逢春天不知长多少新枝。\n希望思念的人儿多多采集，小小红豆引人相思。",
    s: "《相思》是王维的名作，“红豆生南国，春来发几枝”以红豆寄托相思之情，“愿君多采撷，此物最相思”将红豆作为爱情的象征，成为千古传诵的爱情名句。全诗语言朴素，情感真挚，是唐诗中最著名的爱情诗之一。"
  },
  "辋川集·竹里馆|王维": {
    y: "独自闲坐在幽静竹林，一边弹琴一边高歌长啸。\n深深的山林中无人知晓，只有一轮明月静静与我相伴。",
    s: "《竹里馆》是王维《辋川集》中的名篇，描写了隐居竹林的悠闲生活。“独坐幽篁里，弹琴复长啸”写出了诗人的孤高自赏，“深林人不知，明月来相照”以明月为伴，表达了诗人超然物外的心境。全诗意境清幽，充满禅意。"
  },
  "送别|王维": {
    y: "请你下马来喝一杯酒，敢问朋友你要去往哪里？\n你说因为生活不得意，要归隐在终南山边。\n只管去吧我不再多问，那白云没有穷尽的时候。",
    s: "《送别》是王维的名作，“但去莫复问，白云无尽时”以白云无尽比喻归隐生活的自在，表达了对友人归隐的理解和祝福。全诗语言朴素，意境悠远，是唐诗五绝的精品。"
  },
  "青谿|王维": {
    y: "进入黄花川游览，每每都去追逐那条青溪。\n溪水随着山势，百转千回，经过的路途，却不足百里。\n水声在山间乱石中喧嚣，水色在深密的松林里幽静。\n清澈的溪水漾起菱荇，澄明的水面倒映着芦苇。\n我的心一向闲静，清澈的溪水也如此淡泊。\n就让我留在这盘石上，垂钓终老吧。",
    s: "《青溪》是王维山水诗的代表作，“声喧乱石中，色静深松里”以动衬静，写出了青溪的幽静之美。全诗以青溪的淡泊比喻自己的心境，表达了对隐居生活的向往，是王维山水诗的佳作。"
  },
  "渭川田家|王维": {
    y: "夕阳的余晖洒向村庄，牛羊沿着深巷纷纷回归。\n老叟惦念着放牧的孙儿，柱杖等候在自家的柴扉。\n雉鸡鸣叫麦儿即将抽穗，蚕儿成眠桑叶已经薄稀。\n农夫们荷锄回到了村里，相见欢声笑语恋恋依依。\n如此安逸怎不叫我羡慕？我不禁怅然地吟起《式微》。",
    s: "《渭川田家》是王维田园诗的代表作，描写了夕阳西下时农村的宁静景象。“斜光照墟落，穷巷牛羊归”写出了乡村的温馨，“即此羡闲逸，怅然吟式微”表达了对田园生活的向往。全诗意境优美，充满生活气息。"
  },
  "终南山|王维": {
    y: "巍巍的终南山高入云霄，与天帝的住所临近。山峦连绵不断，一直延伸到海边。\n回望山间白云，茫茫一片，走进山中，青霭却又看不见了。\n中峰两侧，分野不同，群山沟壑中，阴晴各异。\n想要找个有人烟的地方投宿，隔着溪水询问樵夫。",
    s: "《终南山》是王维山水诗的代表作，“白云回望合，青霭入看无”以传神的笔墨写出了终南山云雾变幻的奇妙景象。全诗气势雄浑，意境开阔，是王维山水诗的杰作。"
  },
  "汉江临泛|王维": {
    y: "汉江流经楚塞又折入三湘，西起荆门往东与九江相通。\n江水滔滔远去，好像一直涌流到天地之外，两岸山色时隐时现，若有若无。\n远处的城郭好像在水面上飘动，波翻浪涌，辽远的天空也仿佛为之摇荡。\n襄阳的风景天气好，我愿在此地酣饮陪伴山翁。",
    s: "《汉江临泛》是王维山水诗的代表作，“江流天地外，山色有无中”以极简练的笔墨写出了汉江的辽阔和山色的朦胧，是千古传诵的写景名句。全诗意境开阔，气势雄浑，是王维山水诗的杰作。"
  },
  "观猎|王维": {
    y: "狂风声里，角弓鸣响，将军狩猎在渭城。\n秋草枯黄，鹰眼更加锐利；冰雪消融，马蹄格外轻快。\n转眼已过新丰市，不久又回细柳营。\n回头远眺射雕的地方，千里暮云，一片平展。",
    s: "《观猎》是王维描写将军打猎的名作，“草枯鹰眼疾，雪尽马蹄轻”以工整的对仗写出了打猎时的紧张与轻快，“回看射雕处，千里暮云平”以景结情，余味无穷。全诗节奏明快，气势雄浑，是王维边塞诗的佳作。"
  },
  "桃源行|王维": {
    y: "渔舟顺着溪水，贪恋山中春色，两岸桃花夹着古老的渡口。\n坐着看红树，不知走了多远，走完青溪，却不见人。\n从山口悄悄进去，开始曲折幽深，山一开，视野开阔，忽然出现平原。\n远远看见一处云树聚集，走近是千家散居在花竹之间。\n樵夫刚传汉代的姓名，居民还没改秦代的衣服。\n居民一起住在武陵源，还从尘世之外建起田园。\n月照松下，房栊寂静，日出云中，鸡犬喧闹。\n惊讶地听说有俗客来，争着聚集，竞相引回家问都城情况。\n清晨街巷扫花开门，傍晚渔樵乘水归来。\n当初因避乱离开人间，到成仙就不再回去。\n峡谷里谁知有人事，世上遥望空见云山。\n不怀疑灵境难以见到，尘心未尽思念家乡。\n出洞后无论隔山隔水，辞家终打算长久漫游。\n自以为经过旧路不会迷路，哪知峰壑如今已变。\n当时只记得入山很深，青溪几度到云林。\n春天来遍是桃花水，辨不清仙源何处寻。",
    s: "《桃源行》是王维根据陶渊明《桃花源记》改写的七言歌行，“春来遍是桃花水，不辨仙源何处寻”写出了桃花源的神秘与不可寻觅。全诗将散文的叙事转化为诗歌的意境，语言优美，意境悠远，是王维七言古诗的代表作。"
  },
  "老将行|王维": {
    y: "当年十五二十岁青春之时，徒步就能夺得胡人战马骑。\n年轻力壮射杀山中白额虎，数英雄岂止邺下的黄须儿。\n身经百战驰骋疆场三千里，曾以一剑抵当百万雄师。\n汉军声势迅猛如惊雷霹雳，虏骑互相践踏是怕遇蒺藜。\n卫青不败是由于天神辅助，李广无功却缘于命运不济。\n自被摈弃不用便开始衰朽，世事随时光流逝人成白首。\n当年百步穿杨箭无虚发，如今臂病不能拉弓。\n像故侯邵平在路旁卖瓜，像陶渊明门前学种五柳。\n苍茫的古树连接着偏僻的里巷，冷落的寒山对着空窗。\n发誓要像耿恭那样让疏勒城飞出泉水，不愿像灌夫那样只会借酒使气。\n贺兰山下军阵如云，紧急的军书日夜不断传来。\n使臣到三河招募少年，皇帝下诏书五路派出将军。\n试拂铁衣如雪色，且持宝剑闪动星文。\n愿得燕地强弓射杀敌军大将，耻于让越甲惊动我君。\n不要嫌旧日云中太守魏尚年老，还能一战建立功勋。",
    s: "《老将行》是王维的名作，抖音上“杀气诗词”榜单中常引用此诗。全诗描写了一位老将从少年英勇到年老被弃，再到重新上阵的故事，“一身转战三千里，一剑曾当百万师”气势磅礴，“莫嫌旧日云中守，犹堪一战取功勋”表达了老当益壮的豪情。全诗叙事曲折，情感深沉，是王维七言古诗的杰作。"
  },
  "洛阳女儿行|王维": {
    y: "洛阳有一位女子住在我对门，年龄才十五六岁，容貌美丽。\n丈夫骑着玉勒装饰的青白马，侍女用金端着切细的鲤鱼。\n画阁朱楼处处相望，红桃绿柳垂在屋檐下。\n罗帷送上七香车，宝扇迎回九华帐。\n丈夫青春年少又富贵，意气骄奢超过石崇。\n亲自教碧玉般的爱妾跳舞，不惜把珊瑚树拿给人打碎。\n春窗天亮才灭九微灯，九微灯的碎片飞落在花格窗上。\n嬉戏完了没有练习曲子的时候，梳妆好了只是熏香坐着。\n城中相识的都是富贵人家，日夜经过赵李等豪门。\n谁可怜越地女子颜如玉，贫贱时只能在江边自己浣纱。",
    s: "《洛阳女儿行》是王维的名作，描写了洛阳豪门贵妇的奢华生活，结尾以“谁怜越女颜如玉，贫贱江头自浣纱”对比，表达了对贫富不均的感慨。全诗辞藻华丽，对比鲜明，是王维七言古诗的代表作。"
  },
  "秋夜曲|王涯": {
    y: "月亮初升时秋露已经稀薄，丝罗衣已单薄却还没有更换。\n夜深了还在殷勤地拨弄银筝，心里害怕空房冷清而不忍回去。",
    s: "《秋夜曲》是王维的闺怨诗，“桂魄初生秋露微”写秋夜的清冷，“心怯空房不忍归”写女子的孤独与思念。全诗意境凄清，情感细腻，是王维七绝中的佳作。"
  },
  "哭晁卿衡|李白": {
    y: "日本友人晁衡卿辞别长安帝都，乘船扬帆绕过蓬莱群岛。\n明月一样的人儿不归，沉入碧海，白云带着愁色笼罩着苍梧山。",
    s: "《哭晁卿衡》是李白为日本遣唐使阿倍仲麻吕（晁衡）所作的悼诗，“明月不归沉碧海，白云愁色满苍梧”以明月沉海比喻晁衡的遇难，以白云愁色表达悲痛。全诗情感真挚，是中日文化交流史上的重要诗篇。"
  },
  "春思|李白": {
    y: "燕地小草像碧丝般青绿，秦地的桑树已叶翠枝绿。\n当你怀念家园盼归之日，我早就因思念你而愁肠百结。\n春风啊你与我素不相识，为何吹进罗帏撩动我的愁思？",
    s: "《春思》是李白的闺怨诗，“燕草如碧丝，秦桑低绿枝”以两地春景对比，“当君怀归日，是妾断肠时”将思妇的思念写得真挚动人，“春风不相识，何事入罗帏”以反问作结，含蓄深沉。全诗语言优美，情感细腻。"
  },
  "月下独酌四首·一|李白": {
    y: "在花丛中摆上一壶美酒，我自斟自饮，身边没有一个亲友。\n举杯向天，邀请明月，与我的影子相对，便成了三人。\n明月既不能理解开怀畅饮之乐，影子也只能默默地跟随在我的左右。\n暂且以明月和影子作伴吧，要趁春宵及时行乐。\n我吟诵诗篇，月亮伴随我徘徊，我手舞足蹈，影子便随之零乱。\n醒时一起欢乐，醉后各自分散。\n我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。",
    s: "《月下独酌》是李白的代表作，“举杯邀明月，对影成三人”是千古传诵的名句，以奇特的想象将孤独写得浪漫而旷达。全诗描写了诗人在月夜独自饮酒的情景，表达了孤独寂寞却又超然物外的心境，是李白浪漫主义诗风的典型体现。"
  },
  "子夜吴歌·秋歌|李白": {
    y: "长安城内一片月光，千户万户都在捣衣。\n秋风吹送捣衣声声，家家怀念戍边之人。\n何时才能平息边境战争，让我丈夫结束远征。",
    s: "《子夜吴歌·秋歌》是李白的名作，“长安一片月，万户捣衣声”以极简练的笔墨勾勒出长安月夜捣衣的场景，“何日平胡虏，良人罢远征”表达了思妇对和平的渴望。全诗意境优美，情感真挚，是李白乐府诗的代表作。"
  },
  "关山月|李白": {
    y: "一轮明月从祁连山升起，穿行在苍茫云海之间。\n浩荡的长风吹越几万里，吹过将士驻守的玉门关。\n当年汉兵直指白登山道，吐蕃觊觎青海大片河山。\n这里就是历代征战之地，出征将士很少能够生还。\n戍守兵士远望边城景象，思归家乡不禁满面愁容。\n此时将士的妻子在高楼，哀叹何时能见远方亲人。",
    s: "《关山月》是李白的边塞诗名作，“明月出天山，苍茫云海间。长风几万里，吹度玉门关”气势雄浑，写出了边塞的辽阔与苍凉。全诗将征人的思乡与思妇的思念结合，意境苍茫，情感深沉，是李白边塞诗的代表作。"
  },
  "长干行二首·一|李白": {
    y: "我的头发刚刚盖过额头，便同你在门前做折花的游戏。\n你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。\n我们同在长干里居住，两个人从小都没什么猜忌。\n十四岁时嫁给你作妻子，害羞得没有露出过笑脸。\n低着头对着墙壁的暗处，一再呼唤也不敢回头。\n十五岁才舒展眉头，愿意永远和你在一起。\n常抱着至死不渝的信念，怎么能想到会走上望夫台。\n十六岁时你离家远行，要去瞿塘峡滟滪堆。\n五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。\n门前是你离家时徘徊的足迹，渐渐地长满了绿苔。\n绿苔太厚，不好清扫，树叶飘落，秋天早早来到。\n八月里，黄色的蝴蝶飞舞，双双飞到西园草地上。\n看到这种情景我很伤心，因而忧愁容颜衰老。\n无论什么时候你想下三巴回家，请预先把家书捎给我。\n迎接你不怕道路遥远，一直走到长风沙。",
    s: "《长干行》是李白的乐府诗名作，“郎骑竹马来，绕床弄青梅”是“青梅竹马”成语的来源，描写了一对男女从小一起长大、结婚后又离别的故事。全诗以女子的口吻，将爱情的纯真与离别的思念写得真挚动人，是李白乐府诗的代表作。"
  },
  "宣州谢朓楼饯别校书叔云|李白": {
    y: "弃我而去的昨天，早已不可挽留；\n乱我心绪的今天，使人无限烦忧。\n万里长风吹送鸿雁，面对此景可以在高楼上畅饮。\n你的文章有建安风骨，又有谢朓那样的清新秀发。\n我们都满怀豪情逸兴，飞跃的神思像要腾空而上，去摘取那皎洁的明月。\n抽刀切断江水，江水却流得更急，举杯想要消愁，愁绪却更加浓重。\n人生在世不能称心如意，不如明天披散头发，驾舟归隐江湖。",
    s: "《宣州谢朓楼饯别校书叔云》是李白的名作，“抽刀断水水更流，举杯消愁愁更愁”是千古传诵的名句，以奇特的比喻写出了愁绪的难以排遣。全诗情感跌宕，从“弃我去者”的苦闷到“欲上青天揽明月”的豪情，再到“人生在世不称意”的旷达，是李白浪漫主义诗风的典型体现。"
  },
  "行路难三首·二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "荅王十二寒夜独酌有怀|李白": {
    y: "昨夜吴中下雪，你像王子猷那样兴起了佳兴。\n万里浮云卷绕着碧山，青天中流着一轮孤月。\n孤月沧浪，银河清澈，北斗错落，长庚明亮。\n你怀念我，对酒独酌，夜霜洁白，玉栏金井，冰棱峥嵘。\n人生飘忽不过百年，应当酣畅地抒发万古之情。\n你不能像那些斗鸡徒，用狸膏金距斗鸡，让鼻息吹到虹霓。\n你不能学哥舒翰，横行青海夜带刀，西屠石堡取紫袍。\n你在北窗下吟诗作赋，万言不值一杯水。\n世人听了都掉头而去，就像东风吹马耳一样。\n鱼目也笑我，说和明月一样。\n骅骝蜷缩不能吃食，跛驴得志在春风中鸣叫。\n《折杨》《黄华》迎合流俗，晋君听琴枉自清角。\n巴人谁肯和阳春，楚地从来轻视奇璞。\n黄金散尽交不成朋友，白首为儒身被轻视。\n一谈一笑就失颜色，苍蝇般的谗言喧嚣。\n曾参岂是杀人的人，谗言三次传到，慈母也受惊。\n与你论心握住你的手，荣辱对我又算什么。\n孔子还曾感伤凤麟不出，董龙更是何鸡狗。\n一生傲岸苦于不谐于世，恩宠疏远，媒人徒劳，志意多乖违。\n严陵对汉天子长揖不拜，何必长剑拄颐侍奉玉阶。\n显达也不足贵，穷困也不足悲。\n韩信羞与绛灌并列，祢衡耻于追逐屠沽之辈。\n你不见李北海，英风豪气如今何在。\n你不见裴尚书，土坟三尺长满蒿棘。\n少年时早就想去五湖隐居，见此更加疏远钟鼎。",
    s: "《答王十二寒夜独酌有怀》是李白的名作，全诗以寒夜独酌起兴，抒发了怀才不遇的愤懑和对现实的批判。“吟诗作赋北窗里，万言不直一杯水”道尽了文人的辛酸，“达亦不足贵，穷亦不足悲”表达了旷达的人生态度。全诗气势磅礴，情感深沉，是李白七言古诗的杰作。"
  },
  "庐山谣寄卢侍御虚舟|李白": {
    y: "我本是像楚狂接舆那样的人，唱着凤歌嘲笑孔丘。\n手里拿着绿玉杖，早晨告别黄鹤楼。\n为了寻仙，走遍五岳也不嫌远，一生就喜欢游名山。\n庐山秀丽，高耸在南斗星旁，九叠屏风像云锦张开。\n山影落在明湖上，泛着青黛的光，金阙前两座山峰耸立，银河倒挂在三石梁上。\n香炉峰瀑布遥遥相望，山崖曲折，层峦叠嶂，直上苍天。\n翠影红霞映着朝阳，鸟儿飞不过这吴地的长天。\n登高壮观天地，大江茫茫一去不还。\n黄云万里，风云变色，九道白波奔流，像雪山一样。\n喜欢作庐山谣，诗兴因庐山而发。\n闲时照石镜，清净我心，谢灵运走过的地方，已长满苍苔。\n早已服了还丹，没有世俗之情，琴心三叠，道初步修成。\n远远看见仙人在彩云里，手把芙蓉朝玉京而去。\n先约定在九天之上漫游，愿接卢敖同游太清。",
    s: "《庐山谣寄卢侍御虚舟》是李白的名作，“我本楚狂人，凤歌笑孔丘”开篇便展现了诗人狂放不羁的性格，“五岳寻仙不辞远，一生好入名山游”写出了诗人对名山大川的热爱。全诗描写了庐山的壮丽景色，表达了求仙学道的愿望，气势磅礴，想象奇绝，是李白七言古诗的代表作。"
  },
  "金陵酒肆留别|李白": {
    y: "春风吹起柳絮，酒店满屋飘香，侍女捧出美酒，劝我细细品尝。\n金陵年轻朋友，纷纷赶来相送，欲走还留之间，各自畅饮。\n请你问问东流的江水，我们的离情别意，和它相比谁短谁长？",
    s: "《金陵酒肆留别》是李白离金陵时所作，“请君试问东流水，别意与之谁短长”以流水比喻离情，将抽象的情感写得具体可感。全诗语言明快，情感真挚，是李白七绝中的佳作。"
  },
  "听蜀僧濬弹琴|李白": {
    y: "蜀僧濬怀抱着绿绮琴，从西面的峨眉峰上下来。\n为我挥手弹奏一曲，好像听到万壑松涛。\n我的心像被流水洗涤，余响融入霜钟。\n不知不觉碧山已暮色苍茫，秋云暗淡了几重。",
    s: "《听蜀僧濬弹琴》是李白描写音乐的名作，“为我一挥手，如听万壑松”以万壑松涛比喻琴声，写出了琴声的雄浑。全诗将琴声与自然景色融为一体，意境悠远，是李白五言律诗的佳作。"
  },
  "夜泊牛渚怀古|李白": {
    y: "秋夜行舟停泊在西江牛渚山，天空湛蓝湛蓝没有一丝游云。\n我登上小船仰望明朗的秋月，徒然地怀想起东晋谢尚将军。\n我也能够吟哦袁宏的咏史诗，可惜没有那识贤的将军倾听。\n明早我将挂起船帆离开牛渚，这里只有满天枫叶飘落纷纷。",
    s: "《夜泊牛渚怀古》是李白的名作，借袁宏被谢尚赏识的典故，抒发了怀才不遇的感慨。“余亦能高咏，斯人不可闻”将自己的才能与不遇对比，含蓄深沉。全诗意境清远，情感真挚，是李白五言律诗的佳作。"
  },
  "玉阶怨|李白": {
    y: "玉石砌的台阶上生起了露水，深夜独立很久，露水浸湿了罗袜。\n回房放下水晶帘，仍然隔着帘子望着玲珑的秋月。",
    s: "《玉阶怨》是李白的宫怨诗，全诗无一“怨”字，却处处含怨。“玉阶生白露，夜久侵罗袜”写宫女久立等待，“却下水晶帘，玲珑望秋月”写回房后仍望月难眠。全诗意境凄清，含蓄深沉，是唐诗五绝的精品。"
  },
  "怨情|李白": {
    y: "美人卷起珠帘，深深坐着，眉头紧锁。\n只见泪痕湿了面颊，不知她心里在恨谁。",
    s: "《怨情》是李白的闺怨诗，“但见泪痕湿，不知心恨谁”以问语作结，将女子的幽怨写得含蓄深沉。全诗仅二十字，却将美人的哀怨写得生动传神，是唐诗五绝的精品。"
  },
  "赠孟浩然|李白": {
    y: "我敬重孟先生的庄重潇洒，他的高尚品格天下闻名。\n少年时就鄙弃官职，晚年隐居在山林。\n月夜常常醉酒，迷恋花草不侍奉君王。\n高山似的品格怎么能仰望呢，只能在此拜揖他的清美芬芳。",
    s: "《赠孟浩然》是李白写给孟浩然的赠诗，“吾爱孟夫子，风流天下闻”开篇便表达了对孟浩然的敬仰，“红颜弃轩冕，白首卧松云”概括了孟浩然的一生。全诗语言朴素，情感真挚，是李白五言律诗的代表作。"
  },
  "渡荆门送别|李白": {
    y: "我乘舟渡江来到遥远的荆门外，来到战国时期楚国的境内游览。\n山随着低平的原野地出现逐渐消失，江水在一望无际的原野中奔流。\n江面月影好似天上飞来的明镜，云层缔构城外幻出海市蜃楼。\n我依然怜爱这来自故乡之水，不远万里来送我东行的小舟。",
    s: "《渡荆门送别》是李白出蜀时所作，“山随平野尽，江入大荒流”写出了荆门一带的壮阔景象，“仍怜故乡水，万里送行舟”将故乡水拟人化，表达了对故乡的眷恋。全诗意境开阔，情感真挚，是李白五言律诗的代表作。"
  },
  "送友人|李白": {
    y: "青翠的山峦横卧在城墙的北面，波光粼粼的流水围绕着城的东边。\n在此地我们相互道别，你就像孤蓬那样随风飘荡，到万里之外远行去了。\n浮云像游子一样行踪不定，夕阳徐徐下山，似乎有所留恋。\n频频挥手作别从此离去，马儿也为惜别声声嘶鸣。",
    s: "《送友人》是李白的送别诗名作，“浮云游子意，落日故人情”以浮云比喻游子，以落日比喻故人之情，对仗工整，意境优美。全诗情景交融，将送别之情写得含蓄深沉，是李白五言律诗的代表作。"
  },
  "秋浦歌十七首·十四|李白": {
    y: "炉火熊熊燃烧，红星四溅，紫烟蒸腾，广袤的天地被红彤彤的炉火照得通明。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。",
    s: "《秋浦歌·其十四》是李白描写冶炼工人劳动的诗篇，“炉火照天地，红星乱紫烟”写出了冶炼场面的壮观，“赧郎明月夜，歌曲动寒川”写出了工人的乐观精神。全诗色彩浓烈，充满生活气息，是中国古代诗歌中少有的描写工人劳动的作品。"
  },
  "陪侍郎叔游洞庭醉后三首·三|李白": {
    y: "把君山削去才好，让湘水平铺流淌。\n巴陵有无限的美酒，醉倒在洞庭秋色中。",
    s: "《陪侍郎叔游洞庭醉后》是李白的名作，“刬却君山好，平铺湘水流”以奇特的想象，想要铲平君山让湘水平铺，展现了诗人豪放不羁的性格。全诗想象奇绝，气势磅礴，是李白七绝中的佳作。"
  },
  "与夏十二登岳阳楼|李白": {
    y: "登上岳阳楼，远望岳阳城尽收眼底，江水辽远，洞庭湖开阔。\n大雁引走了我的愁心，月亮从山后升起，带来了好月。\n在云间下榻，在天上举杯。\n醉后凉风四起，吹得人衣袖飞舞。",
    s: "《与夏十二登岳阳楼》是李白登岳阳楼时所作，“雁引愁心去，山衔好月来”以拟人手法写雁和山，将愁心被带走、好月被送来的情景写得生动有趣。全诗意境开阔，情调欢快，是李白五言律诗的佳作。"
  },
  "峨眉山月歌|李白": {
    y: "半轮明月高高悬挂在峨眉山前，青衣江澄澈的水面倒映着月影。\n夜间乘船出发，离开清溪直奔三峡。想你却难相见，只能依依不舍顺江去向渝州。",
    s: "《峨眉山月歌》是李白出蜀时所作，全诗连用了峨眉山、平羌江、清溪、三峡、渝州五个地名，却毫无堆砌之感，“峨眉山月半轮秋，影入平羌江水流”写出了月映清江的美景。全诗意境优美，语言流畅，是李白七绝中的佳作。"
  },
  "春夜洛城闻笛|李白": {
    y: "这是从谁家飘出的悠扬笛声呢？它随着春风飘扬，传遍洛阳全城。\n就在客居的今夜，听到《折杨柳》的曲调，谁能不生出怀恋故乡的深情？",
    s: "《春夜洛城闻笛》是李白客居洛阳时所作，“此夜曲中闻折柳，何人不起故园情”以《折杨柳》曲触发思乡之情，将游子的思乡写得真挚动人。全诗意境优美，情感深沉，是李白七绝中的佳作。"
  },
  "清平调·一|李白": {
    y: "见到云就联想到她华艳的衣裳，见到花就联想到她艳丽的容貌；春风吹拂栏杆，露珠润泽花色更浓。\n如此天姿国色，不是群玉山头所见的飘飘仙子，就是瑶台殿前月光照耀下的神女。",
    s: "《清平调·其一》是李白为杨贵妃所作，“云想衣裳花想容，春风拂槛露华浓”以云喻衣，以花喻容，将杨贵妃的美貌写得如梦如幻。全诗想象奇绝，辞藻华丽，是李白七绝中的佳作，也是抖音上极火的诗词。"
  },
  "清平调·二|李白": {
    y: "像一枝红艳的牡丹，带着露水凝聚着芳香，楚王为巫山神女枉自断肠。\n请问汉宫之中谁能与她相比？可怜那赵飞燕还要依靠新妆才能比得上。",
    s: "《清平调·其二》以牡丹喻杨贵妃，“一枝红艳露凝香”写出了杨贵妃的美艳，“借问汉宫谁得似，可怜飞燕倚新妆”以赵飞燕衬托杨贵妃的美貌。全诗辞藻华丽，想象丰富，是李白七绝中的佳作。"
  },
  "清平调·三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "兵车行|杜甫": {
    y: "大路上车轮滚滚，战马嘶叫，出征的青年弓箭挂在腰间。\n爹娘妻子儿女奔跑来相送，行军时扬起的尘土遮天蔽日以致看不见咸阳桥。\n拦在路上牵着士兵衣服顿脚哭，哭声直上天空冲入云霄。\n路旁经过的人问出征士兵怎么样，出征士兵只是说按名册征兵很频繁。\n有的人十五岁到黄河以北去戍守，纵然到了四十岁还要到西部边疆去屯田。\n到里长那里用头巾把头发束起来，他们回时已经白头还要去守边疆。\n边疆无数士兵流血形成了海水，武皇开拓边疆的念头还没停止。\n您没听说汉家华山以东两百州，百千村落长满了草木。\n即使有健壮的妇女手拿锄犁耕种，田土里的庄稼也长得没有东西行列。\n更何况秦地的士兵又能够苦战，被驱使去作战与鸡狗没有分别。\n尽管长辈有疑问，服役的人们怎敢申诉怨恨？\n就像今年冬天，还没有停止征调函谷关以西的士兵。\n县官紧急地催逼百姓交租税，租税从哪里出？\n如果确实知道生男孩是坏事情，反而不如生女孩好。\n生下女孩还能够嫁给近邻，生下男孩死于沙场埋没在荒草间。\n您没有看见，青海的边上，自古以来战死士兵的白骨没人掩埋。\n新鬼烦恼地怨恨旧鬼哭泣，天阴雨湿时众鬼啾啾地喊叫。",
    s: "《兵车行》是杜甫的代表作，“边庭流血成海水，武皇开边意未已”以强烈的对比，揭露了唐玄宗穷兵黩武的罪恶。“生女犹得嫁比邻，生男埋没随百草”一反传统重男轻女的观念，道尽了战争给人民带来的苦难。全诗叙事与抒情结合，情感深沉，是杜甫新乐府诗的杰作。"
  },
  "丽人行|杜甫": {
    y: "三月三日阳春时节天气清新，长安曲江河畔聚集好多美人。\n姿态凝重神情高远文静自然，肌肤丰润胖瘦适中身材匀称。\n绫花绫罗衣裳映衬暮春风光，金丝绣的孔雀银丝刺的麒麟。\n头上戴的是什么珠宝首饰呢？翡翠玉做的花饰垂挂在两鬓。\n在她们的背后能看见什么呢？珠宝镶嵌的裙腰多稳当合身。\n其中有几位都是后妃的亲戚，她们有虢国夫人和秦国夫人的封号。\n翡翠蒸锅端出香喷的紫驼峰，水晶圆盘送来肥美的白鱼鲜。\n她们捏着犀角筷子久久不动，厨师们快刀细切空忙了一场。\n宦官骑马飞驰不敢扬起灰尘，御厨络绎不绝送来海味山珍。\n笙箫鼓乐缠绵宛转感动鬼神，宾客随从满座都是达官贵人。\n有一个骑马官人是何等骄横，车前下马从绣毯上走进帐门。\n白雪似的杨花飘落覆盖浮萍，青鸟飞去衔起地上的红丝帕。\n杨家气焰很高权势无与伦比，切勿近前以免丞相发怒斥人。",
    s: "《丽人行》是杜甫的代表作，通过描写杨贵妃姐妹曲江游宴的奢华场面，讽刺了杨氏家族的骄奢淫逸。“炙手可热势绝伦，慎莫近前丞相嗔”以冷峻的笔调写出了杨国忠的权势。全诗铺陈细腻，讽刺深刻，是杜甫新乐府诗的杰作。"
  },
  "哀江头|杜甫": {
    y: "少陵野老强忍悲痛，吞声哭泣，春日里偷偷走到曲江的角落。\n江头的宫殿千门紧锁，细柳新蒲为谁而绿？\n回忆当年皇帝的旌旗来到南苑，苑中万物都增添了光彩。\n昭阳殿里的第一人杨贵妃，与皇帝同车随侍在皇帝身边。\n车辇前的才人带着弓箭，白马咬着黄金的马勒。\n翻身向天仰射云中的飞鸟，一笑之间正射下双飞的鸟。\n明眸皓齿如今在哪里？血污的游魂归不得。\n清渭东流，剑阁深远，死去的和活着的彼此都没有消息。\n人生有情，泪水沾湿了胸襟，江水江花哪里有尽头！\n黄昏时胡骑的尘土满城，想要往城南去，却望着城北。",
    s: "《哀江头》是杜甫在安史之乱中所作，“明眸皓齿今何在？血污游魂归不得”以杨贵妃的惨死，写出了安史之乱的悲剧。全诗将对往昔繁华的回忆与今日的荒凉对比，情感深沉，是杜甫七言古诗的代表作。"
  },
  "登楼|杜甫": {
    y: "登楼望春近看繁花游子越发伤心，万方多难愁思满腹我来此处登临。\n锦江的春色从天地边际迎面扑来，玉垒山的浮云变幻莫测从古到今。\n大唐的朝廷真像北极星不可动摇，吐蕃夷狄莫再前来骚扰徒劳入侵。\n可叹刘后主那么昏庸还立庙祠祀，日暮时分我要学孔明聊作梁甫吟。",
    s: "《登楼》是杜甫的代表作，“锦江春色来天地，玉垒浮云变古今”以壮阔的景色写出了历史的沧桑，“北极朝廷终不改，西山寇盗莫相侵”表达了对国家命运的关切。全诗意境开阔，情感深沉，是杜甫七律的杰作，叶梦得称此诗“气象雄盖宇宙”。"
  },
  "客至|杜甫": {
    y: "草堂的南北绿水缭绕、春意荡漾，只见一群群鸥鸟日日结队飞来。\n长满花草的庭院小路没有因为迎客而打扫，只是为了你的到来，我家草门首次打开。\n离集市太远盘中没好菜肴，家境贫寒只有陈酒浊酒招待。\n如肯与邻家老翁举杯一起对饮，那我就隔着篱笆将他唤来，一起喝尽这余下的几杯。",
    s: "《客至》是杜甫在成都草堂时所作，“花径不曾缘客扫，蓬门今始为君开”以朴素的语言写出了对客人的热情欢迎。全诗充满生活气息，情感真挚，是杜甫七律中少有的轻快之作。"
  },
  "咏怀古迹五首·三|杜甫": {
    y: "成千上万的山峦山谷连绵不断，如向荆门奔去一般，王昭君生长的山村还至今留存。\n从紫台一去直通向塞外沙漠，最后只留荒郊上的一座孤坟对着黄昏。\n糊涂的君王只依凭画图识别昭君的容颜，月夜里环佩叮当是昭君归魂。\n千载流传她作的胡音琵琶曲，曲中倾诉的分明是满腔悲愤。",
    s: "《咏怀古迹·其三》是杜甫咏怀王昭君的名作，“一去紫台连朔漠，独留青冢向黄昏”以工整的对仗写出了昭君出塞的悲剧，“千载琵琶作胡语，分明怨恨曲中论”将昭君的怨恨写得深沉感人。全诗意境苍凉，情感真挚，是杜甫七律的代表作。"
  },
  "阁夜|杜甫": {
    y: "岁末时节白天的时间就越来越短，夔州霜雪停了的寒冬夜晚，雪光映照下，明朗如昼。\n破晓时军营中鼓角声更显得悲壮凄凉，银河倒映江面，在湍急的三峡中摇曳，繁星随着波浪摇动。\n战乱的消息传来，千家万户的哭声响彻四野，好几个地方的渔民、樵夫唱起了夷歌。\n像诸葛亮和公孙述这样的历史人物，最终也成了黄土中的枯骨，人事与音书，都只能任其寂寞了。",
    s: "《阁夜》是杜甫在夔州时所作，“五更鼓角声悲壮，三峡星河影动摇”以壮阔的景色写出了战乱的悲凉，“卧龙跃马终黄土，人事音书漫寂寥”表达了对历史和人生的感慨。全诗意境苍凉，情感深沉，是杜甫七律的杰作。"
  },
  "又呈吴郎|杜甫": {
    y: "来堂前打枣我从不阻拦任随西邻，因为她是一个无食无儿的老妇人。\n若不是由于穷困怎会做这样的事？正因她心存恐惧反更该与她相亲。\n见你来就防着你虽然是多此一举，但你一来就插上篱笆却甚像是真。\n她说官府征租逼税已经一贫如洗，想起时局兵荒马乱不禁涕泪满巾。",
    s: "《又呈吴郎》是杜甫写给亲戚吴郎的诗，通过劝阻吴郎不要插篱笆阻止西邻老妇打枣，表达了对贫苦人民的深切同情。“不为困穷宁有此？只缘恐惧转须亲”道尽了穷人的辛酸。全诗语言朴素，情感真挚，体现了杜甫忧国忧民的情怀。"
  },
  "月夜|杜甫": {
    y: "今夜里鄜州上空那轮圆月，只有你在闺房中独自遥看。\n远在他方怜惜幼小的儿女，还不懂得你为何思念长安。\n蒙蒙雾气沾湿了你的鬓发，清冷的月光使你的玉臂生寒。\n什么时候才能在一起共同靠在透光的窗帘或帷幔旁，让月光擦干两人的思念的泪。",
    s: "《月夜》是杜甫在安史之乱中被困长安时所作，全词从对方落笔，想象妻子在鄜州独自望月思念自己的情景，“香雾云鬟湿，清辉玉臂寒”以细腻的笔触写出了妻子的深情。全诗构思巧妙，情感真挚，是杜甫五言律诗的佳作。"
  },
  "月夜忆舍弟|杜甫": {
    y: "戍楼上的更鼓声断绝了人行，秋夜的边塞传来了孤雁哀鸣。\n从今夜就进入了白露节气，月亮还是故乡的最明亮。\n虽有兄弟但都离散各去一方，已经无法打听到他们的消息。\n寄往洛阳城的家书老是不能送到，何况战乱频繁还没有停止。",
    s: "《月夜忆舍弟》是杜甫在安史之乱中所作，“露从今夜白，月是故乡明”是千古传诵的名句，将思乡之情写得真挚动人。全诗在战乱的背景下思念离散的兄弟，情感深沉，是杜甫五言律诗的佳作。"
  },
  "天末忆李白|杜甫": {
    y: "凉风飕飕从天边刮起，不知此时你心境怎样。\n鸿雁捎信什么时候才能到，江湖之上秋水浩渺风波多。\n有才华的人总是命途多舛，山精水怪喜欢人们经过。\n你应该与冤魂屈原共语，把诗投进汨罗江赠给他。",
    s: "《天末怀李白》是杜甫为李白被流放夜郎而作，“文章憎命达，魑魅喜人过”道尽了文人的命运多舛，“应共冤魂语，投诗赠汨罗”将李白与屈原相比，表达了对李白的深切同情。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "奉济驿重送严公四韵|杜甫": {
    y: "远送你从此分别，青山空自增添离情。\n什么时候能再把杯共饮，昨夜我们还在月光下同行。\n各郡的百姓都讴歌惋惜，你历事三朝出入荣耀。\n我独自回到江村的住处，寂寞地度过残生。",
    s: "《奉济驿重送严公四韵》是杜甫送别好友严武的诗作，“几时杯重把，昨夜月同行”将对友人的思念写得真挚动人，“江村独归处，寂寞养残生”表达了送别后的孤独。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "别房太尉墓|杜甫": {
    y: "我在他乡又要奔走，停下马告别你的孤坟。\n眼泪落下，近处的土都湿了，低空中有断云飘浮。\n当年像谢安那样陪你下棋，如今像季札那样把剑挂在你的墓前。\n只见林中的花飘落，黄莺的啼叫声像在为我送行。",
    s: "《别房太尉墓》是杜甫拜谒好友房琯墓时所作，“近泪无干土，低空有断云”以景衬情，将悲痛写得深沉感人，“对棋陪谢傅，把剑觅徐君”用典故表达了对友人的深情。全诗意境凄清，情感真挚，是杜甫五言律诗的佳作。"
  },
  "旅夜书怀|杜甫": {
    y: "微风吹拂着江岸的细草，那立着高高桅杆的小船在夜里孤零地停泊着。\n星星垂在天边，平野显得宽阔；月光随波涌动，大江滚滚东流。\n我难道是因为文章而著名吗？年老病多也应该休官了。\n自己到处漂泊像什么呢？就像天地间的一只孤零零的沙鸥。",
    s: "《旅夜书怀》是杜甫晚年漂泊时所作，“星垂平野阔，月涌大江流”以壮阔的景色反衬诗人的孤独，“飘飘何所似，天地一沙鸥”以沙鸥自喻，将漂泊无依的感慨写得深沉感人。全诗意境开阔，情感深沉，是杜甫五言律诗的杰作。"
  },
  "江南逢李龟年|杜甫": {
    y: "当年在岐王宅里，常常见到你的演出；在崔九堂前，也曾多次欣赏你的艺术。\n现在正好是江南风景秀美的时候，在这暮春季节再次遇见了你。",
    s: "《江南逢李龟年》是杜甫晚年在江南遇见著名乐师李龟年时所作，“正是江南好风景，落花时节又逢君”以乐景写哀情，将时代的沧桑和人生的感慨写得含蓄深沉。全诗仅二十八字，却蕴含了丰富的历史内容，是杜甫七绝的代表作。"
  },
  "绝句二首·一|杜甫": {
    y: "沐浴在春光下的江山显得格外秀丽，春风送来花草的芳香。\n泥土随着春天的来临而融化变得松软，燕子衔泥筑巢，暖和的沙子上睡着成双成对的鸳鸯。",
    s: "《绝句·迟日江山丽》是杜甫在成都草堂时所作，“泥融飞燕子，沙暖睡鸳鸯”以生动的细节写出了春日的生机和温馨。全诗色彩明丽，意境优美，是杜甫五言绝句的代表作。"
  },
  "八阵图|杜甫": {
    y: "三国鼎立你建立了盖世功绩，创八阵图你成就了永久声名。\n任凭江流冲击，石头却依然如故，千年遗恨，在于刘备失策想吞吴。",
    s: "《八阵图》是杜甫咏怀诸葛亮的名作，“功盖三分国，名成八阵图”以工整的对仗概括了诸葛亮的功绩，“江流石不转，遗恨失吞吴”表达了对诸葛亮壮志未酬的惋惜。全诗仅二十字，却蕴含了丰富的历史内容，是杜甫五言绝句的佳作。"
  },
  "相见欢·无言独上西楼|李煜": {
    y: "孤独的人默默无语，独自一人缓缓登上西楼。仰视天空，残月如钩。梧桐树寂寞地孤立院中，幽深的庭院被笼罩在清冷凄凉的秋色之中。\n那剪也剪不断，理也理不清，让人心乱如麻的，正是亡国之苦。这样的离异思念之愁，而今在心头上却又是另一般不同的滋味。",
    s: "《相见欢》是李煜亡国后的作品，“剪不断，理还乱，是离愁”以丝麻比喻离愁，将抽象的愁绪写得具体可感，“别是一般滋味在心头”则将亡国之痛写得难以言说。全词语言朴素，情感深沉，是李煜词的代表作。"
  },
  "虞美人·春花秋月何时了|李煜": {
    y: "春花秋月的美好时光什么时候结束的，以前的事情还记得多少！昨夜小楼上又吹来了春风，在这皓月当空的夜晚怎能忍受得了回忆故国的伤痛。\n精雕细刻的栏杆、玉石砌成的台阶应该都还在，只是所怀念的人已衰老。要问我心中有多少哀愁，就像那不尽的春江之水滚滚东流。",
    s: "《虞美人》是李煜的绝命词，也是他最著名的作品。“问君能有几多愁？恰似一江春水向东流”以春水比喻愁绪，将抽象的愁写得汪洋恣肆、无穷无尽，成为千古传诵的名句。全词将故国之思、亡国之痛写得淋漓尽致，是词史上最伟大的作品之一。"
  },
  "浪淘沙令·帘外雨潺潺|李煜": {
    y: "门帘外传来雨声潺潺，浓郁的春意又要凋残。即使身盖罗织的锦被也受不住五更时的冷寒。只有迷梦中忘掉自身是羁旅之客，才能享受片时的欢愉。\n不该独自一人登楼凭栏远望，引起对故国的无尽思念和感慨。离开容易再见故土就难了。流水带走落花，春光已经逝去，好景一去不返。今昔对比，一个是天上一个是人间。",
    s: "《浪淘沙令》是李煜亡国后的作品，“梦里不知身是客，一晌贪欢”以梦中的欢愉反衬现实的凄凉，“流水落花春去也，天上人间”将亡国之痛写得深沉绝望。全词语言自然，情感真挚，是李煜词的代表作。"
  },
  "菩萨蛮·一|温庭筠": {
    y: "眉妆漫染，额上的额黄半明半暗的闪耀，鬓边发丝飘过，洁白的香腮似雪。懒懒地无心去描弯弯的眉，迟了好久才起身梳理晨妆。\n插一朵花，前后都照镜子，看花朵与面容交相辉映。刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。",
    s: "《菩萨蛮》是温庭筠的代表作，也是花间词的典范。全词以细腻的笔触描写了一位女子晨起梳妆的过程，“小山重叠金明灭”写闺房陈设，“懒起画蛾眉，弄妆梳洗迟”写女子的慵懒情态，“双双金鹧鸪”以鹧鸪成双反衬女子的孤独，含蓄深婉，是花间词风的典型体现。"
  },
  "踏莎行|欧阳修": {
    y: "馆舍前的梅花已经凋残，溪桥旁新生细柳轻垂，春风踏芳草远行人跃马扬鞭。走得越远离愁越没有穷尽，就像那迢迢不断的春江之水。\n寸寸柔肠痛断，行行盈淌粉泪，不要登高楼望远把栏杆凭倚。平坦的草地尽头就是重重春山，行人还在那重重春山之外。",
    s: "《踏莎行》是欧阳修婉约词的代表作，“离愁渐远渐无穷，迢迢不断如春水”以春水比喻离愁，将抽象的愁绪写得具体可感，“平芜尽处是春山，行人更在春山外”以景结情，将思念写得悠远绵长。全词意境优美，情感细腻。"
  },
  "生查子|欧阳修": {
    y: "去年元宵节的时候，花市被灯光照的如同白昼。与佳人相约在黄昏之后、月上柳梢头之时同叙衷肠。\n今年正月十五元宵节，月光与灯光仍同去年一样。再也看不到去年的故人，相思之泪沾湿了春衫的衣袖。",
    s: "《生查子·元夕》通过去年与今年元宵的对比，抒发了物是人非的怅惘。“月上柳梢头，人约黄昏后”是千古传诵的名句，写出了恋人约会的温馨美好；“不见去年人，泪湿春衫袖”则写出了旧情难续的悲伤。全词语言朴素，情感真挚。"
  },
  "望海潮|柳永": {
    y: "杭州地处东南方，地理形势优越，风景优美，是三吴的都会，这里自古以来就十分繁华。雾气笼罩着的柳树、装饰华美的桥梁，挡风的帘子、青绿色的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的树木，围绕着钱塘江沙堤，汹涌的江水卷起雪白的浪花，天堑般的钱塘江一望无边。市场上陈列着珍宝，家家户户都存满了绫罗绸缎，争相比奢华。\n里湖、外湖与重重叠叠的山岭非常清秀美丽，有秋天的桂子，十里的荷花。晴天欢快地奏乐，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官，乘醉听吹箫击鼓，观赏、吟唱烟霞风光。他日画上美好景致，回京升官时向人们夸耀。",
    s: "《望海潮》是柳永描写杭州繁华景象的名作，“三秋桂子，十里荷花”以极简练的笔墨概括了杭州的美景，成为千古传诵的名句。全词铺叙了杭州的自然风光、市井繁华和百姓生活，是宋词中描写城市风貌的杰作，相传金主完颜亮读此词后，遂起投鞭渡江之志。"
  },
  "八声甘州|柳永": {
    y: "面对着潇潇暮雨从天空洒落在江面上，经过一番雨洗的秋景，分外寒凉清朗。凄凉的霜风一阵紧似一阵，关山江河一片冷清萧条，落日的余光照耀在高楼上。到处红花凋零翠叶枯落，一切美好的景物渐渐地衰残。只有那滔滔的长江水，不声不响地向东流淌。\n不忍心登高遥看远方，眺望渺茫遥远的故乡，渴求回家的心思难以收拢。叹息这些年来的行踪，为什么苦苦地长期停留在异乡？想着佳人正在华丽的楼上抬头凝望思念着我，多少次错把远处驶来的船当作心上人回家的船。她哪会知道我，倚着栏杆，愁思正如此的深重。",
    s: "《八声甘州》是柳永羁旅词的代表作，“渐霜风凄紧，关河冷落，残照当楼”被苏轼评为“不减唐人高处”。全词以萧瑟的秋景衬托游子的思乡之情，“想佳人妆楼颙望，误几回、天际识归舟”从对方落笔，将思念写得曲折深婉，是柳永慢词的杰作。"
  },
  "念奴娇|苏轼": {
    y: "大江浩浩荡荡向东流去，滔滔巨浪淘尽了千古以来的英雄人物。那旧营垒的西边，人们说就是三国时周瑜大破曹军的赤壁。陡峭的乱石直插云霄，汹涌的惊涛拍打着江岸，卷起千万堆白雪般的浪花。江山壮美如画，一时间涌现出多少英雄豪杰。\n遥想当年的周瑜，小乔刚刚嫁给他，英姿勃发，气度不凡。他手摇羽扇，头戴纶巾，谈笑之间，就把曹军的战船烧得灰飞烟灭。我今日神游古战场，应该笑我太多愁善感，早早地生出了白发。人生就像一场梦，且洒一杯酒，祭奠这江上的明月。",
    s: "《念奴娇·赤壁怀古》是豪放词的巅峰之作，也是苏轼最具代表性的作品。全词借赤壁怀古，写尽历史沧桑与人生旷达，气势雄浑，境界开阔。“大江东去”四字开篇，便奠定了全词磅礴的基调，是宋词中流传最广、影响力最大的作品之一。"
  },
  "水龙吟|苏轼": {
    y: "非常像花又好像不是花，无人怜惜任凭衰零坠地。它飘泊无家，傍路而行，仔细思量起来，看似无情，却自有愁思。萦绕牵挂，愁坏了柔肠，困倦得睁不开娇媚的眼睛，刚要睁开又闭上。梦中随风万里，去寻觅情郎的去处，却又被黄莺的啼叫声唤起。\n不恨杨花飘飞落尽，只恨西园里的落花难以再连缀。清晨一阵雨过后，杨花的踪迹何在？已化作一池碎萍。如果把春色分为三分，二分化为了尘土，一分付诸了流水。细细看来，那飘飞的不是杨花，点点都是离人的眼泪。",
    s: "《水龙吟·次韵章质夫杨花词》是苏轼咏物词的代表作，王国维称“东坡杨花词，和韵而似原唱”。“似花还似非花”抓住了杨花的特点，“细看来，不是杨花，点点是离人泪”以杨花比喻离人泪，将咏物与抒情融为一体，意境优美，情感深沉，是咏物词的千古绝唱。"
  },
  "卜算子|苏轼": {
    y: "弯弯的勾月悬挂在疏落的梧桐树上；夜阑人静，漏壶的水早已滴光了。有谁见到幽居的人独自往来，仿佛天边孤雁般缥缈的身影。\n突然惊起又回过头来，心有遗憾却无人知情。挑遍了寒枝也不肯栖息，甘愿在沙洲忍受寂寞凄冷。",
    s: "《卜算子》是苏轼被贬黄州时所作，以孤鸿自喻，“拣尽寒枝不肯栖，寂寞沙洲冷”表达了诗人虽身处逆境，却依然坚守高洁品格、不肯随波逐流的精神。全词意境幽冷，情感深沉，是苏轼婉约词的代表作。"
  },
  "鹊桥仙|秦观": {
    y: "纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。\n缱绻的柔情像流水般绵绵不断，重逢的约会如梦影般缥缈虚幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。",
    s: "《鹊桥仙》是秦观最著名的词作，借牛郎织女的神话故事，歌颂了坚贞不渝的爱情。“两情若是久长时，又岂在朝朝暮暮”一反传统七夕词的伤感，表达了爱情贵在长久、不在朝夕的独到见解，成为千古传诵的爱情名句。"
  },
  "踏莎行|秦观": {
    y: "暮霭沉沉，楼台消失在浓雾中，月色朦胧，渡口也隐没不见。望断了天涯，理想中的桃花源无处寻觅。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！\n远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你本来是环绕着郴山奔流，为什么偏偏要流到潇湘去呢？",
    s: "《踏莎行·郴州旅舍》是秦观被贬郴州时所作，“郴江幸自绕郴山，为谁流下潇湘去”以郴江绕郴山却又流向潇湘，比喻自己本想安居却被迫漂泊，含蓄深沉。苏轼极爱此两句，曾书于扇上。全词意境凄迷，情感深沉，是秦观词的代表作。"
  },
  "声声慢|李清照": {
    y: "苦苦地寻觅，却只落得冷冷清清，一派凄惨悲戚的景象。天气忽暖忽寒的时候，最难调养身体。喝两三杯淡酒，又怎么抵挡得住傍晚袭来的寒风？一行大雁从天上飞过，正让人伤心，却发现它们都是当年见过的旧相识。\n满地的黄花堆积零落，花儿都已经憔悴不堪，如今还有谁来采摘？守着窗子，独自一人，怎么挨到天黑？梧桐叶上滴着细雨，到了黄昏时分，还是点点滴滴下个不停。这般情景，怎么是一个“愁”字就能说得尽的！",
    s: "《声声慢》是李清照南渡之后的代表作，也是婉约词的千古绝唱。开篇七组叠词，一气呵成，将孤苦无依的心境渲染到极致。全词围绕一个“愁”字，从日常景物入手，层层递进，将国破家亡、身世飘零的沉痛写得入木三分，读来催人泪下。"
  },
  "武陵春|李清照": {
    y: "风停了，尘土里带有花的香气，花儿已凋落殆尽。日头已经升的老高，我却懒得来梳妆。景物依旧，人事已变，一切事情都已经完结。想要倾诉自己的感慨，还未开口，眼泪先流下来。\n听说双溪春景尚好，我也打算泛舟前去。只恐怕双溪蚱蜢般的小船，载不动我内心沉重的忧愁。",
    s: "《武陵春》是李清照南渡后的作品，“只恐双溪舴艋舟，载不动许多愁”以小船载不动愁的奇特比喻，将抽象的愁绪写得具体可感，与李煜“问君能有几多愁，恰似一江春水向东流”异曲同工。全词语言朴素，情感深沉，是李清照晚年词的代表作。"
  },
  "永遇乐|辛弃疾": {
    y: "历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛。\n然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着中原仍然记得，当年扬州路上，到处是金兵南侵的战火烽烟。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，只把他当作一位神祇来供奉，还有谁会记得，这曾是异族皇帝的行宫？还有谁会问，廉颇老了，饭量还好吗？",
    s: "《永遇乐·京口北固亭怀古》是辛弃疾晚年的代表作，也是豪放词的巅峰之作。全词借古讽今，用孙权、刘裕、刘义隆、廉颇等历史典故，抒发了自己渴望收复中原、却不被重用的悲愤。“想当年，金戈铁马，气吞万里如虎”“凭谁问：廉颇老矣，尚能饭否”都是千古传诵的名句，全词用典精当，气势雄浑，是辛弃疾词的压卷之作。"
  },
  "丑奴儿・采桑子|辛弃疾": {
    y: "人年轻的时候不懂忧愁的滋味，喜欢登高远望。喜欢登高远望，为了写出新词，没有愁而硬要说有愁。\n现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说道：好个凉爽的秋天呀！",
    s: "《丑奴儿》以“少年”与“而今”的对比，写出了对“愁”的不同理解。少年时“为赋新词强说愁”，是无病呻吟；而今“识尽愁滋味”，却“欲说还休”，因为真正的愁是无法言说的。全词以浅近的语言表达了深沉的人生感慨，是辛弃疾词的名篇。"
  },
  "卜算子|陆游": {
    y: "驿站之外的断桥边，梅花孤单寂寞地绽开了花，无人过问。暮色降临，梅花无依无靠，已经够愁苦了，却又遭到了风雨的摧残。\n梅花并不想费尽心思去争艳斗宠，对百花的妒忌与排斥毫不在乎。即使凋零了，被碾作泥土，又化作尘土了，梅花依然和往常一样散发出缕缕清香。",
    s: "《卜算子·咏梅》是陆游咏物言志的名作，以梅花自喻，“零落成泥碾作尘，只有香如故”表达了诗人虽屡遭排挤、身处逆境，却依然坚守高洁品格的精神。全词以梅喻人，托物言志，是咏梅词中的杰作。"
  },
  "破阵子|晏殊": {
    y: "燕子飞来正赶上社祭之时，梨花落了之后就是清明。池塘边点缀着几点青苔，树叶底下传来一两声黄鹂的啼叫。白日渐长，柳絮轻盈地飞舞。\n东邻的少女们笑得天真烂漫，在采桑的路上相遇。怪不得昨夜做了个好梦，原来是今天斗草赢了。笑容从双颊上绽开。",
    s: "《破阵子·春景》是晏殊描写春日少女生活的词作，“池上碧苔三四点，叶底黄鹂一两声”以细腻的笔触写出了春日的生机，“笑从双脸生”将少女的天真快乐写得生动传神。全词语言明快，充满生活气息，是晏殊词中少有的轻快之作。"
  },
  "采桑子|欧阳修": {
    y: "西湖风光好，驾轻舟划短桨多么逍遥。碧绿的湖水绵延不断，长堤上花草散出芳香。隐隐传来的音乐歌唱，像是随着船儿在湖上飘荡。\n无风的水面，光滑得好似琉璃一样，不觉得船儿在前进，只见微微的细浪在船边荡漾。看，被船儿惊起的水鸟，正掠过湖岸在飞翔。",
    s: "《采桑子·轻舟短棹西湖好》是欧阳修描写颍州西湖的组词之一，“无风水面琉璃滑，不觉船移”以细腻的笔触写出了西湖的宁静之美，“微动涟漪，惊起沙禽掠岸飞”以动写静，意境优美。全词语言清丽，充满生活气息。"
  },
  "临江仙|晏几道": {
    y: "深夜梦回楼台朱门紧锁，宿酒醒后帘幕重重低垂。去年的春恨涌上心头时，人在落花纷扬中幽幽独立，燕子在微风细雨中双双翱飞。\n记得与小蘋初次相见，她穿着绣有两重心字的罗衣。琵琶轻弹，声声诉说相思之情。当时的明月如今还在，曾经照着她像彩云一样归去。",
    s: "《临江仙·梦后楼台高锁》是晏几道的代表作，“落花人独立，微雨燕双飞”以工整的对仗写出了孤独与相思，“当时明月在，曾照彩云归”以明月和彩云比喻往事，将对恋人的思念写得含蓄深沉。全词意境优美，情感真挚，是婉约词的杰作。"
  },
  "卜算子|王观": {
    y: "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。要是到江南赶上春天，千万要把春天的景色留住。",
    s: "《卜算子·送鲍浩然之浙东》是王观的名作，“水是眼波横，山是眉峰聚”以美人的眼波和眉峰比喻山水，构思巧妙，“若到江南赶上春，千万和春住”将送别与迎春结合，表达了对友人的祝福。全词语言清丽，构思新颖，是宋词中的佳作。"
  },
  "满庭芳|苏轼": {
    y: "微小的虚名，微薄的小利，算来有什么值得忙碌的。凡事都已前定，谁弱谁强又怎样。且趁现在身体还未衰老，让我放浪一些，疏狂一些。百年之中，就算都让我醉，也不过三万六千场。\n细想，人生能有多少时间，忧愁风雨，就占去了一半，又何必拼命去说短论长。有幸面对清风皓月，以苔藓为席，以云幕为帐。江南好啊，千钟美酒，一曲满庭芳。",
    s: "《满庭芳·蜗角虚名》是苏轼的代表作，“蜗角虚名，蝇头微利”以比喻手法写出了名利的微不足道，表达了诗人对名利的淡泊和对自由生活的向往。全词语言旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "玉蝴蝶|柳永": {
    y: "望着雨收云散的天空，我默默凭倚栏杆，目送秋日的时光渐渐远去。晚景萧瑟凄凉，足以引起宋玉那样的悲凉。水面风轻，蘋花渐渐老去，月光露水寒冷，梧桐叶飘黄。这情景让人感伤。故人在哪里，烟水茫茫。\n难忘，我们一起饮酒赋诗的聚会，多少次辜负了风月，多少次变换了星霜。海阔山遥，不知哪里是潇湘。想那双燕，难以凭它们传递远信，指着暮色的天空，空自辨认归航的船。黯然相望。在孤雁的哀鸣声中，我一直站到夕阳西下。",
    s: "《玉蝴蝶·望处雨收云断》是柳永的名作，“故人何在，烟水茫茫”以景结情，将对故人的思念写得含蓄深沉，“断鸿声里，立尽斜阳”以孤雁和夕阳衬托诗人的孤独。全词意境凄清，情感深沉，是柳永慢词的佳作。"
  },
  "翦牡丹|张先": {
    y: "野外的绿色连着天空，青天垂到水面，白色的水光荡漾都很明净。柳树下的小路没有人，柳絮飘落飞无影。汀洲上日落人归，长巾薄袖，采香拾翠竞相游玩。好像懂得凌波微步，停泊在烟渚的春夜。\n彩绦朱索刚刚整理好。宿在绣屏边，画船上风已定。金凤凰响在双槽上，弹出今古的幽思谁能领会。玉盘大小乱珠迸溅。酒上了妆面，花艳和媚相并。再听。弹尽汉妃一曲，江空月静。",
    s: "《剪牡丹·舟中闻双琵琶》是张先的名作，描写了舟中听琵琶的情景。“玉盘大小乱珠迸”以比喻手法写出了琵琶声的美妙，“江空月静”以景结情，余味无穷。全词意境优美，描写细腻，是宋词中的佳作。"
  },
  "点绛唇|王禹": {
    y: "雨绵绵，云愁闷，江南依然称得上美丽。水村渔市，一缕孤烟细细升起。\n天边的大雁，远远看去行列相连。平生的事，此时凝神注视，谁能理解我凭栏的心意。",
    s: "《点绛唇·感兴》是王禹偁的名作，“天际征鸿，遥认行如缀”以大雁比喻自己的志向，“谁会凭栏意”将怀才不遇的感慨写得含蓄深沉。全词意境开阔，情感深沉，是宋初词的佳作。"
  },
  "酒泉子|潘阆": {
    y: "常常回忆观潮的情景，满城的人争着到江上眺望。潮水来时，怀疑沧海全都空了，万面鼓声中。\n弄潮儿站在浪头上，手举红旗，红旗不被水打湿。离别后几次在梦中看到，梦醒还心有余悸。",
    s: "《酒泉子·长忆观潮》是潘阆的名作，描写了钱塘江大潮的壮观景象。“来疑沧海尽成空，万面鼓声中”以夸张手法写出了潮水的磅礴气势，“弄潮儿向涛头立，手把红旗旗不湿”写出了弄潮儿的英勇。全词气势磅礴，是宋词中少有的描写大潮的作品。"
  },
  "满庭芳|秦观": {
    y: "会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，连绵无穷。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情爱的往事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。",
    s: "《满庭芳·山抹微云》是秦观的代表作，秦观也因此被称为“山抹微云君”。“山抹微云，天连衰草”以极简练的笔墨写出了秋日的苍茫，“斜阳外，寒鸦万点，流水绕孤村”化用隋炀帝诗句，意境优美。全词将离别之情写得真挚动人，是婉约词的杰作。"
  },
  "定风波|柳永": {
    y: "自从春天以来，绿叶红花都让人发愁，芳心对什么事都漫不经心。太阳升到花梢，黄莺穿过柳带，还压着香被躺着。肌肤消瘦，头发散乱，整天懒得梳妆。无奈。恨薄情郎一去，连个音信都没有。\n早知道这样，后悔当初没把他的马鞍锁住。在书房里，只给他纸和笔，管束着让他吟诗学习。永远相随，不要抛躲，闲着时拿着针线陪他坐着。和我在一起，免得年少时光白白度过。",
    s: "《定风波·自春来》是柳永的名作，以市井女子的口吻，描写了对丈夫的思念和对平凡夫妻生活的向往。“针线闲拈伴伊坐”写出了女子对温馨生活的渴望，相传晏殊曾以此词讥讽柳永。全词语言通俗，情感真挚，是柳永俚词的代表作。"
  },
  "夜半乐|柳永": {
    y: "寒云暗淡的天气，我乘一叶扁舟，乘兴离开江渚。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，山风忽然吹起，又听到商旅相互呼唤。船帆高高举起，画船轻快地驶过南浦。\n望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰杨掩映，岸边两两三三，是浣纱的游女。躲避行人，含羞笑着相互说话。\n到此因此思念，轻易抛弃了绣阁中的佳人，像浪萍一样难以停留。感叹后约的叮咛究竟有什么凭据。离怀凄惨，空自恨岁晚归期受阻。泪眼凝望，遥远的京城路。孤雁声远，长天暮色。",
    s: "《夜半乐》是柳永的长调名作，全词分三片，描写了舟行所见的江南景色和对佳人的思念。“败荷零落，衰杨掩映，岸边两两三三，浣纱游女”以细腻的笔触写出了江南水乡的生活气息，“断鸿声远长天暮”以景结情，余味无穷。全词意境优美，是柳永慢词的佳作。"
  },
  "踏莎行|晏殊": {
    y: "小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。",
    s: "《踏莎行·小径红稀》是晏殊的名作，“春风不解禁杨花，濛濛乱扑行人面”以拟人手法写春风，生动有趣，“一场愁梦酒醒时，斜阳却照深深院”以景结情，将闲愁写得含蓄深沉。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "南歌子|欧阳修": {
    y: "凤凰发髻上束着金泥带，龙纹玉掌梳插在发间。走到窗下笑着相扶，爱问画眉深浅合不合时宜？\n依偎着人摆弄笔很久，初次试着描花。轻易耽误了绣花功夫，笑着问鸳鸯两个字怎么写？",
    s: "《南歌子·凤髻金泥带》是欧阳修的名作，以细腻的笔触描写了新婚夫妇的甜蜜生活。“爱道画眉深浅入时无”化用朱庆余诗句，“笑问鸳鸯两字怎生书”将少女的娇羞写得生动传神。全词语言明快，充满生活气息，是欧阳修词中少有的轻快之作。"
  },
  "临江仙|苏轼": {
    y: "夜里在东坡饮酒，醉而复醒，醒了又饮。回来的时候仿佛已经三更。家里的童仆早已睡熟鼾声如雷鸣。反复敲门里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n长恨身在宦途，这身子已不是我自己所有。什么时候能忘却为功名利禄而奔竞钻营！夜深了，风停了，江面上的水波也平静下来。真想乘上小船从此消逝，在江河湖海中了却余生。",
    s: "《临江仙·夜归临皋》是苏轼被贬黄州时所作，“小舟从此逝，江海寄余生”表达了诗人对自由生活的向往，相传苏轼写此词后，“挂冠服江边，拏舟长啸去矣”，太守徐君猷闻之大惊，以为苏轼逃走。全词意境旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "西江月|苏轼": {
    y: "我三次经过平山堂下，半生在弹指声中过去了。十年没见老仙翁欧阳修了，墙壁上他的字迹还龙蛇飞动。\n想要悼念文章太守欧阳修，仍然歌唱他的杨柳春风。不要说万事转头就空，没转头的时候也都是梦。",
    s: "《西江月·平山堂》是苏轼经过扬州平山堂时，为悼念恩师欧阳修而作。“壁上龙蛇飞动”写出了欧阳修书法的雄健，“休言万事转头空，未转头时皆梦”表达了对人生的深刻感悟。全词情感真挚，意境旷达，是苏轼婉约词的佳作。"
  },
  "永遇乐|苏轼": {
    y: "明月如霜，好风如水，清景无限。曲折的港湾里鱼儿跳跃，圆圆的荷叶上露珠滚落，寂寞无人看见。三更鼓声响起，一片叶子铿然落下，黯黯的梦云被惊断。夜色茫茫，重寻无处，醒来后把小园走遍。\n天涯的倦客，山中的归路，望断了故园的视线。燕子楼空，佳人在哪里，空锁住楼中的燕子。古今如梦，何曾从梦中醒来，只有旧欢新怨。他日对着黄楼夜景，会为我长叹。",
    s: "《永遇乐·明月如霜》是苏轼夜宿燕子楼时所作，“燕子楼空，佳人何在，空锁楼中燕”是千古传诵的名句，将对历史的感慨写得含蓄深沉。全词意境凄清，情感深沉，是苏轼婉约词的杰作，晁补之称“燕子楼空，佳人何在，空锁楼中燕”为“三句说尽张建封事”。"
  },
  "洞仙歌|苏轼": {
    y: "冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹开，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n起来携着她的纤纤素手，走到无声的庭院，时时看到稀疏的星星渡过银河。试问夜有多深？已经是三更时分，月光淡了，玉绳星低低转动。屈指算西风几时吹来，又不道流年在暗中偷偷变换。",
    s: "《洞仙歌·冰肌玉骨》是苏轼根据蜀主孟昶与花蕊夫人的故事改写的词作，“冰肌玉骨，自清凉无汗”写出了花蕊夫人的清丽，“但屈指西风几时来，又不道流年暗中偷换”将时光流逝的感慨写得含蓄深沉。全词意境优美，情感细腻，是苏轼婉约词的佳作。"
  },
  "越调·天净沙秋思|马致远": {
    y: "枯萎的藤蔓，苍老的古树，黄昏时归巢的乌鸦；小桥下溪水潺潺，旁边有几户人家；古老的道路上，萧瑟的西风里，走着一匹疲惫的瘦马。夕阳向西边落下，漂泊在外的游子，还远在天涯，愁肠寸断。",
    s: "《天净沙·秋思》被称为“秋思之祖”，仅用28个字，便勾勒出一幅苍凉的秋日羁旅图。全曲无一“愁”字，却字字含愁，情景交融，是元曲中最广为人知的作品，也是中国古典诗歌中描写乡愁的巅峰之作。"
  },
  "南吕·四块玉别情|关汉卿": {
    y: "自从送别之后，心中难舍，这一点相思什么时候才能断绝？凭栏远望，衣袖拂过如雪的杨花。溪水又斜，青山又遮，人已经去了！",
    s: "《四块玉·别情》是关汉卿的小令名作，以女子的口吻写送别后的相思。“凭阑袖拂杨花雪”以动作写思念，“溪又斜，山又遮，人去也”以景结情，将离别的惆怅写得含蓄深沉。全曲语言朴素，情感真挚。"
  },
  "离骚（节选）|屈原": {
    y: "我是古帝高阳氏的子孙，我已去世的父亲字伯庸。\n岁星在寅那年的孟春月，正当庚寅日那天我降生。\n父亲仔细揣测我的生辰，于是赐给我相应的美名。\n父亲把我的名取为正则，同时把我的字叫作灵均。\n天赋给我很多良好素质，我不断加强自己的修养。\n我把江离芷草披在肩上，把秋兰结成索佩挂身旁。\n光阴似箭我好像跟不上，岁月不等待人令我心慌。\n早晨我在大坡采集木兰，傍晚在小洲中摘取宿莽。\n时光迅速逝去不能久留，四季更相代谢变化有常。\n我想到草木已由盛到衰，恐怕自己身体逐渐衰老。\n何不利用盛时扬弃秽政，为何还不改变这些法度？\n乘上千里马纵横驰骋吧，来呀我在前面引导开路！",
    s: "《离骚》是屈原的代表作，也是中国古代最长的抒情诗，共373句。这里节选的是开篇部分，诗人自叙身世、生辰和名字，表达了自己的高洁品质和对国家的忧虑。“路漫漫其修远兮，吾将上下而求索”的精神贯穿全诗，奠定了中国浪漫主义文学的传统，对后世影响深远。"
  },
  "鹿柴|王维": {
    y: "幽静的山谷里看不见人，只听到人说话的声音。\n落日的影晕映入了深林，又照在幽暗处的青苔上。",
    s: "《鹿柴》是王维《辋川集》中的名篇，全诗仅二十字，却营造出一种空寂幽深的意境。“空山不见人，但闻人语响”以有声衬无声，“返景入深林，复照青苔上”以光亮写幽暗，充满禅意，体现了王维“诗佛”的艺术特色。"
  },
  "送元二使安西|王维": {
    y: "渭城早晨一场春雨沾湿了轻尘，客舍周围柳树的枝叶翠嫩一新。\n老朋友请你再干一杯美酒，向西出了阳关就难以遇到故旧亲人。",
    s: "《送元二使安西》又名《渭城曲》，是王维最著名的送别诗，后被谱成《阳关三叠》，广为传唱。“劝君更尽一杯酒，西出阳关无故人”两句，将依依惜别之情浓缩在一杯酒中，含蓄深沉，余味无穷，是唐诗中最动人的送别名句。"
  },
  "从军行·其四|王昌龄": {
    y: "青海湖上乌云密布，遮得连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。\n守边将士身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。",
    s: "《从军行》是王昌龄边塞诗的代表作，“黄沙百战穿金甲，不破楼兰终不还”两句，以铿锵的音调、坚定的语气，写出了戍边将士誓死报国的英雄气概，是唐诗中最具豪情壮志的名句之一。"
  },
  "蜀道难|李白": {
    y: "唉呀呀！多么高峻伟岸！蜀道难以攀越，简直难于上青天。\n传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。\n从那时至今约有四万八千年了吧，秦蜀被秦岭所阻从不沟通往返。\n西边太白山高峻无路只有飞鸟可通行，飞鸟可以直通峨眉山巅。\n山崩地裂，埋葬了五位开山英雄壮士，这样高险的山路和栈道才相互勾连。\n蜀中上有挡住太阳神六龙车的山巅，下有激浪排空曲折的大川。\n善于高飞的黄鹤尚且无法飞过，即使猢狲要想翻过也愁于攀援。\n青泥岭的泥路曲曲弯弯，百步九折萦绕着山峦。\n屏住呼吸仰头就可触摸参星和井星，紧张得透不过气来，用手抚胸惊恐不已徒长吁短叹。\n好朋友呵请问你西游何时回还？可怕的岩山栈道实在难以登攀！\n只见那悲鸟在古树上哀鸣啼叫，雄雌相随飞翔在树丛之间。\n月夜又听到杜鹃凄凉悲啼，在空山中传响令人愁思绵绵。\n蜀道难以攀越呵简直难于上青天，使人听到这些怎么不脸色突变？\n山峰座座相连离天还不到一尺，枯松老枝倒挂倚贴在绝壁之间。\n漩涡飞转瀑布飞泻争相喧闹着，飞流撞击着巨石在山谷中滚动像万壑鸣雷一般。\n这样危险的地方，唉呀呀你这个远方而来的客人，为什么非要来这里不可呀？\n剑阁所在崇峻巍峨高入云端，只要一人把守千军万马难攻占。\n驻守的官员倘若不是可信赖的人，难免要变为豺狼，据险作乱。\n每日每夜都要躲避猛虎和长蛇，它们磨牙吮血，杀人如麻。\n锦官城虽然说是个快乐的所在，如此险恶还不如早早地把家还。\n蜀道难以攀越呵简直难于上青天，侧身西望令人不免感慨与长叹！",
    s: "《蜀道难》是李白浪漫主义诗歌的代表作，以雄奇奔放的笔调描绘了蜀道的艰险壮丽。全诗以“蜀道之难，难于上青天”为主旋律，三次反复出现，一唱三叹，气势磅礴。诗人运用夸张、想象、神话传说等手法，将蜀道的奇险写得惊心动魄，是唐诗中最具想象力的杰作。"
  },
  "行路难·其一|李白": {
    y: "金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。\n心中郁闷，我放下杯筷不愿进餐；拔出宝剑环顾四周，心里一片茫然。\n想渡黄河，冰雪却冻封了河川；想登太行山，莽莽风雪早已封山。\n像姜尚垂钓溪，闲待东山再起；又像伊尹做梦，他乘船经过日边。\n人生道路多么艰难，多么艰难；歧路纷杂，如今又身在何处？\n相信乘风破浪的时机总会到来，到时定要扬起征帆，横渡沧海！",
    s: "《行路难》是李白在仕途受挫时所作，全诗情感跌宕起伏，从“停杯投箸不能食”的苦闷茫然，到“长风破浪会有时，直挂云帆济沧海”的豪迈自信，展现了诗人虽身处逆境却依然乐观进取的精神。结尾两句是千古传诵的励志名句。"
  },
  "秋浦歌·其十五|李白": {
    y: "白发长达三千丈，是因为愁才长得这样长。\n不知在明镜之中，是何处的秋霜落在了我的头上？",
    s: "《秋浦歌》以“白发三千丈”的极度夸张开篇，将愁思之深之长写得惊心动魄。“缘愁似个长”点明白发因愁而生，后两句以问语作结，含蓄深沉。全诗仅二十字，却将怀才不遇的悲愤写得淋漓尽致，是李白浪漫主义夸张手法的典范。"
  },
  "江畔独步寻花·其六|杜甫": {
    y: "黄四娘家周围的小路旁开满了鲜花，千朵万朵鲜花把枝条都压得低垂了。\n嬉闹的彩蝶恋恋不舍地盘旋飞舞，自由自在的小黄莺在花间不断欢唱。",
    s: "《江畔独步寻花》是杜甫在成都草堂时的组诗，这一首描写了春日繁花似锦、蝶舞莺啼的美好景象。全诗语言明快，色彩明丽，充满生活气息，展现了杜甫诗歌中轻松愉悦的一面，是描写春景的名篇。"
  },
  "绝句|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，四句四景，对仗工整，色彩明丽。“两个黄鹂鸣翠柳，一行白鹭上青天”以黄、翠、白、青四种颜色交织，画面感极强；“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗是杜甫七绝中的精品。"
  },
  "琵琶行|白居易": {
    y: "秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。\n我下马和客人在船上饯别设宴，举起酒杯要饮却无助兴的管弦。\n酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。\n忽听得江面上传来琵琶清脆声，我忘却了回归客人也不想动身。\n循身轻轻探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。\n我们移船靠近邀请她出来相见，叫下人添酒回灯重新摆起酒宴。\n千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。\n转紧琴轴拨动琴弦试弹了几声，尚未成曲调那形态就非常有情。\n弦弦凄楚悲切声音隐含着沉思，似乎在诉说着她平生的不得志。\n她低着头随手连续地弹个不停，用琴声把心中无限的往事说尽。\n轻轻抚拢慢慢捻滑抹了又加挑，初弹霓裳羽衣曲接着再弹六幺。\n大弦浑宏悠长嘈嘈如暴风骤雨，小弦和缓幽细切切如有人私语。\n嘈嘈声切切声互为交错地弹奏，就像大珠小珠一串串掉落玉盘。\n琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉。\n水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。\n像另有一种愁思幽恨暗暗滋生，此时闷闷无声却比有声更动人。\n突然间好像银瓶撞破水浆四溅，又好像铁甲骑兵厮杀刀枪齐鸣。\n一曲终了她对准琴弦中心划拨，四弦一声轰鸣好像撕裂了布帛。\n东船西舫人们都静悄悄地聆听，只见江心之中映着白白秋月影。\n她沉吟着收起拨片插在琴弦中，整顿衣裳依然显出庄重的颜容。\n她说我原是京城负有盛名的歌女，老家住在长安城东南的虾蟆陵。\n弹奏琵琶技艺十三岁就已学成，教坊乐团第一队中列有我姓名。\n每曲弹罢都令艺术大师们叹服，每次妆成都被同行歌妓们嫉妒。\n京都豪富子弟争先恐后来献彩，弹完一曲收来的红绡不知其数。\n钿头银篦打节拍常常断裂粉碎，红色罗裙被酒渍染污也不后悔。\n年复一年都在欢笑打闹中度过，秋去春来美好的时光白白消磨。\n兄弟从军姊妹死家道已经破败，暮去朝来我也渐渐地年老色衰。\n门前车马减少光顾者落落稀稀，青春已逝我只得嫁给商人为妻。\n商人重利不重情常常轻易别离，上个月他去浮梁做茶叶的生意。\n他去了留下我在江口孤守空船，秋月与我作伴绕舱的秋水凄寒。\n更深夜阑常梦少年时作乐狂欢，梦中哭醒纵横了泪水和脂粉。\n我听了琵琶声早已摇头叹息，又听到她这番诉说更加歔欷。\n同样都是天涯沦落的可怜人，今日相逢何必问是否曾经相识！\n自从去年我离开繁华长安京城，被贬居住在浔阳江畔常常卧病。\n浔阳这地方荒凉偏僻没有音乐，一年到头也听不到管弦的乐器声。\n住在湓江附近低洼潮湿的地方，黄芦和苦竹绕着宅第丛生。\n在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。\n春江花朝秋江月夜那样好光景，也无可奈何常常取酒独酌独饮。\n难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。\n今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。\n请你不要推辞坐下来再弹一曲，我要为你创作一首新诗琵琶行。\n被我的话所感动她站立了好久，回身坐下再转紧琴弦拨出急声。\n凄凄切切不再像刚才那种声音，在座的人重听都掩面哭泣不停。\n要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！",
    s: "《琵琶行》是白居易贬官江州时所作，通过描写琵琶女的高超技艺和不幸身世，抒发了自己被贬的愤懑之情。“同是天涯沦落人，相逢何必曾相识”是千古传诵的名句，将诗人与琵琶女的命运联系在一起，感人至深。诗中对琵琶音乐的描写更是出神入化，“大珠小珠落玉盘”“此时无声胜有声”等句成为描写音乐的经典。"
  },
  "忆江南·其一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "钱塘湖春行|白居易": {
    y: "从孤山寺的北面到贾亭的西面，湖面春水刚与堤平，白云低垂，同湖面上连成一片。\n几只早出的黄莺争相飞往向阳的树木，谁家新飞来的燕子忙着筑巢衔泥。\n纷繁的花朵渐渐开放使人眼花缭乱，浅浅的青草刚刚够上遮没马蹄。\n最爱的湖东美景百游不厌，杨柳成排绿荫中穿过一条白沙堤。",
    s: "《钱塘湖春行》是白居易任杭州刺史时所作，描写了西湖早春的明媚风光。“几处早莺争暖树，谁家新燕啄春泥”以莺燕的活动写出早春的生机，“乱花渐欲迷人眼，浅草才能没马蹄”写花草的繁茂，全诗充满春天的气息，是描写西湖春景的名篇。"
  },
  "卖炭翁|白居易": {
    y: "有位卖炭的老翁，整年在南山里砍柴烧炭。\n他满脸灰尘，显出被烟熏火燎的颜色，两鬓头发灰白，十个手指也被炭烧得很黑。\n卖炭得到的钱用来干什么？买身上穿的衣裳和嘴里吃的食物。\n可怜他身上只穿着单薄的衣服，心里却担心炭卖不出去，还希望天更寒冷。\n夜里城外下了一尺厚的大雪，清晨，老翁驾着炭车碾轧冰冻的车轮印往集市上赶去。\n牛累了，人饿了，但太阳已经升得很高了，他们就在集市南门外泥泞中歇息。\n那得意忘形的骑着两匹马的人是谁啊？是皇宫内的太监和太监的手下。\n太监手里拿着文书，嘴里却说是皇帝的命令，吆喝着牛朝皇宫拉去。\n一车的炭，一千多斤，太监差役们硬是要赶着走，老翁是百般不舍，但又无可奈何。\n那些人把半匹红纱和一丈绫，朝牛头上一挂，就充当炭的价钱了。",
    s: "《卖炭翁》是白居易《新乐府》中的名篇，通过卖炭翁的遭遇，深刻揭露了宫市制度的罪恶，对劳动人民寄予深切同情。“可怜身上衣正单，心忧炭贱愿天寒”将老人矛盾的心理写得入木三分，是白居易现实主义诗歌的代表作。"
  },
  "无题·相见时难别亦难|李商隐": {
    y: "相见很难，离别更难，何况在这东风无力、百花凋谢的暮春时节。\n春蚕结茧到死时丝才吐完，蜡烛要烧成灰烬时像泪一样的蜡油才能滴干。\n早晨梳妆照镜，只担忧如云的鬓发改变颜色，容颜消失。长夜独自吟诗不寐，必然感到冷月侵人。\n蓬莱山离这儿不算太远，却无路可通，烦请青鸟一样的使者，殷勤地为我去探看。",
    s: "《无题》是李商隐爱情诗的代表作，“春蚕到死丝方尽，蜡炬成灰泪始干”以春蚕吐丝、蜡烛燃烧比喻至死不渝的爱情，成为千古传诵的爱情名句。全诗意境朦胧，情感深沉，是李商隐“无题诗”中最著名的一首。"
  },
  "登乐游原|李商隐": {
    y: "傍晚时分我心情不太好，独自驱车登上了乐游原。\n这夕阳晚景的确十分美好，只不过已是黄昏。",
    s: "《登乐游原》仅二十字，却蕴含着深沉的哲理。“夕阳无限好，只是近黄昏”既写出了夕阳的美丽，又感叹好景不长，既有对美好事物的珍惜，又有对时光流逝的无奈，成为千古传诵的名句。"
  },
  "嫦娥|李商隐": {
    y: "云母屏风上烛影暗淡，银河渐渐斜落，晨星也隐没低沉。\n嫦娥应该后悔偷取了长生不老之药，如今空对碧海青天夜夜孤寂。",
    s: "《嫦娥》借嫦娥奔月的神话故事，抒发了诗人孤寂清高的心境。“嫦娥应悔偷灵药，碧海青天夜夜心”以嫦娥的孤独比喻自己的处境，含蓄深沉，意境悠远，是李商隐七绝中的佳作。"
  },
  "江南春|杜牧": {
    y: "辽阔的江南，到处莺歌燕舞，绿树红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的许多座古寺，如今有多少笼罩在这蒙胧烟雨之中。",
    s: "《江南春》以极简练的笔触描绘了江南春天的美丽景象，“千里莺啼绿映红”从听觉和视觉写江南春景，“南朝四百八十寺，多少楼台烟雨中”在写景中融入历史兴亡的感慨，意境深远，是描写江南春景的千古名篇。"
  },
  "悯农·其二|李绅": {
    y: "盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？",
    s: "《悯农》是李绅最著名的诗作，“谁知盘中餐，粒粒皆辛苦”以朴素的语言道出了粮食的来之不易，告诫人们珍惜粮食、尊重劳动。全诗语言浅近，寓意深刻，是中国流传最广的诗篇之一。"
  },
  "离思·其四|元稹": {
    y: "经历过波澜壮阔的大海，别处的水再也不值得一观。陶醉过巫山的云雨的梦幻，别处的风景就不称之为云雨了。\n即使身处万花丛中，我也懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。",
    s: "《离思》是元稹悼念亡妻韦丛所作，“曾经沧海难为水，除却巫山不是云”以沧海之水和巫山之云比喻爱情的深广与美好，表达了对亡妻的忠贞不渝。全诗情感真挚，意境深远，是中国文学史上最著名的悼亡诗之一。"
  },
  "凉州词|王翰": {
    y: "酒筵上甘醇的葡萄美酒盛满在夜光杯之中，正要畅饮时，马上琵琶也声声响起，仿佛催人出征。\n如果醉卧在沙场上，也请你不要笑话，古来出外打仗的能有几人返回家乡？",
    s: "《凉州词》是王翰的代表作，描写了边塞将士在出征前开怀畅饮的场景。“醉卧沙场君莫笑，古来征战几人回”以豪迈旷达的语气写出了战争的残酷和将士们视死如归的气概，全诗格调苍凉而豪放，是唐代边塞诗的名篇。"
  },
  "回乡偶书·其一|贺知章": {
    y: "年少时离乡老年才归家，我的乡音虽未改变，但鬓角的毛发却已经疏落。\n家乡的儿童们看见我，没有一个认识我。他们笑着询问我：你是从哪里来的呀？",
    s: "《回乡偶书》是贺知章八十多岁告老还乡时所作，“少小离家老大回，乡音无改鬓毛衰”写出了久客他乡的感慨，“儿童相见不相识，笑问客从何处来”以儿童的天真提问，反衬出诗人的沧桑与悲凉，全诗语言朴素，情感深沉，是唐诗中最感人的思乡名篇。"
  },
  "饮湖上初晴后雨·其二|苏轼": {
    y: "在灿烂的阳光照耀下，西湖水微波粼粼，波光艳丽，看起来很美；雨天时，在雨幕的笼罩下，西湖周围的群山迷迷茫茫，若有若无，也显得非常奇妙。\n若把西湖比作美人西施，淡妆浓抹都是那么得十分适宜。",
    s: "《饮湖上初晴后雨》是苏轼描写西湖的名篇，“欲把西湖比西子，淡妆浓抹总相宜”以西施比喻西湖，既写出了西湖晴雨皆宜的美丽，又赋予西湖以人的神韵，成为描写西湖的千古名句，西湖也因此被称为“西子湖”。"
  },
  "夏日田园杂兴·其七|范成大": {
    y: "白天去田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树荫下学着种瓜。",
    s: "《夏日田园杂兴》是范成大田园诗的代表作，描写了农村夏日的劳动场景。“童孙未解供耕织，也傍桑阴学种瓜”以儿童学种瓜的细节，写出了农村劳动的代代相传，充满生活气息，全诗语言朴素，意境清新，是宋代田园诗的佳作。"
  },
  "江南|佚名": {
    y: "江南又到了适宜采莲的季节了，莲叶浮出水面，挨挨挤挤，重重叠叠，迎风招展。在茂密如盖的荷叶下面，欢快的鱼儿在不停的嬉戏玩耍。\n一会儿在这儿，一会儿又忽然游到了那儿，说不清究竟是在东边，还是在西边，还是在南边，还是在北边。",
    s: "《江南》是汉乐府民歌，描写了江南水乡采莲的欢乐场景。全诗以“鱼戏莲叶”的反复咏唱，营造出活泼欢快的氛围，充满江南水乡的生活气息，是小学课本中的经典篇目。"
  },
  "画|王维": {
    y: "远看高山色彩明亮，走近一听水却没有声音。\n春天过去，可是依旧有许多花草争奇斗艳，人走近，可是鸟却依然没有被惊动。",
    s: "《画》是一首谜语诗，每句都在描写画中的景物，远看山有颜色，近听水却无声，春去花还在，人来鸟不惊，处处暗示这是一幅画。全诗构思巧妙，语言浅近，是小学生最喜爱的古诗之一。"
  },
  "古朗月行（节选）|李白": {
    y: "小时候不认识月亮，把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。",
    s: "《古朗月行》是李白的作品，这里节选的是前四句，以儿童的视角描写月亮，“呼作白玉盘”“又疑瑶台镜”两个比喻天真可爱，充满童趣，是小学课本中的经典篇目。"
  },
  "渔歌子|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "塞下曲|卢纶": {
    y: "死寂之夜，乌云遮月，天边大雁惊飞，单于的军队想要趁着夜色悄悄潜逃。\n正想要带领轻骑兵一路追赶，大雪纷纷扬扬落满了身上的弓刀。",
    s: "《塞下曲》是卢纶的边塞诗名作，“月黑雁飞高，单于夜遁逃”写敌军夜逃，“欲将轻骑逐，大雪满弓刀”写将士追击，全诗没有直接写战斗，却充满紧张的战斗氛围，气势雄浑，是唐代边塞诗的佳作。"
  },
  "浪淘沙·其一|刘禹锡": {
    y: "弯弯曲曲的黄河，挟带着泥沙，波涛滚滚如巨风掀簸来自天涯。\n如今好像要直飞上高空的银河，请你带上我一起去寻访牛郎织女的家。",
    s: "《浪淘沙》是刘禹锡的组诗，这一首描写黄河的雄伟景象。“九曲黄河万里沙”写出黄河的蜿蜒与泥沙，“如今直上银河去，同到牵牛织女家”由黄河联想到银河，想象奇特，充满浪漫主义色彩。"
  },
  "忆江南|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "池上|白居易": {
    y: "小娃撑着小船，偷偷地从池塘里采了白莲回来。\n他不懂得掩藏自己的行踪，浮萍被船儿荡开，水面上留下了一条长长的水线。",
    s: "《池上》是白居易描写儿童生活的小诗，“小娃撑小艇，偷采白莲回”写出了小孩的天真淘气，“不解藏踪迹，浮萍一道开”以浮萍被分开的细节，将小孩的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "悯农·其一|李绅": {
    y: "春天只要播下一粒种子，秋天就可收获很多粮食。\n普天之下，没有荒废不种的田地，却仍有劳苦农民被饿死。",
    s: "《悯农·其一》以“春种一粒粟，秋收万颗子”的丰收景象，与“农夫犹饿死”的残酷现实形成强烈对比，揭露了封建社会农民的悲惨命运，表达了对劳动人民的深切同情。全诗语言朴素，对比鲜明，发人深省。"
  },
  "江上渔者|范仲淹": {
    y: "江上来来往往的行人，只喜爱味道鲜美的鲈鱼。\n你看那一叶小小渔船，时隐时现在滔滔风浪里。",
    s: "《江上渔者》是范仲淹的名作，以“江上往来人，但爱鲈鱼美”与“君看一叶舟，出没风波里”对比，写出了捕鱼人的艰辛，表达了对劳动人民的同情。全诗语言朴素，对比鲜明，是小学课本中的经典篇目。"
  },
  "南园十三首·其五|李贺": {
    y: "男子汉大丈夫为什么不腰带武器，去收复黄河南北被割据的关塞河山五十州呢？\n请你暂且登上那凌烟阁去看一看，又有哪一个书生曾被封为食邑万户的列侯？",
    s: "《南园十三首·其五》是李贺的名作，“男儿何不带吴钩，收取关山五十州”是抖音上最火的“杀气诗词”之一，充满少年人的意气风发和报国豪情。全诗语言刚劲，气势磅礴，表达了诗人渴望建功立业的雄心壮志。"
  },
  "唐多令·芦叶满汀洲|刘过": {
    y: "芦苇的枯叶落满沙洲，浅浅的寒水在沙滩上无声无息地流过。二十年光阴似箭，如今我又重新登上这南楼。柳树下的船还未系稳，能有几天呢，又到了中秋时节。\n黄鹤矶头，旧日的友人如今还在吗？旧日的江山全是新添的愁绪。想要买上桂花，带着美酒一同去水上泛舟逍遥，却终究没有了少年时出游的那种意气风发的情怀。",
    s: "《唐多令·芦叶满汀洲》是刘过的代表作，“欲买桂花同载酒，终不似，少年游”是抖音上最火的词句之一，道尽了物是人非、青春不再的感慨。全词今昔对比，情感深沉，是南宋豪放词中的佳作。"
  },
  "赠刘景文|苏轼": {
    y: "荷花凋谢连那擎雨的荷叶也枯萎了，只有那开败了菊花的花枝还傲寒斗霜。\n一年中最好的光景你一定要记住，那就是橙子金黄、橘子青绿的秋末冬初的时节啊。",
    s: "《赠刘景文》是苏轼送给好友刘景文的诗，“一年好景君须记，最是橙黄橘绿时”是抖音上秋天最火的诗句，写出了秋末冬初的美好景色，也暗含了对友人的勉励。全诗意境开阔，格调高昂，是苏轼写景诗的佳作。"
  },
  "浣溪沙·一曲新词酒一杯|晏殊": {
    y: "填一曲新词品尝一杯美酒，时令气候亭台池榭依旧，西下的夕阳几时才能回转？\n无可奈何中百花再残落，似曾相识的春燕又归来，独自在花香小径里徘徊。",
    s: "《浣溪沙》是晏殊最著名的词作，“无可奈何花落去，似曾相识燕归来”以花落燕归的自然景象，抒发了对时光流逝、美好事物消逝的感慨，对仗工整，意境深远，成为千古传诵的名句，也是抖音上极火的词句。"
  },
  "白头吟|卓文君": {
    y: "爱情应该像山上的雪一般纯洁，像云间月亮一样皎洁。\n听说你怀有二心，所以来与你决裂。\n今日置酒作最后一次聚会，明日便在沟头分手。\n我缓缓地移动脚步沿沟走去，过去的生活宛如沟水东流，一去不返。\n当初我毅然离家随君，就不像一般女孩那样哭哭啼啼。\n满以为嫁了一个情意专心的称心郎，可以相爱到老永远幸福。\n男女情投意合就像钓竿那样轻细柔长，鱼儿那样活波可爱。\n男子应当以情意为重，失去了真诚的爱情是任何钱财珍宝都无法补偿的。",
    s: "《白头吟》相传为卓文君所作，“愿得一心人，白头不相离”是抖音上最火的爱情诗句之一，表达了对忠贞爱情的向往。全诗以雪山明月起兴，语言刚健，情感真挚，是中国文学史上最著名的爱情诗之一。"
  },
  "上邪|佚名": {
    y: "上天呀！我渴望与你相知相惜，长存此心永不褪减。\n除非巍巍群山消逝不见，除非滔滔江水干涸枯竭。除非凛凛寒冬雷声翻滚，除非炎炎酷暑白雪纷飞，除非天地相交聚合连接，我才敢将对你的情意抛弃决绝！",
    s: "《上邪》是汉乐府民歌，“山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝”以五种不可能发生的自然现象来发誓，表达了对爱情的坚贞不渝，是抖音上极火的爱情诗句。全诗感情热烈，想象奇特，是中国文学史上最著名的爱情诗之一。"
  },
  "生年不满百|佚名": {
    y: "人生在世只有短短几十年，却常常怀有无限的忧虑。\n既然白天那么短暂，黑夜那么漫长，为何不拿着蜡烛，日夜游乐呢？\n行乐应当及时，哪能等到将来呢？\n愚蠢的人总是吝啬钱财，为后世所讥笑。\n像王子乔那样成仙的人，实在是难以企及啊。",
    s: "《生年不满百》是《古诗十九首》中的名篇，“生年不满百，常怀千岁忧”是抖音上极火的诗句，表达了人生苦短、及时行乐的思想。全诗语言朴素，哲理深刻，是汉代文人五言诗的代表作。"
  },
  "西洲曲|佚名": {
    y: "思念梅花的时候就到西洲去，折一枝梅花寄给江北的心上人。\n她穿着杏红色的单衫，两鬓的头发像小乌鸦的羽毛一样黑亮。\n西洲在哪里呢？在两桨可到的桥头渡口。\n傍晚伯劳鸟飞过，风吹动乌臼树。\n树下就是她的家门，门里露出她翠绿的发饰。\n打开门心上人没有来，她就出门去采红莲。\n秋天在南塘采莲，莲花高过人头。\n低头拨弄莲子，莲子清如水。\n把莲子放在怀袖中，莲心红得透彻。\n思念心上人他却不来，抬头仰望飞鸿。\n飞鸿飞满西洲，她登上青楼望心上人。\n楼太高望不见，整天靠在栏杆上。\n栏杆弯弯曲曲，她垂下的手洁白如玉。\n卷起帘子天空高远，海水摇荡着空绿的波光。\n海水悠悠如梦，你忧愁我也忧愁。\n南风如果知道我的心意，请把我的梦吹到西洲。",
    s: "《西洲曲》是南朝乐府民歌的代表作，“南风知我意，吹梦到西洲”是抖音上极火的诗句，表达了女子对远方情人的深切思念。全诗以折梅、采莲、望鸿等细节，层层递进地描写相思之情，语言优美，意境悠远，是南朝乐府的巅峰之作。"
  },
  "感遇·其一|张九龄": {
    y: "兰草逢春，枝叶繁盛；桂花到秋，皎洁芬芳。\n世间万物都顺应季节，生机勃勃，欣欣向荣。\n谁知那些山林中的隐士，闻到兰桂的芬芳，心生爱慕。\n草木散发香气本是天性，哪里是为了求美人折取呢？",
    s: "《感遇》是张九龄的组诗，这一首以兰桂自喻，“草木有本心，何求美人折”表达了诗人坚守本心、不慕荣利的高洁品格。全诗托物言志，语言清雅，是盛唐五言古诗的代表作。"
  },
  "在狱咏蝉|骆宾王": {
    y: "深秋季节寒蝉叫个不停，蝉声把我这囚徒的愁绪带到远方。\n怎么能忍受这秋蝉扇动乌黑双翅，对我一头斑斑白发，不尽不止地长吟。\n秋露浓重，蝉儿纵使展开双翼也难以高飞，寒风瑟瑟，轻易地把它的鸣唱淹没。\n虽然蝉儿居高食洁，又有谁能相信我的清白，代我表述内心的沉冤？",
    s: "《在狱咏蝉》是骆宾王被诬下狱时所作，以蝉自喻，“无人信高洁，谁为表予心”表达了诗人品行高洁却不被理解的悲愤。全诗托物言志，情感深沉，是初唐咏物诗的代表作。"
  },
  "代悲白头翁|刘希夷": {
    y: "洛阳城东的桃花李花，飘来飘去落在谁家？\n洛阳女子有着美丽的容颜，坐在落花边长声叹息。\n今年花谢了容颜也改了，明年花开时还有谁在呢？\n已经看见松柏被摧折为柴薪，又听说桑田变成了大海。\n古人不再到洛城东了，今人还对着落花的春风。\n年年岁岁花还是相似的，岁岁年年人却不同了。",
    s: "《代悲白头翁》是刘希夷的代表作，“年年岁岁花相似，岁岁年年人不同”是千古传诵的名句，也是抖音上极火的诗句，道尽了时光流逝、物是人非的感慨。全诗以落花起兴，抒发了对青春易逝、人生无常的感叹，是初唐七言歌行的杰作。"
  },
  "杂诗|王维": {
    y: "您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？",
    s: "《杂诗》是王维的名作，以询问故乡窗前梅花是否开花的细节，表达了对故乡的深切思念。“来日绮窗前，寒梅著花未”以小见大，将思乡之情写得含蓄深沉。全诗语言朴素，情感真挚，是唐诗五绝的精品。"
  },
  "竹里馆|王维": {
    y: "独自闲坐在幽静竹林，一边弹琴一边高歌长啸。\n深深的山林中无人知晓，只有一轮明月静静与我相伴。",
    s: "《竹里馆》是王维《辋川集》中的名篇，描写了隐居竹林的悠闲生活。“独坐幽篁里，弹琴复长啸”写出了诗人的孤高自赏，“深林人不知，明月来相照”以明月为伴，表达了诗人超然物外的心境。全诗意境清幽，充满禅意。"
  },
  "青溪|王维": {
    y: "进入黄花川游览，每每都去追逐那条青溪。\n溪水随着山势，百转千回，经过的路途，却不足百里。\n水声在山间乱石中喧嚣，水色在深密的松林里幽静。\n清澈的溪水漾起菱荇，澄明的水面倒映着芦苇。\n我的心一向闲静，清澈的溪水也如此淡泊。\n就让我留在这盘石上，垂钓终老吧。",
    s: "《青溪》是王维山水诗的代表作，“声喧乱石中，色静深松里”以动衬静，写出了青溪的幽静之美。全诗以青溪的淡泊比喻自己的心境，表达了对隐居生活的向往，是王维山水诗的佳作。"
  },
  "秋夜曲|王维": {
    y: "月亮初升时秋露已经稀薄，丝罗衣已单薄却还没有更换。\n夜深了还在殷勤地拨弄银筝，心里害怕空房冷清而不忍回去。",
    s: "《秋夜曲》是王维的闺怨诗，“桂魄初生秋露微”写秋夜的清冷，“心怯空房不忍归”写女子的孤独与思念。全诗意境凄清，情感细腻，是王维七绝中的佳作。"
  },
  "月下独酌·其一|李白": {
    y: "在花丛中摆上一壶美酒，我自斟自饮，身边没有一个亲友。\n举杯向天，邀请明月，与我的影子相对，便成了三人。\n明月既不能理解开怀畅饮之乐，影子也只能默默地跟随在我的左右。\n暂且以明月和影子作伴吧，要趁春宵及时行乐。\n我吟诵诗篇，月亮伴随我徘徊，我手舞足蹈，影子便随之零乱。\n醒时一起欢乐，醉后各自分散。\n我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。",
    s: "《月下独酌》是李白的代表作，“举杯邀明月，对影成三人”是千古传诵的名句，以奇特的想象将孤独写得浪漫而旷达。全诗描写了诗人在月夜独自饮酒的情景，表达了孤独寂寞却又超然物外的心境，是李白浪漫主义诗风的典型体现。"
  },
  "长干行·其一|李白": {
    y: "我的头发刚刚盖过额头，便同你在门前做折花的游戏。\n你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。\n我们同在长干里居住，两个人从小都没什么猜忌。\n十四岁时嫁给你作妻子，害羞得没有露出过笑脸。\n低着头对着墙壁的暗处，一再呼唤也不敢回头。\n十五岁才舒展眉头，愿意永远和你在一起。\n常抱着至死不渝的信念，怎么能想到会走上望夫台。\n十六岁时你离家远行，要去瞿塘峡滟滪堆。\n五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。\n门前是你离家时徘徊的足迹，渐渐地长满了绿苔。\n绿苔太厚，不好清扫，树叶飘落，秋天早早来到。\n八月里，黄色的蝴蝶飞舞，双双飞到西园草地上。\n看到这种情景我很伤心，因而忧愁容颜衰老。\n无论什么时候你想下三巴回家，请预先把家书捎给我。\n迎接你不怕道路遥远，一直走到长风沙。",
    s: "《长干行》是李白的乐府诗名作，“郎骑竹马来，绕床弄青梅”是“青梅竹马”成语的来源，描写了一对男女从小一起长大、结婚后又离别的故事。全诗以女子的口吻，将爱情的纯真与离别的思念写得真挚动人，是李白乐府诗的代表作。"
  },
  "行路难·其二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "答王十二寒夜独酌有怀|李白": {
    y: "昨夜吴中下雪，你像王子猷那样兴起了佳兴。\n万里浮云卷绕着碧山，青天中流着一轮孤月。\n孤月沧浪，银河清澈，北斗错落，长庚明亮。\n你怀念我，对酒独酌，夜霜洁白，玉栏金井，冰棱峥嵘。\n人生飘忽不过百年，应当酣畅地抒发万古之情。\n你不能像那些斗鸡徒，用狸膏金距斗鸡，让鼻息吹到虹霓。\n你不能学哥舒翰，横行青海夜带刀，西屠石堡取紫袍。\n你在北窗下吟诗作赋，万言不值一杯水。\n世人听了都掉头而去，就像东风吹马耳一样。\n鱼目也笑我，说和明月一样。\n骅骝蜷缩不能吃食，跛驴得志在春风中鸣叫。\n《折杨》《黄华》迎合流俗，晋君听琴枉自清角。\n巴人谁肯和阳春，楚地从来轻视奇璞。\n黄金散尽交不成朋友，白首为儒身被轻视。\n一谈一笑就失颜色，苍蝇般的谗言喧嚣。\n曾参岂是杀人的人，谗言三次传到，慈母也受惊。\n与你论心握住你的手，荣辱对我又算什么。\n孔子还曾感伤凤麟不出，董龙更是何鸡狗。\n一生傲岸苦于不谐于世，恩宠疏远，媒人徒劳，志意多乖违。\n严陵对汉天子长揖不拜，何必长剑拄颐侍奉玉阶。\n显达也不足贵，穷困也不足悲。\n韩信羞与绛灌并列，祢衡耻于追逐屠沽之辈。\n你不见李北海，英风豪气如今何在。\n你不见裴尚书，土坟三尺长满蒿棘。\n少年时早就想去五湖隐居，见此更加疏远钟鼎。",
    s: "《答王十二寒夜独酌有怀》是李白的名作，全诗以寒夜独酌起兴，抒发了怀才不遇的愤懑和对现实的批判。“吟诗作赋北窗里，万言不直一杯水”道尽了文人的辛酸，“达亦不足贵，穷亦不足悲”表达了旷达的人生态度。全诗气势磅礴，情感深沉，是李白七言古诗的杰作。"
  },
  "夜思|李白": {
    y: "明亮的月光洒在窗户纸上，好像地上泛起了一层白霜。\n我抬起头来，看那天窗外空中的明月，不由得低头沉思，想起远方的家乡。",
    s: "《静夜思》是李白最著名的诗篇，也是中国流传最广的唐诗之一。全诗仅二十字，语言朴素自然，却将游子思乡之情写得真挚动人。“举头望明月，低头思故乡”两个动作，将思乡之情表现得含蓄而深沉，千百年来引起无数游子的共鸣。"
  },
  "秋浦歌·其十四|李白": {
    y: "炉火熊熊燃烧，红星四溅，紫烟蒸腾，广袤的天地被红彤彤的炉火照得通明。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。",
    s: "《秋浦歌·其十四》是李白描写冶炼工人劳动的诗篇，“炉火照天地，红星乱紫烟”写出了冶炼场面的壮观，“赧郎明月夜，歌曲动寒川”写出了工人的乐观精神。全诗色彩浓烈，充满生活气息，是中国古代诗歌中少有的描写工人劳动的作品。"
  },
  "陪侍郎叔游洞庭醉后|李白": {
    y: "把君山削去才好，让湘水平铺流淌。\n巴陵有无限的美酒，醉倒在洞庭秋色中。",
    s: "《陪侍郎叔游洞庭醉后》是李白的名作，“刬却君山好，平铺湘水流”以奇特的想象，想要铲平君山让湘水平铺，展现了诗人豪放不羁的性格。全诗想象奇绝，气势磅礴，是李白七绝中的佳作。"
  },
  "清平调·其一|李白": {
    y: "见到云就联想到她华艳的衣裳，见到花就联想到她艳丽的容貌；春风吹拂栏杆，露珠润泽花色更浓。\n如此天姿国色，不是群玉山头所见的飘飘仙子，就是瑶台殿前月光照耀下的神女。",
    s: "《清平调·其一》是李白为杨贵妃所作，“云想衣裳花想容，春风拂槛露华浓”以云喻衣，以花喻容，将杨贵妃的美貌写得如梦如幻。全诗想象奇绝，辞藻华丽，是李白七绝中的佳作，也是抖音上极火的诗词。"
  },
  "清平调·其二|李白": {
    y: "像一枝红艳的牡丹，带着露水凝聚着芳香，楚王为巫山神女枉自断肠。\n请问汉宫之中谁能与她相比？可怜那赵飞燕还要依靠新妆才能比得上。",
    s: "《清平调·其二》以牡丹喻杨贵妃，“一枝红艳露凝香”写出了杨贵妃的美艳，“借问汉宫谁得似，可怜飞燕倚新妆”以赵飞燕衬托杨贵妃的美貌。全诗辞藻华丽，想象丰富，是李白七绝中的佳作。"
  },
  "清平调·其三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "咏怀古迹·其三|杜甫": {
    y: "成千上万的山峦山谷连绵不断，如向荆门奔去一般，王昭君生长的山村还至今留存。\n从紫台一去直通向塞外沙漠，最后只留荒郊上的一座孤坟对着黄昏。\n糊涂的君王只依凭画图识别昭君的容颜，月夜里环佩叮当是昭君归魂。\n千载流传她作的胡音琵琶曲，曲中倾诉的分明是满腔悲愤。",
    s: "《咏怀古迹·其三》是杜甫咏怀王昭君的名作，“一去紫台连朔漠，独留青冢向黄昏”以工整的对仗写出了昭君出塞的悲剧，“千载琵琶作胡语，分明怨恨曲中论”将昭君的怨恨写得深沉感人。全诗意境苍凉，情感真挚，是杜甫七律的代表作。"
  },
  "天末怀李白|杜甫": {
    y: "凉风飕飕从天边刮起，不知此时你心境怎样。\n鸿雁捎信什么时候才能到，江湖之上秋水浩渺风波多。\n有才华的人总是命途多舛，山精水怪喜欢人们经过。\n你应该与冤魂屈原共语，把诗投进汨罗江赠给他。",
    s: "《天末怀李白》是杜甫为李白被流放夜郎而作，“文章憎命达，魑魅喜人过”道尽了文人的命运多舛，“应共冤魂语，投诗赠汨罗”将李白与屈原相比，表达了对李白的深切同情。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "绝句·两个黄鹂鸣翠柳|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，全诗四句四景，“两个黄鹂鸣翠柳，一行白鹭上青天”色彩明丽，“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗对仗工整，是杜甫七绝的代表作。"
  },
  "绝句·迟日江山丽|杜甫": {
    y: "沐浴在春光下的江山显得格外秀丽，春风送来花草的芳香。\n泥土随着春天的来临而融化变得松软，燕子衔泥筑巢，暖和的沙子上睡着成双成对的鸳鸯。",
    s: "《绝句·迟日江山丽》是杜甫在成都草堂时所作，“泥融飞燕子，沙暖睡鸳鸯”以生动的细节写出了春日的生机和温馨。全诗色彩明丽，意境优美，是杜甫五言绝句的代表作。"
  },
  "菩萨蛮·小山重叠金明灭|温庭筠": {
    y: "眉妆漫染，额上的额黄半明半暗的闪耀，鬓边发丝飘过，洁白的香腮似雪。懒懒地无心去描弯弯的眉，迟了好久才起身梳理晨妆。\n插一朵花，前后都照镜子，看花朵与面容交相辉映。刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。",
    s: "《菩萨蛮》是温庭筠的代表作，也是花间词的典范。全词以细腻的笔触描写了一位女子晨起梳妆的过程，“小山重叠金明灭”写闺房陈设，“懒起画蛾眉，弄妆梳洗迟”写女子的慵懒情态，“双双金鹧鸪”以鹧鸪成双反衬女子的孤独，含蓄深婉，是花间词风的典型体现。"
  },
  "蝶恋花·槛菊愁烟兰泣露|晏殊": {
    y: "栏外的菊花笼罩着一层愁惨的烟雾，兰花沾露好似在哭泣，罗幕之间荡漾着一缕轻寒，燕子双双穿过帘幕飞走了。明月不明白离别之苦，斜斜的银辉直到破晓还穿入朱户。\n昨天夜里秋风劲吹，凋零了绿树。我独自登上高楼，望尽那消失在天涯的道路。想给我的心上人寄一封信。但是高山连绵，碧水无尽，又不知道我思念的人究竟在何处。",
    s: "《蝶恋花》是晏殊的名作，“昨夜西风凋碧树，独上高楼，望尽天涯路”被王国维称为“古今之成大事业、大学问者”的第一境界。全词以秋景写离愁，意境高远，情感深沉，是婉约词的佳作。"
  },
  "踏莎行·候馆梅残|欧阳修": {
    y: "馆舍前的梅花已经凋残，溪桥旁新生细柳轻垂，春风踏芳草远行人跃马扬鞭。走得越远离愁越没有穷尽，就像那迢迢不断的春江之水。\n寸寸柔肠痛断，行行盈淌粉泪，不要登高楼望远把栏杆凭倚。平坦的草地尽头就是重重春山，行人还在那重重春山之外。",
    s: "《踏莎行》是欧阳修婉约词的代表作，“离愁渐远渐无穷，迢迢不断如春水”以春水比喻离愁，将抽象的愁绪写得具体可感，“平芜尽处是春山，行人更在春山外”以景结情，将思念写得悠远绵长。全词意境优美，情感细腻。"
  },
  "生查子·元夕|欧阳修": {
    y: "去年元宵节的时候，花市被灯光照的如同白昼。与佳人相约在黄昏之后、月上柳梢头之时同叙衷肠。\n今年正月十五元宵节，月光与灯光仍同去年一样。再也看不到去年的故人，相思之泪沾湿了春衫的衣袖。",
    s: "《生查子·元夕》通过去年与今年元宵的对比，抒发了物是人非的怅惘。“月上柳梢头，人约黄昏后”是千古传诵的名句，写出了恋人约会的温馨美好；“不见去年人，泪湿春衫袖”则写出了旧情难续的悲伤。全词语言朴素，情感真挚。"
  },
  "雨霖铃·寒蝉凄切|柳永": {
    y: "秋蝉的叫声凄凉而急促，傍晚时分，面对着长亭，骤雨刚停。在京都郊外设帐饯行，却没有畅饮的心绪，正在依依不舍的时候，船上的人已催着出发。握着对方的手含着泪对视，哽咽的说不出话来。想到这一去路途遥远，千里烟波渺茫，傍晚的云雾笼罩着南天，深厚广阔，不知尽头。\n自古以来，多情的人总是为离别而伤感，更何况是在这冷清、凄凉的秋天！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又再同谁去诉说呢？",
    s: "《雨霖铃》是柳永最著名的词作，也是婉约词的巅峰之作。“执手相看泪眼，竟无语凝噎”将离别时的难舍难分写得入木三分，“今宵酒醒何处？杨柳岸，晓风残月”以景写情，将离别后的凄凉孤寂写得淋漓尽致，成为千古传诵的名句。全词铺叙委婉，情景交融，是柳永慢词的代表作。"
  },
  "望海潮·东南形胜|柳永": {
    y: "杭州地处东南方，地理形势优越，风景优美，是三吴的都会，这里自古以来就十分繁华。雾气笼罩着的柳树、装饰华美的桥梁，挡风的帘子、青绿色的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的树木，围绕着钱塘江沙堤，汹涌的江水卷起雪白的浪花，天堑般的钱塘江一望无边。市场上陈列着珍宝，家家户户都存满了绫罗绸缎，争相比奢华。\n里湖、外湖与重重叠叠的山岭非常清秀美丽，有秋天的桂子，十里的荷花。晴天欢快地奏乐，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官，乘醉听吹箫击鼓，观赏、吟唱烟霞风光。他日画上美好景致，回京升官时向人们夸耀。",
    s: "《望海潮》是柳永描写杭州繁华景象的名作，“三秋桂子，十里荷花”以极简练的笔墨概括了杭州的美景，成为千古传诵的名句。全词铺叙了杭州的自然风光、市井繁华和百姓生活，是宋词中描写城市风貌的杰作，相传金主完颜亮读此词后，遂起投鞭渡江之志。"
  },
  "八声甘州·对潇潇暮雨洒江天|柳永": {
    y: "面对着潇潇暮雨从天空洒落在江面上，经过一番雨洗的秋景，分外寒凉清朗。凄凉的霜风一阵紧似一阵，关山江河一片冷清萧条，落日的余光照耀在高楼上。到处红花凋零翠叶枯落，一切美好的景物渐渐地衰残。只有那滔滔的长江水，不声不响地向东流淌。\n不忍心登高遥看远方，眺望渺茫遥远的故乡，渴求回家的心思难以收拢。叹息这些年来的行踪，为什么苦苦地长期停留在异乡？想着佳人正在华丽的楼上抬头凝望思念着我，多少次错把远处驶来的船当作心上人回家的船。她哪会知道我，倚着栏杆，愁思正如此的深重。",
    s: "《八声甘州》是柳永羁旅词的代表作，“渐霜风凄紧，关河冷落，残照当楼”被苏轼评为“不减唐人高处”。全词以萧瑟的秋景衬托游子的思乡之情，“想佳人妆楼颙望，误几回、天际识归舟”从对方落笔，将思念写得曲折深婉，是柳永慢词的杰作。"
  },
  "蝶恋花·伫倚危楼风细细|柳永": {
    y: "我长时间倚靠在高楼的栏杆上，微风拂面一丝丝一细细，望不尽的春日离愁，沮丧忧愁从遥远无边的天际升起。碧绿的草色，飘忽缭绕的云霭雾气掩映在落日余晖里，默默无言谁理解我靠在栏杆上的心情。\n本想尽情放纵喝个一醉方休，想要在举杯歌唱时勉强寻欢作乐，反而觉得毫无意味。我日渐消瘦也不觉得懊悔，为了你我情愿一身憔悴。",
    s: "《蝶恋花》是柳永的名作，“衣带渐宽终不悔，为伊消得人憔悴”以身体的消瘦写对爱情的执着，被王国维称为“古今之成大事业、大学问者”的第二境界。全词以登高望远起笔，将相思之情写得深沉执着，是婉约词的佳作。"
  },
  "念奴娇·赤壁怀古|苏轼": {
    y: "大江浩浩荡荡向东流去，滔滔巨浪淘尽了千古以来的英雄人物。那旧营垒的西边，人们说就是三国时周瑜大破曹军的赤壁。陡峭的乱石直插云霄，汹涌的惊涛拍打着江岸，卷起千万堆白雪般的浪花。江山壮美如画，一时间涌现出多少英雄豪杰。\n遥想当年的周瑜，小乔刚刚嫁给他，英姿勃发，气度不凡。他手摇羽扇，头戴纶巾，谈笑之间，就把曹军的战船烧得灰飞烟灭。我今日神游古战场，应该笑我太多愁善感，早早地生出了白发。人生就像一场梦，且洒一杯酒，祭奠这江上的明月。",
    s: "《念奴娇·赤壁怀古》是豪放词的巅峰之作，也是苏轼最具代表性的作品。全词借赤壁怀古，写尽历史沧桑与人生旷达，气势雄浑，境界开阔。“大江东去”四字开篇，便奠定了全词磅礴的基调，是宋词中流传最广、影响力最大的作品之一。"
  },
  "水调歌头·明月几时有|苏轼": {
    y: "丙辰年的中秋节，我畅饮到天亮，喝得大醉，写下这首词，同时思念弟弟苏辙。明月是从什么时候开始有的？我端着酒杯问苍天。不知道天上的仙宫，今晚是哪一年。我想乘着清风回到天上，又怕那美玉砌成的楼宇太高，受不住那里的寒冷。起身在月光下起舞，影子也随着舞动，哪里比得上人间的温暖。\n月光转过朱红的楼阁，低低地照进雕花的门窗，照着无法入眠的人。月亮不该有什么怨恨吧，为什么偏偏在人们离别的时候变得圆满？人有悲欢离合的变迁，月有阴晴圆缺的更替，这样的事自古以来就难以周全。只希望世上所有人都能平安长久，即便相隔千里，也能共享这美好的月光。",
    s: "《水调歌头》被誉为“中秋词第一”，千百年来每逢中秋便被人反复吟诵。全词由望月发问起笔，从对天上的想象，落到人间的离别，最终以旷达的祝愿收尾，既有对亲人的思念，又有对人生的通透感悟。“但愿人长久，千里共婵娟”更是成为中国人最经典的中秋祝福。"
  },
  "江城子·密州出猎|苏轼": {
    y: "我姑且抒发一下少年的豪情壮志，左手牵着黄犬，右臂托起苍鹰，头戴华美鲜艳的帽子，身穿貂鼠皮衣，带着随从疾风般席卷平坦的山冈。为了报答全城的人跟随我出猎的盛意，我要像孙权一样，亲自射杀猛虎。\n我痛饮美酒，心胸开阔，胆气更为豪壮，两鬓微微发白，这又有何妨？什么时候皇帝会派人下来，就像汉文帝派遣冯唐去云中赦免魏尚一样信任我呢？那时我将使尽力气拉满雕弓就像满月一样，瞄准西北，射向西夏军队。",
    s: "《江城子·密州出猎》是苏轼第一首豪放词，“会挽雕弓如满月，西北望，射天狼”表达了诗人渴望为国戍边、抗击外敌的雄心壮志。全词气势磅礴，节奏明快，一改词为“艳科”的传统，开创了豪放词派，在词史上具有重要意义。"
  },
  "江城子·乙卯正月二十日夜记梦|苏轼": {
    y: "你我夫妻诀别已经整整十年，强忍不去思念可终究难相忘。千里之外那座遥远的孤坟啊，竟无处向你倾诉满腹的悲凉。纵然夫妻相逢你也认不出我，我已经是灰尘满面、两鬓如霜。\n昨夜我在梦中忽然回到了家乡，在小屋窗口你正在打扮梳妆。你我二人默默相对惨然不语，只有相对无言泪落千行。料想得到我当年想她的地方，就在明月的夜晚矮松的山冈。",
    s: "《江城子·乙卯正月二十日夜记梦》是苏轼悼念亡妻王弗的词作，也是中国文学史上最著名的悼亡词。“十年生死两茫茫，不思量，自难忘”开篇便将生死相隔的思念写得深沉动人，“相顾无言，惟有泪千行”将梦中重逢的悲喜写得淋漓尽致。全词情感真挚，感人至深。"
  },
  "定风波·莫听穿林打叶声|苏轼": {
    y: "三月七日，在沙湖道上赶上了下雨，拿着雨具的仆人先前离开了，同行的人都觉得很狼狈，只有我不这么觉得。过了一会儿天晴了，就做了这首词。不用注意那穿林打叶的雨声，何妨放开喉咙吟唱从容而行。竹杖和草鞋轻捷得胜过骑马，有什么可怕的？一身蓑衣任凭风吹雨打，照样过我的一生。\n春风微凉吹醒我的酒意，微微有些冷，山头初晴的斜阳却应时相迎。回头望一眼走过来的风雨萧瑟的地方，我信步归去，不管它是风雨还是放晴。",
    s: "《定风波》是苏轼被贬黄州时所作，借途中遇雨的小事，抒发了自己旷达超脱的人生态度。“一蓑烟雨任平生”“也无风雨也无晴”表达了诗人面对人生风雨的从容与豁达，是苏轼人生哲学的集中体现。全词以小见大，寓意深刻，是苏轼词的代表作。"
  },
  "水龙吟·次韵章质夫杨花词|苏轼": {
    y: "非常像花又好像不是花，无人怜惜任凭衰零坠地。它飘泊无家，傍路而行，仔细思量起来，看似无情，却自有愁思。萦绕牵挂，愁坏了柔肠，困倦得睁不开娇媚的眼睛，刚要睁开又闭上。梦中随风万里，去寻觅情郎的去处，却又被黄莺的啼叫声唤起。\n不恨杨花飘飞落尽，只恨西园里的落花难以再连缀。清晨一阵雨过后，杨花的踪迹何在？已化作一池碎萍。如果把春色分为三分，二分化为了尘土，一分付诸了流水。细细看来，那飘飞的不是杨花，点点都是离人的眼泪。",
    s: "《水龙吟·次韵章质夫杨花词》是苏轼咏物词的代表作，王国维称“东坡杨花词，和韵而似原唱”。“似花还似非花”抓住了杨花的特点，“细看来，不是杨花，点点是离人泪”以杨花比喻离人泪，将咏物与抒情融为一体，意境优美，情感深沉，是咏物词的千古绝唱。"
  },
  "卜算子·黄州定慧院寓居作|苏轼": {
    y: "弯弯的勾月悬挂在疏落的梧桐树上；夜阑人静，漏壶的水早已滴光了。有谁见到幽居的人独自往来，仿佛天边孤雁般缥缈的身影。\n突然惊起又回过头来，心有遗憾却无人知情。挑遍了寒枝也不肯栖息，甘愿在沙洲忍受寂寞凄冷。",
    s: "《卜算子》是苏轼被贬黄州时所作，以孤鸿自喻，“拣尽寒枝不肯栖，寂寞沙洲冷”表达了诗人虽身处逆境，却依然坚守高洁品格、不肯随波逐流的精神。全词意境幽冷，情感深沉，是苏轼婉约词的代表作。"
  },
  "鹊桥仙·纤云弄巧|秦观": {
    y: "纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。\n缱绻的柔情像流水般绵绵不断，重逢的约会如梦影般缥缈虚幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。",
    s: "《鹊桥仙》是秦观最著名的词作，借牛郎织女的神话故事，歌颂了坚贞不渝的爱情。“两情若是久长时，又岂在朝朝暮暮”一反传统七夕词的伤感，表达了爱情贵在长久、不在朝夕的独到见解，成为千古传诵的爱情名句。"
  },
  "浣溪沙·漠漠轻寒上小楼|秦观": {
    y: "薄薄春寒无声无息地侵入小楼，拂晓阴云惨淡像荒凉的暮秋，彩色的屏风画着淡烟笼罩流水。\n柳絮飞舞如虚无缥缈的梦境，丝丝细雨落下如同我的忧愁，再看那缀着珠宝的帘子正随意悬挂在小小银钩之上。",
    s: "《浣溪沙》是秦观婉约词的代表作，“自在飞花轻似梦，无边丝雨细如愁”以梦喻花、以愁喻雨，将抽象的愁绪写得具体可感，对仗工整，意境优美。全词以轻灵的笔触描写了春日的闲愁，是婉约词的精品。"
  },
  "踏莎行·郴州旅舍|秦观": {
    y: "暮霭沉沉，楼台消失在浓雾中，月色朦胧，渡口也隐没不见。望断了天涯，理想中的桃花源无处寻觅。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！\n远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你本来是环绕着郴山奔流，为什么偏偏要流到潇湘去呢？",
    s: "《踏莎行·郴州旅舍》是秦观被贬郴州时所作，“郴江幸自绕郴山，为谁流下潇湘去”以郴江绕郴山却又流向潇湘，比喻自己本想安居却被迫漂泊，含蓄深沉。苏轼极爱此两句，曾书于扇上。全词意境凄迷，情感深沉，是秦观词的代表作。"
  },
  "苏幕遮·燎沉香|周邦彦": {
    y: "焚烧沉香，来消除夏天闷热潮湿的暑气。鸟雀鸣叫呼唤着晴天，拂晓时分我偷偷听它们在屋檐下窃窃私语。初出的阳光晒干了荷叶上昨夜的雨滴，水面上的荷花清润圆正，微风吹过，荷叶一一挺立。\n想到那遥远的故乡，什么时候才能回去啊？我家本在吴越一带，长久地客居长安。五月，我故乡的小时候的伙伴是否在想我？划着一叶扁舟，在我的梦中来到了过去的荷花塘。",
    s: "《苏幕遮》是周邦彦的名作，“叶上初阳干宿雨，水面清圆，一一风荷举”以极简练的笔墨写出了雨后荷叶的生动姿态，王国维评为“真能得荷之神理者”。全词由写景到思乡，过渡自然，意境清新，是周邦彦词的代表作。"
  },
  "兰陵王·柳|周邦彦": {
    y: "正午的柳荫直直地落下，雾霭中，丝丝柳枝随风摆动。在古老的隋堤上，曾经多少次看见柳絮飞舞，把匆匆离去的人相送。登上高堤，望故乡，谁能理解我这个在京城漂泊已久的倦客？在长亭送别的路上，年复一年，折下的柳枝恐怕已超过千尺了吧。\n闲暇时寻找旧日的踪迹，又一次在哀怨的弦乐声中饮酒，灯光照着离别的宴席。梨花盛开，榆火取新，寒食节又到了。令人忧愁的是船行如箭，风助船快，竹篙一点，水波荡漾，回头之间已经过了几个驿站，送行的人已远在天北。\n心中凄恻，离恨层层堆积！送别的水边渐渐迂回曲折，渡口的守望所一片寂静，夕阳缓缓西下，春色无边无际。想起当年在月光下的水榭携手，在露水沾湿的桥上听笛。沉思往事，恍如梦中，眼泪暗暗滴落。",
    s: "《兰陵王·柳》是周邦彦的代表作，也是宋代慢词的典范。全词以柳起兴，铺写离别之情，层次分明，回环往复。“柳阴直，烟里丝丝弄碧”写柳之美，“登临望故国，谁识京华倦客”点出羁旅之愁，“沉思前事，似梦里，泪暗滴”以情作结，余味无穷。全词格律严谨，语言典雅，是周邦彦词的代表作。"
  },
  "声声慢·寻寻觅觅|李清照": {
    y: "苦苦地寻觅，却只落得冷冷清清，一派凄惨悲戚的景象。天气忽暖忽寒的时候，最难调养身体。喝两三杯淡酒，又怎么抵挡得住傍晚袭来的寒风？一行大雁从天上飞过，正让人伤心，却发现它们都是当年见过的旧相识。\n满地的黄花堆积零落，花儿都已经憔悴不堪，如今还有谁来采摘？守着窗子，独自一人，怎么挨到天黑？梧桐叶上滴着细雨，到了黄昏时分，还是点点滴滴下个不停。这般情景，怎么是一个“愁”字就能说得尽的！",
    s: "《声声慢》是李清照南渡之后的代表作，也是婉约词的千古绝唱。开篇七组叠词，一气呵成，将孤苦无依的心境渲染到极致。全词围绕一个“愁”字，从日常景物入手，层层递进，将国破家亡、身世飘零的沉痛写得入木三分，读来催人泪下。"
  },
  "如梦令·常记溪亭日暮|李清照": {
    y: "经常记起在溪边的亭子游玩直到太阳落山的时候，被美景陶醉而流连忘返。游兴满足了，天黑往回划船，不小心划进了荷花池深处。划呀，划呀，惊动满滩的水鸟，都飞起来了。",
    s: "《如梦令》是李清照早期的作品，回忆了少女时代溪亭游赏的欢乐场景。“争渡，争渡，惊起一滩鸥鹭”以急促的节奏和生动的画面，写出了少女的天真活泼。全词语言明快，意境优美，是李清照早期词的代表作。"
  },
  "如梦令·昨夜雨疏风骤|李清照": {
    y: "昨夜雨虽然下得稀疏，但是风却劲吹不停，酣睡一夜仍有余醉未消。问那正在卷帘的侍女，外面的情况如何，她却说海棠花依然和昨天一样。知道吗？知道吗？这个时节应该是绿叶繁茂，红花凋零了。",
    s: "《如梦令》是李清照早期的名作，“知否，知否？应是绿肥红瘦”以“绿肥红瘦”概括暮春景象，“绿”代叶，“红”代花，“肥”“瘦”二字生动传神，将对春光流逝的惋惜写得含蓄深沉。全词篇幅短小，却意蕴丰富，是李清照词的精品。"
  },
  "一剪梅·红藕香残玉簟秋|李清照": {
    y: "粉红色的荷花已经凋谢，幽香也已消散，光滑如玉的竹席带着秋的凉意。解开绫罗裙，换着便装，独自登上小船。仰头凝望远天，那白云舒卷处，谁会将锦书寄来？雁群飞回来时，月光已经洒满了西楼。\n落花独自地飘零着，水独自地流淌着。彼此都在思念对方，可又不能互相倾诉，只好各在一方独自愁闷着。这相思的愁苦实在无法排遣，刚从微蹙的眉间消失，又隐隐缠绕上了心头。",
    s: "《一剪梅》是李清照写给丈夫赵明诚的词作，“此情无计可消除，才下眉头，却上心头”将相思之情写得生动传神，眉头刚舒展，心头又涌上愁思，把那种无法排遣的思念写得入木三分。全词语言清丽，情感真挚，是李清照婉约词的代表作。"
  },
  "醉花阴·薄雾浓云愁永昼|李清照": {
    y: "薄雾弥漫，云层浓密，日子过得郁闷愁烦，龙脑香在金兽香炉中缭袅。又到了重阳佳节，卧在玉枕纱帐中，半夜的凉气刚将全身浸透。\n在东篱边饮酒直到黄昏以后，淡淡的黄菊清香溢满双袖。此时此地怎么能不令人伤感呢？风乍起，卷帘而入，帘内的人儿因过度思念身形竟比那黄花还要瘦弱。",
    s: "《醉花阴》是李清照重阳节思念丈夫所作，“莫道不销魂，帘卷西风，人比黄花瘦”以黄花比喻人的消瘦，将相思之苦写得生动传神，成为千古传诵的名句。相传赵明诚收到此词后，闭门谢客，写了五十首词与李清照的词混在一起，请友人陆德夫品评，陆德夫说“只三句绝佳”，正是“莫道不销魂，帘卷西风，人比黄花瘦”。"
  },
  "武陵春·风住尘香花已尽|李清照": {
    y: "风停了，尘土里带有花的香气，花儿已凋落殆尽。日头已经升的老高，我却懒得来梳妆。景物依旧，人事已变，一切事情都已经完结。想要倾诉自己的感慨，还未开口，眼泪先流下来。\n听说双溪春景尚好，我也打算泛舟前去。只恐怕双溪蚱蜢般的小船，载不动我内心沉重的忧愁。",
    s: "《武陵春》是李清照南渡后的作品，“只恐双溪舴艋舟，载不动许多愁”以小船载不动愁的奇特比喻，将抽象的愁绪写得具体可感，与李煜“问君能有几多愁，恰似一江春水向东流”异曲同工。全词语言朴素，情感深沉，是李清照晚年词的代表作。"
  },
  "破阵子·为陈同甫赋壮词以寄之|辛弃疾": {
    y: "醉梦里挑亮油灯观看宝剑，梦中回到了当年的各个营垒，接连响起号角声。把烤牛肉分给部下，乐队演奏北疆歌曲。这是秋天在战场上阅兵。\n战马像的卢马一样跑得飞快，弓箭像惊雷一样，震耳离弦。我一心想替君主完成收复国家失地的大业，取得世代相传的美名。可怜已成了白发人！",
    s: "《破阵子》是辛弃疾写给好友陈亮的壮词，“醉里挑灯看剑，梦回吹角连营”开篇便写出了词人渴望收复中原的壮志，“了却君王天下事，赢得生前身后名”表达了词人的理想，结尾“可怜白发生”以壮志未酬的悲愤作结，全词气势磅礴，情感跌宕，是辛弃疾豪放词的代表作。"
  },
  "永遇乐·京口北固亭怀古|辛弃疾": {
    y: "历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛。\n然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着中原仍然记得，当年扬州路上，到处是金兵南侵的战火烽烟。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，只把他当作一位神祇来供奉，还有谁会记得，这曾是异族皇帝的行宫？还有谁会问，廉颇老了，饭量还好吗？",
    s: "《永遇乐·京口北固亭怀古》是辛弃疾晚年的代表作，也是豪放词的巅峰之作。全词借古讽今，用孙权、刘裕、刘义隆、廉颇等历史典故，抒发了自己渴望收复中原、却不被重用的悲愤。“想当年，金戈铁马，气吞万里如虎”“凭谁问：廉颇老矣，尚能饭否”都是千古传诵的名句，全词用典精当，气势雄浑，是辛弃疾词的压卷之作。"
  },
  "青玉案·元夕|辛弃疾": {
    y: "东风吹开了元宵夜的火树银花，花灯灿烂，就像千树花开。从天而降的礼花，犹如星雨。豪华的马车在飘香的街道行过。悠扬的凤箫声四处回荡，玉壶般的明月渐渐向西边倾斜，一夜鱼龙灯飞舞笑语喧哗。\n美人头上都戴着亮丽的饰物，笑语盈盈地随人群走过，身上香气飘洒。我在人群中寻找她千百回，猛然回头，不经意间却在灯火零落之处发现了她。",
    s: "《青玉案·元夕》是辛弃疾婉约词的代表作，“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”被王国维称为“古今之成大事业、大学问者”的第三境界。全词以元夕的繁华热闹反衬“那人”的孤独清高，寄托了词人不与世俗同流合污的高洁品格，意境深远，余味无穷。"
  },
  "摸鱼儿·更能消几番风雨|辛弃疾": {
    y: "淳熙己亥年，我由湖北转运副使调任湖南转运副使，同僚王正之在小山亭设酒饯行，我写下这首词。还经得起几回风雨，春天又将匆匆归去。爱惜春天我常怕花开得过早，何况此时已落红无数。春天啊，请暂且留步，听说天涯芳草已经遮断了你的归路。我埋怨春天总是默默无语。算来只有画檐下的蜘蛛网，整天殷勤地沾惹飞舞的柳絮。\n长门宫的陈皇后，本约好的佳期又被耽误。美貌的女子从来遭人嫉妒。纵然能花千金买得司马相如的赋，这脉脉深情又能向谁倾诉？你们不要得意忘形地跳舞，难道没看见杨玉环、赵飞燕都化作了尘土！无端的闲愁最是痛苦。不要去倚靠高高的栏杆，夕阳正照在烟柳迷蒙的令人断肠之处。",
    s: "《摸鱼儿》是辛弃疾婉约词的代表作，以暮春景象寄托政治感慨。“更能消、几番风雨，匆匆春又归去”以春逝暗喻南宋国势的衰微，“斜阳正在，烟柳断肠处”以景结情，余味无穷。全词比兴深婉，寄托遥深，梁启超评此词“回肠荡气，至于此极，前无古人，后无来者”。"
  },
  "西江月·夜行黄沙道中|辛弃疾": {
    y: "皎洁的月光从树枝间掠过，惊飞了枝头喜鹊，清凉的晚风吹来仿佛听见了远处的蝉叫声。田里稻花飘香，蛙声阵阵，似乎在告诉人们今年是一个丰收年。\n天边几颗星星忽明忽暗，山前下起了淅淅沥沥的小雨。往日的小茅草屋还在土地庙的树林旁，道路转过溪水的源头，它便忽然出现在眼前。",
    s: "《西江月·夜行黄沙道中》是辛弃疾描写农村风光的名作，“稻花香里说丰年，听取蛙声一片”以蛙声和稻花香写出了农村的丰收景象，充满生活气息。全词语言清新自然，意境优美，是辛弃疾农村词的代表作。"
  },
  "丑奴儿·书博山道中壁|辛弃疾": {
    y: "人年轻的时候不懂忧愁的滋味，喜欢登高远望。喜欢登高远望，为了写出新词，没有愁而硬要说有愁。\n现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说道：好个凉爽的秋天呀！",
    s: "《丑奴儿》以“少年”与“而今”的对比，写出了对“愁”的不同理解。少年时“为赋新词强说愁”，是无病呻吟；而今“识尽愁滋味”，却“欲说还休”，因为真正的愁是无法言说的。全词以浅近的语言表达了深沉的人生感慨，是辛弃疾词的名篇。"
  },
  "钗头凤·红酥手|陆游": {
    y: "你红润酥腻的手里，捧着盛上黄縢酒的杯子。满城荡漾着春天的景色，你却早已像宫墙中的绿柳那般遥不可及。春风多么可恶，将欢情吹得那样稀薄。满怀的忧愁情绪，离别几年来的生活十分萧索。遥想当初，只能感叹：错，错，错！\n春景依旧，只是人却白白相思地消瘦。泪水洗尽脸上的胭脂红，又把薄绸的手帕全都湿透。满春的桃花凋落在寂静空旷的池塘楼阁上。永远相爱的誓言还在，可是锦文书信再也难以交付。遥想当初，只能感叹：莫，莫，莫！",
    s: "《钗头凤》是陆游写给前妻唐琬的词作，讲述了陆游与唐琬的爱情悲剧。“红酥手，黄縢酒”写昔日的恩爱，“东风恶，欢情薄”写被迫分离的痛苦，“山盟虽在，锦书难托”写旧情难续的无奈。全词情感真挚，催人泪下，是中国文学史上最著名的爱情词之一。"
  },
  "卜算子·咏梅|陆游": {
    y: "驿站之外的断桥边，梅花孤单寂寞地绽开了花，无人过问。暮色降临，梅花无依无靠，已经够愁苦了，却又遭到了风雨的摧残。\n梅花并不想费尽心思去争艳斗宠，对百花的妒忌与排斥毫不在乎。即使凋零了，被碾作泥土，又化作尘土了，梅花依然和往常一样散发出缕缕清香。",
    s: "《卜算子·咏梅》是陆游咏物言志的名作，以梅花自喻，“零落成泥碾作尘，只有香如故”表达了诗人虽屡遭排挤、身处逆境，却依然坚守高洁品格的精神。全词以梅喻人，托物言志，是咏梅词中的杰作。"
  },
  "诉衷情·当年万里觅封侯|陆游": {
    y: "回想当年为了建功立业驰骋万里，单枪匹马奔赴边境戍守梁州。如今防守边疆要塞的从军生活只能在梦中出现，梦一醒不知身在何处？唯有曾穿过的貂裘，已积满灰尘变得又暗又旧。\n胡人还未消灭，自己的双鬓却早已白如秋霜，只能任忧国的眼泪白白地流淌。谁能料我这一生，心始终在前线抗敌，人却老死在沧洲！",
    s: "《诉衷情》是陆游晚年的作品，“当年万里觅封侯，匹马戍梁州”追忆了早年的抗金经历，“胡未灭，鬓先秋，泪空流”写出了壮志未酬的悲愤，“心在天山，身老沧洲”将理想与现实的矛盾写得淋漓尽致。全词情感沉郁，感人至深。"
  },
  "扬州慢·淮左名都|姜夔": {
    y: "淳熙丙申年冬至，我路过扬州。夜里初雪放晴，满眼都是荠菜麦子。进入城中，四顾萧条，寒水碧绿，暮色渐起，戍角悲鸣。我心中悲伤，感慨今昔，于是自创此曲。千岩老人认为此词有《黍离》之悲。\n扬州是淮河东边著名的大都，在竹西亭美好的住处，解下马鞍稍作停留，这是最初的路程。经过春风十里的扬州路，如今全是青青的荠麦。自从金兵进犯长江回去以后，荒废了池苑，伐去了乔木，至今还讨厌说起旧日用兵。天气渐渐到了黄昏，凄凉的号角吹起了寒气，这都是在被洗劫一空的空城中。\n杜牧有卓越的鉴赏力，料想今天重来此地一定会吃惊。即使有写“豆蔻”的精工词采，有写“青楼梦好”的才华，也难以表达出深沉的悲痛。二十四桥仍然还在，桥下江中的波浪荡漾，凄冷的月光默默无声。想桥边的红芍药，年年盛开，究竟是为谁而生呢？",
    s: "《扬州慢》是姜夔的代表作，描写了扬州经过金兵洗劫后的萧条景象，抒发了对国家衰亡的感慨。“过春风十里，尽荠麦青青”以昔日繁华与今日荒凉对比，“二十四桥仍在，波心荡，冷月无声”以景结情，余味无穷。全词意境凄清，情感深沉，是南宋婉约词的杰作。"
  },
  "暗香·旧时月色|姜夔": {
    y: "辛亥年冬天，我冒雪去拜访石湖居士。住了一个多月，他给我纸索要诗句，并要求创作新的曲调，我作了这两首曲子。石湖居士反复把玩，让歌女练习演唱，音节和谐婉转，于是命名为《暗香》《疏影》。\n昔日的月色，曾多少次照耀我，在梅花边吹笛？唤起美人，不顾清寒一起攀折梅花。何逊如今渐渐老去，都忘却了春风般的词笔。只奇怪竹外稀疏的梅花，冷香飘入华美的筵席。\n江南水乡，正一片寂静，感叹寄梅路途遥远，夜雪刚刚堆积。翠绿的酒杯前容易落泪，红梅无言，耿耿相忆。永远记得曾携手的地方，千树梅花压着西湖寒碧的湖水。如今梅花又一片片被吹尽了，什么时候才能再见到呢？",
    s: "《暗香》是姜夔自度曲的代表作，与《疏影》并为咏梅词的双璧。全词以梅花为线索，将个人身世之感与家国之恨融为一体，意境清空，情感深沉。张炎评姜夔词“如野云孤飞，去留无迹”，此词正是这种风格的典范。"
  },
  "苏幕遮·怀旧|范仲淹": {
    y: "云天蓝碧，黄叶落满地，天边秋色与秋波相连，波上弥漫着空翠略带寒意的秋烟。远山沐浴着夕阳天空连接着江水。不解思乡之苦的芳草，一直延伸到夕阳之外的天际。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，每天夜里除非是美梦才能留人入睡。当明月照射高楼时不要独自依倚，端起酒来洗涤愁肠，可是都化作相思的眼泪。",
    s: "《苏幕遮·怀旧》是范仲淹的代表作，“碧云天，黄叶地”是千古传诵的写景名句，“酒入愁肠，化作相思泪”将相思之情写得真挚动人。全词上阕写景，下阕抒情，意境开阔，情感深沉，是宋词中的佳作。"
  },
  "渔家傲·秋思|范仲淹": {
    y: "秋天到了，西北边塞的风光和江南大不同。大雁又飞回了衡阳，一点也没有停留之意。黄昏时分，号角吹起，边塞特有的风声、马啸声、羌笛声和着号角声从四面八方回响起来。连绵起伏的群山里，夕阳西下，青烟升腾，孤零零的一座城城门紧闭。\n饮一杯浊酒，不由得想起万里之外的亲人，眼下战事未平，功名未立，还不能早作归计。远方传来羌笛的悠悠之声，天气寒冷，霜雪满地。夜深了，在外征战的人都难以入睡，将军已是头发花白，士兵抹着思乡的泪水。",
    s: "《渔家傲·秋思》是范仲淹镇守西北边疆时所作，“塞下秋来风景异”开篇便写出了边塞的荒凉，“将军白发征夫泪”将将士们的思乡之情和报国之志写得深沉感人。全词意境苍凉，情感真挚，是宋词中少有的边塞词，开豪放词之先声。"
  },
  "浣溪沙·一向年光有限身|晏殊": {
    y: "人的生命是有限的，时光是短暂的，离别是容易让人销魂的。不要推辞频繁的酒筵歌席。\n空自思念远方的人，满目山河也无济于事，风雨中的落花更让人伤春。不如好好珍惜眼前的人。",
    s: "《浣溪沙·一向年光有限身》是晏殊的名作，“满目山河空念远，落花风雨更伤春。不如怜取眼前人”是千古传诵的名句，表达了珍惜当下、把握眼前的人生态度。全词语言清丽，情感深沉，是晏殊婉约词的代表作。"
  },
  "破阵子·春景|晏殊": {
    y: "燕子飞来正赶上社祭之时，梨花落了之后就是清明。池塘边点缀着几点青苔，树叶底下传来一两声黄鹂的啼叫。白日渐长，柳絮轻盈地飞舞。\n东邻的少女们笑得天真烂漫，在采桑的路上相遇。怪不得昨夜做了个好梦，原来是今天斗草赢了。笑容从双颊上绽开。",
    s: "《破阵子·春景》是晏殊描写春日少女生活的词作，“池上碧苔三四点，叶底黄鹂一两声”以细腻的笔触写出了春日的生机，“笑从双脸生”将少女的天真快乐写得生动传神。全词语言明快，充满生活气息，是晏殊词中少有的轻快之作。"
  },
  "蝶恋花·庭院深深深几许|欧阳修": {
    y: "庭院深深，不知有多深？杨柳依依，飞扬起片片烟雾，一重重帘幕不知有多少层。豪华的车马停在贵族公子寻欢作乐的地方，登上高楼也望不见通向章台的大路。\n风狂雨骤的暮春三月，再是重门将黄昏景色掩闭，也无法留住春意。泪眼汪汪问落花可知道我的心意，落花默默不语，纷乱的，零零落落一点一点飞到秋千外。",
    s: "《蝶恋花·庭院深深深几许》是欧阳修的名作，“庭院深深深几许”以三个“深”字渲染了闺房的幽深，“泪眼问花花不语，乱红飞过秋千去”以花的无情反衬人的多情，将闺怨写得含蓄深沉。全词意境凄清，情感细腻，是婉约词的佳作。"
  },
  "玉楼春·尊前拟把归期说|欧阳修": {
    y: "饯行的酒席前就想先把归期说定，一杯心切情切，欲说时佳人无语滴泪，如春风妩媚的娇容，先自凄哀低咽。啊，人生自是有情，情到深处痴绝，这凄凄别恨不关涉楼头的清风与中天的明月。\n饯别的酒宴前，不要再唱新的离歌了，一曲离歌能让人愁肠寸结。啊，此时只需要看遍洛阳城的牡丹，才能够和春风轻松地告别。",
    s: "《玉楼春·尊前拟把归期说》是欧阳修的名作，“人生自是有情痴，此恨不关风与月”是千古传诵的名句，将离别的愁恨归于人的多情，而非风月的无情。全词情感真挚，语言清丽，是欧阳修婉约词的代表作。"
  },
  "浪淘沙·把酒祝东风|欧阳修": {
    y: "端起酒杯向东风祈祷，请你再留些时日不要匆匆离去。洛阳城东郊外的小道已是柳枝满垂。大多是我们去年携手同游的地方，我们游遍了姹紫嫣红的花丛。\n人生的欢聚与别离总是苦短，这遗憾无穷无尽。今年的花比去年开得更红。可惜明年的花会更好，不知又能和谁一同欣赏？",
    s: "《浪淘沙·把酒祝东风》是欧阳修的名作，“今年花胜去年红。可惜明年花更好，知与谁同”以花的年年盛开，反衬人事的聚散无常，将对友人的思念写得含蓄深沉。全词语言清丽，情感真挚，是欧阳修婉约词的代表作。"
  },
  "采桑子·轻舟短棹西湖好|欧阳修": {
    y: "西湖风光好，驾轻舟划短桨多么逍遥。碧绿的湖水绵延不断，长堤上花草散出芳香。隐隐传来的音乐歌唱，像是随着船儿在湖上飘荡。\n无风的水面，光滑得好似琉璃一样，不觉得船儿在前进，只见微微的细浪在船边荡漾。看，被船儿惊起的水鸟，正掠过湖岸在飞翔。",
    s: "《采桑子·轻舟短棹西湖好》是欧阳修描写颍州西湖的组词之一，“无风水面琉璃滑，不觉船移”以细腻的笔触写出了西湖的宁静之美，“微动涟漪，惊起沙禽掠岸飞”以动写静，意境优美。全词语言清丽，充满生活气息。"
  },
  "桂枝香·金陵怀古|王安石": {
    y: "我登上城楼放眼远望，故都金陵正是深秋，天气已变得飒爽清凉。千里澄江宛如一条白练，青翠山峰像箭簇耸立前方。帆船在夕阳下往来穿梭，西风起处，斜插着的酒旗高高飘扬。画船如同在淡云中浮游，白鹭好像在银河里飞舞，丹青妙笔也难描画这壮美风光。\n遥想当年，故都金陵何等繁盛堂皇。可叹在朱雀门外结绮阁楼，六朝君主一个个地相继败亡。自古多少人在此登高怀古，无不对历代荣辱喟叹感伤。六朝旧事已随流水消逝，剩下的只有寒烟惨淡、绿草衰黄。直到如今的商女，还不知亡国的悲恨，时时放声歌唱《后庭》遗曲。",
    s: "《桂枝香·金陵怀古》是王安石的代表作，“千里澄江似练，翠峰如簇”写出了金陵的壮丽景色，“至今商女，时时犹唱，后庭遗曲”借古讽今，表达了对国家命运的忧虑。全词意境开阔，寓意深刻，是宋词中怀古的杰作，苏轼曾赞叹“此老乃野狐精也”。"
  },
  "临江仙·梦后楼台高锁|晏几道": {
    y: "深夜梦回楼台朱门紧锁，宿酒醒后帘幕重重低垂。去年的春恨涌上心头时，人在落花纷扬中幽幽独立，燕子在微风细雨中双双翱飞。\n记得与小蘋初次相见，她穿着绣有两重心字的罗衣。琵琶轻弹，声声诉说相思之情。当时的明月如今还在，曾经照着她像彩云一样归去。",
    s: "《临江仙·梦后楼台高锁》是晏几道的代表作，“落花人独立，微雨燕双飞”以工整的对仗写出了孤独与相思，“当时明月在，曾照彩云归”以明月和彩云比喻往事，将对恋人的思念写得含蓄深沉。全词意境优美，情感真挚，是婉约词的杰作。"
  },
  "鹧鸪天·彩袖殷勤捧玉钟|晏几道": {
    y: "你挥舞彩袖手捧酒杯殷勤劝酒，回想当年心甘情愿地醉倒在你的红颜中。翩翩起舞，舞到杨柳梢头的月亮西沉，尽情歌唱，唱到桃花扇底的风都停歇。\n自从离别后，总想重相逢，多少回你我在梦中重逢。今夜我反复把银灯照亮，只怕这次相逢又是在梦中。",
    s: "《鹧鸪天·彩袖殷勤捧玉钟》是晏几道的代表作，“舞低杨柳楼心月，歌尽桃花扇底风”以工整的对仗写出了昔日欢聚的欢乐，“今宵剩把银釭照，犹恐相逢是梦中”将久别重逢的惊喜写得真挚动人。全词情感真挚，语言清丽，是婉约词的杰作。"
  },
  "卜算子·送鲍浩然之浙东|王观": {
    y: "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。要是到江南赶上春天，千万要把春天的景色留住。",
    s: "《卜算子·送鲍浩然之浙东》是王观的名作，“水是眼波横，山是眉峰聚”以美人的眼波和眉峰比喻山水，构思巧妙，“若到江南赶上春，千万和春住”将送别与迎春结合，表达了对友人的祝福。全词语言清丽，构思新颖，是宋词中的佳作。"
  },
  "水调歌头·黄州快哉亭赠张偓佺|苏轼": {
    y: "落日中卷起绣帘眺望，亭下江水与碧空相接，远处的夕阳与亭台相映，空阔无际。为了我的来到，你特意在窗户上涂上了清油的朱漆，色彩犹新。这让我想起当年在平山堂的时候，靠着枕席，欣赏江南的烟雨，遥望远方天际孤鸿出没的情景。今天看到眼前的景象，我方体会到欧阳醉翁词句中所描绘的，山色若隐若现的景致。\n广阔的水面十分明净，山峰翠绿的影子倒映其中。忽然江面波涛汹涌，一个渔翁驾着小舟在风浪中掀舞。见此不由得想起了宋玉的《风赋》，像宋玉这样可笑的人，是不可能理解庄子的风是天籁之说的，硬说什么风有雄雌。其实，一个人只要具备至大至刚的浩然之气，就能在任何境遇中都处之泰然，享受到无穷快意的千里雄风。",
    s: "《水调歌头·黄州快哉亭赠张偓佺》是苏轼的代表作，“一点浩然气，千里快哉风”是千古传诵的名句，表达了诗人旷达超脱的人生态度。全词将写景、抒情、议论融为一体，意境开阔，气势磅礴，是苏轼豪放词的代表作。"
  },
  "浣溪沙·游蕲水清泉寺|苏轼": {
    y: "游玩蕲水的清泉寺，寺庙在兰溪的旁边，溪水向西流淌。\n山脚下兰草新抽的幼芽浸润在溪水中，松林间的沙路被雨水冲洗得一尘不染，傍晚时分，细雨萧萧，传来子规的声声啼叫。\n谁说人生就不能再回到少年时期？门前的溪水都还能向西边流淌！不要在老年感叹时光的飞逝啊！",
    s: "《浣溪沙·游蕲水清泉寺》是苏轼被贬黄州时所作，“谁道人生无再少？门前流水尚能西！休将白发唱黄鸡”以溪水西流的现象，表达了老当益壮、积极进取的人生态度。全词意境清新，格调高昂，是苏轼婉约词中的佳作。"
  },
  "蝶恋花·春景|苏轼": {
    y: "花儿残红褪尽，树梢上长出了小小的青杏。燕子飞舞，清澈的河流围绕着村落人家。柳枝上的柳絮已被吹得越来越少，但不要担心，到处都可见茂盛的芳草。\n围墙里面，有一位少女正在荡秋千，墙外的行人都可听见。少女发出动听的笑声，慢慢地，围墙里边的笑声就听不见了，行人惘然若失，仿佛多情的自己被无情的少女所伤害。",
    s: "《蝶恋花·春景》是苏轼的名作，“天涯何处无芳草”是千古传诵的名句，“多情却被无情恼”将单相思的苦恼写得生动有趣。全词语言清丽，意境优美，是苏轼婉约词的代表作。"
  },
  "满庭芳·蜗角虚名|苏轼": {
    y: "微小的虚名，微薄的小利，算来有什么值得忙碌的。凡事都已前定，谁弱谁强又怎样。且趁现在身体还未衰老，让我放浪一些，疏狂一些。百年之中，就算都让我醉，也不过三万六千场。\n细想，人生能有多少时间，忧愁风雨，就占去了一半，又何必拼命去说短论长。有幸面对清风皓月，以苔藓为席，以云幕为帐。江南好啊，千钟美酒，一曲满庭芳。",
    s: "《满庭芳·蜗角虚名》是苏轼的代表作，“蜗角虚名，蝇头微利”以比喻手法写出了名利的微不足道，表达了诗人对名利的淡泊和对自由生活的向往。全词语言旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "行香子·述怀|苏轼": {
    y: "清静的夜晚没有尘埃，月色如银。斟酒时，要斟满十分。浮名浮利，白白地劳神费力。感叹时光如白驹过隙，如击石迸出的火花，如梦中之身。\n虽然怀抱文章之才，开口又有谁亲近。姑且欢乐，尽享天真。什么时候归去，做个闲人。对着一张琴，一壶酒，一溪云。",
    s: "《行香子·述怀》是苏轼的名作，“对一张琴，一壶酒，一溪云”以极简练的笔墨写出了隐居生活的美好，表达了诗人对自由生活的向往。全词语言清丽，意境悠远，是苏轼婉约词的佳作。"
  },
  "定风波·南海归赠王定国侍人寓娘|苏轼": {
    y: "常常羡慕这世间如玉雕琢般丰神俊朗的男子，就连上天也怜惜他，赠予他柔美聪慧的佳人与之相伴。人人称道那女子歌声轻妙，笑容柔美，风起时，那歌声如雪片飞过炎热的夏日使世界变得清凉。\n你从遥远的地方归来却看起来更加年轻了，笑容依旧，笑颜里好像还带着岭南梅花的清香。我问你：“岭南的风土应该不是很好吧？”你却坦然答道：“心安定的地方，便是我的故乡。”",
    s: "《定风波·南海归赠王定国侍人寓娘》是苏轼的名作，“此心安处是吾乡”是千古传诵的名句，表达了随遇而安、旷达超脱的人生态度。全词通过对寓娘的描写，展现了苏轼的人生哲学，语言清丽，情感真挚。"
  },
  "玉蝴蝶·望处雨收云断|柳永": {
    y: "望着雨收云散的天空，我默默凭倚栏杆，目送秋日的时光渐渐远去。晚景萧瑟凄凉，足以引起宋玉那样的悲凉。水面风轻，蘋花渐渐老去，月光露水寒冷，梧桐叶飘黄。这情景让人感伤。故人在哪里，烟水茫茫。\n难忘，我们一起饮酒赋诗的聚会，多少次辜负了风月，多少次变换了星霜。海阔山遥，不知哪里是潇湘。想那双燕，难以凭它们传递远信，指着暮色的天空，空自辨认归航的船。黯然相望。在孤雁的哀鸣声中，我一直站到夕阳西下。",
    s: "《玉蝴蝶·望处雨收云断》是柳永的名作，“故人何在，烟水茫茫”以景结情，将对故人的思念写得含蓄深沉，“断鸿声里，立尽斜阳”以孤雁和夕阳衬托诗人的孤独。全词意境凄清，情感深沉，是柳永慢词的佳作。"
  },
  "少年游·长安古道马迟迟|柳永": {
    y: "在长安古道上骑马缓行，高高的柳树上蝉声纷乱。夕阳在飞鸟之外，秋风在原野之上，极目远望，天幕四垂。\n归云一去没有踪迹，哪里是以前的约期？游冶的兴致已经生疏，酒友也稀少，不像少年时那样了。",
    s: "《少年游·长安古道马迟迟》是柳永的名作，“夕阳鸟外，秋风原上，目断四天垂”以极简练的笔墨写出了秋日的苍茫，“狎兴生疏，酒徒萧索，不似少年时”将人生的沧桑写得深沉感人。全词意境苍凉，情感真挚，是柳永小令的佳作。"
  },
  "鹤冲天·黄金榜上|柳永": {
    y: "在金字题名的榜上，我偶然失去了状元的希望。在圣明的时代暂时遗漏了贤才，该怎么办呢？没有得到好的机遇，怎能不恣意狂荡。何必计较得失？才子词人，自然就是白衣卿相。\n在烟花巷陌里，依约有丹青屏障。幸好有中意的人，可以去寻访。就这样偎红倚翠，风流事，是平生的畅快。青春不过片刻。忍心把浮名，换成了浅斟低唱。",
    s: "《鹤冲天·黄金榜上》是柳永科举落第后所作，“忍把浮名，换了浅斟低唱”表达了对科举功名的蔑视和对自由生活的向往，相传宋仁宗因此批“且去浅斟低唱，何要浮名”，柳永遂自称“奉旨填词柳三变”。全词情感奔放，语言率真，是柳永个性的集中体现。"
  },
  "忆帝京·薄衾小枕凉天气|柳永": {
    y: "小枕薄被，天气凉爽，忽然尝到了离别的滋味。辗转反侧数着寒夜的更鼓，起来了又重新睡下。毕竟不能成眠，一夜长得像一年。\n也打算勒转马头回去。又怎奈已经定下了出行的计划。万种思量，多方开解，只落得寂寞无聊。系住我一生的心，辜负了你千行眼泪。",
    s: "《忆帝京·薄衾小枕凉天气》是柳永的名作，“系我一生心，负你千行泪”以工整的对仗写出了爱情的真挚与离别的痛苦，是千古传诵的名句。全词语言朴素，情感真挚，是柳永婉约词的佳作。"
  },
  "诉衷情·芙蓉金菊斗馨香|晏殊": {
    y: "芙蓉和金菊争香斗艳，天气快要到重阳了。远处的村庄秋色如画，红叶树间夹杂着疏黄。\n流水淡远，碧天辽阔，道路茫茫。登高远望，鸿雁飞来时，引起无限思量。",
    s: "《诉衷情·芙蓉金菊斗馨香》是晏殊的名作，描写了秋日的美丽景色和登高怀远的情思。“芙蓉金菊斗馨香”写出了秋日的生机，“凭高目断，鸿雁来时，无限思量”将思乡之情写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "清平乐·红笺小字|晏殊": {
    y: "精美的红格信笺写满了密密的小字，写尽了我一生的情意。鸿雁在云端，鱼在水中，惆怅的是这份情意难以传递。\n夕阳西下，我独自倚在西楼，远山正对着帘钩。不知那人如今在何处，绿波依旧向东流去。",
    s: "《清平乐·红笺小字》是晏殊的名作，“鸿雁在云鱼在水，惆怅此情难寄”以鸿雁和鱼的典故，写出了书信难寄的惆怅，“人面不知何处，绿波依旧东流”以景结情，将物是人非的感慨写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "木兰花·春景|宋祁": {
    y: "漫步东城感受到风光越来越好，船儿行驶在波纹骤起的水面上。拂晓的轻寒笼罩着如烟的杨柳，惟见那红艳艳的杏花簇绽枝头，春天的意趣热闹非凡。\n人生总是怨恨欢乐太少，谁愿意吝惜千金而轻视欢笑呢。让我为你举起酒杯奉劝斜阳，请留下来把晚花照耀。",
    s: "《木兰花·春景》是宋祁的代表作，“红杏枝头春意闹”以一个“闹”字将春天的生机写得淋漓尽致，宋祁也因此被称为“红杏枝头春意闹尚书”。全词意境优美，情感真挚，是宋词中的佳作。"
  },
  "天仙子·水调数声持酒听|张先": {
    y: "手持酒杯听着《水调》曲，午醉醒来愁还没醒。送走了春天，春天什么时候回来？傍晚照镜，感伤流逝的光景，往事和未来的约定都空自记在心里。\n沙滩上鸳鸯并栖，池塘上暮色降临，云破月出，花影摇曳。重重帘幕密密遮住灯光，风不定，人刚静，明天落花应该铺满了小路。",
    s: "《天仙子·水调数声持酒听》是张先的代表作，“云破月来花弄影”以一个“弄”字将花影写得生动传神，张先也因此被称为“云破月来花弄影郎中”。全词意境优美，情感细腻，是宋词中的佳作。"
  },
  "青门引·春思|张先": {
    y: "天气刚刚变暖还有些微冷，风雨到傍晚才停。庭院寂寞，将近清明，对着残花饮酒，又犯了去年的病。\n楼头的画角声被风吹醒，入夜后重门寂静。哪能忍受，明月又把隔墙的秋千影送过来。",
    s: "《青门引·春思》是张先的名作，“那堪更被明月，隔墙送过秋千影”以明月和秋千影，将相思之情写得含蓄深沉。全词意境凄清，情感细腻，是宋词中的佳作。"
  },
  "剪牡丹·舟中闻双琵琶|张先": {
    y: "野外的绿色连着天空，青天垂到水面，白色的水光荡漾都很明净。柳树下的小路没有人，柳絮飘落飞无影。汀洲上日落人归，长巾薄袖，采香拾翠竞相游玩。好像懂得凌波微步，停泊在烟渚的春夜。\n彩绦朱索刚刚整理好。宿在绣屏边，画船上风已定。金凤凰响在双槽上，弹出今古的幽思谁能领会。玉盘大小乱珠迸溅。酒上了妆面，花艳和媚相并。再听。弹尽汉妃一曲，江空月静。",
    s: "《剪牡丹·舟中闻双琵琶》是张先的名作，描写了舟中听琵琶的情景。“玉盘大小乱珠迸”以比喻手法写出了琵琶声的美妙，“江空月静”以景结情，余味无穷。全词意境优美，描写细腻，是宋词中的佳作。"
  },
  "相思令·吴山青|林逋": {
    y: "吴山青翠，越山青翠，两岸的青山迎送着行人，谁知道离别的情意？\n你泪流满面，我泪流满面，罗带的同心结还没结成，江边的潮水已经平了。",
    s: "《相思令·吴山青》是林逋的名作，以民歌的笔调描写了离别的悲伤。“吴山青，越山青”以重叠的句式写出了江南的秀美，“罗带同心结未成”将爱情的遗憾写得真挚动人。全词语言朴素，情感真挚，是宋词中的佳作。"
  },
  "点绛唇·感兴|王禹偁": {
    y: "雨绵绵，云愁闷，江南依然称得上美丽。水村渔市，一缕孤烟细细升起。\n天边的大雁，远远看去行列相连。平生的事，此时凝神注视，谁能理解我凭栏的心意。",
    s: "《点绛唇·感兴》是王禹偁的名作，“天际征鸿，遥认行如缀”以大雁比喻自己的志向，“谁会凭栏意”将怀才不遇的感慨写得含蓄深沉。全词意境开阔，情感深沉，是宋初词的佳作。"
  },
  "酒泉子·长忆观潮|潘阆": {
    y: "常常回忆观潮的情景，满城的人争着到江上眺望。潮水来时，怀疑沧海全都空了，万面鼓声中。\n弄潮儿站在浪头上，手举红旗，红旗不被水打湿。离别后几次在梦中看到，梦醒还心有余悸。",
    s: "《酒泉子·长忆观潮》是潘阆的名作，描写了钱塘江大潮的壮观景象。“来疑沧海尽成空，万面鼓声中”以夸张手法写出了潮水的磅礴气势，“弄潮儿向涛头立，手把红旗旗不湿”写出了弄潮儿的英勇。全词气势磅礴，是宋词中少有的描写大潮的作品。"
  },
  "苏幕遮·碧云天|范仲淹": {
    y: "云天蓝碧，黄叶落满地，天边秋色与秋波相连，波上弥漫着空翠略带寒意的秋烟。远山沐浴着夕阳天空连接着江水。不解思乡之苦的芳草，一直延伸到夕阳之外的天际。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，每天夜里除非是美梦才能留人入睡。当明月照射高楼时不要独自依倚，端起酒来洗涤愁肠，可是都化作相思的眼泪。",
    s: "《苏幕遮·碧云天》是范仲淹的代表作，“碧云天，黄叶地”是千古传诵的写景名句，王实甫《西厢记》中“碧云天，黄花地”即由此化用。“酒入愁肠，化作相思泪”将相思之情写得真挚动人。全词上阕写景，下阕抒情，意境开阔，情感深沉。"
  },
  "御街行·秋日怀旧|范仲淹": {
    y: "纷纷飘落的树叶，在香阶上堆积，夜色寂静，寒声细碎。珍珠帘子卷起，玉楼空寂，天色清淡，银河垂地。年年今夜，月光如白练，总是人在千里之外。\n愁肠已断，无法喝醉，酒还没到，先化成了泪。残灯明灭，枕头倾斜，尝尽了孤眠的滋味。这些事，眉间心上，没有办法回避。",
    s: "《御街行·秋日怀旧》是范仲淹的名作，“年年今夜，月华如练，长是人千里”以月光的永恒反衬人的分离，“都来此事，眉间心上，无计相回避”将相思之情写得真挚动人。全词意境凄清，情感深沉，是宋词中的佳作。"
  },
  "满庭芳·山抹微云|秦观": {
    y: "会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，连绵无穷。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情爱的往事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。",
    s: "《满庭芳·山抹微云》是秦观的代表作，秦观也因此被称为“山抹微云君”。“山抹微云，天连衰草”以极简练的笔墨写出了秋日的苍茫，“斜阳外，寒鸦万点，流水绕孤村”化用隋炀帝诗句，意境优美。全词将离别之情写得真挚动人，是婉约词的杰作。"
  },
  "定风波·自春来|柳永": {
    y: "自从春天以来，绿叶红花都让人发愁，芳心对什么事都漫不经心。太阳升到花梢，黄莺穿过柳带，还压着香被躺着。肌肤消瘦，头发散乱，整天懒得梳妆。无奈。恨薄情郎一去，连个音信都没有。\n早知道这样，后悔当初没把他的马鞍锁住。在书房里，只给他纸和笔，管束着让他吟诗学习。永远相随，不要抛躲，闲着时拿着针线陪他坐着。和我在一起，免得年少时光白白度过。",
    s: "《定风波·自春来》是柳永的名作，以市井女子的口吻，描写了对丈夫的思念和对平凡夫妻生活的向往。“针线闲拈伴伊坐”写出了女子对温馨生活的渴望，相传晏殊曾以此词讥讽柳永。全词语言通俗，情感真挚，是柳永俚词的代表作。"
  },
  "戚氏·晚秋天|柳永": {
    y: "时值深秋，短促的细雨洒落在庭院栏干前。栏边的菊花稀疏，井边的梧桐叶零乱，惹起残烟。凄凉啊，远望江山关隘，飞云暗淡在夕阳之间。当年宋玉悲秋，对着此景临水登山。远道迢迢，行人凄楚，听厌了陇水潺潺。正是蝉在败叶中吟唱，蟋蟀在衰草中鸣叫，相互应和，喧闹不停。\n孤馆中，度日如年。风露渐渐变凉，悄悄到了更深夜阑。长天明净，银河清浅，皓月明媚。思绪绵绵。长夜对景，哪能忍受屈指暗想从前。没有功名没有利禄，在绮陌红楼中，往往一年年拖延。\n京城风光好，当年少的时候，朝朝暮暮宴饮欢乐。何况有狂放怪异的朋友，遇到对酒当歌就竞相留连。别来时光如梭，旧游似梦，烟水路程多么遥远。想名利，憔悴地长久萦绕牵绊。追念往事，空自愁容惨淡。漏箭移动，渐渐觉得微寒。渐渐呜咽，画角几声残响。对着闲窗，灯灭到天亮，抱着影子无眠。",
    s: "《戚氏》是柳永最长的词调，共212字，是柳永慢词的代表作。全词以凄清的秋景衬托游子的思乡之情和对往事的回忆，“念名利，憔悴长萦绊”道尽了为名利奔波的辛酸。全词结构宏大，情感深沉，是宋词中慢词的杰作。"
  },
  "夜半乐·冻云黯淡天气|柳永": {
    y: "寒云暗淡的天气，我乘一叶扁舟，乘兴离开江渚。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，山风忽然吹起，又听到商旅相互呼唤。船帆高高举起，画船轻快地驶过南浦。\n望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰杨掩映，岸边两两三三，是浣纱的游女。躲避行人，含羞笑着相互说话。\n到此因此思念，轻易抛弃了绣阁中的佳人，像浪萍一样难以停留。感叹后约的叮咛究竟有什么凭据。离怀凄惨，空自恨岁晚归期受阻。泪眼凝望，遥远的京城路。孤雁声远，长天暮色。",
    s: "《夜半乐》是柳永的长调名作，全词分三片，描写了舟行所见的江南景色和对佳人的思念。“败荷零落，衰杨掩映，岸边两两三三，浣纱游女”以细腻的笔触写出了江南水乡的生活气息，“断鸿声远长天暮”以景结情，余味无穷。全词意境优美，是柳永慢词的佳作。"
  },
  "玉楼春·春恨|晏殊": {
    y: "在绿杨芳草的长亭路上，年少的人轻易地抛下我离去。楼头的残梦被五更钟惊醒，花底的离愁像三月的雨。\n无情的人不像多情的人那样痛苦，一寸相思还能变成千万缕。天涯地角总有尽头，只有相思没有尽头。",
    s: "《玉楼春·春恨》是晏殊的名作，“无情不似多情苦，一寸还成千万缕”以对比手法写出了多情的痛苦，“天涯地角有穷时，只有相思无尽处”以夸张手法写出了相思的无穷无尽。全词情感真挚，语言清丽，是晏殊婉约词的代表作。"
  },
  "踏莎行·小径红稀|晏殊": {
    y: "小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。",
    s: "《踏莎行·小径红稀》是晏殊的名作，“春风不解禁杨花，濛濛乱扑行人面”以拟人手法写春风，生动有趣，“一场愁梦酒醒时，斜阳却照深深院”以景结情，将闲愁写得含蓄深沉。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "清平乐·金风细细|晏殊": {
    y: "微微的秋风细细吹，梧桐叶一片片坠下。初尝绿酒人容易醉，在小窗下枕着浓睡。\n紫薇和朱槿花都残了，斜阳正照着栏杆。双燕将要归去的时节，银屏昨夜微微寒冷。",
    s: "《清平乐·金风细细》是晏殊的名作，以细腻的笔触描写了秋日的闲愁。“金风细细，叶叶梧桐坠”写出了秋日的萧瑟，“双燕欲归时节，银屏昨夜微寒”以双燕归巢反衬人的孤独。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "浣溪沙·小阁重帘有燕过|晏殊": {
    y: "小楼的重重帘幕间有燕子飞过，晚花的红瓣落在庭院的莎草上。曲折的栏杆影子映入凉波。\n一阵好风吹动翠幕，几回疏雨滴在圆荷上。酒醒人散，得到的愁更多。",
    s: "《浣溪沙·小阁重帘有燕过》是晏殊的名作，以细腻的笔触描写了暮春的景色和闲愁。“几回疏雨滴圆荷”以疏雨滴荷的细节，写出了环境的清幽，“酒醒人散得愁多”将闲愁写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "诉衷情·眉意|欧阳修": {
    y: "清晨卷起帘幕，看到轻霜，呵着暖手试着画梅妆。都是因为自己有离恨，所以把眉毛画得像远山一样长。\n思念往事，惋惜流逝的芳华，容易成伤。想要唱歌先收敛，想要笑又皱眉，最让人断肠。",
    s: "《诉衷情·眉意》是欧阳修的名作，以女子画眉的细节，描写了离恨之深。“都缘自有离恨，故画作远山长”将离恨融入画眉的动作中，构思巧妙，“拟歌先敛，欲笑还颦，最断人肠”将女子的复杂心理写得生动传神。全词情感细腻，是婉约词的佳作。"
  },
  "南歌子·凤髻金泥带|欧阳修": {
    y: "凤凰发髻上束着金泥带，龙纹玉掌梳插在发间。走到窗下笑着相扶，爱问画眉深浅合不合时宜？\n依偎着人摆弄笔很久，初次试着描花。轻易耽误了绣花功夫，笑着问鸳鸯两个字怎么写？",
    s: "《南歌子·凤髻金泥带》是欧阳修的名作，以细腻的笔触描写了新婚夫妇的甜蜜生活。“爱道画眉深浅入时无”化用朱庆余诗句，“笑问鸳鸯两字怎生书”将少女的娇羞写得生动传神。全词语言明快，充满生活气息，是欧阳修词中少有的轻快之作。"
  },
  "临江仙·夜归临皋|苏轼": {
    y: "夜里在东坡饮酒，醉而复醒，醒了又饮。回来的时候仿佛已经三更。家里的童仆早已睡熟鼾声如雷鸣。反复敲门里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n长恨身在宦途，这身子已不是我自己所有。什么时候能忘却为功名利禄而奔竞钻营！夜深了，风停了，江面上的水波也平静下来。真想乘上小船从此消逝，在江河湖海中了却余生。",
    s: "《临江仙·夜归临皋》是苏轼被贬黄州时所作，“小舟从此逝，江海寄余生”表达了诗人对自由生活的向往，相传苏轼写此词后，“挂冠服江边，拏舟长啸去矣”，太守徐君猷闻之大惊，以为苏轼逃走。全词意境旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "西江月·平山堂|苏轼": {
    y: "我三次经过平山堂下，半生在弹指声中过去了。十年没见老仙翁欧阳修了，墙壁上他的字迹还龙蛇飞动。\n想要悼念文章太守欧阳修，仍然歌唱他的杨柳春风。不要说万事转头就空，没转头的时候也都是梦。",
    s: "《西江月·平山堂》是苏轼经过扬州平山堂时，为悼念恩师欧阳修而作。“壁上龙蛇飞动”写出了欧阳修书法的雄健，“休言万事转头空，未转头时皆梦”表达了对人生的深刻感悟。全词情感真挚，意境旷达，是苏轼婉约词的佳作。"
  },
  "阮郎归·初夏|苏轼": {
    y: "绿槐高柳上，新蝉的鸣叫声咽住了，和暖的南风刚刚入弦。碧纱窗下，水沉香的烟袅袅升起，下棋声惊醒了午睡。\n微雨过后，小荷叶翻卷，石榴花开得像要燃烧。玉盆中纤手拨弄清泉，水珠碎了又圆。",
    s: "《阮郎归·初夏》是苏轼描写初夏景色的词作，“榴花开欲然”以夸张手法写出了石榴花的鲜艳，“玉盆纤手弄清泉，琼珠碎却圆”以细腻的笔触写出了少女戏水的情景。全词色彩明丽，充满生活气息，是苏轼婉约词的佳作。"
  },
  "贺新郎·乳燕飞华屋|苏轼": {
    y: "小燕子飞落在华丽的房屋上，静悄悄无人，梧桐阴转到正午，傍晚凉爽，刚洗过澡。手拿着生丝白团扇，扇和手一时都像玉一样。渐渐困倦倚着，孤眠清熟。帘外谁来推绣户？枉自让人梦断瑶台曲。又却是，风敲竹子。\n石榴花半开，像红巾皱起，等浮花浪蕊都谢尽，陪伴你幽独。浓艳的一枝仔细看，芳心千重像束起来。又恐怕被秋风惊绿。如果等得你来到这里，花前对酒不忍触碰。和粉泪一起，两厢簌簌落下。",
    s: "《贺新郎·乳燕飞华屋》是苏轼的咏物词代表作，以石榴花比喻美人，“待浮花浪蕊都尽，伴君幽独”写出了石榴花的高洁，“共粉泪，两簌簌”将花与人融为一体，意境凄美。全词托物言志，情感深沉，是苏轼婉约词的杰作。"
  },
  "永遇乐·明月如霜|苏轼": {
    y: "明月如霜，好风如水，清景无限。曲折的港湾里鱼儿跳跃，圆圆的荷叶上露珠滚落，寂寞无人看见。三更鼓声响起，一片叶子铿然落下，黯黯的梦云被惊断。夜色茫茫，重寻无处，醒来后把小园走遍。\n天涯的倦客，山中的归路，望断了故园的视线。燕子楼空，佳人在哪里，空锁住楼中的燕子。古今如梦，何曾从梦中醒来，只有旧欢新怨。他日对着黄楼夜景，会为我长叹。",
    s: "《永遇乐·明月如霜》是苏轼夜宿燕子楼时所作，“燕子楼空，佳人何在，空锁楼中燕”是千古传诵的名句，将对历史的感慨写得含蓄深沉。全词意境凄清，情感深沉，是苏轼婉约词的杰作，晁补之称“燕子楼空，佳人何在，空锁楼中燕”为“三句说尽张建封事”。"
  },
  "洞仙歌·冰肌玉骨|苏轼": {
    y: "冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹开，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n起来携着她的纤纤素手，走到无声的庭院，时时看到稀疏的星星渡过银河。试问夜有多深？已经是三更时分，月光淡了，玉绳星低低转动。屈指算西风几时吹来，又不道流年在暗中偷偷变换。",
    s: "《洞仙歌·冰肌玉骨》是苏轼根据蜀主孟昶与花蕊夫人的故事改写的词作，“冰肌玉骨，自清凉无汗”写出了花蕊夫人的清丽，“但屈指西风几时来，又不道流年暗中偷换”将时光流逝的感慨写得含蓄深沉。全词意境优美，情感细腻，是苏轼婉约词的佳作。"
  },
  "天净沙·秋思|马致远": {
    y: "枯萎的藤蔓，苍老的古树，黄昏时归巢的乌鸦；小桥下溪水潺潺，旁边有几户人家；古老的道路上，萧瑟的西风里，走着一匹疲惫的瘦马。夕阳向西边落下，漂泊在外的游子，还远在天涯，愁肠寸断。",
    s: "《天净沙·秋思》被称为“秋思之祖”，仅用28个字，便勾勒出一幅苍凉的秋日羁旅图。全曲无一“愁”字，却字字含愁，情景交融，是元曲中最广为人知的作品，也是中国古典诗歌中描写乡愁的巅峰之作。"
  },
  "汉宫秋·第三折（节选）|马致远": {
    y: "呀！我面对着这辽阔荒凉的原野，草已经变黄，野兔早已遇上了秋霜。猎狗褪了毛变得苍灰，战士们扛起了缨枪，马驮着行装，车运着干粮，打猎的围场已经布置好。她伤心地辞别汉主，我携着手送她到河梁。她的随从进入了荒凉的远方，我的车驾返回咸阳。返回咸阳，经过宫墙；经过宫墙，绕着回廊；绕着回廊，靠近椒房；靠近椒房，月色昏黄；月色昏黄，夜里生凉；夜里生凉，寒蝉悲泣；寒蝉悲泣，绿纱窗下；绿纱窗下，怎能不思念！",
    s: "《汉宫秋》是马致远的杂剧代表作，写王昭君出塞的故事。这段曲词以顶真手法，从“返咸阳”到“不思量”，层层递进，将汉元帝回宫后对王昭君的思念写得缠绵悱恻，是元曲中最著名的唱段之一。"
  },
  "山坡羊·潼关怀古|张养浩": {
    y: "群山好像从四面八方聚集而来，黄河的波涛汹涌澎湃，像在发怒；潼关外有黄河，内有华山，地势十分险要。遥望古都长安，思绪起伏，久久不能平静。令人伤心的是，当年秦汉盛世的地方，万间宫殿都早已化作了尘土。国家兴盛的时候，受苦的是百姓；国家灭亡的时候，受苦的还是百姓。",
    s: "《山坡羊·潼关怀古》是元曲中怀古咏史的代表作，作者行经潼关，目睹历代王朝兴衰遗迹，发出了穿透历史的深沉慨叹。结尾“兴，百姓苦；亡，百姓苦”八字，道尽了封建时代百姓的命运，极具思想深度，在抖音等平台被广泛引用。"
  },
  "一枝花·不伏老（节选）|关汉卿": {
    y: "【尾】我是个蒸不烂、煮不熟、捶不扁、炒不爆、响当当的一粒铜豌豆，那些子弟们谁让你们钻进了他锄不断、砍不下、解不开、甩不掉、慢腾腾的千层锦套头？我玩的是梁园的明月，饮的是东京的美酒，赏的是洛阳的名花，攀的是章台的杨柳。我也会围棋、会踢球、会打猎、会插科打诨、会唱歌跳舞、会吹弹乐器、会唱曲、会吟诗、会双陆。你就是打掉了我的牙、打歪了我的嘴、打瘸了我的腿、打断了我的手，上天赐给我的这些毛病，我还是不肯罢休！除非是阎王亲自来召唤，神鬼亲自来勾魂。三魂归了地府，七魄丧了幽冥。天哪！那时候我才不往烟花路上走！",
    s: "《一枝花·不伏老》是关汉卿的自叙之作，以“铜豌豆”自喻，展现了自己坚韧不屈、放荡不羁的性格。“蒸不烂、煮不熟、捶不匾、炒不爆”的排比，气势磅礴，将关汉卿的叛逆精神和顽强生命力写得淋漓尽致，是元曲中最具个性的作品之一。"
  },
  "窦娥冤·第三折（节选）|关汉卿": {
    y: "【正宫·端正好】无缘无故犯了王法，没有提防遭受刑罚，叫一声屈动地惊天。顷刻间游魂先赴了阎王殿，怎么不把天地也深深地埋怨。\n【滚绣球】有日月早晚悬挂，有鬼神掌着生死大权。天地啊，只应该把清浊分辨，可怎么混淆了盗跖和颜渊？行善的受贫穷又命短，作恶的享富贵又寿长。天地啊，做得个怕硬欺软，却原来也这般顺水推船！地啊，你不分好歹算什么地？天啊，你错判贤愚枉做天！哎，只落得两泪涟涟。",
    s: "《窦娥冤》是关汉卿的代表作，也是中国古代悲剧的巅峰之作。这段唱词是窦娥在法场上对天地的控诉，“地也，你不分好歹何为地？天也，你错勘贤愚枉做天！”以震天撼地的呐喊，揭露了封建社会的黑暗与不公，是元曲中最具反抗精神的唱段。"
  },
  "天净沙·春|白朴": {
    y: "桃红柳绿的春山，煦暖的阳光照耀，和柔的东风吹拂，楼阁上卷起帘拢，凭栏远望。院中杨柳依依，秋千轻轻摇动。黄莺在歌唱，春燕在飞舞，小桥下流水潺潺，柳絮飞花飘扬。",
    s: "《天净沙·春》是白朴的名作，与马致远《天净沙·秋思》齐名。全曲以白描手法描绘了春日的美好景象，“春山暖日和风”“啼莺舞燕，小桥流水飞红”，色彩明丽，生机盎然，与《秋思》的苍凉形成鲜明对比。"
  },
  "墙头马上·第一折（节选）|白朴": {
    y: "【后庭花】不要说姻缘难得，这是情意坚定。他用眉眼传递心事，我把心肠写进短笺。我若得见天颜，将他好言相劝，他是宰相家的贵公子，我是总管的女婵娟。\n【柳叶儿】呀，我只怕你情意淡薄，我只怕你日久心变，我只怕你另寻了姻缘。我只怕你等闲间把人轻视，我只怕你话里把人哄骗，我只怕你口是心非把人怠慢。",
    s: "《墙头马上》是白朴的爱情喜剧代表作，与《西厢记》《拜月亭》《倩女离魂》并称元曲四大爱情剧。这段唱词以女子的口吻，表达了对爱情的渴望和对未来的担忧，心理描写细腻生动，是元曲爱情戏的经典片段。"
  },
  "高祖还乡（节选）|睢景臣": {
    y: "【般涉调·哨遍】社长挨家挨户通知，只要有差使都不许推脱。这差使不寻常，一边要交纳草料，一边又要出夫役，都要应付。又说是车驾，都说是銮舆，今天要回故乡。王乡老拿着瓦台盘，赵忙郎抱着酒葫芦。新刷的头巾，刚浆过的绸衫，真是装模作样的大户。\n【耍孩儿】瞎王留领着一伙怪男女，乱踢蹬吹笛擂鼓。看见一队人马到庄门，当头几面旗舒展。一面旗白圈套着个迎霜兔，一面旗红圈打着个毕月乌。一面旗鸡学舞，一面旗狗生双翅，一面旗蛇缠葫芦。",
    s: "《高祖还乡》是睢景臣的代表作，以一个农民的视角，描写了汉高祖刘邦还乡的场面。全曲以幽默讽刺的笔法，将皇帝的仪仗描写得荒诞可笑，撕下了帝王的神圣面纱，表现了对封建皇权的蔑视，是元曲中最具讽刺性的作品之一。"
  },
  "醉太平·堂堂大元|无名氏": {
    y: "堂堂大元朝，奸臣专权。开河变钞是祸乱的根源，惹起了红巾军万千。官法混乱，刑法严苛，百姓怨恨。人吃人，钞买钞，何曾见过。贼做官，官做贼，愚贤不分，真是可悲可怜！",
    s: "《醉太平·堂堂大元》是元代末年的民间散曲，以尖锐泼辣的语言揭露了元末社会的黑暗：奸佞专权、官法泛滥、刑法严苛、人吃人、贼做官，是对元末社会现实的真实写照，也是元曲中最具批判精神的作品之一。"
  },
  "卖花声·怀古|张可久": {
    y: "阿房宫里罗袖翻飞，金谷园中玉楼高耸，隋堤上的古柳系着龙舟。往事不堪回首，东风又吹来了，野花开在暮春时候。",
    s: "《卖花声·怀古》是张可久的代表作，以阿房宫、金谷园、隋堤三个历史典故，抒发了对历史兴亡的感慨。“不堪回首，东风还又，野花开暮春时候”以景结情，将历史的沧桑与自然的永恒对比，含蓄深沉，是元曲中怀古的佳作。"
  },
  "人月圆·山中书事|张可久": {
    y: "千古以来的兴亡繁华，都像一场梦，诗人的眼睛已厌倦了天涯漂泊。孔林的乔木，吴宫的蔓草，楚庙的寒鸦，都在诉说着历史的沧桑。几间茅舍，藏书万卷，终老在乡村人家。山中做什么事？用松花酿酒，用春水煎茶。",
    s: "《人月圆·山中书事》是张可久的代表作，表达了对历史兴亡的感慨和对隐居生活的向往。“松花酿酒，春水煎茶”以极简练的笔墨写出了隐居生活的闲适与美好，全曲意境清雅，语言凝练，是元曲中小令的精品。"
  },
  "清江引·秋怀|张可久": {
    y: "西风送来家书，家在万里之外，问我什么时候回去？大雁在红叶满天的秋天啼叫，人在黄花满地的地方醉倒，芭蕉叶上的雨声，飘进了秋日的梦里。",
    s: "《清江引·秋怀》是张可久的名作，以西风、家书、雁啼、红叶、黄花、芭蕉、雨声等意象，营造出凄清的秋日意境，表达了游子的思乡之情。全曲语言凝练，意境优美，是元曲中写秋的佳作。"
  },
  "寿阳曲·远浦归帆|马致远": {
    y: "夕阳西下，酒旗悠闲地飘着，两三只船还没有靠岸。落花飘在水上，带着香气，茅舍笼罩在暮色中，断桥头上卖鱼的人已经散去。",
    s: "《寿阳曲·远浦归帆》是马致远《潇湘八景》组曲之一，以极简练的笔墨描绘了一幅渔村晚景图。“夕阳下，酒旆闲”“断桥头卖鱼人散”，画面宁静优美，充满生活气息，是元曲中写景的佳作。"
  },
  "四块玉·别情|关汉卿": {
    y: "自从送别之后，心中难舍，这一点相思什么时候才能断绝？凭栏远望，衣袖拂过如雪的杨花。溪水又斜，青山又遮，人已经去了！",
    s: "《四块玉·别情》是关汉卿的小令名作，以女子的口吻写送别后的相思。“凭阑袖拂杨花雪”以动作写思念，“溪又斜，山又遮，人去也”以景结情，将离别的惆怅写得含蓄深沉。全曲语言朴素，情感真挚。"
  },
  "沉醉东风·渔夫|白朴": {
    y: "黄芦岸边白苹渡口，绿柳堤上红蓼滩头。虽然没有刎颈之交，却有忘机之友。秋江上点染着白鹭沙鸥。傲视人间的万户侯，我是个不识字的烟波钓叟。",
    s: "《沉醉东风·渔夫》是白朴的名作，以渔夫的生活表达了对自由的向往和对权贵的蔑视。“傲杀人间万户侯，不识字烟波钓叟”将渔夫的自由与权贵的束缚对比，表达了不慕荣利、追求自由的人生态度，是元曲中隐逸题材的佳作。"
  },
  "鹦鹉曲·渔父|冯子振": {
    y: "我家住在鹦鹉洲边，是个不识字的渔父。浪花中一叶扁舟，在江南烟雨中酣睡。醒来时满眼青山，抖抖绿蓑衣归去。算从前错怨了天公，原来也有安排我的地方。",
    s: "《鹦鹉曲·渔父》是冯子振的代表作，以渔父的生活表达了随遇而安的人生态度。“浪花中一叶扁舟，睡煞江南烟雨”意境优美，“算从前错怨天公，甚也有安排我处”充满哲理，是元曲中隐逸题材的名篇。"
  },
  "小桃红·秋江|倪瓒": {
    y: "一江秋水笼罩着淡淡的寒烟，水面明净如白练。眼底的离愁如几行飞雁。雪后初晴，绿苹红蓼参差可见。唱着吴歌荡桨，一声哀怨，惊起了安眠的白鸥。",
    s: "《小桃红·秋江》是倪瓒的名作，倪瓒是元代著名画家，此曲以画家的笔触描绘了秋江的景色，“一江秋水澹寒烟，水影明如练”画面感极强，“吴歌荡桨，一声哀怨，惊起白鸥眠”以动写静，意境悠远，是元曲中写景的精品。"
  },
  "登徒子好色赋（节选）|宋玉": {
    y: "大夫登徒子在楚王身边侍奉，说宋玉的坏话：“宋玉这个人，相貌娴雅英俊，口才很好，又生性好色。希望大王不要让他出入后宫。”\n楚王把登徒子的话告诉了宋玉。宋玉说：“相貌娴雅英俊，是上天赐予的；口才很好，是从老师那里学来的；至于好色，臣下没有这回事。”\n楚王说：“你不好色，有什么说法吗？有道理就留下，没有道理就退下。”\n宋玉说：“天下的美女，没有比得上楚国的；楚国的美女，没有比得上我家乡的；我家乡的美女，没有比得上我东边邻居家的女儿。东边邻居家的女儿，增加一分就太高，减少一分就太矮；搽粉就太白，抹胭脂就太红；眉毛像翠鸟的羽毛，肌肤像白雪；腰像一束素绢，牙齿像含着贝壳；嫣然一笑，就能迷惑阳城、下蔡的公子。然而这个女子爬墙偷看我三年，我至今没有答应她。登徒子就不是这样：他的妻子头发蓬乱，耳朵卷曲，嘴唇外翻，牙齿稀疏，走路歪歪扭扭，还长着疥疮和痔疮。登徒子却很喜欢她，让她生了五个孩子。大王仔细考察一下，谁是好色的人呢？”",
    s: "《登徒子好色赋》是宋玉的代表作，以登徒子与宋玉的对比，讽刺了以貌取人的偏见。“增之一分则太长，减之一分则太短”成为描写美女的千古名句，“登徒子”也成为好色之徒的代名词。全赋语言优美，比喻生动，是先秦赋的代表作。"
  },
  "风赋（节选）|宋玉": {
    y: "楚襄王在兰台宫游玩，宋玉、景差在旁侍奉。有一阵风飒飒吹来，楚王就敞开衣襟迎着风，说：“这风真痛快啊！这是我和百姓共同享受的吗？”\n宋玉回答说：“这只是大王您的风罢了，百姓怎么能和您共同享受呢！”\n楚王说：“风，是天地间的气，普遍畅通地吹来，不分贵贱高低都吹到。现在你独独认为是我的风，难道有什么说法吗？”\n宋玉回答说：“我从老师那里听说：枳树弯曲的枝桠会招来鸟筑巢，空穴会引来风。它所依托的环境是这样，那么风的气势就不同了。”\n楚王说：“风，最初是从哪里产生的呢？”\n宋玉回答说：“风从大地上产生，从青苹草的末梢兴起。渐渐进入山谷，在山洞口猛烈怒吼。沿着泰山的山坳，在松柏之下飞舞。飘忽澎湃，激荡如烈火怒吼。轰轰如雷声，回旋交错。吹动石头，折断树木，冲击森林。等到它将要衰弱的时候，就四面分散，穿洞动门，光彩灿烂，离散转移。所以那清凉的雄风，就飘举升降，越过高高的城墙，进入深深的宫殿。吹开花叶散发香气，在桂树椒树之间徘徊，在急流之上翱翔。将冲击荷花，掠过蕙草，分开秦衡，掠过新夷，覆盖初生的杨树，回旋冲击，使众芳萧条。然后在庭院中徜徉，向北进入玉堂，穿过罗帐，经过深邃的内室，这才成为大王的风。所以这风吹到人的身上，直让人感到凄凉寒冷，清凉得让人叹息。清清凉凉，能治好病，解除酒醉，使人耳聪目明，身体安宁。这就是所说的大王的雄风。”",
    s: "《风赋》是宋玉的代表作，以“雄风”与“雌风”的对比，讽刺了统治者与百姓生活的天壤之别。“风起于青苹之末”成为千古名句，比喻事物的发展有一个从小到大的过程。全赋想象丰富，描写细腻，是先秦赋的杰作。"
  },
  "子虚赋（节选）|司马相如": {
    y: "楚王派子虚出使齐国，齐王征发全部车马，和使者一起外出打猎。打猎结束后，子虚去拜访乌有先生，亡是公也在座。坐定后，乌有先生问道：“今天打猎快乐吗？”子虚说：“快乐。”“收获多吗？”子虚说：“少。”“那为什么快乐呢？”子虚回答说：“我快乐是因为齐王想向我夸耀他的车骑众多，而我却用云梦泽的事来回答他。”乌有先生说：“可以说给我听听吗？”\n子虚说：“可以。齐王驾着千辆马车，挑选了万名骑兵，在海边打猎。士卒布满沼泽，罗网布满山丘，掩捕野兔，车轮碾死鹿，射杀麋鹿，抓住麟。在盐滩上奔驰，切割鲜肉，血染车轮。射中捕获很多，骄傲地自夸功劳。回头对我说：'楚国也有像这样富饶快乐的平原广泽游猎之地吗？楚王打猎和我比怎么样？'我下车回答说：'我是楚国的鄙陋之人，有幸在宫中宿卫十多年，时常跟随出游，在后宫花园游玩，看了一些景色，但还没有全部看完，又怎么能说宫外的大泽呢！'齐王说：'即使这样，你就大致说说你所听到看到的吧。'",
    s: "《子虚赋》是司马相如的代表作，与《上林赋》并称，是汉大赋的典范。全赋以子虚、乌有先生、亡是公三人的对话展开，极力铺陈楚国云梦泽的富饶和齐王打猎的盛况，规模宏大，辞藻华丽，奠定了汉大赋的体制，对后世影响深远。"
  },
  "上林赋（节选）|司马相如": {
    y: "亡是公笑着说：“楚国错了，齐国也不算对。让诸侯纳贡，不是为了财物，而是让他们陈述职守。划定疆界，不是为了防守，而是为了禁止放纵。现在齐国作为东方的藩国，却对外私通肃慎，离开本国，越过边界，渡海打猎，这在道义上本来就不可以。而且你们两位的议论，不致力于阐明君臣的道义，端正诸侯的礼仪，只是争着谈论游戏的快乐，苑囿的广大，想以奢侈争胜负，以荒淫比高低，这不能用来扬名传誉，反而足以贬低君主、损害自己。”\n“况且齐楚的事，又哪里值得称道呢！你们没有见过那巨大壮丽的景象，难道没听说过天子的上林苑吗？左边是苍梧，右边是西极。丹水经过它的南边，紫渊穿过它的北边。灞水浐水始终流在苑中，泾水渭水出入其中；酆水镐水潦水潏水，曲折蜿蜒，流经苑内。浩浩荡荡八条河流分流，方向不同，形态各异。东西南北，奔驰往来，从椒丘的阙口流出，在沙洲的水边行进，经过桂林之中，越过广阔的原野。水势浩荡，顺着山坡而下，奔赴狭窄的峡口，撞击巨石，冲击沙堆，沸腾暴怒，汹涌澎湃。水势湍急，相迫相击，横流回旋，翻腾飞溅，水势浩大。波浪如云般回旋，水流曲折纠缠。后浪越过前浪奔向低洼，水石相击流下浅滩。冲击岩石，拍打堤岸，奔腾飞扬。流向小洲，注入深谷，水声潺潺，水势深沉，轰鸣作响，水势汹涌，如鼎沸腾。波浪奔驰，泡沫跳跃，水流迅疾。悠远长流，寂静无声，安然长归。然后水势浩大，缓缓回旋，波光粼粼，向东注入太湖，溢满池塘。”",
    s: "《上林赋》是司马相如的代表作，与《子虚赋》连为一体，是汉大赋的巅峰之作。全赋以亡是公之口，极力铺陈天子上林苑的壮丽和天子打猎的盛况，规模宏大，辞藻华丽，气势磅礴，最后归于节俭，体现了“劝百讽一”的赋颂传统，对后世辞赋影响极大。"
  },
  "归田赋|张衡": {
    y: "在京城游历已久，没有高明的谋略辅佐时政。只是临河羡鱼，等待黄河水清却遥遥无期。感慨蔡泽的慷慨，跟随唐举决断疑惑。实在是天道幽微不明，追随渔父一同嬉戏。超脱尘世远去，与世事永远辞别。\n于是在美好的仲春二月，气候温和，天气清明；平原低地草木茂盛，百草繁荣。雎鸠展翅，黄鹂哀鸣；交颈上下翻飞，关关嘤嘤和鸣。在这里逍遥自在，姑且愉悦心情。\n于是在大泽边龙吟，在山丘上虎啸。仰射飞鸟，俯钓长流。鸟中箭而死，鱼贪饵吞钩。射落云间的飞鸟，钓起深渊中的鱼。\n这时太阳西斜，接着月亮升起。极尽游乐的至乐，虽然到了傍晚也忘记了疲劳。有感于老子的遗诫，将驾车回到茅屋。弹奏五弦琴的妙曲，诵读周公孔子的图书。挥笔作文，陈述三皇的法度。只要纵情于物外，哪里知道荣辱的所在。",
    s: "《归田赋》是张衡的代表作，也是中国文学史上第一篇描写田园隐居乐趣的赋作。全赋篇幅短小，语言清丽，一改汉大赋的铺张扬厉，开创了抒情小赋的先河，对后世陶渊明的田园诗产生了深远影响。"
  },
  "登楼赋|王粲": {
    y: "登上这座楼向四面眺望啊，姑且借闲暇的日子消解忧愁。看这座楼所处的位置啊，确实明亮宽敞少有匹敌。旁临清澈漳水的河口啊，倚靠曲折沮水的长洲。背后是高而平的广阔陆地啊，面前是低洼湿地的肥沃水流。北边直到陶牧，西边连接昭丘。花果遮蔽原野，黍稷长满田畴。虽然确实美好却不是我的故乡啊，又怎么值得稍稍停留。\n遭遇乱世而迁徙流亡啊，漫漫超过十二年直到如今。情意眷恋而思归啊，谁能承受这样的忧思？靠着栏杆遥望啊，迎着北风敞开衣襟。平原遥远极目远望啊，被荆山的高峰遮蔽。道路曲折而漫长啊，河水荡漾而渡口深。悲伤故乡被阻隔啊，眼泪纵横落下而不能禁止。从前孔子在陈国啊，有“归欤”的叹息。钟仪被囚禁而奏楚乐啊，庄舄显贵而仍越吟。人的感情都同样怀念故土啊，难道会因穷困显达而改变心意！\n想到时光流逝啊，等待黄河水清却没有尽头。希望王道统一太平啊，凭借大道施展才力。害怕像匏瓜那样白白悬挂啊，担心井已淘清却无人饮用。徘徊漫步啊，太阳忽然将要西沉。风声萧瑟四起啊，天色惨淡无光。野兽惊慌回顾寻找群伴啊，鸟儿相鸣而展翅。原野寂静无人啊，征夫行走不停。心中凄怆感慨啊，情意悲伤哀痛。沿着台阶走下楼啊，怨气交结充满胸中。到了半夜还不能入睡啊，惆怅徘徊翻来覆去。",
    s: "《登楼赋》是王粲的代表作，也是建安文学的名篇。王粲避难荆州，登当阳城楼，写下此赋，抒发了思乡之情和怀才不遇的感慨。“虽信美而非吾土兮，曾何足以少留”“人情同于怀土兮，岂穷达而异心”都是千古传诵的名句。全赋抒情真挚，语言清丽，是魏晋抒情小赋的典范。"
  },
  "洛神赋（节选）|曹植": {
    y: "黄初三年，我到京师朝见，回来时渡过洛水。古人说，这洛水的神，名叫宓妃。有感于宋玉对楚王说的神女之事，于是作了这篇赋。辞说：\n我从京城出发，回到东方的藩国。离开伊阙，越过轘辕，经过通谷，登上景山。太阳已经西斜，车困马乏。于是在长满杜蘅的岸边停车，在种满芝草的田里喂马，在阳林漫步，放眼眺望洛川。这时精神恍惚，忽然思绪飘散。低头没有看清，抬头却看到奇异的景象，看见一位美人，在山崖边。于是拉着车夫告诉他说：“你看见那个人了吗？那是谁啊？这样美丽！”车夫回答说：“我听说河洛的神，名叫宓妃。那么君王所见的，莫非就是她吗？她的样子怎样？我想听听。”\n我告诉他说：“她的形态，轻盈如惊飞的鸿雁，婉曲如游动的蛟龙。容光如秋菊般灿烂，风华如春松般茂盛。隐隐约约如轻云遮住月亮，飘飘摇摇如流风吹起回旋的雪花。远远望去，皎洁如朝阳升起在朝霞中；走近细看，鲜明如荷花出清水。肥瘦适中，高矮合度。肩膀如削成一般，腰肢如一束素绢。脖颈修长，洁白的肌肤显露。不施芳香，不涂脂粉。发髻高耸如云，眉毛修长弯曲。红唇鲜明，皓齿洁白，明亮的眼睛善于顾盼，面颊有美丽的酒窝。姿态瑰丽艳逸，仪态文静娴雅。柔情绰约，言语娇媚。服饰奇特举世无双，骨相应图。披着璀璨的罗衣，戴着华美的瑶碧玉佩。戴着金翠首饰，缀着明珠照耀身躯。穿着远游的花鞋，拖着薄雾般的轻裙。幽兰的芳香微微散发，在山边徘徊漫步。”",
    s: "《洛神赋》是曹植的代表作，以浪漫主义的笔法描写了人神相恋的故事。“翩若惊鸿，婉若游龙”“仿佛兮若轻云之蔽月，飘飖兮若流风之回雪”成为描写美女的千古名句。全赋想象瑰丽，辞藻华美，情感真挚，是中国文学史上最著名的赋作之一，也是后世绘画、戏曲的重要题材。"
  },
  "酒德颂|刘伶": {
    y: "有一位大人先生，把天地当作一天，把万年当作片刻，把日月当作门窗，把八方荒远之地当作庭院道路。行走没有车辙痕迹，居住没有房屋，以天为幕，以地为席，随心所欲。停下来就拿着酒杯，走动就提着酒壶，只致力于饮酒，哪里知道其他的事？\n有尊贵的公子和士大夫，听到我的名声，议论我的作为。于是挥袖挽襟，怒目咬牙，陈说礼法，是非纷起。先生这时正捧着酒坛接着酒槽，含着酒杯漱口酒，抖动胡须，箕踞而坐，枕着酒曲，垫着酒糟，无思无虑，其乐陶陶。昏然醉倒，豁然醒来。静听听不到雷霆的声音，细看看不见泰山的形状，不觉得寒暑侵入肌肤，利欲触动感情。俯视万物，纷纷扰扰，像江汉水中漂浮的浮萍；两位贵人侍立在旁，就像蜾蠃和螟蛉一样。",
    s: "《酒德颂》是刘伶的代表作，也是魏晋名士风度的集中体现。全文以大人先生的形象，表达了蔑视礼法、纵酒放达的人生态度，“幕天席地，纵意所如”成为千古名句。文章短小精悍，气势磅礴，是魏晋文学的名篇。"
  },
  "闲情赋（节选）|陶渊明": {
    y: "那是何等瑰丽超逸的美好姿容，举世无双，秀出群伦。展现出倾城的艳丽姿色，期望有美德流传。佩戴鸣玉来比洁白，与幽兰比芬芳。在世俗中保持淡泊柔情，怀抱高雅之志上凌云天。悲叹晨曦容易西斜，感慨人生长久辛劳。同样都在百年后穷尽，为何欢乐少而忧愁多。撩起红色帷幕端坐，弹奏清瑟自娱。纤细的手指传送余韵，洁白的衣袖挥动缤纷。美丽的眼睛转动流盼，含着言笑难以分辨。\n曲调将到一半，日影落到西窗。悲风叩击树林，白云依傍山峦。仰望天路，俯身催促琴弦。神态妩媚，举止安详妍丽。清音激越感动了我，希望促膝交谈。想亲自前往结下誓言，又怕冒犯礼法成为过错。等待凤鸟传话，又怕别人抢在我前面。心意惶惑不安，魂魄片刻之间九次变迁。\n愿做衣服的领子，承受美发的余香；悲叹罗衣夜里脱下，怨恨秋夜漫长。愿做裙子的腰带，束住窈窕的纤腰；嗟叹温凉变化，有时脱旧换新。愿做头发的油脂，涂抹在垂肩的黑发上；悲叹佳人多次洗发，随白水煎熬干枯。愿做眉毛的黛色，随着顾盼而舒展；悲叹脂粉求鲜，有时在华妆中被毁。愿做蒲草席，在三秋安托柔弱的身体；悲叹花纹褥子取代，要等一年才被用。愿做丝线做鞋，附着白足周旋；悲叹行止有节，白白被抛弃在床前。愿做白天的影子，常依身形或西或东；悲叹高树多荫，有时不能相随。愿做夜晚的蜡烛，在两楹之间照亮玉容；悲叹太阳升起，忽然灭影藏光。愿做竹子做扇，在柔握中含着清风；悲叹白露晨降，看着襟袖而遥远。愿做树木做桐，做膝上的鸣琴；悲叹乐极哀来，最终推开我而停止弹奏。",
    s: "《闲情赋》是陶渊明唯一的爱情赋作，“十愿”（愿在衣而为领、愿在裳而为带……）以奇特的想象，表达了对美人的深情爱慕，是中国文学史上最著名的爱情描写之一。全赋辞藻华美，情感真挚，与陶渊明平时平淡自然的风格形成鲜明对比，萧统评价为“白璧微瑕”，实则是陶渊明才情的另一种展现。"
  },
  "芜城赋|鲍照": {
    y: "广陵平原连绵起伏，向南可达苍梧、涨海，向北可到紫塞、雁门。以漕渠为舵，以昆岗为轴。是重关复江的险要之地，四方通达的要道。当它全盛的时候，车轴相碰，人肩相摩，房屋遍地，歌声震天。盐田滋生财富，铜山开采利益，财力雄厚，兵马精良。所以能超越秦法，超过周令，修筑高墙，挖掘深沟，图谋永世的好运。因此板筑城墙的盛状，建造望楼的辛勤，高度超过五岳，广度超过三坟，险峻如断岸，高耸如长云。用磁石制作防御，用红泥涂抹飞文。看这城防的坚固，将万年一君。经历三代，五百多年，竟然瓜剖豆分。\n井边长满青苔，道路缠绕野葛。庭院中遍布毒蛇，台阶上獐鼠相斗。木魅山鬼，野鼠城狐，在风雨中嚎叫，黄昏出现，清晨奔走。饥鹰磨嘴，寒鸥吓雏。潜伏猛虎，吸血食肉。崩倒的榛树堵塞道路，古老的大道险峻。白杨早落，寒草先衰。霜气凛冽，风威肃杀。孤蓬自飞，惊沙乱卷。灌木茫茫无际，草丛纷杂相依。城壕已经填平，城楼已经坍塌。直视千里之外，只见黄尘飞扬。凝神静听，心伤已碎。\n至于雕花的门、绣花的帐，歌堂舞阁的基址；玉池碧树，射猎垂钓的馆舍；吴蔡齐秦的音乐，鱼龙爵马的玩物；都香消烟灭，光沉响绝。东都的美女，南国的丽人，蕙心纨质，玉貌红唇，无不埋魂于幽石，委骨于穷尘。哪里还会记得同辇的欢乐，离宫的苦辛呢？\n天道如何，抱恨的人多。拿琴奏曲，作芜城之歌。歌道：边风急啊城上寒，井径灭啊丘垄残。千年啊万代，同归于尽啊又何言。",
    s: "《芜城赋》是鲍照的代表作，描写了广陵城（今扬州）从繁华到荒芜的巨变。“千龄兮万代，共尽兮何言”以苍凉的笔调抒发了对历史兴亡的感慨。全赋对比强烈，辞藻瑰丽，情感深沉，是南朝抒情小赋的巅峰之作。"
  },
  "别赋（节选）|江淹": {
    y: "最让人黯然销魂的，只有离别而已！何况秦吴是相隔绝远的国家，燕宋又相隔千里。有时春苔才开始生长，忽然秋风又暂时吹起。因此游子肠断，百感凄恻。风声萧萧而异响，云色漫漫而奇色。船在水边停滞，车在山侧徘徊。船桨迟缓怎能前进，马寒鸣不停。掩住金杯谁能饮，横放琴柱泪沾轼。在家的人愁卧，恍然若失。日影下墙而光彩沉，月亮上楼而飞光。见红兰承受露水，望青楸遭受寒霜。沿着高柱空掩门，抚摸锦幕空凄凉。知道离梦徘徊，料想别魂飞扬。\n所以离别虽是一种情绪，事情却有万种。至于龙马银鞍，朱车绣轴，在东都设帐饯饮，在金谷送客。琴羽奏响啊箫鼓陈列，燕赵悲歌啊美人伤心，珠玉啊艳于暮秋，罗绮啊娇于初春。惊得驷马仰头嚼食，耸动深渊鱼的红鳞。到分手时含泪，感到寂寞而伤神。\n又有剑客感恩，少年报士，像聂政刺韩相，豫让伏赵厕，专诸刺吴王，荆轲在燕市。割舍慈爱，离开邦国乡里，洒泪诀别，擦血相视。驱征马不回头，只见行尘时时扬起。正是因一剑感恩，不是为了买名于黄泉。金石震动而色变，骨肉悲痛而心死。",
    s: "《别赋》是江淹的代表作，与《恨赋》并称。“黯然销魂者，唯别而已矣”开篇便点明主旨，成为千古传诵的名句。全赋铺写了各种类型的离别，辞藻华丽，情感真挚，是南朝骈赋的典范之作，对后世影响深远。"
  },
  "滕王阁序（节选）|王勃": {
    y: "时当九月，正值深秋。雨后的积水已经消尽，寒冷的潭水十分清澈；烟雾凝聚，傍晚的山峦呈现出一片紫色。我们在高高的山路上驾车前行，到崇山峻岭中寻访风景。来到滕王营建的长洲上，看见了这座仙人般的楼阁。层叠的山峦耸起一片苍翠，向上直插云霄；凌空的楼阁丹漆流动，往下看，深不见底。白鹤、野鸭栖息的沙洲，极尽岛屿曲折回环的景致；桂木、兰木修建的宫殿，依着山峦的起伏排列。\n推开雕花的阁门，俯视华美的屋脊，辽阔的山川平原尽收眼底，迂回的江河湖泽令人惊叹。房屋遍地，都是钟鸣鼎食的富贵人家；船只停满渡口，都是青雀、黄龙造型的大船。乌云消散，雨过天晴，阳光普照，天空明朗。落日的晚霞与孤单的野鸭一同飞翔，秋天的江水和辽阔的天空浑然一色。傍晚渔舟中传来歌声，响彻彭蠡湖畔；雁群被寒气惊扰，叫声消失在衡阳的水边。\n胸怀顿时舒畅，超逸的兴致迅速飞扬。排箫声起，清风徐来，柔歌缭绕，白云停飞。睢园的绿竹，豪气胜过陶渊明的酒樽；邺水的朱华，光彩照过谢灵运的诗笔。四种美好都具备，两种难得也齐全。极目远望长空，在假日尽情游乐。天高地远，感到宇宙无穷；兴尽悲来，知道盛衰有定。远望长安在日下，遥看吴会在云间。地势尽而南海深，天柱高而北极远。关山难越，谁为迷路的人悲伤？萍水相逢，都是他乡之客。思念宫门却不得见，等待宣室召见又在哪一年？\n唉！时运不齐，命运多舛。冯唐容易衰老，李广难得封侯。贾谊被贬到长沙，不是没有圣明的君主；梁鸿逃到海边，难道不是政治清明的时代？所依赖的是君子看到征兆，达人知道命运。老当益壮，怎能改变白发之心？穷且益坚，不堕青云之志。喝贪泉的水更觉清爽，处干涸的车辙依然欢乐。北海虽远，乘风可到；早晨虽过，傍晚不晚。孟尝高洁，空有报国之情；阮籍猖狂，岂能学他穷途之哭！",
    s: "《滕王阁序》是骈文的巅峰之作，也是王勃的千古绝唱。全文辞藻华丽，对仗工整，意境开阔，“落霞与孤鹜齐飞，秋水共长天一色”更是千古名句。“老当益壮，宁移白首之心？穷且益坚，不坠青云之志”激励了无数身处逆境的人。全文是中国古代赋体文学最具代表性的作品。"
  },
  "前赤壁赋|苏轼": {
    y: "壬戌年的秋天，七月十六日，我和客人乘船在赤壁之下游玩。清风缓缓吹来，水面波澜不惊。我举起酒杯劝客人同饮，吟诵《诗经》中关于明月的诗篇。不一会儿，月亮从东山上升起，在斗宿和牛宿之间徘徊。白茫茫的水汽笼罩江面，水光与天空连成一片。我们任凭小船像一片苇叶般飘荡，越过茫茫万顷的江面。浩浩荡荡的，好像凌空驾风而行，不知道要停在哪里；飘飘然的，好像脱离了尘世，无牵无挂，变成了神仙飞上了天。\n这时候喝酒喝得高兴起来，用手叩击船舷应声而歌。歌词说：“桂木做的棹啊兰木做的桨，拍击着清澈的江水啊，在月光浮动的江面逆流而上。我的心怀悠远啊，遥望美人啊在天的一方。”客人中有吹洞箫的，按着歌声伴奏。那箫声呜呜咽咽，像怨恨又像思慕，像哭泣又像倾诉，尾声婉转悠长，像不断的细丝。能使深谷中的蛟龙起舞，能使孤舟上的寡妇哭泣。\n我的神色变得忧愁，整理好衣襟端坐，问客人说：“箫声为什么这样悲凉呢？”客人说：“'月明星稀，乌鹊南飞'，这不是曹孟德的诗吗？向西望是夏口，向东望是武昌，山水环绕，一片苍翠，这不是曹孟德被周瑜围困的地方吗？当他攻破荆州，攻下江陵，顺流东下的时候，战船相连千里，旌旗遮蔽天空，在江边斟酒，横执长矛吟诗，本是一代枭雄，如今又在哪里呢？何况我和你在江中小洲打鱼砍柴，以鱼虾为伴，以麋鹿为友，驾着一叶小船，举起酒杯互相劝酒。像蜉蝣一样寄生在天地之间，渺小得像大海中的一粒粟。哀叹我们生命的短暂，羡慕长江的无穷无尽。想和飞仙一起遨游，和明月相拥而永存。知道这些不可能轻易得到，只能把箫声的余音寄托给悲凉的秋风。”\n我说：“你也知道那江水和月亮吗？江水像这样不断流逝，却并没有真正流走；月亮像那样时圆时缺，却终究没有增减。如果从变化的一面去看，天地间的万事万物，连一眨眼的工夫都不曾保持原样；从不变的一面去看，万物和我们都是永恒的，又有什么可羡慕的呢？况且天地之间，万物各有其主，如果不是我所有的，即使一丝一毫也不能索取。只有江上的清风，和山间的明月，耳朵听到就成为声音，眼睛看到就成为颜色，取之不尽，用之不竭，这是大自然无穷无尽的宝藏，是我和你可以共同享受的。”\n客人高兴地笑了，洗了酒杯重新斟酒。菜肴和果品都吃完了，杯子盘子杂乱地放着。大家互相枕着靠着睡在船中，不知不觉东方已经发白。",
    s: "《前赤壁赋》是宋代文赋的典范，苏轼借赤壁夜游，探讨了变与不变、短暂与永恒的哲学命题。全文写景、抒情、议论浑然一体，既有泛舟江上的诗意，又有通透豁达的人生智慧。“惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭”成为千古名句，是中国古代散文中的不朽名篇。"
  },
  "秋声赋|欧阳修": {
    y: "欧阳先生夜里正在读书，听到有声音从西南方向传来，惊恐地侧耳倾听，说：“奇怪啊！”起初是淅淅沥沥的雨声夹杂着萧飒的风声，忽然奔腾澎湃起来，像波涛在夜间惊起，风雨突然到来。它碰到物体上，鏦鏦铮铮，像金属兵器相击；又像奔赴敌阵的士兵，衔枚快跑，听不到号令，只听到人马的行进声。我对童子说：“这是什么声音？你出去看看。”童子说：“星月皎洁，银河在天，四周没有人声，声音在树间。”\n我说：“唉，可悲啊！这是秋声，为什么而来呢？秋天的样子是：它的颜色惨淡，烟飞云收；它的容貌清明，天高气爽，阳光灿烂；它的气候寒冷，刺人肌骨；它的意境萧条，山川寂静。所以它发出的声音，凄凄切切，呼号奋发。茂盛的草碧绿繁茂，美好的树木葱茏可爱；可是草被秋风一吹就变色，树被秋风一刮就落叶。它之所以能摧败零落，是因为这一股肃杀之气的余威。秋天，是刑官，在时令上属阴；又是兵象，在五行中属金。这叫做天地的义气，常以肃杀为心。天对于万物，春生秋实，所以在音乐上，商声是西方的音，夷则是七月的律。商，就是伤，万物老了就悲伤；夷，就是戮，万物过盛就当杀。\n唉！草木无情，有时还要飘零。人是动物，是万物之灵；百忧触动他的心，万事劳累他的身体；心中有所触动，必然动摇他的精神。何况要思考他力量所不及的事，忧虑他智慧所不能的事；当然会使红润的容颜变成枯木，乌黑的头发变成花白。为什么要用不是金石的体质，想和草木争荣呢？想想是谁伤害了自己，又何必怨恨这秋声呢！”\n童子没有回答，低头睡着了。只听到四壁虫声唧唧，像在附和我的叹息。",
    s: "《秋声赋》是欧阳修的代表作，以秋声为线索，抒发了对人生的感慨。“草木无情，有时飘零。人为动物，惟物之灵”将草木与人对比，表达了对人生劳碌的感慨。全赋以无形的秋声为描写对象，想象丰富，描写生动，是宋代文赋的典范。"
  },
  "杂曲歌辞·行路难三首·二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "清平调词三首·三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "渔父·一|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "杂曲歌辞·忆江南·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "沁园春·雪|毛泽东": {
    s: "上片写景，以「北国风光，千里冰封，万里雪飘」总写北国雪景，意境壮阔；「望长城内外，惟余莽莽；大河上下，顿失滔滔」远望长城黄河，写雪后的苍茫；「山舞银蛇，原驰蜡象，欲与天公试比高」以动写静，群山如银蛇舞动、高原如蜡象奔驰，「欲与天公试比高」赋予山河以人的精神；「须晴日，看红装素裹，分外妖娆」想象雪后初晴的美景，红日白雪交相辉映。下片议论抒情，以「江山如此多娇，引无数英雄竞折腰」承上启下；「惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕」以「惜」字统领，评说历代帝王，指出他们武功有余而文治不足；「俱往矣，数风流人物，还看今朝」以「俱往矣」收束历史，「还看今朝」推向高潮，指出真正的风流人物是当今的无产阶级和人民大众。全词意境壮阔、气势磅礴、写景议论抒情融为一体，是中国词史上的千古绝唱。",
    b: "1936年2月，毛泽东率红军抗日先锋军东渡黄河，途经陕北清涧县袁家沟时，适逢大雪，他攀登海拔千米的高原视察地形，目睹「千里冰封」的北国风光，写下了这首气吞山河的壮丽词篇。1945年10月，毛泽东赴重庆谈判时书赠柳亚子，随后在重庆《新民报晚刊》发表，轰动全国。",
    n: ["北国：指我国北方","惟余莽莽：只剩下白茫茫的一片。惟余，只剩；莽莽，无边无际","大河上下：指黄河的上游和下游","顿失滔滔：指黄河因结冰而立刻失去了波涛滚滚的气势。顿，立刻","山舞银蛇：群山好像（一条条）银蛇在舞动","原驰蜡象：高原（上的丘陵）好像（许多）白象在奔跑。原，指秦晋高原；蜡象，白色的象","红装素裹：形容雪后天晴，红日和白雪相映衬的壮丽景色。红装，红色的装束；素裹，白色的包裹","妖娆：娇艳美好。娆音ráo","折腰：弯腰行礼，这里是倾倒的意思","秦皇汉武：秦始皇嬴政、汉武帝刘彻","略输文采：文采方面稍微差一些。输，差","唐宗宋祖：唐太宗李世民、宋太祖赵匡胤","稍逊风骚：文学才华稍微差一些。逊，差；风骚，《诗经》的《国风》和《楚辞》的《离骚》，代指文学才华","天骄：天之骄子","成吉思汗：元太祖铁木真。汗音hán","只识弯弓射大雕：只知道拉弓射大雕。雕，一种猛禽","风流人物：这里指能建功立业的英雄人物"]
  },
  "忆秦娥·娄山关|毛泽东": {
    s: "上片写景，「西风烈，长空雁叫霜晨月」以「西风烈」「雁叫」「霜晨月」三个意象，勾勒出一幅凄冷肃杀的战地黎明图——西风猛烈，长空雁叫，寒霜晨月；「霜晨月，马蹄声碎，喇叭声咽」以叠句「霜晨月」承上，以「马蹄声碎」「喇叭声咽」写红军急行军的场景——马蹄声细碎急促，军号声低沉悲凉，「碎」「咽」二字传神地写出了战斗的紧张和悲壮；下片抒情，「雄关漫道真如铁，而今迈步从头越」以「雄关漫道真如铁」写娄山关的险要——不要说雄关真的像铁一样坚固，以「而今迈步从头越」写红军的英勇——如今我们迈开大步从它头顶跨越过去，「真如铁」与「从头越」形成强烈对比，突出了红军无坚不摧的英雄气概；「从头越，苍山如海，残阳如血」以叠句「从头越」承上，以「苍山如海，残阳如血」写战斗结束后的景色——青山起伏如大海波涛，夕阳鲜红如血，「如海」「如血」两个比喻，意境壮阔、色彩浓烈，既是写景，也象征着革命道路的漫长和战斗的惨烈。全词意境壮阔、气势磅礴、写景抒情融为一体、语言精炼、色彩浓烈，是毛泽东诗词中的精品。",
    b: "1935年1月，遵义会议确立了毛泽东在党和红军中的领导地位。会后，毛泽东指挥红军二渡赤水，回师遵义，于2月26日攻占娄山关，28日再占遵义，取得了长征以来最大的一次胜利。这首词就是在攻占娄山关后写下的，描绘了红军在娄山关战斗中激烈悲壮的场面，表达了红军不怕牺牲、勇往直前的革命英雄主义精神。",
    n: ["忆秦娥：词牌名，又名《秦楼月》。李白有「箫声咽，秦娥梦断秦楼月」句，故名","娄山关：在贵州遵义北大娄山中，是贵州进入四川的要道，地势险要，历来为兵家必争之地","西风烈：西风猛烈。烈，猛烈","长空雁叫霜晨月：辽阔的天空中大雁在叫，寒霜的早晨挂着残月","霜晨月：这是词牌规定的叠句，重复上句末尾三字","马蹄声碎：马蹄声细碎急促。碎，细碎","喇叭声咽：军号声低沉悲凉。喇叭，指军号；咽音yè，声音因阻塞而低沉","雄关漫道真如铁：不要说雄伟的关隘真的像铁一样坚固。雄关，指娄山关；漫道，不要说，别说","而今迈步从头越：如今我们迈开大步从它的头顶跨越过去。迈步，迈开大步；从头越，从娄山关的山顶跨越过去","从头越：叠句","苍山如海：青山起伏像大海的波涛。苍山，青山","残阳如血：夕阳像血一样鲜红。残阳，夕阳"]
  },
  "清平乐·六盘山|毛泽东": {
    s: "上片写景抒情，「天高云淡，望断南飞雁」以「天高云淡」写秋日高原的晴朗天空，以「望断南飞雁」写词人目送大雁南飞的情景——望到看不见南飞的大雁，「望断」二字既写了眺望之久，也寄托了对南方革命根据地和战友的思念；「不到长城非好汉，屈指行程二万」以「不到长城非好汉」写红军的坚定信念——不到达目的地绝不是好汉，以「屈指行程二万」写长征的历程——弯指一算已经走了二万里，「非好汉」「二万」充满了革命自豪感；下片展望未来，「六盘山上高峰，红旗漫卷西风」写六盘山顶的景色——高峰之上，红旗在西风中飘扬，「漫卷」二字写出了红旗飘扬的自由和豪迈；「今日长缨在手，何时缚住苍龙？」以「长缨在手」写革命武装力量已经掌握在手中，以「何时缚住苍龙」写对革命胜利的期盼和信心——什么时候能捆住苍龙（国民党反动派）呢？「何时」不是疑问，而是充满信心的展望。全词意境开阔、气势豪迈、写景抒情融为一体、语言精炼、充满革命自豪感和胜利信心，是毛泽东诗词中的名篇。",
    b: "1935年10月，毛泽东率领中央红军翻越六盘山，这是红军长征途中翻越的最后一座大山。翻越六盘山后，红军即将到达陕北，长征胜利在望。毛泽东在六盘山顶峰，面对秋日高原的壮阔景色，回顾长征的战斗历程，展望革命的未来，写下了这首词。",
    n: ["清平乐：词牌名","六盘山：在宁夏回族自治区南部和甘肃东部，海拔2928米，是红军长征途中翻越的最后一座大山","天高云淡：天空高远，云彩淡薄","望断南飞雁：望到看不见南飞的大雁。望断，望到看不见；南飞雁，秋天向南飞的大雁","不到长城非好汉：不登临长城关口绝不是英雄好汉。长城，这里指长征的目的地，也指抗日前线","屈指行程二万：弯着手指头计算，已经走了二万里。屈指，弯着手指头计算；行程二万，指二万五千里长征的约数","红旗漫卷西风：红旗在西风中随意飘扬。漫卷，随意飘扬","长缨：长绳子。缨，绳子。这里指革命武装力量","苍龙：太岁神的别名，这里指国民党反动派。古代方士以太岁为凶神"]
  },
  "水调歌头·游泳|毛泽东": {
    s: "上片写游泳的感受，「才饮长沙水，又食武昌鱼」以「才饮」「又食」写行程的紧凑和轻松——刚喝了长沙水，又吃了武昌鱼，化用民谣「宁饮建业水，不食武昌鱼」而反其意，充满生活情趣；「万里长江横渡，极目楚天舒」写横渡长江的壮阔——横渡万里长江，放眼远望楚天开阔，「万里」「极目」「舒」写出了长江的壮阔和词人的舒畅；「不管风吹浪打，胜似闲庭信步，今日得宽余」写游泳的豪迈——不管风吹浪打，胜过在庭院里散步，今天得到了舒展，「风吹浪打」与「闲庭信步」对比，突出了词人的从容和自信；「子在川上曰：逝者如斯夫！」引用孔子的话，感叹时光流逝，也暗示要珍惜时间、加快建设；下片写建设宏图，「风樯动，龟蛇静，起宏图」以「风樯动」「龟蛇静」写长江两岸的景色，以「起宏图」引出建设规划；「一桥飞架南北，天堑变通途」写武汉长江大桥——一座大桥飞架南北，天堑变成通途，「飞架」二字写出了大桥的气势，「天堑变通途」写出了大桥的作用；「更立西江石壁，截断巫山云雨，高峡出平湖」写三峡工程的宏伟蓝图——还要在长江西部建立大坝，拦住巫山云雨，高峡出平湖，想象奇特、气势磅礴；「神女应无恙，当惊世界殊」以巫山神女的惊叹收束——神女应该还健康吧，一定会惊叹世界的巨大变化，用神话传说增添浪漫色彩，也表达了对社会主义建设成就的自豪。全词意境开阔、气势磅礴、写景抒情议论融为一体、用典自然、想象奇特、充满建设豪情，是毛泽东诗词中的名篇。",
    b: "1956年6月，毛泽东从长沙到武汉，三次畅游长江，写下了这首词。当时我国正处于第一个五年计划时期，社会主义建设蓬勃发展，武汉长江大桥正在建设中，三峡工程也在规划中。词人通过畅游长江的感受，抒发了对社会主义建设的豪情壮志和对未来的美好展望。",
    n: ["水调歌头：词牌名","才饮长沙水：刚喝了长沙的水。长沙水，长沙白沙古井的水，以清冽甘甜闻名","又食武昌鱼：又吃了武昌的鱼。武昌鱼，湖北鄂城（古武昌）出产的团头鲂，味道鲜美","万里长江横渡：横渡万里长江","极目楚天舒：放眼远望，湖北一带的天空开阔舒展。极目，放眼远望；楚天，湖北古属楚国，故称楚地的天空；舒，舒展，开阔","不管风吹浪打：不管风吹浪打","胜似闲庭信步：比在清静的庭院里随意散步还要自在。胜似，胜过；闲庭，清静的庭院；信步，随意散步","宽余：宽裕，舒缓","子在川上曰：逝者如斯夫：孔子在河边说：「消逝的时光就像这河水一样啊！」用《论语·子罕》「子在川上曰：『逝者如斯夫，不舍昼夜。』」","风樯动：风帆在动。樯音qiáng，桅杆","龟蛇静：龟山和蛇山静静地矗立着。龟蛇，龟山在汉阳，蛇山在武昌，两山隔江对峙","起宏图：开始了宏伟的建设规划。宏图，宏伟的规划","一桥飞架南北：一座大桥飞架南北。指武汉长江大桥，1957年建成通车","天堑变通途：天然的险阻变成了畅通的大道。天堑音qiàn，天然的壕沟，这里指长江；通途，畅通的大道","更立西江石壁：还要在长江西部建立一道拦河大坝。西江，指长江上游；石壁，指拦河大坝","截断巫山云雨：拦住巫山的云雨。巫山，在四川巫山县东，长江穿流其中，形成巫峡；巫山云雨，用宋玉《高唐赋》「旦为朝云，暮为行雨」典故，这里指长江上游的雨水","高峡出平湖：在高山峡谷中出现一个平静的大湖。指三峡水库","神女应无恙：神女应该还健康吧。神女，指巫山神女，用宋玉《高唐赋》巫山神女的典故；恙音yàng，病","当惊世界殊：一定会惊叹世界发生了巨大的变化。殊，不同，变化"]
  },
  "浪淘沙·北戴河|毛泽东": {
    s: "上片写景，「大雨落幽燕，白浪滔天」以「大雨落幽燕」写雨势之大——大雨落在幽燕大地上，以「白浪滔天」写浪势之猛——白色的波浪滔天，两个意象勾勒出一幅壮阔的雨中海景图；「秦皇岛外打鱼船，一片汪洋都不见，知向谁边？」写打鱼船在大雨中的命运——秦皇岛外的打鱼船，在一片汪洋中都看不见了，不知道漂向哪里去了，「都不见」「知向谁边」既写了雨大海深，也寄托了对渔民的关切；下片怀古抒情，「往事越千年，魏武挥鞭，东临碣石有遗篇」以「往事越千年」引出历史回忆——往事已经过去了一千年，以「魏武挥鞭，东临碣石有遗篇」写曹操的往事——魏武帝曹操挥鞭策马，东登碣石山留下了《观沧海》；「萧瑟秋风今又是，换了人间」以「萧瑟秋风今又是」呼应曹操《观沧海》中的「秋风萧瑟，洪波涌起」——萧瑟的秋风今天又吹起来了，以「换了人间」点明主旨——人间已经换了样子，曹操时代是封建社会，今天是社会主义新时代，「今又是」与「换了人间」形成对比，突出了时代的巨变。全词意境壮阔、气势磅礴、写景怀古抒情融为一体、用典自然、抚今追昔、充满时代自豪感，是毛泽东诗词中的名篇。",
    b: "1954年夏，毛泽东在北戴河休养期间，面对大海的壮丽景色，联想到一千七百多年前曹操在此写下《观沧海》的往事，抚今追昔，写下了这首词。词人通过对北戴河大雨中海景的描绘，抒发了对新时代的赞美和对历史的感慨。",
    n: ["浪淘沙：词牌名","北戴河：在河北秦皇岛西南，是著名的避暑胜地","大雨落幽燕：大雨落在幽燕大地上。幽燕，指河北北部和辽宁一带，古属幽州和燕国","白浪滔天：白色的波浪滔天。滔天，形容水势极大","秦皇岛外打鱼船：秦皇岛外面的打鱼船。秦皇岛，在河北，因秦始皇曾在此入海求仙而得名","一片汪洋都不见：一片汪洋都看不见了。都不见，指打鱼船都看不见了","知向谁边：不知道漂向哪里去了。谁边，何处，哪里","往事越千年：往事已经过去了一千年。越，超过，过去了","魏武挥鞭：魏武帝曹操挥鞭策马。魏武，指曹操，曹丕称帝后追尊曹操为魏武帝；挥鞭，挥鞭策马，指驰骋征战","东临碣石有遗篇：向东登上碣石山留下了诗篇。碣石，山名，在今河北昌黎西北，一说在北戴河附近；遗篇，遗留下来的诗篇，指曹操的《观沧海》。公元207年，曹操北征乌桓，途经碣石山，写下了《观沧海》","萧瑟秋风今又是：萧瑟的秋风今天又吹起来了。萧瑟，形容风吹树木的声音；曹操《观沧海》有「秋风萧瑟，洪波涌起」句","换了人间：人间已经换了样子。指社会发生了翻天覆地的变化"]
  },
  "卜算子·咏梅|毛泽东": {
    s: "上片写梅花在严寒中开放，「风雨送春归，飞雪迎春到」以「风雨」「飞雪」写环境的恶劣——风雨送走了春天，飞雪迎来了春天，「送」「迎」二字赋予风雨飞雪以人的动作；「已是悬崖百丈冰，犹有花枝俏」以「悬崖百丈冰」写严寒的程度——悬崖上已经结了百丈冰，以「犹有花枝俏」写梅花的傲然——仍然有梅花俏丽地开放，「已是」与「犹有」形成强烈对比，突出了梅花不畏严寒的精神；下片写梅花的品格，「俏也不争春，只把春来报」以「不争春」写梅花的无私——虽然俏丽，但不与百花争春，以「只把春来报」写梅花的奉献——只是把春天到来的消息报告给人们；「待到山花烂漫时，她在丛中笑」以「山花烂漫」写春天的繁盛——等到满山遍野的花都盛开了，以「她在丛中笑」写梅花的欣慰和谦逊——梅花在百花丛中欢笑，「笑」字写出了梅花的乐观和无私——自己开放不是为了争春，而是为了报春，当百花盛开时，她在花丛中欣慰地笑。全词意境优美、形象鲜明、对比强烈、拟人巧妙、托物言志、充满革命乐观主义精神，是毛泽东诗词中托物言志的名篇。陆游的咏梅写「寂寞开无主」「零落成泥碾作尘，只有香如故」，充满孤独悲凉；毛泽东反其意，写梅花的乐观自信和无私奉献，境界远高于陆游。",
    b: "1961年12月，毛泽东在广州期间，读了陆游的《卜算子·咏梅》，「反其意而用之」，写下了这首咏梅词。当时我国正处于三年困难时期，国际上也面临着反华势力的围攻。毛泽东以梅花自喻，通过对梅花在严寒中傲然开放的描写，表达了中国共产党人不畏艰难、敢于斗争、无私奉献的革命精神和乐观主义态度。词前有小序：「读陆游咏梅词，反其意而用之。」",
    n: ["卜算子：词牌名","读陆游咏梅词，反其意而用之：毛泽东自注：读了陆游的《卜算子·咏梅》，反其意而用之。陆游的咏梅词写梅花的寂寞孤独，毛泽东反其意，写梅花的乐观自信","风雨送春归：风雨把春天送走了","飞雪迎春到：飞雪又把春天迎来了","已是悬崖百丈冰：已经是悬崖上结了百丈冰的时候。百丈冰，形容冰很厚","犹有花枝俏：仍然有梅花俏丽地开放。犹，仍然；俏，俊俏，美丽","俏也不争春：梅花虽然俏丽，但不与百花争春。争春，争占春光","只把春来报：只是把春天到来的消息报告给人们","待到山花烂漫时：等到满山遍野的花都盛开的时候。烂漫，颜色鲜明而美丽，这里指花盛开的样子","她在丛中笑：梅花在花丛中欢笑。她，指梅花；丛中，百花丛中"]
  },
  "七律·人民解放军占领南京|毛泽东": {
    s: "首联「钟山风雨起苍黄，百万雄师过大江」以「钟山风雨起苍黄」写南京的形势——钟山风雨骤起，天色昏黄，暗指国民党政权仓皇崩溃，以「百万雄师过大江」写解放军渡江的壮举——百万雄师渡过长江，气势磅礴；颔联「虎踞龙盘今胜昔，天翻地覆慨而慷」以「虎踞龙盘今胜昔」写南京的新生——虎踞龙盘的南京今天胜过以往，以「天翻地覆慨而慷」写革命变化的巨大——天翻地覆的变化令人慷慨激昂；颈联「宜将剩勇追穷寇，不可沽名学霸王」是全诗的主旨——应该用剩余的勇气追剿穷途末路的敌人，不能为了虚名而学楚霸王项羽放走刘邦，用项羽的典故告诫全党将革命进行到底，不要给敌人喘息的机会；尾联「天若有情天亦老，人间正道是沧桑」以「天若有情天亦老」用李贺诗句写革命变革的必然性——天如果有感情也会因悲伤而衰老，以「人间正道是沧桑」点明主旨——人间的正道就是沧海桑田的巨大变化，革命变革是历史发展的必然规律。全诗气势磅礴、用典贴切、对仗工稳、情感激昂、哲理深刻，是中国革命诗歌史上的千古名篇。",
    b: "1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，百万人民解放军强渡长江。4月23日，人民解放军占领南京，宣告了国民党反动统治的覆灭。毛泽东在北平香山双清别墅得知这一消息后，心潮澎湃，写下了这首气势磅礴的诗篇，歌颂了人民解放军的伟大胜利，表达了将革命进行到底的决心。",
    n: ["钟山：即紫金山，在南京市东，这里代指南京","风雨起苍黄：风雨骤起，天色昏黄。苍黄，同「仓皇」，这里指天色昏黄，也暗指国民党政权仓皇崩溃","百万雄师过大江：百万雄壮的人民解放军渡过长江。1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，百万雄师在西起湖口东至江阴的千里战线上强渡长江","虎踞龙盘今胜昔：南京的地势比以往更加雄伟。虎踞龙盘，形容南京地势险要，诸葛亮曾说南京「钟山龙盘，石头虎踞，此帝王之宅」；今胜昔，今天胜过以往","天翻地覆慨而慷：天翻地覆的变化令人慷慨激昂。慨而慷，即慷慨，情绪激昂。曹操《短歌行》有「慨当以慷」","宜将剩勇追穷寇：应该用剩余的勇气去追剿穷途末路的敌人。剩勇，剩余的勇气；穷寇，穷途末路的敌人，指国民党残余势力","不可沽名学霸王：不能为了虚名而学楚霸王项羽。沽名，故意做作或用某种手段猎取名誉；霸王，指项羽，项羽在鸿门宴上为了「仁义」之名放走刘邦，最终被刘邦所败。这里告诫全党不要给国民党喘息的机会","天若有情天亦老：天如果有感情，也会因为悲伤而衰老。用唐李贺《金铜仙人辞汉歌》「衰兰送客咸阳道，天若有情天亦老」句","人间正道是沧桑：人间的正道是沧海桑田的巨大变化。沧桑，「沧海桑田」的略语，比喻世事变化很大。这里指革命变革是人间的正道"]
  },
  "蝶恋花·答李淑一|毛泽东": {
    s: "上片写烈士忠魂飞上月宫，「我失骄杨君失柳，杨柳轻飏直上重霄九」以「我失骄杨君失柳」开篇，「骄杨」二字饱含对杨开慧的深情和骄傲——我失去了骄傲的杨开慧，你失去了柳直荀，「杨柳」双关，既指两位烈士，也指柳絮，「轻飏直上重霄九」写忠魂轻轻地飘飞上九重云霄，想象浪漫；「问讯吴刚何所有，吴刚捧出桂花酒」写忠魂到了月宫，吴刚捧出桂花酒招待——询问吴刚有什么，吴刚捧出桂花酒，以神话传说中的人物接待烈士，表达了对烈士的敬意；下片写嫦娥起舞和喜讯传来，「寂寞嫦娥舒广袖，万里长空且为忠魂舞」写寂寞的嫦娥也舒展广袖，在万里长空中为忠魂翩翩起舞，连月宫中的嫦娥都被烈士的忠魂感动；「忽报人间曾伏虎，泪飞顿作倾盆雨」以「忽报」转折——忽然传来人间已经降服猛虎（革命胜利）的消息，烈士的忠魂激动得泪飞如雨，顿时化作倾盆大雨，「泪飞顿作倾盆雨」想象奇特、情感浓烈，将对革命胜利的喜悦和对烈士的悼念融为一体。全词想象奇特、浪漫主义色彩浓厚、用神话传说写革命情怀、情感深沉、意境壮美，是毛泽东诗词中浪漫主义的代表作。",
    b: "1957年1月，毛泽东的老友李淑一（杨开慧的好友、柳直荀的夫人）给毛泽东写信，附上她1933年悼念丈夫柳直荀的词《菩萨蛮·惊梦》，并请求毛泽东把早年写给杨开慧的词抄给她。毛泽东5月11日回信，信中说：「大作读毕，感慨系之。开慧所述那一首不好，不要写了吧。有《游仙》一首为赠。」这首《游仙》即《蝶恋花·答李淑一》，发表时改题。词中通过浪漫主义的想象，写杨开慧、柳直荀两位烈士的忠魂飞上月宫，受到吴刚、嫦娥的热情接待，当听到革命胜利的消息时，激动得泪飞如雨，表达了对革命先烈的深切悼念和崇高敬意。",
    n: ["蝶恋花：词牌名","答李淑一：李淑一，柳直荀的夫人，杨开慧的好友。1957年1月，李淑一给毛泽东写信，附上她悼念柳直荀的词《菩萨蛮·惊梦》，毛泽东回信并写了这首词答她","我失骄杨君失柳：我失去了骄傲的杨开慧，你失去了柳直荀。骄杨，指杨开慧，毛泽东的妻子，1930年被国民党杀害；骄，以为骄傲；君，你，指李淑一；柳，指柳直荀，李淑一的丈夫，1932年在洪湖苏区牺牲","杨柳轻飏直上重霄九：杨开慧和柳直荀的忠魂轻轻地飘扬，一直飞上九重云霄。杨柳，双关，既指杨开慧和柳直荀，也指柳絮；轻飏，轻轻飘扬；重霄九，即九重霄，天的最高处","问讯吴刚何所有：询问吴刚有什么东西。吴刚，神话传说中的人物，因学仙有过，被罚在月宫砍桂树","吴刚捧出桂花酒：吴刚捧出桂花酒来招待他们。桂花酒，用桂花酿制的酒","寂寞嫦娥舒广袖：寂寞的嫦娥舒展宽大的袖子翩翩起舞。嫦娥，神话传说中后羿的妻子，因偷吃不死药而奔月；舒广袖，舒展宽大的袖子，指跳舞","万里长空且为忠魂舞：在万里长空中暂且为忠魂翩翩起舞。且，暂且；忠魂，指杨开慧和柳直荀的忠魂","忽报人间曾伏虎：忽然传来人间已经降服了猛虎的消息。伏虎，降服猛虎，比喻革命胜利，推翻了国民党反动派","泪飞顿作倾盆雨：泪水顿时飞洒，化作倾盆大雨。顿作，顿时化作；倾盆雨，形容雨下得极大"]
  },
  "西江月·井冈山|毛泽东": {
    s: "上片写战斗场面，「山下旌旗在望，山头鼓角相闻」以「山下旌旗」「山头鼓角」写战斗的紧张气氛——山下的军旗看得见，山头上的鼓角声互相听得见，视听结合，勾勒出一幅战地画面；「敌军围困万千重，我自岿然不动」以「敌军围困万千重」写敌军的嚣张——敌军把井冈山围困了千万重，以「我自岿然不动」写红军的镇定——我们依然巍然屹立毫不动摇，「万千重」与「岿然不动」形成强烈对比，突出了红军的英雄气概；下片写胜利原因和结果，「早已森严壁垒，更加众志成城」以「森严壁垒」写防御工事的坚固——早就构筑了严整的防御工事，以「众志成城」写军民的团结——更加上大家同心协力像城墙一样坚固，从物质和精神两个方面写胜利的原因；「黄洋界上炮声隆，报道敌军宵遁」以「黄洋界上炮声隆」写战斗的激烈——黄洋界上炮声隆隆，以「报道敌军宵遁」写战斗的结果——报告说敌军在夜里逃跑了，「宵遁」二字写出了敌军的狼狈。全词意境壮阔、对比鲜明、视听结合、叙事写景抒情融为一体、充满革命自豪感，是毛泽东诗词中描写战斗的名篇。",
    b: "1928年8月，毛泽东率领红军主力去湘南迎还红军大队，湘赣两省的国民党军队趁机对井冈山发动第二次「会剿」。留守井冈山的红军以不足一个营的兵力，在黄洋界哨口凭借险要地形，击退了敌军四个团的进攻，取得了黄洋界保卫战的胜利。毛泽东在率领红军大队回井冈山的途中，得知黄洋界保卫战胜利的消息，写下了这首词，歌颂了井冈山军民团结抗敌的革命精神。",
    n: ["西江月：词牌名","井冈山：在江西西部和湖南东部交界处，是中国第一个农村革命根据地","山下旌旗在望：山下的军旗在视线之内。旌旗，军旗；在望，在视线之内，看得见","山头鼓角相闻：山头上的战鼓声和号角声互相听得见。鼓角，战鼓和号角；相闻，互相听得见","敌军围困万千重：敌军把井冈山围困了千万重。万千重，千万层，形容围困之严密","我自岿然不动：我们依然巍然屹立，毫不动摇。岿然，高大独立的样子。岿音kuī","早已森严壁垒：早就构筑了严整的防御工事。森严，严整；壁垒，古代军营的围墙，这里指防御工事","更加众志成城：更加上大家同心协力，像城墙一样坚固。众志成城，大家同心协力，就像城墙一样坚固，比喻团结一致力量无比强大","黄洋界上炮声隆：黄洋界上炮声隆隆。黄洋界，井冈山五大哨口之一，地势险要；隆，形容声音大","报道敌军宵遁：报告说敌军在夜里逃跑了。宵遁，夜里逃跑。宵，夜；遁音dùn，逃跑"]
  },
  "菩萨蛮·黄鹤楼|毛泽东": {
    s: "上片写景，「茫茫九派流中国，沉沉一线穿南北」以「茫茫九派」写长江的壮阔——茫茫的长江九条支流连贯中国中部，以「沉沉一线」写铁路的延伸——沉沉的一条铁路线贯穿南北，一横一纵，勾勒出武汉的地理形势；「烟雨莽苍苍，龟蛇锁大江」以「烟雨莽苍苍」写景色的迷茫——烟雨迷茫一片苍茫，以「龟蛇锁大江」写龟山蛇山的雄姿——龟山和蛇山锁住了长江，「锁」字写出了两山的险要，也暗喻了革命形势的压抑；下片抒情，「黄鹤知何去？剩有游人处」以「黄鹤知何去」用崔颢诗意发问——黄鹤知道飞到哪里去了，以「剩有游人处」写黄鹤楼的现状——只剩下供游人游览的地方，暗含对世事变迁的感慨；「把酒酹滔滔，心潮逐浪高」以「把酒酹滔滔」写词人的动作——端起酒洒在滔滔的江水中，以「心潮逐浪高」写词人的心情——心潮随着波浪越来越高，「逐浪高」三字将心潮与江浪融为一体，表达了词人在革命危急关头不屈不挠的斗争精神和将革命进行到底的决心。全词意境壮阔、写景抒情融为一体、用典自然、情感深沉、充满革命激情，是毛泽东诗词中的名篇。",
    b: "1927年春，毛泽东在武汉担任全国农民协会总干事，面对大革命失败前夕的严峻形势——蒋介石发动「四一二」反革命政变，汪精卫也在酝酿「分共」，革命处于危急关头。毛泽东登临黄鹤楼，面对长江的壮丽景色和阴沉的政治形势，心潮澎湃，写下了这首词，表达了对革命形势的忧虑和将革命进行到底的决心。",
    n: ["菩萨蛮：词牌名","黄鹤楼：在湖北武汉武昌蛇山黄鹤矶头，是江南三大名楼之一，始建于三国吴黄武二年（223年），历代屡毁屡建","茫茫九派流中国：茫茫的长江九条支流在中国大陆上奔流。九派，相传长江在湖北江西一带分为九派；流中国，流贯中国中部。中国，这里指中国中部","沉沉一线穿南北：沉沉的一条铁路线贯穿南北。一线，指京汉铁路和粤汉铁路（今京广铁路的前身）；穿南北，贯穿南北","烟雨莽苍苍：烟雨迷茫，一片苍茫。莽苍苍，迷茫辽阔的样子","龟蛇锁大江：龟山和蛇山锁住了长江。龟蛇，龟山在汉阳，蛇山在武昌，两山隔江对峙，像锁住了长江","黄鹤知何去：黄鹤知道飞到哪里去了？用崔颢《黄鹤楼》「昔人已乘黄鹤去，此地空余黄鹤楼」诗意","剩有游人处：只剩下供游人游览的地方","把酒酹滔滔：端起酒洒在滔滔的江水中。把酒，端起酒；酹音lèi，把酒洒在地上表示祭奠；滔滔，指滔滔的江水","心潮逐浪高：心潮随着波浪越来越高。心潮，心中的激情像潮水一样；逐，随着"]
  },
  "采桑子·重阳|毛泽东": {
    s: "上片写重阳，「人生易老天难老，岁岁重阳」以「人生易老天难老」开篇，对比人生与自然——人生容易衰老，天却难以衰老，以「岁岁重阳」写时间的永恒——年年都有重阳节；「今又重阳，战地黄花分外香」以「今又重阳」写今年的重阳节，以「战地黄花分外香」写战场上的菊花——战场上的菊花格外芳香，「战地」二字点明了革命战争的环境，「分外香」写出了词人对革命战争的赞美——在战场上开放的菊花比平时更香，因为它是革命战士用鲜血浇灌的；下片写秋景，「一年一度秋风劲，不似春光。胜似春光，寥廓江天万里霜」以「一年一度秋风劲」写秋风的强劲——一年一度的秋风强劲，以「不似春光。胜似春光」对比秋天和春天——秋天不像春天的风光，但胜过春天的风光，为什么呢？因为「寥廓江天万里霜」——辽阔的江天之上万里都是霜，秋天的景色比春天更壮阔、更雄浑。全词意境开阔、对比鲜明、写景抒情融为一体、充满革命乐观主义精神，「战地黄花分外香」「胜似春光」表达了词人对革命战争的赞美和对革命前途的乐观态度，是毛泽东诗词中咏秋的名篇。",
    b: "1929年10月，毛泽东在闽西革命根据地，当时他因受到「左」倾路线的排挤，离开了红军主要领导岗位，在地方指导工作。重阳节这天，他面对闽西秋天的壮丽景色，回顾革命的战斗历程，写下了这首词，表达了对革命战争的赞美和对革命前途的乐观态度。",
    n: ["采桑子：词牌名","重阳：农历九月初九，重阳节，有登高、赏菊的习俗","人生易老天难老：人生容易衰老，天却难以衰老","岁岁重阳：年年都有重阳节。岁岁，年年","今又重阳：今天又到了重阳节","战地黄花分外香：战场上的菊花格外芳香。战地，战场；黄花，菊花；分外，格外","一年一度秋风劲：一年一度的秋风强劲。劲，强劲","不似春光：不像春天的风光","胜似春光：胜过春天的风光","寥廓江天万里霜：辽阔的江天之上，万里都是霜。寥廓，高远空旷；江天，江和天；万里霜，万里都是霜，形容秋霜之广"]
  },
  "七律·和柳亚子先生|毛泽东": {
    s: "首联「饮茶粤海未能忘，索句渝州叶正黄」回忆与柳亚子的两次交往——1926年在广州一起饮茶，1945年在重庆互相唱和，「未能忘」「叶正黄」充满了对旧友的深情；颔联「三十一年还旧国，落花时节读华章」写三十一年后回到北京，在落花时节读到了柳亚子的诗篇，「三十一年」「落花时节」既写了时间的跨度，也暗含了对世事变迁的感慨；颈联「牢骚太盛防肠断，风物长宜放眼量」是全诗的主旨——牢骚太多了要防止伤身体，对世间万物应该放长远眼光去衡量，以委婉的语气批评了柳亚子的牢骚情绪，劝他以大局为重、放眼未来；尾联「莫道昆明池水浅，观鱼胜过富春江」以「昆明池水浅」「观鱼胜过富春江」劝慰柳亚子——不要说昆明湖的水浅，在这里观鱼胜过在富春江隐居，用严子陵富春江隐居的典故，劝柳亚子留在北京参加新中国建设，比退隐回乡更有意义。全诗用典贴切、对仗工稳、语气委婉、情感真挚、既批评又劝慰、充满政治家的胸怀和人情味，是毛泽东诗词中唱和劝慰的名篇。",
    b: "1949年3月，柳亚子作为民主人士参加中国人民政治协商会议的筹备工作，因对工作安排和生活待遇不满，写了《七律·感事呈毛主席》，诗中有「安得南征驰捷报，分湖便是子陵滩」句，流露出退隐回乡之意。毛泽东读到这首诗后，于4月29日写了这首和诗，既肯定了柳亚子的历史贡献，又委婉地批评了他的牢骚情绪，劝他以大局为重，留在北京参加新中国建设。",
    n: ["和柳亚子先生：和，依照别人诗词的题材和体裁做诗词；柳亚子，诗人，国民党左派人士，毛泽东的诗友。1949年3月，柳亚子写了《七律·感事呈毛主席》，诗中流露出退隐之意，毛泽东写这首诗劝慰他","饮茶粤海未能忘：在广州一起喝茶的事不能忘怀。饮茶粤海，1926年毛泽东在广州主持农民运动讲习所时，与柳亚子相识，曾一起饮茶；粤海，指广州","索句渝州叶正黄：在重庆索取诗句时树叶正黄。索句，索取诗句，指互相唱和；渝州，指重庆；叶正黄，指秋天，1945年8月至10月，毛泽东赴重庆谈判，与柳亚子重逢，曾书赠《沁园春·雪》","三十一年还旧国：三十一年后回到了旧都。三十一年，从1918年毛泽东第一次到北京到1949年回到北京，正好三十一年；旧国，指北京，北京曾是元明清三代的都城","落花时节读华章：在落花时节读到了你的华美诗篇。落花时节，指暮春，用杜甫《江南逢李龟年》「正是江南好风景，落花时节又逢君」诗意；华章，华美的诗篇，指柳亚子的《感事呈毛主席》","牢骚太盛防肠断：牢骚太多了要防止肠子断。牢骚，抑郁不满的情绪；太盛，太多；防肠断，防止伤身体","风物长宜放眼量：对世间万物应该放长远眼光去衡量。风物，风光景物，这里指世间的事物；长宜，应该经常；放眼量，放开眼界去衡量","莫道昆明池水浅：不要说昆明湖的水浅。昆明池，指北京颐和园的昆明湖；水浅，比喻地方小、条件差","观鱼胜过富春江：在昆明湖观鱼胜过在富春江隐居。观鱼，用《庄子·秋水》「庄子与惠子游于濠梁之上，观鱼之乐」典故，也暗指柳亚子诗中「分湖便是子陵滩」的退隐之意；富春江，在浙江，东汉严子陵曾在此隐居垂钓。这里劝柳亚子留在北京参加新中国建设，比去富春江隐居更好"]
  },
  "浣溪沙·和柳亚子先生|毛泽东": {
    s: "上片写旧中国的黑暗，「长夜难明赤县天，百年魔怪舞翩跹，人民五亿不团圆」以「长夜难明」比喻旧社会的黑暗漫长——漫长的黑夜难以天亮，以「百年魔怪舞翩跹」比喻一百多年来帝国主义、封建主义和官僚资本主义的横行——一百多年来妖魔鬼怪翩翩起舞，以「人民五亿不团圆」写旧中国人民的苦难——五亿人民不能团圆，三句层层递进，写出了旧中国的黑暗和人民的苦难；下片写新中国的光明，「一唱雄鸡天下白，万方乐奏有于阗，诗人兴会更无前」以「一唱雄鸡天下白」比喻新中国的成立——雄鸡一叫天就亮了，黑暗的旧时代结束了，以「万方乐奏有于阗」写新中国各民族的大团结——全国各地都演奏起欢乐的乐曲，其中还有来自新疆于阗的乐曲，以「诗人兴会更无前」写诗人的兴奋——诗人的兴致前所未有，「更无前」三字将欢乐的气氛推向高潮。全词对比鲜明、用典自然、意境开阔、情感激昂、充满对新中国的赞美和对各民族大团结的歌颂，是毛泽东诗词中歌颂新中国的名篇。",
    b: "1950年10月3日，新中国成立一周年之际，全国各民族代表在北京怀仁堂举行联欢晚会，西南各民族文工团、新疆文工团、吉林省延边文工团、内蒙古文工团联合演出了歌舞节目。毛泽东、刘少奇、周恩来等党和国家领导人出席了晚会。柳亚子当场填了一首《浣溪沙》，毛泽东当场和了这首词，通过新旧社会的对比，歌颂了新中国的成立和各民族的大团结。",
    n: ["浣溪沙：词牌名","和柳亚子先生：1950年10月，新中国成立一周年之际，全国各民族代表在北京怀仁堂举行联欢晚会，柳亚子即席填了一首《浣溪沙》，毛泽东当场和了这首词","长夜难明赤县天：漫长的黑夜难以天亮，这是旧中国的天空。长夜难明，比喻旧社会的黑暗漫长；赤县，指中国，战国时邹衍称中国为「赤县神州」","百年魔怪舞翩跹：一百多年来妖魔鬼怪翩翩起舞。百年，指1840年鸦片战争以来的一百多年；魔怪，比喻帝国主义、封建主义和官僚资本主义；翩跹音piānxiān，形容轻快地跳舞","人民五亿不团圆：五亿人民不能团圆。人民五亿，当时中国人口约五亿；不团圆，指国家分裂、人民不能团聚","一唱雄鸡天下白：雄鸡一叫，天就亮了。比喻新中国成立，黑暗的旧时代结束了。用唐李贺《致酒行》「雄鸡一声天下白」句","万方乐奏有于阗：全国各地都演奏起欢乐的乐曲，其中还有来自新疆于阗的乐曲。万方，全国各地；乐奏，演奏乐曲；于阗音tián，汉西域国名，在今新疆和田一带，这里指新疆各民族的文工团","诗人兴会更无前：诗人的兴致更是前所未有。诗人，指柳亚子，也可泛指与会的诗人；兴会，兴致；更无前，前所未有"]
  },
  "清平乐·会昌|毛泽东": {
    s: "上片抒情，「东方欲晓，莫道君行早」以「东方欲晓」写时间——东方快要天亮了，以「莫道君行早」写词人的行动——不要说你走得早，暗含「莫道君行早，更有早行人」之意，也暗示革命的道路还很长；「踏遍青山人未老，风景这边独好」以「踏遍青山」写革命的历程——走遍了青山，转战南北，以「人未老」写革命精神的旺盛——人还没有衰老，以「风景这边独好」写对会昌一带的赞美——这里的风景特别好，「独好」二字既写了自然风景，也暗含了对革命根据地的感情；下片写景，「会昌城外高峰，颠连直接东溟」写会昌城外的高峰——山峰连绵不断，一直连接到东海，「直接东溟」写出了山峰的连绵和壮阔；「战士指看南粤，更加郁郁葱葱」写战士们指着南方的广东方向看——那里的草木更加茂盛，「郁郁葱葱」既写了草木的茂盛，也比喻革命的生机和希望。全词意境开阔、写景抒情融为一体、充满革命乐观主义精神和对革命胜利的坚定信念，「踏遍青山人未老，风景这边独好」成为名句，是毛泽东诗词中的名篇。",
    b: "1934年夏，中央革命根据地第五次反「围剿」失利，形势十分危急。当时毛泽东因受到「左」倾路线的排挤，被调离红军主要领导岗位，在会昌一带做地方工作。7月的一天清晨，毛泽东登上会昌城外的岚山岭，面对南方的壮丽景色，回顾革命的战斗历程，写下了这首词，表达了对革命前途的乐观态度和对革命胜利的坚定信念。",
    n: ["清平乐：词牌名","会昌：县名，在江西南部，是中央革命根据地的南大门","东方欲晓：东方快要天亮了。欲，将要","莫道君行早：不要说你走得早。君，你，这里是词人自指，也可指红军战士","踏遍青山人未老：走遍了青山，人还没有衰老。踏遍青山，指转战南北；人未老，指革命精神还很旺盛","风景这边独好：这里的风景特别好。这边，指会昌一带；独好，特别好","会昌城外高峰：会昌城外的高峰，指会昌城外的岚山岭","颠连直接东溟：山峰连绵不断，一直连接到东海。颠连，山峰连绵不断；东溟，东海。溟音míng","战士指看南粤：战士们指着南方的广东方向看。指看，指着看；南粤，指广东，广东古属南越","更加郁郁葱葱：更加草木茂盛，充满生机。郁郁葱葱，草木茂盛的样子，也比喻气象旺盛"]
  },
  "十六字令三首|毛泽东": {
    s: "第一首写山之高，「山，快马加鞭未下鞍。惊回首，离天三尺三」以「快马加鞭未下鞍」写红军行军的急促——快马加鞭还没有下马，以「惊回首，离天三尺三」写山之高——猛然回头一看，山离天只有三尺三了，「惊」字写出了红军翻越高山时的惊叹，「离天三尺三」以夸张的手法极言山之高；第二首写山之势，「山，倒海翻江卷巨澜。奔腾急，万马战犹酣」以「倒海翻江卷巨澜」写群山的气势——群山像翻江倒海卷起巨大的波澜，以「奔腾急，万马战犹酣」写群山的动态——群山奔腾急促，像万马正在激烈地战斗，把静止的山写成了奔腾的万马，充满了战斗的激情；第三首写山之坚，「山，刺破青天锷未残。天欲堕，赖以拄其间」以「刺破青天锷未残」写山的锋利——山像宝剑一样刺破了青天，剑锋还没有残缺，以「天欲堕，赖以拄其间」写山的作用——天好像要塌下来，全靠山支撑在天地之间，把山写成了顶天立地的擎天柱，象征着红军和中国共产党顶天立地的英雄气概。三首小令各有侧重，第一首写高、第二首写势、第三首写坚，合起来塑造了一个高大、雄伟、坚定的山的形象，也象征着红军的英雄形象。全词想象奇特、比喻新颖、夸张巧妙、气势磅礴、充满革命英雄主义精神，是毛泽东诗词中短小精悍的名篇。",
    b: "1934年至1935年间，红军长征途中翻越了无数崇山峻岭。毛泽东在长征途中，面对连绵起伏的群山，写下了这三首小令，通过对山的三种不同形象的描绘，歌颂了红军不怕艰难险阻的革命英雄主义精神和顶天立地的英雄气概。",
    n: ["十六字令：词牌名，全词仅十六字，是最短的词牌之一","山，快马加鞭未下鞍：山啊，快马加鞭还没有下鞍。快马加鞭，跑得很快的马再加上几鞭，比喻快上加快；未下鞍，还没有下马","惊回首，离天三尺三：猛然回头一看，山离天只有三尺三了。惊，猛然；回首，回头看；离天三尺三，极言山之高，是夸张的说法","山，倒海翻江卷巨澜：山啊，像翻江倒海卷起巨大的波澜。倒海翻江，形容声势浩大；巨澜，巨大的波澜。这里把山比作翻江倒海的波澜","奔腾急，万马战犹酣：群山奔腾急促，像万马正在激烈地战斗。奔腾急，奔腾急促；万马战犹酣，像万马战斗正激烈。酣音hān，激烈，尽兴","山，刺破青天锷未残：山啊，刺破了青天，剑锋还没有残缺。锷音è，刀剑的刃；未残，没有残缺。这里把山比作刺破青天的宝剑","天欲堕，赖以拄其间：天好像要塌下来，全靠山支撑在天地之间。欲堕，将要塌下来；赖以，依靠它；拄音zhǔ，支撑；其间，指天地之间"]
  },
  "七律·冬云|毛泽东": {
    s: "首联「雪压冬云白絮飞，万花纷谢一时稀」以「雪压冬云白絮飞」写严冬的景象——大雪压着冬云，雪花像白絮一样飞舞，以「万花纷谢一时稀」写百花的凋谢——各种花纷纷凋谢，一时之间显得稀少，比喻在严峻的形势下，一些人动摇退缩了；颔联「高天滚滚寒流急，大地微微暖气吹」以「高天滚滚寒流急」写寒流的猛烈——高空的寒流滚滚而来十分急促，以「大地微微暖气吹」写暖气的微弱——大地上微微有暖气吹来，「寒流」与「暖气」对比，寒流虽然猛烈，但暖气已经在大地上萌生，比喻革命的力量虽然还微弱，但正在生长；颈联「独有英雄驱虎豹，更无豪杰怕熊罴」以「独有英雄驱虎豹」写英雄的无畏——只有英雄豪杰才能驱赶虎豹，以「更无豪杰怕熊罴」写豪杰的勇敢——更没有豪杰害怕熊罴，「虎豹」「熊罴」比喻凶恶的敌人，「独有」「更无」突出了革命战士不畏强暴的英雄气概；尾联「梅花欢喜漫天雪，冻死苍蝇未足奇」以「梅花欢喜漫天雪」写梅花的品格——梅花喜欢漫天的大雪，越是严寒越开放，以「冻死苍蝇未足奇」写苍蝇的下场——冻死了苍蝇也不值得奇怪，「梅花」比喻革命战士，「苍蝇」比喻微不足道的敌人，在严寒中梅花傲然开放，苍蝇却被冻死了，对比鲜明，寓意深刻。全诗比喻丰富、对比鲜明、对仗工稳、气势磅礴、充满革命英雄主义精神，是毛泽东诗词中托物言志的名篇。",
    b: "1962年冬，国际上反华势力猖獗，苏联领导人推行霸权主义，对中国施加压力，国内也面临着严重的经济困难。面对严峻的国际国内形势，毛泽东写下了这首诗，以冬云、寒流、虎豹、熊罴、苍蝇比喻凶恶的敌人和困难，以梅花比喻革命战士，表达了中国共产党和中国人民不畏强暴、敢于斗争的革命英雄主义精神。",
    n: ["冬云：冬天的云","雪压冬云白絮飞：大雪压着冬天的云，白色的雪花像棉絮一样飞舞。白絮，白色的棉絮，比喻雪花","万花纷谢一时稀：各种花纷纷凋谢，一时之间显得稀少了。万花纷谢，各种花纷纷凋谢；一时稀，一时之间显得稀少","高天滚滚寒流急：高空的寒流滚滚而来，十分急促。高天，高空；滚滚，形容水流翻腾，这里形容寒流的猛烈","大地微微暖气吹：大地上微微有暖气吹来。微微，轻微；暖气，指春天的暖气，也比喻革命的力量","独有英雄驱虎豹：只有英雄豪杰才能驱赶虎豹。独有，只有；英雄，指革命战士；驱，驱赶；虎豹，比喻凶恶的敌人","更无豪杰怕熊罴：更没有豪杰害怕熊罴。更无，更没有；豪杰，英雄豪杰；熊罴音pí，熊和罴，比喻凶恶的敌人。罴，棕熊","梅花欢喜漫天雪：梅花喜欢漫天的大雪。欢喜，喜欢；漫天，满天","冻死苍蝇未足奇：冻死了苍蝇也不值得奇怪。苍蝇，比喻微不足道的敌人；未足奇，不值得奇怪"]
  },
  "满江红·和郭沫若同志|毛泽东": {
    s: "上片写反华势力的猖獗和衰落，「小小寰球，有几个苍蝇碰壁」以「小小寰球」写地球之小，以「苍蝇碰壁」比喻反华势力的猖獗和失败——小小的地球上，有几个苍蝇在墙壁上乱撞；「嗡嗡叫，几声凄厉，几声抽泣」以「嗡嗡叫」「凄厉」「抽泣」写反华势力的叫嚣和悲哀——嗡嗡地叫，几声凄凉尖厉，几声抽抽泣泣，形象生动；「蚂蚁缘槐夸大国，蚍蜉撼树谈何易」用「南柯一梦」和「蚍蜉撼树」两个典故，写反华势力的狂妄和不自量力——蚂蚁沿着槐树爬还夸耀国家大，蚍蜉想摇动大树谈何容易；「正西风落叶下长安，飞鸣镝」以「西风落叶」比喻反华势力的衰落，以「飞鸣镝」写革命的攻势——正当西风落叶飘满长安的时候，我们射出了响箭；下片写革命形势和战斗决心，「多少事，从来急；天地转，光阴迫。一万年太久，只争朝夕」以「从来急」「光阴迫」写时间的紧迫，以「一万年太久，只争朝夕」写只争朝夕的战斗精神——一万年太久了，要争取早晨和晚上的时间，这是全词的名句，也是毛泽东革命精神的生动写照；「四海翻腾云水怒，五洲震荡风雷激」以「四海翻腾」「五洲震荡」写世界革命形势的高涨——四海之内翻腾，云水发怒；五大洲震荡，风雷激荡；「要扫除一切害人虫，全无敌」以「扫除一切害人虫」写战斗目标，以「全无敌」写革命的必胜信念——要扫除一切害人的虫子，全世界没有敌手。全词比喻丰富、用典贴切、气势磅礴、情感激昂、充满革命精神，「一万年太久，只争朝夕」成为千古名句，是毛泽东诗词中战斗精神的代表作。",
    b: "1962年冬至1963年初，国际上反华势力猖獗，苏联领导人推行霸权主义，与中国共产党的分歧日益加深。1963年元旦，郭沫若写了《满江红·1963年元旦抒怀》，词中表达了对国际形势的看法。毛泽东读了之后，于1月9日写了这首和词，以苍蝇、蚂蚁、蚍蜉比喻反华势力，以「四海翻腾」「五洲震荡」写革命形势，表达了中国共产党和中国人民不畏强暴、敢于斗争的革命精神。",
    n: ["满江红：词牌名","和郭沫若同志：1963年1月，郭沫若写了《满江红·1963年元旦抒怀》，毛泽东读了之后写了这首和词","小小寰球：小小的地球。寰球，地球","有几个苍蝇碰壁：有几个苍蝇在墙壁上乱撞。苍蝇，比喻国际上反华势力；碰壁，比喻遭到失败","嗡嗡叫：嗡嗡地叫，比喻反华势力的叫嚣","几声凄厉：几声凄凉尖厉的叫声。凄厉，凄凉尖厉","几声抽泣：几声抽抽搭搭的哭泣声。抽泣，低声哭泣","蚂蚁缘槐夸大国：蚂蚁沿着槐树爬，还夸耀自己的国家大。用唐李公佐《南柯太守传》「槐安国」典故——淳于棼梦入槐安国，当了驸马和南柯太守，醒来发现槐安国原来是槐树下的蚂蚁窝。缘，沿着；夸大国，夸耀自己的国家大","蚍蜉撼树谈何易：蚂蚁想摇动大树，谈何容易。蚍蜉音pífú，大蚂蚁；撼，摇动。用唐韩愈《调张籍》「蚍蜉撼大树，可笑不自量」诗意","正西风落叶下长安：正当西风把落叶吹到长安城下的时候。西风落叶，比喻反华势力的衰落；长安，汉唐都城，这里代指中国。用唐贾岛《忆江上吴处士》「秋风生渭水，落叶满长安」诗意","飞鸣镝：射出响箭。鸣镝音dí，响箭，古代射出时发出声响的箭，比喻革命的攻势","多少事，从来急：多少事情，从来都是急迫的","天地转，光阴迫：天地在运转，光阴紧迫。迫，紧迫","一万年太久，只争朝夕：一万年太久了，要争取早晨和晚上的时间。朝夕，早晨和晚上，形容时间短暂","四海翻腾云水怒：四海之内翻腾，云和水都在发怒。四海，指全世界；翻腾，指革命运动高涨；云水怒，云和水都发怒，比喻革命形势的猛烈","五洲震荡风雷激：五大洲震荡，风和雷都在激荡。五洲，指全世界；震荡，震动激荡；风雷激，风雷激荡，比喻革命运动的激烈","要扫除一切害人虫，全无敌：要扫除一切害人的虫子，全世界没有敌手。害人虫，比喻一切敌人；全无敌，全世界没有敌手"]
  },
  "水调歌头·重上井冈山|毛泽东": {
    s: "上片写重上井冈山的所见所感，「久有凌云志，重上井冈山」以「久有凌云志」写词人的远大志向——很早就有了凌云的壮志，以「重上井冈山」写这次行动——重新登上了井冈山；「千里来寻故地，旧貌变新颜」以「千里来寻故地」写行程之远——从千里之外来寻找旧地，以「旧貌变新颜」写井冈山的变化——旧的面貌变成了新的容颜，38年过去，井冈山发生了翻天覆地的变化；「到处莺歌燕舞，更有潺潺流水，高路入云端」以「莺歌燕舞」「潺潺流水」「高路入云端」写井冈山的新貌——到处莺歌燕舞，更有潺潺流水，高高的公路直通云端，描绘了一幅生机勃勃的井冈山新貌图；「过了黄洋界，险处不须看」以「过了黄洋界」写行程，以「险处不须看」写词人的豪迈——过了黄洋界，险要的地方也不必看了，「不须看」三字充满了对艰难险阻的蔑视；下片写革命的豪情和壮志，「风雷动，旌旗奋，是人寰」以「风雷动」「旌旗奋」写革命形势——风雷在动，旌旗在奋飞，这就是人间；「三十八年过去，弹指一挥间」以「三十八年过去」写时间的跨度，以「弹指一挥间」写时间的短暂——三十八年过去了，如同弹一下手指、挥一下手那样短暂；「可上九天揽月，可下五洋捉鳖，谈笑凯歌还」以「九天揽月」「五洋捉鳖」写革命的豪情壮志——可以上九天摘月，可以下五洋捉鳖，在谈笑声中高唱凯歌胜利归来，想象奇特、气势磅礴；「世上无难事，只要肯登攀」以「世上无难事」写革命的信念，以「只要肯登攀」写革命的精神——世界上没有困难的事情，只要肯攀登，这是全词的名句，也是毛泽东革命精神的生动写照。全词意境开阔、想象奇特、气势磅礴、情感激昂、充满革命豪情和乐观主义精神，「可上九天揽月，可下五洋捉鳖」「世上无难事，只要肯登攀」成为千古名句，是毛泽东诗词中革命豪情的代表作。",
    b: "1965年5月22日至29日，毛泽东重上井冈山，这是他1927年秋收起义后率部上井冈山创建中国第一个农村革命根据地以来，时隔38年第一次重上井冈山。在井冈山期间，毛泽东视察了井冈山的建设，会见了老红军、烈士家属和当地群众，回顾了井冈山的斗争历史，展望了革命的未来，写下了这首词，表达了将革命进行到底的决心和「世上无难事，只要肯登攀」的革命精神。",
    n: ["水调歌头：词牌名","重上井冈山：1965年5月，毛泽东重上井冈山，这是他1927年秋收起义后率部上井冈山以来，时隔38年第一次重上井冈山","久有凌云志：很早就有了凌云的壮志。凌云志，凌云的壮志，比喻远大的革命志向","重上井冈山：重新登上了井冈山","千里来寻故地：从千里之外来寻找旧地。故地，旧地，指井冈山革命根据地","旧貌变新颜：旧的面貌变成了新的容颜。指井冈山发生了翻天覆地的变化","到处莺歌燕舞：到处都是黄莺歌唱燕子飞舞。莺歌燕舞，形容春天的美好景象，也比喻革命形势的大好","更有潺潺流水：更有潺潺的流水。潺潺音chán，形容水流动的声音","高路入云端：高高的公路直通云端。高路，指盘山公路；入云端，直通云端，形容公路之高","过了黄洋界：过了黄洋界哨口。黄洋界，井冈山五大哨口之一","险处不须看：险要的地方也不必看了。不须，不必","风雷动，旌旗奋，是人寰：风雷在动，旌旗在奋飞，这就是人间。风雷动，比喻革命运动；旌旗奋，旌旗奋飞，比喻革命力量；人寰，人间","三十八年过去：三十八年过去了。从1927年毛泽东率部上井冈山到1965年重上井冈山，正好三十八年","弹指一挥间：如同弹一下手指、挥一下手那样短暂。弹指，佛家语，比喻时间极短；一挥间，一挥手之间","可上九天揽月：可以上到九天的高处去摘取月亮。九天，天的最高处；揽月，摘取月亮。揽，采摘","可下五洋捉鳖：可以下到五大洋的深处去捉鳖。五洋，指太平洋、大西洋、印度洋、北冰洋、南冰洋，泛指全世界的海洋；捉鳖，捉甲鱼，比喻擒拿敌人。鳖音biē，甲鱼","谈笑凯歌还：在谈笑声中高唱凯歌胜利归来。凯歌，胜利的歌","世上无难事：世界上没有困难的事情","只要肯登攀：只要肯攀登。登攀，攀登"]
  },
  "念奴娇·昆仑|毛泽东": {
    s: "上片写昆仑山的雄伟和功过，「横空出世，莽昆仑，阅尽人间春色」以「横空出世」写昆仑山的雄伟——横亘在空中，超出人世，以「莽昆仑」写昆仑山的辽阔——莽莽的昆仑山，以「阅尽人间春色」写昆仑山的古老——看尽了人间的春天景色；「飞起玉龙三百万，搅得周天寒彻」以「玉龙三百万」比喻积雪的山峰——飞起了三百万条玉龙，以「搅得周天寒彻」写昆仑山的寒冷——搅得整个天地都寒冷透了，想象奇特、气势磅礴；「夏日消溶，江河横溢，人或为鱼鳖」写昆仑山的「过」——夏天冰雪消融，江河洪水泛滥，人们有的被淹死变成了鱼鳖；「千秋功罪，谁人曾与评说」以反问写昆仑山的功过无人评论——千年的功绩和罪过，谁曾经给过评论？下片写改造昆仑山的伟大理想，「而今我谓昆仑：不要这高，不要这多雪」以「我谓昆仑」直接对昆仑山说话——现在我对昆仑山说，不要这么高，不要这么多雪；「安得倚天抽宝剑，把汝裁为三截？」以「倚天抽宝剑」写词人的豪情——怎么能够靠着天抽出宝剑，把你裁成三截？想象奇特、气势磅礴；「一截遗欧，一截赠美，一截还东国」写改造昆仑山的方案——一截送给欧洲，一截赠给美洲，一截还给东方各国，把昆仑山的雪水分给全世界；「太平世界，环球同此凉热」以「太平世界」写理想，以「环球同此凉热」写世界大同——太平的世界，全世界都同样享受这凉爽和温暖，表达了改造世界、实现世界大同的伟大理想。全词想象奇特、气势磅礴、意境壮阔、情感激昂、充满改造世界的伟大理想，「安得倚天抽宝剑，把汝裁为三截」「太平世界，环球同此凉热」成为名句，是毛泽东诗词中浪漫主义的代表作。",
    b: "1935年10月，毛泽东率领中央红军翻越岷山，即将到达陕北。在岷山上，毛泽东远望昆仑山的壮丽景色，回顾长征的战斗历程，展望革命的未来，写下了这首词。词人通过对昆仑山的描绘和评论，表达了改造世界、实现世界大同的伟大理想。",
    n: ["念奴娇：词牌名","昆仑：昆仑山，西起帕米尔高原，横贯新疆、西藏，东延入青海，是中国最大的山脉之一","横空出世：横亘在空中，超出人世。横空，横亘在空中；出世，超出人世","莽昆仑：莽莽的昆仑山。莽，莽莽，形容无边无际","阅尽人间春色：看尽了人间的春天景色。阅尽，看尽；春色，春天的景色，比喻人间的美好事物","飞起玉龙三百万：飞起了三百万条玉龙。玉龙，比喻积雪的山峰，昆仑山终年积雪，山峰连绵，像无数条玉龙；三百万，极言其多","搅得周天寒彻：搅得整个天地都寒冷透了。周天，整个天地；寒彻，寒冷透了","夏日消溶：夏天冰雪消融。消溶，消融","江河横溢：江河洪水泛滥。横溢，洪水泛滥","人或为鱼鳖：人们有的变成了鱼鳖。或，有的；为，变成；鱼鳖，鱼和鳖，指被淹死。鳖音biē","千秋功罪：千年的功绩和罪过。千秋，千年；功罪，功绩和罪过","谁人曾与评说：谁曾经给过评论。评说，评论","而今我谓昆仑：现在我对昆仑山说。谓，对……说","不要这高：不要这么高","不要这多雪：不要这么多雪","安得倚天抽宝剑：怎么能够靠着天抽出宝剑。安得，怎么能够；倚天，靠着天，形容宝剑之长","把汝裁为三截：把你裁成三截。汝，你，指昆仑山；裁，裁剪","一截遗欧：一截送给欧洲。遗音wèi，赠送","一截赠美：一截赠给美洲","一截还东国：一截还给东方各国。东国，东方各国","太平世界：太平的世界","环球同此凉热：全世界都同样享受这凉爽和温暖。环球，全世界；同此凉热，同样享受这凉热，比喻世界大同"]
  },
  "贺新郎·读史|毛泽东": {
    s: "上片写人类社会的发展史，「人猿相揖别。只几个石头磨过，小儿时节」以「人猿相揖别」写人类的起源——人和猿拱手相别，以「只几个石头磨过」写旧石器时代——只有几个磨过的石头，以「小儿时节」比喻人类社会的早期——像小孩子的时代；「铜铁炉中翻火焰，为问何时猜得？不过几千寒热」以「铜铁炉中翻火焰」写青铜器和铁器时代——铜铁炉中翻起火焰，以「不过几千寒热」写时间的短暂——不过几千年的冷暖，从石器时代到铜器铁器时代，人类社会经历了漫长的发展；「人世难逢开口笑，上疆场彼此弯弓月。流遍了，郊原血」以「人世难逢开口笑」写人生的苦难——人生在世难得开口一笑，以「上疆场彼此弯弓月」写战争的残酷——到战场上彼此弯弓如月，以「流遍了，郊原血」写战争的灾难——流遍了郊外原野上的血，人类社会的历史充满了战争和苦难；下片写对历史的评论，「一篇读罢头飞雪，但记得斑斑点点，几行陈迹」以「一篇读罢头飞雪」写读史的感慨——一篇历史读完头发已经白了像飞雪，以「斑斑点点」「几行陈迹」写历史的痕迹——只记得斑斑点点的几行陈旧遗迹；「五帝三皇神圣事，骗了无涯过客」以「五帝三皇神圣事」写传统的历史观——五帝三皇的神圣事业，以「骗了无涯过客」写对传统历史观的批判——欺骗了无数的后人，所谓「神圣事业」不过是欺骗后人的谎言；「有多少风流人物？盗跖庄蹻流誉后，更陈王奋起挥黄钺」以反问「有多少风流人物」引出真正的英雄——盗跖和庄蹻的名声流传到后世，更有陈胜奋起挥动黄钺，词人把农民起义领袖看作真正的风流人物，表达了历史唯物主义观点——人民群众是历史的创造者；「歌未竟，东方白」以「歌未竟」写词还没有写完，以「东方白」写革命即将胜利——歌还没有唱完，东方已经发白了，以景结情，表达了对革命胜利的信心。全词气势磅礴、概括力强、观点鲜明、用典自然、充满历史唯物主义精神，「盗跖庄蹻流誉后，更陈王奋起挥黄钺」「歌未竟，东方白」成为名句，是毛泽东诗词中咏史的代表作。",
    b: "1964年春，毛泽东在读了大量历史书籍后，写下了这首词，通过对人类社会发展史的概括和评论，表达了他的历史唯物主义观点——人民群众是历史的创造者，农民起义是推动历史发展的动力。词人以磅礴的气势概括了从人类起源到现代社会的历史，评论了历史上的英雄人物，歌颂了农民起义领袖，表达了对革命胜利的信心。",
    n: ["贺新郎：词牌名","读史：读历史","人猿相揖别：人和猿拱手相别。揖别，拱手告别，指人类从猿进化而来","只几个石头磨过：只有几个磨过的石头。指旧石器时代，人类使用打制石器","小儿时节：像小孩子的时代。比喻人类社会的早期","铜铁炉中翻火焰：铜铁炉中翻起火焰。指青铜器时代和铁器时代，人类使用铜器和铁器","为问何时猜得：请问什么时候能够猜得到。为问，请问；猜得，猜得到","不过几千寒热：不过几千年的冷暖。寒热，冷暖，指岁月。从铜器时代到毛泽东时代不过几千年","人世难逢开口笑：人生在世难得开口一笑。用唐杜牧《九日齐山登高》「尘世难逢开口笑」句","上疆场彼此弯弓月：到战场上彼此弯弓如月。疆场，战场；弯弓月，把弓拉得像月亮一样圆","流遍了，郊原血：流遍了，郊外原野上的血。郊原，郊外原野","一篇读罢头飞雪：一篇历史读完，头发已经白了像飞雪。头飞雪，头发白了像飞雪","但记得斑斑点点：只记得斑斑点点的历史痕迹。斑斑点点，形容历史痕迹的零散","几行陈迹：几行陈旧的遗迹。陈迹，陈旧的遗迹","五帝三皇神圣事：五帝三皇的神圣事业。五帝三皇，传说中的古代帝王；神圣事，神圣的事业","骗了无涯过客：欺骗了无数的过往行人。无涯，无数；过客，过往行人，指后人","有多少风流人物：有多少杰出的人物。风流人物，杰出的人物","盗跖庄蹻流誉后：盗跖和庄蹻的名声流传到后世。盗跖音zhí，春秋末期奴隶起义领袖；庄蹻音qiāo，战国末期楚国农民起义领袖；流誉，名声流传","更陈王奋起挥黄钺：更有陈胜奋起挥动黄色的大斧。陈王，陈胜，秦末农民起义领袖，曾称王；黄钺音yuè，黄色的大斧，古代帝王征伐时用的器具，这里指起义的武器","歌未竟，东方白：歌还没有唱完，东方已经发白了。竟，完毕；东方白，东方天亮了，比喻革命即将胜利"]
  },
  "七绝·为女民兵题照|毛泽东": {
    s: "首两句「飒爽英姿五尺枪，曙光初照演兵场」写女民兵的英姿——英姿飒爽地握着五尺步枪，清晨的阳光刚刚照在练兵场上，「飒爽英姿」写出了女民兵的豪迈矫健，「曙光初照」写出了练兵场的清晨景象，画面鲜明；后两句「中华儿女多奇志，不爱红装爱武装」写女民兵的精神——中华儿女多有不平凡的志向，不喜爱红装喜爱武装，「多奇志」写出了新中国女性的远大志向，「不爱红装爱武装」对比鲜明，写出了女民兵「不爱红装爱武装」的精神风貌，是全诗的名句。全诗画面鲜明、对比鲜明、语言精炼、情感激昂、充满对新中国女性的赞美和对全民皆兵的期望，「中华儿女多奇志，不爱红装爱武装」成为千古名句，是毛泽东诗词中歌颂女民兵的名篇。",
    b: "1961年，毛泽东的机要员小李参加民兵训练，拍了一张手持步枪的照片，送给毛泽东看。毛泽东看后非常高兴，当即题写了这首诗，歌颂了新中国女民兵的英姿飒爽和「不爱红装爱武装」的精神风貌，表达了对全民皆兵、保家卫国的期望。",
    n: ["七绝：七言绝句","为女民兵题照：为女民兵的照片题诗。1961年，毛泽东的机要员小李参加民兵训练，拍了一张持步枪的照片，毛泽东看后题写了这首诗","飒爽英姿五尺枪：英姿飒爽地握着五尺长的步枪。飒爽，豪迈矫健；英姿，英俊的姿态；五尺枪，五尺长的步枪","曙光初照演兵场：清晨的阳光刚刚照在练兵场上。曙光，清晨的阳光；初照，刚刚照耀；演兵场，练兵场","中华儿女多奇志：中华儿女多有不平凡的志向。奇志，不平凡的志向","不爱红装爱武装：不喜爱红色的装束，喜爱武装。红装，红色的装束，指女性的打扮；武装，军装，指军事训练"]
  },
  "七律·登庐山|毛泽东": {
    s: "首联「一山飞峙大江边，跃上葱茏四百旋」写庐山的雄伟和登山的豪迈——一座山飞峙在长江边，跃上了苍翠的山峦盘旋了四百个弯，「飞峙」二字写出了庐山的雄伟，「跃上」二字写出了登山的豪迈；颔联「冷眼向洋看世界，热风吹雨洒江天」写对世界形势的观察和庐山的景色——用冷静的眼光向着海洋看世界，热风吹着细雨洒在江天之上，「冷眼向洋」写出了词人对世界形势的冷静观察，「热风吹雨」写出了庐山夏天的景色，一冷一热，对比鲜明；颈联「云横九派浮黄鹤，浪下三吴起白烟」写长江的壮丽景色——云横亘在长江九条支流之上，黄鹤在云中飘浮；波浪向下游的三吴地区冲去，泛起白色的烟雾，「云横九派」「浪下三吴」写出了长江的壮阔，「浮黄鹤」「起白烟」增添了浪漫色彩；尾联「陶令不知何处去，桃花源里可耕田」以陶渊明和桃花源的典故收尾——陶渊明不知道到哪里去了，桃花源里还可以耕田吗？用《桃花源记》的典故，问桃花源里是否还能耕田，暗含对理想社会的思考——理想中的世外桃源是否还能存在？全诗意境壮阔、用典自然、对仗工稳、情感深沉、充满对世界形势的观察和对理想社会的思考，「冷眼向洋看世界，热风吹雨洒江天」成为名句，是毛泽东诗词中写景抒情的名篇。",
    b: "1959年7月，毛泽东在庐山召开中共中央政治局扩大会议（即庐山会议），会议初期旨在总结「大跃进」以来的经验教训，纠正「左」的错误。会议期间，毛泽东登上庐山，面对庐山的壮丽景色和复杂的国内外形势，写下了这首诗，表达了对世界形势的观察和对理想社会的思考。",
    n: ["七律：七言律诗","登庐山：1959年7月，毛泽东在庐山召开中共中央政治局扩大会议（即庐山会议）期间，登上庐山，写下了这首诗","一山飞峙大江边：一座山飞峙在长江边。飞峙，飞耸屹立；大江，指长江。庐山在长江南岸，九江市南","跃上葱茏四百旋：跃上了苍翠的山峦，盘旋了四百个弯。葱茏，草木苍翠茂盛，这里指庐山；四百旋，指盘山公路有四百个弯道。旋，转弯","冷眼向洋看世界：用冷静的眼光向着海洋看世界。冷眼，冷静的眼光；向洋，向着海洋；看世界，观察世界形势","热风吹雨洒江天：热风吹着细雨洒在江天之上。热风，夏天的热风；洒，洒落；江天，江和天","云横九派浮黄鹤：云横亘在长江九条支流之上，黄鹤在云中飘浮。九派，长江在湖北江西一带的九条支流；浮黄鹤，飘浮着黄鹤，用崔颢《黄鹤楼》「黄鹤一去不复返，白云千载空悠悠」诗意","浪下三吴起白烟：波浪向下游的三吴地区冲去，泛起白色的烟雾。三吴，指吴郡、吴兴、会稽，泛指长江下游的江浙一带；白烟，白色的烟雾","陶令不知何处去：陶渊明不知道到哪里去了。陶令，陶渊明，曾任彭泽县令，故称陶令","桃花源里可耕田：桃花源里还可以耕田吗？桃花源，用陶渊明《桃花源记》的典故，指理想中的世外桃源。可耕田，可以耕田，这里问桃花源里是否还能耕田，暗含对理想社会的思考"]
  },
  "七律二首·送瘟神·其一|毛泽东": {
    s: "首联「绿水青山枉自多，华佗无奈小虫何」写血吸虫病的危害——绿水青山空自很多，华佗也对这小小的虫子无可奈何，「枉自多」写出了绿水青山的徒然，「华佗无奈小虫何」写出了血吸虫病的难治，连名医华佗也无可奈何；颔联「千村薜荔人遗矢，万户萧疏鬼唱歌」写血吸虫病造成的灾难——上千个村庄长满了薜荔，人们拉稀便；上万户人家萧条冷落，鬼在唱歌，「千村薜荔」「万户萧疏」写出了村庄的荒芜，「人遗矢」「鬼唱歌」写出了人民的苦难，画面触目惊心；颈联「坐地日行八万里，巡天遥看一千河」以浪漫主义的想象写词人的思绪——坐在地上一天就走了八万里，在天上巡游远远地看一千条银河，「坐地日行八万里」用地球自转的科学知识，「巡天遥看一千河」用宇宙运行的想象，想象奇特、气势磅礴，是全诗的名句；尾联「牛郎欲问瘟神事，一样悲欢逐逝波」以牛郎的典故收尾——牛郎想要问瘟神的事情，一样的悲欢离合都随着流逝的波浪而去了，牛郎是农民出身，关心民间疾苦，他问瘟神的事情，得到的回答是「一样悲欢逐逝波」——在旧中国，人民的悲欢离合都随着流逝的波浪而去了，瘟神肆虐，人民苦难。全诗意境壮阔、想象奇特、对比鲜明、情感深沉、充满对人民苦难的同情和对血吸虫病的控诉，「坐地日行八万里，巡天遥看一千河」成为千古名句，是毛泽东诗词中浪漫主义的代表作。",
    b: "1958年6月30日，《人民日报》发表了《第一面红旗——记江西余江县根本消灭血吸虫病的经过》的报道。毛泽东读了这篇报道后，非常激动，「浮想联翩，夜不能寐。微风拂煦，旭日临窗。遥望南天，欣然命笔」，于7月1日写下了《七律二首·送瘟神》。第一首写旧中国血吸虫病的危害和人民的苦难，第二首写新中国消灭血吸虫病的胜利和人民的欢乐。",
    n: ["七律二首·送瘟神：1958年7月1日，毛泽东读了《人民日报》关于江西省余江县消灭血吸虫病的报道后，「浮想联翩，夜不能寐」，写下了这两首诗。瘟神，指血吸虫病。送瘟神，送走瘟神，即消灭血吸虫病","绿水青山枉自多：绿水青山空自很多。枉自，空自，徒然","华佗无奈小虫何：华佗也对这小小的虫子无可奈何。华佗，东汉末年的名医；无奈……何，对……无可奈何；小虫，指血吸虫","千村薜荔人遗矢：上千个村庄长满了薜荔，人们拉稀便。薜荔音bìlì，一种蔓生植物，这里形容村庄的荒芜；人遗矢，人们拉稀便，遗矢，拉屎，矢同「屎」，血吸虫病的症状之一是腹泻","万户萧疏鬼唱歌：上万户人家萧条冷落，鬼在唱歌。萧疏，萧条冷落；鬼唱歌，形容死人多，鬼在唱歌","坐地日行八万里：坐在地上一天就走了八万里。地球赤道周长约四万公里，即八万里，地球自转一周，人坐在地上就随地球自转了八万里","巡天遥看一千河：在天上巡游，远远地看一千条银河。巡天，在天上巡游，指地球在宇宙中运行；一千河，一千条银河，指无数的星系","牛郎欲问瘟神事：牛郎想要问瘟神的事情。牛郎，神话传说中的牛郎，他是农民出身，关心民间疾苦","一样悲欢逐逝波：一样的悲欢离合都随着流逝的波浪而去了。悲欢，悲哀和欢乐；逐逝波，随着流逝的波浪而去"]
  },
  "七律二首·送瘟神·其二|毛泽东": {
    s: "首联「春风杨柳万千条，六亿神州尽舜尧」写新中国的欣欣向荣——春风吹拂着万千条杨柳，六亿中国人民都是尧舜一样的圣人，「春风杨柳」写出了新中国的欣欣向荣，「六亿神州尽舜尧」写出了对人民力量的赞美——六亿中国人民都是尧舜一样的圣人，这是对人民群众的高度评价；颔联「红雨随心翻作浪，青山着意化为桥」写新中国人民改造自然的力量——红色的雨随着心意翻作波浪，青山有意化为桥梁，「随心」「着意」写出了人民改造自然的主观能动性，红雨可以翻作浪，青山可以化为桥，人民的力量可以改变一切；颈联「天连五岭银锄落，地动三河铁臂摇」写人民劳动的壮阔场面——天连着五岭，银色的锄头落下；大地震动，三条河流的铁臂在摇动，「银锄落」「铁臂摇」写出了人民劳动的壮阔场面，「天连五岭」「地动三河」写出了劳动范围的广阔，气势磅礴；尾联「借问瘟君欲何往，纸船明烛照天烧」以送瘟神的仪式收尾——请问瘟君想要到哪里去？纸船和明烛照着天空焚烧，「借问瘟君欲何往」用反问写瘟神的末日，「纸船明烛照天烧」写送瘟神的仪式，欢庆消灭血吸虫病的胜利。全诗意境壮阔、想象奇特、对比鲜明、情感激昂、充满对人民力量的赞美和对胜利的欢庆，「春风杨柳万千条，六亿神州尽舜尧」「借问瘟君欲何往，纸船明烛照天烧」成为名句，与第一首形成鲜明对比，是毛泽东诗词中歌颂新中国的名篇。",
    b: "这是《七律二首·送瘟神》的第二首，写新中国消灭血吸虫病的胜利和人民的欢乐。与第一首写旧中国的苦难形成鲜明对比，表达了对新中国人民力量的赞美和对消灭血吸虫病胜利的欢庆。",
    n: ["春风杨柳万千条：春风吹拂着万千条杨柳","六亿神州尽舜尧：六亿中国人民都是尧舜一样的圣人。六亿，当时中国人口约六亿；神州，指中国；尽，都；舜尧，尧舜，传说中的古代圣君，这里指品德高尚的人","红雨随心翻作浪：红色的雨随着心意翻作波浪。红雨，红色的雨，这里指落花，也比喻革命的潮流；随心，随着心意","青山着意化为桥：青山有意化为桥梁。着意，有意；化为桥，化为桥梁","天连五岭银锄落：天连着五岭，银色的锄头落下。五岭，大庾岭、骑田岭、萌渚岭、都庞岭、越城岭；银锄，银色的锄头，指农民的劳动工具","地动三河铁臂摇：大地震动，三条河流的铁臂在摇动。三河，指黄河、淮河、海河，也泛指全国的河流；铁臂，铁一样的臂膀，指劳动人民的臂膀","借问瘟君欲何往：请问瘟君想要到哪里去。借问，请问；瘟君，对瘟神的戏称；欲何往，想要到哪里去","纸船明烛照天烧：纸船和明烛照着天空焚烧。纸船，民间送瘟神时用纸折的船；明烛，明亮的蜡烛；照天烧，照着天空焚烧，指送瘟神的仪式"]
  },
  "虞美人·枕上|毛泽东": {
    s: "上片写夜晚的愁苦，「堆来枕上愁何状，江海翻波浪」以「堆来枕上」写愁之多——愁堆积在枕上，以「江海翻波浪」比喻愁之深——像江海翻起了波浪，比喻奇特、情感深沉；「夜长天色总难明，寂寞披衣起坐数寒星」以「夜长天色总难明」写夜的漫长——夜很长，天色总是难以亮，以「寂寞披衣起坐数寒星」写词人的寂寞——寂寞地披上衣服起来坐着数寒星，「数寒星」三字写出了词人的寂寞和无聊，因思念而无法入睡，只能起来数星星；下片写清晨的思念，「晓来百念都灰尽，剩有离人影」以「晓来百念都灰尽」写天亮后的感受——天亮了，各种念头都像灰烬一样消失了，以「剩有离人影」写对妻子的思念——只剩下离人的影子，各种念头都消失了，只有对妻子的思念还在；「一钩残月向西流，对此不抛眼泪也无由」以「一钩残月向西流」写清晨的景色——一钩残月向西边流去，以「对此不抛眼泪也无由」写词人的伤感——面对这样的景色不抛眼泪也没有理由，「向西流」的「流」字写出了月亮移动的样子，也暗示了时光的流逝和离别的愁苦。全词情感真挚、婉约动人、比喻奇特、情景交融、充满对妻子的深切思念和离别的愁苦，是毛泽东诗词中唯一的一首纯爱情词，「堆来枕上愁何状，江海翻波浪」成为名句，与毛泽东后来气势磅礴的诗词风格形成鲜明对比，展现了毛泽东情感世界的另一面。",
    b: "1921年，毛泽东与杨开慧结婚后不久，因革命工作需要，不得不与杨开慧分别。在一个夜晚，毛泽东思念杨开慧，写下了这首词，表达了对妻子的深切思念和离别的愁苦。这是毛泽东诗词中唯一的一首纯爱情词，也是毛泽东最早的词作之一，情感真挚、婉约动人，与他后来气势磅礴的诗词风格截然不同。",
    n: ["虞美人：词牌名","枕上：在枕上。这是毛泽东1921年写给杨开慧的词，是毛泽东诗词中唯一的一首纯爱情词","堆来枕上愁何状：堆在枕上的愁是什么样子。堆来，堆积而来；愁何状，愁是什么样子","江海翻波浪：像江海翻起了波浪。形容愁之多、愁之深","夜长天色总难明：夜很长，天色总是难以亮。夜长，夜很长；总难明，总是难以亮","寂寞披衣起坐数寒星：寂寞地披上衣服起来坐着数寒星。披衣，披上衣服；数寒星，数着寒冷的星星","晓来百念都灰尽：天亮了，各种念头都像灰烬一样消失了。晓来，天亮了；百念，各种念头；灰尽，像灰烬一样消失了","剩有离人影：只剩下离人的影子。离人，离别之人，指杨开慧；影，影子","一钩残月向西流：一钩残月向西边流去。一钩残月，一弯残月；向西流，向西边移动，「流」字写出了月亮移动的样子","对此不抛眼泪也无由：面对这样的景色不抛眼泪也没有理由。抛眼泪，流泪；无由，没有理由"]
  },
  "虽有嘉肴|《礼记》": {
    s: "文章以「嘉肴弗食不知旨」类比「至道弗学不知善」，就近取譬，把抽象道理讲得平易可亲；再从学、教两面分写「知不足」「知困」后的自省与自强，最后引《尚书》一语收束，层层推进，逻辑严密。",
    b: "选自《礼记·学记》，是战国时期儒家论述教育作用与教学规律的名篇，借日常饮食类比讲清「教学相长」的道理。",
    n: ["嘉肴：美味的肉食。肴，做熟的鱼肉","旨：甘美，味美","至道：最好的道理，指圣贤之道","自反：反躬自问，反省自己","自强：自我勉励、奋发图强。强，音qiǎng","教学相长：教和学两方面互相促进、共同提高","《兑命》：《尚书》篇名，「兑」音yuè","学学半：教人是学习的一半；前一「学」音xiào，同「敩」，教导"]
  },
  "大道之行也|《礼记》": {
    s: "文章以对比结构展开：先铺陈「大同」之世天下为公、人得其所、夜不闭户的图景，再写「大道既隐」后以礼义纲纪维系的「小康」，一理想一现实，对照鲜明；大量排比句式使理想社会的画面层层展开，气势充沛。",
    b: "选自《礼记·礼运》，记孔子在蜡祭之后与弟子言偃的谈话，提出「大同」「小康」两种社会理想，是儒家社会政治思想的经典表述。",
    n: ["天下为公：天下是公众的，天子之位传贤不传子","选贤与能：选拔贤德、推举有才能的人。与，同「举」","讲信修睦：讲求诚信，培养和睦风气","矜寡孤独：矜，同「鳏」，老而无妻；寡，老而无夫；孤，幼而无父；独，老而无子","分、归：分，职分；归，女子出嫁，此指各有归宿","外户而不闭：大门不用上锁。外户，从外面把门带上","大同：儒家理想中的太平盛世","小康：政教清明、礼义有序的社会，较「大同」次一等","世及：世袭，父传子为世，兄传弟为及"]
  },
  "桃夭|佚名": {
    s: "三章重章叠句，以桃花、桃实、桃叶层层推进，暗合新娘由新婚之美到多子多福、家族兴旺的祝愿；「灼灼」二字写花光如火，开后世以花喻美人的先河，欢快明朗，充满生活气息。",
    b: "出自《诗经·周南》，是周代祝贺新娘出嫁的喜庆乐歌，以桃花起兴，三章分别以花、果、叶祝愿新娘宜室宜家。",
    n: ["夭夭：桃花茂盛、枝条摇曳的样子","灼灼：花朵鲜艳明亮的样子。华，同「花」","之子于归：这位姑娘要出嫁。子，你；归，古代女子出嫁","宜：和顺、适宜，使家庭和睦","有蕡：果实硕大的样子。蕡，音fén","蓁蓁：树叶繁密茂盛的样子。蓁，音zhēn"]
  },
  "静女|佚名": {
    s: "全诗以男子口吻写成：先写赴约不见恋人、搔首徘徊的焦急，再写收到彤管、荑草后的欢喜；末章翻进一层——物以人重，草本寻常，因是美人所赠便觉「洵美且异」，痴情之态跃然纸上。",
    b: "出自《诗经·邶风》，写一对青年男女城角约会、互赠信物的情景，是《诗经》中最富生活情趣的爱情小诗之一。",
    n: ["静女：娴静的姑娘","姝：美丽。音shū","俟：等待。城隅，城角僻静处","爱而不见：故意躲藏起来不露面。爱，同「萲」，隐藏","踟蹰：徘徊、心里迟疑。音chíchú","娈：美好。音luán","贻我彤管：赠我一支红色的管草（或指红色管乐器）。贻，赠送","说怿女美：喜爱你的美丽。说怿，喜爱；女，同「汝」，指彤管","牧归荑：从郊外采来荑草赠我。归，同「馈」，赠送","洵：实在、确实","匪女之为美：不是这草本身美。匪，同「非」；女，同「汝」"]
  },
  "硕人|佚名": {
    s: "诗分四章：首章以一连串亲族身份写其出身高贵，次章连用六个比喻工笔细描容貌，尤以「巧笑倩兮，美目盼兮」化静为动，神韵全出；后两章写婚礼车驾之盛与齐国风物之饶，铺张得体，开后世铺陈写人的先河。",
    b: "出自《诗经·卫风》，写齐女庄姜出嫁卫庄公时的盛况与美貌，是中国文学史上最早、最著名的女性肖像描写之一。",
    n: ["硕人：高大白胖的美人，指卫庄公夫人庄姜","颀：身材修长。衣锦褧衣：内穿锦衣、外罩麻纱罩衣。褧，音jiǒng","柔荑：柔嫩的白茅嫩芽，喻手指纤细","凝脂：凝结的油脂，喻皮肤洁白细腻","蝤蛴：天牛幼虫，白而长，喻脖颈。音qiúqí","瓠犀：葫芦籽，洁白整齐，喻牙齿。音hùxī","螓首蛾眉：额如螓（小蝉）般方正，眉如蚕蛾触须般弯长","巧笑倩兮：笑靥美好。倩，两颊酒窝","美目盼兮：眼珠黑白分明、顾盼动人","敖敖：修长高大的样子","说于农郊：在城郊歇息。说，同「税」，停舍","庶姜孽孽：陪嫁的姜姓女子众多盛装"]
  },
  "黍离|佚名": {
    s: "三章重章叠唱，以稷由「苗」而「穗」而「实」的生长过程，对应愁绪由「摇摇」而「如醉」而「如噎」的层层加深，情景相生；「知我—不知我」的对照与呼天一问，把无人理解的孤愤推向极致，苍凉沉郁。",
    b: "出自《诗经·王风》。旧说东周大夫行役经过西周故都镐京，见宗庙宫室尽为禾黍，悲悯周室倾覆而作，后世遂以「黍离之悲」代指故国之思、亡国之痛。",
    n: ["黍、稷：黄米和高粱，泛指庄稼","离离：庄稼成行、繁茂的样子","行迈靡靡：脚步沉重迟缓。靡靡，缓慢","中心摇摇：心中恍惚、摇摇不安","此何人哉：这（亡国局面）是什么人造成的啊","如噎：喉咙堵塞，喻忧思难舒。噎，音yē"]
  },
  "君子于役|佚名": {
    s: "诗人巧选黄昏这一最惹愁思的时刻：鸡归埘、牛羊下括，万物各有所归，唯独征人归期无定，以禽畜知归反衬人不归，朴素白描中愈见深情；末句「苟无饥渴」退一步作祝愿语，体贴入微，语淡而悲。",
    b: "出自《诗经·王风》，写一位山村农妇在黄昏时分思念久役不归的丈夫，是最早的「闺怨」题材作品之一。",
    n: ["君子：此指从军在外的丈夫","于役：在外服徭役、兵役","曷至哉：什么时候才能回来。曷，何","埘：墙壁上挖成的鸡窝。音shí","不日不月：归期无定，没法用日月计算","佸：相会、团聚。音huó","桀：木桩，此指鸡栖的木架","下括：下来聚集。括，会集","苟无饥渴：但愿他不至于受饥受渴。苟，姑且、表祝愿"]
  },
  "无衣|佚名": {
    s: "两章短章重叠，先说自己并非无衣可穿，却偏觉「不如子之衣」，以退为进，把对赠衣者的感念写得真挚含蓄；「安且吉」「安且燠」从称心与温暖两处落笔，小中见情。",
    b: "出自《诗经·唐风》（注意与传诵的《秦风·无衣》「岂曰无衣，与子同袍」不是同一篇）。旧说为晋大夫感念晋武公命服之赐而作，全诗借衣怀人、因物感恩。",
    n: ["七、六：指衣上的章饰等级：侯伯之衣七章、卿六章，此以礼数之盛作比","子之衣：你（所赠、所制）的衣，旧说指晋武公命服","安且吉兮：舒适又美善","燠：暖和。音yù"]
  },
  "七月|佚名": {
    s: "全诗八章，以「衣食」为经纬：授衣、采桑、染织、狩猎写其劳，食郁枣、烹葵菽、筑场纳稼写其食，凿冰献羔、跻堂称觥写其岁时祭祀；历法上周历夏历并用，物候与人事交织，铺陈细密而井然，既见农人艰辛，也见古朴和乐，是研究上古社会的史诗性篇章。",
    b: "出自《诗经·豳风》，是《国风》中最长的一首叙事诗，以月令为线索，详记西周早期农人一年四季的生产劳动与生活，堪称上古农耕社会的风俗长卷。",
    n: ["七月流火：七月大火星偏西下行，标志暑退秋来。火，大火星（心宿二）","九月授衣：九月分发寒衣","一之日、二之日：周历正月、二月，当夏历十一月、十二月；下文三之日、四之日类推","觱发、栗烈：寒风呼啸、寒气凛冽。觱发音bìbō","褐：粗麻短衣","何以卒岁：靠什么度到年终","于耜、举趾：修理耒耜、抬脚下田耕作。耜音sì","馌彼南亩：把饭送到南边田头。馌音yè","田畯：农官。音jùn","载阳：开始暖和","仓庚：黄莺","懿筐：深筐","微行：小路。行音háng","爰求柔桑：于是采摘柔嫩桑叶","采蘩祁祁：采的白蒿很多。蘩，白蒿；祁祁，众多","殆及公子同归：怕被公子带走（写女心伤悲）","萑苇：芦苇，用以制蚕箔。萑音huán","蚕月条桑：养蚕之月修剪桑枝","斧斨：斧类工具，装柄孔方者为斨。音qiāng","猗彼女桑：拉住嫩枝采叶。猗同「掎」，牵引","鵙：伯劳鸟。音jú","载绩：开始纺麻线","载玄载黄，我朱孔阳：染成黑红、黄色，那朱红色尤其鲜亮。孔，很；阳，鲜明","秀葽：远志结子。葽音yāo","鸣蜩：蝉鸣。蜩音tiáo","陨萚：草木落叶。萚音tuò","于貉：去猎貉子。貉音hé","载缵武功：继续进行田猎习武。缵，继续","言私其豵，献豜于公：小兽归己、大兽献公。豵，一岁小猪；豜，三岁大猪，音jiān","斯螽、莎鸡：蚱蜢、纺织娘","穹窒熏鼠：堵好墙洞熏走老鼠","塞向墐户：堵上北窗、用泥涂好门缝。向，北窗；墐，涂泥，音jìn","改岁：过年","郁、薁：郁李、野葡萄。薁音yù","亨葵及菽：煮葵菜和豆子。亨同「烹」","剥枣：打枣。剥音pū，击","春酒、介眉寿：冬酿春成的酒；祈求长寿。介，助","断壶、叔苴：摘葫芦、拾麻籽。叔，拾取；苴音jū","采荼薪樗：挖苦菜、臭椿当柴。荼，苦菜；樗音chū","筑场圃：把菜园改筑成晒谷场","纳禾稼：把粮食收进仓","黍稷重穋：晚熟作物叫重、早熟叫穋。穋音lù","上入执宫功：还要到公家服劳役","宵尔索綯：夜里搓绳子。綯，绳","亟其乘屋：赶紧上房修缮。亟，急；乘，登","凿冰冲冲：凿冰声咚咚","纳于凌阴：藏进冰窖。凌阴，冰窖","蚤：同「早」，指早朝祭祖","献羔祭韭：献上羔羊、韭菜祭庙","肃霜、涤场：天高气爽、场院清扫干净","朋酒斯飨：捧上两樽酒聚饮。飨，享","跻彼公堂：登上公堂。跻，登","称彼兕觥：举起犀牛角杯。兕觥音sìgōng"]
  },
  "鹿鸣|佚名": {
    s: "三章以鹿得苹草呦呦相呼起兴，喻主人以美酒音乐、币帛礼遇嘉宾；一章重结纳之道、二章重立德示范、三章重和乐交心，层层写出宾主相得的雍雍气象，温厚和平，为宴饮诗之祖。",
    b: "出自《诗经·小雅》，是周王宴飨群臣嘉宾的乐歌，后来曹操《短歌行》曾化用其句表达求贤若渴之意。",
    n: ["呦呦：鹿鸣声。音yōu","苹、蒿、芩：三种可食的野草。芩音qín","鼓瑟吹笙：弹瑟吹笙宴乐宾客","承筐是将：主人命人捧上筐中布帛礼物赠客。将，奉上","周行：大道，此指治国的正道。行音háng","德音孔昭：美好的声名十分昭著。孔，很","视民不恌：给百姓做不轻薄的榜样。视，同「示」；恌，同「佻」","是则是效：以此为法则、去效仿","旨酒：美酒","式燕以敖：尽情宴饮遨游。燕，同「宴」","湛：深厚、尽兴。音dān，同「耽」"]
  },
  "采薇|佚名": {
    s: "全诗六章，前五章以薇菜的生长和战事的反复写久戍之苦、军容之壮，末章陡然收束于归途：以杨柳春日之乐景写昔日别哀，以雨雪严冬之哀景写今日归悲，今昔、物我、哀乐四重对照，被王夫之赞为「以乐景写哀，以哀景写乐，一倍增其哀乐」。",
    b: "出自《诗经·小雅》，写一位戍边士兵多年征战归来途中的回忆与悲慨，是中国最早的边塞征戍诗杰作。",
    n: ["薇：野豌豆苗，可食，戍卒采以充饥","作、柔、刚：薇菜初生、柔嫩、粗老，写时序推移","莫：同「暮」，岁暮","玁狁：北方游牧部族，即后来的匈奴。音xiǎnyǔn","不遑启居：没空安稳坐下。遑，闲暇","归聘：捎信回家。聘，问讯","王事靡盬：王室差事没有尽头。盬，止息，音gǔ","孔疚：非常痛苦。疚，病痛","尔：同「薾」，花盛开貌","路：同「辂」，高大的战车","四牡业业：四匹雄马高大健壮","骙骙：马强壮貌。音kuí","小人所腓：士兵借战车掩蔽。腓，庇护，音féi","象弭鱼服：象牙装饰的弓梢、鲨鱼皮箭袋","今我来思：如今我归来。思，语气词","雨雪霏霏：大雪纷纷飘落。雨，音yù，落"]
  },
  "愚公移山|列御寇": {
    s: "故事以「二山阻路」起、以「二山被负」终，结构完整；愚公与智叟的辩论是全篇文眼——愚公以发展的眼光看世代与山的消长，智叟以静止的眼光看残年与土石，命名上「愚」智「叟」的反讽更见褒贬，对比中凸显恒心的力量。",
    b: "选自《列子·汤问》，相传战国列御寇撰，以寓言形式讲述愚公率众移山、感动天帝的故事，阐明人定胜天、有志竟成的道理。",
    n: ["方七百里：方圆七百里","仞：古代七尺（一说八尺）为一仞","惩山北之塞：苦于山北道路阻塞。惩，苦于","迂：绕远","聚室而谋：集合全家商量","杂然相许：纷纷表示赞同","献疑：提出疑问","如……何：把……怎么办","焉置土石：把土石放到哪里","荷担者：能挑担的人。荷，扛","始龀：刚换牙，约七八岁。龀，音chèn","寒暑易节，始一反焉：冬夏换季才往返一次。反，同「返」","惠：同「慧」，聪明","其如土石何：又能把土石怎么样","长息：长叹","固不可彻：顽固到不能开窍。彻，通","穷匮：穷尽。匮，音kuì","亡以应：无话可答。亡，同「无」","厝：放置。音cuò","陇断：山冈阻隔。陇，同「垄」"]
  },
  "两小儿辩日|列御寇": {
    s: "短文以对话推进：两小儿分别从「视觉大小」和「触觉凉热」两个角度各执一理，论据都来自日常观察，合乎经验却结论相反；结尾孔子「不能决」并遭小儿一笑，非但不损圣人形象，反而彰显「知之为知之」的求真精神，机锋隽永。",
    b: "选自《列子·汤问》，写孔子路遇两个小孩争论太阳远近而不能决断，说明人的认识总有局限、求知应实事求是。",
    n: ["辩斗：辩论、争论","以：认为","去人：距离人","车盖：古代车上遮阳挡雨的圆伞","盘盂：盛物的圆盘和方器","沧沧凉凉：清凉微寒","探汤：把手伸进热水里。汤，热水","决：判断、判定","孰为汝多知乎：谁说你知识渊博呢。为，同「谓」；知，同「智」"]
  },
  "生于忧患，死于安乐|孟子": {
    s: "文章先以六个排比事例铺陈「生于忧患」的历史依据，再由个别上升到一般，层层推导个人成才与国家存亡的共同规律；句式短促整齐，使动用法密集，读来如重锤击鼓，最后「生于忧患，死于安乐」八字点题，警策千古。",
    b: "选自《孟子·告子下》，孟子列举舜、傅说等六位圣贤起于微贱的事例，论证忧患磨砺成才、安逸招致败亡的道理。",
    n: ["发、举：被起用、被选拔","畎亩：田间。畎，音quǎn","版筑：筑墙的活计","鱼盐：鱼盐贩子之列","士：狱官","故天将降大任：所以上天将要降下重大使命","苦、劳、饿、空乏：使……痛苦/劳累/挨饿/资财匮乏，均为使动用法","行拂乱其所为：使他所做的事颠倒不顺。拂，违背","动心忍性：使内心受到震动、性格变得坚韧","曾益：增加。曾，同「增」","恒过：常常犯错","衡于虑：思虑阻塞。衡，同「横」，梗塞","作：奋发有所作为","征于色，发于声：表现在脸色上、流露在言谈中","入、出：在国内、在国外","法家拂士：守法度的大臣和辅弼的贤士。拂，同「弼」"]
  },
  "鱼我所欲也|孟子": {
    s: "全文以比喻起论，由「舍鱼取熊掌」自然引出「舍生取义」的中心论点；再以正反对比——行道之人不食嗟来之食与为宫室妻妾而受万钟——批判见利忘义者丧失本心，设喻浅显而逻辑层层进逼，气势浩然。",
    b: "选自《孟子·告子上》，孟子以鱼与熊掌设喻，阐明「义重于生」、人应保有羞恶本心的主张。",
    n: ["熊掌：熊的脚掌，古人视为珍贵食物","兼得：同时得到","苟得：苟且偷生","患：祸患。辟，同「避」","何不用也：什么手段不用呢","由是：凭借这种办法","贤者能勿丧耳：贤人能够不丧失（本心）罢了","箪、豆：古代盛饭、盛羹的器具","呼尔而与之：吆喝着施舍给人","蹴尔：用脚踢着。蹴，音cù","不屑：认为不值得接受","万钟：很厚的俸禄。钟，古量器","何加：有什么益处","得我：感激我。得，同「德」，感恩","乡为身死而不受：从前宁可死也不接受。乡，同「向」","已：停止、罢休","本心：天性，此指羞恶之心"]
  },
  "得道多助，失道寡助|孟子": {
    s: "文章开门见山提出论点，随即以攻城不胜、守城弃逃两个战例逐层论证天时、地利、人和的轻重次序，再由军事推及治国，最后以「多助—寡助」的对比和「顺—畔」的结局收束，论证如剥笋，结论掷地有声。",
    b: "选自《孟子·公孙丑下》，孟子通过战争胜负的分析，提出「人和」是决定成败的根本，阐发其仁政思想。",
    n: ["天时、地利、人和：有利的时令气候、有利的地理条件、人心的团结","三里之城，七里之郭：内城方圆三里、外城七里","环而攻之：包围起来攻打","委而去之：弃城逃跑。委，放弃","域民：限制百姓定居","固国：巩固国防","威天下：威慑天下","寡助之至：帮助他的人少到极点","亲戚畔之：内外亲属都背叛他。畔，同「叛」","君子有不战：君子要么不战"]
  },
  "富贵不能淫|孟子": {
    s: "文章是一段精彩的驳论：先引景春之论立靶，再以「妾妇之道」类比揭穿公孙衍、张仪一味顺从君王的本质，最后正面提出居仁、由义、守礼的大丈夫标准；三个「不能」构成排比，如洪钟大吕，成为中华民族气节的经典宣言。",
    b: "选自《孟子·滕文公下》，孟子批驳纵横家以顺从权术为能的「妾妇之道」，树立儒家「大丈夫」的人格标准。",
    n: ["景春、公孙衍、张仪：均为战国纵横家，后两人以合纵连横游说诸侯","诚大丈夫：真正是大丈夫","安居而天下熄：他们安居家中，天下战火就平息","焉：怎么、哪里","丈夫之冠：男子二十行冠礼。冠音guàn","父命之：父亲给以训导","往之女家：到了你夫家。女，同「汝」","无违夫子：不要违背丈夫","以顺为正：把顺从当作正道","广居、正位、大道：朱熹释为仁、礼、义","与民由之：与百姓一同遵循正道而行","淫、移、屈：使……迷惑/动摇/屈服，使动用法"]
  },
  "湘夫人|屈原": {
    s: "全诗以候人不至为线索：开篇「袅袅秋风」二句以水边秋景写尽怅惘，被称为「千古言秋之祖」；中段铺陈水中筑室、百草充庭的华美幻境，越写越热闹，愈显梦醒后的失落；末段捐袂遗褋、搴杜若以待远者，缠绵悱恻，香草意象处处映衬高洁痴情。",
    b: "选自屈原《九歌·湘夫人》，是祭湘水女神的乐歌，写湘君（男神）期约湘夫人不至的思慕与惆怅，与《湘君》为姊妹篇。",
    n: ["帝子：天帝之女，指尧女娥皇、女英，舜妃，此即湘水女神","北渚：北边的小洲。渚，水中小块陆地","眇眇：极目远望的样子。愁予，使我发愁","袅袅：秋风轻柔吹拂貌","洞庭波兮木叶下：洞庭泛起波澜、树叶纷纷飘落","登白薠兮骋望：登上长满白薠的高地纵目。薠，草名，音fán","与佳期兮夕张：与佳人约会，傍晚张设帷帐","萃、罾：聚集；鱼网。鸟本当栖木却聚于水草、渔网本在水中却张到树上，喻所愿难遂","沅、醴：沅水、澧水；茝、兰皆香草","水裔：水边","济兮西澨：渡到西边水涯。澨，音shì","葺之兮荷盖：用荷叶盖屋顶","荪壁兮紫坛：荪草饰壁、紫贝铺庭","罔薜荔：编结薜荔。罔，同「网」","擗蕙櫋：剖开蕙草做屋檐板。擗音pǐ，櫋音mián","九嶷：九嶷山诸神。缤，众多貌","捐余袂、遗余褋：抛袖、弃单衣于水，寄情远者。褋，音dié","搴：拔取。汀洲，水中平地","骤得：屡次得到、轻易得到","容与：从容徘徊"]
  },
  "国殇|屈原": {
    s: "诗分两段：前段以白描再现短兵相接、车马交错的惨烈鏖战，节奏急促如金戈交鸣；后段直抒礼赞，歌颂将士视死如归、刚强不屈的精魂。通篇刚健雄浑，在《九歌》凄婉迷离的整体风格中独呈悲壮之色。",
    b: "选自屈原《九歌·国殇》，是追悼楚国阵亡将士的祭歌，约作于楚与秦争战失利之后，充满同仇敌忾的悲壮之气。",
    n: ["国殇：指为国战死的将士。殇，本指未成年而死，此指牺牲","操吴戈兮被犀甲：手持吴地利戈、身披犀牛皮甲。被，同「披」","车错毂：敌我车轮交错。毂，车轮中心，音gǔ","短兵接：短兵相接肉搏","凌余阵兮躐余行：敌军冲犯我阵、践踏我行列。躐，音liè","左骖殪兮右刃伤：左骖马倒地而死、右骖马被刃所伤","霾两轮兮絷四马：把两轮埋住、四马绊住，以示死战不退。霾同「埋」，絷音zhí","援玉枹：拿起玉饰鼓槌。枹，鼓槌，音fú","天时怼兮威灵怒：天昏地暗、神灵震怒。怼，怨恨，音duì","严杀尽兮弃原野：战士全部壮烈战死、尸骨弃于原野","首身离兮心不惩：身首分离而忠心不悔。惩，悔恨","神以灵：精神化为神灵、永不泯灭","鬼雄：鬼中豪杰"]
  },
  "涉江|屈原": {
    s: "诗作集纪行、写景、言志于一体：先以奇服宝璐的自我画像和驾龙游仙的想象表白高洁，中段写溯江南行的幽寂凄寒之景，景中见孤愤；再以接舆、伍子胥、比干自况，把个人不幸纳入自古忠贤的谱系，乱辞以善恶异位的比喻痛斥时世，悲而弥厉。",
    b: "选自屈原《九章·涉江》，为屈原第二次被放逐、渡江南下时所作，借纪行抒写守正不移、九死未悔的情志。",
    n: ["奇服：奇伟的服饰，喻高洁不同流俗的品格","长铗：长剑。陆离，长而错落貌","切云：高冠名，言其高可触云","被明月兮佩宝璐：披挂夜光珠、佩带美玉。被同「披」，璐，美玉","高驰：高高地驰骋于理想之境","青虬、白螭：青龙、白龙。螭音chī","重华：舜的名字。瑶之圃，昆仑仙境花园","南夷：指楚国南方僻远之地","鄂渚：地名，在今武昌一带","欸秋冬之绪风：叹息于秋冬余寒之风。欸，叹息，音ǎi","乘舲船：乘着有窗的小船。上沅，溯沅水而上","齐吴榜以击汰：齐举大桨击水。汰，水波","淹回水而疑滞：停留在回旋水流中难以前进。疑同「凝」","枉渚、辰阳、溆浦：皆沅水流域地名","儃徊：徘徊。音chánhuái","猿狖：猿猴。狖音yòu","霰：雪珠。垠，边际","接舆髡首、桑扈臝行：春秋楚国隐士接舆剃发、桑扈裸行以避世。髡音kūn，臝同「裸」","伍子逢殃、比干菹醢：伍子胥遭祸、比干被剁成肉酱。菹醢音zūhǎi，酷刑","董道：坚守正道。董，正","重昏：处于层层黑暗之中","乱：楚辞篇末总括全篇的乐章","鸾鸟凤皇：贤士；燕雀乌鹊，小人","巢堂坛：占据朝廷","露申辛夷：香草，喻君子；林薄，草木丛杂处","腥臊并御，芳不得薄：奸佞并进，贤人不得靠近。薄，接近","怀信侘傺：怀抱忠信而失意。侘傺音chàchì"]
  },
  "橘颂|屈原": {
    s: "全诗处处写橘、又处处写人：写橘「受命不迁」「深固难徙」，正是写自己眷恋宗国、九死不悔；写橘「精色内白」「秉德无私」，正是写内修外洁的人格。咏物与言志妙合无痕，四言为主、兮字助声，清峻挺拔，开后世咏物诗「体物写志」的传统。",
    b: "选自屈原《九章·橘颂》，是中国诗歌史上第一首完整的咏物诗，借咏橘言志，寄托自己扎根南国、忠贞不移的怀抱。",
    n: ["后皇嘉树：天地间美好的橘树。后，后土；皇，皇天","橘徕服兮：橘树生来适应南国水土。徕同「来」","受命不迁：秉受天性、不可迁徙（古谓橘过淮则化为枳）","素荣：白色的花","曾枝剡棘：枝条层叠、尖刺锐利。曾同「层」，剡音yǎn，锐利","圆果抟：果实圆滚滚。抟同「团」，音tuán","青黄杂糅：橘子青皮黄实相杂，色彩斑斓","精色内白：外表色泽鲜明、内瓤洁白","类任道：像担当道义的君子","纷缊宜修：香气馥郁、修饰合宜。缊音yūn","姱：美好。音kuā","廓其无求：心胸开阔、无所贪求","苏世独立：清醒地独立于世间。苏，苏醒","横而不流：特立独行而不随波逐流","闭心自慎：坚心守志、谨慎自持","秉德无私：持守美德、毫无私心","参天地：与天地并列","愿岁并谢，与长友：愿与橘树共度岁月、长为友朋","淑离不淫：美好而不过分。离同「丽」","梗其有理：枝干刚正、纹理分明，喻人有原则","行比伯夷：品行可比不食周粟的伯夷","置以为像：立为榜样。像，法式、榜样"]
  },
  "曹刿论战|左丘明": {
    s: "文章以「论战」为核心而非铺陈战阵：战前写曹刿与鲁庄公三问三答，得出民心向背才是战争根本；战中只用「未可」「可矣」两处节制之语制造悬念；战后「视辙望旗」的补叙和「彼竭我盈」的分析，把一位深谋远虑的平民战略家写得跃然纸上，剪裁精当。",
    b: "选自《左传·庄公十年》，记齐鲁长勺之战，是中国历史上以弱胜强的著名战例，也是《左传》战争描写与记言艺术的典范。",
    n: ["十年：鲁庄公十年（前684年）","齐师伐我：齐国军队攻打鲁国。我，《左传》以鲁纪年，故称我","肉食者：居高位享厚禄的人","间：参与。音jiàn","鄙：鄙陋，目光短浅","衣食所安：衣食这类安身之物","专：独自享用","牺牲玉帛：祭祀用的牛羊猪和玉帛","加：虚夸、虚报","孚：使人信服","小大之狱：大大小小的诉讼案件","虽不能察，必以情：即使不能一一明察，也一定按实情判断","忠之属也：这是尽职分一类的事","驰之：驱车追击","辙、轼：车轮碾痕、车前横木","既克：战胜以后","一鼓作气：第一次击鼓能振作士气","再而衰：第二次击鼓士气就衰减","三而竭：第三次士气耗尽","彼竭我盈：敌竭我盛。盈，饱满","靡：倒下"]
  },
  "烛之武退秦师|左丘明": {
    s: "全文以说辞为核心：烛之武不谈郑之存亡，只站在秦国立场层层算账——亡郑只利晋、舍郑反利秦、晋历来背信且贪得无厌，最终「阙秦以利晋」一句击中要害，使秦伯反与郑盟。说辞迂回曲折、步步紧逼，不卑不亢，是「一言兴邦」的辞令典范。",
    b: "选自《左传·僖公三十年》，记公元前630年秦晋围郑、烛之武夜入秦营凭一席话说退秦师的史事，展现高超的辞令艺术。",
    n: ["以其无礼于晋：因为郑国曾对晋文公无礼","贰于楚：表面从晋、暗中亲楚","军：驻军。函陵、氾南皆地名","佚之狐、烛之武：皆郑国大夫","缒而出：用绳子从城墙上吊下出城","执事：对秦伯的敬称，字面指办事人员","越国以鄙远：越过晋国把远方的郑国作边邑。鄙，边邑，作动词","焉用亡郑以陪邻：何必灭郑来增加邻国（晋）的土地。陪，增加","东道主：东方道路上招待过客的主人，后泛指请客主人","行李之往来：出使的人往来。行李，外交使者","共其乏困：供给他们缺少的物资。共同「供」","尝为晋君赐：曾对晋君施恩","朝济而夕设版焉：早上渡河回国、晚上就筑城防御，言晋背信之快","何厌之有：哪有满足的时候。厌同「餍」，满足","既东封郑：在东边使郑国成为它的疆界后","肆其西封：扩张西边的疆界","阙秦：使秦国受损。阙，损害，音quē","说：同「悦」","戍之：派兵驻守郑国","子犯：晋文公舅父狐偃","微夫人之力：没有那人（秦穆公）的力量。微，没有","因人之力而敝之：依靠过别人却去损害他。敝，损害","失其所与，不知：失掉同盟国是不明智的。知同「智」","以乱易整，不武：用冲突代替联合不算威武"]
  },
  "北冥有鱼|庄周": {
    s: "庄子以极度夸张的数字与想象塑造鲲鹏形象：鱼之化鸟、翼若垂云、水击三千里、抟上九万里，境界雄奇；又以野马尘埃作对照，提出大小虽殊、皆「有所待」的思考，奇诡汪洋，寓哲理于形象，开浪漫主义散文先河。",
    b: "选自《庄子·逍遥游》开篇，以鲲鹏展翅的宏阔想象阐发「有待—无待」的哲理，是庄子散文浪漫风格的代表。",
    n: ["北冥：北方的大海。冥同「溟」","鲲：传说中的大鱼","化而：变化成为","怒而飞：振奋地展翅。怒，奋发","垂天之云：天边垂下的巨云，形容鹏翼之大","海运：海水运动、海风起时","南冥、天池：南海；天然形成的大池","《齐谐》：记载怪异事物的书","志怪：记载怪异","水击三千里：翅膀拍击水面达三千里","抟扶摇而上：乘着旋风盘旋而上。抟，盘旋；扶摇，旋风","去以六月息：凭借六月的大风离开。息，气息，此指风","野马：春日野外蒸腾如奔马的雾气","生物之以息相吹：都是生物用气息互相吹拂","正色：真正的颜色","无所至极：没有尽头","其视下也：大鹏从天上往下看"]
  },
  "劝学|荀况": {
    s: "文章最突出的特色是博喻连翩：以青蓝、冰寒、木轮、金砺喻学习能改变和提升人，以登高、舆马、舟楫喻善假于物，以积土成山、骐骥驽马、朽木金石、蚓蟹对比喻积累与专一，二十余喻层见叠出而说理条贯，句式整散结合，朗朗可诵。",
    b: "选自《荀子·劝学》，系统论述学习的意义、态度与方法，是先秦论说文中劝学名篇，多用比喻和排比说理。",
    n: ["已：停止","青，取之于蓝，而青于蓝：靛青从蓝草中提取，却比蓝草更青。于，从/比","木直中绳：木材直得合于墨线。中，符合，音zhòng","輮以为轮：用火烤弯做成车轮。輮同「煣」","虽有槁暴：即使又晒干。有同「又」，槁暴，晒干，暴同「曝」","金就砺则利：金属刀剑拿到磨石上磨就锋利","参省乎己：对自己检验反省。参，检验；省音xǐng","知明：智慧明达。知同「智」","须臾：片刻","跂而望：踮起脚跟远望","彰：清楚","假舆马：借助车马。假，借助","利足：脚走得快","致千里：到达千里之外","绝江河：横渡江河","生非异：天性并无不同。生同「性」","跬步：半步。跨一脚为跬，跨两脚为步","骐骥、驽马：骏马、劣马","十驾：马拉车十天的路程","锲：刻","镂：雕刻","用心一也、用心躁也：因为用心专一/浮躁。一，专一"]
  },
  "扁鹊见蔡桓公|韩非": {
    s: "文章以时间为序层层推进：病由腠理→肌肤→肠胃→骨髓，扁鹊态度由劝告→复见→再劝→「望而还走」，桓公则由「寡人无疾」到体痛遂死，两条线索对照分明；最后以「逃秦」反衬无力回天，叙事极简而寓意深刻。",
    b: "选自《韩非子·喻老》，以扁鹊四见蔡桓公、病情逐层加深而桓公拒医致死的故事，阐明防微杜渐、虚心纳谏的道理。",
    n: ["立有间：站了一会儿。间，音jiān","腠理：皮肤的纹理，此指体表。腠音còu","将恐深：恐怕要加深","好治不病以为功：喜欢给没病的人治病来当作功劳","居十日：过了十天","肌肤：肌肉","不应：不回应","还走：转身就跑。还同「旋」，掉转","故使人问之：特意派人问他","汤熨：用热水焐、用药物热敷。汤同「烫」","针石：金针、石针","火齐：清火的汤药。齐同「剂」","司命之所属：司命神所管辖，医药已无能为力","无奈何：没有办法","索：寻找"]
  },
  "过秦论·上|贾谊": {
    s: "全文用的是「蓄势于前、逆转于后」的笔法：以极写秦国之强、六国之众、始皇之威层层铺垫，铺张扬厉；再以陈涉之卑微疲敝与之对比，「成败异变、功业相反」的巨大反差逼出最后一问一答，结论「仁义不施」水到渠成，气势磅礴而警策深刻，是汉代政论散文的巅峰之作。",
    b: "《过秦论》分上中下三篇，此为上篇，西汉贾谊所作，旨在总结秦朝速亡的历史教训，为汉文帝提供治国借鉴，「过秦」即指责秦政之失。",
    n: ["崤函：崤山、函谷关，关中险塞","雍州：古九州之一，今陕西一带","窥周室：暗中图谋夺取周室天下","席卷、包举、囊括：并吞之意，三词叠用","八荒：八方极远之地","商君：商鞅","连衡、合从：秦「连横」分化六国、六国「合纵」联合抗秦。从同「纵」","拱手：两手相合，言毫不费力","蒙故业，因遗策：继承旧基业、沿袭既定策略","膏腴：肥沃","致天下之士：招纳天下人才","相与为一：互相结盟成为一体","四君：孟尝君、平原君、春申君、信陵君","逡巡：犹豫不前。音qūnxún","亡矢遗镞：损失一支箭、一个箭头，言代价极小。镞，箭头","追亡逐北：追赶败逃的军队。北，败北","流血漂橹：血流成河能漂起盾牌","奋六世之余烈：振兴六代先王遗留的功业","振长策而御宇内：举起长鞭驾驭天下","吞二周而亡诸侯：吞并东西二周、灭亡各国","履至尊而制六合：登上帝位、控制天下","执敲扑：拿着刑具，喻以严刑统治","俯首系颈：低头降服、颈上系绳","委命下吏：把性命交给秦的小吏","却匈奴：使匈奴退却","焚百家之言：焚烧诸子百家著作","以愚黔首：使百姓愚昧。黔首，百姓","隳名城：毁坏名城。隳音huī","销锋镝：销毁兵器","践华为城，因河为池：据华山为城墙、就黄河为护城河","谁何：盘诘呵问行人","殊俗：不同风俗的边远之地","瓮牖绳枢：以破瓮为窗、以草绳系门轴，极言出身贫贱","氓隶、迁徙之徒：下层平民、被征发戍边的人","中人：平常人","蹑足行伍：投身军队行伍之间","揭竿为旗：举起竹竿当旗帜","赢粮而景从：担着粮食如影随形地跟从。景同「影」","山东：崤山以东","度长絜大：量量长短、比比大小。絜音xié，衡量","万乘：天子级别的势力","序八州而朝同列：使八州就位、使同等诸侯来朝","一夫作难而七庙隳：陈涉一人发难、秦宗庙尽毁。七庙，天子宗庙","身死人手：秦王子婴死于项羽之手","仁义不施而攻守之势异也：（结论）不施仁义，攻取与守成的形势就变了"]
  },
  "涉江采芙蓉|佚名": {
    s: "诗仅八句却有两层转折：前四句由采芙蓉起兴，乐景写哀——花再美，所思在远道，采之何用；后四句以望乡长路浩浩收束，空间的辽阔反衬人的孤独。语言浅近自然，情意含蓄不尽，代表《古诗十九首》「一字千金」的风格。",
    b: "选自《古诗十九首》，东汉末年无名文人所作，写游子涉江采莲、欲赠远方所思而不得的忧伤，是五言抒情诗成熟的标志。",
    n: ["芙蓉：荷花","兰泽：生有兰草的水泽","遗：赠送。音wèi","远道：远方","还顾：回头看","漫浩浩：无边无际","同心而离居：感情深厚却分居两地","终老：度过余生"]
  },
  "庭中有奇树|佚名": {
    s: "全诗以「奇树—繁花—折荣—馨香」一线贯穿，由景入情：花愈香、怀袖愈盈，路远莫致的怅惘愈深；末句反挑一笔——花不足贵，可贵的是别后的相思，卒章显志，温柔敦厚。",
    b: "选自《古诗十九首》，写一位思妇攀树折花、欲寄远人而路远难达，在一树繁花中写尽绵长相思。",
    n: ["奇树：佳美的树","华滋：花朵繁盛。滋，繁茂","攀条折其荣：攀着枝条折下花。荣，花","遗所思：赠给思念的人","馨香盈怀袖：花香沾满衣襟衣袖","致之：送到（他手中）","何足贵：有什么珍贵","但感别经时：只是因离别太久而感慨。但，只"]
  },
  "邹忌讽齐王纳谏|刘向": {
    s: "文章结构精巧：先写邹忌与徐公比美、三问三答、窥镜自视的家庭小事，再写他「暮寝而思」悟出私、畏、有求三种蒙蔽；继而以小喻大，由「一家之蔽」推及「一国之蔽」，讽齐王纳谏。叙事生动、推理自然，最后以「门庭若市—时时间进—无可进者」写改革成效，余味悠长。",
    b: "选自《战国策·齐策一》，写齐相邹忌以自身「比美」的生活体悟讽喻齐威王广开言路、革除蔽政，是「讽谏」艺术的名篇。",
    n: ["修：长，此指身高","昳丽：光艳美丽。昳音yì","朝服衣冠：早晨穿戴好衣帽。服，穿戴","窥镜：照镜子","孰与：与……相比，谁更……","旦日：第二天","孰视：仔细看。孰同「熟」","暮寝而思之：晚上躺着想这件事","私我：偏爱我","地方千里：土地方圆千里","宫妇左右：宫中姬妾和身边近臣","四境：全国","蔽：受蒙蔽","面刺：当面指责","谤讥于市朝：在公共场合议论（过失）","闻寡人之耳：使我听到","时时而间进：偶尔有人进谏。间，间或，音jiàn","期年：满一年。音jī","战胜于朝廷：在朝廷上修明政治就战胜了别国"]
  },
  "赠从弟·其二|刘桢": {
    s: "全诗以松喻人：先写松立高山、风盛而枝劲，再写冰霜惨凄而松姿端正，一问一答点出「本性」二字。咏物即咏怀，寄托了建安士人在乱世中追求的坚贞人格，语言质朴而骨力遒劲。",
    b: "刘桢，「建安七子」之一。《赠从弟》共三首，此为其二，以山上青松勉励堂弟坚贞自守、不因外力压迫而改变本性。",
    n: ["亭亭：挺拔直立的样子","瑟瑟：寒风声","一何：多么","劲：刚劲","惨凄：严酷凛冽","终岁：一年到头","罹凝寒：遭受严寒。罹，遭受，音lí","本性：天生的品性"]
  },
  "大风歌|刘邦": {
    s: "全诗仅三句却跌宕生姿：首句以风云起兴，写群雄逐鹿、定鼎天下的壮阔；次句写衣锦还乡的帝王之威；末句陡然一转，透出守成之难与求才之渴，豪迈中含苍凉，故被鲁迅称许为「楚风」遗响。",
    b: "汉高祖刘邦平定英布叛乱后归乡，置酒沛宫、自击筑而歌此诗，抒发帝业既成而渴求猛士镇守天下的豪情与隐忧。",
    n: ["兮：楚辞式语气词，相当于「啊」","威加海内：威望施加于天下。海内，天下","安得：怎样才能得到","猛士：勇猛的将士","守四方：镇守四方疆土"]
  },
  "木兰诗|北朝民歌": {
    s: "叙事诗按「叹息缘由—备装出征—征战生涯—辞官还乡—合家欢聚—兔喻作结」次第展开，繁简极具匠心：十年征战只用六句带过，而东市西市买马、归家理妆却不厌其详，以详略突出木兰的女儿本色与至孝至勇；复沓、排比、顶真、比喻交错使用，民歌风味浓郁。",
    b: "又名《木兰辞》，北朝乐府民歌，与《孔雀东南飞》并称「乐府双璧」，写少女木兰女扮男装、代父从军、功成辞赏的传奇。",
    n: ["唧唧：叹息声（一说织布机声）","当户织：对着门织布","机杼：织布机上的器件。杼音zhù","军帖：征兵文书","可汗大点兵：君主大规模征兵。可汗音kèhán","军书十二卷：征兵名册一卷接一卷，十二言其多","爷：父亲","市鞍马：买鞍马，代指备办战具","鞯、辔头：马鞍下的垫子、马笼头和缰绳","溅溅、啾啾：流水声、马鸣声","赴戎机：奔赴军机战事","度若飞：像飞一样越过","朔气传金柝：北方寒气中传来打更声。金柝，军中打更器具，音tuò","策勋十二转：记很大的功。策勋，记功；转，军功升一级为一转","百千强：成百上千还多。强，有余","尚书郎：尚书省的官","千里足：日行千里的坐骑","郭：外城","扶将：扶持","理红妆：梳妆打扮","霍霍：磨刀声","著我旧时裳：穿上从前的衣裙。著同「着」","帖花黄：在额上贴花黄（妇女面饰）。帖同「贴」","火伴：同伍的士兵。火同「伙」","扑朔、迷离：脚爬搔、眼眯缝的样子","傍地走：贴着地面跑","安能：怎能"]
  },
  "敕勒歌|北朝民歌": {
    s: "小诗先以「穹庐」喻天，写出草原民族独特的天地观——天如毡帐笼盖四野，亲切而壮阔；末句最妙：草高没牛羊，风过处牛羊时隐时现，静景化为动景，一派水草丰美、牛羊成群的生机，雄浑中含悠然。",
    b: "北朝乐府民歌，本为鲜卑语歌谣，译为汉语，歌咏阴山脚下敕勒川草原的辽阔丰美，境界雄浑。",
    n: ["敕勒川：敕勒族聚居的平原。敕勒，古代北方游牧民族，音chìlè","阴山：今内蒙古阴山山脉","穹庐：游牧民族的圆顶毡帐，即蒙古包","笼盖四野：像帐篷一样笼罩四面原野。野，旧读yǎ","苍苍：深青色","茫茫：辽阔无边","风吹草低见牛羊：风过处牧草伏低、露出成群牛羊。见同「现」"]
  },
  "与朱元思书|吴均": {
    s: "文章先以「奇山异水，天下独绝」总领，再分写水之「异」（缥碧见底、急湍猛浪，动静相生）与山之「奇」（负势竞上、泉响鸟鸣，以闹写静）；在工笔写景中插入「望峰息心」两句抒怀，使山水之美与厌弃尘俗之志交融，骈散相间、声韵铿锵。",
    b: "南朝梁吴均写给友人朱元思的书信节选，是六朝骈体山水小品的名作，描绘富春江富阳至桐庐一段的奇山异水。",
    n: ["风烟俱净：烟雾都消散净尽","天山共色：天与山融为一色","从流飘荡：任船随江流漂荡","自富阳至桐庐：今浙江境内富春江一段","缥碧：青白色。缥音piǎo","急湍甚箭：急流比箭还快","猛浪若奔：猛浪像奔马","负势竞上：山峦凭依地势争相向上","互相轩邈：彼此争着往高处、远处伸展。轩，高；邈，远","泠泠：清越的水声。音líng","嘤嘤：鸟鸣相和声。音yīng","千转不穷：长久不断地鸣啭。转同「啭」","鸢飞戾天：像鸢鸟高飞冲天，喻追求名利到极点。戾，至，音lì","望峰息心：望见雄峰便平息了竞进之心","经纶世务：经营筹划世俗事务。经纶，整理丝缕，引申为筹划","窥谷忘反：看到幽谷便流连忘返。反同「返」","横柯上蔽：横斜的树枝在上边遮蔽","疏条交映：稀疏枝条交错掩映"]
  },
  "七步诗|曹植": {
    s: "诗以煮豆为喻：萁在釜下燃、豆在釜中泣，拟人写来字字含泪；「同根」点出血缘，「相煎」直指迫害，取譬浅近而锋芒直指，七步成章，才思与悲愤俱在其中。",
    b: "相传魏文帝曹丕忌惮弟弟曹植，命其七步之内成诗，否则治罪，曹植应声吟成此诗，以豆萁煮豆讽喻骨肉相残。",
    n: ["豆萁：豆秸。萁音qí","釜：锅","燃：烧","本是同根生：豆子和豆秸本是同一条根上长出来的，喻同胞兄弟","相煎何太急：煎熬我何必这么急迫，喻兄长逼迫太甚。煎，煎熬"]
  },
  "梁甫行|曹植": {
    s: "诗以「八方风雨」起笔拉开视野，随即聚焦边海之民：寄身草野、妻儿如兽、柴门萧条、狐兔登堂，白描之中见触目惊心；末句以狐兔出入写人迹之稀、村落之荒，不言同情而同情自见，体现曹植后期诗歌沉郁的现实关怀。",
    b: "曹植晚年备受曹丕、曹叡猜忌，徙封无定、处境困窘。《梁甫行》写海边底层贫民的蛮荒生活，寄寓深切的悲悯，也暗含自身流离之慨。",
    n: ["八方各异气：八方气候各不相同","千里殊风雨：千里之内风雨不一","剧哉：多么艰难啊。剧，艰难","边海民：海边贫民","寄身草野：栖身在荒草野地","妻子象禽兽：妻子儿女像禽兽一样生活（极言其困苦）","行止依林阻：一举一动都依傍险阻山林","翔我宇：在我的屋檐下窜来窜去。翔，游走；宇，屋檐"]
  },
  "陈情表|李密": {
    s: "全文以「情」字驱动：先陈孤苦身世与祖孙相依为命，再陈进退两难的狼狈，继而以「圣朝以孝治天下」为依据消解武帝猜忌，最后提出「先尽孝、后尽节」的两全之策。融叙事、抒情、说理于一炉，四字句密集，骈散结合，凄恻动人，被誉为「读《陈情表》不哭者不孝」。",
    b: "李密曾任蜀汉尚书郎，蜀亡后晋武帝征他为太子洗马，他以祖母刘氏年迈病重为由上《陈情表》辞官，情辞恳切，终获准许。",
    n: ["险衅：命运坎坷、罪孽。衅，音xìn","夙遭闵凶：早年就遭遇不幸。闵同「悯」，此指父丧","见背：背弃我，是父亲去世的婉辞","舅夺母志：舅舅强迫母亲改变守节之志而改嫁","愍：怜惜。音mǐn","九岁不行：九岁还不能走路","零丁孤苦：孤苦无依。零丁同「伶仃」","成立：长大成人","终鲜兄弟：终究没有兄弟。鲜，少，音xiǎn","门衰祚薄：家门衰微、福分浅薄。祚，福分","期功强近之亲：关系较近的亲属。期、功为古代丧服名称，音jī","应门五尺之僮：照应门户的童仆","茕茕孑立，形影相吊：孤孤单单，只有身体和影子互相安慰。孑音jié；吊，安慰","婴疾病：被疾病缠身。婴，缠绕","蓐：草垫子，此指病床","逮奉圣朝：到了本朝（晋朝）","沐浴清化：蒙受清明教化","察臣孝廉、举臣秀才：察举、荐举为孝廉、秀才","供养无主：无人主持供养（祖母）","拜臣郎中、除臣洗马：任命为郎中、太子洗马。除，授官；洗音xiǎn","猥以微贱：像我这样卑微。猥，谦词","东宫：太子居处，代指太子","陨首：掉脑袋，言以死相报","切峻：急切严厉","责臣逋慢：责备我逃避怠慢。逋，逃避，音bū","急于星火：比流星火光还急","日笃：一天比一天沉重","告诉不许：申诉不被允许","狼狈：进退两难","伏惟：我恭恭敬敬地想（下对上的敬辞）","故老：遗老","矜育：怜悯养育","少仕伪朝：年轻时在伪朝（蜀汉）做官","郎署：郎官衙署","不矜名节：不自夸名节（打消晋武猜忌）","亡国贱俘：亡国的低贱俘虏，自谦","宠命优渥：恩宠优厚。渥，厚","盘桓：逗留不进","日薄西山：太阳接近西山，喻寿命将尽。薄，迫近","气息奄奄：呼吸微弱","朝不虑夕：早晨保不住晚上","更相为命：互相依靠维持性命。更相，互相","区区不能废远：拳拳孝心使我不能废止奉养而远离","乌鸟私情：乌鸦反哺之情，喻奉养长辈的孝心","愿乞终养：请求奉养（祖母）到最后","二州牧伯：梁州、益州的长官","皇天后土：天地神明","矜愍愚诚：怜悯我愚拙的诚心","听臣微志：准许我微小的心愿","保卒余年：保全祖母度过余年","死当结草：死后也当报恩（用魏颗结草典故）","犬马怖惧之情：像犬马一样惶恐的心情，表文套语"]
  },
  "长歌行|汉乐府": {
    s: "全诗托物言志：先以朝露易干、春荣秋枯写万物盛衰有时，再以百川东去不复返比喻时光一去不回，最后水到渠成逼出「少壮不努力，老大徒伤悲」的警策；由景入理，层层蓄势，结句朴素而力量千钧。",
    b: "汉代乐府《相和歌辞》名篇，以园葵起兴、以百川归海作比，劝人珍惜青春年华、及时努力，是最早的惜时劝学诗之一。",
    n: ["葵：葵菜，古代重要蔬菜","朝露待日晞：清晨的露水等待太阳晒干。晞，晒干，音xī","阳春布德泽：温暖的春天布施恩泽","焜黄华叶衰：花叶枯黄凋零。焜黄，颜色枯黄；华同「花」","百川东到海：千百条江河东流入海","复西归：再向西流回来","老大：年老"]
  },
  "十五从军征|汉乐府": {
    s: "全诗纯用白描，不着一字议论而批判自深：归乡的欣喜与「松柏冢累累」的真相迎头相撞；兔入雉飞、野谷野葵的荒宅细节，以及「饭熟不知饴阿谁」的一幕，把无家可归的悲怆写到极致；末句老泪纵横，无声胜有声。",
    b: "汉代乐府民歌，以一位十五岁从军、八十岁才还乡的老兵视角，写战乱之后家破人亡的惨状，是反战诗的杰作。",
    n: ["十五从军征，八十始得归：极言服役时间之长","阿谁：谁。阿，词头","遥看是君家：远远看去那就是你的家","冢累累：坟墓一个挨一个。冢，坟墓，音zhǒng","狗窦：给狗进出的墙洞","雉：野鸡","旅谷、旅葵：野生的谷子、葵菜。旅，不种自生","舂谷：捣掉谷壳。舂音chōng","持作饭、作羹：拿来做饭、做汤","饴：送给。音sì","沾我衣：浸湿衣裳"]
  },
  "兰亭集序|王羲之": {
    s: "文章由「乐」起、以「痛」转、以「感」收：先写兰亭良辰美景、群贤雅集之乐，笔致明丽；继而由聚散无常想到人生短促、死生之大，情调转入苍凉；最后批判庄子「一死生」「齐彭殇」的虚无，肯定生命的价值。骈散结合、清新自然，在玄言诗风行的东晋独树一帜。",
    b: "公元353年三月初三，王羲之与谢安等四十一位名士会于会稽兰亭，曲水流觞、饮酒赋诗，本文是王羲之为诗集所作的序，既是散文名篇，也是「天下第一行书」的法帖内容。",
    n: ["永和九年：东晋穆帝永和九年（353年）","岁在癸丑：干支纪年为癸丑年。癸guǐ","暮春之初：农历三月初，此指三月上巳日","会稽山阴：今浙江绍兴。会音kuài","修禊：古代三月上巳临水洗濯、祓除不祥的祭礼。禊音xì","群贤毕至，少长咸集：众多贤士都到了、年长年少者齐集","崇山峻岭：高峻的山岭","茂林修竹：茂密的林木、高高的竹子","清流激湍：清澈湍急的水流","映带左右：环绕映衬在亭子四周","流觞曲水：把酒杯放在弯曲水道上顺流而下，停在谁前谁就饮酒赋诗","列坐其次：依次坐在水边。次，旁边","一觞一咏：边饮酒边赋诗","幽情：深远的情怀","惠风：和风","仰观宇宙之大，俯察品类之盛：抬头观览天地之大、低头审视万物之多","游目骋怀：纵目浏览、舒展胸怀。骋，放开","信可乐也：实在快乐。信，确实","相与：相处、相交","俯仰一世：一生转瞬即逝","取诸怀抱，悟言一室之内：把胸怀抱负在室内与朋友面对面畅谈。悟同「晤」","因寄所托，放浪形骸之外：寄托情怀、放纵形骸于世俗之外","趣舍万殊：取舍千差万别。趣同「取」","暂得于己：一时感到自得","不知老之将至：竟忘了衰老将至（语出《论语》）","所之既倦：对所喜爱或得到的事物已经厌倦","感慨系之：感慨随之而生","向之所欣：从前感到欢欣的","俯仰之间：转瞬之间","修短随化：寿命长短听凭造化","终期于尽：最终都要归于死亡","死生亦大矣：死生也是人生大事（语出《庄子》）","兴感之由：发生感慨的缘由","若合一契：像符契一样吻合","临文嗟悼：面对古人文章叹息哀伤","不能喻之于怀：心里又不能明白释然","一死生为虚诞：把死和生等同起来是荒诞的。一，看作一样","齐彭殇为妄作：把长寿的彭祖与夭折的儿童等量齐观是虚妄的。彭，彭祖；殇，夭折者","列叙时人：一一记下当时与会的人","世殊事异：时代不同、事情变化","致一：情致相同"]
  },
  "诫子书|诸葛亮": {
    s: "文章以「静」字立骨：修身在静、成学在静，而「淫慢」「险躁」正是其反面；正面立论与反面警示交错，双重否定句式斩钉截铁；末段以「年与时驰」的紧迫感收束，把立志、为学、惜时一以贯之，言近旨远。",
    b: "诸葛亮晚年写给八岁儿子诸葛瞻的家书，短短八十六字，凝聚修身立志、为学做人的训诫，是千古传诵的家训名篇。",
    n: ["夫君子之行：君子的品行操守。夫，发语词","静以修身：以宁静专一来修养身心","俭以养德：以节俭来培养品德","淡泊：内心恬淡、不慕名利","明志：明确志向","宁静：摒除杂念、安宁专一","致远：达到远大目标","广才：增长才干","淫慢则不能励精：放纵懈怠就不能振奋精神。淫，过度；慢，懈怠","险躁则不能治性：轻薄浮躁就不能修养性情。治，修养","年与时驰：年华随同时光飞逝","意与日去：意志随同岁月消磨","枯落：像枯叶般凋落，喻人老而无成","多不接世：大多对社会没有贡献","穷庐：破房子","将复何及：又怎么来得及"]
  },
  "三峡|郦道元": {
    s: "文章先以正面描写与侧面烘托结合写山之高峻连亘，再按夏、春冬、秋的时序写水：夏水奔放、春冬清幽、秋景凄异，动静相生；结尾引渔者歌谣，以猿鸣哀转收束，把三峡的险与旅人的愁融为一体，炼字精当，节奏张弛有致。",
    b: "选自北魏郦道元《水经注·江水》，为古书《水经》作注时综合前人记载写成，仅用百余字就写尽三峡四季的雄奇幽美。",
    n: ["自三峡七百里中：在三峡七百里之间。三峡，瞿塘峡、巫峡、西陵峡","两岸连山，略无阙处：两岸山连着山，几乎没有中断处。阙同「缺」","重岩叠嶂：层层悬崖、排排峭壁。嶂，直立像屏障的山","隐天蔽日：遮蔽天空和太阳","自非亭午夜分：如果不是正午和半夜。自非，如果不是","曦月：日月。曦，日光，此指太阳，音xī","夏水襄陵：夏天江水漫上山陵。襄，冲上、漫上","沿溯阻绝：顺流而下和逆流而上的航路都被阻断。溯音sù","王命急宣：皇帝的命令要急速传达","朝发白帝，暮到江陵：早晨从白帝城出发、傍晚到江陵","乘奔御风：骑着奔马、驾着疾风","不以疾也：也不如它快","素湍绿潭：雪白的急流、碧绿的深潭","回清倒影：回旋着清波、倒映着景物","绝巘：极高的山峰。巘音yǎn","悬泉瀑布，飞漱其间：悬泉瀑布在山峰间飞流冲荡。漱，冲荡","清荣峻茂：水清、树荣、山高、草茂","良：甚、实在","晴初霜旦：雨后初晴或下霜的早晨","林寒涧肃：树林山涧清冷寂静","属引凄异：声音连续不断、凄凉异常。属音zhǔ，连接；引，延长","空谷传响：空荡的山谷传来回声","哀转久绝：悲哀婉转的声音很久才消失。转同「啭」"]
  },
  "答谢中书书|陶弘景": {
    s: "文章以「山川之美，古来共谈」总起，随即从高低（高峰清流）、色彩（石壁青林）、晨昏（晓雾夕日）、动静（猿鸟沉鳞）多角度铺陈，对仗工整而画面流转；末以谢灵运作衬，自豪地表示自己方能与古人同赏此奇，寥寥数笔，仙意盎然。",
    b: "陶弘景是南朝齐梁时的道教思想家，这是他写给友人谢中书的一封书信，短短六十八字，写尽江南山水之美，是六朝山水小品名作。",
    n: ["五色交辉：石壁色彩斑斓、交相辉映","四时俱备：四季景色都有","晓雾将歇：清晨薄雾将要消散","夕日欲颓：夕阳将要坠落。颓，坠落","沉鳞竞跃：潜游水中的鱼争相跃出。沉鳞，潜游的鱼","欲界之仙都：人间的仙境。欲界，佛家语，此指人间","康乐：指南朝宋山水诗人谢灵运，袭封康乐侯","与其奇者：欣赏这种奇丽山水。与，参与，此指欣赏，音yù"]
  },
  "归去来兮辞|陶渊明": {
    s: "全赋以「归」字为线索：首段写辞官归途的如释重负，二段写抵家后的天伦田园之乐，三段写躬耕出游的春日生机，末段纵论生死、委心乘化。叙事、写景、抒情、议论水乳交融，语言平淡自然而意蕴深远，「云无心以出岫」二句物我两忘，成为隐逸情怀的千古写照。",
    b: "陶渊明四十一岁辞去彭泽县令、归隐田园，本篇即辞官之初所作，是其归隐之志的宣言书，也是魏晋抒情小赋的代表作。",
    n: ["归去来兮：回去吧。来、兮皆语气词","田园将芜胡不归：田园将要荒芜，为什么还不回去。胡，为什么","以心为形役：让心灵被形体役使，即为免于饥寒而违心做官","奚惆怅而独悲：为什么还独自惆怅悲伤。奚，为什么","悟已往之不谏：认识到过去的已不可挽回。谏，止、挽回","知来者之可追：知道未来的还来得及补救","迷途其未远：误入迷途还不算远","今是而昨非：如今归隐对、从前出仕错","舟遥遥以轻飏：船轻快漂荡。飏，飞扬","征夫：行人","恨晨光之熹微：恨天亮得太慢。熹微，天色微明","乃瞻衡宇：终于望见自家简陋的房屋。衡同「横」，横木为门","载欣载奔：一边高兴一边奔跑","三径就荒：院中小路已近荒芜，用汉代蒋诩归隐典故","眄庭柯以怡颜：看看院中的树就露出喜色。眄，斜视，音miǎn","寄傲：寄托傲世之情","审容膝之易安：深知狭小之地也易安居。容膝，仅容双膝，极言屋小","策扶老以流憩：拄着拐杖随处歇息","矫首而遐观：抬头远望","云无心以出岫：云气自然而然从山间飘出。岫，山峰，音xiù","景翳翳以将入：日光暗淡、太阳将落。景同「影」，日光；翳翳，昏暗","盘桓：徘徊","请息交以绝游：让我断绝与官场的交游","复驾言兮焉求：还驾车出游追求什么。驾言，驾车，语出《诗经》","悦亲戚之情话：以与亲人说知心话为乐","将有事于西畴：要到西边田地里耕作。畴，田地","巾车、孤舟：有帷幕的小车、小船","窈窕、崎岖：幽深曲折、高低不平","欣欣以向荣：草木蓬勃生长","涓涓：细水缓流貌","善万物之得时：羡慕万物各得其时","感吾生之行休：感叹我的一生将要结束","已矣乎：算了吧","寓形宇内：寄身天地之间","委心任去留：随自己心意决定去留","遑遑：匆忙不安","帝乡不可期：成仙成神不可企及","怀良辰以孤往：爱惜美好时光独自出游","植杖而耘耔：放下手杖除草培苗。耔，培苗，音zǐ","登东皋以舒啸：登上东边高岗放声长啸","聊乘化以归尽：姑且顺着自然变化走向生命尽头","乐夫天命复奚疑：乐天知命还有什么可疑虑的"]
  },
  "读山海经·其十|陶渊明": {
    s: "诗前四句咏叹二神：精卫以微木填沧海、刑天断首犹舞干戚，力量悬殊而斗志不灭，「猛志常在」四字掷地有声；后四句一转，「徒设」「讵可待」在同情神话英雄壮志难酬的同时寄寓自身的悲慨，鲁迅因此称陶诗并非浑身静穆，也有「金刚怒目」的一面。",
    b: "陶渊明《读山海经》共十三首，此为第十首，借精卫、刑天两个神话形象抒发对不屈抗争精神的赞颂，也暗含自己壮志未酬的感慨。",
    n: ["精卫：神话中炎帝之女溺死东海后所化之鸟，衔木石填海","微木：细小的木枝","刑天：神话人物，与天帝争神被砍头，仍以乳为目、以脐为口，挥舞盾斧","干戚：盾与斧","猛志固常在：勇猛的斗志永远存在。固，本来","同物既无虑：化为异物（精卫、刑天）后已无顾虑","化去不复悔：身死化去也毫不后悔","徒设在昔心：空有昔日的壮志。徒，徒然","良辰讵可待：实现壮志的好时机又怎能等到。讵，岂，音jù"]
  },
  "五柳先生传|陶渊明": {
    s: "传文以「不知何许人」的模糊开篇，故意隐去姓名里籍，凸显超脱世俗的隐士形象；接着以「好读书、性嗜酒、安贫贱、著文章」四事白描，笔墨省净而风神毕现；赞语引黔娄之妻之言，以「不戚戚、不汲汲」点睛，再以无怀、葛天之民作结，平淡中见高趣。",
    b: "陶渊明以自况笔法为一位安贫乐道、好读书、性嗜酒、常著文的「五柳先生」作传，实为作者的自我画像，是中国文学史上第一篇自传体别传。",
    n: ["何许人：什么地方的人","不详其姓字：不清楚他的姓名","因以为号焉：就用（五柳）作为自己的号","不慕荣利：不羡慕功名利禄","不求甚解：读书只求领会要旨，不在字句上过分深究（与今义不同）","会意：有所领会","性嗜酒：生性酷爱喝酒","亲旧：亲戚旧友","或置酒而招之：有时备酒招待他","造饮辄尽：去喝酒就一定要喝尽兴。造，往、到；辄，就","期在必醉：图的是一醉。期，期望","曾不吝情去留：竟毫不掩饰去留的态度。曾不，竟不","环堵萧然：居室四壁空空、冷冷清清","短褐穿结：粗布短衣打满补丁","箪瓢屡空：饭篮水瓢常常空着，写贫困","晏如：安然自若的样子","兹若人之俦：这人应是五柳先生一类人吧。俦，类","戚戚、汲汲：忧愁不安、急切营求的样子","衔觞赋诗：饮酒作诗。觞，酒杯","无怀氏、葛天氏：传说中的上古太平时代帝王"]
  },
  "垓下歌|项羽": {
    s: "全诗仅四句，情感却两度跌宕：首句以拔山盖世自许，何等雄豪；二三句叹时运不济、骏马不驰，英雄失路之悲扑面而来；末句连呼「虞兮」，把对爱人的不舍与无力回天的痛惜交织在一起，刚极而柔，成为千古末路英雄的典型心声。",
    b: "楚汉相争末期，项羽被汉军围于垓下、夜闻四面楚歌，于帐中饮酒，对爱姬虞姬慷慨悲歌，此即《垓下歌》，是英雄末路的绝命词。",
    n: ["力拔山兮气盖世：力气能拔起大山、气概笼盖一世","时不利兮骓不逝：时运不利，连乌骓马也不肯奔驰。骓，青白杂色马，音zhuī","可奈何：能怎么办","虞兮虞兮奈若何：虞姬啊虞姬，把你怎么安排呢。若，你"]
  },
  "春山夜月|于良史": {
    s: "颔联是千古名句：捧水则月影入怀、弄花则香气沾衣，把水月、花香与人的动作融为一体，物我两惬；全诗由「忘归」起、以「惜芳菲」承、以钟声楼台收，清幽高远，兴致盎然。",
    b: "于良史为唐代天宝至大历间诗人，生平不详。此诗写春山夜游、赏月弄花的雅兴，是其传世名作。",
    n: ["胜事：美好的事","掬：双手捧起","芳菲：花草的芬芳，代指春景","翠微：青翠掩映的山腰幽深处"]
  },
  "行宫|元稹": {
    s: "诗以「宫花寂寞红」的乐景反衬行宫寥落，以「白头宫女」与「说玄宗」构成巨大的时间落差——盛世已成闲谈，无限沧桑尽在「闲坐」二字中，以少总多，含蓄隽永，被潘德舆誉为「十个字足赅《连昌宫赋》」。",
    b: "元稹此诗写安史之乱后洛阳行宫的冷落：红颜入宫、白头犹在，闲说玄宗旧事，以二十字包藏一代盛衰。",
    n: ["行宫：皇帝出巡暂住的离宫，此指洛阳上阳宫","寥落：冷落萧条","玄宗：唐玄宗李隆基，开天盛世的缔造者，亦亲历安史之乱"]
  },
  "闻乐天授江州司马|元稹": {
    s: "全诗以残灯、暗影、暗风、寒雨层层渲染凄凉，「惊坐起」三字于病体难支中陡然发力，惊的是友人命运、亦是自己身世；结句以景结情，风雨寒窗既是实景，也是两位迁客凄苦心境的外化。",
    b: "元和十年（815）白居易被贬江州司马，时元稹也因得罪权贵贬谪通州、正卧病，闻讯惊作此诗，写患难友情与同病相怜之痛。",
    n: ["乐天：白居易字乐天","江州司马：白居易被贬为江州（今九江）司马","幢幢：影子摇晃不定的样子。音chuáng","谪：贬官。音zhé","垂死病中：重病将死之时，夸张写病势沉重"]
  },
  "离思五首·一|元稹": {
    s: "小诗不直言情，而以「残妆—环钗—日射—红颊」四笔白描晨起情态，末句以「一朵红苏」喻胭脂颊上的鲜活，「欲融」二字化静为动，细腻传神，秾丽而不轻薄。",
    b: "此为元稹《离思五首》之一，组诗多为悼念亡妻韦丛而作，本篇截取晨起对镜的一个片段，写女子娇慵明艳之态，是组诗中偏于闺情刻画的一首。",
    n: ["残妆晓镜：清晨镜中残留昨夜妆色","环钗谩𥮾：环钗随意插在发间。谩，漫、随意；𥮾同「簪」，插","须臾：片刻","燕脂：即胭脂","一朵红苏旋欲融：红晕上脸、如红花复苏般几乎要融化。旋，随即"]
  },
  "春怨|刘方平": {
    s: "全诗以时间推移写愁绪加深：日落黄昏、金屋无人、空庭春晚、梨花满地，层层设色而终归于「不开门」的封闭；「梨花满地」既写暮春之景，又暗喻青春零落，情景双关，凄婉欲绝。",
    b: "刘方平，唐代诗人。此诗写一位幽居深宫（或深闺）的女子在春晚黄昏独自垂泪的寂寞，是宫怨诗的名篇。",
    n: ["金屋：用汉武帝「金屋藏娇」典故，此指华美而孤寂的宫室","春欲晚：春光将尽","梨花满地：梨花飘落满地，暗喻青春凋零"]
  },
  "蜀先主庙|刘禹锡": {
    s: "首联以「英雄气」笼罩全篇、笔力千钧；颔联写创业之艰（三分鼎、复汉业），颈联以「得相开国」与「生儿不贤」作尖锐对比，尾联以蜀妓舞魏宫的凄凉画面收束，兴亡之叹尽在不言中，用典精切、对仗工稳。",
    b: "刘禹锡任夔州刺史时谒刘备庙所作，全诗凭吊蜀汉兴亡，寄托对治乱兴衰的感慨。",
    n: ["蜀先主：蜀汉先主刘备，庙在夔州","凛然：令人敬畏的样子","三足鼎：魏蜀吴三分天下如鼎三足","业复五铢钱：以汉武帝五铢钱代指复兴汉室（王莽废五铢，光武复之）","得相：得到诸葛亮为相","不象贤：后嗣不肖，指后主刘禅昏庸。象，效法","蜀故妓来舞魏宫：蜀亡后，刘禅被迁洛阳，在司马昭宴上闻蜀伎歌舞而嬉笑，用《三国志》事"]
  },
  "始闻秋风|刘禹锡": {
    s: "诗以与秋风对话起笔，去年别、今年回，亲切而有岁月之慨；颈联最为警拔——战马思念边塞秋草而卷毛耸动、雄鹰顾盼青云而睡眼睁开，借马与雕的意象写出诗人老而弥坚的用世之心；末句扶病登台，豪情振起，一反悲秋老调。",
    b: "刘禹锡晚年多病，闻秋风而作此诗。与传统悲秋之作不同，本诗偏写秋风中奋厉向上的豪情，是其「诗豪」性格的写照。",
    n: ["君：此指秋风，以拟人语相呼","玄蝉：寒蝉，秋天黑色的蝉","五夜：五更天，将晓之时","飕飗：风声。音sōuliú","颜状：容貌，此指衰老之态","拳毛：卷曲的马毛","雕眄青云：雄鹰斜望青云。眄，斜视，音miǎn","肃清：秋气肃杀、天地清旷","扶病：抱病、带病"]
  },
  "西塞山怀古|刘禹锡": {
    s: "前四句以雄浑笔力写灭吴之战：楼船东下、王气黯然、铁锁沉江、降幡出城，一「收」一「出」，胜败如见；后四句由史入景，几回往事与山形依旧对举，人事代谢而江山不改，末以故垒芦荻的萧瑟秋景收束，怀古苍凉，被誉为唐人怀古七律压卷之一。",
    b: "长庆四年（824）刘禹锡由夔州赴和州，途经西塞山，触景生情，借西晋灭吴的史事慨叹六朝兴亡、国家统一之可贵。",
    n: ["西塞山：在今湖北大冶东，长江要塞","西晋楼船：晋将王濬率高大战船顺江灭吴。益州，今成都","金陵王气：金陵（今南京，吴都）的帝王之气","千寻铁锁：吴国在长江设千寻铁链横锁江面拦晋军。寻，八尺","沈江底：王濬以火炬烧断铁锁、沉入江底。沈同「沉」","降旛出石头：投降的旗子从石头城举起。旛同「幡」","四海为家：天下一统","故垒：旧时营垒"]
  },
  "竹枝词二首·一|刘禹锡": {
    s: "前两句以青柳平江、歌声隐隐铺出明丽背景；后两句是全诗神髓，借江南「太阳雨」的常见景象，以「晴」谐「情」，把初恋少女似有若无、忐忑试探的心理写得既含蓄又明朗，谐音双关天然入妙，是学习民歌的典范。",
    b: "刘禹锡任夔州刺史时学习民歌所作《竹枝词》之一，以少女口吻写江上闻歌、捉摸情人心意的微妙心理。",
    n: ["竹枝词：巴渝一带民歌，刘禹锡依声填词、多写风土爱情","唱歌声：西南男女恋爱以歌声传情","晴：谐音「情」，双关语"]
  },
  "秋词二首·一|刘禹锡": {
    s: "开篇即以议论立异——「秋日胜春朝」，断然否定悲秋老调；后两句以晴空孤鹤排云直上的明丽画面作论据，鹤之高举即诗人情志之高举，情景理三者合一，明快刚健，尽显贬中不馁的胸襟。",
    b: "刘禹锡贬朗州时作《秋词》二首，此为其一，以昂扬之笔翻写自古悲秋的传统主题。",
    n: ["悲寂寥：悲叹秋天冷落萧条","春朝：春天的早晨，代指春天。朝音zhāo","排云上：冲破云层、凌云直上","碧霄：碧蓝的高空"]
  },
  "杨柳枝词九首·一|刘禹锡": {
    s: "诗以两首前朝旧曲起兴作衬：梅花羌笛、淮南桂词，虽美皆属「前朝」；后两句直陈主张，「莫奏」与「听唱」对举，鲜明提出文学要与时俱进、翻为新声。以诗论艺，寓革新之志，爽朗明快。",
    b: "刘禹锡《杨柳枝词》九首之一，主张文学艺术应随时代创新，不要一味因袭旧曲。",
    n: ["塞北梅花羌笛吹：塞北羌笛吹奏《梅花落》古曲。羌音qiāng","淮南桂树小山词：西汉淮南王门客小山作《招隐士》，有「桂树丛生兮山之幽」句","新翻：新创作、翻新曲调","杨柳枝：即《杨柳枝词》，源于古横吹曲，刘禹锡翻新为新声"]
  },
  "再游玄都观|刘禹锡": {
    s: "诗以「百亩半苔、桃花净尽」写当年炙手可热的新贵烟消云散，以菜花取代桃花暗示政局翻覆；「前度刘郎今又来」一句倔强幽默，在戏谑中见不屈，十四年贬谪的傲骨尽在「又」字之中。",
    b: "刘禹锡因咏玄都观桃花诗讥讽权贵再度被贬，十四年后重还长安、再游玄都观而作此诗，是前诗《元和十年自朗州至京戏赠看花诸君子》的续篇。",
    n: ["玄都观：长安道观。观音guàn","苔：青苔，言游人绝迹","种桃道士：暗指当年扶植新贵的当权者","前度刘郎：上次来过的刘郎，诗人自指。度，次"]
  },
  "金陵五题·石头城|刘禹锡": {
    s: "全诗无一句人语，纯以山水明月写「空」字：青山依旧环拥故都、潮水拍打空城又寂寞退回，只有曾照六朝繁华的旧时明月，深夜还照例越过女墙。「寂寞」二字拟人，山、潮、月皆有情而人踪已绝，怀古之思苍茫无尽。",
    b: "刘禹锡《金陵五题》组诗之一，写六朝故都石头城的荒凉，寄托国运兴亡之叹，白居易曾「掉头苦吟，叹赏良久」。",
    n: ["石头城：今南京，六朝古都，此为《金陵五题》之一","故国：旧都、故都","周遭：四周环绕","淮水：秦淮河","女墙：城墙上凹凸的矮墙，即城垛"]
  },
  "和乐天春词|刘禹锡": {
    s: "前两句写新妆下楼、一院春愁，「锁」字双关院锁与心锁；后两句以「数花朵」写百无聊赖，更以蜻蜓误把美人当花、飞上玉簪的细节作结，灵动巧妙——人静如静物，愈显其孤寂，以美写愁，韵味悠长。",
    b: "刘禹锡此诗写一位新妆下楼、深院春愁的女子，以数花朵、蜻蜓停簪的细节写其寂寞无聊，是唱和白居易的宫怨佳作。",
    n: ["和乐天春词：酬和白居易《春词》之作","新妆面面：一作「新妆宜面」，言脂粉与面容相宜","深锁春光：春光被深锁院中，喻人被深锁楼中","玉搔头：玉簪的别称"]
  },
  "逢雪宿芙蓉山主人|刘长卿": {
    s: "前两句写日暮途远、天寒屋贫，渲染清冷孤寂；后两句于静极处忽闻犬吠、又见归人，以声破静、以动写静，「风雪夜归人」五字既写主人冒雪归家，也含诗人投宿得依的温暖，画面感极强。",
    b: "刘长卿逢雪夜投宿芙蓉山贫家所作，以短短二十字勾勒出一幅寒山雪夜投宿图。",
    n: ["芙蓉山主人：芙蓉山中的人家（主人是对居停人家的称呼）","白屋：以白茅覆盖的贫家屋","柴门：柴木编的门","夜归人：夜里冒雪归来的人"]
  },
  "听弹琴|刘长卿": {
    s: "前两句以泠泠琴声、松风寒意写琴调高古；后两句由琴及人、由乐及世——古调自爱而今人不弹，正是诗人怀才不遇、不合时俗的自况，言浅意深，慨叹含蓄。",
    b: "刘长卿借听琴咏怀，慨叹世风不古、知音难觅，是一首托物言志的五言绝句。",
    n: ["泠泠：清越的琴声。音líng","七丝：七弦琴","松风寒：琴曲有《风入松》，此兼写琴声如松间寒风","古调：古雅的曲调，亦双关古朴的操守"]
  },
  "送灵澈上人|刘长卿": {
    s: "全诗如一幅淡墨送客图：苍苍竹林、杳杳晚钟交代环境与时分，后两句写灵澈荷笠披一身夕阳、独自隐入青山，「带夕阳」三字尤妙，仿佛夕阳可披可戴；清寂高远，禅意悠然，别情不着一字而风神自远。",
    b: "刘长卿在润州（今镇江）送诗僧灵澈归山所作，是中唐送别诗中的清隽小品。",
    n: ["灵澈上人：中唐诗僧灵澈，上人是对僧人的敬称","竹林寺：在今江苏镇江","杳杳：深远幽暗，此指钟声悠远","荷笠：背着斗笠。荷，扛、背","独归远：独自向青山深处归去"]
  },
  "送李中丞之襄州|刘长卿": {
    s: "首联「曾驱十万师」极写昔日威风，与「流落」对举，盛衰立见；颈联「轻生一剑知」最为沉郁——将军出生入死的忠勇唯有随身长剑知晓，写尽功臣无人相知的悲凉；末以茫茫汉江、日暮何之收束，身世苍茫。",
    b: "刘长卿送别一位罢职流落、暮年漂泊的老将，对其功高失所寄予深切同情，也暗含对朝廷薄待功臣的微词。",
    n: ["李中丞：一位李姓御史中丞，曾为征南名将","之襄州：前往襄州","旧业：家乡产业","明时：政治清明的时代（含对朝廷的期许）","三朝：经历三朝","轻生：看轻性命、奋不顾身","何之：去往何处。之，往"]
  },
  "秋日登吴公台上寺远眺寺即陈将吴明彻战场|刘长卿": {
    s: "首联以摇落秋景起乡思；颔联野寺云峰写其荒僻；颈联是名句——残阳斜照旧垒、寒磬声满空林，视听交织，「依」「满」二字尤见苍凉；尾联由战场故垒想到南朝纷争，唯长江自流至今，吊古之情悠然而尽。",
    b: "刘长卿秋日登吴公台寺远眺，此地原为古战场，全诗吊古伤怀、兼写羁旅乡思。",
    n: ["吴公台：在今扬州，南朝陈将吴明彻战场遗址，后建寺","摇落：草木凋零，用宋玉「悲哉秋之为气也」意","旧垒：旧日营垒、战场工事","寒磬：寒空中传来的磬声。磬，寺中铜制打击乐器","南朝事：南朝兴亡旧事"]
  },
  "逢病军人|卢纶": {
    s: "诗不写征战之壮而写还乡之惨：行、病、无粮、未到乡，四层困厄层层叠加；末句「秋气入金疮」以寒气催裂旧伤的细节，把伤兵的痛楚写得具体可感，字字含泪，是对战争创伤的冷峻记录。",
    b: "卢纶这首七绝写一位在战争中负伤、带病乞讨还乡的退伍士兵，是中唐边塞诗中直面伤兵疾苦的现实主义佳作。",
    n: ["行多有病：行路既久、又带着病","住无粮：停下又没有口粮","万里还乡：从万里之外的边塞返乡","蓬鬓：鬓发蓬乱","金疮：刀剑创伤，此指战伤复发、遇秋寒而痛"]
  },
  "和张仆射塞下曲·一|卢纶": {
    s: "前两句以雕翎良箭、燕尾绣旗两件军物起笔，装备精良已见军容；后两句写将军独立台上、一声令下而千营同呼，以「一」与「千」的对比凸显号令严明、上下同心，短短二十字，声威如闻。",
    b: "卢纶《和张仆射塞下曲》六首之一，写将军登台发令、千营齐应的军威，是盛唐气象在中唐边塞诗中的回响。",
    n: ["张仆射：张延赏（一说张建封），仆射为官名。射音yè","鹫翎：雕翎，制箭羽的材料。鹫音jiù","金仆姑：良箭名","燕尾：旗上燕尾形飘带","蝥弧：春秋诸侯的旗名，此指军旗。蝥音máo","扬新令：发布新将令"]
  },
  "晚次鄂州|卢纶": {
    s: "颔联是写江行的名句：商人昼眠、舟人夜语，皆从听觉与推想落笔，于细微处见江上行船的生活气息；颈联由景入情，衰鬓逢秋色、归心对明月，乡思浩茫；尾联追及战乱根源，旧业已尽而鼓鼙又闻，把个人漂泊与时代丧乱拧在一起，沉郁苍凉。",
    b: "安史之乱中卢纶南逃避乱，途经鄂州泊舟所作，写战乱中归心似箭又前路茫茫的愁绪。",
    n: ["晚次鄂州：傍晚停船于鄂州（今武昌）。次，停宿","估客：商人。估同「贾」","舟人：船家","三湘：湘江流域统称","旧业：家乡产业","更堪：哪堪、怎能再受","鼓鼙：军中战鼓，代指战乱。鼙音pí"]
  },
  "贼平后送人北归|司空曙": {
    s: "首联以「同南去」与「独北还」对举，一别一留之间见出战乱离散；颔联是名句——他乡熬白了头发，故乡却只有青山依旧，人事之老与山河之常对举，悲慨深沉；后两联设想友人一路晓月残垒、寒禽衰草相伴，处处是战后荒凉，处处是送者愁心。",
    b: "安史之乱平定后，司空曙送友人北归故乡，自己却仍滞留南方，诗中既有劫后余生之慨，也有自伤留滞之情。",
    n: ["贼平：安史之乱平定","时清：时局清平","旧国：故乡","残垒：残破的营垒","故关：旧关隘","愁颜：带愁的面容"]
  },
  "云阳馆与韩绅宿别|司空曙": {
    s: "首联写江海一别、山川久隔；颔联是千古传诵的写重逢名句——乱世久别，忽然相见反疑是梦，悲从中来又互问年岁，「疑梦」「问年」把惊喜、苍老、辛酸和盘托出；颈联孤灯寒雨、湿竹浮烟渲染凄凉，尾联「明朝恨」使今宵之聚更显珍贵。",
    b: "司空曙在云阳驿馆与老友韩绅久别重逢、翌日又别，诗写乱世中骤逢乍别的悲喜交集。",
    n: ["云阳馆：云阳县的驿馆","宿别：同宿一夜又分别","几度：多少年","乍见：忽然相见","翻疑梦：反而怀疑是在梦里","问年：询问年岁","湿竹暗浮烟：湿润的竹林间浮动着如烟夜雾","离杯：饯别的酒杯","惜共传：珍惜地互相传递"]
  },
  "江村即事|司空曙": {
    s: "全诗以「不系船」立骨：钓罢、月落、人眠，本应系船而偏不系；后两句自答其故——纵使一夜风吹，船也不过漂在芦花浅水之边，何碍之有？于理是写江村水缓风平，于情是写人心无挂碍，疏懒闲远之趣跃然。",
    b: "司空曙这首小诗写渔者（或隐者）夜钓归来、任船自漂的洒脱，表现江村生活的闲适与安宁。",
    n: ["江村即事：就江村眼前之事赋诗","不系船：不把船拴在岸上。系，拴，音jì","正堪眠：正适合睡觉","纵然：即使","芦花浅水边：长满芦花的浅水边"]
  },
  "喜外弟卢纶见宿|司空曙": {
    s: "首联写静夜荒居、四邻无邻的清贫；颔联是名句——雨中飘零的黄叶树、灯下相对的白头人，树之将枯与人之将老互为比喻，兴象悲凉而对仗精工；后四句写沉沦之久、愧见亲情频顾，又以「蔡家亲」点明姑表之谊，悲中有温。",
    b: "司空曙家境清贫、仕途失意，表弟卢纶来访留宿，诗写荒居贫居中得亲人慰藉的悲喜。",
    n: ["外弟：表弟，卢纶是司空曙的表弟","见宿：来访并留宿。见，表动作指向自己","旧业：祖上产业","以我独沈久：因为我长久沉沦下僚。沈同「沉」","分：情谊、缘分。音fèn","蔡家亲：用羊祜为蔡邕外孙典故，指表亲关系"]
  },
  "题龙阳县青草湖|唐温如": {
    s: "前两句以秋风「吹老」洞庭波、一夜愁白湘君头，奇想惊人，把无形秋意写成催人老去之物；后两句更入化境——醉后忘却是天空倒映水中，只觉一船清梦沉甸甸地压在璀璨星河之上，亦真亦幻，缥缈如仙。",
    b: "唐温如生平无考，仅存此诗（一说为晚唐诗）。写秋夜洞庭醉后所见的奇幻景象，是唐诗中极具浪漫色彩的名篇。",
    n: ["龙阳县青草湖：在今湖南洞庭湖畔","湘君：湘水女神","天在水：天空倒映水中","清梦压星河：清梦仿佛压在银河之上。星河，银河"]
  },
  "宿业师山房期丁大不至|孟浩然": {
    s: "全诗以时间推移写山中向晚：夕阳度岭、众壑渐暝是暮色初临，松间月上、风泉满听是夜色全至，视觉与听觉交错，凉意可触；樵人归尽、烟鸟栖定以人鸟各归反衬候人不至，末以孤琴候径作结，静候之中自有雅人深致。",
    b: "孟浩然夜宿业师山房、等候友人丁大不至而作，写山中薄暮清幽之景与候人不至的悠然。",
    n: ["业师：一位法名含「业」字的禅师","山房：山中僧房","期丁大不至：约丁大来宿却未到。期，约定","群壑倏已暝：山谷忽然暗下来。倏，忽然；暝，昏暗","满清听：满耳都是清越声响","烟鸟：暮烟中的归鸟","之子：这个人，指丁大","萝迳：藤萝掩映的小路。迳同「径」"]
  },
  "宿桐庐江寄广陵旧游|孟浩然": {
    s: "首联以山暝猿愁、沧江夜流奠定凄清基调；颔联名句以风声叶鸣、月照孤舟写尽江上独宿的孤清——「两岸」之阔对「一舟」之孤，叶声可闻、月色可见，羁愁弥漫；后四句由建德异乡转到维扬旧游，泪寄海西，情深一往。",
    b: "孟浩然漫游吴越、夜泊桐庐江时作，写江上旅愁并寄怀扬州旧友。",
    n: ["桐庐江：即桐江，在今浙江","广陵旧游：扬州的旧友。广陵，今扬州","山暝：山色昏暗","建德：今浙江建德一带","非吾土：不是我的故乡（用王粲「虽信美而非吾土」意）","维扬：扬州别称","海西头：扬州地处东海西头"]
  },
  "与诸子登岘山|孟浩然": {
    s: "开篇「人事有代谢，往来成古今」如格言破空而来，道出宇宙人生的普遍规律，笼罩全篇；中间写登临所见水落泽深的寒旷之景；尾联落到羊公碑——羊祜有德于民、碑传后世，对比自己功名未立，读碑泪下，吊古正所以自伤，平淡中见深慨。",
    b: "孟浩然隐居襄阳时与友人登岘山，凭吊西晋名将羊祜，抒发人事代谢、怀古伤今之感。",
    n: ["岘山：在今湖北襄阳，西晋羊祜曾登此山。岘音xiàn","代谢：更替、兴衰交替","胜迹：名胜古迹，此指羊公碑等","鱼梁：渔梁洲，汉江中沙洲","梦泽：云梦泽，古大泽","羊公碑：百姓为纪念羊祜所立的碑，人见其碑莫不流泪，又名「堕泪碑」"]
  },
  "晚泊浔阳望庐山|孟浩然": {
    s: "诗以「几千里名山都未逢」作铺垫，欲扬先抑；「始见香炉峰」一「始」字，写出千里逢山的惊喜；后半由山及人，因读慧远之传而永怀尘外之踪，末以「日暮但闻钟」收束——望而不见、唯闻钟声，空灵淡远，余韵不尽。",
    b: "孟浩然泊舟浔阳、遥望庐山，因怀想东晋高僧慧远而作，写名山始见的欣喜与向慕隐逸的情怀。",
    n: ["晚泊浔阳：傍晚停船浔阳（今九江）","挂席：扬帆。席，船帆","郭：外城","香炉峰：庐山名峰","远公：东晋高僧慧远，曾在庐山建东林寺","尘外踪：超尘出世的踪迹","东林精舍：东林寺。精舍，僧道居所","但闻钟：只听见钟声"]
  },
  "岁暮归南山|孟浩然": {
    s: "首联「休上书」「归敝庐」看似自决，实含怨愤；颔联是全诗焦点——以「不才」「多病」自抑，以「明主弃」「故人疏」暗写见弃之怨，似哀实愤；后两联白发催年、青阳逼岁、永怀不寐、松月窗虚，把失意老至的孤苦写得清冷入骨。",
    b: "相传孟浩然在王维处偶遇唐玄宗，奉命诵诗，诵及「不才明主弃」，玄宗不悦，孟由此归山。此诗写求仕无门、岁暮归隐的怅惘。",
    n: ["岁暮归南山：年终归隐终南山（一题《归故园作》）","北阙：宫殿北面的门楼，代指朝廷。阙音què","休上书：不要再上书求仕","敝庐：破旧的家园","不才：不成材，自谦（实为怨语）","青阳逼岁除：新春催着旧岁过去。青阳，春天；岁除，年终","夜窗虚：月光下窗内空寂。虚，空寂"]
  },
  "送朱大入秦|孟浩然": {
    s: "前两句写友人将游武陵、腰间宝剑价值千金，为后两句蓄势；临别解剑相赠，赠的不只是千金之剑，更是平生相知的一片肝胆。语言质朴而豪气干云，颇有「宝剑赠烈士」的古侠遗风。",
    b: "孟浩然送别友人朱大入秦，以解剑相赠写任侠重义的豪情，是盛唐赠别诗中的短章精品。",
    n: ["朱大：一位朱姓友人，排行老大","入秦：到长安一带（秦地）去","游人：游子，指朱大","直千金：价值千金。直同「值」","脱：解下（相赠）"]
  },
  "宿建德江|孟浩然": {
    s: "首句点题泊舟，次句「客愁新」直启愁绪；后两句是千古名句：因野旷而觉天低于树、因江清而觉月近于人，一「低」一「近」体察入微——旷野苍茫反添孤愁，唯有水中明月可亲可近，以景写情，淡而有味，清绝千古。",
    b: "孟浩然漫游浙东、夜泊建德江所作，是写羁旅夜愁的五绝典范。",
    n: ["建德江：新安江流经建德的一段","移舟：移动小船靠岸","烟渚：烟雾笼罩的小洲。渚，水中小块陆地","客愁新：旅愁新添","野旷天低树：原野空旷，远处天空仿佛低于树木","江清月近人：江水清澈，水中月影仿佛近在身边"]
  },
  "渡浙江问舟中人|孟浩然": {
    s: "首句「潮落江平未有风」写尽渡江的平稳惬意，次句「扁舟共济」点出同舟之缘；后两句写频频引颈遥望天边、辨认何处青山是目的地越中，期待之情如在目前，语言浅白而风神散朗。",
    b: "孟浩然渡钱塘江时作，写与同舟人共渡、遥望越中的情景，于行旅中见从容兴致。",
    n: ["浙江：钱塘江","扁舟共济：乘小船一同渡江。扁音piān","引领：伸长脖子远望","天末：天边","越中：今浙江绍兴一带，古越国地"]
  },
  "杂曲歌辞·游子吟|孟郊": {
    s: "前四句白描慈母缝衣：手中线、身上衣，临行密密缝、意恐迟迟归，细节越细，母爱越深；后两句翻进一层作比——子女如寸草、母爱如三春阳晖，小草怎能报答春光于万一？以常景喻至情，朴素真挚，成为母爱的千古绝唱。",
    b: "孟郊任溧阳县尉时迎养母亲而作，以缝衣细节歌颂深挚母爱，是千古传诵的母爱诗，白居易曾评「诗到孟东野，天地为之清」。",
    n: ["游子：远游在外的人","临：将要","意恐：担心","寸草心：小草般微薄的心意，喻子女之心","三春晖：春天三个月的阳光，喻母爱深厚。晖，阳光"]
  },
  "古怨别|孟郊": {
    s: "诗以秋风飒飒起兴，渲染悲凉；「欲语气先咽」捕捉临别瞬间——千言万语堵在喉头，情态真切；「心曲千万端，悲来却难说」道尽情到深时反无言的共感；末句以天涯共月自慰，悲而不伤，留下温厚的余味。",
    b: "孟郊这首古体写情人（或友人）秋风中黯然话别的情景，刻画临别无言、悲从中来的复杂心理。",
    n: ["飒飒：风声","相向：相对","气先咽：话未出口先已哽咽。咽，哽咽，音yè","心曲：内心深处、心事","天涯共明月：远隔天涯共此一轮明月（后为张九龄「海上生明月」、苏轼「千里共婵娟」同调）"]
  },
  "武威送刘判官赴碛西行军|岑参": {
    s: "首句以五月火山、行人稀少反衬使者「马去疾如鸟」的迅疾豪壮；后两句更奇——行营远在太白星西，一声号角吹开胡天晓色，既写军营地之辽远，又暗喻唐军一令而边地重光，气象雄阔，盛唐边塞的豪迈跃然纸上。",
    b: "岑参在武威送同僚刘判官赴安西军前所作，以雄奇想象写边地行军的壮阔与唐军声威。",
    n: ["武威：今甘肃武威","刘判官：一位刘姓节度判官","碛西：沙漠以西，指安西都护府。碛音qì","火山：即火焰山，在今新疆吐鲁番，极言炎热","都护行营：都护的临时军营。太白西，太白星以西，极言其远","角：画角，军中号角","胡天晓：边地天色破晓"]
  },
  "山房春事二首·一|岑参": {
    s: "前两句总写风恬日暖、蝶蜂乱入，春光烂漫到「乱入房」；后两句特写：门柳垂枝低拂衣架、山花落瓣飘满笔床，以柳低、花落写山居与自然相融的闲趣，动静相宜，明丽如画。",
    b: "岑参《山房春事》二首之一，写春日山房明媚热闹、生机盎然的景象，于边塞雄浑之外另见清新一面。",
    n: ["山房春事：山居春日所见。此为组诗其一","风恬日暖：风和日丽。恬，安适","衣桁：晾衣架。桁音hàng","笔床：卧放毛笔的器具"]
  },
  "碛中作|岑参": {
    s: "首句「走马西来欲到天」以夸张写大漠与天相接的苍茫；次句以月两回圆计时，见出辞家之久而不言愁，愁在其中；后两句一问一答，今夜宿处不知、唯见万里平沙杳无人烟，视野愈阔、孤寂愈深，苍凉雄浑。",
    b: "岑参出塞途中行经大漠所作，写沙漠行军的辽阔荒远与辞家思乡之情。",
    n: ["碛中：沙漠之中。碛，沙漠，音qì","欲到天：仿佛要走到天尽头，极言大漠辽阔","见月两回圆：两次见月圆，言离家已两月","平沙：平坦无边的沙漠","绝人烟：没有人烟"]
  },
  "赵将军歌|岑参": {
    s: "前两句以「风似刀」「缩寒毛」极写九月天山奇寒，环境越酷烈，越反衬后两句将军的豪兴——博戏场场皆胜，连单于的貂袍都赢了来，苦寒之地反成英雄用武之场，豪迈乐观，妙趣横生。",
    b: "岑参这首七绝写边塞将军冬日围猎博戏、豪气纵横的生活，是盛唐边将精神风貌的生动剪影。",
    n: ["赵将军：一位赵姓边将","天山：在今新疆境内","缩寒毛：马因寒冷而鬃毛缩起","纵博：纵情博戏（军中赌赛游戏）","单于：匈奴君主称号，此指少数民族首领。音chányú","貂鼠袍：貂皮袍子，贵重御寒衣物"]
  },
  "春梦|岑参": {
    s: "前两句交代春风入房、故人远隔湘江，现实空间被江水阻隔；后两句转入梦境——枕上片刻春梦，竟走遍江南数千里，以梦境时间之短与空间之长对举，把刻骨相思托于迷离春梦，含蓄而奇警。",
    b: "岑参这首春梦诗写春夜怀人、梦中片时而行尽江南数千里，极写思念之深与梦境之快。",
    n: ["洞房：幽深的居室（非新婚洞房）","故人：老友（或所思之人）","片时：片刻","行尽：走遍"]
  },
  "巴山道中除夜书怀|崔涂": {
    s: "首联迢递三巴、羁危万里，写尽空间之远与身世之危；颔联名句以乱山、残雪、孤烛、异乡四词密集叠加，除夕本当团圆，诗人却独对孤烛迎「异乡春」，凄清入骨；颈联「渐与骨肉远，转于僮仆亲」道尽旅人微妙心理，真实动人；尾联以明日岁新反衬今夜漂泊，感慨弥深。",
    b: "崔涂，晚唐诗人，久在巴蜀漂泊。此诗作于巴山道中除夕，写乱山残雪之夜、异乡孤烛逢年的凄苦。",
    n: ["除夜：除夕之夜","迢遰：路途遥远。音tiáodì，同「迢递」","三巴：巴郡、巴东、巴西，今四川东部一带","羇危：漂泊在艰险之地。羇同「羁」","孤烛：一支孤烛","转于僮仆亲：反而与僮仆更亲近（写旅途孤苦）","岁华新：新的一年、岁月更新"]
  },
  "宿王昌龄隐居|常建": {
    s: "首联以清溪、孤云写隐者之高；颔联最妙——松梢微月初露、清辉洒落，仿佛仍为旧主人（王昌龄）而照，物犹有情，人何以堪；颈联茅亭花影、药院苔纹写居处幽寂；尾联直抒「余亦谢时去」的归隐之志，景清而志洁。",
    b: "常建游王昌龄旧日隐居处所作，既写隐居环境的清幽，也表达自己辞官归隐、与鸾鹤为群的志向。",
    n: ["王昌龄隐居：王昌龄早年隐居之处","隐处：隐居的地方","宿花影：花影仿佛静宿于茅亭","药院：种药的庭院","滋苔纹：长出青苔纹路","谢时：辞去世俗（出尘归隐）","鸾鹤群：与鸾鹤为群，指归隐山林"]
  },
  "题破山寺后禅院|常建": {
    s: "全诗沿游踪展开：入寺、见日、穿竹径、到禅院，渐入幽深；颈联是禅意名句——山光使鸟性怡悦、潭影使人心空，物我两忘；尾联以万籁俱寂、唯余钟磬作结，以声写静，袅袅钟磬把禅院的幽静与诗人的禅心融为一体，意境浑成。",
    b: "常建此诗题写于破山寺后禅院，是盛唐山水诗中融禅理于景物的千古名篇，宋代大书法家米芾曾书之。",
    n: ["破山寺：今江苏常熟虞山兴福寺","后禅院：僧人修行的后院","初日：初升的太阳","竹迳：竹林小路。迳同「径」","禅房：僧房","悦鸟性：使鸟儿性情欢悦","空人心：使人心境空明、涤除尘念","万籁：自然界一切声响。籁，孔穴发出的声音","钟磬：寺院诵经、斋饭时敲打的乐器。磬音qìng"]
  },
  "塞下曲四首·一|常建": {
    s: "诗不写征战之苦、也不写武功之盛，而写「朝回」之后的宁静：乌孙归心、不再称王，天涯静处再无征战，战争戾气消融于日月清辉。想象瑰伟、立意高远，表达了各族和睦、天下太平的美好愿望。",
    b: "常建《塞下曲》四首之一，借汉代乌孙和亲的史事，歌颂化干戈为玉帛、边塞安宁的太平理想，在边塞诗中别具一格。",
    n: ["塞下曲：此写和亲之后边塞安宁","玉帛：朝聘的礼物，此指乌孙与汉通好","帝乡：京城长安，代指汉朝","乌孙：汉代西域国名，曾与汉和亲","不称王：不再与汉分庭抗礼","兵气销为日月光：战争之气化为日月清辉，言天下太平"]
  },
  "书边事|张乔": {
    s: "首联以角声、戍楼勾出边塞轮廓；颔联写昭君青冢沐于春风、梁州边城落日安详，以「春风」「白日」暖色调暗示边地和平的可贵；颈联「大汉无兵阻，穷边有客游」——道路因无战事而畅通，游客可至，正反衬战时之苦；尾联以蕃情如水愿向南流作喻，寄托民族团结之愿。",
    b: "张乔，晚唐诗人。此诗写晚唐一度边和时的边塞景象，表达盼望民族和睦、边地长治的愿望。",
    n: ["书边事：记述边地之事","调角：吹角。调，吹奏。角，画角","断清秋：角声划破清秋","戍楼：边防城楼","青冢：王昭君墓，在今呼和浩特，相传草色常青","梁州：此指西北边地","穷边：极远的边塞","蕃情：吐蕃等少数民族的心意","向南流：心向中原（如江水南流般归顺）"]
  },
  "赋得自君之出矣|张九龄": {
    s: "前两句写丈夫离家后织机不复整理，以机残写心乱、以动作停摆写相思刻骨；后两句是神来之笔——思君之貌本如十五满月，却因夜夜相思而如月亮般一天天减却清辉，比喻新颖贴切，把抽象的憔悴化为可见的月相，含蓄温婉。",
    b: "张九龄沿用汉乐府旧题所作闺怨诗，以织机荒废、月渐亏缺写思妇念远之情。",
    n: ["赋得：按乐府旧题或限定题作诗的标志","自君之出矣：乐府《杂曲歌辞》旧题，「出矣」即出门离家","残机：残破的织机，因无心织布而搁置","满月：圆月","减清辉：月光一夜夜亏减，喻容颜因相思而憔悴"]
  },
  "宫词二首·一|张祜": {
    s: "全诗仅二十字却嵌进四个数字：三千里写空间之远、二十年写时间之长，空间与时间的双重囚禁压顶而来；后两句一声悲歌、双泪齐落，以「一」与「双」对举，二十年的委屈在一声哀歌中决堤。对仗天成，凝练沉痛。",
    b: "张祜这首宫词写一位远离家乡、幽闭深宫二十年的宫女，以一曲《何满子》倾泻积怨，是宫怨诗的绝唱，相传曾为宫人广泛传唱。",
    n: ["宫词：写宫中生活的诗","故国：故乡","河满子：唐教坊曲名，相传沧州歌者何满子临刑所唱，声调哀婉，一作「何满子」","君：皇帝"]
  },
  "集灵台二首·一|张祜": {
    s: "前两句以日光斜照、红树迎露铺写集灵台晨景，看似庄重明丽；后两句以「新授箓」「含笑入帘」轻轻一点——杨氏本为寿王妃，借出家为女道士（号太真）的名义入宫，「含笑」二字含蓄而讽刺入骨，体现宫词「婉而多讽」的特色。",
    b: "张祜《集灵台》二首之一，表面写上皇授箓、太真入帘，实则微讽唐玄宗纳儿媳杨玉环为妃的宫闱旧事。",
    n: ["集灵台：在骊山华清宫，为祭祀神灵之台","上皇：指唐玄宗（安史之乱后退位为太上皇）","授箓：道教传授符箓的仪式。箓，道教秘文，音lù","太真：杨贵妃为女道士时号太真","入帘来：进入帘内，暗讽其以道箓为名入宫"]
  },
  "题金陵渡|张祜": {
    s: "首句点出地点与「行人自可愁」的旅愁；后两句是写江夜的名句：潮落、夜江、斜月，清冷的大背景上，对岸瓜洲只有两三点如星灯火，以星火之「小」反衬江夜之「阔」，以明灭灯火反衬旅人之孤，宁静优美而愁思悠然。",
    b: "张祜旅途夜宿镇江金陵渡小楼，因羁愁难眠而作，写江上夜色与旅人孤寂。",
    n: ["金陵渡：在今江苏镇江（唐时亦称金陵渡，非南京）","津渡：渡口","小山楼：渡口小楼","行人：旅人，诗人自指","自可愁：自然要生愁","斜月：西斜的夜月","星火：灯火如星","瓜州：瓜洲，长江北岸渡口，与镇江隔江相望"]
  },
  "成都曲|张籍": {
    s: "前两句写锦江烟水碧绿、雨后山头荔枝红熟，绿与红相映，色彩明丽，已见蜀中物产丰美；后两句写万里桥边酒家林立、游人竟不知宿于何家，以问句收束，写尽成都的繁华好客与游人的惬意，轻快活泼。",
    b: "张籍此诗写成都锦江一带雨后清新明丽的风光与市井繁华，是一幅成都风土小画。",
    n: ["锦江：在成都，传说濯锦其中则锦色鲜艳","烟水：烟霭笼罩的江面","万里桥：在成都南，三国费祎使吴，诸葛亮饯行于此，曰「万里之行始于此」","向：在、到"]
  },
  "没蕃故人|张籍": {
    s: "首联交代前年全军覆没之惨；颔联「死生长别离」五字沉痛；颈联是名句，以废帐无人收、归马识残旗的战场细节侧面写全军覆灭，马犹识旗、人已无存，触目惊心；尾联「欲祭疑君在」捕捉最微妙的心理——存一线侥幸便不忍设祭，终于绝望，唯有天涯一哭，深挚入骨。",
    b: "张籍此诗悼念一位在唐蕃战争中全军覆没、生死不明的老友，写尽战争残酷与故人至情。",
    n: ["没蕃故人：与吐蕃作战中阵亡的老友。没，死；蕃音bō","伐月支：攻打月支（此借指吐蕃）。月支音yuèzhī","没全师：全军覆没","蕃汉：吐蕃与唐朝","废帐：废弃的军帐","归马识残旗：逃归的战马还认得残破军旗","欲祭疑君在：想祭奠又疑心你还活着"]
  },
  "秋思|张籍": {
    s: "诗以「见秋风」起——秋风无形而可「见」，一个见字写出游子敏感；后三句全在一个「又开封」的细节上发力：信已写好、行人将发，又匆匆拆开补写，生怕遗漏半分，把抽象的「意万重」化为可触可见的动作，于细微处见深情。（「忽恐」通行本多作「复恐」，本文从库内原文。）",
    b: "张籍客居洛阳，见秋风起而作家书，本诗捕捉寄信前「又开封」的细节，成为写乡思的千古名篇。",
    n: ["秋思：秋日思乡之情","归书：家信。意万重，要说的话千头万绪。重音chóng","行人：捎信的人","临发：将要出发","开封：打开已封好的信"]
  },
  "相和歌辞·春江花月夜|张若虚": {
    s: "全诗以月为轴心，按「月升—月悬—月斜—月落」组织：先写春江花月的澄澈宇宙，继而生发出「何人初见月、何年初照人」的千古天问，在永恒江月与代代人生的对照中获得豁达；后半转入人间离愁，扁舟游子、明月楼思妇两两相望，最后以落月摇情收束。景、情、理水乳交融，音韵婉转，洗净六朝宫体铅华。",
    b: "张若虚传世仅存诗两首，此为其一，沿乐府旧题写春江月夜之景与游子思妇之情，被闻一多誉为「诗中的诗，顶峰上的顶峰」。",
    n: ["滟滟：水波闪光貌。音yàn","宛转遶芳甸：江流曲折绕过花草遍生的郊野。遶同「绕」；甸，郊野","霰：细密雪珠，此喻月光下花林洁白。音xiàn","空里流霜：空中月色如飞霜而不觉其飞","汀：沙滩","纤尘：微尘","穷已：穷尽","但见：只见","青枫浦：地名，亦泛指游子所在。浦，水边","扁舟子：乘小舟漂泊的游子。扁音piān","明月楼：思妇的妆楼","裴回：同「徘徊」，月光流连不去","玉户：华美的门户，指闺中","𢭏衣砧：捶捣衣裳的砧石。𢭏同「捣」；砧音zhēn","逐月华：追随月光","鸿雁长飞光不度：鸿雁善飞也飞不出月光（度不去此情）","水成文：水面荡起波纹。文同「纹」","闲潭：幽静的水潭","碣石潇湘：北有碣石、南有潇湘，泛指天南海北","乘月：趁着月色","落月摇情满江树：落月的余晖摇动情思、洒满江边树林"]
  },
  "早梅|张谓": {
    s: "首句以「白玉条」喻寒梅满枝之洁白；次句点出早梅独临溪桥的环境；后两句是点睛之笔：远望不知是近水之梅先发，还疑心是去冬残雪未消，以「疑雪」写梅之早、之白，又暗合「近水楼台先得月」的物候之理，构思灵巧。",
    b: "张谓这首早梅诗写水边寒梅先发、远望疑雪的惊喜，是咏梅名篇。",
    n: ["白玉条：梅花枝条洁白如玉条","迥临：远远地靠近。迥，远","傍谿桥：依傍溪桥。谿同「溪」","近水花先发：临近溪水的梅花因水暖而先开","经春雪未销：过了一冬（一作经冬）的雪还没融化"]
  },
  "除夜宿石头驿|戴叔伦": {
    s: "首联以旅馆无人相问、唯寒灯可亲写尽孤况；颔联是千古名联——「一年将尽夜」对「万里未归人」，时间之末与空间之远十字相激，除夕本当团圆而己独为客，凄怆逼人；后两联追怀前事、自笑支离，愁颜衰鬓又逢新春，以「又」字写出年年漂泊的无奈。",
    b: "戴叔伦除夕之夜羁旅石头驿，寒灯独对、一年将尽而万里未归，写尽岁暮旅愁。",
    n: ["除夜：除夕","石头驿：在今江西南昌的驿站。驿，驿馆","相问：相慰问","支离：流离多病","衰鬓：衰老的鬓发"]
  },
  "兰溪棹歌|戴叔伦": {
    s: "前两句写静景：眉月挂湾、越山如镜，清凉澄澈；后两句化静为动——连下三日桃花春雨、溪水新涨，半夜鲤鱼泼剌跃上浅滩，生机盎然。以民歌笔调、明快画面写出江南春夜的灵动，凉月之静与鲤鱼之动相映成趣。",
    b: "戴叔伦这首仿民歌的棹歌写兰溪春夜月下的清新山水与渔家生机，是中唐山水小诗精品。",
    n: ["兰溪：在今浙江兰溪，富春江上游","棹歌：船歌、渔歌。棹，船桨，音zhào","凉月如眉：新月如眉","柳湾：栽柳的水湾","越中：今浙江一带，古越地","镜中看：山色如在镜中","桃花雨：桃花开放时节的春雨","上滩：鲤鱼趁春水新涨跃上浅滩"]
  },
  "苏溪亭|戴叔伦": {
    s: "首句亭上草漫，已见暮春寥落；「谁倚东风十二阑」以倚阑之人暗逗相思；后两句情景交融——燕子不归暗喻所期之人不至，春事已晚；一汀烟雨、杏花生寒，把暮春的清冷与内心的怅惘打成一片，迷蒙含蓄。",
    b: "戴叔伦暮春登苏溪亭，借迷蒙烟雨、迟暮杏花写怀人未遇、春光将逝的怅惘。",
    n: ["苏溪亭：在今浙江义乌","草漫漫：春草繁茂无边","十二阑：曲折的栏杆，十二言其多","春事晚：春光将暮","一汀烟雨：整片沙洲笼罩在如烟细雨中。汀，水洲","杏花寒：雨中杏花透出寒意"]
  },
  "霜月|李商隐": {
    s: "前两句写实：征雁初闻、寒蝉已绝，百尺高楼上水光接天，交代时令与眺望角度；后两句由实景生发奇想——霜是青女所洒、月为素娥所居，两位冰雪女神都耐得住寒冷，正在月中霜里争妍斗美。把霜月之寒、之美写得有性格、有精神，想象瑰奇。",
    b: "李商隐这首《霜月》写深秋登楼所见霜月交辉之景，以神话想象写出霜月的高洁之美。",
    n: ["征雁：南飞的大雁","已无蝉：秋深蝉声已绝","水接天：月光水光相接，言楼之高","青女：主管霜雪的女神","素娥：嫦娥，月宫仙女","耐冷：经得起寒冷","鬬婵娟：比斗美好。鬬同「斗」；婵娟，美好貌，此指霜月争辉"]
  },
  "蝉|李商隐": {
    s: "咏蝉即自咏：蝉栖高饮露而难饱、费声传恨而徒劳，正是诗人才高而清贫、陈情而无应的写照；「一树碧无情」尤妙——树自青翠，对蝉之悲鸣无动于衷，正是世态凉薄的象征；后半由蝉及己，薄宦漂泊、故园荒芜，末以「举家清」人蝉双收，物我合一。",
    b: "李商隐一生羁旅幕府、职位卑微，此诗借咏蝉自伤身世，是咏物诗「不即不离」的典范。",
    n: ["高难饱：蝉栖高树、饮清露，故难以饱腹","徒劳恨费声：悲鸣传恨也是白费力气","疏欲断：蝉声稀疏、几近断绝","一树碧无情：树自碧绿、全然不解蝉之悲","薄宦：卑微的官职","梗犹泛：如桃梗木偶般漂泊无定（用《战国策》土偶桃梗典）","芜已平：荒草已长得没路","相警：相提醒","举家清：全家清贫，亦以蝉之清高自况"]
  },
  "忆梅|李商隐": {
    s: "首句「定定住天涯」叠词突兀，写尽身不由己的滞留；次句「依依向物华」写对春光的留恋；后两句翻出新意——寒梅最「堪恨」，因它开在岁末，等春回大地、百花争发时它早已开过，成了「去年花」。言梅实自怜：自己如寒梅早秀而不逢其时，含蓄自伤。",
    b: "李商隐羁旅异乡、春日忆梅而作，以早梅「常作去年花」的特点自比先春而发、生不逢时。",
    n: ["定定：牢牢地、动不了，写滞留之苦","天涯：此指诗人滞留的异乡","依依：深切留恋","物华：美好春光","去年花：寒梅多在腊前冬末开放，到春日已是「去年之花」"]
  },
  "风雨|李商隐": {
    s: "首联以《宝剑篇》起，慨叹壮志销磨于羁泊穷年；颔联名联以「黄叶风雨」与「青楼管弦」作强烈对比——自己如风雨中飘零的黄叶，豪贵之家却自顾笙歌，一冷一热、一悲一乐，世情如见；后写新遭薄俗、旧好隔绝，唯有以酒销愁，沉郁顿挫。",
    b: "李商隐中年羁泊异乡、交游零落，面对风雨凄其、他人宴乐，借《宝剑篇》与马周典故抒发怀才不遇之愤。",
    n: ["宝剑篇：唐初郭震所上名篇，喻壮志未酬","羁泊：羁旅漂泊","欲穷年：将这样潦倒一辈子","仍：更、兼","青楼：富贵人家的华楼（非后世妓院义）","管弦：音乐宴乐","薄俗：浅薄的世俗","旧好：旧交","心断新丰酒：想用新丰美酒浇愁也不可得（用马周困居新丰典）。新丰，在长安附近","斗几千：一斗酒值几千钱，言酒美价高"]
  },
  "寄令狐郎中|李商隐": {
    s: "前两句写两地睽违、忽接来书：嵩云秦树各在一方，「双鲤迢迢一纸书」见珍重；后两句以两个典故自况——自己正如梁园旧客、茂陵病中的司马相如，秋雨闭门、潦倒多病。「休问」二字含无限身世之感，用典贴切、语淡情深。",
    b: "李商隐在洛阳患病，收到长安旧友令狐绹来信问讯，作此诗答谢，感念旧谊并自陈病况。",
    n: ["令狐郎中：令狐绹，时任考功郎中，诗人旧友","嵩云秦树：嵩山云（诗人在洛阳）、秦中树（友在长安），喻两地相望","双鲤：指书信（古乐府「客从远方来，遗我双鲤鱼」）","迢迢：遥远","梁园旧宾客：司马相如、枚乘等曾为梁孝王宾客，此自比曾在令狐家为客","茂陵秋雨病相如：司马相如晚年病居茂陵，此以病相如自况"]
  },
  "落花|李商隐": {
    s: "首联客去、花飞并起，人散花谢同其寥落；颔联写落花参差连路、随夕阳远飘，凄迷辽阔；颈联「肠断未忍扫，眼穿仍欲归」，惜花人不忍扫花、盼春留而春仍去，痴情如见；尾联双关收束——花之芳心随春而尽，所得只是落瓣沾衣；人之芳心随望成空，所得只是清泪沾衣，人花同慨。",
    b: "李商隐这首咏落花诗，借花伤己，在客去花飞的暮春景象中寄寓身世飘零之感。",
    n: ["客竟去：客人终于离去","参差：错落、纷繁，此指落花纷飞。音cēncī","曲陌：曲折的小路","迢遰：遥远，此指落花被余晖送向远方。同「迢递」","斜晖：夕阳","眼穿：望眼欲穿，盼春留","芳心：双关花之心与诗人惜春之心","沾衣：泪落沾衣，亦双关花瓣落衣"]
  },
  "为有|李商隐": {
    s: "诗以「云屏无限娇」极写闺中人之娇贵，以「寒尽怕春宵」反挑——春宵本千金，何以言怕？后两句作答：只怨嫁了个佩金龟的高官夫婿，每每辜负香衾、赶去早朝。以华贵写幽怨，以「无端」的娇嗔写尽少年夫妻的离别滋味，构思新颖。",
    b: "李商隐这首闺怨（一作宫怨）诗写一位嫁与高官的少妇，在丈夫勤于早朝、独守春宵时的娇怨，含蓄微讽。",
    n: ["为有：取首二字为题（李商隐无题诗惯例）","云屏：云母屏风，言闺房华贵","无限娇：无比娇媚","凤城：京城","春宵：春夜","无端：没来由地、不料","金龟婿：佩金龟的高官夫婿（武则天时改佩鱼为佩龟）","辜负香衾：辜负了温暖的衾被。衾，被子","事早朝：为了赶早朝"]
  },
  "马嵬二首·一|李商隐": {
    s: "前两句写叛军动地而来、红粉顷刻成灰，两个「自」字冷峻——祸到临头，所谓恩宠连爱妃也保不住；后两句以反问作诛心之论：若说真是美色倾覆国家，那玄宗车驾又何至于仓皇逃经马嵬？把亡国之责从「女祸」拉回君王自身，笔锋犀利。",
    b: "李商隐《马嵬》二首之一，针对唐玄宗与杨贵妃马嵬兵变事作翻案反思，批判君王误国。",
    n: ["马嵬：马嵬坡，安史之乱中杨贵妃赐死处。嵬音wéi","冀马燕犀：河北叛军的精锐兵马（冀、燕皆安禄山据地），犀指犀甲","动地来：铺天盖地杀来","自埋红粉自成灰：玄宗亲手赐死贵妃、杨亦化为尘土","倾国：双关绝色美人和倾覆国家","玉辇：皇帝车驾。辇音niǎn"]
  },
  "瑶池|李商隐": {
    s: "前两句写西王母绮窗长开、等待穆王，而《黄竹》哀歌动地，生死之悲已伏；后两句反问冷峻：八骏神速如此，穆王为何终究不能重来赴约？——连最受神仙眷顾、有神骏可乘的穆王都难免一死，求仙长生之妄不言自明，以神话外壳包裹现实讽刺。",
    b: "李商隐借周穆王会见西王母的神话，讽刺唐代帝王迷信神仙、妄求长生终究虚妄。",
    n: ["瑶池：神话中西王母居所","阿母：西王母又称玄都阿母","绮窗：雕饰华美的窗户","黄竹歌：周穆王曾作《黄竹歌》哀冻死者，「动地哀」言其声哀","八骏：周穆王的八匹神马，日行万里","穆王何事不重来：穆王曾与西王母约三年后复会，终因身死不能重来"]
  },
  "板桥晓别|李商隐": {
    s: "前两句写回望高城、晓河渐落、长亭窗影压着微波，凄清的晓色中含无限留恋；后两句全用比兴——行人如乘鲤水仙飘然欲去，送者如芙蓉泣露、一夜红泪，「红泪」兼花露与人泪，亦人亦花，绮艳中见深情，典型的李商隐式朦胧美。",
    b: "李商隐这首小诗写清晨板桥送别，以神话和鲜花喻离别，绮丽而哀婉。",
    n: ["板桥：浮桥、木板桥","高城：指所别者所居之城","落晓河：天渐晓、银河西沉","长亭：送别处","水仙欲上鲤鱼去：用琴高乘鲤成仙典，喻行人将乘舟远去","芙蓉红泪：以荷花带露喻别泪（兼用薛灵芸泣别、泪红如血典）"]
  },
  "夕阳楼|李商隐": {
    s: "首句「花明柳暗」本是美景，却接「绕天愁」，以乐景写哀、愁弥天地；次句「上尽重城更上楼」写层层登高、层层求索；后两句最妙：本想问孤鸿飞向何处，却蓦然惊觉自己的身世也如孤鸿、悠悠无依——问鸿正是自问，人鸿合一，孤愤旷远。",
    b: "此诗为李商隐登夕阳楼感怀而作，时恩人萧澣遭贬，诗人亦自伤身世，故望孤鸿而兴叹。",
    n: ["夕阳楼：在荥阳（今郑州），李商隐受知于刺史萧澣时所登，后萧被贬","绕天愁：愁绪弥漫如绕天际","重城：层叠的城","孤鸿：孤雁，自喻身世飘零","悠悠：邈远、无可依托"]
  },
  "晚晴|李商隐": {
    s: "首联点明深居俯城、夏初清和；颔联是千古名句——天意仿佛怜惜幽僻小草而放晴，人间也格外珍视这傍晚的晴光，「晚晴」既写实景，又喻人生晚年或困顿中短暂的美好，哲理深邃；后写高阁因晴而显高远、小窗因余晖而明亮，越鸟巢干、归飞体轻，明快中见自奋之意。",
    b: "李商隐任职桂林幕府时，逢久雨晚晴而作，在幽草晚晴、越鸟归飞中寄寓身世之感与短暂慰藉。",
    n: ["夹城：宫城间的复道","春去夏犹清：春已去而夏日清和","幽草：背阴处的小草，自喻卑微","重晚晴：珍视傍晚初晴的天色（亦喻晚年短暂清明）","并添：更添","迥：高远","微注：夕阳微微流注、照入","越鸟：南方的鸟（诗人时在桂林，古越地）","巢干后：雨停巢干","体更轻：归飞之鸟身姿轻快"]
  },
  "天涯|李商隐": {
    s: "前两句「春日在天涯，天涯日又斜」以顶真蝉联，春光虽好却身在天涯，天涯之上又是日暮，两层美好（春）与两层难堪（天涯、日斜）叠加，愁绪逼人；后两句奇想：黄莺啼鸣若也有泪，请为我打湿枝头最高的那朵花——最高花最先承受风雨，正是诗人自况，凄艳绝伦。",
    b: "李商隐春日漂泊天涯，见莺啼花落而作，以春日斜阳、莺啼最高花写迟暮飘零之悲。",
    n: ["天涯：天边，此指异乡","日又斜：夕阳又西沉","如有泪：好像带着眼泪","最高花：枝头最高处的花"]
  },
  "贾生|李商隐": {
    s: "诗先扬后抑：前两句极写汉文帝「求贤」——宣室召见、逐臣才调无伦，似是千古君臣遇合盛事；后两句陡然一转：如此倾心听问，问的却不是天下苍生而是鬼神之事，「虚前席」的「虚」字一针见血——知遇之态越殷，不任贤才之实越显，托古讽今，警策深刻。",
    b: "李商隐借汉文帝在宣室夜召贾谊、不问治国只问鬼神的史事，托古讽今，慨叹贤才不被重用、帝王不恤民瘼。",
    n: ["贾生：贾谊，西汉青年政论家，曾被贬长沙","宣室：汉未央宫前殿正室","访逐臣：召见被贬之臣（贾谊）","才调：才气、才情","无伦：无人能比","可怜：可惜","虚前席：汉文帝听得入神，移坐向前（古人席地而坐），「虚」言徒然如此","苍生：百姓","鬼神：鬼神之事（贾谊被问的本是鬼神之本）"]
  },
  "凉思|李商隐": {
    s: "首联客去波平、蝉休露满，秋夜清寂；颔联「永怀」「倚立移时」以伫立之久写思念之深；颈联由近及远——北望长安，春天已远、人更远；滞留南陵，归使迟迟，时空双重寥落；尾联写屡次占梦、甚至疑故人有了新知，把久滞无音者的敏感多疑写得细腻真切。",
    b: "李商隐奉使滞留南方，秋夜怀人（或怀京洛友人），写客中孤寂与对友情的忐忑。",
    n: ["凉思：秋凉中的思绪","波平槛：槛外水波平息。槛，栏杆","蝉休：秋蝉停鸣","永怀：深长的思绪","移时：过了好一阵","北斗兼春远：北斗所指的北方（长安）连同逝去的春天一样遥远","南陵寓使迟：出使滞留南陵、归期迟迟","占梦数：屡次据梦境占卜归期。数音shuò，屡次","疑误有新知：疑心对方是否有了新交而忘了旧友"]
  },
  "北青萝|李商隐": {
    s: "诗按访僧行程写来：残阳入崦、茅屋访僧，落叶满山、人踪何在，寒云叠叠、山路几层；「独敲初夜磬，闲倚一枝藤」以磬声和藤杖勾勒孤僧的闲适；尾联由访僧而悟禅——大千世界不过微尘，一身之爱憎又何足挂怀，在凄清旅思中透出禅悦的旷达。",
    b: "李商隐秋日傍晚入山寻访孤僧，在清幽禅境中获得「爱憎两忘」的顿悟。",
    n: ["北青萝：地名，在王屋山中，僧人居处","崦：崦嵫山，传说日落处，此指夕阳西下。音yān","初夜磬：入夜时分的磬声","一枝藤：一根藤杖","世界微尘里：佛家言大千世界俱在微尘之中","吾宁爱与憎：我何必再执着于爱憎呢。宁，岂、何"]
  },
  "鼓吹曲辞·将进酒|李白": {
    s: "全诗以两组「君不见」领起：黄河奔海喻时光一去不返、朝暮成雪喻人生短促，悲感至极而以豪语出之；「天生我材必有用」是全诗脊梁，于失意中透出极强自信；钟鼓馔玉不足贵、圣贤寂寞饮者名，是愤激的反语；末以马裘换酒、同销万古愁收束，大起大落，纵横开合，为李白浪漫诗风的巅峰之作。",
    b: "约天宝十一载（752）李白与友人岑勋、元丹丘嵩山饮宴所作，时诗人被赐金放还已近十年，借酒抒怀，一吐长安失意的万古愁闷。",
    n: ["将进酒：汉乐府旧题，「将」音qiāng，请","天上来：言黄河发源高远、势如从天而落","高堂明镜悲白发：于高堂明镜前悲白发之生","得意：有兴致、得志之时","金尊：华美酒杯。尊同「樽」","会须：应当、正应该","岑夫子、丹丘生：岑勋、元丹丘，李白好友","钟鼓馔玉：鸣钟列鼎而食、饮食精如玉，指富贵生活。馔音zhuàn","陈王：陈思王曹植","平乐：平乐观，曹植《名都篇》「归来宴平乐，美酒斗十千」","恣欢谑：纵情欢乐戏谑。谑音xuè","径须：只管、干脆","酤取：买酒","五花马：名贵的马（鬃毛剪成五瓣花形）","千金裘：价值千金的皮衣","将出：拿出去。将，拿","尔：你"]
  },
  "塞下曲六首·一|李白": {
    s: "前四句写边地苦寒：五月天山尚雪、无花唯寒，笛中虽闻《折杨柳》而春色终不可见，以「闻折柳」与「未曾看」对写，愈显荒寒；后四句陡然振起——晓战随鼓、宵眠抱鞍，征战之苦只作铺垫，逼出「愿将腰下剑，直为斩楼兰」的誓言，用傅介子典，豪迈刚烈。",
    b: "李白《塞下曲》六首之一，写边塞五月犹寒、将士昼夜苦战、誓斩敌王的报国豪情。",
    n: ["天山：今新疆天山","祗有：只有。祗同「只」","折柳：笛曲《折杨柳》，本是春曲，边地闻之而春色未见","金鼓：以金钲、鼓指挥进退","宵：夜","玉鞍：精美的马鞍","直为：就要、径直去。为，语气词","斩楼兰：用西汉傅介子计斩楼兰王典故，喻平定边患"]
  },
  "秋浦歌十七首·三|李白": {
    s: "前两句直写锦驼鸟羽毛似锦、珍异罕有；后两句用衬托之法——素以自爱羽毛、临水照影著称的山鸡，见了锦驼鸟竟自惭形秽、不敢照水，以山鸡之「羞」反衬驼鸟之美，不正面写其羽而其美自见，诙谐灵动。",
    b: "李白漫游秋浦时所作组诗之三，专咏当地罕见的锦驼鸟，是一首别致的咏物小诗。",
    n: ["秋浦：今安徽池州贵池，李白漫游此地作《秋浦歌》十七首","锦驼鸟：羽毛如锦的鸵鸟（一说秋浦所产锦鸡类珍禽）","人间天上稀：人间罕有、天上也稀","山鸡：锦鸡，自爱其羽，常照水而舞","羞渌水：面对碧水自惭不如（衬托驼鸟之美）。渌，清澈","毛衣：羽毛"]
  },
  "沙丘城下寄杜甫|李白": {
    s: "前两句自问来此何事、高卧沙丘，已见百无聊赖；三四句城边古树、日夕秋声，以萧瑟秋景衬离思；颈联「鲁酒不可醉，齐歌空复情」——酒也醉不了、歌也不解愁，正因思念太深；尾联以汶水为喻，思君之情如汶水浩荡、随君南流，即景取喻，情深无际。",
    b: "李白与杜甫分别后寓居沙丘，思念友人而作此诗寄怀，李杜交谊的千古见证。",
    n: ["沙丘：在今山东兖州一带，李白曾寓居","竟何事：究竟为了什么","高卧：闲居","日夕：朝夕","鲁酒、齐歌：鲁地的酒、齐地的歌（齐鲁皆今山东）","空复情：徒然有情（酒不能醉、歌不解愁）","汶水：山东大汶河。汶音wèn","浩荡：水势浩大，喻思情绵长","南征：向南远行，指杜甫将南游"]
  },
  "金乡送韦八之西京|李白": {
    s: "首联「客自长安来，还归长安去」平平而起，似口语却见友人往返、自己留滞；颔联突发奇想——一颗心竟被狂风吹起、高挂在长安的树上，把抽象的依恋写得可见可触，是李白式的天真与夸张；后写此情难述、后会难期，末以望而不见、连山烟雾收束，怅惘不尽。",
    b: "李白在金乡送别归长安的友人韦八，以奇特想象写心随友人西去的惜别深情。",
    n: ["韦八：一位韦姓友人，排行第八","之西京：往长安去","狂风吹我心，西挂咸阳树：心随友人西去、仿佛被风吹挂在长安树上（咸阳代长安）","不可道：说不尽","望望：一再瞻望","连山：连绵的山","烟雾：云雾"]
  },
  "鲁郡东石门送杜二甫|李白": {
    s: "首联忆别前数日醉复登临、遍游池台的快意；颔联「何时石门路，重有金樽开」预想后会，珍重中含期待；颈联写别时秋景——泗水秋波、徂徕海色，明丽开阔；尾联以飞蓬喻各自天涯，且尽杯中酒，不作儿女沾巾之态，旷达中藏深情，正见李白性情。",
    b: "天宝四载（745）李白与杜甫在鲁郡东石门最后一次分别，此诗写二人同游之乐与别后相念。",
    n: ["杜二甫：杜甫，排行第二","石门：鲁郡东石门山","登临遍池台：一同游遍了山水台榭","金樽开：举杯重聚","泗水：在今山东","徂徕：山名，在今山东泰安。音cúlái","飞蓬：飘飞的蓬草，喻各自漂泊","且尽手中杯：姑且饮尽杯中酒"]
  },
  "秋登宣城谢朓北楼|李白": {
    s: "首联「江城如画」总领、山晓晴空写环境；颔联是名句——两水如明镜相夹、双桥似彩虹飞落，对仗工巧、色彩明丽；颈联「寒」「老」二字最见炼字之功：橘柚间升起人烟而带寒意、梧桐染秋色而显苍老，把秋意写得可触可感；尾联临风怀谢公，古今诗人遥相呼应。",
    b: "李白秋日登宣城谢朓北楼，写景怀人，表达对南齐诗人谢朓的追慕。",
    n: ["宣城：今安徽宣城","谢朓北楼：南齐诗人谢朓任宣城太守时所建，又名谢公楼。朓音tiǎo","江城：宣城，有水阳江绕城","两水：句溪、宛溪","夹明镜：两水如两面明镜相夹","双桥：凤凰桥、济川桥","落彩虹：桥如天上落下的彩虹","橘柚：南方果木","老梧桐：梧桐秋色深而显老","谢公：谢朓"]
  },
  "苏台览古|李白": {
    s: "诗以「旧苑荒台」与「杨柳新」对举，台荒而柳新，人事已非而自然依旧；菱歌清唱、春意无穷，越写春之永恒，越显宫苑之易朽；后两句点题——如今唯有西江明月，曾照见过当年吴宫美人，以月为历史见证，把吊古之思推向苍茫，含蓄不尽。",
    b: "李白游苏州姑苏台遗址，见杨柳新绿、菱歌依旧而吴宫成尘，抒发昔盛今衰之感。",
    n: ["苏台：姑苏台，吴王夫差为西施所建，在苏州","旧苑荒台：昔日宫苑、如今荒台","菱歌：采菱歌","不胜春：春意无穷。胜音shēng，尽","只今：如今","西江月：西边江上之月","吴王宫里人：西施等吴宫中人"]
  },
  "越中览古|李白": {
    s: "此诗章法独特：前三句一气铺张盛——勾践破吴、义士锦衣、宫女如花满殿，把胜利的繁华写到极处；末句陡然一落，「只今惟有鹧鸪飞」，盛与衰、热与冷在一句之内翻转，以盛衬衰，其衰倍哀，篇幅短小而冲击力极强。",
    b: "李白游览越中（今绍兴）越王勾践故宫遗址，以昔日灭吴盛况反衬今日荒凉，是七绝怀古的典范。",
    n: ["越王句践：春秋越王勾践，卧薪尝胆灭吴。句同「勾」","义士还乡尽锦衣：灭吴将士凯旋、皆着锦衣（衣锦还乡）","春殿：宫殿春光","只今惟有鹧鸪飞：如今只剩鹧鸪飞于故址"]
  },
  "访戴天山道士不遇|李白": {
    s: "全诗沿访道行踪展开：犬吠水声、桃花带露写进山之初的幽美；树深见鹿、正午不闻钟，以「见鹿」之幽、「不闻钟」之静暗写无人；野竹分云、飞泉挂峰写山间清奇；尾联「无人知所去，愁倚两三松」点出不遇，余韵悠然，景中有人。",
    b: "李白早年在戴天山寻访道士不遇而作，以一路清幽山景写访隐的兴致与不遇的惆怅，是其现存较早的律诗。",
    n: ["戴天山：又名大匡山，在今四川江油，李白少年读书处","不遇：没有遇到","带雨浓：带着浓露（一作露浓）","溪午不闻钟：走到溪边已正午，却听不到寺钟（暗示道士不在）","青霭：青色云气。霭，云气","飞泉：瀑布","愁倚：惆怅地倚着"]
  },
  "越女词五首·一|李白": {
    s: "小诗以白描勾勒吴地女儿：先以「眉目艳新月」写面容之姣好，再特写木屐之上双足白如霜、不穿鸦头袜，抓住吴越女子赤足着屐的地方风习，写得天然清新、健康明朗，全无脂粉气，深得南朝民歌神韵。",
    b: "李白漫游吴越时作《越女词》五首，此首写吴地少女天足自然之美，富民歌风情。",
    n: ["越女词：写吴越女子的组诗，此为其一","长干：金陵里巷名（长干里），此泛指吴地","儿女：女儿、女子","眉目艳新月：眉目比新月还要明艳","屐：木屐，木底鞋","足如霜：脚肤白如霜","鸦头袜：分叉如鸦头形的袜子（着屐时穿）"]
  },
  "喜见外弟又言别|李益": {
    s: "首联「十年离乱后，长大一相逢」交代时代背景；颔联是写重逢的千古名句——分别时都是孩童，重逢竟先问姓氏、待报上名字才忆起旧容，把久别乍逢的惊疑、追忆写得极其真切；颈联叙谈间沧海桑田、不觉暮钟，见话之长；尾联预想明日巴陵道上秋山万重，刚逢又别，悲喜交集。",
    b: "李益这首五律写安史乱后与表弟久别重逢、翌日又别的情景，是写乱世离合的名篇。",
    n: ["外弟：表弟","言别：话别、道别","一相逢：才相逢、忽然相逢","问姓：先问姓氏（因分别太久已不相识）","称名：报出名字","忆旧容：才忆起儿时面容","沧海事：如沧海桑田般的世事巨变","巴陵道：通往巴陵（今岳阳）的路"]
  },
  "夜上受降城闻笛|李益": {
    s: "首联入夜思归、笛声哀切，奠定愁绪；颔联最妙——本是愁人怕听哀笛，笛声却偏「自到枕前来」，躲无可躲，把征人欲避乡愁而不得的无奈写活；颈联风起云断、夜深月出，清冷之景衬孤愁；尾联平明独惆怅、一庭梅落，以景结情，一夜无眠自见。",
    b: "李益久在边塞，此诗写征人夜闻笛声、思乡难眠，是其边塞诗的代表作之一（与名篇「回乐烽前沙似雪」同题而异辞）。",
    n: ["受降城：唐代为防御突厥所筑东、西、中三受降城，此为边塞泛称","思归切：思归之情急切","清更哀：清越而哀伤","自到枕前来：笛声自己飘到枕边","塞云断：边云被风刮散","关月开：关塞上空云散月出","平明：天亮","落尽一庭梅：（一作）庭中梅花落尽，烘托一夜无眠"]
  },
  "度破讷沙二首·一|李益": {
    s: "前两句写大漠实景：风卷沙移、经年不见寸草，极写环境之荒；后两句翻进一层作议论——不要说塞北没有春天，纵然春天真的来了，在这寸草不生的沙海里又从何处感知？以反问写尽边地无春的苦寒，也暗喻征人青春虚掷，含蓄深沉。",
    b: "李益《度破讷沙》二首之一，写塞北大漠终年风沙、无春可见的荒寒，寄征人感慨。",
    n: ["破讷沙：沙漠名，又作普纳沙，在今内蒙古","沙旋移：沙尘被风卷着旋转移动","经年不省：整年看不见。省，记得、看见，音xǐng","莫言：不要说","总有春来何处知：就算春天来了，又从哪里能知道呢"]
  },
  "汴河曲|李益": {
    s: "前两句构成强烈对比：汴水东流、年年春色无限，隋家宫阙却已化为尘土，自然永恒与王朝短促对举；后两句以劝人莫上长堤作转——只因风起杨花漫天，最易牵动兴亡之愁。汴河柳、隋宫尘本是一体之两面，吊古伤今，绵邈苍凉。",
    b: "李益沿汴河而行，见春光依旧、隋宫成尘，借杨花抒写对隋炀帝荒淫亡国的历史感慨。",
    n: ["汴河：通济渠，隋炀帝开凿的大运河一段，两岸植柳","隋家宫阙：隋朝宫殿","已成尘：早已化为尘土","长堤：汴河堤","杨花：柳絮","愁杀人：愁煞人"]
  },
  "边思|李益": {
    s: "前两句写武将装束与戍边经历：锦带吴钩、走马防秋，英气勃勃；后两句一转——莫笑我这关西将门之后，没能立功封侯，只把满腹诗情带到了凉州。于自嘲中见自负：边塞风霜皆入诗篇，正是李益边塞诗独步中唐的自况，苍凉而不失风骨。",
    b: "李益曾五次从军、久历边塞，此诗自写从戎经历——本是将门之子，最终却以诗名传于边地，自豪中含自嘲。",
    n: ["吴钩：吴地所产弯形宝刀，泛指利剑","走马：驰马","防玉塞秋：秋天戍守玉门关边塞（秋高马肥，胡人常入寇，故秋防）","关西将家子：函谷关以西多出将才，诗人自谓将门之后","秪将：只把。秪同「只」","诗思入凉州：作诗的情思都融入了凉州边地。凉州，今武威一带"]
  },
  "从军北征|李益": {
    s: "前两句写环境与笛声：天山雪后、海风刺骨，偏偏横笛吹起凄苦的《行路难》，以景衬声、以声引情；后两句是宏大特写——三十万征人竟在同一刻回头凝望明月，「一时」二字写尽乡心的普遍与齐一，不言愁而处处是愁，场面壮阔而悲怆。",
    b: "李益这首七绝写雪后风寒的大漠上，一支三十万征人的队伍因一支《行路难》笛曲而齐望明月的动人场面。",
    n: ["从军北征：随军北征途中","天山：此泛指边塞之山","海风：从内陆大湖（如蒲类海）吹来的风","行路难：乐府旧曲，声情凄苦","碛里：沙漠中。碛音qì","三十万：极言征人众多","回向月明看：都回头望向明月（望乡）"]
  },
  "隋宫燕|李益": {
    s: "诗以燕子的口吻感受兴亡：燕语呢喃，仿佛在感伤旧国之春；宫花一落、霸业成尘；自从行宫封闭、风光不再，燕子几度归来，再不见当年宫人。以燕子的「几度飞来」见证时间流逝，以「不见人」写尽荒凉，角度新巧、感慨深沉。",
    b: "李益以年年归来的春燕为视角，写隋宫封闭后的荒凉，借燕语寄托兴亡之感。",
    n: ["隋宫：隋炀帝行宫","旧国春：故都（隋朝）的春色","宫花一落：宫花凋落，喻隋亡","一闭风光：行宫一旦封闭、繁华散尽","几度：多少次"]
  },
  "江南曲|李益": {
    s: "前两句写雨收花明、江城日暮、游人相邀，透出江南生活的悠然；后两句用工致对句写风物——春楼虚掩、连锁不闭，见民风之安闲；绿水回环、桥随水转，见地势之玲珑。色彩明丽、音韵流转，如一幅江南水乡小品。",
    b: "李益这首小诗写江南江城日暮、雨收花明、春楼不锁、绿水桥回的明丽风光与闲适人情。",
    n: ["江南曲：写江南风物的诗","长乐：长乐坡（或长乐里），在长安/江南地名","雨点销：雨点渐稀渐止。销同「消」","相邀：相互邀约游赏","葳蕤锁：雕饰繁复、可屈折的连锁。葳蕤音wēiruí","回连：回环相连","宛转桥：曲折回转的桥"]
  },
  "拜新月|李端": {
    s: "前两句以连贯动作写少女的天真：开帘忽见新月，便立刻下阶而拜，「便即」二字见其情急可爱；后两句写她对着月儿轻声许愿，旁人听不真切，只有北风吹动裙带——以「人不闻」制造私密感，以风吹裙带的细节勾勒月下亭亭身影，含蓄灵动，余味悠然。",
    b: "李端这首小诗写一位少女开帘见月、匆匆下拜、临风细语的娇憨情态，清新如画。",
    n: ["拜新月：古代妇女有七夕或月初拜新月、许愿的习俗","便即：随即","下阶拜：走下台阶对月下拜","细语：轻声诉说心愿","裙带：系裙的带子"]
  },
  "古风二首·一|李绅": {
    s: "前两句极写丰收：春种一粒、秋收万颗，以「一」与「万」的对比写劳动创造之丰；第三句再推一层，四海之内再无一块闲田，丰收已写到极处；末句陡然逆转——农夫「犹饿死」！丰收越被铺陈，饿死越显触目，不言原因而原因自见，冷峻深刻。",
    b: "李绅《悯农》二首之一，以春种秋收的丰收与农夫饿死的强烈对比，揭露社会不公，是千古传诵的悯农诗。",
    n: ["古风二首：即《悯农二首》，此为其一（另一首「锄禾日当午」）","粟：谷子，泛指粮食","秋成：秋天收获（一作秋收）","四海：普天之下","闲田：撂荒的田地","犹：还、仍然"]
  },
  "过华清宫绝句三首·一|杜牧": {
    s: "前两句写长安回望骊山、宫阙如绣、千门次第开启，庄严隆重，设下悬念；后两句揭谜——驿马绝尘、妃子一笑，没人知道这十万火急的军国般排场，竟只是为送几颗荔枝！「妃子笑」与「一骑红尘」并置，以小见大，讽刺入木三分而不着一字议论。",
    b: "杜牧途经华清宫所作三首之一，截取驿马送荔枝的典型场景，讽刺唐玄宗为博妃子一笑而疲民劳驿。",
    n: ["华清宫：唐玄宗与杨贵妃的骊山行宫","回望：从长安回望骊山","绣成堆：骊山花木建筑如团团锦绣","千门次第开：宫门一道接一道打开。次第，依次","一骑红尘：一匹驿马飞驰、扬起红尘。骑音jì","妃子：杨贵妃","荔枝：杨贵妃喜食鲜荔枝，驿马自岭南（或蜀）日夜驰送"]
  },
  "长安秋望|杜牧": {
    s: "前两句写天：楼高出霜树之外，天空明净如镜、纤云不染，已见高远；后两句更出新意——终南山是有形之高，秋色（秋空清气）是无形之高，二者气势互不相让、争相比高。把抽象的「秋色」写得有气势、可与高山争衡，构思奇特、笔力遒劲。",
    b: "杜牧这首五绝写秋日登楼、天高云净、终南耸翠的寥廓景象，表现高朗开阔的胸襟。",
    n: ["长安秋望：秋日远望长安（或终南山）","霜树外：高出经霜的树林（言楼之高）","镜天：天空明净如镜","无一毫：没有一丝云彩","南山：终南山","气势两相高：南山的高峻与秋色的高远争相比高"]
  },
  "将赴吴兴登乐游原一绝|杜牧": {
    s: "前两句写在「清时」只爱孤云、静爱高僧，看似闲适，「无能」实为牢骚反语；后两句写将持麾远去江南，临行登乐游原遥望太宗昭陵——望昭陵正是追慕贞观盛世、慨叹今世不遇明主，去国恋阙之情尽在一望中，含蓄沉郁。",
    b: "大中四年（850）杜牧将离长安赴湖州刺史任，登乐游原远望昭陵而作，于自嘲中寓盛世不再、壮志难酬之慨。",
    n: ["吴兴：今浙江湖州，杜牧将赴任湖州刺史","乐游原：长安东南登高胜地","清时：政治清明之时（反语，含不遇之慨）","有味是无能：闲静有味反因自己「无能」，自嘲","一麾：一面刺史旌麾，此指出任外官。麾音huī","江海去：到江南（湖州）去","昭陵：唐太宗陵墓，含追慕贞观盛世之意"]
  },
  "齐安郡后池绝句|杜牧": {
    s: "前两句写得极热闹：菱透浮萍、池如绿锦，夏莺在蔷薇间千啭，色彩与声音交织；后两句却以「尽日无人」一转，转入极静——唯有鸳鸯相对、于微雨中浴其红衣，以鸳鸯之成双、自得，反衬人之独处，动静相衬，「红衣」喻羽，鲜丽传神。",
    b: "杜牧任黄州刺史时作，写夏日后池细雨中菱萍、夏莺、鸳鸯构成的明丽幽静画面。",
    n: ["齐安郡：今湖北黄冈，杜牧曾任黄州刺史","菱透浮萍：菱叶从浮萍间透出","绿锦池：池塘美如绿色锦缎","千啭：鸣声婉转多变。啭，鸟鸣","蔷薇：花木名","微雨：细雨","浴红衣：鸳鸯戏水、梳理红色羽毛。红衣喻鸳鸯彩羽"]
  },
  "鹭鸶|杜牧": {
    s: "前两句写静：白鹭雪衣青喙、群立溪影中捕鱼，颜色相映；后两句写动——白鹭惊起、远衬碧山飞去，恰似一树洁白梨花在晚风中纷纷飘落。以梨花喻群鹭，色白形似，化动为静又化无生为有生，清新奇丽，是咏物佳句。",
    b: "杜牧这首咏物小诗写白鹭溪中捕鱼、惊飞远映碧山的姿态，比喻新巧、画面清雅。",
    n: ["鹭鸶：白鹭。鸶音sī","雪衣雪发：羽毛洁白如雪","青玉觜：青玉般的长喙。觜同「嘴」","群捕：成群捕食","溪影：溪水中的倒影","碧山：青山","一树梨花落晚风：喻白鹭惊飞如梨花被晚风扬起"]
  },
  "题乌江亭|杜牧": {
    s: "首句立论——兵家胜败本难预料；次句提出「包羞忍耻」方为男儿，暗批项羽经不起一败；后两句假设推论：江东子弟人才济济，若能重返江东、重整旗鼓，胜负尚未可知。咏史而不囿成说，以假设作结，议论警拔、气势豪宕，体现杜牧咏史绝句善作翻案的特色。",
    b: "杜牧过乌江亭，针对项羽「无颜见江东父老」而自刎的史事作翻案诗，认为大丈夫当忍辱负重、以待再起。",
    n: ["乌江亭：在今安徽和县，项羽兵败自刎处","事不期：胜败之事难以预料","包羞忍耻：能忍受羞耻挫折","江东：长江下游南岸，项羽起兵之地","才俊：才能出众的人","卷土重来：失败后重新恢复势力"]
  },
  "题木兰庙|杜牧": {
    s: "前两句写木兰的双重身份：弯弓征战、不输男儿是其表，梦里画眉、不忘女儿身是其里；后两句更妙——木兰几度思乡把酒，却在边地拂云堆上祭奠明妃王昭君：两位女子一征战、一和亲，皆为家国远走绝域，异代相怜，把木兰的情感世界写得深婉，构思巧妙。",
    b: "杜牧游木兰庙所作，既写木兰代父从军的英勇，又体贴其女儿本色与思乡之情，立意新颖。",
    n: ["木兰庙：祭祀花木兰的庙","作男儿：女扮男装","与画眉：（梦中）和女伴一起描眉（恢复女儿本色）","把酒：举酒","拂云堆：地名，在今内蒙古，有神祠","祝明妃：祭奠王昭君（明妃即王昭君，和亲匈奴，和木兰一样远涉边地）"]
  },
  "遣怀|杜牧": {
    s: "前两句以近乎格言的语言慨叹时命：道「泰」之时时运却不至，透出才命相妨的无奈；后两句表达志向——何时才能离开喧嚣城市，到博山深处高卧归隐。语言简淡，却可见诗人在党争倾轧的晚唐渴望全身远害的心境。",
    b: "此为杜牧《遣怀》的另一首（库内文本，与传诵的「落魄江湖载酒行」非同一篇），写时命未至、渴望离城归隐的情怀。",
    n: ["遣怀：排遣情怀","道泰：世道（或个人时运）安泰","时来：时机到来","何当：何时才能","博山隈：博山（今山东或泛指山林）的弯曲幽深处。隈，山曲处，音wēi","高卧：高枕闲居、归隐"]
  },
  "叹花|杜牧": {
    s: "全诗以花喻人、通篇比兴：自恨寻芳来迟，往年曾见花在「未开」之时（少女年幼），如今风摆花落、狼藉满地，绿叶成荫、子实满枝——花之已谢正喻人之已嫁、儿女成行。不着一情语而怅惘无尽，比喻贴切，成为「绿叶成荫」成语的出处。",
    b: "相传杜牧早年游湖州识一少女、约以十年内来娶，十四年后再至，女子已嫁三年、生二子，因作此诗叹惋。",
    n: ["叹花：叹惜花朵（一作怅诗，本事与杜牧早年邂逅湖州女子、十年后再来已嫁人生子有关）","寻芳：寻访春花（喻寻访意中人）","狼籍：纵横散乱貌，此指花已凋零。籍同「藉」","绿叶成阴子满枝：绿树成荫、果实满枝（喻女子已出嫁生子）"]
  },
  "秋夕|杜牧": {
    s: "首句「冷」字奠定基调：秋光、画屏皆带寒意，既是天凉也是心冷；次句以「扑流萤」写宫女百无聊赖——唯有流萤相伴，见深宫之冷落；后两句夜色凉如水、坐看牵牛织女，双星尚有一年一度之会，自己却长闭深宫、相逢无期，以乐景（双星相会）写哀，含蓄不尽。",
    b: "杜牧这首宫怨诗写七夕之夜宫女扑萤、坐看双星的孤寂，以清冷之景写失意之情。",
    n: ["秋夕：七夕之夜（一作七夕）","红烛：一作「银烛」","冷画屏：烛光使画屏生出寒意","轻罗小扇：轻薄丝绢制成的小团扇","流萤：飞动的萤火虫","天阶：宫中石阶","牵牛织女：牛郎、织女星，七夕鹊桥相会"]
  },
  "金谷园|杜牧": {
    s: "首句「繁华事散逐香尘」总括金谷园昔日繁华尽随香尘消散；次句「流水无情草自春」，以自然之无情反衬人之有情；后两句是名句——日暮东风中啼鸟如怨，飘落的花瓣多像当年坠楼的绿珠！以落花喻堕楼人，人花同命，凄艳绝伦，吊古与怜人融为一体。",
    b: "杜牧过洛阳金谷园遗址，凭吊石崇与绿珠故事，写繁华散尽、落花如人的深沉感伤。",
    n: ["金谷园：西晋富豪石崇的名园，在洛阳，绿珠坠楼于此","香尘：石崇曾以沉香屑铺象牙床、令姬妾踏之，此代指昔日繁华","草自春：春草自绿，不管兴亡","堕楼人：绿珠，石崇爱妾，孙秀强索不得、石崇获罪，绿珠坠楼殉情"]
  },
  "旅宿|杜牧": {
    s: "首联无良伴、自悄然，已见孤寂；颔联寒灯思旧事、断雁警愁眠，视听交织，以雁之孤衬人之孤；颈联是名句——梦归要到拂晓、家书隔年才到，极写乡关之远、音信之疏；尾联忽转，以湘江烟月、门系钓船的闲适画面反衬自己不能归去，以景结情，余味悠然。",
    b: "杜牧旅宿湘江边旅馆，寒灯孤雁、家书难达，写尽羁旅之愁与对闲适生活的向往。",
    n: ["凝情：凝神沉思","悄然：忧愁寂静貌","断雁：离群的孤雁","警愁眠：惊醒愁眠之人","远梦归侵晓：归乡的梦遥远，做到天将晓才醒","家书到隔年：家信要隔一年才到","烟月：烟水月色"]
  },
  "游龙门奉先寺|杜甫": {
    s: "首联点题游寺宿寺；颔联写夜宿所闻所见：阴壑生虚籁、月林散清影，声色俱幽；颈联「天阙象纬逼，云卧衣裳冷」以夸张写寺之高峻——星辰可扪、云气侵衣，气象阔大；尾联将醒未醒闻晨钟，顿生深省，由景入理，禅意悠然，是杜诗中少见的清远之作。",
    b: "杜甫青年时期游洛阳龙门、夜宿奉先寺所作，是其早期山水纪游诗，已见沉郁雄浑的笔力。",
    n: ["龙门奉先寺：在洛阳龙门石窟，奉先寺为唐代大像窟","招提：梵语拓斗提奢的省称，此指寺院","阴壑：幽深的山谷","虚籁：空谷中的自然声响。籁，从孔穴发出的声音","天阙：即龙门两山如天阙（宫门双阙）","象纬逼：星辰仿佛逼近。象纬，日月星辰","云卧：高卧云间","发深省：引发深刻的省悟"]
  },
  "贫交行|杜甫": {
    s: "首句以「翻云覆雨」的比喻写尽人情反复，成为千古成语；次句「何须数」三字冷峻，不屑之情溢于言表；后两句以管鲍贫交作对照——古人贫贱相交、生死相托之道，今人竟弃如粪土。以古衬今，愤激深沉，短短二十八字道尽世态炎凉。",
    b: "杜甫困居长安时，见世态炎凉、人情反复，借管鲍之交的典故慨叹当世再无贫贱之交。",
    n: ["贫交行：写贫贱之交的乐府诗。行，歌行体","翻手作云覆手雨：翻手为云、覆手为雨，喻人情反复无常","纷纷轻薄：众多轻薄之徒","何须数：哪值得一一数说","管鲍：管仲与鲍叔牙，春秋时贫贱之交的典范","此道：指贫贱相交之道","弃如土：被抛弃如粪土"]
  },
  "秋雨叹三首·一|杜甫": {
    s: "首联以雨中百草烂死反衬决明颜色独鲜，赞其坚韧；颔联以翠羽盖、黄金钱两个比喻写决明叶之茂、花之艳，色彩明丽；颈联忽转忧——凉风急吹，恐其错过花期、难以独立，既是惜花也是自伤；尾联书生白头、临风三嗅而泣，花与人合而为一，物我同悲。",
    b: "杜甫《秋雨叹》三首之一，天宝十三载秋长安久雨成灾，诗人借阶下决明花在秋雨中独鲜、又恐被秋风摧折，自伤身世。",
    n: ["决明：草本植物，夏秋开黄花，种子可入药","著叶满枝翠羽盖：叶子满枝如翠羽伞盖","开花无树黄金钱：花开如黄金钱（决明花黄色圆形）","凉风萧萧：秋风萧瑟","后时：晚于时节、错过花期","堂上书生：杜甫自指","三齅馨香：多次嗅其香气。齅同「嗅」"]
  },
  "秋雨叹三首·二|杜甫": {
    s: "首联以「四海八荒同一云」极写雨势之大、范围之广；颔联化用《庄子》牛马不辨之典，又以泾渭清浊难分写雨雾迷蒙，用典而不见痕迹；颈联写禾穗生耳、黍穗发黑，农田绝收的惨状如在目前；尾联写城中灾民卖被换米、不计价钱，以具体交易写饥荒之重，沉郁痛切。",
    b: "杜甫《秋雨叹》之二，写天宝十三载长安久雨成灾、农田受损、米价飞涨的民生惨状，是现实主义的实录。",
    n: ["阑风长雨：连绵不断的风雨。阑，残、尽","四海八荒同一云：天下各处都笼罩在同一片阴云下","去马来牛不复辨：雨大到牛马不辨（用《庄子》「两涘渚崖之间不辨牛马」意）","浊泾清渭何当分：泾水浊、渭水清，大雨中也无法分辨","禾头生耳：雨后禾穗发芽如耳（霉变）","黍穗黑：黍穗因雨发黑","斗米换衾裯：一斗米就能换被子（言粮贵物贱、灾民卖物换粮）。衾裯，被子","相许宁论两相直：双方同意就换，哪还论价钱相当。直同「值」"]
  },
  "房兵曹胡马诗|杜甫": {
    s: "首联点出大宛名马；颔联以「锋棱」「竹批」写马的骨相耳形，工笔细描而见神骏；颈联由形入神——所向无阻、可托死生，马之品格跃然；尾联「万里可横行」由马及人，既是赞马也是期许房兵曹能驰骋疆场，咏物即咏人，雄健豪迈。",
    b: "杜甫早期咏物诗，为友人房兵曹的胡马画像，借马言志，抒发青年时期建功立业的豪情。",
    n: ["房兵曹：一位姓房的兵曹参军","胡马大宛名：大宛（今中亚费尔干纳）出产的名马。宛音yuān","锋棱瘦骨成：瘦骨棱棱如刀锋，写马的神骏","竹批双耳峻：双耳如削竹般尖锐挺立（良马特征）","风入四蹄轻：跑起来四蹄生风、轻快如飞","所向无空阔：所到之处没有能阻挡它的空阔之地","真堪托死生：真可以把生死托付给它","骁腾：矫健奔腾"]
  },
  "画鹰|杜甫": {
    s: "首联「风霜起」三字破空而来，写画鹰气势逼人；颔联写画中鹰竦身侧目、欲捕狡兔的神态，「愁胡」喻鹰眼，形神兼备；颈联写画之逼真——绦旋可摘、呼之欲出，以假乱真；尾联由画及真，盼此鹰能搏击凡鸟、血染原野，借鹰言志，抒发扫除奸邪的豪情，咏物诗的典范。",
    b: "杜甫早期咏画诗，为一幅苍鹰画题咏，借画鹰抒发嫉恶如仇、搏击凡庸的壮志。",
    n: ["素练：白绢，画鹰所用","风霜起：画上仿佛有风霜之气涌起","画作殊：画得特别出色","身：竦身、耸身。同「竦」","思狡兔：想捕捉狡兔","俱目似愁胡：鹰眼锐利如愁胡（胡人，其目深碧锐利）","绦旋：系鹰的丝绳和转轴。绦音tāo","光堪擿：光彩耀眼几乎可摘下。擿同「摘」","轩楹：廊柱，此指画鹰悬挂之处","势可呼：气势如生，仿佛呼之欲出","凡鸟：凡庸的鸟","平芜：平坦的原野"]
  },
  "春日忆李白|杜甫": {
    s: "首联「诗无敌」「思不群」直抒对李白的推崇；颔联以庾信之清新、鲍照之俊逸比李白诗风，用典精当；颈联是千古名句——渭北春树、江东暮云，两地之景各自在目，而思念之情尽在不言中，情景交融、含蓄不尽；尾联盼重聚把酒论文，情深意切，是李杜交谊的见证。",
    b: "天宝五载（746）前后杜甫在长安，思念漫游江东的李白而作，盛赞李白诗才，表达重聚论诗的渴望。",
    n: ["白也：李白，「也」为语气词","无敌：无人能比","飘然思不群：才思飘逸、卓尔不群","庾开府：庾信，北周文学家，官至开府仪同三司","鲍参军：鲍照，南朝宋诗人，曾任临海王参军","渭北：渭水以北，指杜甫所在长安","江东：长江以东，指李白所在吴越","一尊酒：一杯酒。尊同「樽」","细论文：细细讨论诗文"]
  },
  "九日曲江|杜甫": {
    s: "首联写重阳茱萸、菡萏已衰，秋意萧瑟；颔联点出九月将半、重阳含悲，「意兼悲」三字定下全诗基调；颈联写江水曲折、荆门路疑，借地理写仕途方向之迷茫；尾联写游兴已尽、重阳赏菊之约也被摇荡，由景入情，含蓄写出贬谪前夕的失意与彷徨。",
    b: "杜甫乾元元年（758）任左拾遗时，重阳日游曲江所作，写秋景衰飒、仕途失意的悲慨。",
    n: ["缀席茱萸：茱萸插在坐席旁（重阳节佩茱萸避邪）","浮舟菡萏衰：泛舟曲江，荷花已凋零。菡萏，荷花","季秋：秋季第三个月，即九月","意兼悲：心意中兼有悲意","江水清源曲：江水清澈、源流曲折","荆门此路疑：此去荆门之路令人疑虑（荆门在湖北，曲江在长安，方向不合）","高兴尽：高情逸兴已尽","摇荡菊花期：动摇了重阳赏菊的约期"]
  },
  "春宿左省|杜甫": {
    s: "首联写薄暮花隐、栖鸟飞过，交代值班时分；颔联是名句——星光下临、万户闪动，月近九霄、高处得月，以夸张写宫殿之高峻壮丽，气象雄浑；颈联写不寐听锁、因风想珂，勤于王事之态如见；尾联写明日有封事、屡问夜如何，以细节写尽尽职的急切，严谨中见忠恳。",
    b: "杜甫任左拾遗时，春夜在门下省值班所作，写宫中夜景与勤于职守的心情，是其早期宫廷诗。",
    n: ["左省：门下省，在宫殿左侧，杜甫时任左拾遗属门下省","掖垣：宫门旁的墙，此指左省。掖音yè","栖鸟：归巢的鸟","星临万户动：星光下照，宫中千门万户仿佛闪动","月傍九霄多：月光靠近高天，宫殿高处得月最多","金钥：宫中门锁","玉珂：马勒上的玉饰，此指百官上朝的马铃声","封事：密封的奏章","数问夜如何：屡次询问夜到几更（盼天亮好上朝）"]
  },
  "秦州杂诗二十首·一|杜甫": {
    s: "首联「满目悲生事」总起，「因人作远游」交代漂泊之由；颔联写度陇胆怯、及关愁生，行旅之苦与心理之惧交织；颈联是名句——以鱼龙川、鸟鼠山两个秦州地名入对，水落山空、夜色秋声，边地荒寒如在目前，对仗工稳而意境苍凉；尾联写西征问烽火、心折淹留，战乱未息、归乡无日，悲慨深沉。",
    b: "杜甫乾元二年（759）弃官西行、初到秦州所作《秦州杂诗》二十首之一，写战乱中漂泊边地的愁苦。",
    n: ["秦州：今甘肃天水，杜甫乾元二年弃官后寓居于此","悲生事：为生计而悲","因人：依靠他人（指投奔在秦州的侄儿杜佐等）","迟回：徘徊犹豫","度陇：越过陇山。陇，陇山，在陕甘交界处","浩荡及关愁：到了边关，愁思浩荡","鱼龙夜：鱼龙川的夜晚（秦州附近水名，秋夜水寒）","鸟鼠秋：鸟鼠山的秋色（秦州附近山名）","西征问烽火：西行路上探问战火（吐蕃侵扰）","心折：心碎、伤心","淹留：久留"]
  },
  "卜居|杜甫": {
    s: "首联点题——浣花溪畔、主人为卜林塘幽处；颔联写出郭少尘事、澄江销客愁，环境宜人；颈联是名句——蜻蜓齐飞上下、㶉𫛶成对浮沉，以两个特写镜头写草堂前的生机与闲适，对仗工细、画面明丽；尾联用王子猷山阴乘兴典故，写在此可乘兴东游、旷达自适，欣喜之情溢于言表。",
    b: "杜甫上元元年（760）初到成都、在浣花溪畔营建草堂时所作，写卜居环境的清幽与欣喜。",
    n: ["浣花流水：浣花溪的流水，在成都西郊","主人：指当地友人（或指成都尹裴冕）为杜甫卜居","卜林塘幽：选择了一处林木池塘清幽的地方。卜，选择","出郭：出城","澄江：清澈的锦江","㶉𫛶：水鸟，似鸳鸯而大，羽毛五彩。音xīchì","沈浮：在水中浮沉。沈同「沉」","乘兴：趁着兴致","山阴：今浙江绍兴，用王子猷雪夜访戴逵「乘兴而行，兴尽而返」典故"]
  },
  "江村|杜甫": {
    s: "首联「清江一曲抱村流，长夏江村事事幽」总写环境清幽；颔联以燕子自来自去、鸥鸟相亲相近，写物态的自在，也暗示人的闲适；颈联写老妻画棋盘、稚子敲钓钩，两个生活细节写尽天伦之乐，朴素而温馨；尾联「多病所须唯药物，微躯此外更何求」，在欣喜中透出一丝苦涩——多病之身只求药物，别无所求，乐中含悲，沉郁底色仍在。",
    b: "杜甫上元元年（760）成都草堂建成后所作，写江村夏日的闲适生活与老妻稚子的天伦之乐，是杜诗中少有的轻快之作。",
    n: ["清江一曲：锦江一弯","抱村流：环绕村庄流淌","长夏：漫长的夏日","事事幽：事事都显得清幽","自去自来堂上燕：堂上燕子自来自去","相亲相近水中鸥：水中鸥鸟相亲相近","画纸为碁局：在纸上画棋盘。碁同「棋」","敲针作钓钩：把针敲弯做成钓钩","微躯：微贱的身躯，杜甫自指"]
  },
  "南邻|杜甫": {
    s: "首联写南邻形象——乌角巾、园收芋粟，隐士风度与清贫生活并见；颔联写儿童惯看宾客而喜、鸟雀得食阶除而驯，以两个细节写主人的好客与环境的宁静；颈联是名句——秋水才四五尺深、小船正好坐两三人，数字入诗而意境清幽，田园气息浓郁；尾联写白沙翠竹、江村日暮、柴门相对月色新，以景结情，两人交往的闲适尽在画面中。",
    b: "杜甫在成都草堂时，写其南邻一位隐士的生活与二人交往，是田园诗的佳作。",
    n: ["锦里先生：指杜甫南邻朱山人（隐士），锦里为成都地名","乌角巾：黑色的方巾，隐士所戴","芋粟：芋头和小米","不全贫：不算太穷","阶除：台阶","鸟雀驯：鸟雀被驯化、不怕人","野航：乡村小船","恰受：正好容纳","柴门：简陋的门"]
  },
  "江亭|杜甫": {
    s: "首联写坦腹江亭、长吟野望，闲适之态如见；颔联是名句——水流而心不竞逐、云在而意兴俱迟，以水云之自在写心境之超然，情景交融、物我两忘，是杜诗中极富禅意的一联；颈联写春将晚、物自私，万物自得而人独寂寞；尾联点出故林归未得、只能强裁诗排闷，闲适背后是深沉的乡思，乐中含悲。",
    b: "杜甫成都草堂时期春日江亭闲坐所作，写闲适心境中暗藏的归乡之思。",
    n: ["坦腹：坦露腹部，用王羲之东床坦腹典故，写闲适不拘","长吟：长声吟咏","野望：眺望原野","水流心不竞：江水自流，我心已无竞逐之意","云在意俱迟：白云自在，我的意兴也同样舒缓","寂寂：寂静貌","欣欣：草木茂盛貌","物自私：万物各自得其乐","故林：故乡的树林，代指故乡","排闷：排遣烦闷","强裁诗：勉强作诗。裁，制作"]
  },
  "琴台|杜甫": {
    s: "首联写相如晚年多病仍爱文君，以「尚爱」二字见爱情之坚；颔联「酒肆人间世，琴台日暮云」，将当年当垆卖酒的热闹与今日琴台空对暮云的荒凉对举，盛衰之感油然而生；颈联是名句——野花如文君的酒窝、蔓草如她的罗裙，以眼前景物想象古人芳踪，亦真亦幻，凄艳动人；尾联叹凤求凰之意已寥寥不闻，怀古伤今，余韵悠然。",
    b: "杜甫成都时期凭吊司马相如琴台所作，借相如文君爱情故事抒发对真挚爱情的追慕与对世事变迁的感慨。",
    n: ["琴台：司马相如与卓文君当垆卖酒处，在成都","茂陵多病后：司马相如晚年多病居茂陵（汉武帝陵邑）","尚爱卓文君：仍然深爱卓文君","酒肆人间世：在酒肆中度过人间岁月（卓文君当垆、相如涤器）","琴台日暮云：琴台之上只有日暮浮云","宝靥：女子的酒窝，此指卓文君的遗迹。靥音yè","罗裙：丝罗裙，代指卓文君","归凤求皇：司马相如以《凤求凰》琴曲打动卓文君。皇同「凰」","寥寥：稀少、断绝"]
  },
  "江畔独步寻花七绝句·一|杜甫": {
    s: "首句「被花恼不彻」出新意——花本可赏，诗人却说被花搅扰，以嗔写爱，花之繁密、人之痴爱尽在「恼」字中；次句写无处诉说、只能独自颠狂，痴态可掬；后两句写去找南邻爱酒的朋友，可友人已出门十天、只剩空床，欲共赏而不得，小小的失望中见春日的烂漫与诗人的天真，语言口语化而情致盎然。",
    b: "杜甫成都草堂时期《江畔独步寻花》七首之一，写春日被花撩拨、欲寻酒友共赏而友人不在的小烦恼，诙谐有趣。",
    n: ["被花恼不彻：被花搅扰得无法排遣。恼，撩拨、搅扰","无处告诉：无处诉说","颠狂：放浪形骸","南邻爱酒伴：南边邻居爱喝酒的朋友（指斛斯融等）","经旬：十天、很长时间","独空床：独自空床（言友人外出未归）"]
  },
  "戏为六绝句·一|杜甫": {
    s: "首两句高度评价庾信——文章越老越成熟、笔力凌云、才思纵横，为庾信正名；后两句讽刺今人——轻薄之徒嗤笑指点庾信流传的赋作，却不知「前贤畏后生」本是褒义，这里反用：你们这些后生如此狂妄，只怕前贤见了也要「畏惧」你们的无知！以戏谑之笔写严肃的文学批评，锋芒毕露而幽默隽永。",
    b: "杜甫《戏为六绝句》之一，针对当时文坛轻薄之徒妄议前贤而发，提出正确评价前代作家的态度，是最早的论诗绝句。",
    n: ["庾信：南北朝文学家，由南入北，诗赋沉郁","老更成：越老越成熟、越有成就","凌云健笔：笔力雄健、直上云霄","意纵横：才思奔放自如","嗤点：嗤笑指点。嗤音chī","流传赋：流传下来的赋作","前贤畏后生：前贤也会畏惧后生可畏（反语，讽刺今人狂妄）"]
  },
  "水槛遣心二首·一|杜甫": {
    s: "首联写草堂环境——去郭轩敞、眺望辽远；颔联写澄江平岸、幽树多花，远景近景相映；颈联是名句——细雨中鱼儿跃出水面、微风里燕子斜飞，「出」「斜」二字极炼，以细腻观察写春日生机，体物工细；尾联以城中十万户与草堂两三家对比，以城市的繁华反衬此处的清幽，表达对闲适田园生活的喜爱，悠然自得。",
    b: "杜甫成都草堂时期《水槛遣心》二首之一，写凭栏远眺所见的江村春色与闲适心境。",
    n: ["水槛：草堂水边的栏杆。槛音jiàn","遣心：排遣心情","去郭：离开城郭","轩楹敞：廊柱宽敞。轩楹，廊柱","眺望赊：眺望得很远。赊，远","澄江平少岸：清澈的江水上涨、几乎与岸平","幽树晚多花：幽静的树木傍晚时花开正多","城中十万户：成都城中有十万户","此地两三家：草堂附近只有两三家"]
  },
  "不见|杜甫": {
    s: "首联写不见李白已久、他佯狂避世，令人哀怜；颔联是千古名句——「世人皆欲杀，吾意独怜才」，以世人的态度与自己的立场强烈对比，在众人喊杀声中独持怜才之论，胆识与深情并见；颈联「敏捷诗千首，飘零酒一杯」以千首诗与一杯酒对举，才高命蹇的反差令人扼腕；尾联盼李白头白归匡山隐居，深情厚谊，感人至深。",
    b: "李白因永王李璘案获罪、流放夜郎（后遇赦），杜甫在成都闻讯而作，表达对李白的深切同情与对其才华的高度推崇。",
    n: ["李生：李白","佯狂：假装癫狂","世人皆欲杀：当时世人都想杀李白（李白因永王李璘案下狱流放）","吾意独怜才：我唯独爱惜他的才华","敏捷诗千首：才思敏捷、作诗千首","飘零酒一杯：漂泊四方、以酒为伴","匡山：大匡山，在四川江油，李白少年读书处","头白好归来：头发白了正好归来隐居"]
  },
  "武侯庙|杜甫": {
    s: "首联写武侯庙的荒凉——丹青剥落、空山草木，以景写情，古庙的荒凉暗喻诸葛亮身后的寂寞；颔联「犹闻辞后主，不复卧南阳」是全诗核心：仿佛还能听到他辞别后主、北伐中原的誓言，可他再也不能回到南阳隐居了——「犹闻」写精神长存，「不复」写身死志决，鞠躬尽瘁、死而后已的形象跃然纸上，短短二十字，沉郁悲壮。",
    b: "杜甫大历元年（766）寓居夔州时谒武侯庙所作，缅怀诸葛亮鞠躬尽瘁、死而后已的一生。",
    n: ["武侯庙：诸葛亮庙，在夔州（今重庆奉节）","遗庙丹青落：古庙中壁画的丹青颜料已经剥落","空山草木长：空山中草木茂盛生长。长音zhǎng","辞后主：辞别后主刘禅（指诸葛亮北伐前上《出师表》辞朝）","不复卧南阳：不能再回到南阳隐居了（诸葛亮早年隐居南阳隆中）"]
  },
  "秋兴八首·一|杜甫": {
    s: "首联以玉露凋伤、巫山萧森奠定全诗萧瑟苍凉的基调；颔联「江间波浪兼天涌，塞上风云接地阴」是千古名句——波浪滔天、风云接地，既写峡中秋景的险恶，也暗喻时局的动荡不安，情景交融、气象雄浑；颈联「丛菊两开他日泪，孤舟一系故园心」，菊开两次、泪流两次，孤舟长系、故园心系，以工整对仗写羁旅之愁与乡思之苦；尾联以寒衣处处、白帝城高、暮砧急促收束，捣衣声中尽是思归之情，沉郁顿挫。",
    b: "杜甫大历元年（766）秋寓居夔州所作《秋兴八首》之首，是组诗的总纲，写夔州秋景与对长安故园的思念。",
    n: ["玉露：白露如玉","凋伤：使草木凋落衰败","巫山巫峡：长江三峡中的巫峡，在今重庆巫山","萧森：萧瑟阴森","兼天涌：波浪滔天","接地阴：云层低垂、仿佛接地，阴晦","丛菊两开：杜甫到夔州已两年，菊开两次","他日泪：为往事（故乡）而流泪","孤舟一系：孤舟一系于此（不能归乡）","故园心：思念故园之心","催刀尺：赶制寒衣（刀尺为裁衣工具）","白帝城：在夔州，三峡入口","急暮砧：傍晚捣衣声急促。砧，捣衣石，音zhēn"]
  },
  "咏怀古迹五首·一|杜甫": {
    s: "首联「支离东北风尘际，漂泊西南天地间」总写自己在安史之乱中流离东北、漂泊西南的身世，「天地间」三字写尽漂泊之广、之孤；颔联写三峡久留、五溪共居，滞留边地的苦闷；颈联以「羯胡无赖」指安禄山叛乱、「词客未还」写自己不能还朝，家国之恨交织；尾联以庾信自比——庾信萧瑟一生、暮年诗赋动江关，正是杜甫自身的写照，借古人写己悲，沉郁苍凉。",
    b: "杜甫《咏怀古迹》五首之一，借庾信身世自比，写自己在战乱中漂泊西南、不能还朝的身世之悲。",
    n: ["支离：流离分散","东北风尘际：安史之乱中（东北方向战火纷飞）","漂泊西南：漂泊到西南（蜀地）","三峡楼台淹日月：在三峡一带的楼台间久留、虚度岁月。淹，滞留","五溪衣服共云山：与五溪少数民族共居云山之间。五溪，湘西黔东五条溪流，少数民族聚居地","羯胡事主终无赖：安禄山（羯胡）侍奉君主最终反复无常。羯胡，古族名，此指安禄山","词客衰时且未还：诗人（词客，杜甫自指）在衰乱之时尚未还朝","庾信平生最萧瑟：庾信一生最是凄凉萧瑟（庾信由南入北，常有乡关之思）","暮年诗赋动江关：晚年诗赋震撼江关（指其《哀江南赋》等名作）"]
  },
  "江汉|杜甫": {
    s: "首联「江汉思归客，乾坤一腐儒」，以「思归客」与「腐儒」自指，漂泊之苦与自嘲之悲并见，「乾坤」二字写尽孤独；颔联「片云天共远，永夜月同孤」，以片云、孤月自比，情景交融，孤独之感深入骨髓；颈联是名句——落日喻暮年而壮心犹在，秋风起而病体渐疏，一「犹」一「欲」，老而弥坚的精神跃然纸上；尾联用老马识途典故，自比老马虽老仍有用，旷达中见自信，是杜甫晚年精神的写照。",
    b: "杜甫大历三年（768）漂泊江陵时所作，写暮年多病、漂泊江汉而壮心不已的情怀。",
    n: ["江汉：长江汉水之间，指湖北江陵一带，杜甫晚年漂泊至此","思归客：思归故乡的游子，杜甫自指","乾坤一腐儒：天地间一个迂腐的书生（自谦兼自伤）","片云天共远：一片孤云与天共远","永夜月同孤：漫长的夜晚与月同孤","落日心犹壮：落日（喻暮年）时分壮心犹在","秋风病欲疏：秋风起时病体渐有好转。疏，疏缓、减轻","古来存老马：自古以来存养老马（用「老马识途」典故）","不必取长途：不一定非要它跑长途（自比老马，虽老仍有用）"]
  },
  "孤雁|杜甫": {
    s: "首联写孤雁不饮不啄、飞鸣念群，以反常行为写失群之痛；颔联「谁怜一片影，相失万重云」是名句——一片孤影与万重云层对比，孤雁的渺小与天空的辽阔形成强烈反差，「谁怜」二字写尽无人同情的孤独；颈联「望尽似犹见，哀多如更闻」，以幻觉写思念之深——望到极处仿佛看见同伴、哀鸣太多仿佛听到回应，痴情可悯；尾联以野鸦的无情喧闹反衬孤雁的孤独，物我同悲，沉郁动人。",
    b: "杜甫大历初年寓居夔州时所作，借孤雁失群写自己在战乱中漂泊、亲友离散的孤独与哀痛。",
    n: ["不饮啄：不饮水不啄食","飞鸣声念群：边飞边鸣、声声呼唤同伴","一片影：一片孤影","相失万重云：在万重云层中失散","望尽似犹见：望到极处仿佛还能看见同伴","哀多如更闻：哀鸣太多仿佛又听到同伴的回应","野鸦无意绪：野鸦全不理会（孤雁的哀鸣）","鸣噪自纷纷：只顾自己纷纷喧闹"]
  },
  "春宫怨|杜荀鹤": {
    s: "首联写早被美貌耽误、欲妆临镜又慵，点出宫怨主题；颔联「承恩不在貌，教妾若为容」是全诗警句——既然受宠不在于容貌，叫我如何去梳妆呢？以反问写尽宫女的绝望与无奈，对宫廷制度的批判含蓄而深刻；颈联「风暖鸟声碎，日高花影重」，以乐景写哀，春光越美、宫怨越深；尾联写年年忆越溪女、相忆采芙蓉，以故乡的自由快乐反衬深宫的孤寂，余味悠然。",
    b: "杜荀鹤（晚唐诗人）这首宫怨诗写宫女因美貌入宫、却因承恩不在貌而无心梳妆，怀念故乡的自由生活。",
    n: ["婵娟：美貌，此指美貌的宫女","误：被（美貌）耽误","临镜慵：对着镜子懒得梳妆。慵，慵懒","承恩：承受皇帝恩宠","若为容：怎样去梳妆打扮。若为，如何","鸟声碎：鸟鸣声细碎","花影重：花影层叠。重音chóng","越溪女：越地（今浙江）溪边的女子，此指西施当年浣纱的同伴","采芙蓉：采荷花（指当年在故乡的快乐生活）"]
  },
  "送人游吴|杜荀鹤": {
    s: "首联「君到姑苏见，人家尽枕河」，以叮嘱口吻写苏州最典型的景观——家家临河而居，画面感极强；颔联「古宫闲地少，水港小桥多」，以「闲地少」写城市的繁华密集、以「小桥多」写水乡的特色，对仗工稳；颈联「夜市卖菱藕，春船载绮罗」，写夜市的热闹与春船的华丽，商业繁荣与水乡风情并见；尾联「遥知未眠月，乡思在渔歌」，由景入情，想象友人月下未眠、乡思尽在渔歌中，以景结情，余韵悠长。",
    b: "杜荀鹤这首诗写苏州水乡的独特风貌——人家尽枕河、水港小桥多，是描写江南水乡的千古名篇。",
    n: ["姑苏：苏州的别称","枕河：房屋临河而建（枕，临、靠近）","古宫：古代吴国的宫殿","闲地少：空闲的土地少","水港：水巷","绮罗：丝织品，此指穿着华丽的游人","未眠月：月下尚未入眠","乡思：思乡之情","渔歌：渔人之歌"]
  },
  "小松|杜荀鹤": {
    s: "前两句写小松的生长环境——自小埋在深草里、如今才渐渐高出蓬蒿，以「刺头」写小松的坚韧与不起眼；后两句是全诗主旨——时人不识这将来能凌云的树木，一直等它真的高耸入云了才称赞它高，以小松喻人才，讽刺世人不识人才于微时、只会在人才成功后跟风称赞，咏物即咏人，寓意深刻。",
    b: "杜荀鹤这首咏物诗借小松不被时人识、直到凌云才被称高，讽刺世人不识人才、目光短浅。",
    n: ["刺头：长满尖刺的小松苗头","蓬蒿：蓬草和蒿草，泛指野草","凌云木：可以高耸入云的树木（喻栋梁之材）","直待：一直等到","始道高：才说它高大"]
  },
  "从军行|杨炯": {
    s: "首联「烽火照西京，心中自不平」，以烽火报警写边情紧急、书生内心激愤；颔联「牙璋辞凤阙，铁骑绕龙城」，写出师出征、包围敌城的雄壮场面；颈联「雪暗凋旗画，风多杂鼓声」，以风雪昏暗、鼓声杂风写战场的艰苦与激烈，视听结合；尾联「宁为百夫长，胜作一书生」，直抒胸臆，宁愿做下级军官冲锋陷阵，也胜过做一介书生，投笔从戎的豪情跃然纸上，刚健豪迈。",
    b: "杨炯（初唐四杰之一）这首《从军行》写书生投笔从戎、渴望建功立业的豪情，是初唐边塞诗的名篇。",
    n: ["西京：长安","牙璋：古代发兵的符信，此指将帅。璋音zhāng","凤阙：皇宫的美称，此指长安","铁骑：精锐的骑兵","龙城：匈奴祭天处，此指敌方要地","凋旗画：使旗帜上的彩绘褪色。凋，使……凋零","百夫长：下级军官，统率百人","胜作一书生：胜过做一个书生"]
  },
  "与浩初上人同看山寄京华亲故|柳宗元": {
    s: "首两句「海畔尖山似剑铓，秋来处处割愁肠」，以剑铓喻尖山，写山形的尖利，而这尖山处处在割我的愁肠，以比喻写乡愁之痛，想象奇特；后两句「若为化得身千亿，散上峰头望故乡」，更进一层——恨不得化身千亿，分散到每座山峰顶上眺望故乡，以夸张写思乡之切、之深，奇想惊人，深情动人，是柳宗元贬谪诗的代表作。",
    b: "柳宗元被贬柳州（今广西）时，与僧人浩初同看山，寄给京城亲友，写被贬边地的思乡之苦。",
    n: ["浩初上人：僧人浩初，上人是对僧人的敬称","京华亲故：京城的亲友","剑铓：剑锋。铓同「芒」，刀剑的尖端","割愁肠：割我的愁肠","若为化得身千亿：怎能把身体化作千亿个","散上峰头：分散到各个山峰顶上","望故乡：眺望故乡"]
  },
  "登柳州城楼寄漳汀封连四州|柳宗元": {
    s: "首联「城上高楼接大荒，海天愁思正茫茫」，登楼远眺、愁思茫茫，奠定全诗基调；颔联「惊风乱飐芙蓉水，密雨斜侵薜荔墙」，写急风乱吹荷花、密雨斜侵薜荔墙，既是眼前实景，也暗喻政治风暴对自己的打击，情景交融；颈联「岭树重遮千里目，江流曲似九回肠」，岭树遮望眼、江流如愁肠，以景写情，对仗工稳；尾联写共来百越文身之地、音书阻隔，同病相怜的悲慨深沉，是柳宗元七律的压卷之作。",
    b: "柳宗元元和十年（815）被贬柳州，与友人韩泰、韩晔、陈谏、刘禹锡同贬南方四州，登柳州城楼寄给四州友人，写共同的贬谪之悲与相思之苦。",
    n: ["漳汀封连四州：漳州、汀州、封州、连州，指与柳宗元同时被贬的四位友人（韩泰、韩晔、陈谏、刘禹锡）","大荒：荒远的边地","海天愁思：愁思如海天般茫茫","惊风：急风","飐：吹动。音zhǎn","芙蓉水：长着荷花的水面","薜荔墙：爬满薜荔的墙。薜荔，常绿藤本植物","岭树：五岭上的树木","重遮：重重遮蔽","九回肠：愁肠九转（喻愁思之深）","百越：南方少数民族地区","文身：纹身（古越地风俗）","音书滞一乡：音信阻隔在各自的贬所。滞，阻隔"]
  },
  "酬曹侍御过象县见寄|柳宗元": {
    s: "首两句「破额山前碧玉流，骚人遥驻木兰舟」，写友人在碧玉般的江流中停舟，画面清丽；后两句「春风无限潇湘意，欲采蘋花不自由」，春风中充满了潇湘的诗情画意，想采一朵蘋花寄给友人却身不由己——「不自由」三字一语双关，既是被贬谪的不自由，也是对友人思念而不得相见的不自由，含蓄蕴藉，余味悠长。",
    b: "柳宗元被贬柳州时，友人曹侍御路过象县寄诗给他，他以此诗酬答，写对友人的思念与被贬不能自由归去的苦闷。",
    n: ["曹侍御：曹姓侍御史","象县：今广西象县","见寄：寄诗给我","破额山：在柳州附近","碧玉流：碧绿如玉的江水","骚人：诗人，此指曹侍御","木兰舟：用木兰木造的船（船的美称）","潇湘意：潇湘一带的诗情画意（潇湘在湖南，柳宗元故乡附近）","蘋花：浮萍的花。蘋音pín","不自由：身不由己（指被贬不能自由归去）"]
  },
  "溪居|柳宗元": {
    s: "首联「久为簪组累，幸此南夷谪」，说久被官职拖累，幸而被贬南方得以闲适，「幸」字是反语，含被贬的苦涩；颔联「闲依农圃邻，偶似山林客」，写与农田为邻、偶尔像山林隐士，闲适中有自嘲；颈联「晓耕翻露草，夜榜响溪石」，写清晨耕地翻草、夜晚摇船碰石，田园生活的画面清新；尾联「来往不逢人，长歌楚天碧」，写独来独往、对天长歌，闲适背后是孤独，乐中含悲，是柳宗元贬谪诗的复杂心境。",
    b: "柳宗元被贬永州（今湖南零陵）时，在溪边闲居，写农耕泛舟的闲适生活与被贬的复杂心情。",
    n: ["簪组：古代官员的冠簪和印绶，代指官职。簪音zān","累：拖累","南夷谪：被贬到南方少数民族地区","农圃邻：与农田菜园为邻","山林客：山林中的隐士","榜：摇船的桨，此指摇船","响溪石：船桨碰击溪石发出声响","楚天：楚地的天空（永州古属楚）"]
  },
  "小石潭记|柳宗元": {
    s: "全文按游踪展开：先闻声（如鸣珮环）、再见潭（水尤清冽、全石为底），再写潭中鱼——「皆若空游无所依」以鱼写水之清，「佁然不动」「俶尔远逝」动静结合，「似与游者相乐」物我同乐；再写潭西南望，斗折蛇行、犬牙差互，写水源之幽；最后写坐潭上，四面竹树环合、寂寥无人、凄神寒骨，以其境过清不可久居，乐中转悲，贬谪的孤寂尽在「悄怆幽邃」四字中。",
    b: "柳宗元被贬永州时所作《永州八记》之一，写发现小石潭的经过与小石潭的清幽景色，是山水游记的千古名篇。",
    n: ["篁竹：成林的竹子。篁音huáng","鸣珮环：像佩玉碰撞的声音。珮同「佩」","清冽：清凉。冽音liè","坻：水中高地。音chí","屿：小岛","嵁：不平的岩石。音kān","翠蔓：翠绿的藤蔓","蒙络摇缀：覆盖缠绕、摇动连结","参差披拂：长短不齐、随风飘拂","佁然：呆呆的样子。佁音yǐ","俶尔：忽然。俶音chù","翕忽：轻快敏捷。翕音xī","斗折蛇行：像北斗星那样曲折、像蛇那样蜿蜒前行","犬牙差互：像狗牙那样交错不齐","悄怆幽邃：寂静凄凉、幽深。悄怆音qiǎochuàng；邃音suì","隶而从者：跟随我来的人"]
  },
  "捕蛇者说|柳宗元": {
    s: "全文用对比和衬托手法：先写异蛇之毒——触草木尽死、啮人无御之者，而永州人却争着捕蛇，以蛇之毒衬赋之重；再写蒋氏三代捕蛇、祖死父死己几死者数矣，而他却不愿更换差役——因为乡邻们被赋税逼得非死即徙，而他以捕蛇独存；悍吏来乡、鸡狗不宁，而他视缶中蛇尚存则弛然而卧，以捕蛇之「幸」衬赋税之「不幸」；最后引孔子「苛政猛于虎」作结，发出「赋敛之毒有甚是蛇」的呐喊，现实主义的批判力透纸背。",
    b: "柳宗元被贬永州时所作，通过捕蛇者蒋氏的遭遇，揭露中唐时期赋税苛重、民不聊生的社会现实，提出「苛政猛于虎」的批判。",
    n: ["黑质而白章：黑色的底子、白色的花纹","腊之以为饵：把它晾干做成药饵。腊音xī，晾干","已大风：治愈麻风病。已，治愈；大风，麻风病","挛踠：手脚弯曲不能伸展。挛音luán、踠音wǎn","瘘疠：脖子肿和恶疮。瘘音lòu、疠音lì","去死肌：去除坏死的肌肉","杀三虫：杀死人体内的寄生虫","岁赋其二：每年征收两次","当其租入：抵他的租税","莅事者：管这事的官吏。莅音lì","更若役：更换你的差役","复若赋：恢复你的赋税","生日蹙：生活一天天窘迫。蹙音cù","殚其地之出：把地里的出产全部拿出。殚音dān","竭其庐之入：把家里的收入全部用尽","顿踣：跌倒在地。踣音bó","隳突：骚扰冲撞。隳音huī","恂恂：小心谨慎的样子。恂音xún","缶：瓦罐。音fǒu","弛然：放心的样子","食之：喂养它。食音sì","观人风者：考察民情的官员。人风，民风（避李世民讳）"]
  },
  "黔之驴|柳宗元": {
    s: "全文按虎对驴的认识过程展开：初见驴以为神、藏林偷看；驴一鸣虎大骇远遁、以为要咬自己；往来视之觉无异能、益习其声、终不敢搏；稍近益狎、荡倚冲冒，驴不胜怒蹄之，虎才识破其技不过如此——跳踉大㘎、断喉尽肉而去。故事生动地写出虎从惧到识的心理变化，也写出驴的外强中干；末段议论「形之庞也类有德，声之宏也类有能」，点明寓意——没有真本领而虚张声势，终会暴露，讽刺深刻。",
    b: "柳宗元被贬永州时所作《三戒》之一，借驴被虎识破而食的故事，讽刺那些外强中干、虚有其表的人。",
    n: ["黔：贵州一带的简称","好事者：喜欢多事的人","庞然大物：庞大的家伙","蔽林间窥之：藏在树林里偷看它。窥音kuī","慭慭然：小心谨慎的样子。慭音yìn","莫相知：不知道它是什么东西","大骇：非常害怕","远遁：逃到远处。遁音dùn","且噬己：将要咬自己。噬音shì","异能：特殊的本领","益习其声：渐渐习惯了它的叫声","终不敢搏：始终不敢扑击它","益狎：更加亲近而不庄重。狎音xiá","荡倚冲冒：摇晃、倚靠、冲撞、冒犯","不胜怒：禁不住发怒。胜音shēng","蹄之：用蹄子踢它","技止此耳：本领不过如此罢了","跳踉：跳跃。踉音liáng","㘎：虎叫声。音hǎn","类有德：好像有德行","类有能：好像有本领"]
  },
  "杂曲歌辞·独不见|沈佺期": {
    s: "首联「卢家小妇郁金堂，海燕双栖玳瑁梁」，以华丽的居室和海燕双栖反衬少妇的孤独；颔联「九月寒砧催下叶，十年征戍忆辽阳」是名句——九月寒砧声催落树叶，丈夫征戍辽阳已十年，捣衣声与落叶声交织，时间之长、思念之深尽在其中；颈联「白狼河北音书断，丹凤城南秋夜长」，写音信断绝、秋夜漫长，两地相思；尾联「谁知含愁独不见，使妾明月照流黄」，以明月照流黄（征衣）作结，物是人非，愁思不尽，是初唐七律的成熟之作。",
    b: "沈佺期（初唐诗人）这首乐府诗写少妇思念远征辽阳的丈夫，是初唐闺怨诗的名篇，对后世影响很大。",
    n: ["卢家小妇：莫愁女（古乐府「河中之水向东流，洛阳女儿名莫愁，十五嫁为卢家妇」），此泛指少妇","郁金堂：用郁金香涂壁的华丽堂屋","玳瑁梁：用玳瑁装饰的屋梁。玳瑁音dàimào，海龟类，甲壳可作装饰","寒砧：寒风中的捣衣声。砧音zhēn","催下叶：催促树叶落下","辽阳：今辽宁辽阳，唐代东北边防要地，此指征人戍守之地","白狼河：即今辽宁大凌河，在辽阳北","丹凤城：指长安（传说秦穆公女弄玉吹箫引凤，凤降咸阳，故称丹凤城）","流黄：黄色的绢，此指征人衣（或指帷帐）"]
  },
  "商山早行|温庭筠": {
    s: "首联「晨起动征铎，客行悲故乡」，清晨车铃响起、游子悲故乡，点明题旨；颔联「鸡声茅店月，人迹板桥霜」是千古名句——十个字六个名词（鸡声、茅店、月、人迹、板桥、霜），不用动词形容词，纯用意象叠加，勾勒出一幅清冷的早行图，「状难写之景如在目前」；颈联「槲叶落山路，枳花明驿墙」，写山路槲叶、驿墙枳花，继续写早行所见；尾联「因思杜陵梦，凫雁满回塘」，以昨夜梦中故乡凫雁满塘的温暖反衬早行的清冷，乡愁更深，余味悠然。",
    b: "温庭筠（晚唐诗人）这首诗写清晨离开商山（在今陕西商洛）时的所见所感，是写羁旅乡愁的千古名篇。",
    n: ["征铎：车行时的铃声。铎音duó","悲故乡：为故乡而悲","茅店：乡村客店","板桥：木板桥","槲叶：槲树的叶子。槲音hú，落叶乔木","枳花：枳树的花。枳音zhǐ，灌木或小乔木","明驿墙：照亮驿站的墙","杜陵梦：梦见杜陵（杜甫祖籍，在长安东南，此指故乡）","凫雁：野鸭和大雁。凫音fú","回塘：曲折的池塘"]
  },
  "送人东游|温庭筠": {
    s: "首联「荒戍落黄叶，浩然离故关」，以荒戍黄叶的萧瑟反衬友人浩然离去的豪迈；颔联「高风汉阳渡，初日郢门山」，写友人行程所经——汉阳渡的秋风、郢门山的初日，以地名入对，气象阔大；颈联「江上几人在，天涯孤櫂还」是名句——江上旧友还有几人在？你却要孤舟远游天涯，对故人凋零的感慨与对友人孤身的担忧交织；尾联「何当重相见，尊酒慰离颜」，以盼重逢、把酒慰别作结，深情厚谊，余味不尽。",
    b: "温庭筠这首诗写送别友人东游，表达对友人的惜别与对故人凋零的感慨。",
    n: ["荒戍：荒废的戍楼、营垒","浩然：豪迈的样子","故关：故乡的关隘","高风：秋风","汉阳渡：汉阳的渡口（在今武汉）","郢门山：荆门山（在今湖北宜昌，郢为楚都）","江上几人在：江上（指友人中）还有几人在","孤櫂：孤舟。櫂同「棹」，船桨，代指船","尊酒：一杯酒。尊同「樽」","离颜：离别后的容颜"]
  },
  "望江南·梳洗罢|温庭筠": {
    s: "全词仅二十七个字，却写尽思妇一天的等待：「梳洗罢」写她精心梳妆、满怀希望；「独倚望江楼」写她独自登楼、痴痴等待；「过尽千帆皆不是」是全词核心——上千只船都过去了，都不是丈夫的船，希望一次次破灭；「斜晖脉脉水悠悠」以夕阳含情、江水悠长写她的失望与愁思，情景交融；「肠断白蘋洲」以白蘋洲（当年送别之处）作结，愁肠寸断。短短小令，情节完整、情感跌宕，是词中精品。",
    b: "温庭筠这首《望江南》（又名《忆江南》）写思妇登楼望归、从希望到失望的全过程，是晚唐小令的千古名篇。",
    n: ["梳洗罢：梳妆完毕","望江楼：临江的楼","过尽千帆：上千只船都过去了","皆不是：都不是（丈夫所乘的船）","斜晖脉脉：夕阳含情不语。脉脉，含情相视貌，音mòmò","悠悠：悠长不尽","白蘋洲：长满白蘋的水洲（蘋，水草，古人常采以赠别）。蘋音pín"]
  },
  "生查子·二|牛希济": {
    s: "上片「新月曲如眉，未有团𪢮意。红豆不堪看，满眼相思泪」，以新月如眉、尚未团圆起兴，以红豆不堪看、满眼相思泪写相思之苦；下片「终日劈桃穰，人在心儿里」是名句——整天劈桃核，因为桃仁（「人」谐音）在核儿里，双关所爱之人在自己心里，比喻巧妙；「两朵隔墙花，早晚成连理」，以隔墙花终会连理比喻两人终会团圆，表达对爱情的坚定信念，语言朴素而情意深挚。",
    b: "牛希济（五代前蜀词人）这首《生查子》写女子对爱情的忠贞与对团圆的渴望，是五代词的名篇。",
    n: ["团𪢮：团圆。𪢮同「圞」，音luán","红豆：相思豆，象征爱情","不堪看：不忍心看","桃穰：桃核里的仁。穰同「瓤」","人在心儿里：人（所爱之人）在我心里","连理：两棵树的枝干连生在一起，喻恩爱夫妻"]
  },
  "山中|王勃": {
    s: "首两句「长江悲已滞，万里念将归」，以长江水之「滞」写自己滞留异乡之悲，以「万里」写空间之远、「将归」写归心之切，情景交融；后两句「况属高风晚，山山黄叶飞」，以秋风萧瑟、黄叶纷飞的秋景渲染乡愁，「山山」叠字写出秋意的辽阔与无处不在，以景结情，不言愁而愁自深，短短二十字，意境苍凉，是初唐五绝的精品。",
    b: "王勃（初唐四杰之首）这首小诗写在长江边滞留、秋风起时思念故乡的心情，是初唐五言绝句的名篇。",
    n: ["长江悲已滞：长江水仿佛也为我滞留而悲（滞，滞留，指自己久留异乡）","万里念将归：在万里之外思念将要归去","况属：更何况正值","高风：秋风","山山黄叶飞：座座山上黄叶纷飞"]
  },
  "新嫁娘词三首·一|王建": {
    s: "这首小诗截取新婚生活的一个有趣片段：新娘刚到婆家，邻居还不认识她，她坐在床上一动不动（堆堆），新郎来到门边，她却满口索要钱财——写的是新婚时的讨喜钱习俗，以口语化的语言、生动的细节，写出新婚生活的诙谐与热闹，朴素自然，富有民间生活气息，体现王建乐府诗善于捕捉生活细节的特色。",
    b: "王建（中唐诗人）《新嫁娘词》三首之一，写新婚次日的一个生活场景，语言口语化、富有生活气息。（注意：传诵的「三日入厨下」是其三，此为其一。）",
    n: ["堆堆：形容新娘端坐着一动不动的样子","郎来傍门户：新郎来到门边","满口索钱财：满口索要钱财（指婚礼中的讨喜钱习俗）"]
  },
  "雨过山村|王建": {
    s: "首两句「雨里鸡鸣一两家，竹溪村路板桥斜」，以鸡鸣、竹溪、村路、板桥勾勒出一幅清新的山村雨景图，「一两家」写出山村的幽静；后两句「妇姑相唤浴蚕去，闲看中庭栀子花」，写嫂嫂小姑互相呼唤着去浴蚕，庭院里只有栀子花在雨中静静开放——以人的忙碌与花的「闲」对比，写出山村农事的繁忙与生活的宁静美好，语言清新自然，充满田园气息。",
    b: "王建这首小诗写山村雨后的景象与农妇浴蚕的农事活动，是中唐田园诗的名篇。",
    n: ["雨里鸡鸣一两家：雨天里只有一两户人家的鸡鸣","竹溪村路板桥斜：竹林、溪水、村路、板桥斜横","妇姑：嫂嫂和小姑（或婆媳）","相唤：互相呼唤","浴蚕：浸洗蚕种（养蚕的准备工作）","闲看：悠闲地看着","栀子花：常绿灌木，花白色芳香，初夏开放"]
  },
  "十五夜望月寄杜郎中|王建": {
    s: "首两句「中庭地白树栖鸦，冷露无声湿桂花」，写中秋月夜的清幽——月光照地如霜、树上栖鸦、冷露无声打湿桂花，视觉、听觉、触觉交织，意境清冷幽美；后两句「今夜月明人尽望，不知秋思在谁家」是名句——中秋之夜人人都在望月，可那秋日的思念究竟落在谁家呢？以委婉的疑问写自己的思乡之情，不直说自己思家，而说「不知在谁家」，含蓄蕴藉，余味悠长，是中秋诗的绝唱。",
    b: "王建这首中秋望月诗写中秋之夜人人望月思乡的情景，是写中秋的千古名篇。",
    n: ["十五夜：农历八月十五中秋夜","杜郎中：一位杜姓郎中（官职）","地白：月光照地洁白如霜","树栖鸦：树上栖息着乌鸦","冷露：清冷的露水","湿桂花：打湿了桂花","人尽望：人人都在仰望（明月）","秋思：秋日的思念（此指中秋思乡之情）","在谁家：（那秋思）落在谁的家中呢"]
  },
  "横吹曲辞·出塞·一|王昌龄": {
    s: "首句「秦时明月汉时关」以互文手法，将明月与关隘的历史追溯到秦汉，千年的边关、千年的征战，时空感极强；次句「万里长征人未还」写征人久戍不归的悲剧，「万里」写空间之远、「未还」写时间之久；后两句「但使龙城飞将在，不教胡马度阴山」，以假设写出对良将的渴望——只要有李广那样的飞将军在，就不会让胡马越过阴山，既是对历史名将的追慕，也是对当朝将帅无能的讽刺，气势雄浑，意境苍凉，是边塞诗的巅峰之作。",
    b: "王昌龄（盛唐边塞诗人）这首《出塞》被明代李攀龙推为唐人七绝压卷之作，写边塞将士对良将的渴望与对和平的向往。",
    n: ["秦时明月汉时关：秦汉时的明月和关隘（互文，即明月和关隘自秦汉以来一直如此）","万里长征：远征万里","人未还：出征的人还没有回来","但使：只要","龙城飞将：龙城（匈奴祭天处）的飞将军李广（一说卫青曾龙城大捷）","不教：不让","胡马：胡人的战马","度阴山：越过阴山（阴山在今内蒙古，是中原与北方游牧民族的界山）"]
  },
  "相和歌辞·从军行·四|王昌龄": {
    s: "首两句「青海长云暗雪山，孤城遥望雁门关」，以青海长云、雪山暗淡、孤城遥望写边塞的荒凉与将士的孤独，境界阔大而苍凉；后两句「黄沙百战穿金甲，不破楼兰终不还」是千古名句——在黄沙中经历百战、铠甲都磨穿了，不打败敌人绝不回去，「百战」写战斗之多、「穿金甲」写战斗之苦，「终不还」写将士的坚定誓言，以艰苦的环境反衬将士的豪情，刚健豪迈，是盛唐气象的典型体现。",
    b: "王昌龄《从军行》七首之四（库文标为「四」），写边塞将士在艰苦环境中立下不破敌不还的誓言，是盛唐边塞诗的名篇。",
    n: ["青海：青海湖，在今青海","长云：层层浓云","暗雪山：使雪山（祁连山）暗淡","孤城：孤立的城池（指玉门关）","遥望：远远望去","雁门关：在今山西代县，北方要塞（通行本作「玉门关」，库文作「雁门关」）","黄沙百战：在黄沙中经历百战","穿金甲：磨穿了金属铠甲","不破楼兰：不打败楼兰（楼兰，西域古国，此泛指敌方）","终不还：终究不回去"]
  },
  "采莲曲二首·一|王昌龄": {
    s: "首两句「吴姬越艳楚王妃，争弄莲舟水湿衣」，以吴姬越艳楚王妃形容采莲女的美丽，写她们争着划莲船、水打湿衣裳的欢快，活泼生动；后两句「来时浦口花迎入，采罢江头月送归」是名句——来时渡口的荷花迎接她们进入，采完莲后江边的月亮送她们归去，以花迎月送的拟人手法写采莲生活的美好，人与自然融为一体，意境清新优美，语言明丽自然，是王昌龄七绝的清新之作。",
    b: "王昌龄这首《采莲曲》写江南采莲女的美丽与采莲生活的欢快，是盛唐山水田园诗的清新之作。",
    n: ["吴姬越艳楚王妃：吴地的美女、越地的艳女、楚王的妃嫔（形容采莲女之美）","争弄莲舟：争着划动采莲船","水湿衣：水打湿了衣裳","浦口：水边、渡口","花迎入：荷花迎接（采莲女）进入","采罢：采完莲","江头：江边","月送归：月亮送（采莲女）归去"]
  },
  "春宫曲|王昌龄": {
    s: "首两句「昨夜风开露井桃，未央前殿月轮高」，以春风吹开井边桃花、未央前殿月轮高悬写宫廷春夜的美好，「昨夜」点明时间；后两句「平阳歌舞新承宠，帘外春寒赐锦袍」，以平阳歌舞（卫子夫故事）写宫女新近受宠，皇帝因帘外春寒赐给她锦袍——全诗不写失宠者的怨，只写得宠者的荣，以他人之宠反衬自己之失，含蓄蕴藉，怨而不怒，是宫怨诗的高妙之作。",
    b: "王昌龄这首《春宫曲》写宫女新承宠的情景，以他人得宠反衬自己失宠，是宫怨诗的含蓄之作。",
    n: ["风开露井桃：春风吹开了井边的桃花。露井，没有井亭覆盖的井","未央：未央宫，汉代宫殿，此指唐宫","前殿：宫殿的前殿","月轮高：月亮高高升起","平阳：平阳公主（汉武帝的姐姐，其家歌女卫子夫后为皇后，此以平阳歌舞指宫女）","新承宠：新近受到宠爱","帘外春寒：帘外春寒料峭","赐锦袍：（皇帝）赐给锦袍"]
  },
  "西宫春怨|王昌龄": {
    s: "首两句「西宫夜静百花香，欲卷珠帘春恨长」，写西宫夜静、百花飘香，宫女想卷珠帘却因春恨悠长而作罢，「欲卷」与「不卷」的矛盾写尽她的犹豫与愁闷；后两句「斜抱云和深见月，朦胧树色隐昭阳」是名句——她斜抱着琴瑟、深深望着月亮，朦胧的树色遮蔽了昭阳宫（君王所在之处），以「斜抱」「深见」的动作写她的痴情与失望，以树色隐昭阳写她见不到君王的惆怅，情景交融，含蓄不尽，是宫怨诗的精品。",
    b: "王昌龄这首《西宫春怨》写失宠宫女在西宫春夜抱琴望月、思念君王的情景，是宫怨诗的名篇。",
    n: ["西宫：西边的宫殿（失宠宫女所居）","百花香：百花飘香","珠帘：珍珠串成的帘子","春恨长：春愁悠长","斜抱：斜抱着","云和：云和（地名，产琴瑟，此代指琴瑟）","深见月：（透过帘子）深深看见月亮","朦胧树色：朦胧的树影","隐昭阳：遮蔽了昭阳宫（昭阳宫是得宠妃子所居，汉成帝时赵飞燕居昭阳宫）"]
  },
  "长信秋词五首·一|王昌龄": {
    s: "首两句「金井梧桐秋叶黄，珠帘不卷夜来霜」，以金井梧桐、秋叶黄、夜来霜写长信宫秋夜的清冷，「珠帘不卷」写宫女的孤寂无心；后两句「熏笼玉枕无颜色，卧听南宫清漏长」是名句——熏笼玉枕都失去了光彩（暗指主人公的孤寂憔悴），她躺着听南宫（君王所在）传来的清晰漏声，一夜漫长，以「无颜色」写物之冷、以「清漏长」写夜之长，失宠之苦尽在其中，含蓄凄清，是宫怨诗的典范。",
    b: "王昌龄《长信秋词》五首之一（库文标为「一」），写失宠宫女在长信宫秋夜的孤寂，是宫怨诗的名篇。（长信宫用汉代班婕妤失宠后居长信宫的典故。）",
    n: ["金井：井栏有金属装饰的井","秋叶黄：秋天的梧桐叶黄了","珠帘不卷：珍珠帘子不卷起来","夜来霜：夜里下了霜","熏笼：熏香用的竹笼（取暖熏香用）","玉枕：玉制的枕头","无颜色：没有光彩（暗指主人公孤寂）","卧听：躺着听","南宫：南面的宫殿（君王/得宠者所居）","清漏长：清晰的漏壶声悠长（漏壶，古代计时工具）"]
  },
  "青楼曲二首·一|王昌龄": {
    s: "首两句「白马金鞍从武皇，旌旗十万宿长杨」，写丈夫白马金鞍随从皇帝狩猎、十万旌旗驻扎长杨，场面盛大，气象雄浑；后两句「楼头小妇鸣筝坐，遥见飞尘入建章」是名句——少妇在楼上弹着筝，远远望见飞扬的尘土进入建章宫（知道丈夫归来了），以少妇的悠闲与丈夫的荣耀对比，写出盛唐时期将士的荣耀与家庭的和乐，视角独特，气象开阔，是王昌龄七绝的别致之作。",
    b: "王昌龄这首《青楼曲》写少妇在楼上望见丈夫随从皇帝狩猎归来的情景，以少妇的视角写盛唐气象，是边塞/宫廷诗的别致之作。",
    n: ["白马金鞍：白马配金鞍","从武皇：跟随汉武帝（此指唐玄宗）","旌旗十万：十万大军的旌旗","宿长杨：驻扎在长杨宫（长杨宫，汉代行宫，在今陕西周至，汉武帝曾在此狩猎）","楼头小妇：楼上的少妇","鸣筝：弹筝","飞尘：飞扬的尘土","建章：建章宫（汉代宫殿，此指唐宫）"]
  },
  "闺怨|王昌龄": {
    s: "首两句「闺中少妇不曾愁，春日凝妆上翠楼」，写少妇本来没有忧愁，春日精心梳妆登上翠楼，「不曾愁」为后文的「悔」作铺垫；后两句「忽见陌头杨柳色，悔教夫婿觅封侯」是千古名句——她忽然看见路边的杨柳春色，顿时后悔让丈夫去从军觅封侯了，「忽见」写心理转变的突然，「悔」字写尽少妇对丈夫的思念与对功名的反思，柳色既写春景，又暗含「折柳送别」的回忆，以乐景写哀，心理刻画细腻入微，是七绝中的精品。",
    b: "王昌龄这首《闺怨》写少妇春日登楼、忽见杨柳春色而后悔让丈夫从军觅封侯的心理变化，是写闺怨的千古名篇。",
    n: ["闺中少妇：闺房中的年轻妻子","不曾愁：从来没有忧愁","凝妆：精心梳妆打扮","翠楼：华美的楼","陌头：路边","杨柳色：杨柳的春色","悔教：后悔让","夫婿：丈夫","觅封侯：去寻求封侯（指从军建功立业）"]
  },
  "听流人水调子|王昌龄": {
    s: "首两句「孤舟微月对枫林，分付鸣筝与客心」，以孤舟、微月、枫林写环境的凄清，写弹筝人将一腔心事托付给筝声、打动了游子的心；后两句「岭色千重万重雨，断弦收与泪痕深」是名句——山岭的景色在层层雨幕中朦胧不清，弹筝人弹断了琴弦、收起来时泪痕已深，以「千重万重雨」写环境的凄迷、以「断弦」「泪痕深」写弹筝人的悲苦，音乐、景色、身世融为一体，凄婉动人，是王昌龄七绝的深沉之作。",
    b: "王昌龄这首诗写在孤舟微月中听流落艺人弹《水调子》、为其凄苦身世感动的情景，是写音乐与身世的名篇。",
    n: ["流人：流落江湖的人（此指弹筝的艺人）","水调子：即《水调歌》，曲调名，声情凄苦","分付：托付、交给","鸣筝：弹筝","客心：游子的心","岭色：山岭的景色","千重万重：层层叠叠","断弦：弹断了琴弦","收与：收起来给","泪痕深：泪痕很深"]
  },
  "野望|王绩": {
    s: "首联「东皋薄暮望，徙倚欲何依」，写傍晚在东皋眺望、徘徊无依，「欲何依」用曹操典故写孤独；颔联「树树皆秋色，山山唯落晖」是名句——树树秋色、山山落晖，以「树树」「山山」叠字写秋景的辽阔与萧瑟，意境开阔；颈联「牧人驱犊返，猎马带禽归」，写牧人猎人傍晚归来，以人的活动反衬自己的孤独；尾联「相顾无相识，长歌怀采薇」，写与众人互不相识，只能长歌怀念伯夷叔齐，表达隐居不仕的志向，孤独中见清高，是初唐律诗的奠基之作。",
    b: "王绩（初唐诗人，自号东皋子）这首《野望》写傍晚在东皋眺望所见的秋景与孤独的心境，是初唐五言律诗的成熟之作，也是现存最早的五言律诗之一。",
    n: ["东皋：东边的高地（王绩隐居处，在今山西河津）。皋音gāo","薄暮：傍晚","徙倚：徘徊、来回走。徙音xǐ","欲何依：想要依靠什么呢（用曹操「绕树三匝，何枝可依」意，写孤独无依）","树树皆秋色：每棵树都呈现秋天的颜色","山山唯落晖：每座山都只有落日的余晖","牧人驱犊返：牧人赶着牛犊回来。犊音dú，小牛","猎马带禽归：猎人骑着马带着猎物回来","相顾无相识：互相看看都不认识","长歌怀采薇：长声歌唱、怀念采薇而食的伯夷叔齐（采薇，代指隐居不仕）"]
  },
  "春中田园作|王维": {
    s: "首联以春鸠鸣、杏花白写春日田园的明丽，视听结合；颔联写农人持斧伐桑、荷锄看泉，农事繁忙而有序；颈联写归燕识巢、旧人看新历，以燕子的恋旧与人的迎新写岁月流转；尾联「临觞忽不御，惆怅远行客」陡然一转，端杯不饮、惆怅远行，由田园之乐转入对漂泊者的同情，乐中含悲，余味悠然。",
    b: "王维这首诗写春日田园的生机与农忙，结尾由乐景转入对远行客的惆怅，是其田园诗的名篇。",
    n: ["春鸠：春天的斑鸠","伐远扬：砍掉过长高扬的桑枝（为了让桑树长得更好）","荷锄觇泉脉：扛着锄头察看泉水的脉络。觇音chān，察看","归燕识故巢：归来的燕子认得旧巢","新历：新的历书","临觞忽不御：端起酒杯忽然又不饮了。觞，酒杯；御，进、用","远行客：远行在外的人（诗人自指，或指思念的远行之人）"]
  },
  "新晴野望|王维": {
    s: "首联「新晴原野旷，极目无氛垢」总写雨后初晴、原野开阔、一尘不染；颔联写郭门临渡、村树连溪，层次分明；颈联「白水明田外，碧峰出山后」是名句——田外白水闪亮、山后碧峰显现，「明」「出」二字极炼，以动写静，色彩明丽；尾联写农月无闲人、倾家事南亩，以人的忙碌反衬田园的生机，画面开阔而充满生活气息，是王维「诗中有画」的典范。",
    b: "王维这首诗写雨后初晴眺望原野所见的明丽景色与农忙景象，是其山水田园诗的名篇。",
    n: ["新晴：雨后初晴","原野旷：原野开阔","极目无氛垢：放眼望去没有尘埃。氛垢，尘埃","郭门：外城的门","谿口：溪水的入口。谿同「溪」","白水明田外：田埂外白水闪亮","碧峰出山后：青山从山后显现","农月：农忙月份","倾家事南亩：全家都到田里耕作。南亩，田地"]
  },
  "辋川闲居赠裴秀才迪|王维": {
    s: "首联「寒山转苍翠，秋水日潺湲」写寒山由苍转翠、秋水日日潺湲，色彩与声音交织；颔联「倚杖柴门外，临风听暮蝉」写诗人拄杖柴门、临风听蝉，神态悠然；颈联「渡头余落日，墟里上孤烟」是千古名句——渡口边还留着落日的余晖，村落里升起一缕炊烟，以「余」「上」二字写尽黄昏的宁静与温暖，是「诗中有画」的典范；尾联以接舆比裴迪、以五柳自比，写两人的醉歌闲逸，物我两忘，意境清远。",
    b: "王维晚年隐居辋川时，与好友裴迪唱和，这首诗写秋日傍晚辋川的清幽景色与两人的闲逸生活，是山水田园诗的千古名篇。",
    n: ["辋川：王维在陕西蓝田的辋川别业","裴秀才迪：裴迪，王维的好友，秀才是对读书人的称呼","苍翠：青绿","潺湲：水缓慢流动的样子。音chányuán","倚杖：拄着拐杖","暮蝉：秋蝉","渡头：渡口","墟里：村落","孤烟：一缕炊烟","复值：又遇到","接舆：春秋楚国隐士接舆，此指裴迪（以隐士比之）","五柳：五柳先生陶渊明，此指王维自己（以隐士自比）"]
  },
  "酬张少府|王维": {
    s: "首联「晚年唯好静，万事不关心」直抒胸臆，写晚年心境；颔联「自顾无长策，空知返旧林」自谦没有治国长策，只知归隐山林，含自嘲；颈联「松风吹解带，山月照弹琴」是名句——松风吹动解开的衣带、山月照着弹琴的身影，以松风、山月写归隐生活的自在，画面清幽；尾联「君问穷通理，渔歌入浦深」以景结情——你问我穷通的道理，你听那渔歌已飘入浦水深处了，不答而答，含蓄蕴藉，禅意悠然。",
    b: "王维晚年隐居辋川时，酬答友人张少府的诗，写自己晚年好静、万事不关心的归隐生活与人生态度，是山水田园诗的名篇。",
    n: ["张少府：姓张的县尉（少府是县尉的尊称）","长策：长远的计策、治国之策","返旧林：回到旧日的山林（指归隐）","解带：解开衣带（指放松、不拘束）","穷通理：困窘与显达的道理（穷，不得志；通，得志）","渔歌入浦深：渔歌声飘入了水浦深处（浦，水边）"]
  },
  "送梓州李使君|王维": {
    s: "首联「万壑树参天，千山响杜鹃」以夸张写蜀地山川的雄奇——万壑树参天、千山杜鹃啼，视听结合，气势磅礴；颔联「山中一夜雨，树杪百重泉」是名句——山中一夜雨后，树梢上挂着百重泉水，以「树杪」写山之高、以「百重」写泉之多，想象奇特；颈联写汉女输橦布、巴人讼芋田，写蜀地的风土民情；尾联用文翁兴学的典故勉励友人，「不敢倚先贤」既是赞美也是期许，送别诗中见格调，气象开阔。",
    b: "王维送友人李使君赴任梓州时所作，写蜀地山川的雄奇与风土，勉励友人效法文翁、兴学教化，是送别诗的名篇。",
    n: ["梓州：今四川三台一带","李使君：姓李的州刺史（使君是对州郡长官的尊称）","万壑树参天：千万道山谷里树木参天","树杪百重泉：树梢上挂着百重泉水（写山高泉多）。杪音miǎo，树梢","汉女输橦布：汉地女子缴纳橦布（橦布，橦花织的布，古代赋税）。橦音tóng","巴人讼芋田：巴地人为芋田打官司","文翁翻教授：文翁反而兴办教育（文翁，西汉蜀郡太守，兴学校、教化蜀地）","不敢倚先贤：不敢倚仗先贤（指李使君会超过文翁，不只是倚仗先贤的政绩）"]
  },
  "过香积寺|王维": {
    s: "首联「不知香积寺，数里入云峰」写不知寺在何处、数里已入云峰，以「不知」「入」写探访的兴致与山的幽深；颔联「古木无人迳，深山何处钟」写古木参天、无人小径，深山里不知何处传来钟声，以钟声写山之幽；颈联「泉声咽危石，日色冷青松」是千古名句——泉声在危石间呜咽、日色使青松显得清冷，「咽」「冷」二字极炼，以通感手法写尽山中的幽寂清冷；尾联「薄暮空潭曲，安禅制毒龙」写傍晚在空潭边、僧人安禅降伏毒龙，以禅理作结，意境幽远，禅意盎然。",
    b: "王维这首诗写探访香积寺途中所见的清幽景色与禅意，是山水诗与禅理结合的名篇。",
    n: ["香积寺：在今陕西长安县南，唐代著名寺院","云峰：云雾缭绕的山峰","古木无人迳：古木参天、没有人走的小路。迳同「径」","咽危石：（泉声）在高耸的岩石间呜咽。咽，呜咽，音yè","冷青松：（日色）使青松显得清冷","薄暮：傍晚","空潭曲：空潭的曲折处","安禅制毒龙：安心打坐、降伏毒龙（安禅，佛教语，安心打坐；毒龙，佛教比喻妄念烦恼）"]
  },
  "皇甫岳云溪杂题五首·鸟鸣涧|王维": {
    s: "首两句「人闲桂花落，夜静春山空」写人心闲静、桂花飘落，夜静山空，以「桂花落」的微动写夜的静；后两句「月出惊山鸟，时鸣春涧中」是名句——月亮升起惊动了山中的鸟，它们不时在春涧中鸣叫，以鸟鸣的动写山涧的静，以动衬静，动静相生，短短二十字写尽春夜山涧的幽静空灵，「诗中有画，画中有诗」。",
    b: "王维《皇甫岳云溪杂题》之一，写春夜山涧的幽静，以动衬静，是山水小诗的千古名篇。",
    n: ["鸟鸣涧：鸟鸣叫的山涧（王维辋川别业附近的景点）","人闲：人心闲静","桂花落：桂花飘落","春山空：春天的山谷空寂","月出：月亮升起","惊山鸟：惊动了山中的鸟","时鸣：不时地鸣叫","春涧中：春天的山涧中"]
  },
  "田园乐七首·一|王维": {
    s: "这首六言诗以对比手法写心境：「厌见千门万户，经过北里南邻」写看厌了都市的繁华、喜欢经过乡村邻里，一厌一喜，态度鲜明；「官府鸣珂有底，崆峒散髪何人」写官府里官员出行鸣珂有什么意思，崆峒山散发隐居的是什么人，以反问写对官场的厌弃与对隐居的向往，六言句式整齐，节奏明快，语言朴素而意境清远，是王维田园诗的别致之作。",
    b: "王维《田园乐》七首之一，六言诗，写厌弃官场、向往隐居的心情，是六言诗的名篇。",
    n: ["田园乐：写田园生活的乐趣（组诗七首，此为其一，六言诗）","厌见千门万户：看厌了都市的千门万户（指官场都市）","经过北里南邻：经过北里南邻（指乡村邻里）","官府鸣珂有底：官府里鸣珂（马笼头上的玉饰，指官员出行）有什么意思呢。有底，有什么意思","崆峒散髪何人：在崆峒山散发（指隐居）的是什么人呢。散髪，散发，指不受拘束、隐居。髪同「发」"]
  },
  "少年行四首·一|王维": {
    s: "首两句「新丰美酒斗十千，咸阳游侠多少年」以美酒的名贵写少年游侠的豪奢，「斗十千」化用曹植「美酒斗十千」；后两句「相逢意气为君饮，系马高楼垂柳边」是名句——少年相逢、意气相投、为君痛饮，把马系在高楼垂柳边，以「意气」写少年的豪情、以「系马」写场景的生动，短短二十字写尽盛唐少年游侠的英风豪气，画面感极强，是王维七绝中的豪放之作。",
    b: "王维《少年行》四首之一，写长安少年游侠意气相投、纵酒豪饮的风采，是盛唐气象的典型体现。",
    n: ["少年行：写少年游侠的诗（组诗四首，此为其一）","新丰：今陕西临潼，产美酒","斗十千：一斗酒值十千钱（极言酒美价高）","咸阳：秦都，此指唐都长安","游侠：游历任侠的少年","相逢意气为君饮：相逢后意气相投、为君痛饮","系马高楼垂柳边：把马系在高楼边的垂柳下"]
  },
  "伊州歌|王维": {
    s: "首两句「清风明月苦相思，荡子从戎十载余」以清风明月写思妇的孤独，以「十载余」写丈夫从军之久，苦相思之情溢于言表；后两句「征人去日殷勤嘱，归雁来时数附书」是名句——不写思妇如何思念，而写回忆丈夫出征时殷勤嘱咐「大雁归来时多多捎信」，以丈夫的嘱咐反衬思妇的等待，以叮嘱的殷勤写离别的深情，含蓄蕴藉，余味悠长，是王维七绝中的深情之作。",
    b: "王维这首诗写少妇思念从军多年的丈夫，回忆丈夫出征时的嘱咐，是闺怨诗的名篇。",
    n: ["伊州歌：乐府曲调名（伊州，今新疆哈密一带）","荡子：在外游荡的丈夫（荡子，指远行不归的人）","从戎：从军","十载余：十多年了","征人去日殷勤嘱：丈夫出征时殷勤嘱咐（我）","归雁来时数附书：大雁归来时多多捎信来。数音shuò，屡次；附书，捎信"]
  },
  "白鹿洞二首·一|王贞白": {
    s: "首两句「读书不觉已春深，一寸光阴一寸金」写读书入迷、不知不觉春意已深，以「一寸光阴一寸金」的比喻写光阴的珍贵，成为千古传诵的成语；后两句「不是道人来引笑，周情孔思正追寻」写如果不是道士来逗笑，自己正在深入研读周公孔子的思想，以「周情孔思」写读书的内容与深度，全诗语言朴素而道理深刻，是劝学诗的名篇。",
    b: "王贞白（唐末诗人）在庐山白鹿洞读书时所作，写读书的勤奋与对光阴的珍惜，「一寸光阴一寸金」成为千古名句。",
    n: ["白鹿洞：在今江西庐山，王贞白（唐末诗人）读书处","春深：春意已深","一寸光阴一寸金：一寸光阴如一寸黄金般珍贵（成语出处）","道人：指白鹿洞的道士","引笑：逗笑、开玩笑","周情孔思：周公的情操、孔子的思想（指儒家经典的研读）","正追寻：正在深入追寻研读"]
  },
  "登鹳雀楼|畅当": {
    s: "首两句「迥临飞鸟上，高出世尘间」以夸张写鹳雀楼之高——高过飞鸟、高出尘世，以「迥临」「高出」写楼的雄伟；后两句「天势围平野，河流入断山」是名句——天空围裹着平旷的原野、黄河流入断裂的山间，以「围」「入」二字写天地的辽阔与黄河的气势，画面壮阔，意境雄浑，与王之涣「白日依山尽，黄河入海流」异曲同工，是写鹳雀楼的名作。",
    b: "畅当（中唐诗人）这首《登鹳雀楼》写登楼所见的壮阔景色，与王之涣同题诗齐名，是盛唐山水诗的名篇。",
    n: ["鹳雀楼：在今山西永济，黄河边的名楼","迥临飞鸟上：高高地临于飞鸟之上。迥音jiǒng，高远","高出世尘间：高出于尘世之外","天势围平野：天空的形势围裹着平旷的原野","河流入断山：黄河流入断裂的山间"]
  },
  "夜雪|白居易": {
    s: "首两句「已讶衾枕冷，复见窗户明」以触觉（衾枕冷）和视觉（窗户明）写夜雪，不直接写雪而雪自见；后两句「夜深知雪重，时闻折竹声」是名句——夜深时知道雪下得大，因为不时听到竹子被雪压断的声音，以听觉（折竹声）写雪之重，以声衬静，全诗从触觉、视觉、听觉三个角度写夜雪，句句写雪而不见「雪」字（除「知雪重」外），构思巧妙，意境清冷，是白居易小诗中的精品。",
    b: "白居易这首《夜雪》写夜间下雪的感受，以触觉、视觉、听觉多角度写夜雪，是咏雪小诗的名篇。",
    n: ["已讶衾枕冷：已经惊讶被子枕头的冰冷。讶，惊讶；衾，被子","复见窗户明：又看见窗户被（雪光）映亮","夜深知雪重：夜深时知道雪下得大","时闻折竹声：不时听到竹子被雪压断的声音"]
  },
  "邯郸冬至夜思家|白居易": {
    s: "首两句「邯郸驿里逢冬至，抱膝灯前影伴身」写冬至夜在驿站、抱膝灯前、只有影子相伴，以「抱膝」「影伴身」写尽孤独；后两句「想得家中夜深坐，还应说着远行人」是名句——不直接写自己思乡，而想象家人深夜坐着、在说着远行的自己，以对方的思念写自己的思念，「对写法」含蓄深沉，「说着远行人」平淡中见深情，是白居易七绝中的深情之作。",
    b: "白居易这首诗写冬至夜在邯郸驿站思念家人，以想象家人思念自己来写自己的思乡，是思乡诗的千古名篇。",
    n: ["邯郸：今河北邯郸","驿：驿站","冬至：二十四节气之一，古代重要节日，家人团聚","抱膝：抱着膝盖（写孤独）","影伴身：只有影子陪伴自己","想得家中夜深坐：想象家中人深夜坐着（思念自己）","还应说着远行人：还应该在说着远行的人（指自己）"]
  },
  "同李十一醉忆元九|白居易": {
    s: "首两句「花时同醉破春愁，醉折花枝当酒筹」写春天与李十一同醉、折花枝当酒筹，写醉酒的欢乐；后两句「忽忆故人天际去，计程今日到凉州」是名句——正醉酒时忽然想起元稹已去了天边，计算他的行程今天应该到了凉州，以「忽忆」写友情的深切、以「计程」写思念的细致，乐景中转入对友人的思念，真情流露，是白居易写友情的名作。",
    b: "白居易与好友李十一醉酒时忽然想起被贬的元稹，计算他今日行程，是写友情的名篇。",
    n: ["李十一：李杓直，排行十一，白居易的好友","元九：元稹，排行九，白居易的挚友","花时：花开时节（指春天）","同醉破春愁：一同醉酒消解春愁","醉折花枝当酒筹：醉后折花枝当酒筹（酒筹，饮酒时计数的筹码）","忽忆故人天际去：忽然想起老友已去了天边（指元稹被贬江陵）","计程今日到凉州：计算路程今天应该到了凉州（今甘肃武威）"]
  },
  "村夜|白居易": {
    s: "首两句「霜草苍苍虫切切，村南村北行人绝」写秋夜乡村的萧瑟——霜草灰白、虫声细碎、没有行人，色调清冷；后两句「独出前门望野田，月明荞麦花如雪」是名句——独自走出前门望田野，明月下荞麦花像雪一样白，以「月明」「花如雪」写田野的明丽，由萧瑟转为明丽，由清冷转为温暖，对比鲜明，画面清新，是白居易写景小诗中的佳作。",
    b: "白居易这首诗写乡村夜晚的景色，由萧瑟转为明丽，是写景小诗的名篇。",
    n: ["霜草苍苍：经霜的草灰白一片。苍苍，灰白色","虫切切：虫声细碎。切切，细碎的声音","行人绝：没有行人","前门：前门（一作「前村」）","野田：田野","荞麦：一种农作物，开白花","花如雪：花像雪一样白"]
  },
  "蓝桥驿见元九诗|白居易": {
    s: "首两句「蓝桥春雪君归日，秦岭秋风我去时」以对比写两人的行踪——你春天归来时蓝桥春雪，我秋天离去时秦岭秋风，一春一秋、一归一去，对比中见友情；后两句「每到驿亭先下马，循墙绕柱觅君诗」是名句——每到驿站先下马，沿着墙绕着柱子寻找你的诗，以「先下马」「循墙绕柱」的细节写对友人的深情，动作细致、情感真挚，是白居易写友情的名作。",
    b: "白居易被贬江州途中经过蓝桥驿，看到好友元稹题的诗，写下这首诗，写对友人的深情，是写友情的名篇。",
    n: ["蓝桥驿：在今陕西蓝田蓝桥，是长安通往东南的要道驿站","元九诗：元稹的诗（元稹曾在蓝桥驿题诗）","君归日：你（元稹）归来的日子","秦岭：在今陕西，长安南面的山脉","我去时：我（白居易）去（贬江州）的时候","驿亭：驿站的亭子","循墙绕柱：沿着墙、绕着柱子","觅君诗：寻找你的诗"]
  },
  "大林寺桃花|白居易": {
    s: "首两句「人间四月芳菲尽，山寺桃花始盛开」以对比写山上山下的物候差异——人间四月百花已谢，山寺桃花才盛开，「尽」与「始」对比鲜明；后两句「长恨春归无觅处，不知转入此中来」是名句——常常遗憾春天归去无处寻找，不知道春天转到这山中来来了，以拟人手法写春天的顽皮，以惊喜写发现山中春色的喜悦，构思巧妙，语言明快，是白居易七绝中的精品。",
    b: "白居易元和十二年（817）游庐山大林寺时所作，写山上桃花晚开的惊喜，是写景小诗的千古名篇。",
    n: ["大林寺：在今江西庐山","芳菲尽：百花都凋谢了。芳菲，花草的芳香，代指花","山寺桃花始盛开：山上寺庙里的桃花才盛开","长恨春归无觅处：常常遗憾春天归去无处寻找","不知转入此中来：不知道春天转到这山中来来了"]
  },
  "遗爱寺|白居易": {
    s: "首两句「弄日临谿坐，寻花绕寺行」写诗人的活动——临溪坐玩日光、绕寺行寻花朵，以「弄」「寻」写游兴之浓；后两句「时时闻鸟语，处处是泉声」是名句——不时听到鸟鸣、到处都是泉声，以「时时」「处处」写鸟声泉声的无处不在，以听觉写寺中的清幽与生机，全诗动静结合、视听交织，语言朴素而意境清新，是白居易写景小诗的佳作。",
    b: "白居易游庐山遗爱寺时所作，写寺中的鸟语泉声，是写景小诗的清新之作。",
    n: ["遗爱寺：在今江西庐山，白居易曾游","弄日临谿坐：面对溪水坐着玩赏日光。谿同「溪」","寻花绕寺行：绕着寺庙行走寻找花朵","时时闻鸟语：不时听到鸟的鸣叫","处处是泉声：到处都是泉水的声音"]
  },
  "问刘十九|白居易": {
    s: "首两句「绿螘新醅酒，红泥小火垆」以「绿」「红」的色彩写新酒与火炉的温暖，画面温馨；后两句「晚来天欲雪，能饮一杯无」是名句——傍晚天要下雪了，能来喝一杯吗，以问句写邀请，以「天欲雪」的寒冷反衬饮酒的温暖，语言朴素如话，而友情深厚、意境温暖，是白居易七绝中的神品，「能饮一杯无」成为千古名句。",
    b: "白居易晚年在洛阳时，邀请友人刘十九来饮酒所作，以极朴素的语言写极深厚的友情，是千古传诵的友情小诗。",
    n: ["刘十九：刘轲（一说刘十九是白居易的友人，排行十九）","绿螘新醅酒：新酿的酒上浮着绿色的泡沫。螘同「蚁」，酒面上的泡沫；醅音pēi，未过滤的酒","红泥小火垆：红泥做的小火炉。垆同「炉」","晚来天欲雪：傍晚天要下雪了","能饮一杯无：能来喝一杯吗。无，语气词，吗"]
  },
  "白云泉|白居易": {
    s: "首句「天平山上白云泉」点题；次句「云自无心水自闲」是名句——云自由自在、水悠闲自得，以「无心」「自闲」写云水的自在，也是诗人向往的境界；后两句「何必奔冲山下去，更添波浪向人间」以反问写何必奔涌下山、给人间增添波浪，以水的奔冲比喻在官场惹是非，托物言志，表达对官场的厌倦与对闲适的向往，语言明快而寓意深刻，是白居易七绝中的哲理之作。",
    b: "白居易任苏州刺史时游天平山白云泉所作，借云水的自在表达对官场的厌倦与对闲适的向往，是托物言志的名篇。",
    n: ["白云泉：在今江苏苏州天平山","云自无心水自闲：云自由自在、水悠闲自得","奔冲：奔涌冲撞","更添波浪向人间：又给人间增添波浪（比喻在人间惹是非）"]
  },
  "采莲子·一|皇甫松": {
    s: "首两句「菡萏香连十顷陂，小姑贪戏采莲迟」写十顷荷塘荷花飘香、小姑娘贪玩采莲采晚了，以「贪戏」写姑娘的天真；后两句「晚来弄水船头湿，更脱红裙裹鸭儿」是名句——傍晚玩水把船头弄湿了，又脱下红裙子裹小鸭儿，以「脱红裙裹鸭儿」的细节写姑娘的天真活泼，画面生动、情趣盎然，语言朴素而富有生活气息，是花间词中别具一格的作品。",
    b: "皇甫松（唐五代词人）这首《采莲子》写采莲姑娘的天真活泼，是花间词中富有生活气息的作品。",
    n: ["采莲子：乐府曲调名，写采莲生活（此为皇甫松所作，唐五代词人）","菡萏：荷花。音hàndàn","十顷陂：十顷的池塘。陂音bēi，池塘","小姑：年轻的姑娘","贪戏采莲迟：贪玩采莲采得晚了","弄水船头湿：玩水把船头弄湿了","更脱红裙裹鸭儿：又脱下红裙子裹小鸭儿"]
  },
  "寻陆鸿渐不遇|皎然": {
    s: "首联「移家虽带郭，野径入桑麻」写陆羽的新家虽近城郭，但野径通入桑麻，环境清幽；颔联「近种篱边菊，秋来未着花」写篱边种菊、秋来未开，以菊花写陆羽的高洁；颈联「扣门无犬吠，欲去问西家」写敲门无狗叫、欲去问邻居，写不遇的过程；尾联「报道山中去，归时每日斜」是名句——邻居回答说陆羽到山中去了，每天回来时太阳都西斜了，以邻居的回答写陆羽的闲适与爱山，不遇中见其人，意境清远，是寻访诗的佳作。",
    b: "皎然（唐代诗僧）寻访好友陆羽不遇时所作，写陆羽的隐居生活与寻访不遇的惆怅，是寻访诗的名篇。",
    n: ["陆鸿渐：陆羽，字鸿渐，茶圣，皎然的好友","移家虽带郭：搬家虽然靠近城郭。带郭，靠近城郭","野径入桑麻：野外的小路通入桑麻地","近种篱边菊：近来在篱笆边种了菊花","秋来未着花：秋天来了还没开花","扣门无犬吠：敲门没有狗叫","欲去问西家：想要离去又问西边的邻居","报道山中去：（邻居）回答说（陆羽）到山中去了","归时每日斜：回来时每天太阳都西斜了"]
  },
  "汴河怀古二首·一|皮日休": {
    s: "首两句「万艘龙舸绿丝间，载到扬州尽不还」写隋炀帝乘万艘龙船南巡、一去不返，以「尽不还」写隋亡的结局；后两句「应是天教开汴水，一千余里地无山」是名句——应该是上天让开凿汴河，一千多里地没有山，以「天教开汴水」的反语写运河开凿的历史必然性，以「地无山」写运河的地理条件，表面赞美实则讽刺，构思独特，是咏史诗中的别致之作。（同题第二首「尽道隋亡为此河，至今千里赖通波」更为传诵。）",
    b: "皮日休（晚唐诗人）这首《汴河怀古》写隋炀帝开凿大运河的历史功过，以独特视角评价隋炀帝，是咏史诗的名篇。",
    n: ["汴河：通济渠，隋炀帝开凿的大运河一段","万艘龙舸：万艘龙船（舸，大船）。舸音gě","绿丝间：在绿柳之间","载到扬州尽不还：运到扬州都不回来了（指隋炀帝南巡江都不返）","应是天教开汴水：应该是上天让开凿汴河","一千余里地无山：一千多里地没有山（指运河开凿的地势平坦）"]
  },
  "终南望余雪|祖咏": {
    s: "首两句「终南阴岭秀，积雪浮云端」写终南山北岭的秀丽、积雪好像浮在云端，以「浮云端」写山之高、雪之厚；后两句「林表明霁色，城中增暮寒」是名句——树林顶端呈现初晴的光色、城中增添了傍晚的寒意，以「林表」的明丽与「城中」的寒冷对比，以望雪而生寒，写尽雪后初晴的清冷，全诗意境清新、语言精炼，是咏雪诗的名篇，「意尽而止」成为诗坛佳话。",
    b: "祖咏（盛唐诗人）这首《终南望余雪》写从长安望终南山雪后的景色，是咏雪诗的名篇，据说这是应试诗，祖咏只写了四句就交卷，说「意尽」。",
    n: ["终南：终南山，在今陕西西安南","阴岭：北面的山岭（山北为阴）","秀：秀丽","积雪浮云端：积雪好像浮在云端","林表明霁色：树林顶端呈现出雨后初晴的光色。霁色，雨后初晴的景色","城中增暮寒：城中增添了傍晚的寒意"]
  },
  "自遣|罗隐": {
    s: "首两句「得即高歌失即休，多愁多恨亦悠悠」写得意高歌、失意罢休，多愁多恨也悠悠然，表面旷达实则愤激；后两句「今朝有酒今朝醉，明日愁来明日愁」是名句——今天有酒今天醉、明天有愁明天愁，以「今朝」「明日」的重复写及时行乐的颓废，以旷达写失意，以颓废写愤激，语言明快而情感深沉，是晚唐诗歌的代表作，「今朝有酒今朝醉」成为流传千古的成语。",
    b: "罗隐（晚唐诗人）这首《自遣》写失意后的旷达与愤激，「今朝有酒今朝醉」成为千古名句，是晚唐颓废气的典型体现。",
    n: ["自遣：自我排遣","得即高歌失即休：得意时就高歌、失意时就罢休","多愁多恨亦悠悠：多愁多恨也悠悠然（不放在心上）","今朝有酒今朝醉：今天有酒今天就喝醉","明日愁来明日愁：明天有愁明天再愁"]
  },
  "正月十五夜|苏味道": {
    s: "首联「火树银花合，星桥铁锁开」写元宵夜灯火辉煌、开禁夜行，「火树银花」成为千古成语；颔联「暗尘随马去，明月逐人来」写游人骑马、尘土飞扬、明月相随，以「随」「逐」写元宵的热闹；颈联「游伎皆秾李，行歌尽落梅」写歌伎美丽、边走边唱，以秾李喻美女；尾联「金吾不禁夜，玉漏莫相催」写不禁夜行、希望漏壶不要催促，以「莫相催」写对元宵夜的留恋，全诗对仗工稳、色彩明丽，是初唐律诗的成熟之作，写尽盛唐元宵的繁华。",
    b: "苏味道（初唐诗人，「文章四友」之一）这首《正月十五夜》写长安元宵夜的繁华热闹，是写元宵节的千古名篇，「火树银花」成为成语。",
    n: ["正月十五夜：元宵节","火树银花合：灯光焰火连成一片（火树银花，形容灯火辉煌）","星桥铁锁开：桥上的铁锁打开（指元宵夜开禁，允许百姓夜行）","暗尘随马去：暗中的尘土随马而去","明月逐人来：明月追逐着人而来","游伎皆秾李：游赏的歌伎都如秾李般美丽。秾李，艳丽的李花，喻美女","行歌尽落梅：边走边唱的都是《梅花落》曲调","金吾不禁夜：金吾（禁军官名）不禁止夜行（指元宵开宵禁）","玉漏莫相催：玉漏（玉制的漏壶，计时器）不要催促（希望夜长一些）"]
  },
  "送友人|薛涛": {
    s: "首两句「水国蒹葭夜有霜，月寒山色共苍苍」写水乡秋夜、芦苇有霜、月寒山色苍茫，以《诗经》「蒹葭苍苍」的意境写送别环境的清冷；后两句「谁言千里自今夕，离梦杳如关塞长」是名句——谁说千里之别从今夜开始，离别后的梦遥远得像关塞一样长，以「谁言」的反问写离情的深切、以「关塞长」比喻离梦的遥远，想象奇特，情感深沉，是薛涛诗中的佳作，也是女诗人送别诗的名篇。",
    b: "薛涛（唐代女诗人）这首《送友人》写送别友人时的景色与离情，是女诗人送别诗的名篇。",
    n: ["薛涛：唐代女诗人，曾居成都浣花溪，制「薛涛笺」","水国：水乡","蒹葭：芦苇。音jiānjiā","苍苍：茂盛的样子","月寒山色共苍苍：月色寒冷、山色与芦苇一样苍茫","谁言千里自今夕：谁说千里之别从今夜开始","离梦杳如关塞长：离别后的梦遥远得像关塞一样长。杳，遥远"]
  },
  "蝉|虞世南": {
    s: "首两句「垂緌饮清露，流响出疏桐」写蝉的形态（垂緌）、食性（饮清露）、鸣声（流响）、栖息（疏桐），以「清露」「疏桐」写蝉的高洁；后两句「居高声自远，非是藉秋风」是千古名句——因为站在高处声音自然传得远，不是凭借秋风的力量，以蝉喻人，写品格高洁的人自然声名远播，不需要凭借外力，托物言志，立意高远，是初唐咏物诗的典范，「居高声自远」成为千古名句。",
    b: "虞世南（初唐诗人，「凌烟阁二十四功臣」之一）这首《蝉》托物言志，以蝉的高洁喻人的品格，是咏蝉诗的千古名篇，与骆宾王《在狱咏蝉》、李商隐《蝉》并称「咏蝉三绝」。",
    n: ["垂緌：蝉的头部伸出的触须（像帽带下垂）。緌音ruí","饮清露：饮用清露（古人认为蝉饮露为生）","流响出疏桐：长鸣声从稀疏的梧桐树中传出","居高声自远：因为站在高处声音自然传得远","非是藉秋风：不是凭借秋风的力量。藉音jiè，凭借"]
  },
  "哥舒歌|西鄙人": {
    s: "首两句「北斗七星高，哥舒夜带刀」以北斗七星高悬起兴，写哥舒翰夜里带刀守边，以「北斗高」喻哥舒翰的威望高；后两句「至今窥牧马，不敢过临洮」是名句——至今吐蕃只敢偷看牧马，不敢越过临洮，以「不敢过」写哥舒翰守边的功绩，以吐蕃的胆怯反衬哥舒翰的威名，语言朴素如民歌，气势雄浑，是唐代边塞民歌的代表作，也是歌颂守边名将的名篇。",
    b: "西鄙人（西部边地的人，佚名）这首《哥舒歌》是唐代民歌，歌颂名将哥舒翰守边的功绩，语言朴素、气势雄浑，是唐代边塞民歌的代表作。",
    n: ["哥舒歌：歌颂哥舒翰的民歌（哥舒翰，唐代名将，曾任陇右节度使，守边有功）","北斗七星高：北斗七星高高挂在天上","哥舒夜带刀：哥舒翰夜里带着刀（守边）","至今窥牧马：至今（吐蕃）偷看牧马（指不敢轻举妄动）","不敢过临洮：不敢越过临洮（临洮，今甘肃岷县，唐代边防要地）"]
  },
  "剑客|贾岛": {
    s: "首两句「十年磨一剑，霜刃未曾试」写十年磨一剑、刀刃锋利却未曾试过，以「十年」写磨砺之久、以「霜刃」写剑之锋利，以剑喻才，写自己十年苦读、才华未展；后两句「今日把似君，谁为不平事」是名句——今天把剑拿给你看，谁有不平的事我来伸张，以「把似君」写渴望施展、以「不平事」写抱负，托物言志，语言朴素而意气豪迈，是贾岛诗中少有的豪放之作，也是咏剑诗的名篇。",
    b: "贾岛（中唐诗人，「苦吟诗人」）这首《剑客》以剑喻才，写自己十年磨砺、渴望施展抱负的心情，是咏物言志的名篇。",
    n: ["剑客：剑客（一作「述剑」）","十年磨一剑：用十年时间磨一把剑（写剑的珍贵与磨砺之久）","霜刃未曾试：霜雪般锋利的刀刃还没有试过。霜刃，形容刀刃锋利如霜","今日把似君：今天把它拿给你看。把似，拿给","谁为不平事：谁有不平的事（我来为他伸张正义）"]
  },
  "题李凝幽居|贾岛": {
    s: "首联「闲居少邻并，草径入荒园」写李凝幽居的偏僻——少邻居、草径通荒园，环境清幽；颔联「鸟宿池边树，僧敲月下门」是千古名句——鸟儿栖息在池边树上、僧人在月光下敲门，以「敲」字写夜的静，以动衬静，「推敲」的典故流传千古；颈联「过桥分野色，移石动云根」写走过桥原野景色分开、移动石头云脚也动，以「分」「动」写景色的变化；尾联「暂去还来此，幽期不负言」写暂时离去还会再来、不食归隐之约，表达对隐居生活的向往，全诗意境清幽、炼字精当，是贾岛苦吟诗的代表作。",
    b: "贾岛拜访友人李凝的幽居时所作，「鸟宿池边树，僧敲月下门」是「推敲」典故的出处，是苦吟诗的典范。",
    n: ["李凝：贾岛的友人，隐士","幽居：隐居的地方","少邻并：很少有邻居","草径入荒园：长满草的小路通入荒芜的园子","鸟宿池边树：鸟儿栖息在池边的树上","僧敲月下门：僧人在月光下敲门（「推敲」典故的出处）","过桥分野色：走过桥去，原野的景色分开","移石动云根：移动石头，云脚也动了（古人认为云「触石而出」，故称石为云根）","暂去还来此：暂时离去还会再来这里","幽期不负言：归隐的约定不食言"]
  },
  "忆江上吴处士|贾岛": {
    s: "首联「闽国扬帆去，蟾蜍亏复团」写友人扬帆去闽地、月亮缺了又圆，以月的圆缺写时间之久、思念之深；颔联「秋风生渭水，落叶满长安」是千古名句——秋风从渭水刮起、落叶飘满长安，以「生」「满」写秋意的浓重，以苍凉的秋景写离情，意境雄浑；颈联「此地聚会夕，当时雷雨寒」回忆当时聚会的夜晚、雷雨交加，以回忆写友情；尾联「兰桡殊未返，消息海云端」写友人还没回来、消息在海云那一边，以「海云端」写距离的遥远，全诗意境苍凉、情感深沉，是贾岛五律的名篇。",
    b: "贾岛这首诗写思念去闽地的友人吴处士，以秋风落叶写离情，是贾岛诗中的名篇，「秋风生渭水，落叶满长安」为千古名句。",
    n: ["吴处士：姓吴的处士（处士，有才德而隐居不仕的人）","闽国扬帆去：扬帆去闽国（今福建）","蟾蜍亏复团：月亮缺了又圆（蟾蜍，代指月亮，古代传说月中有蟾蜍）","秋风生渭水：秋风从渭水刮起","落叶满长安：落叶飘满长安","此地聚会夕：在这里聚会的夜晚","当时雷雨寒：当时雷雨交加、天气寒冷","兰桡殊未返：木兰舟还没有回来（指吴处士还没回来）。兰桡，木兰做的船桨，代指船","消息海云端：消息在海云的那一边（指遥远）"]
  },
  "雪晴晚望|贾岛": {
    s: "首联「倚杖望晴雪，溪云几万重」写拄杖眺望晴雪、溪上云几万重，以「几万重」写云之多；颔联「樵人归白屋，寒日下危峰」写樵夫归白屋、寒日落危峰，以「归」「下」写傍晚的动态，画面清冷；颈联「野火烧冈草，断烟生石松」写野火烧冈草、断烟生石松，以「烧」「生」写景色的生机；尾联「却回山寺路，闻打暮天钟」写返回山寺路上、听到暮钟，以「暮钟」写山寺的清幽，全诗画面清冷、意境幽远，是贾岛山水诗的佳作。",
    b: "贾岛这首诗写雪后初晴傍晚眺望山寺所见的景色，以清冷的画面写隐居的意境，是贾岛山水诗的名篇。",
    n: ["雪晴晚望：雪后初晴傍晚眺望","倚杖望晴雪：拄着拐杖眺望雪后初晴的景色","溪云几万重：溪上的云有几万重","樵人归白屋：樵夫回到白屋（白屋，不施彩漆的屋子，指贫家）","寒日下危峰：寒冷的太阳落下高耸的山峰","野火烧冈草：野火烧着山冈上的草","断烟生石松：断续的烟从石松间升起","却回山寺路：返回山寺的路上","闻打暮天钟：听到傍晚的钟声"]
  },
  "宿山寺|贾岛": {
    s: "首联「众岫耸寒色，精庐向此分」写群峰耸寒色、佛寺对着这里分开，以「寒色」写山的清冷；颔联「流星透疏木，走月逆行云」是名句——流星透过疏木、月亮与云反向而行，以「透」「逆」写夜景的生动，想象奇特；颈联「绝顶人来少，高松鹤不群」写绝顶人少、高松鹤不群，以「人少」「鹤不群」写山寺的清幽与高洁；尾联「一僧年八十，世事未曾闻」写八十老僧、不问世事，以老僧的超脱写山寺的境界，全诗意境清幽、想象奇特，是贾岛五律的佳作。",
    b: "贾岛这首诗写夜宿山寺所见的清幽景色与老僧的超脱，是贾岛山水诗的名篇。",
    n: ["众岫耸寒色：群峰耸立着寒冷的景色。岫音xiù，山峰","精庐向此分：精舍（佛寺）对着这里分开","流星透疏木：流星透过稀疏的树木","走月逆行云：月亮行走、与云反向而行（写云行月移）","绝顶人来少：绝顶上来的人少","高松鹤不群：高松上的鹤不合群（喻高洁）","一僧年八十：一个僧人八十岁了","世事未曾闻：世间的事从未听说过"]
  },
  "暮过山村|贾岛": {
    s: "首联「数里闻寒水，山家少四邻」写几里外闻寒水、山家少四邻，以「寒水」「少四邻」写山村的偏僻；颔联「怪禽啼旷野，落日恐行人」是名句——怪鸟在旷野啼叫、落日让行人害怕，以「怪禽」「落日」写环境的荒凉与行人的恐惧，画面阴森；颈联「初月未终夕，边烽不过秦」写新月未全黑、烽火未过秦，以「边烽不过秦」写这里的安宁；尾联「萧条桑柘外，烟火渐相亲」写萧条桑柘外、炊烟渐亲切，以「烟火渐相亲」写由恐惧转为温暖，全诗由荒凉到温暖、由恐惧到亲切，情感转折自然，是贾岛五律的佳作。",
    b: "贾岛这首诗写傍晚经过山村的所见所感，由荒凉到温暖，是贾岛山水诗的名篇。",
    n: ["暮过山村：傍晚经过山村","数里闻寒水：几里外就听到寒冷的水声","山家少四邻：山里人家很少有四邻（写偏僻）","怪禽啼旷野：怪鸟在旷野啼叫","落日恐行人：落日让行人害怕","初月未终夕：新月还没到晚上（指天还没全黑）","边烽不过秦：烽火没有越过秦地（指这里没有战火）。秦，今陕西一带","萧条桑柘外：萧条的桑树柘树外。柘音zhè，桑树的一种","烟火渐相亲：炊烟渐渐让人感到亲切"]
  },
  "题诗后|贾岛": {
    s: "首两句「二句三年得，一吟双泪流」写两句诗三年才得到、一吟诵就双泪直流，以「三年」写苦吟之久、以「双泪流」写得诗之喜，是苦吟诗人的真实写照；后两句「知音如不赏，归卧故山秋」写知音如果不欣赏就归隐故山，以「归卧」写对知音的渴望，全诗语言朴素、情感真挚，是贾岛苦吟诗风的自白，「二句三年得，一吟双泪流」成为千古名句，也是了解中唐苦吟诗派的重要作品。",
    b: "贾岛这首《题诗后》写自己苦吟的艰辛，「二句三年得，一吟双泪流」是苦吟诗人的自白，是了解贾岛诗风的名篇。",
    n: ["题诗后：题完诗后（贾岛苦吟，作诗后写此诗）","二句三年得：两句诗三年才得到","一吟双泪流：一吟诵就双泪直流","知音如不赏：知音如果不欣赏","归卧故山秋：就回到故山秋卧（指归隐）"]
  },
  "柏林寺南望|郎士元": {
    s: "首两句「溪上遥闻精舍钟，泊舟微径度深松」写溪上遥闻寺钟、停船穿松寻寺，以「遥闻」「度深松」写游兴与山的幽深；后两句「青山霁后云犹在，画出东南四五峰」是名句——青山雨后初晴云还在、东南方的四五座山峰像画出来的一样，以「画出」写山的明丽如画，以「四五峰」写山的错落，语言清新、意境明丽，是中唐写景七绝的佳作。",
    b: "郎士元（中唐诗人）这首诗写雨后初晴望柏林寺南的青山，以「画出」写山的明丽，是写景小诗的名篇。",
    n: ["柏林寺：在今河北赵县（一说在今陕西西安）","溪上遥闻精舍钟：在溪上远远听到佛寺的钟声。精舍，佛寺","泊舟微径度深松：停船沿小路穿过深松","青山霁后云犹在：青山雨后初晴云还在。霁，雨后初晴","画出东南四五峰：画出了东南方的四五座山峰"]
  },
  "淮上与友人别|郑谷": {
    s: "首两句「扬子江头杨柳春，杨花愁杀渡江人」写扬子江头杨柳青青、柳絮飘飞愁煞渡江人，以杨柳、杨花写离情（古人折柳送别）；后两句「数声风笛离亭晚，君向潇湘我向秦」是千古名句——几声风笛、离亭傍晚，你去潇湘我去秦，以「风笛」「离亭」写离别的氛围、以「君向潇湘我向秦」写两人各奔东西，以朴素的语言写深挚的离情，「君向潇湘我向秦」成为千古名句，是晚唐送别诗的代表作。",
    b: "郑谷（晚唐诗人）这首诗写在淮水边与友人分别，一人去潇湘一人去秦，是送别诗的千古名篇。",
    n: ["淮上：淮水边","扬子江头：长江渡口（扬子江，长江下游）","杨柳春：杨柳青青的春天","杨花愁杀渡江人：柳絮飘飞愁煞渡江的人","风笛：风中的笛声","离亭：送别亭","君向潇湘我向秦：你去潇湘（湖南）我去秦（陕西）"]
  },
  "谷口书斋寄杨补阙|钱起": {
    s: "首联「泉壑带茅茨，云霞生薜帷」写泉水山谷环绕茅屋、云霞从薜帷生起，环境清幽；颔联「竹怜新雨后，山爱夕阳时」是名句——竹子在新雨后更可爱、山在夕阳时更可爱，以「怜」「爱」写对竹与山的喜爱，以「新雨」「夕阳」写景色的明丽；颈联「闲鹭栖常早，秋花落更迟」写闲鹭早栖、秋花迟落，以动植写书斋的闲适；尾联「家童扫萝迳，昨与故人期」写家童扫小路、昨天与故人约定，以「扫萝迳」写期待友人来访，全诗意境清幽、对仗工稳，是大历十才子山水诗的代表作。",
    b: "钱起（中唐诗人，「大历十才子」之首）这首诗写谷口书斋的清幽景色，邀请友人杨补阙来访，是山水田园诗的名篇。",
    n: ["谷口：谷口（在今陕西泾阳，汉代隐士郑子真隐居处）","书斋：书房","杨补阙：姓杨的补阙（补阙，官名，掌讽谏）","泉壑带茅茨：泉水山谷环绕着茅屋。茅茨，茅屋","云霞生薜帷：云霞从薜荔帷帐中生起。薜帷，薜荔做的帷帐","竹怜新雨后：竹子在新雨后更可爱。怜，爱","山爱夕阳时：山在夕阳时更可爱","闲鹭栖常早：悠闲的白鹭常常栖息得早","秋花落更迟：秋天的花落得更迟","家童扫萝迳：家童扫藤萝掩映的小路。迳同「径」","昨与故人期：昨天与故人（指杨补阙）约定了"]
  },
  "别离|陆龟蒙": {
    s: "首联「丈夫非无泪，不洒离别间」写大丈夫不是没有泪、只是不洒在离别间，以「非无泪」「不洒」写大丈夫的克制；颔联「杖剑对尊酒，耻为游子颜」写持剑对酒、耻于做游子愁颜，以「杖剑」写豪情；颈联「蝮蛇一螫手，壮士即解腕」是名句——蝮蛇咬手、壮士断腕，用「壮士解腕」的典故写大丈夫的果断与以大局为重；尾联「所志在功名，离别何足叹」写志向在功名、离别不足叹，以反问写豪情，全诗刚健豪迈、一反送别诗的伤感传统，是晚唐送别诗中的别调。",
    b: "陆龟蒙（晚唐诗人，「皮陆」之一）这首《别离》写大丈夫以功名自任、不以离别为意的豪情，是送别诗中的豪放之作。",
    n: ["杖剑：拿着剑。杖同「仗」","尊酒：一杯酒。尊同「樽」","耻为游子颜：耻于做出游子的愁颜","蝮蛇一螫手：蝮蛇一旦咬了手。螫音shì，毒虫刺人","壮士即解腕：壮士就砍断手腕（「蝮蛇螫手，壮士解腕」典故，指为大局牺牲局部）","所志在功名：志向在功名","离别何足叹：离别哪里值得叹息"]
  },
  "新沙|陆龟蒙": {
    s: "首两句「渤澥声中涨小堤，官家知后海鸥知」写渤海中涨出新沙洲、官家比海鸥还先知道，以「官家知后海鸥知」的夸张讽刺官家征税之快、之细，连海鸥都不如；后两句「蓬莱有路教人到，应亦年年税紫芝」是名句——如果蓬莱有路让人到，也应该年年征收紫芝税，以「蓬莱税紫芝」的想象讽刺官家征税无孔不入，连仙境都不放过，想象奇特、讽刺辛辣，是晚唐讽刺诗的代表作。",
    b: "陆龟蒙这首《新沙》讽刺官家征税无孔不入，连新涨的沙洲都不放过，是晚唐讽刺诗的名篇。",
    n: ["新沙：新涨出的沙洲","渤澥声中涨小堤：渤海的涛声中涨出了小堤。渤澥，渤海的别称。澥音xiè","官家知后海鸥知：官家知道后海鸥才知道（讽刺官家征税之快，连海鸥都不如）","蓬莱有路教人到：如果蓬莱有路让人到","应亦年年税紫芝：也应该年年征收紫芝税（紫芝，灵芝，传说中的仙草）"]
  },
  "感遇诗三十八首·一|陈子昂": {
    s: "首四句「微月生西海，幽阳始代升。圆光正东满，阴魂已朝凝」写新月从西海升起、日月交替、月满月落，以日月运行写宇宙的规律；后四句「太极生天地，三元更废兴。至精谅斯在，三五谁能征」写太极生天地、三元更替兴衰，最精微的道理确实在这里，三皇五帝谁能验证呢，以哲理写对宇宙人生的思考，语言古朴、意境深远，是陈子昂感遇诗的代表作，体现了其追慕汉魏风骨、反对齐梁绮靡的诗学主张。",
    b: "陈子昂（初唐诗人，唐诗革新的先驱）《感遇》三十八首之一，以日月运行、太极生天地的哲理写对宇宙人生的思考，是其感遇诗的代表作。",
    n: ["感遇诗三十八首：陈子昂的组诗，共三十八首，此为其一","微月生西海：新月从西海升起","幽阳始代升：幽暗的太阳开始替代升起（指日月交替）","圆光正东满：圆月正从东方满盈","阴魂已朝凝：阴魂已在早晨凝聚（指月落）","太极生天地：太极生天地（太极，古代哲学概念，指天地未分前的混沌之气）","三元更废兴：天、地、人三元更替兴衰。三元，天、地、人","至精谅斯在：最精微的道理确实在这里。谅，确实","三五谁能征：三皇五帝谁能验证呢。三五，三皇五帝；征，验证"]
  },
  "陇西行四首·一|陈陶": {
    s: "首两句「汉主东封报太平，无人金阙议边兵」写汉皇东封泰山夸耀太平、金殿上无人议论边事，以「东封」「无人议边兵」讽刺帝王粉饰太平、不关心边防；后两句「纵饶夺得林胡塞，碛地桑麻种不生」是名句——纵然夺得林胡塞，沙漠地里桑麻种不活，以「碛地桑麻种不生」写夺得了沙漠也无用，讽刺穷兵黩武、劳民伤财，语言朴素而讽刺深刻，是晚唐咏史讽刺诗的佳作。",
    b: "陈陶（晚唐诗人）《陇西行》四首之一，讽刺帝王夸耀太平、无人关心边事、夺得了沙漠也无用，是咏史讽刺诗。（同题第二首「誓扫匈奴不顾身，五千貂锦丧胡尘。可怜无定河边骨，犹是春闺梦里人」更为传诵。）",
    n: ["陇西行：乐府旧题，写边塞征战（陈陶，晚唐诗人）","汉主东封报太平：汉皇东封泰山报告太平（指帝王封禅，夸耀太平）","无人金阙议边兵：金殿上无人议论边防战事。金阙，宫殿","纵饶夺得林胡塞：纵然夺得林胡塞（林胡，古代北方民族，此指边地）","碛地桑麻种不生：沙漠地里桑麻种不活。碛音qì，沙漠"]
  },
  "台城|韦庄": {
    s: "首两句「江雨霏霏江草齐，六朝如梦鸟空啼」写江上细雨蒙蒙、江草整齐，六朝像梦一样、鸟儿空自啼叫，以「霏霏」「如梦」写六朝的虚幻与荒凉；后两句「无情最是台城柳，依旧烟笼十里堤」是千古名句——最无情的是台城的柳树，依旧烟雾笼罩十里长堤，以柳的「无情」「依旧」写人的有情、历史的变迁，以乐景写哀，借古讽今，意境苍凉，是晚唐咏史怀古诗的代表作，「无情最是台城柳」成为千古名句。",
    b: "韦庄（晚唐诗人，「花间派」代表）这首《台城》写六朝故都的荒凉，借古讽今，是晚唐咏史怀古诗的千古名篇。",
    n: ["台城：六朝时的宫城，在今南京玄武湖边","江雨霏霏江草齐：江上细雨蒙蒙、江草整齐。霏霏，细雨蒙蒙的样子","六朝如梦鸟空啼：六朝像梦一样、鸟儿空自啼叫。六朝，吴、东晋、宋、齐、梁、陈，皆建都南京","无情最是台城柳：最无情的是台城的柳树","依旧烟笼十里堤：依旧烟雾笼罩着十里长堤"]
  },
  "菩萨蛮·人人尽说江南好|韦庄": {
    s: "上片「人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠」写人人都说江南好、游人只合江南老，春水比天碧绿、画船听雨入眠，以「春水碧于天」写江南水的明丽、以「画船听雨眠」写江南生活的闲适；下片「垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠」写垆边女子貌美、皓腕如霜雪，以「未老莫还乡，还乡须断肠」写对故乡的思念与不敢还乡的痛苦（韦庄故乡在战乱中），以乐景写哀，江南越美、思乡越痛，情感深沉，是花间词的代表作，「春水碧于天，画船听雨眠」成为千古名句。",
    b: "韦庄《菩萨蛮》五首之二（库文标为「人人尽说江南好」），写江南的美好与游子的思乡，是花间词的千古名篇，与白居易《忆江南》齐名。",
    n: ["菩萨蛮：词牌名","人人尽说江南好：人人都说江南好","游人只合江南老：游人只应该在江南终老。只合，只应该","春水碧于天：春水比天还碧绿","画船听雨眠：在画船上听着雨声入眠","垆边人似月：酒垆边的女子像月亮一样美丽。垆，酒垆","皓腕凝霜雪：洁白的手腕像凝结的霜雪","未老莫还乡：没老不要还乡","还乡须断肠：还乡一定会断肠（指故乡战乱，回去会伤心）"]
  },
  "淮上喜会梁川故人|韦应物": {
    s: "首联「江汉曾为客，相逢每醉还」写曾经在江汉做客、相逢每次醉归，回忆昔日的交游；颔联「浮云一别后，流水十年间」是名句——像浮云一样分别后、流水一样十年过去了，以「浮云」「流水」比喻离别与时间，以「十年」写时间之久，对仗工稳、意境苍凉；颈联「欢笑情如旧，萧疏鬓已斑」写欢笑情意如旧、鬓发已斑，以「情如旧」与「鬓已斑」对比，写岁月无情；尾联「何因北归去，淮上对秋山」写什么原因北归、在淮水边对秋山，以景结情，余味悠然，全诗情感深沉、对仗工稳，是韦应物五律的代表作。",
    b: "韦应物（中唐诗人）这首诗写在淮上与梁川故人久别重逢，写友情与岁月的感慨，是中唐五律的名篇。",
    n: ["淮上：淮水边","梁川故人：梁川（今陕西南郑一带）的老朋友","江汉曾为客：曾经在江汉一带做客","相逢每醉还：相逢每次都醉着回去","浮云一别后：像浮云一样分别后","流水十年间：流水一样十年过去了","欢笑情如旧：欢笑的情意如旧","萧疏鬓已斑：稀疏的鬓发已经斑白。萧疏，稀疏","何因北归去：什么原因北归呢","淮上对秋山：在淮水边对着秋山"]
  },
  "初发扬子寄元大校书|韦应物": {
    s: "首联「凄凄去亲爱，泛泛入烟雾」写凄凄离别亲爱、船驶入烟雾，以「凄凄」「泛泛」写离情与船行；颔联「归棹洛阳人，残钟广陵树」写回洛阳的人、残钟从广陵树间传来，以「归棹」「残钟」写离别的场景；颈联「今朝此为别，何处还相遇」写今天分别、何处再相遇，以反问写离别的惆怅；尾联「世事波上舟，沿洄安得住」是名句——世事像波浪上的船、顺流逆流怎么停得住，以「波上舟」比喻世事无常，以反问写对人生的感慨，全诗情感深沉、比喻贴切，是韦应物送别诗的代表作。",
    b: "韦应物这首诗写从扬子津出发、送别友人元大，写离情与世事无常的感慨，是送别诗的名篇。",
    n: ["初发扬子：从扬子津（长江渡口）出发","元大校书：元大（排行大）校书郎（官名）","凄凄去亲爱：凄凄地离别亲爱之人","泛泛入烟雾：船泛泛地驶入烟雾中","归棹洛阳人：回洛阳的人（指元大，元大要回洛阳）。棹，船桨，代指船","残钟广陵树：残钟从广陵（扬州）的树间传来","今朝此为别：今天在这里分别","何处还相遇：什么地方还能相遇","世事波上舟：世事像波浪上的船","沿洄安得住：顺流逆流怎么能停得住呢。沿洄，顺流与逆流"]
  },
  "寄全椒山中道士|韦应物": {
    s: "首联「今朝郡斋冷，忽念山中客」写今天官署冷、忽然想念山中道士，以「冷」写心境、以「忽念」写思念；颔联「涧底束荆薪，归来煮白石」想象道士在涧底捆柴、回来煮白石，以「束荆薪」「煮白石」写道士的清苦与高洁；颈联「欲持一瓢酒，远慰风雨夕」写想拿一瓢酒、远远慰藉风雨之夜，以「一瓢酒」写情意的真；尾联「落叶满空山，何处寻行迹」是名句——落叶满空山、到哪里寻踪迹，以「落叶满空山」写山的空寂、以「何处寻」写寻而不得的惆怅，以景结情，意境清远，是韦应物五古的代表作，「落叶满空山，何处寻行迹」成为千古名句。",
    b: "韦应物任滁州刺史时，想念全椒山中道士，想送酒去却寻不到，是寄赠诗的千古名篇。",
    n: ["全椒：今安徽全椒","山中道士：山中的道士","郡斋：州郡的官署（韦应物时任滁州刺史）","涧底束荆薪：在涧底捆柴。荆薪，柴草","归来煮白石：回来煮白石（道家传说仙人煮白石为粮，此指道士的清苦生活）","欲持一瓢酒：想拿一瓢酒","远慰风雨夕：远远地慰藉风雨之夜","落叶满空山：落叶满了空山","何处寻行迹：到哪里寻找踪迹呢"]
  },
  "赋得暮雨送李胄|韦应物": {
    s: "首联「楚江微雨里，建业暮钟时」写楚江微雨、建业暮钟，以「微雨」「暮钟」写送别的环境；颔联「漠漠帆来重，冥冥鸟去迟」是名句——茫茫中船帆沉重、昏暗中鸟飞迟缓，以「帆重」「鸟迟」写雨的细密，以「漠漠」「冥冥」写雨的迷蒙，对仗工稳、意境苍凉；颈联「海门深不见，浦树远含滋」写海门深不见、浦树远含滋，以「深不见」「远含滋」写远景的迷蒙；尾联「相送情无限，沾襟比散丝」写相送情无限、泪比雨丝多，以「散丝」比喻雨丝与泪丝，情景交融，全诗意境苍凉、情感深沉，是韦应物送别诗的代表作。",
    b: "韦应物这首诗写在暮雨中送别友人李胄，以雨写离情，是送别诗的名篇。",
    n: ["赋得暮雨送李胄：以暮雨为题送李胄（赋得，指定题目赋诗）","楚江微雨里：楚江（长江）在微雨里","建业暮钟时：建业（南京）傍晚敲钟时","漠漠帆来重：茫茫中船帆来的沉重（因雨湿）。漠漠，迷蒙的样子","冥冥鸟去迟：昏暗中鸟飞去迟缓。冥冥，昏暗的样子","海门深不见：海门（长江入海处）深得看不见","浦树远含滋：水边的树远远含着湿润。滋，湿润","相送情无限：相送情意无限","沾襟比散丝：沾湿衣襟的泪比雨丝还多。散丝，比喻细雨"]
  },
  "长安遇冯著|韦应物": {
    s: "首联「客从东方来，衣上灞陵雨」写客人从东方来、衣上带灞陵雨，以「灞陵雨」写行程的辛苦；颔联「问客何为来，采山因买斧」写问客人为什么来、答进山隐居买斧，以问答写冯著的失意与隐居之志；颈联「冥冥花正开，飏飏燕新乳」是名句——昏暗中花正开、飞舞中燕新乳，以「花正开」「燕新乳」写春景的生机，以乐景衬哀情；尾联「昨别今已春，鬓丝生几缕」写昨天分别今天已春、鬓边生了几缕白发，以「鬓丝」写岁月无情，全诗语言朴素、情感深沉，是韦应物赠答诗的代表作。",
    b: "韦应物这首诗写与友人冯著重逢，写冯著的失意与岁月的感慨，是赠答诗的名篇。",
    n: ["冯著：韦应物的友人，曾隐居","客从东方来：客人从东方来","衣上灞陵雨：衣服上带着灞陵的雨（灞陵，在长安东，汉文帝陵墓，古人送别处）","问客何为来：问客人为什么来","采山因买斧：进山（隐居）因此买斧（指来买隐居的工具）","冥冥花正开：昏暗中花正开","飏飏燕新乳：飞舞中燕子刚喂雏。飏飏，飞舞的样子。飏音yáng","昨别今已春：昨天分别今天已是春天","鬓丝生几缕：鬓边生了几缕白发"]
  },
  "夕次盱眙县|韦应物": {
    s: "首联「落帆逗淮镇，停舫临孤驿」写落帆停淮镇、停船靠孤驿，以「孤驿」写旅夜的孤寂；颔联「浩浩风起波，冥冥日沈夕」写浩浩风起波、冥冥日西沉，以「浩浩」「冥冥」写环境的苍茫；颈联「人归山郭暗，雁下芦洲白」是名句——人归山郭昏暗、雁下芦洲白，以「人归」「雁下」写傍晚的动态，以「暗」「白」写色彩的对比，画面苍凉；尾联「独夜忆秦关，听钟未眠客」写独夜忆秦关、听钟未眠，以「未眠」写思乡之深，全诗意境苍凉、情感深沉，是韦应物羁旅诗的代表作。",
    b: "韦应物这首诗写傍晚停宿盱眙县，写旅夜的孤寂与思乡，是羁旅诗的名篇。",
    n: ["夕次盱眙县：傍晚停宿在盱眙县（今江苏盱眙）。次，停宿","落帆逗淮镇：落下船帆停在淮水边的镇子。逗，停留","停舫临孤驿：停船靠着孤驿。舫，船","浩浩风起波：浩浩的风掀起波浪","冥冥日沈夕：昏暗中太阳西沉。沈同「沉」","人归山郭暗：人归山郭昏暗","雁下芦洲白：雁下到白色的芦洲","独夜忆秦关：孤独的夜里忆念秦关（长安）","听钟未眠客：听着钟声的未眠客人"]
  },
  "滁州西涧|韦应物": {
    s: "首两句「独怜幽草涧边生，上有黄鹂深树鸣」写独爱涧边幽草、上有黄鹂深树鸣，以「幽草」「黄鹂」写涧边的清幽，以「独怜」写诗人的偏爱；后两句「春潮带雨晚来急，野渡无人舟自横」是千古名句——春潮带雨傍晚来得急、野渡无人船自横，以「急」写雨的急、以「自横」写船的自在，以动衬静，画面清幽，意境深远，全诗语言朴素、意境清远，是韦应物七绝的代表作，「野渡无人舟自横」成为千古名句，也是中国山水画的常见题材。",
    b: "韦应物任滁州刺史时所作，写滁州西涧的清幽景色，是山水小诗的千古名篇，「野渡无人舟自横」成为千古名句。",
    n: ["滁州西涧：滁州（今安徽滁州）城西的涧水","独怜幽草涧边生：独独喜爱涧边生长的幽草。怜，爱","上有黄鹂深树鸣：上面有黄鹂在深树中鸣叫","春潮带雨晚来急：春潮带着雨傍晚来得急","野渡无人舟自横：荒野的渡口无人、船自横在那里"]
  },
  "闻雁|韦应物": {
    s: "首两句「故园眇何处，归思方悠哉」写故乡遥远在哪里、归思正悠长，以「眇」写故乡的遥远、以「悠哉」写归思的悠长；后两句「淮南秋雨夜，高斋闻雁来」是名句——淮南的秋雨之夜、在高斋中听到大雁飞来，以「秋雨夜」写环境的清冷、以「闻雁」写思乡的触发（大雁南飞引发游子思乡），以景结情，意境清远，全诗语言朴素、情感深沉，是韦应物五绝的代表作。",
    b: "韦应物任滁州刺史时所作，写秋雨夜闻雁思乡，是思乡小诗的名篇。",
    n: ["闻雁：听到大雁的叫声","故园眇何处：故乡遥远在哪里。眇同「渺」，遥远","归思方悠哉：归思正悠长。悠哉，悠长的样子","淮南秋雨夜：淮南的秋雨之夜","高斋闻雁来：在高斋中听到大雁飞来"]
  },
  "晚春|韩愈": {
    s: "首两句「谁收春色将归去，慢绿妖红半不存」写谁收了春色将归去、绿叶红花大半不存，以「谁收」的拟人写春归、以「半不存」写晚春的凋零；后两句「榆荚祗能随柳絮，等闲撩乱走空园」是名句——榆荚只能随着柳絮、随便在空园里撩乱飞舞，以「祗能」「等闲」写榆荚柳絮的无奈与顽皮，以拟人写晚春的生机，语言明快、想象奇特，是韩愈七绝中的清新之作。",
    b: "韩愈这首《晚春》写晚春景色，以拟人手法写榆荚柳絮的飞舞，是写景小诗的名篇。（韩愈《晚春》另一首「草树知春不久归，百般红紫斗芳菲。杨花榆荚无才思，惟解漫天作雪飞」更为传诵。）",
    n: ["晚春：晚春","谁收春色将归去：谁收了春色将要归去","慢绿妖红半不存：慢绿（绿叶）妖红（红花）大半不存在了","榆荚祗能随柳絮：榆荚只能随着柳絮（飘飞）。祗同「只」；榆荚，榆树的果实，形似钱，又称榆钱","等闲撩乱走空园：随便地在空园里撩乱飞舞。等闲，随便；撩乱，纷乱"]
  },
  "左迁至蓝关示侄孙湘|韩愈": {
    s: "首联「一封朝奏九重天，夕贬潮州路八千」以「朝奏」「夕贬」的对比写获罪之快、贬谪之远，悲愤激烈；颔联「欲为圣朝除弊事，肯将衰朽惜残年」直抒胸臆，写自己为朝廷除弊、不惜残年的忠愤；颈联「云横秦岭家何在，雪拥蓝关马不前」是千古名句——云横秦岭、家在何处，雪拥蓝关、马不肯前，以景写情，家亡国愁交织，苍凉悲壮；尾联「知汝远来应有意，好收吾骨瘴江边」写侄孙远来、正好在瘴江边收我的尸骨，以沉痛语作结，忠愤之气凛然，是韩愈七律的压卷之作。",
    b: "韩愈元和十四年（819）因上《论佛骨表》谏迎佛骨，触怒宪宗，被贬潮州，行至蓝关遇侄孙韩湘，写下这首诗，是韩诗的千古名篇。",
    n: ["左迁：贬官（古人以右为尊，左迁即降职）","蓝关：蓝田关，在今陕西蓝田东南","侄孙湘：侄孙韩湘","一封朝奏九重天：早上一封奏章上达皇帝。九重天，指皇帝","夕贬潮州路八千：傍晚就被贬到八千里外的潮州","弊事：有害的事（指迎佛骨）","肯将衰朽惜残年：哪肯因衰老顾惜残年","瘴江：有瘴气的江水（指潮州一带）"]
  },
  "早春呈水部张十八员外二首·一|韩愈": {
    s: "首两句「天街小雨润如酥，草色遥看近却无」写京城小雨滋润如酥、草色远看有近看无，以「润如酥」写春雨的细腻、以「遥看近却无」写早春草的朦胧，观察入微；后两句「最是一年春好处，绝胜烟柳满皇都」写早春正是一年春好处、远胜过晚春烟柳满皇都，以对比写早春的可爱，全诗语言清新、观察细腻，是写早春的千古名篇，「草色遥看近却无」成为名句。",
    b: "韩愈这首小诗写早春景色，以「草色遥看近却无」写早春草的朦胧，是写早春的千古名篇。",
    n: ["早春呈水部张十八员外：早春呈给水部员外郎张籍（张籍排行十八）","天街：京城的街道","润如酥：滋润如酥油（形容春雨的细腻）","草色遥看近却无：草色远看有、近看却无（写早春草刚发芽的状态）","最是一年春好处：正是一年中春天最好的地方","绝胜烟柳满皇都：远远胜过烟柳笼罩的皇都（晚春景色）"]
  },
  "师说|韩愈": {
    s: "全文围绕「师道」展开：第一段提出中心论点——古之学者必有师，师者传道受业解惑，道之所存师之所存；第二段以对比批判当时耻于从师的风气——古之圣人从师而问、今之众人耻学于师，爱其子择师而教、于其身则耻师，巫医乐师百工不耻相师、士大夫群聚笑之，三层对比层层深入；第三段以孔子从师为例，提出「弟子不必不如师，师不必贤于弟子，闻道有先后，术业有专攻」的进步观点；第四段说明写作缘由——嘉许李蟠能行古道。全文论证严密、对比鲜明、气势充沛，是论说文的典范。",
    b: "韩愈这篇《师说》是针对当时士大夫耻于从师的风气而作，提出「道之所存，师之所存」「弟子不必不如师，师不必贤于弟子」等进步观点，是中国古代论说文的千古名篇。",
    n: ["学者：求学的人","传道受业解惑：传授道理、教授学业、解答疑惑。受同「授」","庸知：哪里知道。庸，岂、哪里","无贵无贱：无论贵贱","句读：句子的停顿。读音dòu","小学而大遗：小的方面学习、大的方面遗漏","不齿：不屑一提","郯子：春秋时郯国国君，孔子曾向他问官名","苌弘：周敬王大夫，孔子曾向他问乐。苌音cháng","师襄：春秋鲁国乐官，孔子曾向他学琴","老聃：老子，孔子曾向他问礼。聃音dān","术业有专攻：学问技艺各有专门研究","贻：赠送。音yí"]
  },
  "马说|韩愈": {
    s: "全文以「伯乐—千里马」的比喻贯穿：第一段提出「世有伯乐，然后有千里马，千里马常有而伯乐不常有」，点明识才者的重要；第二段写千里马因食不饱、力不足而才美不外见，揭示人才被埋没的原因——「食马者不知其能千里而食也」；第三段写「策之不以其道，食之不能尽其材，鸣之而不能通其意」，却执策而临之曰「天下无马」，以「其真无马邪？其真不知马也」的反问作结，辛辣讽刺统治者不识人才。全文托物寓意、层层深入、语言精炼，是寓言式论说文的典范。",
    b: "韩愈这篇《马说》以千里马喻人才，以伯乐喻识才者，批判当时统治者不识人才、摧残人才的社会现象，是中国古代寓言式论说文的千古名篇。",
    n: ["伯乐：春秋时善相马的人（孙阳）","祗辱于奴隶人之手：只是在奴仆手中受屈辱。祗同「只」","骈死于槽枥之间：并排死在马厩里。骈，两马并驾；槽枥，马槽。枥音lì","一食或尽粟一石：吃一顿有时能吃完一石粮食。石音dàn，容量单位","食马者：喂马的人。食音sì，喂养","才美不外见：才能和优点不能表现出来。见同「现」","策之不以其道：鞭打它不按正确方法。策，马鞭，此指鞭打","执策而临之：拿着鞭子面对着它","其真无马邪：难道真的没有千里马吗。邪同「耶」，语气词"]
  },
  "进学解|韩愈": {
    s: "全文采用辞赋的「主客问答」形式：第一段国子先生教诲学生——业精于勤荒于嬉、行成于思毁于随，当今圣贤相逢、选拔公平，诸生只需业精行成；第二段学生反驳——先生口不绝吟、手不停披、焚膏继晷，可谓勤矣；觝排异端、攘斥佛老，可谓劳矣；沉浸醲郁、含英咀华，文章闳中肆外，可谓能矣；然而公不见信、私不见助，跋前踬后、动辄得咎，冬暖儿号寒、年丰妻啼饥，头童齿豁，先生自己尚且如此，还教别人？第三段先生以工匠用材、医师用药为喻，说明人各有宜、量才录用，孟轲荀卿尚且不遇，自己如今「投闲置散，乃分之宜」，以自解作结，实则愤懑更深。全文辞藻华美、用典丰富、抑扬顿挫，是辞赋式论说文的典范。",
    b: "韩愈元和七年（812）任国子博士时所作，借国子先生与学生的对话，抒发自己才高而不被重用的愤懑，是中国古代辞赋式论说文的千古名篇，「业精于勤荒于嬉，行成于思毁于随」成为千古名句。",
    n: ["进学解：关于增进学业的辨析（韩愈任国子博士时所作）","国子先生：韩愈自称（时任国子博士）","业精于勤荒于嬉：学业精进在于勤奋、荒废在于嬉戏","行成于思毁于随：品行成就在于思考、败坏在于因循","治具毕张：法令制度全部施行。治具，法令","爬罗剔抉：搜罗挑选（指选拔人才）","刮垢磨光：刮去污垢、磨出光泽（指培养人才）","焚膏油以继晷：点油灯继续日光（指夜以继日）。晷音guǐ，日光","兀兀：劳苦的样子","觝排异端：排斥异端邪说。觝同「抵」","补苴罅漏：弥补裂缝和漏洞。苴音jū，铺垫；罅音xià，裂缝","佶屈聱牙：文句曲折拗口。佶音jí、聱音áo","跋前踬后：进退两难。踬音zhì","头童齿豁：头顶秃了、牙齿缺了。童，秃；豁，缺","杗：大梁。音máng","桷：方椽子。音jué","欂栌：斗拱。音bólú","卓荦：卓越。荦音luò","訾：诋毁。音zǐ","豨苓：猪苓，泻药。豨音xī"]
  },
  "同题仙游观|韩翃": {
    s: "首联「仙台下见五城楼，风物凄凄宿雨收」写仙台下见五城楼、宿雨初收风物凄凄，以「五城楼」写道观如仙境；颔联「山色遥连秦树晚，砧声近报汉宫秋」写山色遥连秦树、砧声近报汉宫秋，以「秦树」「汉宫」写历史的沧桑；颈联「疏松影落空坛静，细草香闲小洞幽」写疏松影落空坛、细草香闲小洞，以「空坛静」「小洞幽」写道观的清幽；尾联「何用别寻方外去，人间亦自有丹丘」写何必另寻方外、人间自有丹丘，以「丹丘」喻此地如仙境，全诗意境清幽、对仗工稳，是大历十才子山水诗的代表作。",
    b: "韩翃（中唐诗人，「大历十才子」之一）这首诗写游仙游观的景色，以道观的清幽写仙境的意境，是大历十才子山水诗的名篇。",
    n: ["仙游观：在今河南嵩山","五城楼：传说中神仙的五城十二楼","宿雨收：昨夜的雨停了","秦树：秦地的树","砧声：捣衣声","汉宫：汉代宫殿，此指唐宫","空坛：空的祭坛","方外：世俗之外","丹丘：神仙居住的地方（昼夜常明）"]
  },
  "寒食|韩翃": {
    s: "首两句「春城无处不飞花，寒食东风御柳斜」写京城寒食节——无处不飞花、东风吹斜御柳，以「飞花」「御柳」写京城春景的明丽，画面生动；后两句「日暮汉宫传蜡烛，轻烟散入五侯家」写傍晚皇宫传送蜡烛、轻烟散入五侯家，以「传蜡烛」「五侯家」暗讽权贵近臣得皇帝特赐、特权独享，以汉喻唐，含蓄讽刺，全诗语言明丽、寓意深刻，是中唐七绝的名篇，「春城无处不飞花」成为千古名句。",
    b: "韩翃这首《寒食》写京城寒食节的景色，以「汉宫传蜡烛」暗讽权贵得宠，是中唐七绝的千古名篇，据说唐德宗因这首诗赏识韩翃。",
    n: ["寒食：寒食节，在清明前一二日，禁火吃冷食","春城无处不飞花：春天的京城无处不飘着柳絮（飞花，指柳絮）","御柳：皇宫中的柳树","汉宫传蜡烛：汉宫（指唐宫）传送蜡烛（寒食禁火，但皇帝特赐蜡烛给近臣）","五侯：指东汉桓帝时同日封侯的五个宦官，此指权贵近臣"]
  },
  "宿石邑山中|韩翃": {
    s: "首两句「浮云不共此山齐，山霭苍苍望转迷」写浮云不能与此山齐、山霭苍苍望转迷，以「浮云不共齐」写山之高、以「望转迷」写山之深；后两句「晓月暂飞高树里，秋河隔在数峰西」是名句——晓月暂时飞进高树里、银河隔在数峰西，以「晓月」「秋河」写山中夜景的清幽，以「暂飞」「隔在」写山的高峻，画面清新、意境幽远，是大历十才子山水诗的佳作。",
    b: "韩翃这首诗写夜宿石邑山中所见的景色，以山的高峻写意境的清幽，是大历十才子山水诗的名篇。",
    n: ["石邑山：在今河北获鹿东南","浮云不共此山齐：浮云不能与此山一样高（写山之高）","山霭苍苍：山中的云气苍茫。霭，云气","望转迷：望过去更加迷茫","晓月暂飞高树里：晓月暂时飞进高树里（写月被树遮）","秋河隔在数峰西：银河隔在数座山峰的西边。秋河，秋天的银河"]
  },
  "过山农家|顾况": {
    s: "这首六言诗四句四个画面：「板桥人渡泉声」写走过板桥听泉声，「茆檐日午鸡鸣」写茅檐正午鸡鸣，以声写山村的宁静；「莫嗔焙茶烟暗」写不要嗔怪焙茶烟熏暗了屋，「却喜晒谷天晴」写却高兴晒谷天晴，以「莫嗔」「却喜」写山农的生活与心情，一嗔一喜，生活气息浓郁，全诗六言句式整齐、画面生动，是六言诗中的佳作。",
    b: "顾况（中唐诗人）这首六言诗写过山农家所见的情景，以焙茶、晒谷写农家生活，是六言诗的名篇。",
    n: ["过山农家：经过山农的家（六言诗）","板桥人渡泉声：人走过板桥时听到泉声","茆檐日午鸡鸣：茅草屋檐下正午鸡鸣。茆同「茅」","莫嗔焙茶烟暗：不要嗔怪焙茶的烟熏暗了屋子。嗔音chēn，责怪；焙音bèi，微火烘烤","却喜晒谷天晴：却高兴晒谷的天气晴朗"]
  },
  "宫词|顾况": {
    s: "首两句「长乐宫连上苑春，玉楼金殿艳歌新」写长乐宫连上苑春、玉楼金殿艳歌新，以宫殿的华丽与歌舞的热闹反衬宫女的孤独；后两句「君门一入无由出，唯有宫莺得见人」是名句——宫门一入就出不来、只有宫莺能见到外面的人，以「宫莺得见人」反衬宫女不能见人，以鸟的自由反衬人的不自由，含蓄深沉，是宫怨诗的佳作。",
    b: "顾况这首《宫词》写宫女一入宫门便失去自由，只有宫莺能见到外面的人，是宫怨诗的名篇。",
    n: ["长乐宫：汉代宫殿，此指唐宫","上苑：皇家园林","玉楼金殿：华丽的楼阁宫殿","艳歌新：新的艳丽歌声","君门一入无由出：宫门一进去就没有理由出来","宫莺：宫中的黄莺"]
  },
  "楚江怀古三首·一|马戴": {
    s: "首联「露气寒光集，微阳下楚丘」写露气寒光聚集、微阳落下楚丘，以「寒光」「微阳」写秋夜的清冷；颔联「猿啼洞庭树，人在木兰舟」是名句——猿在洞庭树上啼、人在木兰舟中，以「猿啼」写环境的凄清、以「人在舟」写游子的孤独，对仗工稳、意境苍凉；颈联「广泽生明月，苍山夹乱流」写广泽生明月、苍山夹乱流，以「明月」「乱流」写夜景的壮阔；尾联「云中君不降，竟夕自悲秋」写云神不降、整夜悲秋，以「悲秋」点题，全诗意境苍凉、对仗工稳，是晚唐五律的名篇。",
    b: "马戴这首诗写在楚江边、洞庭湖畔的秋夜景色，怀古伤今，是晚唐五律的名篇。",
    n: ["楚江怀古：在楚江边怀古（马戴，晚唐诗人）","露气寒光集：露气与寒光聚集","微阳下楚丘：微弱的夕阳落下楚地的山丘","洞庭树：洞庭湖边的树","木兰舟：木兰木做的船（船的美称）","广泽：广阔的水泽（指洞庭湖）","乱流：杂乱的水流","云中君：云神（《楚辞·九歌》有《云中君》）","竟夕：整夜"]
  },
  "灞上秋居|马戴": {
    s: "首联「灞原风雨定，晚见雁行频」写灞原风雨初定、傍晚见雁阵频飞，以「雁行频」写秋意与思乡；颔联「落叶他乡树，寒灯独夜人」是名句——他乡树上的落叶、寒灯前孤独的人，以「落叶」「寒灯」写环境的凄清、以「他乡」「独夜」写游子的孤独，对仗工稳、意境苍凉；颈联「空园白露滴，孤壁野僧邻」写空园白露滴、孤壁与野僧邻，以「空园」「孤壁」写居处的荒凉；尾联「寄卧郊扉久，何门致此身」写久居郊外、什么门路能出仕，以反问写失意，全诗意境苍凉、情感深沉，是晚唐五律的名篇。",
    b: "马戴这首诗写在灞上秋居的孤独与失意，是晚唐五律的名篇。",
    n: ["灞上：灞陵（在长安东）","灞原风雨定：灞原上的风雨停了","雁行频：雁阵频繁飞过","落叶他乡树：他乡树上的落叶","寒灯独夜人：寒灯前孤独的夜行人","空园白露滴：空园里白露滴落","孤壁野僧邻：孤壁旁与野僧为邻","郊扉：郊外的门（指自己的居处）","何门致此身：什么门路能让我出仕呢"]
  },
  "送李少府贬峡中王少府贬长沙|高适": {
    s: "首联「嗟君此别意何如，驻马衔杯问谪居」写感叹分别、停马饮酒问谪居，以「嗟」「问」写离情；颔联「巫峡啼猿数行泪，衡阳归雁几封书」是名句——巫峡猿啼使人落泪、衡阳归雁带来书信，以「巫峡」「衡阳」分别对应两位友人的贬所，对仗工稳、用典贴切；颈联「青枫江上秋天远，白帝城边古木疏」写青枫江秋远、白帝城古木疏，继续写两地景色；尾联「圣代即今多雨露，暂时分手莫踌躇」写当今圣明恩泽广、暂时分别不要犹豫，以宽慰作结，全诗情感真挚、对仗工稳，是盛唐送别七律的名篇。",
    b: "高适（盛唐边塞诗人）这首诗送两位友人分别被贬峡中和长沙，写离情与对友人的宽慰，是盛唐送别七律的名篇。",
    n: ["李少府贬峡中：李姓县尉被贬到峡中（三峡一带）","王少府贬长沙：王姓县尉被贬到长沙","嗟君此别意何如：感叹你们这次分别心情如何","驻马衔杯问谪居：停马饮酒问贬谪之地","巫峡啼猿数行泪：巫峡猿啼使人落泪","衡阳归雁几封书：衡阳归雁带来几封书信","青枫江：青枫江（在长沙）","白帝城：在今重庆奉节（三峡入口）","圣代：圣明的时代","雨露：皇帝的恩泽","踌躇：犹豫不前"]
  },
  "题菊花|黄巢": {
    s: "首两句「飒飒西风满院栽，蘂寒香冷蝶难来」写秋风萧瑟满院菊花、花蕊寒冷香气清冷蝴蝶难来，以「西风」「寒香」写菊花的孤寂；后两句「他年我若为青帝，报与桃花一处开」是名句——将来我如果做了掌管春天的青帝，就让菊花与桃花一起开放，以「青帝」的想象写改变命运的雄心，以「桃花一处开」写对平等的渴望，托物言志、气势豪迈，是黄巢诗的代表作，也预示了他后来的起义。",
    b: "黄巢这首《题菊花》以菊花自比，写菊花在寒风中开放、蝴蝶难来，表达改变命运的雄心，是咏物言志的名篇。",
    n: ["题菊花：题咏菊花（黄巢，唐末农民起义领袖）","飒飒西风：秋风萧瑟","蘂寒香冷蝶难来：花蕊寒冷香气清冷蝴蝶难来。蘂同「蕊」","他年我若为青帝：将来我如果做了青帝（青帝，神话中掌管春天的神）","报与桃花一处开：就让菊花与桃花一起开放"]
  },
  "不第后赋菊|黄巢": {
    s: "首两句「待到秋来九月八，我花开后百花杀」写等到九月初八、菊花开后百花凋谢，以「我花开」「百花杀」写菊花的压倒一切；后两句「冲天香阵透长安，满城尽带黄金甲」是千古名句——冲天的香气阵列浸透长安、满城都像披着黄金铠甲，以「冲天」「透长安」写气势的磅礴、以「黄金甲」写菊花的壮丽，想象奇特、气势豪迈，托物言志，预示了黄巢后来领导农民起义、攻入长安的雄心，是咏物诗中的千古名篇。",
    b: "黄巢科举落第后所作，以菊花的盛开写自己的雄心壮志，「满城尽带黄金甲」成为千古名句，是咏物言志的千古名篇。",
    n: ["不第后赋菊：科举落第后咏菊（黄巢）","待到秋来九月八：等到秋天九月初八（九月九重阳节前一天）","我花开后百花杀：菊花开后百花都凋谢了（我花，指菊花）","冲天香阵透长安：冲天的香气阵列浸透长安","满城尽带黄金甲：满城都像披着黄金铠甲（指菊花盛开如黄金甲）"]
  },
  "谒金门·风乍起|冯延巳": {
    s: "上片「风乍起，吹皱一池春水。闲引鸳鸯香径里，手挼红杏蕊」写风忽然吹起、吹皱一池春水，以「吹皱春水」比喻少妇心绪的不宁；闲来逗引鸳鸯、手揉红杏蕊，以「闲引」「手挼」写少妇的百无聊赖；下片「斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜」写独倚斗鸭栏杆、碧玉簪斜坠，以「独倚」「斜坠」写少妇的慵懒与孤独；终日望君君不至、抬头闻鹊喜，以「闻鹊喜」写在失望中又生希望，情感细腻，「风乍起，吹皱一池春水」成为千古名句。",
    b: "冯延巳（五代南唐词人，官至宰相）这首《谒金门》写闺中少妇思念丈夫的心情，「风乍起，吹皱一池春水」成为千古名句，是花间词的名篇。",
    n: ["谒金门：词牌名","风乍起：风忽然吹起","吹皱一池春水：吹皱了一池春水（名句，中主李璟曾戏问冯延巳「吹皱一池春水，干卿何事」）","闲引鸳鸯：闲来逗引鸳鸯","香径：充满花香的小路","手挼红杏蕊：手揉搓红杏花蕊。挼音ruó，揉搓","斗鸭阑干：斗鸭的栏杆（古代有斗鸭的游戏）","碧玉搔头：碧玉做的簪子。搔头，簪子","斜坠：斜斜地坠落","举头闻鹊喜：抬头听到喜鹊叫而欢喜（喜鹊叫预示喜事）"]
  },
  "鹊踏枝·谁道闲情抛掷久|冯延巳": {
    s: "上片「谁道闲情抛掷久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦」写谁说闲情抛掉了、每到春来惆怅依旧，天天花前醉酒、不辞朱颜消瘦，以「病酒」「朱颜瘦」写闲情的深；下片「河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后」写河畔青草堤上柳、试问新愁为何年年有，独立小桥风满袖、平林新月人归后，以「独立小桥」「风满袖」写孤独，以「平林新月」「人归后」写环境的清冷，意境深远，「独立小桥风满袖，平林新月人归后」成为千古名句，对后世影响深远。",
    b: "冯延巳这首《鹊踏枝》写闲情惆怅的缠绵，以「独立小桥风满袖」写孤独，是花间词向士大夫词过渡的名篇，对晏殊、欧阳修影响很大。",
    n: ["鹊踏枝：词牌名，即《蝶恋花》","谁道闲情抛掷久：谁说闲情已经抛掉很久了","惆怅还依旧：惆怅还是依旧","日日花前常病酒：天天在花前常常醉酒。病酒，醉酒","不辞镜里朱颜瘦：不推辞镜里红颜消瘦","河畔青芜堤上柳：河畔青草、堤上柳树。青芜，青草","为问新愁：试问新愁","何事年年有：为什么年年都有","独立小桥风满袖：独自站在小桥上风吹满袖","平林新月人归后：平林上新月升起、人归去后"]
  },
  "相见欢·林花谢了春红|李煜": {
    s: "上片「林花谢了春红，太匆匆。无奈朝来寒雨晚来风」写林花凋谢了春红、太匆匆，无奈朝来寒雨晚来风，以「林花谢」写美好事物的消逝、以「朝来寒雨晚来风」写摧残的频繁，既是写花也是写自己的亡国之痛；下片「胭脂泪，相留醉，几时重。自是人生长恨水长东」写胭脂般的泪水、相互挽留沉醉、何时再重逢，以「胭脂泪」写美人的悲泣、以「几时重」写重逢的无望，最后以「人生长恨水长东」的比喻作结——人生的长恨就像水永远向东流一样不可挽回，意境深远、情感沉痛，是李煜词的千古名篇。",
    b: "李煜（南唐后主）亡国后所作，以林花凋谢写人生长恨，是李煜词的千古名篇，「人生长恨水长东」成为千古名句。",
    n: ["相见欢：词牌名","林花谢了春红：林间的花凋谢了春天的红色","太匆匆：太匆匆忙忙了","无奈朝来寒雨晚来风：无奈早上寒雨晚上风","胭脂泪：胭脂般的泪水（指女子的泪，或指落花带雨如泪）","相留醉：相互挽留沉醉","几时重：什么时候再重逢","自是人生长恨水长东：人生本来就是长恨如水长向东流"]
  },
  "破阵子·四十年来家国|李煜": {
    s: "上片「四十年来家国，三千里地山河。凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈」写南唐四十年家国、三千里山河，凤阁龙楼连云霄、玉树琼枝如烟雾，几曾认识战争，以繁华的回忆与「几曾识干戈」的无知对比，写亡国的原因；下片「一旦归为臣虏，沈腰潘鬓消磨。最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥」写一旦做了俘虏、沈腰潘鬓消磨，最是仓皇辞庙那天、教坊还奏别离歌、垂泪对宫娥，以「仓皇辞庙」「教坊奏歌」「垂泪宫娥」三个细节写亡国的惨痛，以乐景写哀，情感沉痛，是李煜词的千古名篇。",
    b: "李煜亡国被俘后所作，回忆南唐的繁华与亡国的惨痛，以「最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥」写亡国之痛，是李煜词的千古名篇。",
    n: ["破阵子：词牌名","四十年来家国：南唐建国四十年（南唐937-975，约四十年）","三千里地山河：三千里地的山河","凤阁龙楼连霄汉：凤阁龙楼连接云霄。凤阁龙楼，指宫殿","玉树琼枝作烟萝：玉树琼枝像烟萝一样（指宫廷园林的珍奇花木）。烟萝，烟雾中的女萝","几曾识干戈：哪里认识战争。干戈，兵器，代指战争","一旦归为臣虏：一旦做了俘虏","沈腰潘鬓消磨：沈腰（沈约腰瘦）潘鬓（潘岳鬓白）都消磨了。沈同「沉」","仓皇辞庙：仓皇辞别宗庙","教坊犹奏别离歌：教坊还在奏别离歌。教坊，宫廷音乐机构","垂泪对宫娥：流着泪面对宫女"]
  },
  "摊破浣溪沙·菡萏香销翠叶残|李璟": {
    s: "上片「菡萏香销翠叶残，西风愁起绿波间。还与韶光共憔悴，不堪看」写荷花香销叶残、西风在绿波间起愁，与韶光一同憔悴、不堪看，以「菡萏香销」写秋景的萧瑟、以「韶光憔悴」写人的憔悴；下片「细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚阑干」写细雨中梦醒、边塞遥远，小楼上吹遍玉笙、笙声凄寒，多少泪珠无限恨、倚着栏杆，以「梦回鸡塞」写思念之深、以「玉笙寒」写心境的凄寒，「细雨梦回鸡塞远，小楼吹彻玉笙寒」成为千古名句，意境凄清、情感深沉，是南唐词的名篇。",
    b: "李璟（南唐中主，李煜之父）这首词写思妇思念征夫的愁情，「细雨梦回鸡塞远，小楼吹彻玉笙寒」成为千古名句，是南唐词的名篇。",
    n: ["摊破浣溪沙：词牌名（浣溪沙的变体）","菡萏香销翠叶残：荷花的香气消散、翠绿的荷叶残败。菡萏音hàndàn，荷花","西风愁起绿波间：西风在绿波间吹起愁意","还与韶光共憔悴：还与美好的时光一同憔悴。韶光，美好的时光","不堪看：不忍心看","细雨梦回鸡塞远：细雨中梦醒、鸡塞（鸡鹿塞，在今内蒙古，此指边塞）遥远","小楼吹彻玉笙寒：小楼上吹遍玉笙、笙声凄寒","多少泪珠何限恨：多少泪珠、无限怨恨","倚阑干：倚着栏杆"]
  },
  "长相思|万俟咏": {
    s: "上片「一声声。一更更。窗外芭蕉窗里灯。此时无限情」写雨声一声接一声、夜一更接一更，窗外芭蕉窗里灯，此时无限情，以「一声声」「一更更」的叠字写雨的绵密与夜的漫长；下片「梦难成。恨难平。不道愁人不喜听。空阶滴到明」写梦难成、恨难平，不管愁人不喜欢听，雨在空阶滴到天明，以「滴到明」写雨的整夜不停与愁人的彻夜难眠，全词以雨声贯穿，叠字运用巧妙，意境凄清，是写雨的名篇。",
    b: "万俟咏（北宋末南宋初词人）这首《长相思》写雨夜的愁思，以雨声贯穿全词，是写雨的名篇。",
    n: ["长相思：词牌名","一声声：一声接一声（指雨声）","一更更：一更接一更（指夜的漫长）","窗外芭蕉窗里灯：窗外的芭蕉、窗里的灯","此时无限情：此时有无限的情思","梦难成：梦难以做成","恨难平：怨恨难以平息","不道愁人不喜听：不管愁人不喜欢听","空阶滴到明：空荡的台阶上（雨）滴到天明"]
  },
  "卜算子|严蕊": {
    s: "上片「不是爱风尘，似被前身误。花落花开自有时，总是东君主」写不是喜爱风尘、似乎被前世耽误，花落花开自有时、总是由春神主宰，以「不是爱风尘」的辩白写自己的无奈、以「东君主」写命运的不由自主；下片「去也终须去。住也如何住。若得山花插满头，莫问奴归处」写离去终究要离去、留下又怎么留，如果能归隐山花插满头、不要问我的归宿，以「山花插满头」写对自由的向往、以「莫问奴归处」写对尊严的坚持，全词语言朴素、情感真挚，是宋词中少有的妓女自白，「不是爱风尘，似被前身误」成为名句。",
    b: "严蕊（南宋天台营妓，有才学）这首《卜算子》是她被朱熹陷害入狱后，在岳霖面前自陈身世之作，写自己的不幸与对自由的渴望，是宋词中少有的妓女自白词。",
    n: ["卜算子：词牌名","不是爱风尘：不是喜爱风尘（风尘，指妓女生活）","似被前身误：似乎是被前世耽误了","花落花开自有时：花落花开自然有时节","总是东君主：总是由东君（春神）主宰","去也终须去：离去终究要离去","住也如何住：留下又怎么能留下","若得山花插满头：如果能（归隐）把山花插满头","莫问奴归处：不要问我的归宿"]
  },
  "贺新郎|刘克庄": {
    s: "上片「国脉微如缕。问长缨、何时入手，缚将戎主。未必人间无好汉，谁与宽些尺度。试看取、当年韩五。岂有谷城公付授，也不干、曾遇骊山母。谈笑起，两河路」写国家命脉微弱如线，问长缨何时入手捆绑敌酋，未必人间无好汉、谁能放宽用人标准，看当年韩世忠，岂是有名师传授、遇过仙母，谈笑间在两河路起兵，以韩世忠为例呼吁用人；下片「少时棋柝曾联句。叹而今、登楼揽镜，事机频误。闻说北风吹面急，边上冲梯屡舞。君莫道、投鞭虚语。自古一贤能制难，有金汤、便可无张许。快投笔，莫题柱」写少年时曾联句，叹如今登楼揽镜、事机频误，听说北风急、边上云梯屡舞，莫道投鞭是虚语，自古一贤能制难，有金城汤池就可以没有张巡许远吗，快投笔从戎、莫追求功名，全词忧国忧民、呼吁抗金，气势豪迈，是南宋爱国词的名篇。",
    b: "刘克庄（南宋后期词人，「江湖派」领袖）这首《贺新郎》写国家危亡、呼吁用人抗金，是南宋爱国词的名篇。",
    n: ["贺新郎：词牌名","国脉微如缕：国家的命脉微弱如线","长缨：长绳（用终军「请缨」典故，指克敌立功）","缚将戎主：捆绑敌酋","宽些尺度：放宽些标准（指用人）","韩五：韩世忠（排行五，南宋抗金名将）","谷城公：黄石公（张良的老师，此指名师）","骊山母：骊山老母（传说中的女仙）","两河路：黄河两岸的路（指中原抗金前线）","棋柝：棋盘和打更的梆子（指少年时的游戏与联句）","登楼揽镜：登楼揽镜（指忧国伤时、揽镜自照）","冲梯：冲锋的云梯","投鞭：投鞭断流（前秦苻坚「投鞭于江，足断其流」，此指敌人兵力强大）","金汤：金城汤池（比喻坚固的城池）","张许：张巡、许远（安史之乱中死守睢阳的名将）","投笔：投笔从戎（班超典故）","题柱：题柱（司马相如题升仙桥柱，指追求功名）"]
  },
  "玉楼春|刘克庄": {
    s: "上片「年年跃马长安市。客舍似家家似寄。青钱换酒日无何，红烛呼庐宵不寐」写年年在长安跃马、客舍似家家似寄，青钱换酒整天无事、红烛呼卢通宵不睡，以「跃马」「换酒」「呼卢」写早年的游乐与放荡；下片「易挑锦妇机中字。难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪」写容易得到锦妇的回文、难得美人的心意，男儿西北有中原、不要为儿女私情流泪，以「西北有神州」的呼吁转折，从个人游乐转向爱国情怀，「男儿西北有神州，莫滴水西桥畔泪」成为名句，全词先抑后扬、气势豪迈，是南宋爱国词的名篇。",
    b: "刘克庄这首《玉楼春》写自己早年在京城的游乐生活，结尾以「男儿西北有神州，莫滴水西桥畔泪」呼吁爱国，是南宋爱国词的名篇。",
    n: ["玉楼春：词牌名","跃马长安市：在长安市跃马（指在京城游乐）","客舍似家家似寄：客舍像家、家像寄居的地方（指常年在外）","青钱换酒日无何：用青钱换酒、整天无所事事。日无何，整天无事","红烛呼庐宵不寐：红烛下呼卢（赌博）通宵不睡。呼卢，赌博时的呼叫","锦妇机中字：锦妇（苏蕙）织在锦上的字（苏蕙织回文锦寄丈夫窦滔的典故）","玉人心下事：美人心中的事","西北有神州：西北有中原（指沦陷的中原）","水西桥畔泪：水西桥边的泪（指为儿女私情流泪）"]
  },
  "沁园春|刘过": {
    s: "上片「斗酒彘肩，风雨渡江，岂不快哉。被香山居士，约林和靖，与东坡老，驾勒吾回。坡谓西湖，正如西子，浓抹淡妆临镜台。二公者，皆掉头不顾，只管衔杯」写斗酒彘肩、风雨渡江岂不快哉，却被白居易约林逋、苏轼拉马回去，苏轼说西湖正如西施、浓抹淡妆临镜台，二公掉头不顾只管喝酒，想象三位古人对话；下片「白云天竺飞来。图画里、峥嵘楼观开。爱东西双涧，纵横水绕，两峰南北，高下云堆。逋曰不然，暗香浮动，争似孤山先探梅。须晴去，访稼轩未晚，且此俳徊」写白云天竺飞来、图画里楼观峥嵘，爱东西双涧水绕、两峰南北云堆，林逋说不然、暗香浮动怎比孤山探梅，等天晴去访辛弃疾也不晚、且在此徘徊，全词想象三位古人对话、各言西湖之美，构思奇特、用典丰富，是宋词中别具一格的名篇。",
    b: "刘过（南宋词人，辛弃疾的朋友）这首《沁园春》是他去拜访辛弃疾的路上，想象白居易、林逋、苏轼三位西湖诗人拉他回去赏西湖，构思奇特，是宋词中别具一格的名篇。",
    n: ["沁园春：词牌名","斗酒彘肩：一斗酒、一只猪肘（樊哙在鸿门宴上的故事，此指豪情）","风雨渡江：风雨中渡江","香山居士：白居易（号香山居士）","林和靖：林逋（字和靖，北宋隐士，隐居西湖孤山）","东坡老：苏轼（号东坡居士）","驾勒吾回：拉着马让我回去","西湖正如西子：西湖正像西施（苏轼「欲把西湖比西子」）","浓抹淡妆临镜台：浓抹淡妆对着镜台（苏轼「淡妆浓抹总相宜」）","天竺飞来：天竺山飞来（飞来峰，在西湖灵隐寺前）","东西双涧：东西两条山涧","两峰南北：南北两高峰","暗香浮动：暗香浮动（林逋「疏影横斜水清浅，暗香浮动月黄昏」）","孤山先探梅：先到孤山探梅","稼轩：辛弃疾（号稼轩）","俳徊：徘徊。俳同「徘」"]
  },
  "唐多令|刘过": {
    s: "上片「芦叶满汀洲。塞沙带浅流。二十年、重过南楼。柳下系舟犹未稳，能几日、又中秋」写芦叶满汀洲、塞沙带浅流，二十年后重过南楼，柳下系船未稳、能几日又中秋，以「二十年」「又中秋」写时间的流逝；下片「黄鹤断矶头。故人今不在。旧江山，浑是新愁。欲买桂花同载酒，终不似、少年游」写黄鹤矶头、故人不在，旧江山全是新愁，想买桂花载酒、终不像少年游，以「故人不在」「旧江山新愁」写物是人非、家国之痛，以「终不似少年游」写青春不再的感慨，全词情感深沉、意境苍凉，「欲买桂花同载酒，终不似、少年游」成为千古名句。",
    b: "刘过这首《唐多令》写二十年后重过武昌南楼，物是人非、江山易主的愁情，「终不似、少年游」成为名句，是南宋婉约词的名篇。",
    n: ["唐多令：词牌名","芦叶满汀洲：芦叶满了水边平地","塞沙带浅流：边塞的沙地带着浅流","二十年、重过南楼：二十年后重过南楼（南楼，在武昌，刘过曾与友人游此）","柳下系舟犹未稳：柳下系船还没稳","能几日、又中秋：能过几天又到中秋","黄鹤断矶头：黄鹤矶的尽头（黄鹤矶，在武昌黄鹤楼旁）","故人今不在：老朋友如今不在了","旧江山，浑是新愁：旧江山全是新愁","欲买桂花同载酒：想买桂花一同载酒","终不似、少年游：终究不像少年时的游乐"]
  },
  "双双燕|史达祖": {
    s: "上片「过春社了，度帘幕中间，去年尘冷。差池欲住，试入旧巢相并。还相雕梁藻井。又软语、商量不定。飘然快拂花梢，翠尾分开红影」写春社过后、燕子穿过帘幕、去年巢穴尘冷，差池欲住、试入旧巢相并，相看雕梁藻井、软语商量不定，飘然快拂花梢、翠尾分开红影，以细腻的笔触写燕子归巢的全过程；下片「芳径。芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。应自栖香正稳。便忘了、天涯芳信。愁损翠黛双蛾，日日画阑独凭」写芳径芹泥雨润、贴地争飞竞夸轻俊，红楼归晚、看足柳昏花暝，栖香正稳、忘了天涯芳信，愁损翠黛双蛾、日日画阑独凭，以燕子的双飞快乐反衬思妇的孤独，全词咏物而不滞于物，以燕写人，是咏物词的千古名篇。",
    b: "史达祖（南宋词人，「婉约派」代表）这首《双双燕》是咏燕词的千古名篇，以燕子的归巢、筑巢、双飞写闺中思妇的孤独，是咏物词的典范。",
    n: ["双双燕：词牌名（史达祖自度曲）","春社：春社日（祭祀土地神的日子，燕子春社来、秋社去）","度帘幕中间：穿过帘幕中间","去年尘冷：去年的巢穴尘土冰冷","差池：燕子羽毛参差不齐的样子（《诗经》「燕燕于飞，差池其羽」）","雕梁藻井：雕花的梁、画有花纹的天花板。藻井，天花板上的装饰","软语商量：柔声商量","花梢：花的顶端","翠尾分开红影：翠绿的尾羽分开红色的花影","芹泥雨润：芹菜地的泥土被雨滋润（燕子衔芹泥筑巢）","贴地争飞：贴着地面争飞","红楼归晚：回到红楼晚了","柳昏花暝：柳树昏暗、花影朦胧。暝音míng，昏暗","栖香正稳：在香巢中安稳栖息","天涯芳信：远方的书信（古人认为燕子能传信）","愁损翠黛双蛾：愁坏了画眉的双眉。翠黛，画眉的颜料；蛾，蛾眉","画阑独凭：独自靠着画栏"]
  },
  "水调歌头|叶梦得": {
    s: "上片「秋色渐将晚，霜信报黄花。小窗低户深映，微路绕敧斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞」写秋色渐晚、霜信报黄花，小窗低户深映、小路绕倾斜，问山翁何事、坐看流年轻度、不顾双鬓花白，徘徊望沧海、天净水明霞，写归隐生活的清幽与对流年虚度的感慨；下片「念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，冉冉云间新雁，边马怨胡笳。谁似东山老，谈笑静胡沙」写念平生空飘荡遍天涯，归来三径重扫、松竹本吾家，却恨悲风起、云间新雁、边马怨胡笳，谁像谢安那样谈笑间平定胡沙，以「东山老」的典故呼吁抗金，全词由归隐到忧国，意境开阔，是南宋爱国词的名篇。",
    b: "叶梦得（南宋词人）这首《水调歌头》写晚年归隐的生活与对国事的忧虑，以「谁似东山老，谈笑静胡沙」呼吁抗金，是南宋爱国词的名篇。",
    n: ["水调歌头：词牌名","霜信报黄花：霜的信息报给菊花（指霜降菊开）","敧斜：倾斜。敧音qī","山翁：山翁（指自己，或指隐士）","流年轻度：轻易度过流年","拚却鬓双华：不顾双鬓花白。拚音pàn，不顾","徙倚：徘徊。徙音xǐ","沧海：大海","三径：三条小路（用蒋诩「三径」典故，指归隐后的家园）","冉冉：慢慢的样子","边马怨胡笳：边地的马怨恨胡笳声。胡笳，北方少数民族乐器","东山老：谢安（隐居东山，此指有才能的隐士）","谈笑静胡沙：谈笑间平定胡人（胡沙，指北方少数民族的侵扰）"]
  },
  "夜书所见|叶绍翁": {
    s: "首两句「萧萧梧叶送寒声，江上秋风动客情」写萧萧梧叶送寒声、江上秋风动客情，以「梧叶」「秋风」写秋意、以「客情」写游子的思乡；后两句「知有儿童挑促织，夜深篱落一灯明」是名句——知道有儿童在挑蟋蟀、夜深篱笆边一盏灯明，以儿童挑促织的欢乐反衬游子的孤独，以乐景写哀，「夜深篱落一灯明」的画面温馨而乡愁更深，全诗语言朴素、意境深远，是南宋七绝的名篇。",
    b: "叶绍翁（南宋诗人）这首小诗写秋夜所见，以儿童挑促织的乐景反衬游子的孤独，是南宋七绝的名篇。",
    n: ["夜书所见：夜晚写下所见","萧萧梧叶送寒声：萧萧的梧桐叶送来寒冷的声音","江上秋风动客情：江上的秋风触动了游子的情思","知有儿童挑促织：知道有儿童在挑促织（蟋蟀）。促织，蟋蟀","夜深篱落一灯明：夜深了篱笆边一盏灯明"]
  },
  "孙权劝学|司马光": {
    s: "全文分两层：第一层写孙权劝学——孙权对吕蒙说「卿今当涂掌事，不可不学」，吕蒙以军中多务推辞，孙权说「孤岂欲卿治经为博士邪！但当涉猎，见往事耳」，并以自己「常读书，自以为大有所益」现身说法，吕蒙乃始就学；第二层写吕蒙就学后的变化——鲁肃过寻阳，与蒙论议，大惊曰「卿今者才略，非复吴下阿蒙」，吕蒙曰「士别三日，即更刮目相待，大兄何见事之晚乎」，肃遂拜蒙母、结友而别。全文以对话为主，语言精炼，「吴下阿蒙」「士别三日，刮目相待」成为千古成语，是叙事散文的典范。",
    b: "司马光《资治通鉴》中的这篇《孙权劝学》写孙权劝吕蒙学习、吕蒙就学后才略大进的故事，「士别三日，即更刮目相待」「吴下阿蒙」成为成语，是中国古代叙事散文的名篇。",
    n: ["孙权劝学：孙权劝吕蒙学习（选自《资治通鉴》）","当涂掌事：当权管事。当涂，当道、当权","辞以军中多务：以军中事务多推辞","治经为博士：研究经典做博士（专掌经学传授的学官）","但当涉猎：只应当广泛浏览。涉猎，广泛浏览","见往事耳：了解历史罢了","孰若孤：谁比得上我。孤，古代王侯的自称","及鲁肃过寻阳：等到鲁肃经过寻阳","才略：才干和谋略","非复吴下阿蒙：不再是吴下的阿蒙了（阿蒙，吕蒙的昵称）","士别三日：读书人分别三天","即更刮目相待：就应当另眼相看。刮目，擦眼睛，指另眼相看","大兄何见事之晚乎：长兄怎么认清事物这么晚呢","拜蒙母：拜见吕蒙的母亲","结友而别：结为朋友才分别"]
  },
  "采桑子|吕本中": {
    s: "全词以「江楼月」为喻，正反两面写：上片「恨君不似江楼月，南北东西。只有相随无别离」写恨你不像江楼月——月亮南北东西都在、只有相随没有别离，以月的「相随无别离」反衬人的别离；下片「恨君却似江楼月，暂满还亏。暂满还亏。待得团团是几时」写恨你却像江楼月——暂时圆满又亏缺，等到团圆是什么时候，以月的「暂满还亏」比喻人的聚少离多，全词以月为喻，一正一反，构思巧妙，「恨君不似」「恨君却似」的对比写尽思妇的矛盾心理，是宋词中的名篇。",
    b: "吕本中（南宋词人）这首《采桑子》以江楼月为喻，写思妇对丈夫的思念，构思巧妙，是宋词中的名篇。",
    n: ["采桑子：词牌名","恨君不似江楼月：遗憾你不像江楼上的月亮","南北东西：（月亮）南北东西（都在）","只有相随无别离：只有相随没有别离","恨君却似江楼月：遗憾你却像江楼上的月亮","暂满还亏：暂时圆满又亏缺","待得团团是几时：等到团圆是什么时候"]
  },
  "南歌子|吕本中": {
    s: "上片「驿路侵斜月，溪桥度晓霜。短篱残菊一枝黄。正是乱山深处、过重阳」写驿路斜月、溪桥晓霜，短篱残菊一枝黄，正是乱山深处过重阳，以「斜月」「晓霜」「残菊」写旅途的凄清、以「乱山深处过重阳」写游子的孤独；下片「旅枕元无梦，寒更每自长。只言江左好风光。不道中原归思、转凄凉」写旅枕无梦、寒更长，只说江左风光好，不说中原归思转凄凉，以「中原归思」写家国之痛，全词由个人旅思转向家国之痛，意境苍凉，是南宋爱国词的名篇。",
    b: "吕本中这首《南歌子》写在乱山深处过重阳的旅思，以「中原归思」写家国之痛，是南宋爱国词的名篇。",
    n: ["南歌子：词牌名","驿路侵斜月：驿路沐浴在斜月中","溪桥度晓霜：走过溪桥上的晓霜","短篱残菊一枝黄：短篱笆边一枝残菊黄","乱山深处、过重阳：在乱山深处过重阳节","旅枕元无梦：旅枕上本来无梦。元同「原」","寒更每自长：寒夜的更声每次都显得长","只言江左好风光：只说江左（江南）风光好","不道中原归思、转凄凉：不说中原的归思转而凄凉"]
  },
  "齐天乐|吴文英": {
    s: "上片「三千年事残鸦外，无言倦凭秋树。逝水移川，高陵变谷，那识当时神禹。幽云怪雨。翠萍湿空梁，夜深飞去。雁起青天，数行书似旧藏处」写三千年往事在残鸦外、无言倦凭秋树，逝水移川、高陵变谷、哪识当时大禹，幽云怪雨、翠萍湿空梁、夜深飞去，雁起青天、几行字似旧藏处，以大禹治水的历史与禹庙的神秘写怀古；下片「寂寥西窗久坐，故人悭会遇，同翦灯语。积藓残碑，零圭断璧，重拂人间尘土。霜红罢舞。漫山色青青，雾朝烟暮。岸锁春船，画旗喧赛鼓」写寂寥西窗久坐、故人少会、同剪灯语，积藓残碑、零圭断璧、重拂尘土，霜红罢舞、山色青青、雾朝烟暮，岸锁春船、画旗喧赛鼓，以友人相聚与禹庙文物写今昔之感，全词用典丰富、意象密丽，是吴文英词的代表作。",
    b: "吴文英（南宋词人，「梦窗词」代表，格律派）这首《齐天乐》写与友人游禹庙、怀古伤今，是吴文英词的名篇，以密丽深涩的风格著称。",
    n: ["齐天乐：词牌名","三千年事残鸦外：三千年的往事在残鸦之外（指历史久远）","无言倦凭秋树：无言疲倦地靠着秋树","逝水移川：流逝的水改变了河道","高陵变谷：高山变成了深谷（指世事变迁）","神禹：大禹（治水的大禹）","幽云怪雨：幽暗的云、怪异的雨","翠萍湿空梁：翠绿的浮萍沾湿了空梁（传说禹庙梁上有龙，能致云雨）","夜深飞去：夜深时飞去","雁起青天：大雁从青天飞起","数行书似旧藏处：几行字像旧藏书的地方（雁阵如字）","西窗久坐：西窗久坐","故人悭会遇：故人少相会。悭音qiān，少","同翦灯语：一同剪灯夜话。翦同「剪」","积藓残碑：积满苔藓的残碑","零圭断璧：零碎的圭、断裂的璧（指残缺的文物）。圭音guī","重拂人间尘土：重新拂去人间的尘土","霜红罢舞：霜红的叶子停止飞舞","漫山色青青：空有山色青青","岸锁春船：岸边锁着春船","画旗喧赛鼓：画旗喧闹、赛鼓声响（赛神的鼓）"]
  },
  "风入松|吴文英": {
    s: "上片「听风听雨过清明。愁草瘗花铭。楼前绿暗分携路，一丝柳、一寸柔情。料峭春寒中酒，交加晓梦啼莺」写听风听雨过清明、愁写葬花铭，楼前绿暗分别路、一丝柳一寸柔情，料峭春寒中酒、晓梦啼莺，以「清明」「葬花」「分携」写离别与思念；下片「西园日日扫林亭。依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生」写西园日日扫林亭、依旧赏新晴，黄蜂频频扑秋千绳、有当时纤手的香气凝聚，惆怅双鸳不到、幽阶一夜苔生，以「黄蜂扑秋千索」的想象写思念之深——秋千索上似乎还留着情人纤手的香气，连黄蜂都被吸引，想象奇特、情感深挚，「黄蜂频扑秋千索，有当时、纤手香凝」成为名句，全词意境凄清、想象奇特，是吴文英词的名篇。",
    b: "吴文英这首《风入松》写清明时节思念情人，以「黄蜂频扑秋千索，有当时、纤手香凝」的想象写思念之深，是吴文英词的名篇。",
    n: ["风入松：词牌名","听风听雨过清明：听风听雨过了清明节","愁草瘗花铭：愁闷中写葬花铭。瘗音yì，埋葬；铭，文体","楼前绿暗分携路：楼前绿荫浓密的分别路。分携，分别","一丝柳、一寸柔情：一丝柳、一寸柔情","料峭春寒中酒：微寒的春寒中醉酒。料峭，微寒","交加晓梦啼莺：交错的晓梦中黄莺啼叫","西园日日扫林亭：西园天天扫林亭","依旧赏新晴：依旧欣赏新晴","黄蜂频扑秋千索：黄蜂频频扑向秋千绳","有当时、纤手香凝：有当时纤手的香气凝聚","惆怅双鸳不到：惆怅鸳鸯（指情人的鞋）不到","幽阶一夜苔生：幽静的台阶一夜长满青苔"]
  },
  "八声甘州|吴文英": {
    s: "上片「渺空烟四远，是何年、青天坠长星。幻苍崖云树，名娃金屋，残霸宫城。箭径酸风射眼，腻水染花腥。时靸双鸳响，廊叶秋声」写空烟四远、何年青天坠长星，幻化出苍崖云树、名娃金屋、残霸宫城，箭径酸风刺眼、腻水染花腥，时靸双鸳响、廊叶秋声，以吴王夫差与西施的遗迹写历史的沧桑；下片「宫里吴王沈醉，倩五湖倦客，独钓醒醒。问苍波无语，华发奈山青。水涵空、阑干高处，送乱鸦、斜日落渔汀。连呼酒，上琴台去，秋与云平」写宫里吴王沉醉、请五湖倦客范蠡独钓醒醒，问苍波无语、华发奈山青，水涵空阑干高处、送乱鸦斜日落渔汀，连呼酒上琴台、秋与云平，以吴王的沉醉与范蠡的清醒对比，以「秋与云平」的开阔意境作结，全词怀古伤今、意境开阔，是吴文英词的千古名篇。",
    b: "吴文英这首《八声甘州》是游苏州灵岩山（吴王夫差与西施的遗迹）时所作，借吴越兴亡的历史写怀古伤今，是吴文英词的千古名篇。",
    n: ["八声甘州：词牌名","渺空烟四远：渺茫的空烟向四方远去","青天坠长星：青天坠下长星（指灵岩山如长星坠地）","幻苍崖云树：幻化出苍崖云树","名娃金屋：名娃（西施）的金屋","残霸宫城：残霸（吴王夫差）的宫城","箭径酸风射眼：箭径（采香径）的酸风刺眼。酸风，刺眼的风","腻水染花腥：腻水（宫女梳洗的水）染花带腥","时靸双鸳响：不时传来拖鞋的声音。靸音sǎ，拖鞋；双鸳，鸳鸯鞋","廊叶秋声：廊下的叶声（响屧廊，吴王宫中的廊，西施穿木屐走过会响）","宫里吴王沈醉：宫里吴王沉醉","倩五湖倦客：请五湖倦客（范蠡，助越灭吴后泛舟五湖）。倩音qìng，请","独钓醒醒：独自垂钓、清醒着","问苍波无语：问苍波无语","华发奈山青：白发无奈山青","水涵空：水包含天空","阑干高处：栏杆高处","送乱鸦、斜日落渔汀：送乱鸦、斜日落在渔汀。汀音tīng，水边平地","连呼酒：连连呼酒","上琴台去：上琴台去（琴台，在灵岩山，西施弹琴处）","秋与云平：秋意与云平"]
  },
  "唐多令|吴文英": {
    s: "上片「何处合成愁。离人心上秋。纵芭蕉、不雨也飕飕。都道晚凉天气好，有明月、怕登楼」写愁字怎么合成、离人的心上有秋（拆字「愁=秋+心」），纵然芭蕉不下雨也飕飕响，都说晚凉天气好、有明月怕登楼，以拆字手法写离愁、以「怕登楼」写思乡；下片「年事梦中休。花空烟水流。燕辞归、客尚淹留。垂柳不萦裙带住，漫长是、系行舟」写年事梦中休、花空烟水流，燕辞归客尚淹留，垂柳不缠住情人的裙带、却总是系住行舟，以「垂柳不萦裙带、却系行舟」的对比写离愁，全词构思巧妙、语言明快，「何处合成愁，离人心上秋」成为名句，是吴文英词中别具一格的作品。",
    b: "吴文英这首《唐多令》写离愁，以「何处合成愁，离人心上秋」的拆字手法开篇，是吴文英词中少有的疏朗明快之作。",
    n: ["唐多令：词牌名","何处合成愁：愁字怎么合成（「愁」=「秋」+「心」）","离人心上秋：离人的心上有秋（拆字：愁=秋+心）","纵芭蕉、不雨也飕飕：纵然芭蕉不下雨也飕飕响。飕飕，风声","都道晚凉天气好：都说晚凉天气好","有明月、怕登楼：有明月、怕登楼","年事梦中休：年事在梦中结束","花空烟水流：花空了、烟水流逝","燕辞归、客尚淹留：燕子辞别归去、客子还滞留。淹留，滞留","垂柳不萦裙带住：垂柳不缠住裙带（指情人）。萦音yíng，缠绕","漫长是、系行舟：总是系住行舟"]
  },
  "鹧鸪天|周紫芝": {
    s: "上片「一点残红欲尽时。乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离」写残灯将尽、秋气满屏帏，梧桐叶上三更雨、叶叶声声是别离，以「三更雨」「叶叶声声」写离愁的绵密；下片「调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂」写调宝瑟、拨金猊，那时同唱鹧鸪词，如今风雨西楼夜、不听清歌也泪垂，以「那时同唱」与「如今泪垂」对比，写物是人非的感慨，全词意境凄清、情感深沉，「梧桐叶上三更雨，叶叶声声是别离」成为名句。",
    b: "周紫芝（南宋词人）这首《鹧鸪天》写秋夜思念情人，以「梧桐叶上三更雨，叶叶声声是别离」写离愁，是宋词中的名篇。",
    n: ["鹧鸪天：词牌名","一点残红欲尽时：一点残灯将尽时","乍凉秋气满屏帏：刚凉的秋气充满屏帏。屏帏，屏风和帷帐","梧桐叶上三更雨：梧桐叶上三更的雨","叶叶声声是别离：每叶每声都是别离","调宝瑟：调弄宝瑟","拨金猊：拨弄金猊（金狮形的香炉）。猊音ní","那时同唱鹧鸪词：那时一同唱鹧鸪词","如今风雨西楼夜：如今风雨西楼的夜晚","不听清歌也泪垂：不听清歌也流泪"]
  },
  "满庭芳|周邦彦": {
    s: "上片「风老莺雏，雨肥梅子，午阴嘉树清圆。地卑山近，衣润费垆烟。人静乌鸢自乐，小桥外、新绿溅溅。凭栏久，黄芦苦竹，拟泛九江船」写风老莺雏、雨肥梅子、午阴嘉树清圆，地卑山近、衣润费炉烟，人静乌鸢自乐、小桥外新绿溅溅，凭栏久、黄芦苦竹、拟泛九江船，以江南夏景写羁旅之愁；下片「年年。如社燕，飘流瀚海，来寄修椽。且莫思身外，长近尊前。憔悴江南倦客，不堪听、急管繁弦。歌筵畔，先安簟枕，容我醉时眠」写年年如社燕、飘流瀚海、来寄修椽，且莫思身外、长近尊前，憔悴江南倦客、不堪听急管繁弦，歌筵畔先安簟枕、容我醉时眠，以社燕自比、以醉眠排遣，全词意境清丽、情感深沉，「风老莺雏，雨肥梅子」成为名句，是周邦彦词的名篇。",
    b: "周邦彦（北宋词人，「婉约派」集大成者，格律派创始人）这首《满庭芳》写在溧水（今江苏溧水）任上的羁旅之愁，以「且莫思身外，长近尊前」写自我排遣，是周邦彦词的名篇。",
    n: ["满庭芳：词牌名","风老莺雏：春风使莺雏长大","雨肥梅子：雨使梅子肥美","午阴嘉树清圆：正午的树荫下嘉树清圆","地卑山近：地势低、靠近山","衣润费垆烟：衣服湿润费炉烟（烤衣服）。垆同「炉」","人静乌鸢自乐：人静时乌鸦鸢鸟自乐。鸢音yuān","新绿溅溅：新绿的水溅溅响。溅溅音jiānjiān，水流声","黄芦苦竹：黄芦和苦竹（白居易《琵琶行》「黄芦苦竹绕宅生」）","拟泛九江船：打算泛九江的船","社燕：春社时来的燕子","飘流瀚海：飘流到瀚海（北方大沙漠，此指遥远）","来寄修椽：来寄居在长椽下。椽音chuán，椽子","且莫思身外：且不要想身外之事","长近尊前：长在酒杯前。尊同「樽」","憔悴江南倦客：憔悴的江南倦客","急管繁弦：急促的管乐、繁复的弦乐","歌筵畔：歌筵旁","先安簟枕：先安好竹席和枕头。簟音diàn，竹席","容我醉时眠：让我醉时眠"]
  },
  "苏幕遮|周邦彦": {
    s: "上片「燎沈香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举」写焚沉香消溽暑，鸟雀呼晴、侵晓窥檐语，叶上初阳干宿雨、水面清圆、一一风荷举，以「风荷举」写荷叶的挺立，「一一」写出荷叶的层次，是写荷花的千古名句；下片「故乡遥，何日去。家住吴门，久作长安旅。五月渔郎相忆否。小楫轻舟，梦入芙蓉浦」写故乡遥、何日去，家住吴门、久作长安旅，五月渔郎相忆否，小楫轻舟、梦入芙蓉浦，以荷塘景色引发思乡，以「梦入芙蓉浦」写对故乡的思念，全词由景入情、过渡自然，「叶上初阳干宿雨，水面清圆，一一风荷举」成为千古名句。",
    b: "周邦彦这首《苏幕遮》写夏日荷塘景色与思乡之情，「叶上初阳干宿雨，水面清圆，一一风荷举」是写荷花的千古名句，王国维评为「真能得荷之神理者」。",
    n: ["苏幕遮：词牌名","燎沈香：焚烧沉香。沈同「沉」","消溽暑：消除潮湿的暑气。溽音rù，潮湿","鸟雀呼晴：鸟雀呼唤晴天","侵晓窥檐语：破晓时在屋檐下窥看鸣叫。侵晓，破晓","叶上初阳干宿雨：叶上的初阳晒干了昨夜的雨","水面清圆：水面上的荷叶清圆","一一风荷举：一片一片风中的荷叶挺立。举，挺立","故乡遥，何日去：故乡遥远，何时归去","家住吴门：家住在吴门（苏州）","久作长安旅：长久在长安做客","五月渔郎相忆否：五月的渔郎还记得我吗","小楫轻舟：小桨轻舟","梦入芙蓉浦：梦中进入荷花塘。芙蓉浦，荷花塘"]
  },
  "齐天乐|周邦彦": {
    s: "上片「绿芜凋尽台城路，殊乡又逢秋晚。暮雨生寒，鸣蛩劝织，深阁时闻裁剪。云窗静掩。叹重拂罗裀，顿疏花簟。尚有𦈌囊，露萤清夜照书卷」写绿芜凋尽台城路、殊乡又逢秋晚，暮雨生寒、鸣蛩劝织、深阁闻裁剪，云窗静掩，重拂罗裀、顿疏花簟，尚有𦈌囊、露萤清夜照书卷，以秋景与物候写羁旅之愁；下片「荆江留滞最久，故人相望处，离思何限。渭水西风，长安乱叶，空忆诗情宛转。凭高眺远。正玉液新𥬠，蟹螯初荐。醉倒山翁，但愁斜照敛」写荆江留滞最久、故人相望、离思何限，渭水西风、长安乱叶、空忆诗情宛转，凭高眺远，玉液新𥬠、蟹螯初荐，醉倒山翁、但愁斜照敛，以故人之思与醉饮排遣，全词用典丰富（车胤囊萤、贾岛秋风、山简醉酒）、格律精严，是周邦彦词的名篇。",
    b: "周邦彦这首《齐天乐》写在异乡逢秋晚的羁旅之愁与对故人的思念，用典丰富、格律精严，是周邦彦词的名篇。",
    n: ["齐天乐：词牌名","绿芜凋尽台城路：绿草凋尽的台城路（台城，六朝宫城，在南京）","殊乡又逢秋晚：在异乡又逢秋晚","暮雨生寒：暮雨生寒","鸣蛩劝织：蟋蟀鸣叫像劝人织布。蛩音qióng，蟋蟀","深阁时闻裁剪：深阁中不时听到裁剪声","云窗静掩：云窗静掩","重拂罗裀：重拂罗褥。裀音yīn，褥子","顿疏花簟：顿时疏远了花竹席。簟音diàn","𦈌囊：粗布袋。𦈌音shū，粗布","露萤清夜照书卷：露水中的萤火虫在清夜照书卷（车胤囊萤读书典故）","荆江留滞最久：在荆江（今湖北一带）留滞最久","故人相望处：故人相望的地方","离思何限：离思无限","渭水西风：渭水的西风（贾岛「秋风生渭水」）","长安乱叶：长安的乱叶","空忆诗情宛转：空忆诗情宛转","凭高眺远：登高眺远","玉液新𥬠：新酿的美酒。𥬠音chōu，滤酒","蟹螯初荐：蟹螯初上桌。蟹螯，螃蟹的大钳","醉倒山翁：醉倒山翁（山简，晋代人，常醉倒）","但愁斜照敛：只愁夕阳收敛"]
  },
  "少年游|周邦彦": {
    s: "上片「并刀如水，吴盐胜雪，纤手破新橙。锦幄初温，兽烟不断，相对坐调笙」写并刀如水、吴盐胜雪、纤手破新橙，锦幄初温、兽烟不断、相对坐调笙，以「破新橙」「调笙」的细节写幽会的温情；下片「低声问向谁行宿，城上已三更。马滑霜浓，不如休去，直是少人行」写低声问今晚到哪里住宿、城上已三更，马滑霜浓、不如休去、只是少人行，以「低声问」的对话写情人的挽留，语言朴素、细节生动，全词以白描手法写幽会的温情，「并刀如水，吴盐胜雪，纤手破新橙」成为名句，是周邦彦词的名篇。",
    b: "周邦彦这首《少年游》写与情人的幽会，以「并刀如水，吴盐胜雪，纤手破新橙」的细节写温情，是周邦彦词的名篇，传说与宋徽宗、李师师的故事有关。",
    n: ["少年游：词牌名","并刀如水：并州的剪刀如水般锋利。并刀，并州（今山西太原）产的剪刀，以锋利著称","吴盐胜雪：吴地的盐胜过雪（吴盐，吴地产的盐，洁白）","纤手破新橙：纤手剥开新橙","锦幄初温：锦制的帷幕刚温暖。幄音wò，帷幕","兽烟不断：兽形香炉的烟不断","相对坐调笙：相对坐着调笙","低声问向谁行宿：低声问今晚到哪里住宿。谁行，哪里、哪边","城上已三更：城上已三更","马滑霜浓：马滑霜浓","不如休去：不如不要去","直是少人行：只是少人行"]
  },
  "解语花|周邦彦": {
    s: "上片「风销焰蜡，露浥烘炉。花市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女、纤腰一把。箫鼓喧，人影参差，满路飘香麝」写风销蜡烛、露沾花灯，花市光相射，桂华流瓦、纤云散、素娥欲下，衣裳淡雅、楚女纤腰，箫鼓喧、人影参差、满路飘香麝，以元宵夜景的繁华写节日的热闹；下片「因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢」写因念都城放夜、千门如昼、嬉笑游冶，钿车罗帕、相逢处暗尘随马，年光是也、旧情衰谢，清漏移、飞盖归来、从舞休歌罢，以元宵的繁华反衬旧情的衰谢，全词意境繁华、情感深沉，是咏元宵的名篇。",
    b: "周邦彦这首《解语花》写元宵节的盛况，以「桂华流瓦」「人影参差」写元宵夜景，是咏元宵的名篇。",
    n: ["解语花：词牌名（周邦彦自度曲）","风销焰蜡：风消蜡烛的焰","露浥烘炉：露沾湿了烘炉（指花灯）。浥音yì，沾湿","花市光相射：花市的灯光相互照射","桂华流瓦：月光流洒在瓦上。桂华，月光（传说月中有桂）","纤云散：纤云散去","耿耿素娥欲下：明亮的嫦娥想下来。素娥，嫦娥","楚女纤腰一把：楚女的纤腰一把（形容腰细）","箫鼓喧：箫鼓喧闹","人影参差：人影参差不齐","满路飘香麝：满路飘香麝香","都城放夜：都城开放夜市（元宵夜开宵禁）","千门如昼：千门如白昼","嬉笑游冶：嬉笑游乐","钿车罗帕：饰金的车、罗帕","相逢处：相逢的地方","自有暗尘随马：自有暗尘随马（苏味道「暗尘随马去」）","年光是也：年光还是这样","旧情衰谢：旧情衰谢","清漏移：清漏移动（指时间流逝）","飞盖归来：飞车归来。盖，车盖，代指车","从舞休歌罢：任舞休歌罢"]
  },
  "花犯|周邦彦": {
    s: "上片「粉墙低，梅花照眼，依然旧风味。露痕轻缀。疑净洗铅华，无限佳丽。去年胜赏曾孤倚。冰盘同宴喜。更可惜，雪中高树，香篝熏素被」写粉墙低、梅花照眼、依然旧风味，露痕轻缀、净洗铅华、无限佳丽，去年胜赏曾孤倚、冰盘同宴喜，更可惜雪中高树、香篝熏素被，以去年赏梅的回忆写梅花的美丽；下片「今年对花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上、旋看飞坠。相将见、脆丸荐酒，人正在、空江烟浪里。但梦想、一枝潇洒，黄昏斜照水」写今年对花最匆匆、相逢似有恨、依依愁悴，吟望久、青苔上旋看飞坠，相将见脆丸荐酒、人正在空江烟浪里，但梦想一枝潇洒、黄昏斜照水，以今年的匆匆与去年的从容对比，以梅花的飞坠写人生的漂泊，全词时间结构精巧、咏物写情，是咏物词的名篇。",
    b: "周邦彦这首《花犯》是咏梅词，以梅花的开落写人生的漂泊，「去年」「今年」「相将见」的时间结构是其特色，是咏物词的名篇。",
    n: ["花犯：词牌名（周邦彦自度曲）","粉墙低：粉墙低","梅花照眼：梅花照眼","依然旧风味：依然是旧日的风味","露痕轻缀：露痕轻轻点缀","疑净洗铅华：怀疑是净洗了铅华（铅华，化妆品）","无限佳丽：无限佳丽","去年胜赏曾孤倚：去年赏梅时曾独自倚靠","冰盘同宴喜：冰盘同宴喜（冰盘里的梅子）","雪中高树：雪中的高树","香篝熏素被：香篝熏着素被（以香篝喻梅香、素被喻雪）。篝音gōu，竹笼","今年对花最匆匆：今年对花最匆匆","相逢似有恨：相逢似有恨","依依愁悴：依依愁悴","吟望久：吟诗望久","青苔上、旋看飞坠：青苔上很快看到梅花飞坠","相将见、脆丸荐酒：将看到脆丸（梅子）下酒","人正在、空江烟浪里：人正在空江烟浪里","但梦想、一枝潇洒：只梦想一枝潇洒的梅花","黄昏斜照水：黄昏时斜照在水上"]
  },
  "六丑|周邦彦": {
    s: "上片「正单衣试酒，恨客里、光阴虚掷。愿春暂留，春归如过翼。一去无迹。为问花何在，夜来风雨，葬楚宫倾国。钗钿堕处遗香泽。乱点桃蹊，轻翻柳陌。多情为谁追惜。但蜂媒蝶使，时叩窗隔」写单衣试酒、恨客里光阴虚掷，愿春暂留、春归如飞鸟过、一去无迹，问花何在、夜来风雨葬楚宫倾国，钗钿堕处遗香泽，乱点桃蹊、轻翻柳陌，多情为谁追惜，但蜂媒蝶使时叩窗，以落花的飘零写春归的惋惜；下片「东园岑寂。渐蒙笼暗碧。静绕珍丛底，成叹息。长条故惹行客。似牵衣待话，别情无极。残英小、强簪巾帻。终不似一朵，钗头颤袅，向人敧侧。漂流处、莫趁潮汐。恐断红、尚有相思字，何由见得」写东园岑寂、蒙笼暗碧，静绕花丛成叹息，长条惹行客、似牵衣待话、别情无极，残英小强簪巾帻、终不似钗头颤袅，漂流处莫趁潮汐、恐断红尚有相思字、何由见得，以落花的漂流写相思的无望，全词咏物写情、用典丰富（楚宫倾国、红叶题诗）、格律精严，是周邦彦词的代表作。",
    b: "周邦彦这首《六丑》是咏落花词，以落花的漂流写人生的漂泊与相思，用典丰富、格律精严，是周邦彦词的代表作，也是宋词中最长的词调之一。",
    n: ["六丑：词牌名（周邦彦自度曲）","正单衣试酒：正是单衣试酒的时候","恨客里、光阴虚掷：恨在客里光阴虚掷","愿春暂留：愿春天暂时留下","春归如过翼：春归如飞鸟过","一去无迹：一去无痕迹","为问花何在：问花在哪里","夜来风雨：夜来风雨","葬楚宫倾国：埋葬了楚宫的倾国美人（喻花）","钗钿堕处遗香泽：钗钿坠落处遗下香泽（喻花落）","乱点桃蹊：乱点在桃树下的小路","轻翻柳陌：轻翻在柳下的小路","多情为谁追惜：多情为谁追惜","但蜂媒蝶使：只有蜂媒蝶使","时叩窗隔：不时叩窗","东园岑寂：东园寂静","渐蒙笼暗碧：渐渐笼罩在暗绿中","静绕珍丛底：静静绕着花丛","成叹息：成叹息","长条故惹行客：长条故意惹行人","似牵衣待话：似牵衣待话","别情无极：别情无限","残英小、强簪巾帻：残花小、勉强插在头巾上。巾帻，头巾","终不似一朵：终究不像一朵","钗头颤袅：在钗头颤动","向人敧侧：向人倾斜","漂流处、莫趁潮汐：漂流处不要趁潮汐","恐断红、尚有相思字：恐怕断红（落花）上还有相思字（红叶题诗典故）","何由见得：怎么能见到呢"]
  },
  "兰陵王|周邦彦": {
    s: "第一段「柳阴直。烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国。谁识。京华倦客。长亭路，年去岁来，应折柔条过千尺」写柳阴直、烟里丝丝弄碧，隋堤上曾见几番拂水飘绵送行色，登临望故国、谁识京华倦客，长亭路年去年来、应折柔条过千尺，以柳写离别；第二段「闲寻旧踪迹。又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿。望人在天北」写闲寻旧踪迹，又酒趁哀弦、灯照离席，梨花榆火催寒食，愁一箭风快、半篙波暖，回头迢递便数驿、望人在天北，写饯别与船行；第三段「凄恻。恨堆积。渐别浦萦回，津堠岑寂。斜阳冉冉春无极。念月榭携手，露桥闻笛。沈思前事，似梦里，泪暗滴」写凄恻恨堆积，别浦萦回、津堠岑寂，斜阳冉冉春无极，念月榭携手、露桥闻笛，沉思前事似梦里、泪暗滴，写别后的思念，全词三段结构、以柳写离、格律精严，是周邦彦词的代表作，「柳阴直，烟里丝丝弄碧」成为名句。",
    b: "周邦彦这首《兰陵王》是写柳的千古名篇，以柳写离别，「柳阴直，烟里丝丝弄碧」开篇，三段结构（咏柳、饯别、别后），是周邦彦词的代表作，据说宋徽宗因此词召周邦彦回京。",
    n: ["兰陵王：词牌名","柳阴直：柳阴笔直（指隋堤上的柳树）","烟里丝丝弄碧：烟里丝丝柳条弄碧","隋堤上、曾见几番：隋堤上曾见过几番","拂水飘绵送行色：拂水飘绵送行色","登临望故国：登临望故乡","谁识：谁认识","京华倦客：京城的倦客","长亭路，年去岁来：长亭路上年去年来","应折柔条过千尺：应该折过的柔条超过千尺","闲寻旧踪迹：闲寻旧踪迹","又酒趁哀弦：又酒趁着哀弦","灯照离席：灯照离席","梨花榆火催寒食：梨花榆火催寒食（寒食节）","愁一箭风快：愁一箭风快（船行快）","半篙波暖：半篙波暖","回头迢递便数驿：回头迢递便过了数驿","望人在天北：望人在天北","凄恻：凄恻","恨堆积：恨堆积","渐别浦萦回：渐渐别浦萦回","津堠岑寂：渡口的土堡寂静。堠音hòu，土堡","斜阳冉冉春无极：斜阳冉冉春无极","念月榭携手：念月榭携手","露桥闻笛：露桥闻笛","沈思前事：沉思前事。沈同「沉」","似梦里：似梦里","泪暗滴：泪暗滴"]
  },
  "西河|周邦彦": {
    s: "第一段「佳丽地。南朝盛事谁记。山围故国绕清江，髻鬟对起。怒涛寂寞打孤城，风樯遥度天际」写佳丽地、南朝盛事谁记，山围故国绕清江、髻鬟对起，怒涛寂寞打孤城、风樯遥度天际，化用刘禹锡《石头城》诗意；第二段「断崖树，犹倒倚。莫愁艇子曾系。空余旧迹郁苍苍，雾沈半垒。夜深月过女墙来，赏心东望淮水」写断崖树犹倒倚，莫愁艇子曾系，空余旧迹郁苍苍、雾沉半垒，夜深月过女墙来、赏心东望淮水，继续写金陵古迹；第三段「酒旗戏鼓甚处市。想依稀、王谢邻里。燕子不知何世。入寻常、巷陌人家，相对如说兴亡，斜阳里」写酒旗戏鼓甚处市，想依稀王谢邻里，燕子不知何世、入寻常巷陌人家、相对如说兴亡、斜阳里，化用刘禹锡《乌衣巷》诗意，以燕子写兴亡之感，全词化用唐诗、意境苍凉，是宋词中怀古的名篇，「相对如说兴亡，斜阳里」成为名句。",
    b: "周邦彦这首《西河》是金陵怀古词，化用刘禹锡《石头城》《乌衣巷》的诗意，以「燕子不知何世，入寻常、巷陌人家，相对如说兴亡，斜阳里」写兴亡之感，是宋词中怀古的名篇。",
    n: ["西河：词牌名","佳丽地：佳丽的地方（指金陵，谢朓「江南佳丽地」）","南朝盛事谁记：南朝的盛事谁记得","山围故国绕清江：山围着故国绕着清江（刘禹锡「山围故国周遭在」）","髻鬟对起：发髻般的山峰相对而起","怒涛寂寞打孤城：怒涛寂寞地打着孤城（刘禹锡「潮打空城寂寞回」）","风樯遥度天际：风中的船帆遥度天际","断崖树，犹倒倚：断崖上的树还倒倚着","莫愁艇子曾系：莫愁的小艇曾系在这里","空余旧迹郁苍苍：空余旧迹郁郁苍苍","雾沈半垒：雾沉了半壁堡垒。沈同「沉」","夜深月过女墙来：夜深月过女墙（城墙上的矮墙）来","赏心东望淮水：赏心亭东望淮水（秦淮河）","酒旗戏鼓甚处市：酒旗戏鼓是哪里的街市","想依稀、王谢邻里：想依稀是王谢的邻里（王导、谢安，东晋豪门）","燕子不知何世：燕子不知什么世代","入寻常、巷陌人家：飞入寻常巷陌人家（刘禹锡「旧时王谢前堂燕，飞入寻常百姓家」）","相对如说兴亡：相对如说兴亡","斜阳里：在斜阳里"]
  },
  "玉楼春|周邦彦": {
    s: "上片「桃溪不作从容住。秋藕绝来无续处。当时相候赤栏桥，今日独寻黄叶路」写桃溪不能从容住、秋藕断了无续处，当时相候赤栏桥、今日独寻黄叶路，以「桃溪」「秋藕」的典故与比喻写离别，以「当时」与「今日」对比；下片「烟中列岫青无数。雁背夕阳红欲暮。人如风后入江云，情似雨余黏地絮」写烟中列岫青无数、雁背夕阳红欲暮，人如风后入江云、情似雨后黏地絮，以「风后入江云」写人的飘忽、以「雨余黏地絮」写情的黏着，比喻新奇、对仗工稳，全词意境苍凉、情感深沉，「人如风后入江云，情似雨余黏地絮」成为名句。",
    b: "周邦彦这首《玉楼春》写离别后的思念，以「人如风后入江云，情似雨余黏地絮」的比喻写情，是周邦彦词的名篇。",
    n: ["玉楼春：词牌名","桃溪不作从容住：桃溪（刘晨阮肇遇仙处）不能从容居住","秋藕绝来无续处：秋藕断了没有续接的地方","当时相候赤栏桥：当时在赤栏桥等候","今日独寻黄叶路：今日独自寻黄叶路","烟中列岫青无数：烟中排列的山峰青无数。岫音xiù，山峰","雁背夕阳红欲暮：雁背的夕阳红欲暮","人如风后入江云：人如风后入江的云（飘忽不定）","情似雨余黏地絮：情如雨后黏地的柳絮（黏着难舍）"]
  },
  "夜飞鹊・夜飞鹊慢|周邦彦": {
    s: "上片「河桥送人处，凉夜何其。斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。相将散离会，探风前津鼓，树杪参旗。华骢会意，纵扬鞭、亦自行迟」写河桥送人处、凉夜如何，斜月堕余辉，铜盘烛泪尽、凉露沾衣，相将散离会、探风前津鼓、树梢参旗，华骝会意、纵扬鞭亦自行迟，以送别之夜的凄凉写离情；下片「迢递路回清野，人语渐无闻，空带愁归。何意重红满地，遗钿不见，斜径都迷。兔葵燕麦，向残阳、欲与人齐。但徘徊班草，欷歔酹酒，极望天西」写迢递路回清野、人语渐无闻、空带愁归，何意重红满地、遗钿不见、斜径都迷，兔葵燕麦向残阳欲与人齐，但徘徊班草、欷歔酹酒、极望天西，以重游故地的荒凉写物是人非，「兔葵燕麦，向残阳、欲与人齐」化用刘禹锡诗意，全词意境苍凉、情感深沉，是周邦彦词的名篇。",
    b: "周邦彦这首《夜飞鹊》写送别后的重游故地，以「兔葵燕麦，向残阳、欲与人齐」写故地的荒凉，是周邦彦词的名篇。",
    n: ["夜飞鹊：词牌名（周邦彦自度曲）","河桥送人处：河桥送人的地方","凉夜何其：凉夜如何（《诗经》「夜如何其」）","斜月远堕余辉：斜月远远坠落余辉","铜盘烛泪已流尽：铜盘的烛泪已流尽","霏霏凉露沾衣：霏霏凉露沾衣","相将散离会：相将散离会","探风前津鼓：探听风前的渡口更鼓","树杪参旗：树梢上的参星旗星（天将亮）","华骢会意：华骝（骏马）会意","纵扬鞭、亦自行迟：纵然扬鞭也自行迟","迢递路回清野：迢递的路回清野","人语渐无闻：人语渐渐听不到了","空带愁归：空带愁归","何意重红满地：何意重红满地（花又开了）","遗钿不见：遗落的钗钿不见了","斜径都迷：斜径都迷了","兔葵燕麦：兔葵燕麦（刘禹锡「兔葵燕麦，动摇春风」，指荒凉）","向残阳、欲与人齐：向残阳欲与人齐（长得和人一样高）","但徘徊班草：但徘徊在班草（铺草而坐）处","欷歔酹酒：欷歔（叹息）洒酒祭奠。欷歔音xīxū","极望天西：极望天西"]
  },
  "点绛唇|姜夔": {
    s: "上片「燕雁无心，太湖西畔随云去。数峰清苦。商略黄昏雨」写燕雁无心、太湖西畔随云去，数峰清苦、商量着黄昏的雨，以「清苦」「商略」的拟人手法写山，想象奇特；下片「第四桥边，拟共天随住。今何许。凭栏怀古。残柳参差舞」写第四桥边、拟共天随子同住，今何许、凭栏怀古、残柳参差舞，以陆龟蒙（天随子）的典故写归隐之志，以「残柳参差舞」写怀古的苍凉，全词意境清远、拟人巧妙，「数峰清苦，商略黄昏雨」成为名句，是姜夔词的名篇。",
    b: "姜夔（南宋词人，「格律派」代表，号白石道人）这首《点绛唇》写在苏州吴江的所见所感，以「数峰清苦，商略黄昏雨」的拟人手法写山，是姜夔词的名篇。",
    n: ["点绛唇：词牌名","燕雁无心：燕雁（北方的雁）无心","太湖西畔随云去：太湖西畔随云去","数峰清苦：几座山峰清苦","商略黄昏雨：商量着黄昏的雨（拟人，山峰像在商量要下雨）","第四桥边：第四桥边（在苏州吴江）","拟共天随住：打算和天随子（陆龟蒙，号天随子，隐居吴江）同住","今何许：如今在哪里","凭栏怀古：凭栏怀古","残柳参差舞：残柳参差不齐地飞舞"]
  },
  "鹧鸪天|姜夔": {
    s: "上片「肥水东流无尽期。当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼」写肥水东流无尽期、当初不该种相思，梦中相见不如画像清楚、暗中被山鸟啼惊醒，以「肥水东流」写相思的无尽、以「梦中」写思念的深切；下片「春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沈吟各自知」写春未绿鬓先丝，人间别久不成悲，谁教年年红莲夜、两地沉吟各自知，以「别久不成悲」写离别的深沉——不是不悲，而是悲到深处已麻木，以「红莲夜」的团圆反衬两地的分离，全词情感深沉、意境凄清，「人间别久不成悲」成为名句，是姜夔词的名篇。",
    b: "姜夔这首《鹧鸪天》写元宵夜思念旧日情人（在合肥相遇的歌女），以「人间别久不成悲」写离别的深沉，是姜夔词的名篇。",
    n: ["鹧鸪天：词牌名","肥水东流无尽期：肥水（在安徽，姜夔曾在此与情人相遇）东流无尽期","当初不合种相思：当初不该种下相思","梦中未比丹青见：梦中相见不如画像中看得清楚。丹青，画像","暗里忽惊山鸟啼：暗中忽然被山鸟啼惊醒","春未绿，鬓先丝：春还没绿、鬓先白了","人间别久不成悲：人间离别久了就不觉得悲了","谁教岁岁红莲夜：谁让年年红莲夜（灯节，元宵）","两处沈吟各自知：两地沉吟各自知道。沈同「沉」"]
  },
  "齐天乐|姜夔": {
    s: "上片「庾郎先自吟愁赋。凄凄更闻私语。露湿铜铺，苔侵石井，都是曾听伊处。哀音似诉。正思妇无眠，起寻机杼。曲曲屏山，夜凉独自甚情绪」写庾信先吟愁赋、凄凄更闻私语（蟋蟀叫），露湿铜铺、苔侵石井、都是曾听它处，哀音似诉，思妇无眠起寻机杼，曲曲屏山、夜凉独自甚情绪，以蟋蟀声写思妇的愁；下片「西窗又吹暗雨。为谁频断续，相和砧杵。候馆迎秋，离宫吊月，别有伤心无数。豳诗漫与。笑篱落呼灯，世间儿女。写入琴丝，一声声更苦」写西窗又吹暗雨，为谁频断续、相和砧杵，候馆迎秋、离宫吊月、别有伤心无数，豳诗漫与，笑篱落呼灯、世间儿女，写入琴丝、一声声更苦，以蟋蟀声写各种人的愁，全词咏物写情、用典丰富（庾信愁赋、《诗经·豳风》）、格律精严，是咏物词的千古名篇。",
    b: "姜夔这首《齐天乐》是咏蟋蟀词，以蟋蟀的叫声写各种人的愁思，「庾郎先自吟愁赋，凄凄更闻私语」开篇，是咏物词的千古名篇，张炎评为「全章精粹，所咏了然在目，且不留滞于物」。",
    n: ["齐天乐：词牌名","庾郎先自吟愁赋：庾郎（庾信，作《愁赋》）先自吟愁赋","凄凄更闻私语：凄凄地更听到私语（蟋蟀的叫声）","露湿铜铺：露湿了铜铺（门上的铜环底座）","苔侵石井：苔藓侵了石井","都是曾听伊处：都是曾听它（蟋蟀）叫的地方","哀音似诉：哀音似在诉说","正思妇无眠：正是思妇无眠时","起寻机杼：起来找机杼（织布）","曲曲屏山：曲曲的屏山（屏风上的山）","夜凉独自甚情绪：夜凉独自什么情绪","西窗又吹暗雨：西窗又吹暗雨","为谁频断续：为谁频频断续","相和砧杵：和着砧杵声（捣衣声）","候馆迎秋：旅馆迎秋","离宫吊月：离宫（行宫）对月","别有伤心无数：别有伤心无数","豳诗漫与：《诗经·豳风》随意写来（《豳风·七月》有「十月蟋蟀入我床下」）","笑篱落呼灯：笑篱笆边呼灯（儿童捉蟋蟀）","世间儿女：世间的儿女","写入琴丝：写入琴丝（琴曲）","一声声更苦：一声声更苦"]
  },
  "琵琶仙・自度曲|姜夔": {
    s: "上片「双桨来时，有人似、旧曲桃根桃叶。歌扇轻约飞花，蛾眉正奇绝。春渐远、汀洲自绿，更添了、几声啼鴂。十里扬州，三生杜牧，前事休说」写双桨来时、有人像桃根桃叶，歌扇轻约飞花、蛾眉正奇绝，春渐远汀洲自绿、更添几声啼鴂，十里扬州、三生杜牧、前事休说，以看到类似旧情人的女子触发相思；下片「又还是、宫烛分烟，奈愁里、匆匆换时节。都把一襟芳思，与空阶榆荚。千万缕、藏鸦细柳，为玉尊、起舞回雪。想见西出阳关，故人初别」写又还是宫烛分烟、奈愁里匆匆换时节，都把一襟芳思给空阶榆荚，千万缕藏鸦细柳、为玉尊起舞回雪，想见西出阳关、故人初别，以寒食节的景色与典故写离情，全词用典丰富（桃根桃叶、杜牧扬州、韩翃寒食、王维阳关）、意境凄清，是姜夔词的名篇。",
    b: "姜夔这首《琵琶仙》是在吴兴游历时，看到双桨画船中的女子像旧日情人，触发相思而作，用典丰富（桃根桃叶、杜牧、韩翃、王维），是姜夔词的名篇。",
    n: ["琵琶仙：词牌名（姜夔自度曲）","双桨来时：双桨划来时","有人似、旧曲桃根桃叶：有人像旧曲中的桃根桃叶（桃叶，王献之的爱妾；桃根，桃叶的妹妹）","歌扇轻约飞花：歌扇轻轻拦住飞花","蛾眉正奇绝：蛾眉正奇绝","春渐远、汀洲自绿：春渐远、汀洲自绿","更添了、几声啼鴂：更添了几声啼鴂（杜鹃鸟）。鴂音jué","十里扬州：十里扬州（杜牧「春风十里扬州路」）","三生杜牧：三生杜牧（杜牧的前世今生，指自己像杜牧）","前事休说：前事休说","又还是、宫烛分烟：又还是宫烛分烟（寒食节，韩翃「日暮汉宫传蜡烛」）","奈愁里、匆匆换时节：奈何愁里匆匆换了时节","都把一襟芳思：都把一襟芳思","与空阶榆荚：给空阶的榆荚","千万缕、藏鸦细柳：千万缕藏鸦的细柳","为玉尊、起舞回雪：为玉尊起舞回雪（柳絮如雪）","想见西出阳关：想见西出阳关（王维「西出阳关无故人」）","故人初别：故人初别时"]
  },
  "扬州慢|姜夔": {
    s: "上片「淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒，都在空城」写淮左名都、竹西佳处、解鞍少驻，过春风十里、尽荠麦青青，自胡马窥江去后、废池乔木、犹厌言兵，渐黄昏、清角吹寒、都在空城，以扬州昔日的繁华与今日的荒凉对比，以「犹厌言兵」写战争的残酷；下片「杜郎俊赏，算而今，重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生」写杜牧俊赏、算如今重到须惊，纵豆蔻词工、青楼梦好、难赋深情，二十四桥仍在、波心荡冷月无声，念桥边红药、年年知为谁生，以杜牧的典故与二十四桥的冷月写今昔之感，全词用典丰富（杜牧诗句多处）、对比鲜明、情感沉痛，是南宋爱国词的千古名篇，「二十四桥仍在，波心荡、冷月无声」成为千古名句。",
    b: "姜夔这首《扬州慢》是他22岁时路过扬州，看到扬州在金兵南侵后的荒凉景象而作，是南宋爱国词的千古名篇，「自胡马窥江去后，废池乔木，犹厌言兵」「二十四桥仍在，波心荡、冷月无声」成为千古名句。",
    n: ["扬州慢：词牌名（姜夔自度曲）","淮左名都：淮左（淮南东路）的名都（指扬州）","竹西佳处：竹西亭的佳处（竹西亭在扬州，杜牧「谁知竹西路，歌吹是扬州」）","解鞍少驻初程：解鞍稍停初程","过春风十里：过春风十里（杜牧「春风十里扬州路」）","尽荠麦青青：全是荠麦青青","自胡马窥江去后：自从金兵窥江（指1161年金主完颜亮南侵）去后","废池乔木：废池乔木","犹厌言兵：还厌恶说起战争","渐黄昏：渐渐黄昏","清角吹寒：清角吹寒（号角声吹出寒意）","都在空城：都在空城","杜郎俊赏：杜牧的俊赏（杜牧善于赏玩）","算而今、重到须惊：算如今重到也会吃惊","纵豆蔻词工：纵然豆蔻词工（杜牧「豆蔻梢头二月初」）","青楼梦好：青楼梦好（杜牧「十年一觉扬州梦，赢得青楼薄幸名」）","难赋深情：难赋深情","二十四桥仍在：二十四桥仍在（杜牧「二十四桥明月夜」）","波心荡、冷月无声：波心荡漾、冷月无声","念桥边红药：念桥边的红芍药","年年知为谁生：年年知道为谁开"]
  },
  "长亭怨慢|姜夔": {
    s: "上片「渐吹尽、枝头香絮。是处人家，绿深门户。远浦萦回，暮帆零乱向何许。阅人多矣，谁得似、长亭树。树若有情时，不会得、青青如此」写渐吹尽柳絮，是处人家绿深门户，远浦萦回、暮帆零乱向何许，阅人多矣、谁得似长亭树，树若有情时、不会青青如此，以长亭树的「青青如此」反衬人的离别之痛；下片「日暮。望高城不见，只见乱山无数。韦郎去也，怎忘得、玉环分付。第一是、早早归来，怕红萼、无人为主。算空有并刀，难翦离愁千缕」写日暮望高城不见、只见乱山无数，韦郎去也、怎忘玉环分付，第一是早早归来、怕红萼无人为主，算空有并刀、难剪离愁千缕，以韦皋玉箫的典故写离别之约，以「并刀难剪离愁」写离愁的深，全词拟人巧妙、用典贴切、情感深沉，「树若有情时，不会得、青青如此」成为名句。",
    b: "姜夔这首《长亭怨慢》写离别，以「树若有情时，不会得、青青如此」的拟人写树的无情反衬人的有情，用韦皋与玉箫的典故写离别之约，是姜夔词的名篇。",
    n: ["长亭怨慢：词牌名（姜夔自度曲）","渐吹尽、枝头香絮：渐渐吹尽枝头的柳絮","是处人家：到处的人家","绿深门户：绿深的门户","远浦萦回：远浦萦回","暮帆零乱向何许：暮帆零乱向何处","阅人多矣：经历的人多了","谁得似、长亭树：谁能像长亭的树","树若有情时：树如果有情时","不会得、青青如此：不会青青如此（不会这么无情地绿着）","日暮：日暮","望高城不见：望高城不见","只见乱山无数：只见乱山无数","韦郎去也：韦郎（韦皋，与玉箫的爱情故事）去了","怎忘得、玉环分付：怎能忘得了玉环的吩咐（韦皋与玉箫分别时留玉指环约定）","第一是、早早归来：第一是早早归来","怕红萼、无人为主：怕红萼（花，指情人）无人为主","算空有并刀：算空有并州剪刀","难翦离愁千缕：难剪离愁千缕"]
  },
  "淡黄柳|姜夔": {
    s: "上片「空城晓月。吹入垂杨陌。马上单衣寒恻恻。看尽鹅黄嫩绿，都是江南旧相识」写空城晓月、吹入垂杨陌，马上单衣寒恻恻，看尽鹅黄嫩绿、都是江南旧相识，以「空城」写合肥的荒凉、以「江南旧相识」写乡愁；下片「正岑寂。明朝又寒食。强携酒、小桥宅，怕梨花落尽成秋色。燕燕飞来，问春何在，唯有池塘自碧」写正岑寂、明朝又寒食，强携酒小桥宅、怕梨花落尽成秋色，燕燕飞来问春何在、唯有池塘自碧，以「怕梨花落尽」写惜春、以「唯有池塘自碧」写春去的空寂，全词意境凄清、情感深沉，「怕梨花落尽成秋色」成为名句，是姜夔词的名篇。",
    b: "姜夔这首《淡黄柳》写在合肥客居时的春景与乡愁，以「怕梨花落尽成秋色」写惜春之情，是姜夔词的名篇。",
    n: ["淡黄柳：词牌名（姜夔自度曲）","空城晓月：空城的晓月","吹入垂杨陌：吹入垂杨路","马上单衣寒恻恻：马上单衣寒恻恻（寒冷）","看尽鹅黄嫩绿：看尽鹅黄嫩绿（初春的柳色）","都是江南旧相识：都是江南旧相识","正岑寂：正岑寂","明朝又寒食：明天又寒食","强携酒、小桥宅：勉强携酒到小桥宅","怕梨花落尽成秋色：怕梨花落尽成秋色","燕燕飞来：燕子飞来","问春何在：问春在哪里","唯有池塘自碧：只有池塘自碧"]
  },
  "暗香|姜夔": {
    s: "上片「旧时月色。算几番照我，梅边吹笛。唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却、春风词笔。但怪得、竹外疏花，香冷入瑶席」写旧时月色几番照我梅边吹笛，唤起玉人不顾清寒一同攀摘，何逊而今渐老忘却春风词笔，只怪竹外疏花香冷入瑶席，以回忆与现实对比写梅花的情思；下片「江国。正寂寂。叹寄与路遥，夜雪初积。翠尊易泣。红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片、吹尽也，几时见得」写江国正寂寂，叹寄梅路遥、夜雪初积，翠尊易泣、红萼无言耿相忆，长记曾携手处千树压西湖寒碧，又片片吹尽、几时见得，以寄梅与西湖千树梅写离情，全词意境清空、用典贴切（何逊咏梅、陆凯寄梅），「旧时月色」开篇，是姜夔词的代表作，与《疏影》并称咏梅双璧。",
    b: "姜夔这首《暗香》是他咏梅的代表作，与《疏影》并称「暗香疏影」，为咏梅词的千古绝唱，是他应范成大之请而作，范成大赠以青衣小红。",
    n: ["暗香：词牌名（姜夔自度曲，咏梅）","旧时月色：旧日的月色","算几番照我：算几番照过我","梅边吹笛：在梅边吹笛","唤起玉人：唤起美人","不管清寒与攀摘：不顾清寒一同攀摘梅花","何逊而今渐老：何逊（南朝梁诗人，有《咏早梅》诗）如今渐老","都忘却、春风词笔：都忘却了春风般的词笔","但怪得、竹外疏花：只怪竹外稀疏的梅花","香冷入瑶席：冷香飘入瑶席（宴席）","江国：江南水乡","叹寄与路遥：感叹寄梅路途遥远（陆凯寄梅范晔「聊赠一枝春」）","翠尊易泣：翠玉酒杯前容易落泪","红萼无言耿相忆：红花无言、耿耿相忆。耿，心中挂念","千树压、西湖寒碧：千树梅花压着西湖寒碧的水","又片片、吹尽也：又一片片被吹尽了","几时见得：何时能再见"]
  },
  "疏影|姜夔": {
    s: "上片「苔枝缀玉。有翠禽小小，枝上同宿。客里相逢，篱角黄昏，无言自倚修竹。昭君不惯胡沙远，但暗忆、江南江北。想佩环、月夜归来，化作此花幽独」写苔枝缀玉、翠禽同宿，客里相逢、篱角黄昏、无言自倚修竹，昭君不惯胡沙远、暗忆江南江北，想佩环月夜归来化作此花幽独，以昭君喻梅、以幽独写梅的品格；下片「犹记深宫旧事，那人正睡里，飞近蛾绿。莫似春风，不管盈盈，早与安排金屋。还教一片随波去，又却怨、玉龙哀曲。等恁时、重觅幽香，已入小窗横幅」写犹记深宫旧事、那人正睡、飞近蛾绿（梅花妆），莫似春风不管盈盈、早安排金屋，还教一片随波去、又怨玉龙哀曲，等那时重觅幽香、已入小窗横幅，用典丰富（寿阳公主梅花妆、金屋藏娇、玉龙吹梅），全词以梅写美人、以美人写家国，意境清空、用典精当，是咏梅词的千古绝唱。",
    b: "姜夔这首《疏影》与《暗香》并称「暗香疏影」，是咏梅词的千古绝唱，用典丰富（昭君、寿阳公主、金屋藏娇、玉龙吹梅），以梅写家国之思，张炎评为「前无古人，后无来者」。",
    n: ["疏影：词牌名（姜夔自度曲，咏梅）","苔枝缀玉：苔枝（长苔藓的梅枝）上缀着玉（梅花）","翠禽小小：小小的翠鸟（用赵师雄罗浮山遇梅花女神故事，有翠禽啼）","客里相逢：在客中相逢","无言自倚修竹：无言独自倚着修竹（用杜甫「天寒翠袖薄，日暮倚修竹」写美人）","昭君不惯胡沙远：王昭君不习惯胡地风沙的遥远","但暗忆、江南江北：只暗忆江南江北","想佩环、月夜归来：想佩环（昭君的佩环）月夜归来（杜甫「环佩空归月夜魂」）","化作此花幽独：化作这梅花的幽独","深宫旧事：深宫旧事（用宋武帝女寿阳公主梅花落额上成梅花妆故事）","那人正睡里：那人正睡着","飞近蛾绿：飞近蛾绿（梅花妆，蛾绿指眉）","莫似春风：不要像春风","不管盈盈：不管盈盈（梅花的美好）","早与安排金屋：早早安排金屋（金屋藏娇，汉武帝「金屋藏娇」典故）","还教一片随波去：却让一片随波去","又却怨、玉龙哀曲：又怨玉龙（笛）的哀曲（玉龙，笛子；梅花落曲）","等恁时、重觅幽香：等那时重觅幽香","已入小窗横幅：已入小窗的横幅画中"]
  },
  "惜红衣|姜夔": {
    s: "上片「簟枕邀凉，琴书换日，睡余无力。细洒冰泉，并刀破甘碧。墙头唤酒，谁问讯、城南诗客。岑寂。高柳晚蝉，说西风消息」写簟枕邀凉、琴书换日、睡余无力，细洒冰泉、并刀破甘碧，墙头唤酒、谁问讯城南诗客，岑寂，高柳晚蝉说西风消息，以夏日生活的细节写客居的岑寂；下片「虹粱水陌。鱼浪吹香，红衣半狼藉。维舟试望故国。眇天北。可惜渚边沙外，不共美人游历。问甚时同赋，三十六陂秋色」写虹粱水陌、鱼浪吹香、红衣半狼藉，维舟试望故国、眇天北，可惜渚边沙外不共美人游历，问甚时同赋三十六陂秋色，以荷花凋零与望故国写乡愁，全词意境清空、情感深沉，是姜夔词的名篇。",
    b: "姜夔这首《惜红衣》写在吴兴（今浙江湖州）客居时的夏日景色与乡愁，以「红衣半狼藉」写荷花凋零，是姜夔词的名篇。",
    n: ["惜红衣：词牌名（姜夔自度曲）","簟枕邀凉：竹席枕头邀来清凉。簟音diàn","琴书换日：琴书打发日子","睡余无力：睡后无力","细洒冰泉：细洒冰泉","并刀破甘碧：并州剪刀破开甘碧（瓜）","墙头唤酒：墙头唤酒（杜甫「墙头过酒」）","谁问讯、城南诗客：谁问讯城南诗客（杜甫在城南）","高柳晚蝉：高柳上的晚蝉","说西风消息：说着西风的消息","虹粱水陌：虹粱（桥）水陌","鱼浪吹香：鱼浪吹香","红衣半狼藉：荷花（红衣）半狼藉","维舟试望故国：系船试望故乡","眇天北：遥远在天北","渚边沙外：渚边沙外","不共美人游历：不与美人一同游历","问甚时同赋：问何时同赋","三十六陂秋色：三十六陂（池塘）的秋色"]
  },
  "翠楼吟|姜夔": {
    s: "上片「月冷龙沙，尘轻虎落，今年汉酺初赐。新翻胡部曲，听毡幕、元戎歌吹。层楼高峙。看栏曲萦红，檐牙飞翠。人姝丽。粉香吹下，夜寒风细」写月冷龙沙、尘轻虎落、今年初赐酺，新翻胡部曲、听毡幕元戎歌吹，层楼高峙、栏曲萦红、檐牙飞翠，人姝丽、粉香吹下、夜寒风细，写安远楼的庆典盛况；下片「此地。宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草、萋萋千里。天涯情味。仗酒袯清愁，花销英气。西山外。晚来还卷，一帘秋霁」写此地宜有词仙、拥素云黄鹤与君游戏，玉梯凝望久、叹芳草萋萋千里，天涯情味、仗酒袯清愁、花销英气，西山外晚来还卷一帘秋霁，以黄鹤典故与芳草萋萋写天涯漂泊之感，全词意境开阔、用典贴切（崔颢黄鹤楼、《楚辞》芳草），是姜夔词的名篇。",
    b: "姜夔这首《翠楼吟》是他在武昌参加安远楼落成庆典时所作，写登楼所见与天涯漂泊之感，是姜夔词的名篇。",
    n: ["翠楼吟：词牌名（姜夔自度曲）","月冷龙沙：月冷龙沙（龙沙，泛指塞外）","尘轻虎落：尘轻虎落（虎落，边塞的栅栏）","今年汉酺初赐：今年汉朝（指宋朝）初次赐酺（聚会饮酒）。酺音pú","新翻胡部曲：新翻的胡部乐曲","听毡幕、元戎歌吹：听毡幕中主将的歌吹。元戎，主将","层楼高峙：层楼高峙","栏曲萦红：栏曲萦绕红（栏杆的红）","檐牙飞翠：檐牙飞翠（屋檐的翠）","人姝丽：人美丽","粉香吹下：粉香吹下","夜寒风细：夜寒风细","此地宜有词仙：此地宜有词仙","拥素云黄鹤：拥素云黄鹤（用崔颢「黄鹤一去不复返」）","与君游戏：与君游戏","玉梯凝望久：玉梯凝望久","叹芳草、萋萋千里：叹芳草萋萋千里（用《楚辞》「王孙游兮不归，春草生兮萋萋」）","天涯情味：天涯情味","仗酒袯清愁：仗酒祓除清愁。袯音fú，祓除","花销英气：花销英气","西山外：西山外","晚来还卷：晚来还卷（帘）","一帘秋霁：一帘秋霁（雨后初晴）"]
  },
  "玉楼春|宋祁": {
    s: "上片「东城渐觉风光好。縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹」写东城风光好、波纹迎客棹，绿杨烟外晓寒轻、红杏枝头春意闹，以「闹」字写春天的生机，王国维评为「着一闹字而境界全出」；下片「浮生长恨欢娱少。肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照」写浮生长恨欢娱少、肯爱千金轻一笑，为君持酒劝斜阳、且向花间留晚照，以「劝斜阳」「留晚照」写惜春之情，全词色彩明丽、「闹」字传神，是北宋词的名篇，「红杏枝头春意闹」成为千古名句。",
    b: "宋祁（北宋词人，官至工部尚书）这首《玉楼春》写游春的欢乐与惜春之情，「红杏枝头春意闹」是千古名句，宋祁因此被称为「红杏枝头春意闹尚书」。",
    n: ["玉楼春：词牌名","东城渐觉风光好：东城渐渐觉得风光好","縠皱波纹迎客棹：绉纱般的波纹迎接客船。縠音hú，绉纱；棹音zhào，船桨代指船","绿杨烟外晓寒轻：绿杨烟外晓寒轻","红杏枝头春意闹：红杏枝头春意热闹（「闹」字是千古名句，王国维评为「着一闹字而境界全出」）","浮生长恨欢娱少：浮生常恨欢娱少","肯爱千金轻一笑：怎肯爱惜千金而轻视一笑","为君持酒劝斜阳：为君持酒劝斜阳","且向花间留晚照：且向花间留晚照"]
  },
  "小重山|岳飞": {
    s: "上片「昨夜寒蛩不住鸣。惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明」写昨夜寒蛩不住鸣、惊醒千里梦已三更，起来独自绕阶行、人悄悄帘外月胧明，以寒蛩、残月、独行写失眠的苦闷；下片「白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴。知音少，弦断有谁听」写白首为功名、旧山松竹老阻归程，欲将心事付瑶琴、知音少弦断有谁听，以「知音少，弦断有谁听」写抗金壮志难酬、知音难觅的苦闷，全词含蓄深沉、意境苍凉，与《满江红》的豪放形成对比，是南宋爱国词的名篇。",
    b: "岳飞（南宋抗金名将）这首《小重山》写抗金壮志难酬、知音难觅的苦闷，与他的《满江红》风格不同，以含蓄深沉见长，是南宋爱国词的名篇。",
    n: ["小重山：词牌名","昨夜寒蛩不住鸣：昨夜寒蟋蟀不住鸣叫。蛩音qióng","惊回千里梦：惊醒了千里（杀敌）的梦","已三更：已三更","起来独自绕阶行：起来独自绕阶行","人悄悄：人悄悄","帘外月胧明：帘外月朦胧明亮","白首为功名：白首为功名","旧山松竹老：故乡的山松竹老了","阻归程：阻归程","欲将心事付瑶琴：想将心事付瑶琴","知音少：知音少","弦断有谁听：弦断了有谁听"]
  },
  "贺新郎|张元干": {
    s: "上片「曳杖危楼去。斗垂天、沧波万顷，月流烟渚。扫尽浮云风不定，未放扁舟夜渡。宿燕落、寒芦深处。怅望关河空吊影，正人间、鼻息鸣鼍鼓。谁伴我，醉中舞」写曳杖危楼、北斗垂天、沧波万顷、月流烟渚，扫尽浮云风不定、未放扁舟夜渡，宿燕落寒芦深处，怅望关河空吊影、人间鼻息鸣鼍鼓，谁伴我醉中舞，以夜景写孤独与壮志；下片「十年一梦扬州路。倚高寒、愁生故国，气吞骄虏。要斩楼兰三尺剑，遗恨琵琶旧语。谩暗涩、铜华尘土。唤取谪仙平章看，过苕溪、尚许垂纶否。风浩荡，欲飞举」写十年一梦扬州路、倚高寒愁生故国气吞骄虏，要斩楼兰三尺剑、遗恨琵琶旧语，谩暗涩铜华尘土，唤取谪仙平章看、过苕溪尚许垂纶否，风浩荡欲飞举，以抗金壮志与对友人的同情写爱国情怀，全词意境苍凉、用典丰富（祖逖闻鸡起舞、楼兰、昭君琵琶、李白谪仙、苕溪垂纶），是南宋爱国词的名篇。",
    b: "张元干（南宋词人）这首《贺新郎》是他送友人胡铨（因反对秦桧被贬）的词，写抗金壮志与对友人的同情，是南宋爱国词的名篇，与他的《贺新郎·送胡邦衡待制》（「梦绕神州路」）并称。",
    n: ["贺新郎：词牌名","曳杖危楼去：拄杖登上高楼","斗垂天、沧波万顷：北斗垂天、沧波万顷","月流烟渚：月照烟渚","扫尽浮云风不定：扫尽浮云风不定","未放扁舟夜渡：未放扁舟夜渡","宿燕落、寒芦深处：宿燕落在寒芦深处","怅望关河空吊影：怅望关河空吊影","正人间、鼻息鸣鼍鼓：正人间鼻息如鼍鼓（鼍鼓，鳄鱼皮鼓，形容鼾声大）。鼍音tuó","谁伴我，醉中舞：谁伴我醉中舞（用祖逖闻鸡起舞典故）","十年一梦扬州路：十年一梦扬州路（指十年前在扬州的抗金经历）","倚高寒、愁生故国：倚高寒、愁生故国","气吞骄虏：气吞骄虏","要斩楼兰三尺剑：要斩楼兰（敌酋）三尺剑","遗恨琵琶旧语：遗恨琵琶旧语（指和亲屈辱，王昭君琵琶）","谩暗涩、铜华尘土：空让铜剑（铜华）暗涩蒙尘","唤取谪仙平章看：唤取谪仙（李白，指友人）评看","过苕溪、尚许垂纶否：过苕溪还许垂纶（钓鱼，指隐居）否。纶音lún，钓丝","风浩荡，欲飞举：风浩荡、欲飞举"]
  },
  "石州慢|张元干": {
    s: "上片「寒水依痕，春意渐回，沙际烟阔。溪梅晴照生香，冷芯数枝争发。天涯旧恨，试看几许消魂，长亭门外山重叠。不尽眼中青，是愁来时节」写寒水依痕、春意渐回、沙际烟阔，溪梅晴照生香、冷蕊数枝争发，天涯旧恨、几许消魂，长亭门外山重叠，不尽眼中青是愁来时节，以春景写离愁；下片「情切。画楼深闭，想见东风，暗销肌雪。辜负枕前云雨，尊前花月。心期切处，更有多少凄凉，殷勤留与归时说。到得却相逢，恰经年离别」写情切、画楼深闭、想见东风暗销肌雪，辜负枕前云雨尊前花月，心期切处多少凄凉、殷勤留与归时说，到得却相逢、恰经年离别，以久别重逢的感慨写相思，全词意境凄清、情感深沉，「到得却相逢，恰经年离别」成为名句。",
    b: "张元干这首《石州慢》写离别后的相思，以「到得却相逢，恰经年离别」写久别重逢的感慨，是婉约词的名篇。",
    n: ["石州慢：词牌名","寒水依痕：寒水依着旧痕","春意渐回：春意渐回","沙际烟阔：沙际烟阔","溪梅晴照生香：溪梅晴照生香","冷芯数枝争发：冷蕊数枝争发。芯同「蕊」","天涯旧恨：天涯旧恨","试看几许消魂：试看几许消魂","长亭门外山重叠：长亭门外山重叠","不尽眼中青：不尽眼中青","是愁来时节：是愁来时节","情切：情切","画楼深闭：画楼深闭","想见东风：想见东风","暗销肌雪：暗销肌雪（肌肤如雪消瘦）","辜负枕前云雨：辜负枕前云雨","尊前花月：尊前花月","心期切处：心期切处","更有多少凄凉：更有多少凄凉","殷勤留与归时说：殷勤留与归时说","到得却相逢：到得却相逢","恰经年离别：恰经年离别"]
  },
  "一丛花令・一丛花|张先": {
    s: "上片「伤高怀远几时穷。无物似情浓。离愁正引千丝乱，更东陌、飞絮蒙蒙。嘶骑渐遥，征尘不断，何处认郎踪」写伤高怀远几时穷、无物似情浓，离愁引千丝乱、东陌飞絮蒙蒙，嘶骑渐遥、征尘不断、何处认郎踪，以柳丝飞絮写离愁；下片「双鸳池沼水溶溶。南北小桡通。梯横画阁黄昏后，又还是、斜月帘栊。沈恨细思，不如桃杏，犹解嫁东风」写双鸳池沼水溶溶、南北小桡通，梯横画阁黄昏后、又还是斜月帘栊，沉恨细思、不如桃杏犹解嫁东风，以「不如桃杏，犹解嫁东风」写思妇的自怜——人不如桃杏还能嫁给东风，想象奇特、情感深沉，全词意境凄清，「不如桃杏，犹解嫁东风」成为千古名句。",
    b: "张先（北宋词人，「张三影」）这首《一丛花令》写闺中思妇的离愁，「不如桃杏，犹解嫁东风」是千古名句，欧阳修曾因此戏称张先为「桃杏嫁东风郎中」。",
    n: ["一丛花令：词牌名","伤高怀远几时穷：伤高怀远几时穷尽","无物似情浓：没有什么像情这样浓","离愁正引千丝乱：离愁正引千丝（柳丝）乱","更东陌、飞絮蒙蒙：更东陌飞絮蒙蒙","嘶骑渐遥：嘶鸣的马渐渐远去","征尘不断：征尘不断","何处认郎踪：何处认郎的踪迹","双鸳池沼水溶溶：双鸳池沼水溶溶（水流动的样子）","南北小桡通：南北小船通。桡音ráo，船桨","梯横画阁黄昏后：梯横画阁黄昏后","又还是、斜月帘栊：又还是斜月帘栊","沈恨细思：沉恨细思。沈同「沉」","不如桃杏：不如桃杏","犹解嫁东风：还懂得嫁给东风（桃杏随风飘落，比喻女子不如桃杏还能有所归宿）"]
  },
  "天仙子|张先": {
    s: "上片「水调数声持酒听。午醉醒来愁未醒。送春春去几时回，临晚镜。伤流景。往事后期空记省」写持酒听水调、午醉醒来愁未醒，送春春去几时回、临晚镜伤流景、往事后期空记省，以愁写伤春；下片「沙上并禽池上暝。云破月来花弄影。重重帘幕密遮灯，风不定。人初静。明日落红应满径」写沙上并禽池上暝、云破月来花弄影，重重帘幕密遮灯、风不定人初静、明日落红应满径，以「云破月来花弄影」的「弄」字写花的灵动，王国维评为「着一弄字而境界全出」，全词意境凄清、「弄」字传神，是北宋词的名篇，「云破月来花弄影」成为千古名句。",
    b: "张先这首《天仙子》写伤春之情，「云破月来花弄影」是千古名句，张先因「云破月来花弄影」「娇柔懒起，帘压卷花影」「柳径无人，堕飞絮无影」三句被称为「张三影」。",
    n: ["天仙子：词牌名","水调数声持酒听：持酒听数声《水调》曲","午醉醒来愁未醒：午醉醒来愁未醒","送春春去几时回：送春春去几时回","临晚镜：临晚镜","伤流景：伤流逝的光景","往事后期空记省：往事后期空记省（省音xǐng，记忆）","沙上并禽池上暝：沙上并禽（成对的鸟）池上暝（天黑）","云破月来花弄影：云破月来花弄影（「弄」字是千古名句，张先因此被称「云破月来花弄影郎中」）","重重帘幕密遮灯：重重帘幕密遮灯","风不定：风不定","人初静：人初静","明日落红应满径：明日落红应满径"]
  },
  "千秋岁|张先": {
    s: "上片「数声𫛸鴂。又报芳菲歇。惜春更把残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日飞花雪」写数声杜鹃、又报芳菲歇，惜春更把残红折，雨轻风色暴、梅子青时节，永丰柳无人尽日飞花雪，以春景写离愁；下片「莫把幺弦拨。怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也，东窗未白凝残月」写莫把幺弦拨、怨极弦能说，天不老情难绝、心似双丝网中有千千结，夜过也、东窗未白凝残月，以「天不老，情难绝」写爱情的坚贞、以「心似双丝网，中有千千结」写情思的缠绵，全词情感深沉、比喻新奇，「天不老，情难绝。心似双丝网，中有千千结」成为千古名句。",
    b: "张先这首《千秋岁》写爱情的坚贞，「天不老，情难绝。心似双丝网，中有千千结」是千古名句，是写爱情的名篇。",
    n: ["千秋岁：词牌名","数声𫛸鴂：数声杜鹃。𫛸鴂音tíjué，杜鹃鸟","又报芳菲歇：又报芳菲（花）凋谢","惜春更把残红折：惜春更把残红折","雨轻风色暴：雨轻风色暴","梅子青时节：梅子青时节","永丰柳：永丰柳（白居易「永丰西角荒园里，尽日无人属阿谁」）","无人尽日飞花雪：无人尽日飞柳絮如雪","莫把幺弦拨：莫把幺弦（琵琶第四弦，最细最哀）拨","怨极弦能说：怨极了弦能诉说","天不老，情难绝：天不老、情难绝","心似双丝网：心似双丝网","中有千千结：中有千千结","夜过也：夜过也","东窗未白凝残月：东窗未白凝残月"]
  },
  "六州歌头|张孝祥": {
    s: "上片「长怀望断，关塞莽然平。征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明。笳鼓悲鸣。遣人惊」写长怀望断关塞、征尘暗霜风劲，追想靖康之变、洙泗弦歌地亦膻腥，隔水毡乡、名王宵猎、笳鼓悲鸣，以中原沦陷的惨状写忠愤；下片「念腰间箭，匣中剑，空埃蠹，竟何成。时易失，心徒壮，岁将零。渺神京。干羽方怀远，静烽燧，且休兵。冠盖使，纷驰骛，若为情。闻道中原遗老，常南望，羽葆霓旌。使行人到此，忠愤气填膺。有泪如倾」写腰间箭匣中剑空埃蠹竟何成，时易失心徒壮岁将零，朝廷干羽怀远静烽燧休兵、使者纷驰骛，闻道中原遗老常南望王师，使行人到此忠愤气填膺有泪如倾，以朝廷主和与中原遗老南望对比写忠愤，全词节奏急促、情感激烈，是南宋爱国词的千古名篇，相传张浚读后为之罢席。",
    b: "张孝祥（南宋词人）这首《六州歌头》写南宋初年中原沦陷、朝廷主和的忠愤之情，相传是他在建康留守席上作，张浚读后为之罢席，是南宋爱国词的千古名篇。",
    n: ["六州歌头：词牌名","长怀望断：长怀望断","关塞莽然平：关塞莽然平","征尘暗：征尘暗","霜风劲：霜风劲","悄边声：悄边声","黯销凝：黯然销魂凝神","追想当年事：追想当年事（指靖康之变）","殆天数：大概是天数","非人力：非人力","洙泗上：洙泗上（洙水泗水，孔子讲学处，代指中原文化）","弦歌地：弦歌地（礼乐之地）","亦膻腥：也膻腥（被金人玷污）。膻音shān","隔水毡乡：隔水毡乡（金人毡帐之乡）","落日牛羊下：落日牛羊下（用《诗经》「日之夕矣，羊牛下来」）","区脱纵横：区脱纵横（区脱，匈奴筑的土室，此指金人的哨所）。区音ōu","看名王宵猎：看名王（金将）夜猎","骑火一川明：骑兵火把一川明","笳鼓悲鸣：笳鼓悲鸣","遣人惊：使人惊","念腰间箭：念腰间箭","匣中剑：匣中剑","空埃蠹：空被尘埃虫蛀。蠹音dù","竟何成：竟何成","时易失：时易失","心徒壮：心徒壮","岁将零：岁将零（将尽）","渺神京：渺神京（遥远的汴京）","干羽方怀远：干羽方怀远（用文德怀远，指朝廷主和。干羽，盾牌和雉羽，文德的象征）","静烽燧：静烽燧（烽火台安静，指不打仗）","且休兵：且休兵","冠盖使：冠盖使（使者）","纷驰骛：纷纷奔驰。骛音wù","若为情：若为情（何以为情）","闻道中原遗老：闻道中原遗老","常南望：常南望","羽葆霓旌：羽葆霓旌（皇帝的仪仗，指王师）","使行人到此：使行人到此","忠愤气填膺：忠愤气填膺","有泪如倾：有泪如倾"]
  },
  "西江月|张孝祥": {
    s: "上片「问讯湖边春色，重来又是三年。东风吹我过湖船，杨柳丝丝拂面」写问讯湖边春色、重来又是三年，东风吹我过湖船、杨柳丝丝拂面，以春景写游兴；下片「世路如今已惯，此心到处悠然。寒光庭下水如天，飞起沙鸥一片」写世路如今已惯、此心到处悠然，寒光亭下水如天、飞起沙鸥一片，以「世路已惯，此心悠然」写旷达、以「水如天」「沙鸥飞」写自由，全词意境开阔、心境旷达，是南宋词的名篇。",
    b: "张孝祥这首《西江月》写游三塔寺（在今江苏丹阳）的所见所感，以「世路如今已惯，此心到处悠然」写旷达的心境，是南宋词的名篇。",
    n: ["西江月：词牌名","问讯湖边春色：问讯湖边春色","重来又是三年：重来又是三年","东风吹我过湖船：东风吹我过湖船","杨柳丝丝拂面：杨柳丝丝拂面","世路如今已惯：世路如今已惯","此心到处悠然：此心到处悠然","寒光庭下水如天：寒光亭下水如天","飞起沙鸥一片：飞起沙鸥一片"]
  },
  "高阳台|张炎": {
    s: "上片「接叶巢莺，平波卷絮，断桥斜日归船。能几番游，看花又是明年。东风且伴蔷薇住，到蔷薇、春已堪怜。更凄然。万绿西泠，一抹荒烟」写接叶巢莺、平波卷絮、断桥斜日归船，能几番游、看花又是明年，东风且伴蔷薇住、到蔷薇春已堪怜，更凄然万绿西泠一抹荒烟，以西湖春景写惜春与亡国之思；下片「当年燕子知何处，但苔深韦曲，草暗斜川。见说新愁，如今也到鸥边。无心再续笙歌梦，掩重门、浅醉闲眠。莫开帘。怕见飞花，怕听啼鹃」写当年燕子知何处、但苔深韦曲草暗斜川，见说新愁如今也到鸥边，无心再续笙歌梦、掩重门浅醉闲眠，莫开帘怕见飞花怕听啼鹃，以燕子、苔深、草暗写今昔之感、以「怕见飞花，怕听啼鹃」写亡国之痛，全词意境凄清、用典贴切（刘禹锡燕子、韦曲、斜川、杜鹃啼归），是南宋遗民词的千古名篇。",
    b: "张炎（南宋末元初词人，「格律派」代表，号玉田）这首《高阳台》写西湖春游的亡国之思，以「莫开帘，怕见飞花，怕听啼鹃」写亡国之痛，是南宋遗民词的千古名篇。",
    n: ["高阳台：词牌名","接叶巢莺：接叶（叶叶相接）巢莺","平波卷絮：平波卷絮","断桥斜日归船：断桥斜日归船","能几番游：能几番游","看花又是明年：看花又是明年","东风且伴蔷薇住：东风且伴蔷薇住","到蔷薇、春已堪怜：到蔷薇春已堪怜","更凄然：更凄然","万绿西泠：万绿西泠（西泠桥，在西湖）","一抹荒烟：一抹荒烟","当年燕子知何处：当年燕子知何处（用刘禹锡「旧时王谢前堂燕」）","但苔深韦曲：但苔深韦曲（韦曲，在长安，代指繁华之地）","草暗斜川：草暗斜川（斜川，在江西，陶渊明游斜川）","见说新愁：见说新愁","如今也到鸥边：如今也到鸥边（鸥鸟本是忘机的，也有了愁）","无心再续笙歌梦：无心再续笙歌梦","掩重门、浅醉闲眠：掩重门浅醉闲眠","莫开帘：莫开帘","怕见飞花：怕见飞花","怕听啼鹃：怕听啼鹃（杜鹃啼声悲，且「不如归去」）"]
  },
  "清平乐|张炎": {
    s: "上片「候蛩凄断。人语西风岸。月落沙平江似练。望尽芦花无雁」写候蛩凄断、人语西风岸，月落沙平江似练、望尽芦花无雁，以秋景写愁；下片「暗教愁损兰成。可怜夜夜关情。只有一枝梧叶，不知多少秋声」写暗教愁损兰成、可怜夜夜关情，只有一枝梧叶、不知多少秋声，以「一枝梧叶」「多少秋声」写愁的细腻——一枝梧叶就能带来多少秋声，愁思之深尽在其中，全词意境凄清、以小见大，「只有一枝梧叶，不知多少秋声」成为名句。",
    b: "张炎这首《清平乐》写秋夜的愁思，以「只有一枝梧叶，不知多少秋声」写愁的细腻，是南宋遗民词的名篇。",
    n: ["清平乐：词牌名","候蛩凄断：候蛩（蟋蟀）凄断","人语西风岸：人语西风岸","月落沙平江似练：月落沙平江似练（谢朓「澄江静如练」）","望尽芦花无雁：望尽芦花无雁","暗教愁损兰成：暗教愁损兰成（庾信，小字兰成，作《哀江南赋》，此指自己）","可怜夜夜关情：可怜夜夜关情","只有一枝梧叶：只有一枝梧叶","不知多少秋声：不知多少秋声"]
  },
  "绝句·古木阴中系短篷|志南": {
    s: "首两句「古木阴中系短篷，杖藜扶我过桥东」写古木阴中系小船、拄藜杖扶我过桥东，以「系短篷」「杖藜」写春游的闲适；后两句「沾衣欲湿杏花雨，吹面不寒杨柳风」是千古名句——杏花时节的雨沾衣欲湿、杨柳时节的风吹面不寒，以「杏花雨」「杨柳风」写春天的美好，「欲湿」「不寒」二字极炼，全诗意境清新、语言明丽，是写春游的千古名篇，「沾衣欲湿杏花雨，吹面不寒杨柳风」成为千古名句。",
    b: "志南（南宋诗僧）这首《绝句》写春游的所见所感，「沾衣欲湿杏花雨，吹面不寒杨柳风」是千古名句，朱熹曾跋其诗「清丽有余，格力闲暇，无蔬笋气」。",
    n: ["绝句：诗体名","古木阴中系短篷：古木阴中系短篷（小船）","杖藜扶我过桥东：拄着藜杖扶我过桥东。藜音lí，藜茎做的杖","沾衣欲湿杏花雨：沾衣欲湿的杏花雨（杏花时节的雨）","吹面不寒杨柳风：吹面不寒的杨柳风（杨柳时节的风）"]
  },
  "酹江月・念奴娇|文天祥": {
    s: "上片「庐山依旧，凄凉处、无限江南风物。空翠晴岚浮汗漫，还障天东半壁。雁过孤峰，猿归危嶂，风急波翻雪。乾坤未老，地灵尚有人杰」写庐山依旧、凄凉处无限江南风物，空翠晴岚浮汗漫还障天东半壁，雁过孤峰猿归危嶂风急波翻雪，乾坤未老地灵尚有人杰，以庐山的雄伟写不屈的气节；下片「堪嗟漂泊孤舟，河倾斗落，客梦催明发。南浦闲云连草树，回首旌旗明灭。三十年来，十年一过，空有星星发。夜深愁听，胡笳吹彻寒月」写堪嗟漂泊孤舟、河倾斗落客梦催明发，南浦闲云连草树回首旌旗明灭，三十年来十年一过空有星星发，夜深愁听胡笳吹彻寒月，以漂泊与胡笳写亡国之痛，全词意境苍凉、气节凛然，「乾坤未老，地灵尚有人杰」成为名句，是南宋爱国词的千古名篇。",
    b: "文天祥（南宋末民族英雄）这首《酹江月》写他被元军俘虏后押解北上、途经庐山时的所见所感，以「乾坤未老，地灵尚有人杰」写不屈的气节，是南宋爱国词的千古名篇。",
    n: ["酹江月：词牌名，即《念奴娇》","庐山依旧：庐山依旧","凄凉处、无限江南风物：凄凉处无限江南风物","空翠晴岚浮汗漫：空翠晴岚浮汗漫（汗漫，广大无边）。岚音lán，山气","还障天东半壁：还障天东半壁","雁过孤峰：雁过孤峰","猿归危嶂：猿归危嶂","风急波翻雪：风急波翻雪","乾坤未老：乾坤未老","地灵尚有人杰：地灵尚有人杰","堪嗟漂泊孤舟：堪嗟漂泊孤舟","河倾斗落：河倾斗落","客梦催明发：客梦催明发","南浦闲云连草树：南浦闲云连草树","回首旌旗明灭：回首旌旗明灭","三十年来：三十年来","十年一过：十年一过","空有星星发：空有星星发（花白的头发）","夜深愁听：夜深愁听","胡笳吹彻寒月：胡笳吹彻寒月"]
  },
  "正气歌|文天祥": {
    s: "全诗分四层：第一层「天地有正气……道义为之根」写正气的本源——天地有正气，下为河岳上为日星，于人曰浩然沛乎塞苍冥，时穷节乃见一一垂丹青，列举齐太史简、晋董狐笔、秦张良椎、汉苏武节、严将军头、嵇侍中血、张睢阳齿、颜常山舌、辽东帽、出师表、渡江楫、击贼笏十二位忠臣义士的事迹，写正气所磅礴凛烈万古存，生死安足论，地维天柱赖以尊，三纲道义为之根；第二层「嗟予遘阳九……百沴自辟易」写自己的遭遇——遭逢阳九、楚囚送穷北，鼎镬甘如饴求之不可得，阴房鬼火春院天黑，牛骥同皂鸡栖凤凰，一朝蒙雾露分作沟中瘠，如此再寒暑百沴自辟易；第三层「嗟哉沮洳场……苍天曷有极」写自己在狱中以正气自守——沮洳场为我安乐国，岂有他缪巧阴阳不能贼，顾此耿耿在仰视浮云白，悠悠我心悲苍天曷有极；第四层「哲人日已远……古道照颜色」写以古人为楷模——哲人日已远典刑在夙昔，风檐展书读古道照颜色。全诗气势磅礴、用典丰富、气节凛然，是中国文学史上最著名的爱国诗篇。",
    b: "文天祥这首《正气歌》是他被元军俘虏后、囚禁在大都（今北京）时所作，列举历史上十二位忠臣义士的壮烈事迹，抒发自己的浩然正气与不屈气节，是中国文学史上最著名的爱国诗篇之一。",
    n: ["正气歌：诗体名，文天祥作","杂然赋流形：杂然赋予各种形体","下则为河岳：下则为河岳","上则为日星：上则为日星","于人曰浩然：于人叫做浩然之气","沛乎塞苍冥：充沛地充满天地。苍冥，天地","皇路当清夷：国家政治清明太平时。皇路，国家政治；清夷，清明太平","含和吐明庭：含和而立于明庭（朝廷）","时穷节乃见：时运穷困时节操才显现。见同「现」","一一垂丹青：一一垂名丹青（史册）","在齐太史简：齐国太史的竹简（太史兄弟直书「崔杼弑其君」）","在晋董狐笔：晋国董狐的笔（董狐直书「赵盾弑其君」）","在秦张良椎：秦朝张良的铁椎（张良使力士击秦始皇于博浪沙）","在汉苏武节：汉朝苏武的节（苏武持节牧羊十九年不降）","为严将军头：为严将军（严颜，「但有断头将军，无降将军」）的头","为嵇侍中血：为嵇侍中（嵇绍，为保护晋惠帝而死）的血","为张睢阳齿：为张睢阳（张巡，守睢阳，咬牙切齿）的齿","为颜常山舌：为颜常山（颜杲卿，守常山，骂贼被割舌）的舌","或为辽东帽：或为辽东帽（管宁，隐居辽东，戴黑帽）","清操厉冰雪：清操厉如冰雪","或为出师表：或为《出师表》（诸葛亮）","鬼神泣壮烈：鬼神泣其壮烈","或为渡江楫：或为渡江楫（祖逖，中流击楫「不能清中原而复济者，有如大江」）","慷慨吞胡羯：慷慨吞胡羯","或为击贼笏：或为击贼笏（段秀实，以笏击朱泚）","逆竖头破裂：逆竖（叛贼）头破裂","是气所磅礴：这气所磅礴","凛烈万古存：凛烈万古存","当其贯日月：当它贯穿日月","生死安足论：生死哪里值得论","地维赖以立：地维（地的四角）赖以立","天柱赖以尊：天柱赖以尊","三纲实系命：三纲实系命","道义为之根：道义为之根","嗟予遘阳九：嗟我遭逢阳九（厄运）。遘音gòu，遭逢；阳九，厄运","隶也实不力：我（隶，奴仆，自谦）实在不力","楚囚缨其冠：楚囚（被俘的人）戴着冠（用钟仪「南冠而絷」典故）","传车送穷北：传车送到穷北","鼎镬甘如饴：鼎镬（酷刑）甘如饴（糖）。镬音huò","求之不可得：求之不可得","阴房阗鬼火：阴房阗（寂静）鬼火。阗音tián","春院閟天黑：春院閟（关闭）天黑。閟音bì","牛骥同一皂：牛和骥（千里马）同一皂（马槽）","鸡栖凤凰食：鸡栖凤凰食（凤凰和鸡一样吃食）","一朝蒙雾露：一旦蒙雾露（生病）","分作沟中瘠：分（理应）作沟中瘠（沟中的枯骨）。瘠音zí，枯骨","如此再寒暑：如此过了两年（再寒暑，两年）","百沴自辟易：百沴（各种灾疫）自辟易（退避）。沴音lì","嗟哉沮洳场：嗟哉沮洳场（低湿的地方）。沮洳音jùrù","为我安乐国：为我安乐国","岂有他缪巧：岂有他缪巧（计谋）。缪同「谬」","阴阳不能贼：阴阳（寒暑）不能贼（害）","顾此耿耿在：顾此耿耿（忠心）在","仰视浮云白：仰视浮云白","悠悠我心悲：悠悠我心悲","苍天曷有极：苍天曷（何）有极","哲人日已远：哲人日已远","典刑在夙昔：典刑（楷模）在夙昔（从前）","风檐展书读：风檐展书读","古道照颜色：古道照颜色"]
  },
  "鹧鸪天|晏几道": {
    s: "上片「彩袖殷勤捧玉钟。当年拼却醉颜红。舞低杨柳楼心月，歌尽桃花扇影风」写彩袖殷勤捧玉钟、当年拼却醉颜红，舞低杨柳楼心月、歌尽桃花扇影风，以「舞低」「歌尽」写当年的欢乐；下片「从别后，忆相逢。几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中」写从别后忆相逢、几回魂梦与君同，今宵剩把银釭照、犹恐相逢是梦中，以「犹恐相逢是梦中」写久别重逢的惊喜与不敢置信，全词今昔对比、情感深沉，「舞低杨柳楼心月，歌尽桃花扇影风」「今宵剩把银釭照，犹恐相逢是梦中」成为千古名句，是婉约词的千古名篇。",
    b: "晏几道（北宋词人，晏殊第七子，号小山）这首《鹧鸪天》写与歌女的久别重逢，「舞低杨柳楼心月，歌尽桃花扇影风」「今宵剩把银釭照，犹恐相逢是梦中」是千古名句，是婉约词的千古名篇。",
    n: ["鹧鸪天：词牌名","彩袖殷勤捧玉钟：彩袖（歌女）殷勤捧玉钟（酒杯）","当年拼却醉颜红：当年拼却醉颜红。拼音pīn，不顾","舞低杨柳楼心月：舞低杨柳楼心月（舞到月亮西沉）","歌尽桃花扇影风：歌尽桃花扇影风（歌到扇影风停）","从别后：从别后","忆相逢：忆相逢","几回魂梦与君同：几回魂梦与君同","今宵剩把银釭照：今宵尽把银釭（灯）照。釭音gāng，灯","犹恐相逢是梦中：犹恐相逢是梦中"]
  },
  "生查子|晏几道": {
    s: "上片「金鞭美少年，去跃青骢马。牵系玉楼人，绣被春寒夜」写金鞭美少年去跃青骢马，牵系玉楼人、绣被春寒夜，以少年的远游写女子的思念；下片「消息未归来，寒食梨花谢。无处说相思，背面秋千下」写消息未归来、寒食梨花谢，无处说相思、背面秋千下，以「背面秋千下」的细节写相思的无言——无处诉说，只能背对着人在秋千下默默思念，细节生动、情感深沉，全词意境凄清，「无处说相思，背面秋千下」成为名句。",
    b: "晏几道这首《生查子》写闺中女子思念远游的少年，以「背面秋千下」写相思的无言，是婉约词的名篇。",
    n: ["生查子：词牌名","金鞭美少年：金鞭美少年","去跃青骢马：去跃青骢马（青白色的马）。骢音cōng","牵系玉楼人：牵系玉楼人（楼上的女子）","绣被春寒夜：绣被春寒夜","消息未归来：消息未归来","寒食梨花谢：寒食梨花谢","无处说相思：无处说相思","背面秋千下：背面秋千下"]
  },
  "清平乐|晏几道": {
    s: "上片「留人不住。醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处」写留人不住、醉解兰舟去，一棹碧涛春水路、过尽晓莺啼处，以留人不住写离别的无奈；下片「渡头杨柳青青。枝枝叶叶离情。此后锦书休寄，画楼云雨无凭」写渡头杨柳青青、枝枝叶叶离情，此后锦书休寄、画楼云雨无凭，以「锦书休寄」「云雨无凭」写失恋的决绝——既然靠不住，就不要再寄信了，决绝中含痛苦，全词意境凄清、情感深沉，「此后锦书休寄，画楼云雨无凭」成为名句。",
    b: "晏几道这首《清平乐》写送别后的决绝，以「此后锦书休寄，画楼云雨无凭」写失恋的痛苦，是婉约词的名篇。",
    n: ["清平乐：词牌名","留人不住：留人不住","醉解兰舟去：醉解兰舟（木兰舟）去","一棹碧涛春水路：一棹碧涛春水路","过尽晓莺啼处：过尽晓莺啼处","渡头杨柳青青：渡头杨柳青青","枝枝叶叶离情：枝枝叶叶离情","此后锦书休寄：此后锦书（情书）休寄","画楼云雨无凭：画楼云雨无凭（靠不住）"]
  },
  "阮郎归|晏几道": {
    s: "上片「旧香残粉似当初。人情恨不如。一春犹有数行书。秋来书更疏」写旧香残粉似当初、人情恨不如，一春犹有数行书、秋来书更疏，以物是人非写相思；下片「衾凤冷，枕鸳孤。愁肠待酒舒。梦魂纵有也成虚。那堪和梦无」写衾凤冷枕鸳孤、愁肠待酒舒，梦魂纵有也成虚、那堪和梦无，以「和梦无」写相思的极致——连梦都没有，比梦中相见更痛苦，全词意境凄清、情感深沉，「梦魂纵有也成虚，那堪和梦无」成为名句。",
    b: "晏几道这首《阮郎归》写闺中女子的相思，以「梦魂纵有也成虚，那堪和梦无」写相思的深沉，是婉约词的名篇。",
    n: ["阮郎归：词牌名","旧香残粉似当初：旧香残粉似当初","人情恨不如：人情恨不如","一春犹有数行书：一春犹有数行书","秋来书更疏：秋来书更疏","衾凤冷：衾凤（绣凤的被子）冷。衾音qīn","枕鸳孤：枕鸳（绣鸳的枕头）孤","愁肠待酒舒：愁肠待酒舒","梦魂纵有也成虚：梦魂纵有也成虚","那堪和梦无：那堪和梦无（连梦都没有）"]
  },
  "少年游|晏几道": {
    s: "上片「离多最是，东西流水，终解两相逢。浅情终似，行云无定，犹到梦魂中」写离多最是东西流水、终解两相逢，浅情终似行云无定、犹到梦魂中，以流水、行云反衬——流水还能相逢、行云还能到梦；下片「可怜人意，薄于云水，佳会更难重。细想从来，断肠多处，不与者番同」写可怜人意薄于云水、佳会更难重，细想从来断肠多处、不与者番同，以「人意薄于云水」写人情的淡薄——人还不如云和水，以「不与者番同」写这次离别最断肠，全词层层递进、情感深沉，「可怜人意，薄于云水」成为名句。",
    b: "晏几道这首《少年游》写离别的痛苦，以「人意薄于云水」写人情的淡薄，是婉约词的名篇。",
    n: ["少年游：词牌名","离多最是：离多最是","东西流水：东西流水","终解两相逢：终解两相逢（流水东西流去还能相逢）","浅情终似：浅情终似","行云无定：行云无定","犹到梦魂中：犹到梦魂中（行云还能到梦中）","可怜人意：可怜人意","薄于云水：薄于云水（人的情意比云和水还薄）","佳会更难重：佳会更难重","细想从来：细想从来","断肠多处：断肠多处","不与者番同：不与者番（这次）同。者同「这」"]
  },
  "思远人|晏几道": {
    s: "上片「红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得」写红叶黄花秋意晚、千里念行客，飞云过尽归鸿无信、何处寄书得，以秋景写相思；下片「泪弹不尽临窗滴。就砚旋研墨。渐写到别来，此情深处，红笺为无色」写泪弹不尽临窗滴、就砚旋研墨，渐写到别来此情深处、红笺为无色，以「泪滴研墨」「红笺无色」的细节写情之深——眼泪滴到砚台里研墨，写到情深处红笺都被泪浸湿褪色，想象奇特、细节生动，全词意境凄清、情感深沉，「红笺为无色」成为千古名句。",
    b: "晏几道这首《思远人》写闺中女子思念远人、写信寄情，以「红笺为无色」写泪之多、情之深，是婉约词的千古名篇。",
    n: ["思远人：词牌名（晏几道自度曲）","红叶黄花秋意晚：红叶黄花秋意晚","千里念行客：千里念行客","飞云过尽：飞云过尽","归鸿无信：归鸿无信","何处寄书得：何处寄书得","泪弹不尽临窗滴：泪弹不尽临窗滴","就砚旋研墨：就砚台随即研墨","渐写到别来：渐写到别来","此情深处：此情深处","红笺为无色：红笺（红纸）为无色（被泪浸湿褪色）"]
  },
  "浣溪沙|晏殊": {
    s: "上片「一曲新词酒一杯。去年天气旧亭台。夕阳西下几时回」写一曲新词酒一杯、去年天气旧亭台，夕阳西下几时回，以新词美酒与旧亭台对比写时光流逝；下片「无可奈何花落去，似曾相识燕归来。小园香径独徘徊」写无可奈何花落去、似曾相识燕归来，小园香径独徘徊，以「花落去」「燕归来」写春去春来、时光流逝，「无可奈何」与「似曾相识」对比，蕴含深刻的人生哲理，全词意境清丽、哲理深沉，「无可奈何花落去，似曾相识燕归来」成为千古名句，是婉约词的千古名篇。",
    b: "晏殊（北宋词人，官至宰相，「大晏」）这首《浣溪沙》写伤春惜时之情，「无可奈何花落去，似曾相识燕归来」是千古名句，是婉约词的千古名篇。",
    n: ["浣溪沙：词牌名","一曲新词酒一杯：一曲新词酒一杯","去年天气旧亭台：去年天气旧亭台","夕阳西下几时回：夕阳西下几时回","无可奈何花落去：无可奈何花落去","似曾相识燕归来：似曾相识燕归来","小园香径独徘徊：小园香径独徘徊"]
  },
  "鹊踏枝・蝶恋花|晏殊": {
    s: "上片「槛菊愁烟兰泣露。罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户」写槛菊愁烟兰泣露、罗幕轻寒燕子双飞，明月不谙离恨苦、斜光到晓穿朱户，以菊愁兰泣、燕双飞写思妇的孤独；下片「昨夜西风凋碧树。独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处」写昨夜西风凋碧树、独上高楼望尽天涯路，欲寄彩笺兼尺素、山长水阔知何处，以「独上高楼，望尽天涯路」写思妇的执着与迷茫，意境开阔、情感深沉，「昨夜西风凋碧树，独上高楼，望尽天涯路」成为千古名句，王国维列为人生三境界之第一境界。",
    b: "晏殊这首《蝶恋花》写闺中思妇的离愁，「昨夜西风凋碧树，独上高楼，望尽天涯路」是千古名句，王国维在《人间词话》中将其列为「古今之成大事业、大学问者」的第一境界。",
    n: ["鹊踏枝：词牌名，即《蝶恋花》","槛菊愁烟兰泣露：栏外菊花愁于烟、兰花泣于露","罗幕轻寒：罗幕轻寒","燕子双飞去：燕子双飞去","明月不谙离恨苦：明月不谙（熟悉）离恨苦。谙音ān","斜光到晓穿朱户：斜光到晓穿朱户","昨夜西风凋碧树：昨夜西风凋碧树","独上高楼：独上高楼","望尽天涯路：望尽天涯路","欲寄彩笺兼尺素：欲寄彩笺（彩色信纸）兼尺素（书信）","山长水阔知何处：山长水阔知何处"]
  },
  "清平乐|晏殊": {
    s: "上片「红笺小字。说尽平生意。鸿雁在云鱼在水。惆怅此情难寄」写红笺小字说尽平生意，鸿雁在云鱼在水、惆怅此情难寄，以雁鱼传书的典故写信难寄；下片「斜阳独倚西楼。遥山恰对帘钩。人面不知何处，绿波依旧东流」写斜阳独倚西楼、遥山恰对帘钩，人面不知何处、绿波依旧东流，以「人面不知何处，绿波依旧东流」写物是人非——人不知去了哪里，只有绿波依旧东流，用崔护典故，全词意境清丽、情感深沉，「人面不知何处，绿波依旧东流」成为名句。",
    b: "晏殊这首《清平乐》写思念情人的惆怅，以「人面不知何处，绿波依旧东流」写物是人非，是婉约词的名篇。",
    n: ["清平乐：词牌名","红笺小字：红笺小字","说尽平生意：说尽平生意","鸿雁在云鱼在水：鸿雁在云鱼在水（雁足传书、鱼腹藏书的典故）","惆怅此情难寄：惆怅此情难寄","斜阳独倚西楼：斜阳独倚西楼","遥山恰对帘钩：遥山恰对帘钩","人面不知何处：人面不知何处（用崔护「人面不知何处去，桃花依旧笑春风」）","绿波依旧东流：绿波依旧东流"]
  },
  "采桑子|晏殊": {
    s: "上片「时光只解催人老。不信多情。长恨离亭。泪滴春衫酒易醒」写时光只解催人老、不信多情，长恨离亭、泪滴春衫酒易醒，以时光催人写离情；下片「梧桐昨夜西风急。淡月胧明。好梦频惊。何处高楼雁一声」写梧桐昨夜西风急、淡月胧明，好梦频惊、何处高楼雁一声，以「雁一声」写惊梦后的凄凉——一声雁叫惊醒好梦，不知从何处高楼传来，以声写情，全词意境凄清、情感深沉，「时光只解催人老」成为名句。",
    b: "晏殊这首《采桑子》写时光流逝与离情，以「何处高楼雁一声」写惊梦后的凄凉，是婉约词的名篇。",
    n: ["采桑子：词牌名","时光只解催人老：时光只解催人老","不信多情：不信多情","长恨离亭：长恨离亭","泪滴春衫酒易醒：泪滴春衫酒易醒","梧桐昨夜西风急：梧桐昨夜西风急","淡月胧明：淡月胧明","好梦频惊：好梦频惊","何处高楼雁一声：何处高楼雁一声"]
  },
  "木兰花・玉楼春|晏殊": {
    s: "上片「东风昨夜回梁苑。日脚依稀添一线。旋开杨柳绿蛾眉，暗拆海棠红粉面」写东风昨夜回梁苑、日脚添一线，旋开杨柳绿蛾眉、暗拆海棠红粉面，以柳叶如蛾眉、海棠如粉面写初春的美好；下片「无情一去云中雁。有意归来梁上燕。有情无意且休论，莫向酒杯容易散」写无情一去云中雁、有意归来梁上燕，有情无意且休论、莫向酒杯容易散，以雁去燕来写春的来去、以「莫向酒杯容易散」写惜春之情，全词色彩明丽、对仗工稳，「无情一去云中雁，有意归来梁上燕」成为名句。",
    b: "晏殊这首《玉楼春》写初春景色与惜春之情，以「无情一去云中雁，有意归来梁上燕」写春的来去，是婉约词的名篇。",
    n: ["木兰花：词牌名，即《玉楼春》","东风昨夜回梁苑：东风昨夜回梁苑（梁苑，汉梁孝王的兔园，此指园林）","日脚依稀添一线：日脚依稀添一线（冬至后日长一线）","旋开杨柳绿蛾眉：旋开杨柳绿蛾眉（柳叶如蛾眉）","暗拆海棠红粉面：暗拆海棠红粉面（海棠如红粉面）","无情一去云中雁：无情一去云中雁","有意归来梁上燕：有意归来梁上燕","有情无意且休论：有情无意且休论","莫向酒杯容易散：莫向酒杯容易散"]
  },
  "诉衷情|晏殊": {
    s: "上片「芙蓉金菊斗馨香。天气欲重阳。远村秋色如画，红树间疏黄」写芙蓉金菊斗馨香、天气欲重阳，远村秋色如画、红树间疏黄，以秋色写重阳前的景色；下片「流水淡，碧天长。路茫茫。凭高目断，鸿雁来时，无限思量」写流水淡碧天长路茫茫，凭高目断、鸿雁来时无限思量，以「凭高目断」「鸿雁来时」写思乡——登高望远，大雁飞来时引起无限思量，全词意境开阔、情感深沉，「凭高目断，鸿雁来时，无限思量」成为名句。",
    b: "晏殊这首《诉衷情》写重阳前的秋色与思乡之情，以「凭高目断，鸿雁来时，无限思量」写秋思，是婉约词的名篇。",
    n: ["诉衷情：词牌名","芙蓉金菊斗馨香：芙蓉金菊斗馨香","天气欲重阳：天气欲重阳","远村秋色如画：远村秋色如画","红树间疏黄：红树间疏黄","流水淡：流水淡","碧天长：碧天长","路茫茫：路茫茫","凭高目断：凭高目断","鸿雁来时：鸿雁来时","无限思量：无限思量"]
  },
  "鹧鸪天|朱敦儒": {
    s: "上片「我是清都山水郎。天教懒慢带疏狂。曾批给露支风敕，累奏留云借月章」写我是清都山水郎、天教懒慢带疏狂，曾批给露支风敕、累奏留云借月章，以「清都山水郎」的自称写疏狂；下片「诗万首，酒千觞。几曾着眼看侯王。玉楼金阙慵归去，且插梅花醉洛阳」写诗万首酒千觞、几曾着眼看侯王，玉楼金阙慵归去、且插梅花醉洛阳，以「几曾着眼看侯王」写对功名的蔑视、以「插梅花醉洛阳」写疏狂，全词气势豪迈、语言明快，「诗万首，酒千觞，几曾着眼看侯王」成为千古名句。",
    b: "朱敦儒（南宋词人，号岩壑）这首《鹧鸪天》写自己的疏狂与对功名的蔑视，「诗万首，酒千觞，几曾着眼看侯王」是千古名句，是南宋词的名篇。",
    n: ["鹧鸪天：词牌名","我是清都山水郎：我是清都（天宫）山水郎（管理山水的官）","天教懒慢带疏狂：天教懒慢带疏狂","曾批给露支风敕：曾批给露支风的敕令（管理风雨的命令）。敕音chì","累奏留云借月章：屡次上奏留云借月的奏章","诗万首：诗万首","酒千觞：酒千觞。觞音shāng，酒杯","几曾着眼看侯王：几曾着眼看侯王","玉楼金阙慵归去：玉楼金阙（天宫）慵（懒）归去","且插梅花醉洛阳：且插梅花醉洛阳"]
  },
  "好事近|朱敦儒": {
    s: "上片「摇首出红尘。醒醉更无时节。活计绿蓑青笠，惯披霜冲雪」写摇首出红尘、醒醉无时节，活计绿蓑青笠、惯披霜冲雪，以渔父生活写自由；下片「晚来风定钓丝闲。上下是新月。千里水天一色，看孤鸿明灭」写晚来风定钓丝闲、上下是新月，千里水天一色、看孤鸿明灭，以「水天一色」「孤鸿明灭」写自由的境界，全词意境开阔、语言明快，「千里水天一色，看孤鸿明灭」成为名句。",
    b: "朱敦儒这首《好事近》写渔父的隐居生活，以「千里水天一色，看孤鸿明灭」写自由的境界，是南宋词的名篇。",
    n: ["好事近：词牌名","摇首出红尘：摇首出红尘（尘世）","醒醉更无时节：醒醉更无时节","活计绿蓑青笠：活计是绿蓑青笠（蓑衣斗笠）","惯披霜冲雪：惯披霜冲雪","晚来风定钓丝闲：晚来风定钓丝闲","上下是新月：上下是新月","千里水天一色：千里水天一色","看孤鸿明灭：看孤鸿明灭（忽明忽暗）"]
  },
  "西江月|朱敦儒": {
    s: "上片「日日深杯酒满。朝朝小圃花开。自歌自舞自开怀。且喜无拘无碍」写日日深杯酒满、朝朝小圃花开，自歌自舞自开怀、且喜无拘无碍，以隐居生活写快乐；下片「青史几番春梦。黄泉多少奇才。不须计较与安排。领取而今现在」写青史几番春梦、黄泉多少奇才，不须计较与安排、领取而今现在，以「青史春梦」「黄泉奇才」写人生短暂、以「领取而今现在」写及时行乐，全词语言明快、哲理深沉，「领取而今现在」成为名句。",
    b: "朱敦儒这首《西江月》写隐居生活的旷达，以「领取而今现在」写及时行乐的人生态度，是南宋词的名篇。",
    n: ["西江月：词牌名","日日深杯酒满：日日深杯酒满","朝朝小圃花开：朝朝小圃花开","自歌自舞自开怀：自歌自舞自开怀","且喜无拘无碍：且喜无拘无碍","青史几番春梦：青史几番春梦","黄泉多少奇才：黄泉多少奇才","不须计较与安排：不须计较与安排","领取而今现在：领取而今现在"]
  },
  "相见欢|朱敦儒": {
    s: "上片「金陵城上西楼。倚清秋。万里夕阳垂地、大江流」写金陵城上西楼、倚清秋，万里夕阳垂地大江流，以夕阳大江写亡国的苍凉；下片「中原乱。簪缨散。几时收。试倩悲风吹泪、过扬州」写中原乱、簪缨散、几时收，试倩悲风吹泪过扬州，以「中原乱，簪缨散，几时收」写亡国之痛与收复之望、以「悲风吹泪过扬州」写对中原的思念，全词意境苍凉、情感激烈，「中原乱，簪缨散，几时收」成为千古名句，是南宋爱国词的名篇。",
    b: "朱敦儒这首《相见欢》写登金陵城楼所见与亡国之痛，「中原乱，簪缨散，几时收」是千古名句，是南宋爱国词的名篇。",
    n: ["相见欢：词牌名","金陵城上西楼：金陵城上西楼","倚清秋：倚清秋","万里夕阳垂地、大江流：万里夕阳垂地大江流","中原乱：中原乱（靖康之变）","簪缨散：簪缨（官员）散","几时收：几时收（收复）","试倩悲风吹泪、过扬州：试请悲风吹泪过扬州。倩音qìng，请"]
  },
  "卜算子|李之仪": {
    s: "上片「我住长江头，君住长江尾。日日思君不见君，共饮长江水」写我住长江头、君住长江尾，日日思君不见君、共饮长江水，以长江水为喻写两地相思——虽然相隔千里，但共饮一江水；下片「此水几时休，此恨何时已。只愿君心似我心，定不负相思意」写此水几时休、此恨何时已，只愿君心似我心、定不负相思意，以江水无尽写相思无尽、以「君心似我心」写对爱情的坚贞，全词语言朴素、比喻巧妙、情感深沉，「我住长江头，君住长江尾」成为千古名句，是婉约词的千古名篇。",
    b: "李之仪（北宋词人）这首《卜算子》写女子对情人的相思，以长江水为喻，「我住长江头，君住长江尾。日日思君不见君，共饮长江水」是千古名句，是婉约词的千古名篇。",
    n: ["卜算子：词牌名","我住长江头：我住长江头","君住长江尾：君住长江尾","日日思君不见君：日日思君不见君","共饮长江水：共饮长江水","此水几时休：此水几时休","此恨何时已：此恨何时已","只愿君心似我心：只愿君心似我心","定不负相思意：定不负相思意"]
  },
  "孤雁儿・御街行|李清照": {
    s: "上片「藤床纸帐朝眠起。说不尽、无佳思。沈香断续玉炉寒，伴我情怀如水。笛里三弄，梅心惊破，多少春情意」写藤床纸帐朝眠起、说不尽无佳思，沉香断续玉炉寒、伴我情怀如水，笛里三弄梅心惊破、多少春情意，以独居生活写孤独；下片「小风疏雨萧萧地。又催下、千行泪。吹箫人去玉楼空，肠断与谁同倚。一枝折得，人间天上，没个人堪寄」写小风疏雨萧萧、又催下千行泪，吹箫人去玉楼空、肠断与谁同倚，一枝折得人间天上、没个人堪寄，以「吹箫人去」写丈夫去世、以「没个人堪寄」写悼亡之痛——折了梅花却无人可寄，全词意境凄清、情感深沉，「吹箫人去玉楼空，肠断与谁同倚」成为名句，是婉约词的千古名篇。",
    b: "李清照（南宋女词人，号易安居士）这首《孤雁儿》是她丈夫赵明诚去世后所作，写悼亡之情，「吹箫人去玉楼空，肠断与谁同倚」是名句，是婉约词的千古名篇。",
    n: ["孤雁儿：词牌名，即《御街行》","藤床纸帐朝眠起：藤床纸帐朝眠起","说不尽、无佳思：说不尽无佳思","沈香断续玉炉寒：沉香断续玉炉寒。沈同「沉」","伴我情怀如水：伴我情怀如水","笛里三弄：笛里三弄（《梅花三弄》笛曲）","梅心惊破：梅心惊破","多少春情意：多少春情意","小风疏雨萧萧地：小风疏雨萧萧地","又催下、千行泪：又催下千行泪","吹箫人去玉楼空：吹箫人去玉楼空（用萧史弄玉吹箫引凤典故，指丈夫去世）","肠断与谁同倚：肠断与谁同倚","一枝折得：一枝折得（折梅）","人间天上：人间天上","没个人堪寄：没个人堪寄（无人可寄）"]
  },
  "渔家傲|李清照": {
    s: "上片「雪里已知春信至。寒梅点缀琼枝腻。香脸半开娇旖旎。当庭际。玉人浴出新妆洗」写雪里已知春信至、寒梅点缀琼枝腻，香脸半开娇旖旎、当庭际玉人浴出新妆洗，以「玉人浴出」比喻梅花的美丽；下片「造化可能偏有意。故教明月玲珑地。共赏金尊沈绿蚁。莫辞醉。此花不与群花比」写造化可能偏有意、故教明月玲珑地，共赏金尊沉绿蚁、莫辞醉，此花不与群花比，以「此花不与群花比」写梅的高洁，全词色彩明丽、比喻巧妙，「此花不与群花比」成为名句。",
    b: "李清照这首《渔家傲》写寒梅的美丽与高洁，以「此花不与群花比」写梅的品格，是咏梅词的名篇。",
    n: ["渔家傲：词牌名","雪里已知春信至：雪里已知春信至","寒梅点缀琼枝腻：寒梅点缀琼枝（如玉的枝）腻（细腻）","香脸半开娇旖旎：香脸半开娇旖旎（柔美）。旖旎音yǐnǐ","当庭际：当庭际","玉人浴出新妆洗：玉人浴出新妆洗","造化可能偏有意：造化可能偏有意","故教明月玲珑地：故教明月玲珑地","共赏金尊沈绿蚁：共赏金尊沉绿蚁（酒面上的泡沫，代指酒）。沈同「沉」","莫辞醉：莫辞醉","此花不与群花比：此花不与群花比"]
  },
  "如梦令|李清照": {
    s: "全词「常记溪亭日暮。沈醉不知归路。兴尽晚回舟，误入藕花深处。争渡。争渡。惊起一滩鸥鹭」写常记溪亭日暮、沉醉不知归路，兴尽晚回舟、误入藕花深处，争渡争渡、惊起一滩鸥鹭，以「误入藕花深处」「争渡」「惊起鸥鹭」写郊游的欢乐与少女的天真，全词语言明快、画面生动、情感欢乐，「争渡，争渡，惊起一滩鸥鹭」成为千古名句，是婉约词的千古名篇，也是李清照早期词的代表作。",
    b: "李清照这首《如梦令》是她少女时代的作品，写一次郊游的欢乐经历，「争渡，争渡，惊起一滩鸥鹭」是千古名句，是婉约词的千古名篇。",
    n: ["如梦令：词牌名","常记溪亭日暮：常记溪亭日暮","沈醉不知归路：沉醉不知归路。沈同「沉」","兴尽晚回舟：兴尽晚回舟","误入藕花深处：误入藕花深处","争渡：争渡（怎么渡出去，一说「怎渡」）","争渡：争渡","惊起一滩鸥鹭：惊起一滩鸥鹭"]
  },
  "菩萨蛮|李清照": {
    s: "上片「风柔日薄春犹早。夹衫乍著心情好。睡起觉微寒。梅花鬓上残」写风柔日薄春犹早、夹衫乍著心情好，睡起觉微寒、梅花鬓上残，以早春景色写南渡后的生活；下片「故乡何处是。忘了除非醉。沈水卧时烧。香消酒未消」写故乡何处是、忘了除非醉，沉水卧时烧、香消酒未消，以「忘了除非醉」写思乡之深——只有喝醉了才能忘记故乡，以「香消酒未消」写酒醒后的痛苦，全词意境凄清、情感深沉，「故乡何处是，忘了除非醉」成为千古名句，是婉约词的千古名篇。",
    b: "李清照这首《菩萨蛮》是她南渡后所作，写思乡之情，「故乡何处是，忘了除非醉」是千古名句，是婉约词的千古名篇。",
    n: ["菩萨蛮：词牌名","风柔日薄春犹早：风柔日薄春犹早","夹衫乍著心情好：夹衫乍著（刚穿上）心情好。著同「着」","睡起觉微寒：睡起觉微寒","梅花鬓上残：梅花鬓上残","故乡何处是：故乡何处是","忘了除非醉：忘了除非醉","沈水卧时烧：沉水（沉香）卧时烧。沈同「沉」","香消酒未消：香消酒未消"]
  },
  "凤凰台上忆吹箫|李清照": {
    s: "上片「香冷金猊，被翻红浪，起来人未梳头。任宝奁闲掩，日上帘钩。生怕闲愁暗恨，多少事、欲说还休。今年瘦，非干病酒，不是悲秋」写香冷金猊、被翻红浪、起来未梳头，任宝奁闲掩日上帘钩，生怕闲愁暗恨、多少事欲说还休，今年瘦非干病酒不是悲秋，以「欲说还休」「非干病酒，不是悲秋」写离情的深沉——瘦了不是因为醉酒也不是因为悲秋，而是因为离别；下片「明朝，这回去也，千万遍阳关，也即难留。念武陵春晚，云锁重楼。记取楼前绿水，应念我、终日凝眸。凝眸处，从今更数，几段新愁」写明朝这回去也、千万遍阳关也难留，念武陵春晚云锁重楼，记取楼前绿水应念我终日凝眸，凝眸处从今更数几段新愁，以「千万遍阳关也难留」写离别的无奈、以「终日凝眸」写思念，全词意境凄清、情感深沉，「今年瘦，非干病酒，不是悲秋」「多少事、欲说还休」成为千古名句，是婉约词的千古名篇。",
    b: "李清照这首《凤凰台上忆吹箫》是她与丈夫赵明诚离别时所作，写离情，「今年瘦，非干病酒，不是悲秋」「多少事、欲说还休」是千古名句，是婉约词的千古名篇。",
    n: ["凤凰台上忆吹箫：词牌名","香冷金猊：香冷金猊（狮形香炉）。猊音ní","被翻红浪：被翻红浪（红被乱翻如浪）","起来人未梳头：起来人未梳头","任宝奁闲掩：任宝奁（梳妆匣）闲掩。奁音lián","日上帘钩：日上帘钩","生怕闲愁暗恨：生怕闲愁暗恨","多少事、欲说还休：多少事欲说还休","今年瘦：今年瘦","非干病酒：非干病酒（不是因为醉酒）","不是悲秋：不是悲秋","明朝：明朝","这回去也：这回去也","千万遍阳关：千万遍阳关（《阳关三叠》送别曲）","也即难留：也即难留","念武陵春晚：念武陵春晚（武陵，陶渊明《桃花源记》，此指与丈夫的美好时光）","云锁重楼：云锁重楼","记取楼前绿水：记取楼前绿水","应念我、终日凝眸：应念我终日凝眸","凝眸处：凝眸处","从今更数：从今更数","几段新愁：几段新愁"]
  },
  "一剪梅・一翦梅|李清照": {
    s: "上片「红藕香残玉簟秋。轻解罗裳，独上兰舟。雪中谁寄锦书来，雁字回时，月满西楼」写红藕香残玉簟秋、轻解罗裳独上兰舟，雪中谁寄锦书来、雁字回时月满西楼，以秋景写相思；下片「花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头」写花自飘零水自流、一种相思两处闲愁，此情无计可消除、才下眉头却上心头，以「才下眉头，却上心头」写相思的无法排遣——刚从眉头消失，又涌上心头，全词意境凄清、情感深沉，「此情无计可消除，才下眉头，却上心头」成为千古名句，是婉约词的千古名篇。",
    b: "李清照这首《一剪梅》是她与丈夫赵明诚离别后所作，写相思之情，「此情无计可消除，才下眉头，却上心头」是千古名句，是婉约词的千古名篇。",
    n: ["一剪梅：词牌名","红藕香残玉簟秋：红藕香残玉簟（竹席）秋。簟音diàn","轻解罗裳：轻解罗裳","独上兰舟：独上兰舟","雪中谁寄锦书来：雪中谁寄锦书来（雁足传书）","雁字回时：雁字回时","月满西楼：月满西楼","花自飘零水自流：花自飘零水自流","一种相思：一种相思","两处闲愁：两处闲愁","此情无计可消除：此情无计可消除","才下眉头：才下眉头","却上心头：却上心头"]
  },
  "鹧鸪天|李清照": {
    s: "上片「寒日萧萧上锁窗。梧桐应恨夜来霜。酒阑更喜团茶苦，梦断偏宜瑞脑香」写寒日萧萧上锁窗、梧桐应恨夜来霜，酒阑更喜团茶苦、梦断偏宜瑞脑香，以秋景写凄凉；下片「秋已尽，日犹长。仲宣怀远更凄凉。不如随分尊前醉，莫负东篱菊蕊黄」写秋已尽日犹长、仲宣怀远更凄凉，不如随分尊前醉、莫负东篱菊蕊黄，以王粲登楼怀远写思乡、以「尊前醉」「莫负菊蕊」写借酒排遣，全词意境凄清、用典贴切（王粲登楼、陶渊明东篱），「仲宣怀远更凄凉」成为名句。",
    b: "李清照这首《鹧鸪天》写秋日的凄凉与借酒排遣，以「仲宣怀远更凄凉」写思乡，是婉约词的名篇。",
    n: ["鹧鸪天：词牌名","寒日萧萧上锁窗：寒日萧萧上锁窗","梧桐应恨夜来霜：梧桐应恨夜来霜","酒阑更喜团茶苦：酒阑更喜团茶苦","梦断偏宜瑞脑香：梦断偏宜瑞脑（香料）香","秋已尽：秋已尽","日犹长：日犹长","仲宣怀远更凄凉：仲宣（王粲，字仲宣，作《登楼赋》怀远）怀远更凄凉","不如随分尊前醉：不如随分（随缘）尊前醉","莫负东篱菊蕊黄：莫负东篱（陶渊明「采菊东篱下」）菊蕊黄"]
  },
  "醉花阴|李清照": {
    s: "上片「薄雾浓云愁永昼。瑞脑消金兽。佳节又重阳，玉枕纱厨，半夜凉初透」写薄雾浓云愁永昼、瑞脑消金兽，佳节又重阳、玉枕纱厨半夜凉初透，以重阳景色写相思；下片「东篱把洒黄昏后，有暗香盈袖。莫道不消魂，帘卷西风，人似黄花瘦」写东篱把酒黄昏后、有暗香盈袖，莫道不消魂、帘卷西风人似黄花瘦，以「人似黄花瘦」写相思之深——人比黄花还瘦，比喻新奇、情感深沉，全词意境凄清、比喻巧妙，「莫道不消魂，帘卷西风，人似黄花瘦」成为千古名句，是婉约词的千古名篇。",
    b: "李清照这首《醉花阴》是她重阳节思念丈夫赵明诚所作，「莫道不消魂，帘卷西风，人似黄花瘦」是千古名句，是婉约词的千古名篇，传说赵明诚读后自愧不如。",
    n: ["醉花阴：词牌名","薄雾浓云愁永昼：薄雾浓云愁永昼（漫长的白天）","瑞脑消金兽：瑞脑在金兽（兽形香炉）中烧尽","佳节又重阳：佳节又重阳","玉枕纱厨：玉枕纱厨（纱帐）","半夜凉初透：半夜凉初透","东篱把洒黄昏后：东篱把酒黄昏后（陶渊明「采菊东篱下」）","有暗香盈袖：有暗香盈袖","莫道不消魂：莫道不消魂","帘卷西风：帘卷西风","人似黄花瘦：人似黄花瘦"]
  },
  "添字丑奴儿・采桑子|李清照": {
    s: "上片「窗前谁种芭蕉树。阴满中庭。阴满中庭。叶叶心心，舒卷有余情」写窗前谁种芭蕉树、阴满中庭，叶叶心心舒卷有余情，以芭蕉写愁；下片「伤心枕上三更雨。点滴霖霪。点滴霖霪。愁损北人，不惯起来听」写伤心枕上三更雨、点滴霖霪，愁损北人不惯起来听，以「三更雨」「点滴霖霪」写雨的绵密、以「愁损北人」写南渡后的思乡——北方人不习惯听这南方的芭蕉雨，全词意境凄清、情感深沉，「愁损北人，不惯起来听」成为名句。",
    b: "李清照这首《添字丑奴儿》是她南渡后所作，写听雨的愁思，以「愁损北人，不惯起来听」写南渡后的思乡，是婉约词的名篇。",
    n: ["添字丑奴儿：词牌名，即《采桑子》","窗前谁种芭蕉树：窗前谁种芭蕉树","阴满中庭：阴满中庭","阴满中庭：阴满中庭","叶叶心心：叶叶心心","舒卷有余情：舒卷有余情","伤心枕上三更雨：伤心枕上三更雨","点滴霖霪：点滴霖霪（连绵不断）。霖霪línyín","点滴霖霪：点滴霖霪","愁损北人：愁损北人（南渡的北方人，李清照自指）","不惯起来听：不惯起来听"]
  },
  "永遇乐|李清照": {
    s: "上片「落日熔金，暮云合璧，人在何处。染柳烟浓，吹梅笛怨，春意知几许。元宵佳节，融和天气，次第岂无风雨。来相召、香车宝马，谢他酒朋诗侣」写落日熔金暮云合璧、人在何处，染柳烟浓吹梅笛怨、春意知几许，元宵佳节融和天气、次第岂无风雨，来相召香车宝马、谢他酒朋诗侣，以元宵景色写南渡后的孤独；下片「中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，拈金雪柳，簇带争济楚。如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语」写中州盛日闺门多暇、记得偏重三五，铺翠冠儿拈金雪柳簇带争济楚，如今憔悴风鬟霜鬓怕见夜间出去，不如向帘儿底下听人笑语，以汴京全盛时的元宵欢乐与如今的憔悴对比写亡国之痛，全词今昔对比、情感深沉，「不如向、帘儿底下，听人笑语」成为千古名句，是婉约词的千古名篇。",
    b: "李清照这首《永遇乐》是她南渡后元宵节所作，写今昔对比的亡国之痛，「不如向、帘儿底下，听人笑语」是千古名句，是婉约词的千古名篇，刘辰翁曾和其韵。",
    n: ["永遇乐：词牌名","落日熔金：落日熔金（落日像熔化的金子）","暮云合璧：暮云合璧（暮云像合拢的玉璧）","人在何处：人在何处","染柳烟浓：染柳烟浓","吹梅笛怨：吹梅笛怨（《梅花落》笛曲哀怨）","春意知几许：春意知几许","元宵佳节：元宵佳节","融和天气：融和天气","次第岂无风雨：次第岂无风雨（接着难道没有风雨吗）","来相召、香车宝马：来相召香车宝马","谢他酒朋诗侣：谢他酒朋诗侣","中州盛日：中州盛日（汴京全盛时）","闺门多暇：闺门多暇","记得偏重三五：记得偏重三五（正月十五元宵节）","铺翠冠儿：铺翠冠儿（饰翠羽的帽子）","拈金雪柳：拈金雪柳（金线的雪柳，元宵节饰物）","簇带争济楚：簇带争济楚（打扮得整齐漂亮）","如今憔悴：如今憔悴","风鬟霜鬓：风鬟霜鬓（头发散乱斑白）","怕见夜间出去：怕见夜间出去","不如向、帘儿底下：不如向帘儿底下","听人笑语：听人笑语"]
  },
  "点绛唇|李清照": {
    s: "上片「寂寞深闺。柔肠一寸愁千缕。惜春春去。几点催花雨」写寂寞深闺、柔肠一寸愁千缕，惜春春去、几点催花雨，以「一寸愁千缕」写愁之深；下片「倚遍阑干。只是无情绪。人何处。连天衰草。望断归来路」写倚遍阑干、只是无情绪，人何处、连天衰草望断归来路，以「倚遍阑干」「望断归来路」写相思的执着，全词意境凄清、情感深沉，「柔肠一寸愁千缕」成为名句。",
    b: "李清照这首《点绛唇》是她早期作品，写闺中女子的相思，以「柔肠一寸愁千缕」写愁之深，是婉约词的名篇。",
    n: ["点绛唇：词牌名","寂寞深闺：寂寞深闺","柔肠一寸愁千缕：柔肠一寸愁千缕","惜春春去：惜春春去","几点催花雨：几点催花雨","倚遍阑干：倚遍阑干","只是无情绪：只是无情绪","人何处：人何处","连天衰草：连天衰草","望断归来路：望断归来路"]
  },
  "忆王孙|李重元": {
    s: "全词「萋萋芳草忆王孙。柳外楼高空断魂。杜宇声声不忍闻。欲黄昏。雨打梨花深闭门」写萋萋芳草忆王孙、柳外楼高空断魂，杜宇声声不忍闻，欲黄昏雨打梨花深闭门，以芳草、柳外楼、杜宇、雨打梨花写春愁，「雨打梨花深闭门」的画面凄清动人，全词意境凄清、用典贴切（《楚辞》王孙芳草、杜鹃啼归），「雨打梨花深闭门」成为千古名句，是婉约词的千古名篇。",
    b: "李重元（北宋词人）这首《忆王孙》写闺中女子思念远人，以「雨打梨花深闭门」写春愁，是婉约词的千古名篇，「忆王孙」四首（春词、夏词、秋词、冬词）以此首最著名。",
    n: ["忆王孙：词牌名","萋萋芳草忆王孙：萋萋芳草忆王孙（用《楚辞》「王孙游兮不归，春草生兮萋萋」）","柳外楼高空断魂：柳外楼高空断魂","杜宇声声不忍闻：杜宇（杜鹃）声声不忍闻","欲黄昏：欲黄昏","雨打梨花深闭门：雨打梨花深闭门"]
  },
  "宿新市徐公店|杨万里": {
    s: "首两句「篱落疏疏一径深，树头新绿未成阴」写篱笆稀疏小路深远、树头新绿未成阴，以乡村景色写环境；后两句「儿童急走追黄蝶，飞入菜花无处寻」是千古名句——儿童急跑追黄蝶、黄蝶飞入菜花无处寻，以「急走」「追」写儿童的天真、以「飞入菜花无处寻」写黄蝶与菜花同色的巧妙，画面生动、情趣盎然，全诗语言明快、充满生活气息，「儿童急走追黄蝶，飞入菜花无处寻」成为千古名句。",
    b: "杨万里（南宋诗人，「诚斋体」）这首《宿新市徐公店》写乡村儿童追蝶的情景，「儿童急走追黄蝶，飞入菜花无处寻」是千古名句，是南宋七绝的名篇。",
    n: ["宿新市徐公店：住宿在新市徐公店","篱落疏疏一径深：篱笆稀疏一条小路深远","树头新绿未成阴：树头新绿未成阴（树荫）","儿童急走追黄蝶：儿童急跑追黄蝶","飞入菜花无处寻：飞入菜花无处寻"]
  },
  "点绛唇|林逋": {
    s: "上片「金谷年年。乱生春色谁为主。余花落处。满地和烟雨」写金谷年年乱生春色谁为主、余花落处满地和烟雨，以金谷园的春草写繁华不再；下片「又是离歌。一阕长亭暮。王孙去。萋萋无数。南北东西路」写又是离歌一阕长亭暮，王孙去萋萋无数南北东西路，以「萋萋无数，南北东西路」写春草的无边与离情的无尽——春草长满了南北东西的路，王孙却不知去了哪里，全词意境凄清、用典贴切（金谷园、《楚辞》王孙芳草），「萋萋无数，南北东西路」成为名句。",
    b: "林逋（北宋诗人，隐居西湖孤山，「梅妻鹤子」）这首《点绛唇》写春草与离别，以「萋萋无数，南北东西路」写离情，是婉约词的名篇。",
    n: ["点绛唇：词牌名","金谷年年：金谷（金谷园，晋石崇的园林，此指繁华之地）年年","乱生春色谁为主：乱生春色谁为主","余花落处：余花落处","满地和烟雨：满地和烟雨","又是离歌：又是离歌","一阕长亭暮：一阕长亭暮","王孙去：王孙去（用《楚辞》「王孙游兮不归」）","萋萋无数：萋萋无数","南北东西路：南北东西路"]
  },
  "雨霖铃|柳永": {
    s: "上片「寒蝉凄切。对长亭晚，骤雨初歇。都门帐饮无绪，留恋处、兰舟催发。执手相看泪眼，竟无语凝噎。念去去、千里烟波，暮霭沈沈楚天阔」写寒蝉凄切对长亭晚骤雨初歇，都门帐饮无绪留恋处兰舟催发，执手相看泪眼竟无语凝噎，念去去千里烟波暮霭沉沉楚天阔，以离别场景写离情；下片「多情自古伤离别。更那堪、冷落清秋节。今宵酒醒何处，杨柳岸、晓风残月。此去经年，应是良辰、好景虚设。便纵有、千种风情，更与何人说」写多情自古伤离别更那堪冷落清秋节，今宵酒醒何处杨柳岸晓风残月，此去经年应是良辰好景虚设，便纵有千种风情更与何人说，以「杨柳岸晓风残月」写酒醒后的凄凉、以「更与何人说」写离别的痛苦，全词意境凄清、情感深沉，「今宵酒醒何处，杨柳岸、晓风残月」成为千古名句，是婉约词的千古名篇。",
    b: "柳永（北宋词人，「婉约派」代表，「奉旨填词柳三变」）这首《雨霖铃》写离别之情，「今宵酒醒何处，杨柳岸、晓风残月」是千古名句，是婉约词的千古名篇，也是柳永的代表作。",
    n: ["雨霖铃：词牌名","寒蝉凄切：寒蝉凄切","对长亭晚：对长亭晚","骤雨初歇：骤雨初歇","都门帐饮无绪：都门帐饮无绪（在京城门外设帐饯行，没有情绪）","留恋处、兰舟催发：留恋处兰舟催发","执手相看泪眼：执手相看泪眼","竟无语凝噎：竟无语凝噎（哽咽说不出话）。噎音yē","念去去、千里烟波：念去去千里烟波","暮霭沈沈楚天阔：暮霭沉沉楚天阔。沈同「沉」","多情自古伤离别：多情自古伤离别","更那堪、冷落清秋节：更那堪冷落清秋节","今宵酒醒何处：今宵酒醒何处","杨柳岸、晓风残月：杨柳岸晓风残月","此去经年：此去经年","应是良辰、好景虚设：应是良辰好景虚设","便纵有、千种风情：便纵有千种风情","更与何人说：更与何人说"]
  },
  "迷仙引|柳永": {
    s: "上片「才过笄年，初绾云鬟，便学歌舞。席上尊前，王孙随分相许。算等闲、酬一笑，便千金慵觑。常祗恐、容易蕣华偷换，光阴虚度」写才过笄年初绾云鬟便学歌舞，席上尊前王孙随分相许，算等闲酬一笑便千金慵觑，常只恐容易蕣华偷换光阴虚度，以歌女的生活写对青春虚度的忧虑；下片「已受君恩顾，好与花为主。万里丹霄，何妨携手同归去。永弃却、烟花伴侣。免教人见妾，朝云暮雨」写已受君恩顾好与花为主，万里丹霄何妨携手同归去，永弃却烟花伴侣，免教人见妾朝云暮雨，以「携手同归去」「永弃却烟花伴侣」写对从良的渴望，全词语言朴素、情感真挚，是柳永写歌女心理的名篇，「万里丹霄，何妨携手同归去」成为名句。",
    b: "柳永这首《迷仙引》写歌女希望从良、与情人携手归去的心愿，以「万里丹霄，何妨携手同归去」写对自由的渴望，是婉约词的名篇。",
    n: ["迷仙引：词牌名","才过笄年：才过笄年（十五岁，女子成年）。笄音jī","初绾云鬟：初绾云鬟（盘起发髻）","便学歌舞：便学歌舞","席上尊前：席上尊前","王孙随分相许：王孙随分相许（随意答应）","算等闲、酬一笑：算等闲酬一笑（平常一笑）","便千金慵觑：便千金慵觑（懒得看）","常祗恐、容易蕣华偷换：常只恐容易蕣华（木槿花，朝开暮落，喻青春）偷换。祗同「只」；蕣音shùn","光阴虚度：光阴虚度","已受君恩顾：已受君恩顾","好与花为主：好与花为主","万里丹霄：万里丹霄","何妨携手同归去：何妨携手同归去","永弃却、烟花伴侣：永弃却烟花伴侣","免教人见妾：免教人见妾","朝云暮雨：朝云暮雨（用宋玉《高唐赋》巫山神女「旦为朝云，暮为行雨」，指妓女生活）"]
  },
  "凤栖梧・蝶恋花|柳永": {
    s: "上片「帘下清歌帘外宴。虽爱新声，不见如花面。牙板数敲珠一串，梁尘暗落琉璃盏」写帘下清歌帘外宴，虽爱新声不见如花面，牙板数敲珠一串、梁尘暗落琉璃盏，以「珠一串」「梁尘落」写歌声之美；下片「桐树花深孤凤怨。渐遏遥天，不放行云散。坐上少年听不惯。玉山未倒肠先断」写桐树花深孤凤怨，渐遏遥天不放行云散，坐上少年听不惯、玉山未倒肠先断，以「响遏行云」写歌声之高、以「肠先断」写歌声的感染力，全词用典丰富（珠串歌声、梁尘落、响遏行云、玉山倾倒）、意境凄清，「玉山未倒肠先断」成为名句。",
    b: "柳永这首《凤栖梧》写歌女的歌声之美与动人，以「玉山未倒肠先断」写歌声的感染力，是婉约词的名篇。",
    n: ["凤栖梧：词牌名，即《蝶恋花》","帘下清歌帘外宴：帘下清歌帘外宴","虽爱新声：虽爱新声","不见如花面：不见如花面","牙板数敲珠一串：牙板（拍板）数敲珠一串（歌声如珠串）","梁尘暗落琉璃盏：梁尘暗落琉璃盏（用「歌声绕梁，尘落」典故）","桐树花深孤凤怨：桐树花深孤凤怨","渐遏遥天：渐遏遥天（响遏行云）","不放行云散：不放行云散","坐上少年听不惯：坐上少年听不惯","玉山未倒肠先断：玉山未倒（未醉）肠先断（玉山，指身体，「玉山倾倒」指醉倒）"]
  },
  "鹤冲天|柳永": {
    s: "上片「黄金榜上。偶失龙头望。明代暂遗贤，如何向。未遂风云便，争不恣狂荡。何须论得丧。才子词人，自是白衣卿相」写黄金榜上偶失龙头望，明代暂遗贤如何向，未遂风云便争不恣狂荡，何须论得丧，才子词人自是白衣卿相，以「白衣卿相」写对功名的蔑视；下片「烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红翠，风流事、平生畅。青春都一饷。忍把浮名，换了浅斟低唱」写烟花巷陌依约丹青屏障，幸有意中人堪寻访，且恁偎红翠风流事平生畅，青春都一饷，忍把浮名换了浅斟低唱，以「忍把浮名，换了浅斟低唱」写对自由生活的向往，全词语言明快、情感激烈，「忍把浮名，换了浅斟低唱」成为千古名句，是柳永的代表作。",
    b: "柳永这首《鹤冲天》是他科举落第后所作，写对功名的蔑视与对自由生活的向往，「忍把浮名，换了浅斟低唱」是千古名句，传说宋仁宗因此批「且去浅斟低唱，何要浮名」，柳永遂自称「奉旨填词柳三变」。",
    n: ["鹤冲天：词牌名","黄金榜上：黄金榜上（科举金榜）","偶失龙头望：偶失龙头望（状元）","明代暂遗贤：明代（圣明时代）暂遗贤（遗落贤才）","如何向：如何向（怎么办）","未遂风云便：未遂风云便（未得志）","争不恣狂荡：争不恣狂荡（怎不恣意狂荡）","何须论得丧：何须论得丧（得失）","才子词人：才子词人","自是白衣卿相：自是白衣卿相（平民卿相）","烟花巷陌：烟花巷陌（歌妓聚居处）","依约丹青屏障：依约丹青屏障（画屏）","幸有意中人：幸有意中人","堪寻访：堪寻访","且恁偎红翠：且恁偎红翠（依偎歌女）","风流事、平生畅：风流事平生畅","青春都一饷：青春都一饷（片刻）。饷同「晌」","忍把浮名：忍把浮名","换了浅斟低唱：换了浅斟低唱"]
  },
  "朝中措|欧阳修": {
    s: "上片「平山阑槛倚晴空。山色有无中。手种堂前垂柳，别来几度春风」写平山堂栏杆倚晴空、山色有无中，手种堂前垂柳、别来几度春风，以平山堂景色写对扬州的怀念；下片「文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁」写文章太守挥毫万字一饮千钟，行乐直须年少、尊前看取衰翁，以「文章太守」写自己的豪情、以「衰翁」写岁月的感慨，全词意境开阔、语言明快，「文章太守，挥毫万字，一饮千钟」成为千古名句。",
    b: "欧阳修（北宋文学家，「唐宋八大家」之一）这首《朝中措》是他送友人刘敞（字原父）出守扬州时所作，写平山堂的景色与自己的感慨，「文章太守，挥毫万字，一饮千钟」是千古名句。",
    n: ["朝中措：词牌名","平山阑槛倚晴空：平山堂（欧阳修在扬州建的堂）的栏杆倚晴空","山色有无中：山色有无中（用王维「江流天地外，山色有无中」）","手种堂前垂柳：手种堂前垂柳","别来几度春风：别来几度春风","文章太守：文章太守（欧阳修自称）","挥毫万字：挥毫万字","一饮千钟：一饮千钟","行乐直须年少：行乐直须年少","尊前看取衰翁：尊前看取衰翁（欧阳修自指）"]
  },
  "诉衷情|欧阳修": {
    s: "上片「清晨帘幕卷轻霜。呵手试梅妆。都缘自有离恨，故画作远山长」写清晨帘幕卷轻霜、呵手试梅妆，都缘自有离恨、故画作远山长，以「画作远山长」写离恨——把眉画得像远山一样长，暗示离恨之长；下片「思往事，惜流芳。易成伤。拟歌先敛，欲笑还颦。最断人肠」写思往事惜流芳易成伤，拟歌先敛欲笑还颦最断人肠，以「拟歌先敛，欲笑还颦」写女子的矛盾心理——想唱歌却先收敛、想笑却还皱眉，全词意境凄清、细节生动，「拟歌先敛，欲笑还颦，最断人肠」成为名句。",
    b: "欧阳修这首《诉衷情》写闺中女子的离恨，以「拟歌先敛，欲笑还颦，最断人肠」写女子的矛盾心理，是婉约词的名篇。",
    n: ["诉衷情：词牌名","清晨帘幕卷轻霜：清晨帘幕卷轻霜","呵手试梅妆：呵手试梅妆（梅花妆，寿阳公主故事）","都缘自有离恨：都缘自有离恨","故画作远山长：故画作远山长（把眉画得像远山一样长，写离恨）","思往事：思往事","惜流芳：惜流芳（流逝的美好时光）","易成伤：易成伤","拟歌先敛：拟歌先敛（想唱歌先收敛表情）","欲笑还颦：欲笑还颦（想笑还皱眉）。颦音pín","最断人肠：最断人肠"]
  },
  "临江仙|欧阳修": {
    s: "上片「柳外轻雷池上雨，雨声滴碎荷声。小楼西角断虹明。阑干倚处，待得月华生」写柳外轻雷池上雨、雨声滴碎荷声，小楼西角断虹明，阑干倚处待得月华生，以雨后景色写闺中等待；下片「燕子飞来窥画栋，玉钩垂下帘旌。凉波不动簟纹平。水精双枕，傍有堕钗横」写燕子飞来窥画栋、玉钩垂下帘旌，凉波不动簟纹平，水精双枕傍有堕钗横，以「堕钗横」的细节写闺中女子的慵懒，全词意境清丽、细节生动，「燕子飞来窥画栋，玉钩垂下帘旌」成为名句。",
    b: "欧阳修这首《临江仙》写夏日雨后的闺中情景，以「燕子飞来窥画栋，玉钩垂下帘旌」写环境的清幽，是婉约词的名篇。",
    n: ["临江仙：词牌名","柳外轻雷池上雨：柳外轻雷池上雨","雨声滴碎荷声：雨声滴碎荷声","小楼西角断虹明：小楼西角断虹明","阑干倚处：阑干倚处","待得月华生：待得月华（月光）生","燕子飞来窥画栋：燕子飞来窥画栋","玉钩垂下帘旌：玉钩垂下帘旌（帘幕）。旌音jīng","凉波不动簟纹平：凉波不动簟纹（竹席纹）平。簟音diàn","水精双枕：水精（水晶）双枕","傍有堕钗横：傍有堕钗横"]
  },
  "浪淘沙|欧阳修": {
    s: "上片「把酒祝东风。且共从容。垂杨紫陌洛城东。总是当时携手处，游遍芳丛」写把酒祝东风且共从容，垂杨紫陌洛城东，总是当时携手处游遍芳丛，以洛阳春色写相聚的欢乐；下片「聚散苦匆匆。此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同」写聚散苦匆匆此恨无穷，今年花胜去年红，可惜明年花更好知与谁同，以「今年花胜去年红」「明年花更好」的递进写聚散无常——花一年比一年好，却不知明年与谁同赏，全词意境清丽、哲理深沉，「今年花胜去年红。可惜明年花更好，知与谁同」成为千古名句。",
    b: "欧阳修这首《浪淘沙》写与友人在洛阳相聚又离别的感慨，「今年花胜去年红。可惜明年花更好，知与谁同」是千古名句，是婉约词的千古名篇。",
    n: ["浪淘沙：词牌名","把酒祝东风：把酒祝东风（祝，向东风祝祷）","且共从容：且共从容（且与东风一同从容赏春）","垂杨紫陌洛城东：垂杨紫陌洛城东（紫陌，帝都的道路）","总是当时携手处：总是当时携手处","游遍芳丛：游遍芳丛","聚散苦匆匆：聚散苦匆匆","此恨无穷：此恨无穷","今年花胜去年红：今年花胜去年红","可惜明年花更好：可惜明年花更好","知与谁同：知与谁同"]
  },
  "浣溪沙|欧阳修": {
    s: "上片「堤上游人逐画船。拍堤春水四垂天。绿杨楼外出秋千」写堤上游人逐画船、拍堤春水四垂天，绿杨楼外出秋千，以「出秋千」的「出」字写秋千的灵动，王国维评为「着一出字而境界全出」；下片「白发戴花君莫笑，六幺催拍盏频传。人生何处似尊前」写白发戴花君莫笑、六幺催拍盏频传，人生何处似尊前，以「白发戴花」写旷达、以「人生何处似尊前」写及时行乐，全词意境明丽、情感旷达，「绿杨楼外出秋千」成为名句。",
    b: "欧阳修这首《浣溪沙》写颍州西湖春游的欢乐，「绿杨楼外出秋千」是名句，「人生何处似尊前」写及时行乐，是婉约词的名篇。",
    n: ["浣溪沙：词牌名","堤上游人逐画船：堤上游人逐画船","拍堤春水四垂天：拍堤春水四垂天（天幕四垂）","绿杨楼外出秋千：绿杨楼外出秋千","白发戴花君莫笑：白发戴花君莫笑","六幺催拍盏频传：六幺（曲调名）催拍盏频传。幺音yāo","人生何处似尊前：人生何处似尊前（酒杯前）"]
  },
  "卖油翁|欧阳修": {
    s: "全文分三层：第一层写陈尧咨善射自矜，卖油翁释担而立、睨之、但微颔之，以卖油翁的冷淡反衬陈尧咨的自矜；第二层写陈尧咨质问卖油翁，卖油翁以「无他，但手熟尔」回答，陈尧咨忿然，卖油翁当场演示酌油——以钱覆葫芦口、徐以杓酌油沥之、自钱孔入而钱不湿，以实际行动证明「手熟」的道理；第三层写卖油翁「我亦无他，惟手熟尔」，陈尧咨笑而遣之，以「熟能生巧」的道理作结。全文叙事简洁、对话生动、寓意深刻，「无他，但手熟尔」成为千古名句，是寓言式散文的典范。",
    b: "欧阳修这篇《卖油翁》通过陈尧咨善射与卖油翁酌油的故事，说明「熟能生巧」的道理，是中国古代寓言式散文的千古名篇。",
    n: ["卖油翁：篇名，欧阳修作","陈康肃公：陈尧咨，谥号康肃，北宋官员，善射","善射：擅长射箭","当世无双：当世无双","自矜：自夸。矜音jīn","家圃：家里的园子。圃音pǔ","释担：放下担子","睨之：斜着眼看他。睨音nì","久而不去：久久不离开","发矢十中八九：射箭十中八九","但微颔之：只是微微点头。颔音hàn，点头","汝亦知射乎：你也懂射箭吗","无他，但手熟尔：没有别的，只是手熟罢了。尔同「耳」","忿然：气愤的样子。忿音fèn","尔安敢轻吾射：你怎么敢轻视我的射箭","以我酌油知之：凭我倒油知道这个道理","乃取一葫芦置于地：于是拿一个葫芦放在地上","以钱覆其口：用铜钱盖住葫芦口","徐以杓酌油沥之：慢慢地用勺子倒油沥入葫芦。杓同「勺」","自钱孔入：从钱孔中进入","而钱不湿：而钱不湿","我亦无他，惟手熟尔：我也没有别的，只是手熟罢了","笑而遣之：笑着打发他走了"]
  },
  "桂枝香|王安石": {
    s: "上片「登临送目。正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风、酒旗斜矗。彩舟云淡，星河鹭起，画图难足」写登临送目、故国晚秋、天气初肃，千里澄江似练翠峰如簇，归帆去棹残阳里背西风酒旗斜矗，彩舟云淡星河鹭起画图难足，以金陵壮丽景色写登临；下片「念往昔、繁华竞逐。叹门外楼头，悲恨相续。千古凭高，对此漫嗟荣辱。六朝旧事随流水，但寒烟、芳草凝绿。至今商女，时时犹唱，后庭遗曲」写念往昔繁华竞逐、叹门外楼头悲恨相续，千古凭高对此漫嗟荣辱，六朝旧事随流水但寒烟芳草凝绿，至今商女时时犹唱后庭遗曲，以六朝兴亡写怀古、以「后庭遗曲」写对现实的隐忧，全词意境壮阔、用典贴切、寓意深刻，「至今商女，时时犹唱，后庭遗曲」成为千古名句，是豪放词的千古名篇。",
    b: "王安石这首《桂枝香》写金陵怀古，「至今商女，时时犹唱，后庭遗曲」是千古名句，是豪放词的千古名篇，杨慎评为「金陵怀古诸词，惟介甫最为绝唱」。",
    n: ["桂枝香：词牌名","登临送目：登临送目（登高远望）","正故国晚秋：正故国（金陵）晚秋","天气初肃：天气初肃（肃杀）","千里澄江似练：千里澄江似练（白绢）。用谢朓「澄江静如练」","翠峰如簇：翠峰如簇（簇拥）。簇音cù","归帆去棹残阳里：归帆去棹残阳里。棹音zhào","背西风、酒旗斜矗：背西风酒旗斜矗。矗音chù，竖立","彩舟云淡：彩舟云淡","星河鹭起：星河（银河，此指长江）鹭起","画图难足：画图难足（难以画尽）","念往昔、繁华竞逐：念往昔繁华竞逐","叹门外楼头：叹门外楼头（用陈后主「门外韩擒虎，楼头张丽华」典故，隋兵已到门外，陈后主还在楼头与张丽华享乐）","悲恨相续：悲恨相续","千古凭高：千古凭高","对此漫嗟荣辱：对此漫嗟荣辱（空叹荣辱）","六朝旧事随流水：六朝旧事随流水","但寒烟、芳草凝绿：但寒烟芳草凝绿","至今商女：至今商女（歌女）","时时犹唱：时时犹唱","后庭遗曲：后庭遗曲（《玉树后庭花》，陈后主作，亡国之音）。用杜牧「商女不知亡国恨，隔江犹唱后庭花」"]
  },
  "梅花|王安石": {
    s: "首两句「墙角数枝梅，凌寒独自开」写墙角几枝梅、冒着严寒独自开放，以「凌寒」「独自」写梅的坚韧；后两句「遥知不是雪，为有暗香来」是千古名句——远远知道不是雪，因为有暗香飘来，以「暗香」写梅的品格，以雪衬梅、以香辨梅，全诗语言朴素、意境清幽，「遥知不是雪，为有暗香来」成为千古名句，是咏梅诗的千古名篇。",
    b: "王安石这首《梅花》写梅花在严寒中独自开放，以「暗香」写梅的品格，是咏梅诗的千古名篇。",
    n: ["梅花：诗题","墙角数枝梅：墙角几枝梅","凌寒独自开：冒着严寒独自开放","遥知不是雪：远远知道不是雪","为有暗香来：因为有暗香飘来"]
  },
  "明妃曲·其一|王安石": {
    s: "全诗分四层：第一层「明妃初出汉宫时……尚得君王不自持」写明妃初出汉宫时的美貌——春风一面花含露，低回顾影无颜色，尚得君王不自持，以「不自持」写昭君之美；第二层「归来却怪丹青手……当时枉杀毛延寿」写汉元帝归来却怪画师毛延寿，入眼平生几曾有，意态由来画不成，当时枉杀毛延寿，以「意态由来画不成」翻案——昭君的风度神态是画不出来的，杀毛延寿是冤枉的，这是千古新意；第三层「一去心知更不归……只有年年鸿雁飞」写昭君一去心知更不归，可怜着尽汉宫衣，寄声欲问塞南事，只有年年鸿雁飞，以「着尽汉宫衣」「鸿雁飞」写昭君的思乡；第四层「家人万里传消息……人生失意无南北」写家人万里传消息，好在毡城莫相忆，君不见咫尺长门闭阿娇，人生失意无南北，以陈皇后阿娇被废长门宫的典故说明——人生失意不分南北，即使在汉朝也有失意，深化了主题。全诗立意新颖、议论精辟、情感深沉，「意态由来画不成，当时枉杀毛延寿」「人生失意无南北」成为千古名句，是咏史诗的千古名篇。",
    b: "王安石这首《明妃曲》写王昭君出塞的故事，「意态由来画不成，当时枉杀毛延寿」「人生失意无南北」是千古名句，是咏史诗的千古名篇，在当时引起很大反响，欧阳修、司马光、梅尧臣等都有和作。",
    n: ["明妃曲：诗题，明妃即王昭君","明妃初出汉宫时：明妃初出汉宫时","春风一面花含露：春风一面花含露（面容如春风中含露的花）","低回顾影无颜色：低回顾影无颜色（低头回看，面容失色）","尚得君王不自持：尚且使君王不能自持（指汉元帝见昭君美貌后悔）","归来却怪丹青手：归来却怪丹青手（画师毛延寿）","入眼平生几曾有：入眼平生几曾有（平生从未见过如此美貌）","意态由来画不成：意态（风度神态）从来画不成","当时枉杀毛延寿：当时枉杀毛延寿","一去心知更不归：一去心知更不归","可怜着尽汉宫衣：可怜穿尽了汉宫衣（思念汉朝）","寄声欲问塞南事：寄声欲问塞南（汉朝）事","只有年年鸿雁飞：只有年年鸿雁飞","家人万里传消息：家人万里传消息","好在毡城莫相忆：好在毡城（匈奴）莫相忆","君不见咫尺长门闭阿娇：君不见咫尺长门（长门宫）闭阿娇（陈皇后，被汉武帝废居长门宫）","人生失意无南北：人生失意无南北（无论南北都有失意）"]
  },
  "江上|王安石": {
    s: "首两句「江水漾西风，江花脱晚红」写江水在西风中荡漾、江花脱落晚红，以秋景写离情；后两句「离情被横笛，吹过乱山东」是名句——离情被横笛声吹过乱山东，以「离情被横笛吹过」的拟人写离情的悠远，想象奇特，全诗意境凄清、想象奇特，「离情被横笛，吹过乱山东」成为名句。",
    b: "王安石这首《江上》写江上秋风中的离情，以「离情被横笛，吹过乱山东」写离情的悠远，是七绝的名篇。",
    n: ["江上：诗题","江水漾西风：江水在西风中荡漾","江花脱晚红：江花脱落了晚红（晚开的红花）","离情被横笛：离情被横笛（笛声）","吹过乱山东：吹过乱山东"]
  },
  "游褒禅山记|王安石": {
    s: "全文分五段：第一段写褒禅山的得名与华山洞的位置，通过仆碑考证「花山」的读音，提出「音谬」的问题；第二段写游前洞与后洞的经过——前洞平旷游者众，后洞窈然入之愈深其进愈难而其见愈奇，因「火且尽」而随怠者出，后悔「不得极夫游之乐」；第三段写由此引发的议论——「夷以近则游者众，险以远则至者少」，「世之奇伟瑰怪非常之观常在于险远」，提出「志、力、物」三者的关系：非有志者不能至，有志矣力不足亦不能至，有志与力而无物以相之亦不能至；「尽吾志也而不能至者，可以无悔矣」；第四段写由仆碑引发的议论——「悲夫古书之不存，后世之谬其传而莫能名者」，提出「学者不可以不深思而慎取之也」；第五段记同游四人与写作时间。全文叙议结合、逻辑严密、寓意深刻，「世之奇伟瑰怪非常之观常在于险远」「尽吾志也而不能至者，可以无悔矣」「深思而慎取」成为千古名句，是游记散文的典范。",
    b: "王安石这篇《游褒禅山记》是他任舒州通判时所作，通过游褒禅山的经历，阐述「志、力、物」三者的关系和「深思而慎取」的治学态度，是中国古代游记散文的千古名篇。",
    n: ["游褒禅山记：篇名，王安石作","褒禅山：在今安徽含山北","浮图慧褒：和尚慧褒。浮图，和尚","始舍于其址：开始在山脚下建屋居住","卒葬之：死后葬在那里","以故其后名之曰褒禅：因此后来称它为褒禅山","慧空禅院：慧空禅院（寺庙）","庐冢：庐舍和坟墓","华山洞：华山洞","华山之阳：华山的南面。阳，山南水北为阳","碑仆道：石碑倒在路上。仆音pū","其文漫灭：碑文模糊磨灭","独其为文犹可识：只有其中的文字还可辨认","曰花山：叫「花山」","今言华如华实之华者：现在把「华」读成「华实」的「华」","盖音谬也：大概是读音错了","前洞：前洞","有泉侧出：有泉水从旁边流出","窈然：幽暗深远的样子。窈音yǎo","拥火以入：拿着火把进去","有怠而欲出者：有懈怠想出去的人","不出，火且尽：不出去，火把将要烧完了","不能十一：不到十分之一","则或咎其欲出者：就有人责怪那个想出去的人。咎音jiù","悔其随之：后悔自己跟着他出来","不得极夫游之乐：不能极尽游洞的乐趣","夷以近：平坦而近","险以远：险峻而远","瑰怪：瑰丽怪异","非常之观：不寻常的景象","非有志者不能至：不是有志气的人不能到达","不随以止：不跟着别人停止","无物以相之：没有外物帮助他。相音xiàng，帮助","力足以至焉：力量足以到达那里","于人为可讥：在别人看来是可以讥笑的","在己为有悔：在自己看来是有悔恨的","尽吾志也而不能至者：尽了我的志向却不能到达的","可以无悔矣：可以没有悔恨了","其孰能讥之乎：谁能讥笑他呢","仆碑：倒了的石碑","悲夫古书之不存：可悲古书不存","后世之谬其传而莫能名者：后世以讹传讹而不能说明白的","何可胜道也哉：哪里说得完呢","深思而慎取：深入思考而谨慎选取","四人者：四个人","庐陵萧君圭君玉：庐陵萧君圭字君玉","长乐王回深父：长乐王回字深父","余弟安国平父：我弟弟王安国字平父","安上纯父：王安上字纯父","至和元年七月某日：至和元年（1054）七月某日","临川王某记：临川王某（王安石）记"]
  },
  "水龙吟|王沂孙": {
    s: "上片「晓霜初著青林，望中故国凄凉早。萧萧渐积，纷纷犹坠，门荒径悄。渭水风生，洞庭波起，几番秋杪。想重崖半没，千峰尽出，山中路、无人到」写晓霜初著青林、望中故国凄凉早，萧萧渐积纷纷犹坠门荒径悄，渭水风生洞庭波起几番秋杪，想重崖半没千峰尽出山中路无人到，以落叶写故国凄凉；下片「前度题红杳杳。溯宫沟、暗流空绕。啼螀未歇，飞鸿欲过，此时怀抱。乱影翻窗，碎声敲砌，愁人多少。望吾庐甚处，只应今夜，满庭谁扫」写前度题红杳杳、溯宫沟暗流空绕，啼螀未歇飞鸿欲过此时怀抱，乱影翻窗碎声敲砌愁人多少，望吾庐甚处只应今夜满庭谁扫，以「题红」「宫沟」写故宫之思、以「满庭谁扫」写亡国后的荒凉，全词意境凄清、用典贴切（红叶题诗、渭水秋风、洞庭波起），是南宋遗民词的名篇。",
    b: "王沂孙（南宋末元初词人，「格律派」代表，号碧山）这首《水龙吟》写落叶，以落叶写亡国之思，是南宋遗民词的名篇，与他的《齐天乐·蝉》《眉妩·新月》并称。",
    n: ["水龙吟：词牌名","晓霜初著青林：晓霜初著（附着）青林","望中故国凄凉早：望中故国凄凉早","萧萧渐积：萧萧渐积（落叶）","纷纷犹坠：纷纷犹坠","门荒径悄：门荒径悄","渭水风生：渭水风生（用贾岛「秋风生渭水」）","洞庭波起：洞庭波起（用屈原「洞庭波兮木叶下」）","几番秋杪：几番秋杪（秋末）。杪音miǎo","想重崖半没：想重崖半没","千峰尽出：千峰尽出","山中路、无人到：山中路无人到","前度题红杳杳：前度题红（红叶题诗典故）杳杳","溯宫沟、暗流空绕：溯宫沟暗流空绕","啼螀未歇：啼螀（寒蝉）未歇。螀音jiāng","飞鸿欲过：飞鸿欲过","此时怀抱：此时怀抱","乱影翻窗：乱影翻窗","碎声敲砌：碎声敲砌（台阶）","愁人多少：愁人多少","望吾庐甚处：望吾庐甚处（我的家在哪里）","只应今夜：只应今夜","满庭谁扫：满庭谁扫（落叶谁扫）"]
  },
  "齐天乐|王沂孙": {
    s: "上片「碧痕初化池塘草，荧荧野光相趁。扇薄星流，盘明露滴，零落秋原飞磷。练裳暗近。记穿柳生凉，度荷分暝。误我残编，翠囊空叹梦无准」写碧痕初化池塘草、荧荧野光相趁，扇薄星流盘明露滴零落秋原飞磷，练裳暗近，记穿柳生凉度荷分暝，误我残编翠囊空叹梦无准，以萤火虫的光写秋夜的凄凉；下片「楼阴时过数点，倚阑人未睡，曾赋幽恨。汉苑飘苔，秦陵坠叶，千古凄凉不尽。何人为省。但隔水余晖，傍林残影。已觉萧疏，更堪秋夜永」写楼阴时过数点、倚阑人未睡曾赋幽恨，汉苑飘苔秦陵坠叶千古凄凉不尽，何人为省，但隔水余晖傍林残影，已觉萧疏更堪秋夜永，以「汉苑飘苔，秦陵坠叶」写千古兴亡、以「秋夜永」写亡国之痛，全词意境凄清、用典贴切（车胤囊萤），是南宋遗民词的名篇。",
    b: "王沂孙这首《齐天乐》写萤火虫，以萤写亡国之思，是南宋遗民词的名篇，与他的《水龙吟·落叶》《眉妩·新月》并称。",
    n: ["齐天乐：词牌名","碧痕初化池塘草：碧痕初化池塘草（萤火虫的碧光初化池塘草）","荧荧野光相趁：荧荧野光相趁（追逐）","扇薄星流：扇薄星流（萤光如星流）","盘明露滴：盘明露滴（露滴如盘明）","零落秋原飞磷：零落秋原飞磷（磷火）","练裳暗近：练裳暗近（白裳暗中靠近）","记穿柳生凉：记穿柳生凉","度荷分暝：度荷分暝（穿过荷塘分开暮色）","误我残编：误我残编（耽误我读书）","翠囊空叹梦无准：翠囊（车胤囊萤读书的袋子）空叹梦无准","楼阴时过数点：楼阴时过数点","倚阑人未睡：倚阑人未睡","曾赋幽恨：曾赋幽恨","汉苑飘苔：汉苑飘苔","秦陵坠叶：秦陵坠叶","千古凄凉不尽：千古凄凉不尽","何人为省：何人为省（知晓）","但隔水余晖：但隔水余晖","傍林残影：傍林残影","已觉萧疏：已觉萧疏","更堪秋夜永：更堪秋夜永（秋夜漫长）"]
  },
  "八六子|秦观": {
    s: "上片「倚危亭。恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊」写倚危亭、恨如芳草萋萋刬尽还生，念柳外青骢别后水边红袂分时怆然暗惊，以「恨如芳草，刬尽还生」写离恨的绵绵不绝；下片「无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝。黄鹂又啼数声」写无端天与娉婷、夜月一帘幽梦春风十里柔情，怎奈欢娱渐随流水素弦声断翠绡香减，那堪片片飞花弄晚蒙蒙残雨笼晴，正销凝黄鹂又啼数声，以「欢娱渐随流水」写欢乐的消逝、以「黄鹂又啼数声」写愁思的不断，全词意境凄清、比喻巧妙、情感深沉，「恨如芳草，萋萋刬尽还生」成为千古名句，是婉约词的千古名篇。",
    b: "秦观（北宋词人，「婉约派」代表，「苏门四学士」之一）这首《八六子》写离别后的相思，「恨如芳草，萋萋刬尽还生」是千古名句，是婉约词的千古名篇。",
    n: ["八六子：词牌名","倚危亭：倚危亭（高亭）","恨如芳草：恨如芳草","萋萋刬尽还生：萋萋刬（铲）尽还生。刬音chǎn，同「铲」","念柳外青骢别后：念柳外青骢（青白色马）别后。骢音cōng","水边红袂分时：水边红袂（红袖，指女子）分时。袂音mèi","怆然暗惊：怆然暗惊。怆音chuàng","无端天与娉婷：无端天与娉婷（美貌）。娉婷音pīngtíng","夜月一帘幽梦：夜月一帘幽梦","春风十里柔情：春风十里柔情（用杜牧「春风十里扬州路」）","怎奈向、欢娱渐随流水：怎奈向欢娱渐随流水","素弦声断：素弦声断","翠绡香减：翠绡（绿纱）香减。绡音xiāo","那堪片片飞花弄晚：那堪片片飞花弄晚","蒙蒙残雨笼晴：蒙蒙残雨笼晴","正销凝：正销凝（销魂凝神）","黄鹂又啼数声：黄鹂又啼数声"]
  },
  "江城子|秦观": {
    s: "上片「西城杨柳弄春柔。动离忧。泪难收。犹记多情，曾为系归舟。碧野朱桥当日事，人不见，水空流」写西城杨柳弄春柔、动离忧泪难收，犹记多情曾为系归舟，碧野朱桥当日事人不见水空流，以杨柳写离忧、以「人不见水空流」写物是人非；下片「韶华不为少年留。恨悠悠。几时休。飞絮落花时候、一登楼。便做春江都是泪，流不尽，许多愁」写韶华不为少年留恨悠悠几时休，飞絮落花时候一登楼，便做春江都是泪流不尽许多愁，以「便做春江都是泪，流不尽，许多愁」的夸张写愁之多，全词意境凄清、夸张巧妙、情感深沉，「便做春江都是泪，流不尽，许多愁」成为千古名句，是婉约词的千古名篇。",
    b: "秦观这首《江城子》写离别后的愁思，「便做春江都是泪，流不尽，许多愁」是千古名句，是婉约词的千古名篇。",
    n: ["江城子：词牌名","西城杨柳弄春柔：西城杨柳弄春柔","动离忧：动离忧","泪难收：泪难收","犹记多情：犹记多情","曾为系归舟：曾为系归舟","碧野朱桥当日事：碧野朱桥当日事","人不见：人不见","水空流：水空流","韶华不为少年留：韶华（美好时光）不为少年留","恨悠悠：恨悠悠","几时休：几时休","飞絮落花时候、一登楼：飞絮落花时候一登楼","便做春江都是泪：便做春江都是泪","流不尽：流不尽","许多愁：许多愁"]
  },
  "减字木兰花|秦观": {
    s: "上片「天涯旧恨。独自凄凉人不问。欲见回肠。断尽金炉小篆香」写天涯旧恨、独自凄凉人不问，欲见回肠断尽金炉小篆香，以「小篆香断尽」喻愁肠的断尽；下片「黛峨长敛。任是春风吹不展。困倚危楼。过尽飞鸿字字愁」写黛峨长敛、任是春风吹不展，困倚危楼过尽飞鸿字字愁，以「春风吹不展」写愁眉之紧、以「飞鸿字字愁」写雁阵如字字字是愁，全词意境凄清、比喻巧妙、情感深沉，「黛峨长敛，任是春风吹不展」「过尽飞鸿字字愁」成为名句。",
    b: "秦观这首《减字木兰花》写闺中女子的愁思，「黛峨长敛，任是春风吹不展」「过尽飞鸿字字愁」是名句，是婉约词的名篇。",
    n: ["减字木兰花：词牌名","天涯旧恨：天涯旧恨","独自凄凉人不问：独自凄凉人不问","欲见回肠：欲见回肠（愁肠）","断尽金炉小篆香：断尽金炉小篆香（盘香，喻愁肠）","黛峨长敛：黛峨（蛾眉）长敛。黛音dài","任是春风吹不展：任是春风吹不展","困倚危楼：困倚危楼","过尽飞鸿字字愁：过尽飞鸿字字愁（雁阵如字，字字是愁）"]
  },
  "画堂春|秦观": {
    s: "上片「落红铺尽水平池。弄晴小雨霏霏。杏园憔悴杜鹃啼。无奈春归」写落红铺尽水平池、弄晴小雨霏霏，杏园憔悴杜鹃啼无奈春归，以春景写伤春；下片「柳外画楼独上。凭阑手拈花枝。放花无语对斜晖。此恨谁知」写柳外画楼独上、凭阑手拈花枝，放花无语对斜晖此恨谁知，以「手拈花枝」「放花无语」的细节写女子的愁思，全词意境凄清、细节生动、情感深沉，「放花无语对斜晖」成为名句。",
    b: "秦观这首《画堂春》写伤春之情，「放花无语对斜晖」是名句，是婉约词的名篇。",
    n: ["画堂春：词牌名","落红铺尽水平池：落红铺尽水平池","弄晴小雨霏霏：弄晴小雨霏霏","杏园憔悴杜鹃啼：杏园憔悴杜鹃啼","无奈春归：无奈春归","柳外画楼独上：柳外画楼独上","凭阑手拈花枝：凭阑手拈（捏）花枝。拈音niān","放花无语对斜晖：放花无语对斜晖","此恨谁知：此恨谁知"]
  },
  "千秋岁|秦观": {
    s: "上片「水边沙外。城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对」写水边沙外城郭春寒退，花影乱莺声碎，飘零疏酒盏离别宽衣带，人不见碧云暮合空相对，以春景写被贬后的飘零；下片「忆昔西池会。鹓鹭同飞盖。携手处，今谁在。日边清梦断，镜里朱颜改。春去也，飞红万点愁如海」写忆昔西池会鹓鹭同飞盖，携手处今谁在，日边清梦断镜里朱颜改，春去也飞红万点愁如海，以「西池会」的回忆与「今谁在」的现实对比、以「飞红万点愁如海」的夸张写愁之深，全词意境凄清、对比鲜明、情感深沉，「春去也，飞红万点愁如海」成为千古名句，是婉约词的千古名篇。",
    b: "秦观这首《千秋岁》是他被贬处州时所作，写对昔日友人的思念与被贬的痛苦，「春去也，飞红万点愁如海」是千古名句，是婉约词的千古名篇。",
    n: ["千秋岁：词牌名","水边沙外：水边沙外","城郭春寒退：城郭春寒退","花影乱：花影乱","莺声碎：莺声碎","飘零疏酒盏：飘零疏酒盏（疏远了酒杯）","离别宽衣带：离别宽衣带（人瘦了衣带宽松，用「衣带渐宽」意）","人不见：人不见","碧云暮合空相对：碧云暮合空相对","忆昔西池会：忆昔西池会（西池，汴京金明池，秦观曾与友人游此）","鹓鹭同飞盖：鹓鹭同飞盖（鹓鹭，指朝官；飞盖，飞驰的车盖）。鹓音yuān","携手处：携手处","今谁在：今谁在","日边清梦断：日边清梦断（皇帝身边的清梦断了，指被贬）","镜里朱颜改：镜里朱颜改","春去也：春去也","飞红万点愁如海：飞红万点愁如海"]
  },
  "浣溪沙|秦观": {
    s: "上片「漠漠轻寒上小楼。晓阴无赖似穷秋。淡烟流水画屏幽」写漠漠轻寒上小楼、晓阴无赖似穷秋，淡烟流水画屏幽，以轻寒、晓阴、画屏写环境的清幽；下片「自在飞花轻似梦。无边丝雨细如愁。宝帘闲挂小银钩」写自在飞花轻似梦、无边丝雨细如愁，宝帘闲挂小银钩，以「飞花轻似梦」「丝雨细如愁」的比喻写愁的轻盈与绵密，比喻新奇、对仗工稳，全词意境清丽、比喻巧妙、情感深沉，「自在飞花轻似梦，无边丝雨细如愁」成为千古名句，是婉约词的千古名篇。",
    b: "秦观这首《浣溪沙》写春愁，「自在飞花轻似梦，无边丝雨细如愁」是千古名句，是婉约词的千古名篇，梁启超评为「奇语」。",
    n: ["浣溪沙：词牌名","漠漠轻寒上小楼：漠漠轻寒上小楼","晓阴无赖似穷秋：晓阴无赖似穷秋（深秋）","淡烟流水画屏幽：淡烟流水画屏幽","自在飞花轻似梦：自在飞花轻似梦","无边丝雨细如愁：无边丝雨细如愁","宝帘闲挂小银钩：宝帘闲挂小银钩"]
  },
  "好事近|秦观": {
    s: "上片「春路雨添花。花动一山春色。行到小溪深处，有黄鹂千百」写春路雨添花、花动一山春色，行到小溪深处有黄鹂千百，以春景写梦中的欢乐；下片「飞云当面化龙蛇。夭矫转空碧。醉卧古藤阴下，了不知南北」写飞云当面化龙蛇、夭矫转空碧，醉卧古藤阴下了不知南北，以「醉卧古藤阴下，了不知南北」写梦中的旷达与忘却，全词意境明丽、想象奇特、情感旷达，「醉卧古藤阴下，了不知南北」成为名句，后来秦观死于藤州，被认为是谶语。",
    b: "秦观这首《好事近》是他被贬处州时梦中所作，写梦中春游的欢乐，「醉卧古藤阴下，了不知南北」是名句，后来秦观死于藤州（今广西藤县），人们认为此词是谶语，是婉约词的名篇。",
    n: ["好事近：词牌名","春路雨添花：春路雨添花","花动一山春色：花动一山春色","行到小溪深处：行到小溪深处","有黄鹂千百：有黄鹂千百","飞云当面化龙蛇：飞云当面化龙蛇（云的形状如龙蛇）","夭矫转空碧：夭矫（屈伸的样子）转空碧。夭矫音yāojiǎo","醉卧古藤阴下：醉卧古藤阴下","了不知南北：了（完全）不知南北"]
  },
  "春日偶成|程颢": {
    s: "首两句「云淡风轻近午天，傍花随柳过前川」写云淡风轻近午天、傍花随柳过前川，以春景写郊游的快乐；后两句「时人不识余心乐，将谓偷闲学少年」是名句——时人不认识我心中的快乐，以为我偷闲学少年游乐，以「时人不识」写理学家的「孔颜乐处」——不是少年的游乐，而是理学家的「天理之乐」，全诗意境明丽、哲理深沉，「时人不识余心乐，将谓偷闲学少年」成为名句。",
    b: "程颢（北宋理学家，「二程」之一）这首《春日偶成》写春日郊游的快乐，「时人不识余心乐，将谓偷闲学少年」是名句，是理学家诗的名篇。",
    n: ["春日偶成：诗题，程颢作","云淡风轻近午天：云淡风轻近午天（中午）","傍花随柳过前川：傍花随柳过前川（前面的河流）","时人不识余心乐：时人不识余心乐","将谓偷闲学少年：将谓偷闲学少年（以为我偷闲学少年游乐）"]
  },
  "六国论|苏洵": {
    s: "全文分五段：第一段提出中心论点——「六国破灭，非兵不利，战不善，弊在赂秦」，并分两层：赂秦而力亏是破灭之道，不赂者以赂者丧（失强援不能独完）；第二段论证「赂秦而力亏」——秦以攻取之外小则获邑大则得城，较秦之所得与战胜而得者其实百倍，诸侯之所亡与战败而亡者其实亦百倍，故秦之所大欲诸侯之所大患固不在战；思厥先祖父暴霜露斩荆棘以有尺寸之地，子孙视之不甚惜举以予人如弃草芥，今日割五城明日割十城然后得一夕安寝，起视四境而秦兵又至；然则诸侯之地有限暴秦之欲无厌，奉之弥繁侵之愈急，故不战而强弱胜负已判矣，至于颠覆理固宜然；引古人云「以地事秦犹抱薪救火，薪不尽火不灭」；第三段论证「不赂者以赂者丧」——齐人未尝赂秦终继五国迁灭，因为与嬴而不助五国，五国既丧齐亦不免；燕赵之君始有远略能守其土义不赂秦，故燕虽小国而后亡斯用兵之效；至丹以荆卿为计始速祸，赵尝五战于秦二败三胜，后秦击赵者再李牧连却之，洎牧以谗诛邯郸为郡，惜其用武而不终；且燕赵处秦革灭殆尽之际可谓智力孤危，战败而亡诚不得已；向使三国各爱其地齐人勿附于秦刺客不行良将犹在，则胜负之数存亡之理当与秦相较或未易量；第四段总结教训——以赂秦之地封天下之谋臣，以事秦之心礼天下之奇才，并力西向则吾恐秦人食之不得下咽；悲夫有如此之势而为秦人积威之所劫，日削月割以趋于亡，为国者无使为积威之所劫哉；第五段借古讽今——夫六国与秦皆诸侯其势弱于秦而犹有可以不赂而胜之之势，苟以天下之大下而从六国破亡之故事，是又在六国下矣。全文论证严密、对比鲜明、气势充沛、借古讽今，「弊在赂秦」「以地事秦犹抱薪救火」「为国者无使为积威之所劫」成为千古名句，是论说文的典范。",
    b: "苏洵（北宋散文家，「唐宋八大家」之一，苏轼之父）这篇《六国论》通过分析六国灭亡的原因在于「赂秦」，借古讽今，告诫北宋统治者不要重蹈覆辙，是中国古代论说文的千古名篇。",
    n: ["六国论：篇名，苏洵作","六国破灭：六国破灭","非兵不利：不是兵器不锋利","战不善：仗打得不好","弊在赂秦：弊病在于贿赂秦国","赂秦而力亏：贿赂秦国而力量亏损","破灭之道也：是破灭的道路","或曰：有人说","六国互丧：六国相继灭亡","率赂秦耶：都是因为贿赂秦国吗。率音shuài，全都","不赂者以赂者丧：不贿赂的因为贿赂的而灭亡","盖失强援：大概因为失去了强大的援助","不能独完：不能独自保全","秦以攻取之外：秦国除了用战争夺取之外","小则获邑：小的就获得邑镇","大则得城：大的就获得城池","较秦之所得：比较秦国所得到的","其实百倍：它实际（数量）是百倍","诸侯之所亡：诸侯所失去的","其实亦百倍：它实际也是百倍","则秦之所大欲：那么秦国最大的欲望","诸侯之所大患：诸侯最大的祸患","固不在战矣：本来就不在于战争了","思厥先祖父：想想他们的先人祖父。厥音jué，其","暴霜露：冒着霜露。暴音pù，同「曝」","斩荆棘：斩断荆棘","以有尺寸之地：才有了尺寸之地","子孙视之不甚惜：子孙看待它不很爱惜","举以予人：拿来送给别人","如弃草芥：像抛弃草芥一样","今日割五城：今天割让五城","明日割十城：明天割让十城","然后得一夕安寝：然后得到一夜的安睡","起视四境：起来看看四周边境","而秦兵又至矣：而秦兵又到了","然则诸侯之地有限：既然这样那么诸侯的土地有限","暴秦之欲无厌：强暴的秦国的欲望没有满足。厌同「餍」，满足","奉之弥繁：奉送它越频繁。弥音mí，更加","侵之愈急：侵犯它越急迫","故不战而强弱胜负已判矣：所以不打仗而强弱胜负已经判定了","至于颠覆：到了灭亡","理固宜然：道理本来应该这样","古人云：古人说","以地事秦：用土地侍奉秦国","犹抱薪救火：就像抱着柴草救火","薪不尽：柴草不烧完","火不灭：火不会灭","此言得之：这话说对了","齐人未尝赂秦：齐人不曾贿赂秦国","终继五国迁灭：最终跟着五国灭亡","何哉：为什么呢","与嬴而不助五国也：亲附秦国而不帮助五国。与，亲附；嬴，秦王姓嬴，代指秦国","五国既丧：五国已经灭亡","齐亦不免矣：齐国也免不了了","燕赵之君：燕赵的国君","始有远略：开始有长远的谋略","能守其土：能守住他们的土地","义不赂秦：坚持正义不贿赂秦国","是故燕虽小国而后亡：所以燕国虽然是小国却后灭亡","斯用兵之效也：这是用兵的效果","至丹以荆卿为计：到了燕太子丹用荆轲（刺秦王）作为计策","始速祸焉：才招致了祸患。速，招致","赵尝五战于秦：赵国曾经与秦国打了五次仗","二败而三胜：两次失败三次胜利","后秦击赵者再：后来秦国两次攻打赵国","李牧连却之：李牧接连击退了它","洎牧以谗诛：等到李牧因为谗言被杀。洎音jì，等到","邯郸为郡：邯郸成为（秦国的）郡","惜其用武而不终也：可惜它用武力而不能坚持到底","且燕赵处秦革灭殆尽之际：况且燕赵处在秦国消灭（各国）将近完了的时候","可谓智力孤危：可以说智谋力量孤危","战败而亡：战败而灭亡","诚不得已：实在是不得已","向使三国各爱其地：假使三国（韩魏楚）各自爱惜他们的土地","齐人勿附于秦：齐人不要亲附秦国","刺客不行：刺客（荆轲）不去行刺","良将犹在：良将（李牧）还在","则胜负之数：那么胜负的命运。数音shù，命运","存亡之理：存亡的道理","当与秦相较：应当与秦国相比较","或未易量：或许还不容易估量","呜呼：唉","以赂秦之地封天下之谋臣：用贿赂秦国的土地分封天下的谋臣","以事秦之心礼天下之奇才：用侍奉秦国的心礼遇天下的奇才","并力西向：合力向西（对付秦国）","则吾恐秦人食之不得下咽也：那么我恐怕秦国人吃饭也咽不下去","悲夫：可悲啊","有如此之势：有这样的形势","而为秦人积威之所劫：却被秦国人积久的威势所胁迫。劫，胁迫","日削月割：天天割地月月割地","以趋于亡：以至于走向灭亡","为国者无使为积威之所劫哉：治理国家的人不要被积久的威势所胁迫啊","夫六国与秦皆诸侯：六国和秦国都是诸侯","其势弱于秦：他们的势力比秦国弱","而犹有可以不赂而胜之之势：却还有可以不贿赂而战胜它的形势","苟以天下之大：如果凭着天下的广大","下而从六国破亡之故事：降低身份追随六国灭亡的旧事（前例）","是又在六国下矣：这又在六国之下了"]
  },
  "定风波|苏轼": {
    s: "上片「莫听穿林打叶声。何妨吟啸且徐行。竹杖芒鞋轻胜马。谁怕。一蓑烟雨任平生」写莫听穿林打叶声、何妨吟啸且徐行，竹杖芒鞋轻胜马谁怕一蓑烟雨任平生，以「一蓑烟雨任平生」写面对风雨的旷达；下片「料峭春风吹酒醒。微冷。山头斜照却相迎。回首向来潇洒处。归去。也无风雨也无晴」写料峭春风吹酒醒微冷、山头斜照却相迎，回首向来潇洒处归去也无风雨也无晴，以「也无风雨也无晴」写宠辱不惊的人生态度——风雨和晴天都无所谓，全词意境旷达、哲理深沉、情感豪迈，「一蓑烟雨任平生」「也无风雨也无晴」成为千古名句，是豪放词的千古名篇。",
    b: "苏轼这首《定风波》是他被贬黄州时所作，写途中遇雨的经历，表达「也无风雨也无晴」的旷达人生态度，是豪放词的千古名篇。",
    n: ["定风波：词牌名","莫听穿林打叶声：不要听穿林打叶的声音","何妨吟啸且徐行：何妨吟诗长啸且慢慢走","竹杖芒鞋轻胜马：竹杖草鞋轻胜过马。芒鞋，草鞋","谁怕：谁怕","一蓑烟雨任平生：一蓑烟雨任平生（任凭一生风雨）","料峭春风吹酒醒：微寒的春风吹酒醒。料峭，微寒","微冷：微冷","山头斜照却相迎：山头斜照却相迎","回首向来潇洒处：回首刚才走过的地方（潇洒处，指遇雨的地方）","归去：归去","也无风雨也无晴：也没有风雨也没有晴天（指宠辱不惊）"]
  },
  "江神子・江城子|苏轼": {
    s: "上片「十年生死两茫茫。不思量。自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜」写十年生死两茫茫、不思量自难忘，千里孤坟无处话凄凉，纵使相逢应不识尘满面鬓如霜，以「十年生死」「千里孤坟」写时间与空间的阻隔、以「尘满面鬓如霜」写自己的衰老；下片「夜来幽梦忽还乡。小轩窗。正梳妆。相顾无言，惟有泪千行。料得年年断肠处，明月夜，短松冈」写夜来幽梦忽还乡、小轩窗正梳妆，相顾无言惟有泪千行，料得年年断肠处明月夜短松冈，以梦中相见写思念、以「相顾无言惟有泪千行」写悲痛、以「明月夜短松冈」写永恒的思念，全词意境凄清、情感深沉、真挚动人，「十年生死两茫茫」「相顾无言，惟有泪千行」成为千古名句，是悼亡词的千古绝唱。",
    b: "苏轼这首《江城子》是他悼念亡妻王弗所作，是中国文学史上最著名的悼亡词，「十年生死两茫茫」「相顾无言，惟有泪千行」是千古名句，是婉约词的千古名篇。",
    n: ["江神子：词牌名，即《江城子》","十年生死两茫茫：十年生死两茫茫（苏轼妻王弗去世十年）","不思量：不思量","自难忘：自难忘","千里孤坟：千里孤坟（王弗葬在四川彭山，苏轼在山东密州，相隔千里）","无处话凄凉：无处话凄凉","纵使相逢应不识：纵使相逢应不识","尘满面：尘满面","鬓如霜：鬓如霜","夜来幽梦忽还乡：夜来幽梦忽还乡","小轩窗：小轩窗","正梳妆：正梳妆","相顾无言：相顾无言","惟有泪千行：惟有泪千行","料得年年断肠处：料得年年断肠处","明月夜：明月夜","短松冈：短松冈（王弗墓地）"]
  },
  "蝶恋花|苏轼": {
    s: "上片「花褪残红青杏小。燕子飞时，绿水人家绕。枝上柳绵吹又少。天涯何处无芳草」写花褪残红青杏小、燕子飞时绿水人家绕，枝上柳绵吹又少天涯何处无芳草，以暮春景色写伤春；下片「墙里秋千墙外道。墙外行人，墙里佳人笑。笑渐不闻声渐悄。多情却被无情恼」写墙里秋千墙外道、墙外行人墙里佳人笑，笑渐不闻声渐悄多情却被无情恼，以「墙里墙外」的场景写多情被无情恼，全词意境清丽、情感深沉、哲理巧妙，「天涯何处无芳草」「多情却被无情恼」成为千古名句，是婉约词的千古名篇。",
    b: "苏轼这首《蝶恋花》写暮春景色与多情被无情恼的感慨，「天涯何处无芳草」「多情却被无情恼」是千古名句，是婉约词的千古名篇。",
    n: ["蝶恋花：词牌名","花褪残红青杏小：花褪残红青杏小","燕子飞时：燕子飞时","绿水人家绕：绿水人家绕","枝上柳绵吹又少：枝上柳绵吹又少","天涯何处无芳草：天涯何处无芳草","墙里秋千墙外道：墙里秋千墙外道","墙外行人：墙外行人","墙里佳人笑：墙里佳人笑","笑渐不闻声渐悄：笑渐不闻声渐悄","多情却被无情恼：多情却被无情恼"]
  },
  "浣溪沙|苏轼": {
    s: "上片「山下兰芽短浸溪。松间沙路净无泥。萧萧暮雨子规啼」写山下兰芽短浸溪、松间沙路净无泥，萧萧暮雨子规啼，以暮春景色写环境的清幽；下片「谁道人生无再少。门前流水尚能西。休将白发唱黄鸡」写谁道人生无再少、门前流水尚能西，休将白发唱黄鸡，以「流水尚能西」的反常现象说明人生可以「再少」、以「休将白发唱黄鸡」反用白居易典故写不要感叹时光流逝，全词意境清丽、哲理深沉、情感旷达，「谁道人生无再少，门前流水尚能西」成为千古名句，是豪放词的千古名篇。",
    b: "苏轼这首《浣溪沙》是他被贬黄州时游蕲水清泉寺所作，写暮春景色与「人生无再少」的旷达，「谁道人生无再少，门前流水尚能西」是千古名句，是豪放词的千古名篇。",
    n: ["浣溪沙：词牌名","山下兰芽短浸溪：山下兰芽短浸溪","松间沙路净无泥：松间沙路净无泥","萧萧暮雨子规啼：萧萧暮雨子规（杜鹃）啼","谁道人生无再少：谁道人生无再少","门前流水尚能西：门前流水尚能西（溪水向西流，反「百川东到海」意）","休将白发唱黄鸡：休将白发唱黄鸡（不要因白发而感叹时光流逝，用白居易「黄鸡催晓」「白日催年」意，反其意而用之）"]
  },
  "和子由渑池怀旧|苏轼": {
    s: "首联「人生到处知何似，应似飞鸿踏雪泥」以「飞鸿踏雪泥」比喻人生的行踪不定，成为千古名句，「雪泥鸿爪」成为成语；颔联「泥上偶然留指爪，鸿飞那复计东西」承接比喻——泥上偶然留下指爪，鸿雁飞走哪还计较东西，写人生的偶然与无常；颈联「老僧已死成新塔，坏壁无由见旧题」回到渑池的具体往事——老僧奉闲已死建成新塔，坏壁上当年的旧题已看不到，以具体人事写人生无常；尾联「往日崎岖还记否，路长人困蹇驴嘶」回忆当年路过渑池的艰辛——路长人困跛驴嘶，以回忆作结，全诗比喻新奇、哲理深沉、情感真挚，「人生到处知何似，应似飞鸿踏雪泥」成为千古名句，「雪泥鸿爪」成为成语。",
    b: "苏轼这首《和子由渑池怀旧》是他早年所作，写对人生无常的感慨，「人生到处知何似，应似飞鸿踏雪泥」是千古名句，「雪泥鸿爪」成为成语，是七律的千古名篇。",
    n: ["和子由渑池怀旧：诗题，和弟弟苏辙（字子由）的《渑池怀旧》","人生到处知何似：人生到处知何似","应似飞鸿踏雪泥：应似飞鸿踏雪泥","泥上偶然留指爪：泥上偶然留指爪","鸿飞那复计东西：鸿飞那复计东西","老僧已死成新塔：老僧已死成新塔（渑池寺中老僧奉闲已死，建了新塔）","坏壁无由见旧题：坏壁无由见旧题（当年题在壁上的诗已看不到了）","往日崎岖还记否：往日崎岖还记否","路长人困蹇驴嘶：路长人困蹇驴（跛脚驴）嘶。蹇音jiǎn"]
  },
  "东栏梨花|苏轼": {
    s: "首两句「梨花淡白柳深青，柳絮飞时花满城」写梨花淡白柳深青、柳絮飞时花满城，以梨花与柳絮对比写春景；后两句「惆怅东栏一株雪，人生看得几清明」是名句——惆怅东栏一株梨花如雪，人生能看到几个清明呢，以「几清明」的反问写人生短暂、春光易逝，全诗意境清丽、情感深沉、哲理巧妙，「人生看得几清明」成为名句。",
    b: "苏轼这首《东栏梨花》写梨花与人生感慨，「人生看得几清明」是名句，是七绝的名篇。",
    n: ["东栏梨花：诗题","梨花淡白柳深青：梨花淡白柳深青","柳絮飞时花满城：柳絮飞时花满城","惆怅东栏一株雪：惆怅东栏一株雪（指梨花）","人生看得几清明：人生看得几清明（几个清明时节）"]
  },
  "海棠|苏轼": {
    s: "首两句「东风袅袅泛崇光，香雾空蒙月转廊」写东风袅袅泛崇光、香雾空蒙月转廊，以东风、香雾、月光写海棠的美丽；后两句「只恐夜深花睡去，故烧高烛照红妆」是千古名句——只恐夜深花睡去，所以烧高烛照红妆，以「花睡去」的拟人写对花的珍爱、以「烧高烛照红妆」写赏花的痴情，全诗意境清丽、拟人巧妙、情感真挚，「只恐夜深花睡去，故烧高烛照红妆」成为千古名句。",
    b: "苏轼这首《海棠》写深夜赏花，以「只恐夜深花睡去，故烧高烛照红妆」写对花的珍爱，是七绝的千古名篇。",
    n: ["海棠：诗题","东风袅袅泛崇光：东风袅袅（轻柔）泛崇光（流动的光泽）。袅袅音niǎo","香雾空蒙月转廊：香雾空蒙月转廊（回廊）","只恐夜深花睡去：只恐夜深花睡去","故烧高烛照红妆：所以烧高烛照红妆（指海棠花）"]
  },
  "春宵|苏轼": {
    s: "首两句「春宵一刻值千金，花有清香月有阴」写春宵一刻值千金、花有清香月有阴，以「一刻值千金」写春夜的珍贵，成为千古成语；后两句「歌管楼台声细细，秋千院落夜沉沉」写歌管楼台声细细、秋千院落夜沉沉，以「声细细」「夜沉沉」写春夜的幽静，全诗意境清丽、语言明快、哲理深沉，「春宵一刻值千金」成为千古成语。",
    b: "苏轼这首《春宵》写春夜的美好，「春宵一刻值千金」成为千古成语，是七绝的名篇。",
    n: ["春宵：诗题","春宵一刻值千金：春宵一刻值千金（成语出处）","花有清香月有阴：花有清香月有阴（阴影）","歌管楼台声细细：歌管楼台声细细","秋千院落夜沉沉：秋千院落夜沉沉"]
  },
  "石钟山记|苏轼": {
    s: "全文分三段：第一段提出质疑——《水经》云彭蠡之口有石钟山，郦道元以为下临深潭微风鼓浪水石相搏声如洪钟，人常疑之（以钟磬置水中虽大风浪不能鸣）；唐李渤访遗踪得双石扣而聆之南声函胡北音清越桴止响腾余韵徐歇自以为得之，余尤疑之（石之铿然有声者所在皆是也，而此独以钟名何哉）；第二段写实地考察——元丰七年六月丁丑余自齐安舟行适临汝，长子迈赴饶之德兴尉，送之至湖口因得观所谓石钟；寺僧使小童持斧于乱石间择其一二扣之硿硿焉，余固笑而不信；至莫夜月明独与迈乘小舟至绝壁下，大石侧立千尺如猛兽奇鬼森然欲搏人，山上栖鹘闻人声惊起磔磔云霄间，又有若老人咳且笑于山谷中者或曰此鹳鹤也；余方心动欲还而大声发于水上噌吰如钟鼓不绝舟人大恐；徐而察之则山下皆石穴罅不知其浅深微波入焉涵澹澎湃而为此也；舟回至两山间将入港口有大石当中流可坐百人空中而多窍与风水相吞吐有窾坎镗鞳之声与向之噌吰者相应如乐作焉；因笑谓迈曰「汝识之乎？噌吰者周景王之无射也，窾坎镗鞳者魏庄子之歌钟也，古之人不余欺也」；第三段写议论——事不目见耳闻而臆断其有无可乎？郦元之所见闻殆与余同而言之不详；士大夫终不肯以小舟夜泊绝壁之下故莫能知；渔工水师虽知而不能言，此世所以不传也；而陋者乃以斧斤考击而求之自以为得其实；余是以记之，盖叹郦元之简而笑李渤之陋也。全文叙议结合、考察细致、议论精辟，「事不目见耳闻，而臆断其有无，可乎」「古之人不余欺也」成为千古名句，是游记散文的典范。",
    b: "苏轼这篇《石钟山记》是他由黄州移任汝州、送儿子苏迈赴德兴尉任时游石钟山所作，通过实地考察探明石钟山命名的原因，提出「事不目见耳闻，而臆断其有无，可乎」的治学态度，是中国古代游记散文的千古名篇。",
    n: ["石钟山记：篇名，苏轼作","《水经》云：《水经》说","彭蠡之口有石钟山焉：彭蠡（鄱阳湖）口有石钟山","郦元以为下临深潭：郦元（郦道元）认为下临深潭","微风鼓浪：微风鼓浪（鼓动波浪）","水石相搏：水石相搏（撞击）","声如洪钟：声如洪钟","是说也：这个说法","人常疑之：人们常常怀疑它","今以钟磬置水中：现在把钟磬放在水中","虽大风浪不能鸣也：即使大风浪也不能使它鸣响","而况石乎：更何况石头呢","至唐李渤始访其遗踪：到唐李渤才寻访它的遗迹","得双石于潭上：在潭上得到两块石头","扣而聆之：敲而听它。扣同「叩」，敲击；聆音líng，听","南声函胡：南边的声音函胡（模糊）","北音清越：北边的声音清越（清脆高扬）","桴止响腾：鼓槌停止声音还在腾响。桴音fú，鼓槌","余韵徐歇：余韵慢慢停歇","自以为得之矣：自以为得到了（石钟山命名的原因）","然是说也：然而这个说法","余尤疑之：我更加怀疑它","石之铿然有声者：石头铿然（金石声）有声的","所在皆是也：到处都是这样","而此独以钟名：而这里独以钟命名","何哉：为什么呢","元丰七年六月丁丑：元丰七年（1084）六月丁丑日","余自齐安舟行适临汝：我从齐安（今湖北黄冈）坐船到临汝（今河南临汝）","而长子迈将赴饶之德兴尉：而大儿子苏迈将去饶州德兴县做县尉","送之至湖口：送他到湖口（今江西湖口）","因得观所谓石钟者：因而得以观看所谓石钟山","寺僧使小童持斧：寺僧让小童拿着斧头","于乱石间择其一二扣之：在乱石间选一两块敲它","硿硿焉：硿硿地响。硿音kōng","余固笑而不信也：我本来笑着不相信","至莫夜月明：到了暮夜（夜晚）月明。莫同「暮」","独与迈乘小舟：独与苏迈乘小舟","至绝壁下：到绝壁下","大石侧立千尺：大石侧立千尺","如猛兽奇鬼：如猛兽奇鬼","森然欲搏人：森然（阴森的样子）想要扑人","而山上栖鹘：而山上栖鹘（隼类猛禽）。鹘音hú","闻人声而惊起：听到人声而惊起","磔磔云霄间：磔磔（鸟鸣声）在云霄间。磔音zhé","又有若老人咳且笑于山谷中者：又有像老人咳嗽且笑在山谷中的","或曰此鹳鹤也：有人说这是鹳鹤。鹳音guàn","余方心动欲还：我正心惊想要回去","而大声发于水上：而大声发于水上","噌吰如钟鼓不绝：噌吰（钟声）如钟鼓不绝。噌吰音chēnghóng","舟人大恐：船夫非常害怕","徐而察之：慢慢观察它","则山下皆石穴罅：则山下都是石穴裂缝。罅音xià，裂缝","不知其浅深：不知它的浅深","微波入焉：微波进入其中","涵澹澎湃而为此也：涵澹（水波动荡）澎湃（波浪相激）而发出这个声音。涵澹音hándàn","舟回至两山间：船回到两山间","将入港口：将要进入港口","有大石当中流：有大石挡在中流","可坐百人：可坐百人","空中而多窍：中间空而多窍（孔）","与风水相吞吐：与风水相吞吐","有窾坎镗鞳之声：有窾坎镗鞳（钟鼓声）之声。窾坎镗鞳音kuǎnkǎntāngtà","与向之噌吰者相应：与刚才的噌吰声相应和","如乐作焉：如音乐演奏一样","因笑谓迈曰：于是笑着对苏迈说","汝识之乎：你知道吗。识音zhì，同「志」，记住","噌吰者：噌吰的声音","周景王之无射也：是周景王的无射钟（无射，钟名，音wúyì）","窾坎镗鞳者：窾坎镗鞳的声音","魏庄子之歌钟也：是魏庄子（魏绛）的歌钟","古之人不余欺也：古人没有欺骗我啊（不余欺，不欺余）","事不目见耳闻：事情不目见耳闻","而臆断其有无：而主观判断它的有无","可乎：可以吗","郦元之所见闻：郦道元的所见所闻","殆与余同：大概与我相同","而言之不详：而说得不详细","士大夫终不肯以小舟夜泊绝壁之下：士大夫终究不肯以小舟夜泊绝壁之下","故莫能知：所以不能知道","而渔工水师虽知而不能言：而渔工水师虽然知道却不能说出来","此世所以不传也：这是世上所以不流传的原因","而陋者乃以斧斤考击而求之：而浅陋的人竟以斧头敲击来寻求它","自以为得其实：自以为得到了它的实际","余是以记之：我因此记下它","盖叹郦元之简：大概感叹郦道元的简略","而笑李渤之陋也：而嘲笑李渤的浅陋"]
  },
  "后赤壁赋|苏轼": {
    s: "全文分四段：第一段写游前准备——是岁十月之望步自雪堂将归于临皋，二客从予过黄泥之坂，霜露既降木叶尽脱，人影在地仰见明月，顾而乐之行歌相答；已而叹曰有客无酒有酒无肴月白风清如此良夜何；客曰今者薄暮举网得鱼巨口细鳞状如松江之鲈顾安所得酒乎；归而谋诸妇，妇曰我有斗酒藏之久矣以待子不时之需；第二段写游赤壁——于是携酒与鱼复游于赤壁之下，江流有声断岸千尺，山高月小水落石出，曾日月之几何而江山不可复识矣；第三段写登山——予乃摄衣而上，履巉岩披蒙茸踞虎豹登虬龙，攀栖鹘之危巢俯冯夷之幽宫，盖二客不能从焉；划然长啸草木震动山鸣谷应风起水涌，予亦悄然而悲肃然而恐凛乎其不可留也；反而登舟放乎中流听其所止而休焉；第四段写孤鹤与梦境——时夜将半四顾寂寥，适有孤鹤横江东来翅如车轮玄裳缟衣戛然长鸣掠予舟而西也；须臾客去予亦就睡，梦一道士羽衣蹁跹过临皋之下揖予而言曰赤壁之游乐乎；问其姓名俯而不答，呜呼噫嘻我知之矣畴昔之夜飞鸣而过我者非子也邪；道士顾笑余亦惊悟，开户视之不见其处。全文写景如画、叙事生动、梦境奇幻、哲理深沉，「山高月小，水落石出」成为千古名句，与《前赤壁赋》并称赋体散文的双璧。",
    b: "苏轼这篇《后赤壁赋》是他被贬黄州时所作，是《前赤壁赋》的姊妹篇，写十月十五日游赤壁的经历，以孤鹤与道士的梦境写超脱旷达的人生态度，是中国古代赋体散文的千古名篇。",
    n: ["后赤壁赋：篇名，苏轼作","是岁十月之望：这年十月十五日（望，农历十五）","步自雪堂：从雪堂（苏轼在黄州建的堂）步行","将归于临皋：将回到临皋（苏轼在黄州的居所）","二客从予过黄泥之坂：两位客人跟我过黄泥坂（山坡）。坂音bǎn","霜露既降：霜露已经降下","木叶尽脱：树叶全部脱落","人影在地：人影在地","仰见明月：仰见明月","顾而乐之：顾而乐之","行歌相答：边走边唱互相唱和","已而叹曰：过了一会儿叹道","有客无酒：有客无酒","有酒无肴：有酒无菜。肴音yáo，菜","月白风清：月白风清","如此良夜何：如此良夜怎么办呢","客曰：客人说","今者薄暮：刚才傍晚","举网得鱼：举网得鱼","巨口细鳞：巨口细鳞","状如松江之鲈：形状像松江的鲈鱼","顾安所得酒乎：但哪里能得到酒呢","归而谋诸妇：回去跟妻子商量","妇曰：妻子说","我有斗酒：我有一斗酒","藏之久矣：藏了很久了","以待子不时之需：以等待你不时的需要","于是携酒与鱼：于是携酒与鱼","复游于赤壁之下：又游于赤壁之下","江流有声：江流有声","断岸千尺：断岸千尺","山高月小：山高月小","水落石出：水落石出","曾日月之几何：才过了多少日子（距前次游赤壁）","而江山不可复识矣：而江山不可再认识了（变化太大）","予乃摄衣而上：我于是提起衣服上山","履巉岩：踏险峻的岩石。巉音chán","披蒙茸：拨开茂密的野草。蒙茸音méngróng","踞虎豹：蹲在虎豹（形状像虎豹的石头）上","登虬龙：登上虬龙（形状像虬龙的树木）。虬音qiú","攀栖鹘之危巢：攀栖鹘（猛禽）的高巢。鹘音hú","俯冯夷之幽宫：俯视冯夷（水神）的幽宫。冯夷音píngyí","盖二客不能从焉：大概两位客人不能跟从我了","划然长啸：划然（长啸声）长啸","草木震动：草木震动","山鸣谷应：山鸣谷应","风起水涌：风起水涌","予亦悄然而悲：我也悄然而悲","肃然而恐：肃然而恐","凛乎其不可留也：凛然（恐惧的样子）不可久留了","反而登舟：反而登舟","放乎中流：放（船）到中流","听其所止而休焉：听它停在哪里就休息在哪里","时夜将半：时夜将半","四顾寂寥：四顾寂寥","适有孤鹤：恰好有孤鹤","横江东来：横江东来","翅如车轮：翅如车轮","玄裳缟衣：玄裳（黑裙）缟衣（白衣）。玄，黑色；缟音gǎo，白色","戛然长鸣：戛然（鹤鸣声）长鸣。戛音jiá","掠予舟而西也：掠过我的船向西去了","须臾客去：过了一会儿客人离去","予亦就睡：我也去睡","梦一道士：梦见一个道士","羽衣蹁跹：羽衣（道士穿的鸟羽衣）蹁跹（轻盈飞舞）。蹁跹音piánxiān","过临皋之下：过临皋之下","揖予而言曰：向我作揖说道","赤壁之游乐乎：赤壁之游乐吗","问其姓名：问他姓名","俯而不答：俯而不答","呜呼噫嘻：呜呼噫嘻（感叹词）","我知之矣：我知道了","畴昔之夜：昨夜","飞鸣而过我者：飞鸣而过我的","非子也邪：不是你吗","道士顾笑：道士回头笑","余亦惊悟：我也惊醒","开户视之：开门看他","不见其处：不见他的去处"]
  },
  "苏幕遮|范仲淹": {
    s: "上片「碧云天。黄叶地。秋色连波，波上寒烟翠。山映斜阳天接水。芳草无情，更在斜阳外」写碧云天黄叶地、秋色连波波上寒烟翠，山映斜阳天接水、芳草无情更在斜阳外，以秋景写思乡；下片「黯乡魂。追旅思。夜夜除非，好梦留人睡。明月楼高休独倚。酒入愁肠，化作相思泪」写黯乡魂追旅思、夜夜除非好梦留人睡，明月楼高休独倚、酒入愁肠化作相思泪，以「酒入愁肠化作相思泪」的夸张写思乡之深，全词意境开阔、情感深沉、夸张巧妙，「碧云天，黄叶地」「酒入愁肠，化作相思泪」成为千古名句，是婉约词的千古名篇。",
    b: "范仲淹（北宋政治家、文学家）这首《苏幕遮》写秋日思乡之情，「碧云天，黄叶地」「酒入愁肠，化作相思泪」是千古名句，是婉约词的千古名篇。",
    n: ["苏幕遮：词牌名","碧云天：碧云天","黄叶地：黄叶地","秋色连波：秋色连波","波上寒烟翠：波上寒烟翠","山映斜阳天接水：山映斜阳天接水","芳草无情：芳草无情","更在斜阳外：更在斜阳外","黯乡魂：黯乡魂（思乡的灵魂黯然）","追旅思：追旅思（羁旅的愁思）","夜夜除非：夜夜除非","好梦留人睡：好梦留人睡","明月楼高休独倚：明月楼高休独倚","酒入愁肠：酒入愁肠","化作相思泪：化作相思泪"]
  },
  "渔家傲|范仲淹": {
    s: "上片「塞下秋来风景异。衡阳雁去无留意。四面边声连角起。千嶂里。长烟落日孤城闭」写塞下秋来风景异、衡阳雁去无留意，四面边声连角起，千嶂里长烟落日孤城闭，以边塞秋景写环境的荒凉；下片「浊酒一杯家万里。燕然未勒归无计。羌管悠悠霜满地。人不寐。将军白发征夫泪」写浊酒一杯家万里、燕然未勒归无计，羌管悠悠霜满地，人不寐将军白发征夫泪，以「家万里」与「燕然未勒」的矛盾写将士的思乡与报国、以「将军白发征夫泪」写将士的悲苦，全词意境苍凉、情感深沉、刚健豪放，「将军白发征夫泪」成为千古名句，是豪放词的千古名篇，开宋代豪放词之先声。",
    b: "范仲淹这首《渔家傲》是他任陕西经略副使、镇守西北边疆时所作，写边塞将士的思乡与报国之情，「将军白发征夫泪」是千古名句，是豪放词的千古名篇，开宋代豪放词之先声。",
    n: ["渔家傲：词牌名","塞下秋来风景异：塞下秋来风景异","衡阳雁去无留意：衡阳雁去无留意（雁去衡阳，毫无留恋之意）","四面边声连角起：四面边声（边塞的声音）连角（号角）起","千嶂里：千嶂（像屏障的山峰）里","长烟落日孤城闭：长烟落日孤城闭","浊酒一杯家万里：浊酒一杯家万里","燕然未勒归无计：燕然未勒归无计（燕然，山名，东汉窦宪追北单于登燕然山刻石纪功；勒，刻石。指没有建立功业不能回去）","羌管悠悠霜满地：羌管（羌笛）悠悠霜满地","人不寐：人不寐（睡不着）","将军白发征夫泪：将军白发征夫泪"]
  },
  "贺新郎|蒋捷": {
    s: "上片「渺渺啼鸦了。亘鱼天、寒生峭屿，五湖秋晓。竹几一灯人做梦，嘶马谁行古道。起搔首、窥星多少。月有微黄篱无影，挂牵牛、数朵青花小。秋太淡，添红枣」写渺渺啼鸦了、亘鱼天寒生峭屿五湖秋晓，竹几一灯人做梦嘶马谁行古道，起搔首窥星多少，月有微黄篱无影挂牵牛数朵青花小，秋太淡添红枣，以秋景写愁思；下片「愁痕倚赖西风扫。被西风、翻催鬓鬒，与秋俱老。旧院隔霜帘不卷，金粉屏边醉倒。计无此、中年怀抱。万里江南吹箫恨，恨参差、白雁横天杪。烟未敛，楚山杳」写愁痕倚赖西风扫、被西风翻催鬓鬒与秋俱老，旧院隔霜帘不卷金粉屏边醉倒计无此中年怀抱，万里江南吹箫恨恨参差白雁横天杪，烟未敛楚山杳，以「吹箫恨」（伍子胥典故）写亡国之痛、以「白雁横天杪」写愁思的辽远，全词意境凄清、用典贴切（伍子胥吹箫）、情感深沉，是南宋遗民词的名篇。",
    b: "蒋捷（南宋末元初词人，号竹山）这首《贺新郎》写秋日的愁思与亡国之痛，「万里江南吹箫恨」写亡国之痛，是南宋遗民词的名篇，与他的《虞美人·听雨》《一剪梅·舟过吴江》并称。",
    n: ["贺新郎：词牌名","渺渺啼鸦了：渺渺啼鸦了（停）","亘鱼天、寒生峭屿：亘（横贯）鱼天寒生峭屿。亘音gèn","五湖秋晓：五湖（太湖）秋晓","竹几一灯人做梦：竹几一灯人做梦","嘶马谁行古道：嘶马谁行古道","起搔首、窥星多少：起搔首窥星多少","月有微黄篱无影：月有微黄篱无影","挂牵牛、数朵青花小：挂牵牛数朵青花小","秋太淡：秋太淡","添红枣：添红枣","愁痕倚赖西风扫：愁痕倚赖西风扫","被西风、翻催鬓鬒：被西风翻催鬓鬒（鬓发）。鬒音zhěn，黑发","与秋俱老：与秋俱老","旧院隔霜帘不卷：旧院隔霜帘不卷","金粉屏边醉倒：金粉屏边醉倒","计无此、中年怀抱：计无此中年怀抱","万里江南吹箫恨：万里江南吹箫恨（用伍子胥吹箫乞食典故）","恨参差、白雁横天杪：恨参差白雁横天杪（天末）。杪音miǎo","烟未敛：烟未敛","楚山杳：楚山杳（遥远）"]
  },
  "女冠子|蒋捷": {
    s: "上片「蕙花香也。雪晴池馆如画。春风飞到，宝钗楼上，一片笙箫，琉璃光射。而今灯漫挂。不是暗尘明月，那时元夜」写蕙花香、雪晴池馆如画，春风飞到宝钗楼上一片笙箫琉璃光射，而今灯漫挂不是暗尘明月那时元夜，以元宵的今昔对比写亡国之痛；下片「况年来、心懒意怯，羞与蛾儿争要。江城人悄初更打。问繁华谁解，再向天公借。剔残红灺。但梦里隐隐，钿车罗帕。吴笺银粉砑。待把旧家风景，写成闲话。笑绿鬟邻女，倚窗犹唱，夕阳西下」写况年来心懒意怯羞与蛾儿争要，江城人悄初更打，问繁华谁解再向天公借，剔残红灺但梦里隐隐钿车罗帕，吴笺银粉砑待把旧家风景写成闲话，笑绿鬟邻女倚窗犹唱夕阳西下，以「邻女犹唱夕阳西下」写对故国的思念——邻女还在唱从前的歌曲，而故国已亡，全词今昔对比、用典贴切、情感深沉，「笑绿鬟邻女，倚窗犹唱，夕阳西下」成为名句，是南宋遗民词的名篇。",
    b: "蒋捷这首《女冠子》写元宵节的今昔对比，以「笑绿鬟邻女，倚窗犹唱，夕阳西下」写亡国之痛，是南宋遗民词的名篇。",
    n: ["女冠子：词牌名","蕙花香也：蕙花香也","雪晴池馆如画：雪晴池馆如画","春风飞到：春风飞到","宝钗楼上：宝钗楼上","一片笙箫：一片笙箫","琉璃光射：琉璃光射","而今灯漫挂：而今灯漫挂（随便挂）","不是暗尘明月：不是暗尘明月（指从前元宵节的热闹）","那时元夜：那时元夜（元宵节）","况年来、心懒意怯：况年来心懒意怯","羞与蛾儿争要：羞与蛾儿（元宵节的饰物）争要","江城人悄初更打：江城人悄初更打","问繁华谁解：问繁华谁解","再向天公借：再向天公借","剔残红灺：剔残红灺（残烛）。灺音xiè，蜡烛的余烬","但梦里隐隐：但梦里隐隐","钿车罗帕：钿车罗帕（饰金的车、罗帕）","吴笺银粉砑：吴笺银粉砑（压光的银粉纸）。砑音yà，碾磨","待把旧家风景：待把旧家风景","写成闲话：写成闲话","笑绿鬟邻女：笑绿鬟邻女","倚窗犹唱：倚窗犹唱","夕阳西下：夕阳西下（指从前的歌曲）"]
  },
  "虞美人·听雨|蒋捷": {
    s: "全词以「听雨」为线索，分三个阶段：上片「少年听雨歌楼上。红烛昏罗帐。壮年听雨客舟中。江阔云低、断雁叫西风」写少年时在歌楼上听雨、红烛昏罗帐——欢乐奢靡；壮年时在客舟中听雨、江阔云低断雁叫西风——漂泊孤独；下片「而今听雨僧庐下。鬓已星星也。悲欢离合总无情。一任阶前、点滴到天明」写而今在僧庐下听雨、鬓已星星——亡国后的孤苦；悲欢离合总无情，一任阶前点滴到天明——对人生的彻悟与无奈。全词以「听雨」贯穿一生，三个场景三种心境，对比鲜明、情感深沉、语言精炼，「少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。而今听雨僧庐下，鬓已星星也」成为千古名句，是南宋遗民词的千古名篇。",
    b: "蒋捷这首《虞美人·听雨》以「听雨」为线索，写少年、壮年、晚年三个阶段的人生经历，表达亡国后的深沉感慨，是南宋遗民词的千古名篇，「少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。而今听雨僧庐下，鬓已星星也」成为千古名句。",
    n: ["虞美人·听雨：词牌名+题目","少年听雨歌楼上：少年听雨歌楼上","红烛昏罗帐：红烛昏罗帐","壮年听雨客舟中：壮年听雨客舟中","江阔云低、断雁叫西风：江阔云低断雁叫西风","而今听雨僧庐下：而今听雨僧庐下","鬓已星星也：鬓已星星也（花白）","悲欢离合总无情：悲欢离合总无情","一任阶前、点滴到天明：一任阶前点滴到天明"]
  },
  "六州歌头|贺铸": {
    s: "上片「少年侠气，交结五都雄。肝胆洞。毛发耸。立谈中。死生同。一诺千金重。推翘勇。衿豪踪。轻盖拥。聊飞鞚。斗城东。轰饮酒炉，春色浮寒瓮。吸海垂虹。闲呼鹰嗾犬，白羽摘雕弓。狡穴俄空。乐匆匆」写少年侠气交结五都雄，肝胆洞毛发耸立谈中死生同一诺千金重，推翘勇衿豪踪轻盖拥聊飞鞚斗城东，轰饮酒炉春色浮寒瓮吸海垂虹，闲呼鹰嗾犬白羽摘雕弓狡穴俄空乐匆匆，以少年的豪侠生活写欢乐；下片「似黄粱梦。辞丹凤。明月共。漾孤篷。官冗从。怀倥偬。落尘笼。薄书从。鹖弁如云众。共粗用。忽奇功。笳鼓动。渔阳弄。思悲翁。不请长缨，系取天娇种。剑吼西风。恨登山临水，手寄七弦桐。目送归鸿」写似黄粱梦辞丹凤明月共漾孤篷，官冗从怀倥偬落尘笼薄书从，鹖弁如云众共粗用忽奇功，笳鼓动渔阳弄思悲翁，不请长缨系取天娇种剑吼西风，恨登山临水手寄七弦桐目送归鸿，以中年的失意与壮志难酬写悲慨，全词气势磅礴、对比鲜明、情感深沉，「不请长缨，系取天娇种。剑吼西风」成为名句，是豪放词的千古名篇。",
    b: "贺铸（北宋词人，号庆湖遗老）这首《六州歌头》写少年的豪侠生活与中年的失意，以「剑吼西风」写壮志难酬，是豪放词的千古名篇，夏敬观评为「雄姿壮采，不可一世」。",
    n: ["六州歌头：词牌名","少年侠气：少年侠气","交结五都雄：交结五都（五大都市）的英雄","肝胆洞：肝胆洞（肝胆相照、坦诚）","毛发耸：毛发耸（激昂）","立谈中：立谈中（站着谈话之间）","死生同：死生同（同生共死）","一诺千金重：一诺千金重（承诺重如千金）","推翘勇：推翘勇（推崇杰出的勇士）","衿豪踪：衿豪踪（衣襟上带着豪杰的踪迹）","轻盖拥：轻盖拥（轻车簇拥）","聊飞鞚：聊飞鞚（姑且飞马）。鞚音kòng，马笼头，代指马","斗城东：斗城东（汴京城东）","轰饮酒炉：轰饮酒炉（在酒垆豪饮）","春色浮寒瓮：春色浮寒瓮（酒瓮中浮着春色）","吸海垂虹：吸海垂虹（像垂虹吸海一样豪饮）","闲呼鹰嗾犬：闲呼鹰嗾犬（嗾，使唤狗的声音，此指嗾使）。嗾音sǒu","白羽摘雕弓：白羽摘雕弓（从雕弓上取箭）","狡穴俄空：狡穴俄空（狡兔的巢穴很快空了）","乐匆匆：乐匆匆（欢乐匆匆）","似黄粱梦：似黄粱梦（像黄粱一梦）","辞丹凤：辞丹凤（辞别京城。丹凤，丹凤楼，代指京城）","明月共：明月共（与明月相伴）","漾孤篷：漾孤篷（飘荡孤舟）","官冗从：官冗从（做闲散的随从官）。冗音rǒng","怀倥偬：怀倥偬（心怀事情繁忙）。倥偬音kǒngzǒng","落尘笼：落尘笼（落入尘世的牢笼）","薄书从：薄书从（簿书文书相从）","鹖弁如云众：鹖弁如云众（武官如云之多。鹖弁音hébiàn，武官的帽子）","共粗用：共粗用（都做粗用）","忽奇功：忽奇功（忽然建立奇功）","笳鼓动：笳鼓动（笳鼓响起，指战事起）","渔阳弄：渔阳弄（渔阳鼙鼓，指安禄山叛乱，此指金兵入侵）","思悲翁：思悲翁（思念悲翁，古乐府曲名）","不请长缨：不请长缨（不请求长绳，指不请缨杀敌）","系取天娇种：系取天娇种（捆绑天骄，指匈奴，此指金人）","剑吼西风：剑吼西风（剑在西风中吼叫）","恨登山临水：恨登山临水","手寄七弦桐：手寄七弦桐（手寄七弦琴。桐，代指琴）","目送归鸿：目送归鸿"]
  },
  "石州引・石州慢|贺铸": {
    s: "上片「薄雨初寒。斜照弄晴。春意空阔。长亭柳色缠黄。远客一枝先折。烟横水际。映带几点归鸦。东风销尽龙沙雪。还记初关来。恰而今时节」写薄雨初寒斜照弄晴春意空阔，长亭柳色缠黄远客一枝先折，烟横水际映带几点归鸦东风销尽龙沙雪，还记初关来恰而今时节，以春景写离别；下片「将发。画楼芳酒。红泪清歌。顿成清别。已是经年。杳杳音尘多绝。欲知方寸。共有几许清愁。芭蕉不展丁香结。枉望断天涯。两厌厌风月」写将发画楼芳酒红泪清歌顿成清别，已是经年杳杳音尘多绝，欲知方寸共有几许清愁芭蕉不展丁香结，枉望断天涯两厌厌风月，以「芭蕉不展丁香结」化用李商隐诗句写愁、以「两厌厌风月」写两人的相思，全词意境凄清、用典贴切、情感深沉，「芭蕉不展丁香结」成为名句。",
    b: "贺铸这首《石州引》写离别后的相思，「芭蕉不展丁香结」化用李商隐诗句，是婉约词的名篇。",
    n: ["石州引：词牌名，即《石州慢》","薄雨初寒：薄雨初寒","斜照弄晴：斜照弄晴","春意空阔：春意空阔","长亭柳色缠黄：长亭柳色缠黄（嫩黄）","远客一枝先折：远客一枝先折","烟横水际：烟横水际","映带几点归鸦：映带几点归鸦","东风销尽龙沙雪：东风销尽龙沙（边塞）雪","还记初关来：还记初关来（刚出关时）","恰而今时节：恰而今时节","将发：将发","画楼芳酒：画楼芳酒","红泪清歌：红泪清歌","顿成清别：顿成清别","已是经年：已是经年","杳杳音尘多绝：杳杳音尘多绝","欲知方寸：欲知方寸（心）","共有几许清愁：共有几许清愁","芭蕉不展丁香结：芭蕉不展丁香结（用李商隐「芭蕉不展丁香结，同向春风各自愁」）","枉望断天涯：枉望断天涯","两厌厌风月：两厌厌风月（两人都厌厌风月）"]
  },
  "半死桐・鹧鸪天|贺铸": {
    s: "上片「重过阊门万事非。同来何事不同归。梧桐半死清霜后，头白鸳鸯失伴飞」写重过阊门万事非、同来何事不同归，梧桐半死清霜后头白鸳鸯失伴飞，以「梧桐半死」「鸳鸯失伴」比喻丧偶；下片「原上草。露初晞。旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣」写原上草露初晞、旧栖新垅两依依，空床卧听南窗雨谁复挑灯夜补衣，以「挑灯夜补衣」的细节写对妻子的思念——再也没有人挑灯夜里补衣服了，细节生动、情感真挚，全词意境凄清、比喻巧妙、细节生动、情感深沉，「空床卧听南窗雨，谁复挑灯夜补衣」成为千古名句，是悼亡词的千古名篇。",
    b: "贺铸这首《半死桐》是他悼念亡妻赵氏所作，是中国文学史上著名的悼亡词，与苏轼《江城子·十年生死两茫茫》并称，「空床卧听南窗雨，谁复挑灯夜补衣」是千古名句。",
    n: ["半死桐：词牌名，即《鹧鸪天》","重过阊门万事非：重过阊门（苏州西门）万事非","同来何事不同归：同来何事不同归（为什么同来却不能同归，指妻子去世）","梧桐半死清霜后：梧桐半死清霜后（用枚乘「梧桐半死」喻丧偶）","头白鸳鸯失伴飞：头白鸳鸯失伴飞","原上草：原上草","露初晞：露初晞（露水刚干。晞音xī，干）","旧栖新垅两依依：旧栖（旧居）新垅（新坟）两依依。垅同「垄」，坟","空床卧听南窗雨：空床卧听南窗雨","谁复挑灯夜补衣：谁复挑灯夜补衣（谁还会挑灯夜里补衣服呢，指妻子）"]
  },
  "横塘路・青玉案|贺铸": {
    s: "上片「凌波不过横塘路。但目送、芳尘去。锦瑟华年谁与度。月桥花院，琐窗朱户。只有春知处」写凌波不过横塘路但目送芳尘去，锦瑟华年谁与度，月桥花院琐窗朱户只有春知处，以美人的离去写思念；下片「飞云冉冉蘅皋暮。彩笔新题断肠句。若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」写飞云冉冉蘅皋暮彩笔新题断肠句，若问闲情都几许——一川烟草、满城风絮、梅子黄时雨，以三种景物（烟草、风絮、梅雨）比喻闲愁的多、乱、绵长，比喻新奇、对仗工稳，全词意境清丽、比喻巧妙、情感深沉，「若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」成为千古名句，贺铸因此被称为「贺梅子」，是婉约词的千古名篇。",
    b: "贺铸这首《横塘路》写对美人的思念与闲愁，「若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」是千古名句，以三种景物比喻闲愁，是婉约词的千古名篇，贺铸因此被称为「贺梅子」。",
    n: ["横塘路：词牌名，即《青玉案》","凌波不过横塘路：凌波不过横塘路（凌波，形容女子步态轻盈，用曹植「凌波微步」）","但目送、芳尘去：但目送芳尘去（芳尘，美人的踪迹）","锦瑟华年谁与度：锦瑟华年谁与度（美好的青春年华与谁度过。用李商隐「锦瑟无端五十弦」）","月桥花院：月桥花院","琐窗朱户：琐窗朱户（雕花窗、红漆门）","只有春知处：只有春知处","飞云冉冉蘅皋暮：飞云冉冉蘅皋暮（蘅皋，长着杜蘅的水边高地。蘅音héng）","彩笔新题断肠句：彩笔新题断肠句（彩笔，用江淹「彩笔」典故，指文才）","若问闲情都几许：若问闲情都几许","一川烟草：一川烟草","满城风絮：满城风絮","梅子黄时雨：梅子黄时雨"]
  },
  "燕山亭|赵佶": {
    s: "上片「裁翦冰绡。打叠数重，冷淡燕脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。闲院落凄凉，几番春暮」写杏花的美丽——裁剪冰绡打叠数重冷淡胭脂匀注，新样靓妆艳溢香融羞杀蕊珠宫女；又写杏花的凋零——易得凋零更多少无情风雨，闲院落凄凉几番春暮，以杏花的美丽与凋零比喻自己的命运；下片「凭寄离恨重重。这双燕，何曾会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里、有时会去。无据。和梦也、有时不做」写凭寄离恨重重这双燕何曾会人言语，天遥地远万水千山知他故宫何处，怎不思量除梦里有时会去，无据和梦也有时不做，以「故宫何处」写亡国之痛、以「和梦也有时不做」写绝望——连梦都做不成了，全词意境凄清、比喻巧妙、情感深沉、字字血泪，「怎不思量，除梦里、有时会去。无据。和梦也、有时不做」成为千古名句，是婉约词的千古名篇，王国维评为「以血书者」。",
    b: "赵佶（宋徽宗，北宋末代皇帝）这首《燕山亭》是他被金兵俘虏北行时所作，写杏花与亡国之痛，「怎不思量，除梦里、有时会去。无据。和梦也、有时不做」是千古名句，是婉约词的千古名篇，王国维评为「以血书者」。",
    n: ["燕山亭：词牌名","裁翦冰绡：裁剪冰绡（洁白的薄绸，喻花瓣）。翦同「剪」","打叠数重：打叠数重（叠了几层）","冷淡燕脂匀注：冷淡燕脂（胭脂）匀注（均匀涂抹）。燕同「胭」","新样靓妆：新样靓妆（新颖的妆扮）。靓音jìng","艳溢香融：艳溢香融（艳丽四溢、香气融合）","羞杀蕊珠宫女：羞杀蕊珠宫女（蕊珠宫，道教天上宫殿）","易得凋零：易得凋零","更多少、无情风雨：更多少无情风雨","愁苦：愁苦","闲院落凄凉：闲院落凄凉","几番春暮：几番春暮","凭寄离恨重重：凭寄离恨重重（凭谁寄离恨重重）","这双燕：这双燕","何曾会人言语：何曾会人言语（哪里懂人的言语）","天遥地远：天遥地远","万水千山：万水千山","知他故宫何处：知他故宫何处","怎不思量：怎不思量","除梦里、有时会去：除梦里有时会去","无据：无据（没有凭据）","和梦也、有时不做：和梦也有时不做（连梦也有时不做）"]
  },
  "摸鱼儿|辛弃疾": {
    s: "上片「更能消、几番风雨。匆匆春又归去。惜春长恨花开早，何况落红无数。春且住。见说道、天涯芳草迷归路。怨春不语。算只有殷勤，画檐珠网，尽日惹飞絮」写更能消几番风雨匆匆春又归去，惜春长恨花开早何况落红无数，春且住见说道天涯芳草迷归路，怨春不语算只有殷勤画檐珠网尽日惹飞絮，以暮春景色写对国事的忧虑——春天（国势）经受不住几番风雨；下片「长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉。君莫舞。君不见、玉环飞燕皆尘土。闲愁最苦。休去倚危楼，斜阳正在，烟柳断肠处」写长门事准拟佳期又误蛾眉曾有人妒，千金纵买相如赋脉脉此情谁诉，君莫舞君不见玉环飞燕皆尘土，闲愁最苦休去倚危楼斜阳正在烟柳断肠处，以「长门事」「蛾眉曾有人妒」写自己的不被重用、以「玉环飞燕皆尘土」警告当权者、以「斜阳正在烟柳断肠处」写对国事的忧虑——国势如斜阳西下，全词意境苍凉、用典丰富、寓意深刻、情感深沉，「君莫舞。君不见、玉环飞燕皆尘土」「斜阳正在，烟柳断肠处」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《摸鱼儿》是他任湖北转运副使时所作，写暮春景色与对国事的忧虑，以「玉环飞燕皆尘土」警告当权者，以「斜阳正在烟柳断肠处」写对国事的忧虑，是豪放词的千古名篇，梁启超评为「回肠荡气，至于此极，前无古人，后无来者」。",
    n: ["摸鱼儿：词牌名","更能消、几番风雨：还能经受几番风雨","匆匆春又归去：匆匆春又归去","惜春长恨花开早：惜春长恨花开早","何况落红无数：何况落红无数","春且住：春且住（春天暂且停住）","见说道、天涯芳草迷归路：听说天涯芳草迷归路（春归路被芳草遮住了）","怨春不语：怨春不语","算只有殷勤：算只有殷勤","画檐珠网：画檐珠网（画檐下的蛛网）","尽日惹飞絮：尽日惹飞絮（整天沾惹飞絮）","长门事：长门事（陈皇后被废居长门宫，司马相如作《长门赋》）","准拟佳期又误：准拟佳期又误（约定的佳期又耽误了）","蛾眉曾有人妒：蛾眉曾有人妒（美女曾被人嫉妒，用屈原「众女嫉余之蛾眉兮」）","千金纵买相如赋：千金纵买相如赋（纵然用千金买司马相如的赋）","脉脉此情谁诉：脉脉此情谁诉（含情脉脉此情向谁诉说）","君莫舞：君莫舞（你不要得意）","君不见、玉环飞燕皆尘土：君不见玉环（杨贵妃）飞燕（赵飞燕）皆尘土","闲愁最苦：闲愁最苦","休去倚危楼：休去倚危楼（不要靠高楼）","斜阳正在：斜阳正在","烟柳断肠处：烟柳断肠处"]
  },
  "沁园春|辛弃疾": {
    s: "上片「三径初成。鹤怨猿惊，稼轩未来。甚云山自许，平生意气，衣冠人笑，抵死尘埃。意倦须还，身闲贵早，岂为莼羹鲈鲙哉。秋江上，看惊弦雁避，骇浪船回」写三径初成鹤怨猿惊稼轩未来，甚云山自许平生意气衣冠人笑抵死尘埃，意倦须还身闲贵早岂为莼羹鲈脍哉，秋江上看惊弦雁避骇浪船回，以「三径」「莼羹鲈脍」写归隐之志、以「惊弦雁避骇浪船回」写官场的险恶；下片「东冈更葺茅斋。好都把轩窗临水开。要小舟行钓，先应种柳，疏篱护竹，莫碍观梅。秋菊堪餐，春兰可佩，留待先生手自栽。沈吟久，怕君恩未许，此意徘徊」写东冈更葺茅斋好都把轩窗临水开，要小舟行钓先应种柳疏篱护竹莫碍观梅，秋菊堪餐春兰可佩留待先生手自栽，沈吟久怕君恩未许此意徘徊，以「秋菊堪餐春兰可佩」用屈原典故写高洁、以「怕君恩未许此意徘徊」写归隐与忠君的矛盾，全词用典丰富、意境开阔、情感深沉，「秋菊堪餐，春兰可佩」成为名句。",
    b: "辛弃疾这首《沁园春》是他带湖新居将成时所作，写归隐之志与对君恩的矛盾，「秋菊堪餐，春兰可佩」用屈原典故，是豪放词的名篇。",
    n: ["沁园春：词牌名","三径初成：三径初成（三径，用蒋诩「三径」典故，指归隐后的家园）","鹤怨猿惊：鹤怨猿惊（鹤猿都抱怨惊讶，指归隐）","稼轩未来：稼轩未来（辛弃疾号稼轩，自己还未来）","甚云山自许：甚云山自许（为什么以云山自许）","平生意气：平生意气","衣冠人笑：衣冠人笑（被官场人嘲笑）","抵死尘埃：抵死尘埃（终究在尘世中）","意倦须还：意倦须还（心意疲倦了必须归去）","身闲贵早：身闲贵早（身闲贵在早）","岂为莼羹鲈鲙哉：岂为莼羹鲈鲙哉（难道是为了莼羹鲈脍吗，用张翰「莼羹鲈脍」典故，指归隐）。鲙同「脍」","秋江上：秋江上","看惊弦雁避：看惊弦雁避（惊弓之雁躲避）","骇浪船回：骇浪船回（骇浪中船转回）","东冈更葺茅斋：东冈更葺茅斋（东冈再盖茅屋）。葺音qì，修补","好都把轩窗临水开：好都把轩窗临水开","要小舟行钓：要小舟行钓","先应种柳：先应种柳","疏篱护竹：疏篱护竹","莫碍观梅：莫碍观梅","秋菊堪餐：秋菊堪餐（可以吃，用屈原「夕餐秋菊之落英」）","春兰可佩：春兰可佩（可以佩戴，用屈原「纫秋兰以为佩」）","留待先生手自栽：留待先生手自栽","沈吟久：沈吟久（沉吟久）。沈同「沉」","怕君恩未许：怕君恩未许（怕皇帝不允许）","此意徘徊：此意徘徊（这个心意徘徊不定）"]
  },
  "水龙吟|辛弃疾": {
    s: "上片「楚天千里清秋。水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏干拍遍，无人会、登临意」写楚天千里清秋水随天去秋无际，遥岑远目献愁供恨玉簪螺髻，落日楼头断鸿声里江南游子，把吴钩看了栏干拍遍无人会登临意，以「把吴钩看了栏干拍遍」的动作写壮志难酬的悲愤、以「无人会登临意」写不被理解的孤独；下片「休说鲈鱼堪鲙。尽西风、季鹰归未。求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此。倩何人，唤取盈盈翠袖，揾英雄泪」写休说鲈鱼堪鲙尽西风季鹰归未，求田问舍怕应羞见刘郎才气，可惜流年忧愁风雨树犹如此，倩何人唤取盈盈翠袖揾英雄泪，以「鲈鱼堪鲙」「求田问舍」两个典故写自己不愿归隐、不谋私利，以「树犹如此」写时光流逝，以「揾英雄泪」写壮志难酬的悲愤，全词意境苍凉、用典丰富、动作生动、情感深沉，「把吴钩看了，栏干拍遍，无人会、登临意」「倩何人，唤取盈盈翠袖，揾英雄泪」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《水龙吟》是他任建康通判时所作，写登临建康赏心亭所见与壮志难酬的悲愤，「把吴钩看了，栏干拍遍，无人会、登临意」「倩何人，唤取盈盈翠袖，揾英雄泪」是千古名句，是豪放词的千古名篇。",
    n: ["水龙吟：词牌名","楚天千里清秋：楚天千里清秋","水随天去秋无际：水随天去秋无际","遥岑远目：遥岑远目（眺望远山）。岑音cén，小山","献愁供恨：献愁供恨（远山好像在献愁供恨）","玉簪螺髻：玉簪螺髻（像玉簪和螺髻，比喻山的形状）。髻音jì","落日楼头：落日楼头","断鸿声里：断鸿声里（孤雁的叫声里）","江南游子：江南游子（辛弃疾自指，他是北方人，流落江南）","把吴钩看了：把吴钩看了（吴钩，古代吴地出产的弯刀，代指武器）","栏干拍遍：栏干拍遍","无人会、登临意：无人会登临意（没有人理解登临的心意）","休说鲈鱼堪鲙：休说鲈鱼堪鲙（不要说鲈鱼可以做脍，用张翰「莼羹鲈脍」典故，指归隐）。鲙同「脍」","尽西风、季鹰归未：尽西风季鹰归未（西风吹尽了，张翰（字季鹰）回来了没有）","求田问舍：求田问舍（买田置屋，用许汜典故，指只顾个人利益）","怕应羞见：怕应羞见","刘郎才气：刘郎才气（刘备的才气，指有大志的人）","可惜流年：可惜流年（可惜时光流逝）","忧愁风雨：忧愁风雨（忧愁国家的风雨飘摇）","树犹如此：树犹如此（用桓温「木犹如此，人何以堪」典故，指时光流逝）","倩何人：倩何人（请什么人）。倩音qìng，请","唤取盈盈翠袖：唤取盈盈翠袖（唤取美丽的女子，翠袖代指女子）","揾英雄泪：揾英雄泪（擦英雄的眼泪）。揾音wèn，擦"]
  },
  "临江仙|辛弃疾": {
    s: "上片「老去惜花心已懒。爱梅犹绕江村。一枝先破玉溪春。更无花态度，全有雪精神」写老去惜花心已懒爱梅犹绕江村，一枝先破玉溪春，更无花态度全有雪精神，以「更无花态度全有雪精神」写梅花的高洁——没有花的媚态，全有雪的精神；下片「剩向空山餐秀色。为渠著句清新。竹根流水带溪云。醉中浑不记，归路月黄昏」写剩向空山餐秀色为渠著句清新，竹根流水带溪云，醉中浑不记归路月黄昏，以「醉中浑不记归路月黄昏」写赏梅的沉醉，全词意境清丽、品格高洁、情感深沉，「更无花态度，全有雪精神」成为名句。",
    b: "辛弃疾这首《临江仙》写梅花的品格，「更无花态度，全有雪精神」是名句，是辛弃疾婉约词的名篇。",
    n: ["临江仙：词牌名","老去惜花心已懒：老去惜花心已懒","爱梅犹绕江村：爱梅犹绕江村","一枝先破玉溪春：一枝先破玉溪春（玉溪的春天先被一枝梅花打破）","更无花态度：更无花态度（没有花的媚态）","全有雪精神：全有雪精神（全有雪的精神）","剩向空山餐秀色：剩向空山餐秀色（只向空山欣赏秀色）","为渠著句清新：为渠著句清新（为它写清新的诗句。渠，它）","竹根流水带溪云：竹根流水带溪云","醉中浑不记：醉中浑不记（醉中全不记得）","归路月黄昏：归路月黄昏"]
  },
  "菩萨蛮|辛弃疾": {
    s: "上片「郁孤台下清江水。中间多少行人泪。西北是长安。可怜无数山」写郁孤台下清江水中间多少行人泪，西北是长安可怜无数山，以「行人泪」写中原沦陷的痛苦、以「可怜无数山」写视线被山遮住、望不到中原；下片「青山遮不住。毕竟江流去。江晚正愁予。山深闻鹧鸪」写青山遮不住毕竟江流去，江晚正愁予山深闻鹧鸪，以「青山遮不住毕竟东流去」写恢复中原的愿望不可阻挡、以「闻鹧鸪」暗指恢复之事行不得的矛盾，全词意境苍凉、比喻巧妙、情感深沉、寓意深刻，「青山遮不住，毕竟东流去」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《菩萨蛮》是他任江西提点刑狱时路过造口所作，写对中原的思念与恢复中原的愿望，「青山遮不住，毕竟东流去」是千古名句，是豪放词的千古名篇。",
    n: ["菩萨蛮：词牌名","郁孤台下清江水：郁孤台下清江水（郁孤台，在今江西赣州）","中间多少行人泪：中间多少行人泪","西北是长安：西北是长安（长安，代指北宋都城汴京，指中原）","可怜无数山：可怜无数山（可惜被无数山遮住）","青山遮不住：青山遮不住","毕竟江流去：毕竟江流去（毕竟江水向东流去）","江晚正愁予：江晚正愁予（江边傍晚正使我忧愁。予，我）","山深闻鹧鸪：山深闻鹧鸪（山深听到鹧鸪叫，鹧鸪叫声似「行不得也哥哥」，暗指恢复中原之事行不得）"]
  },
  "青玉案|辛弃疾": {
    s: "上片「东风夜放花千树。更吹落、星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞」写东风夜放花千树更吹落星如雨，宝马雕车香满路，凤箫声动玉壶光转一夜鱼龙舞，以夸张的手法写元宵节的盛况——花灯如千树花开、烟花如星雨、宝马雕车、凤箫玉壶、鱼龙百舞；下片「蛾儿雪柳黄金缕。笑语盈盈暗香去。众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」写蛾儿雪柳黄金缕笑语盈盈暗香去，众里寻他千百度蓦然回首那人却在灯火阑珊处，以「众里寻他千百度」写追寻的执着、以「蓦然回首那人却在灯火阑珊处」写发现的惊喜——在灯火稀疏的地方找到了意中人，全词意境开阔、夸张巧妙、情感深沉、哲理深刻，「众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」成为千古名句，王国维列为人生三境界之第三境界（最高境界），是豪放词的千古名篇。",
    b: "辛弃疾这首《青玉案》写元宵节的盛况与对意中人的追寻，「众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」是千古名句，王国维在《人间词话》中将其列为「古今之成大事业、大学问者」的第三境界（最高境界），是豪放词的千古名篇。",
    n: ["青玉案：词牌名","东风夜放花千树：东风夜放花千树（东风夜里吹放了千树花，指花灯）","更吹落、星如雨：更吹落星如雨（更吹落星星如雨，指烟花）","宝马雕车香满路：宝马雕车香满路","凤箫声动：凤箫声动（箫声响起）","玉壶光转：玉壶光转（玉壶般的月亮光影移动，或指白玉灯）","一夜鱼龙舞：一夜鱼龙舞（鱼龙灯舞动，指百戏）","蛾儿雪柳黄金缕：蛾儿雪柳黄金缕（元宵节妇女的饰物）","笑语盈盈暗香去：笑语盈盈暗香去（笑语盈盈、带着暗香离去）","众里寻他千百度：众里寻他千百度（在人群里找了她千百次）","蓦然回首：蓦然回首（忽然回头）","那人却在：那人却在","灯火阑珊处：灯火阑珊处（灯火稀疏的地方。阑珊，稀疏、将尽）"]
  },
  "阮郎归|辛弃疾": {
    s: "上片「山前风雨欲黄昏。山头来去雪。鹧鸪声里数家村。潇湘逢故人」写山前风雨欲黄昏山头来去雪，鹧鸪声里数家村潇湘逢故人，以潇湘的风雨鹧鸪写环境的荒凉；下片「挥羽扇。整纶巾。少年鞍马尘。如今憔悴赋招魂。儒冠多误身」写挥羽扇整纶巾少年鞍马尘，如今憔悴赋招魂儒冠多误身，以「挥羽扇整纶巾」用诸葛亮典故写少年的英雄气概、以「如今憔悴赋招魂儒冠多误身」写如今的憔悴与失意——儒生的帽子多误了自身，用杜甫典故，全词今昔对比、用典贴切、情感深沉，「如今憔悴赋招魂。儒冠多误身」成为名句。",
    b: "辛弃疾这首《阮郎归》写在潇湘遇到老朋友，回忆少年的鞍马生活与如今的憔悴，「儒冠多误身」用杜甫典故，是豪放词的名篇。",
    n: ["阮郎归：词牌名","山前风雨欲黄昏：山前风雨欲黄昏","山头来去雪：山头来去雪（山头雪来来去去）","鹧鸪声里数家村：鹧鸪声里数家村（鹧鸪声里有几个村庄）","潇湘逢故人：潇湘逢故人（在潇湘遇到老朋友）","挥羽扇：挥羽扇（挥羽扇，用诸葛亮「羽扇纶巾」典故）","整纶巾：整纶巾（整理纶巾。纶巾，青丝带头巾，诸葛亮所戴。纶音guān）","少年鞍马尘：少年鞍马尘（少年时在鞍马风尘中）","如今憔悴赋招魂：如今憔悴赋招魂（如今憔悴，赋《招魂》（屈原作品，指招回魂魄））","儒冠多误身：儒冠多误身（儒生的帽子多误了自身，用杜甫「纨绔不饿死，儒冠多误身」）"]
  },
  "清平乐|辛弃疾": {
    s: "上片「茅檐低小。溪上青青草。醉里蛮音相媚好。白发谁家翁媪」写茅檐低小溪上青青草，醉里蛮音相媚好白发谁家翁媪，以茅檐、青草、翁媪写农村环境的清幽与老夫妻的温馨；下片「大儿锄豆溪东。中儿正织鸡笼。最喜小儿亡赖。溪头卧剥莲蓬」写大儿锄豆溪东中儿正织鸡笼，最喜小儿亡赖溪头卧剥莲蓬，以三个儿子的不同活动写农村生活的生动——大儿子勤劳、二儿子手巧、小儿子顽皮，全词意境清新、语言朴素、细节生动、情感真挚，「最喜小儿亡赖，溪头卧剥莲蓬」成为千古名句，是宋词中最著名的农村词，是婉约词的千古名篇。",
    b: "辛弃疾这首《清平乐》写江西上饶农村的一个五口之家的生活，是宋词中最著名的农村词，「最喜小儿亡赖，溪头卧剥莲蓬」是千古名句，是婉约词的千古名篇。",
    n: ["清平乐：词牌名","茅檐低小：茅檐低小（茅屋的屋檐又低又小）","溪上青青草：溪上青青草","醉里蛮音相媚好：醉里蛮音相媚好（醉里用吴地方言互相逗趣。蛮音，库文作「蛮音」，通行本作「吴音」）","白发谁家翁媪：白发谁家翁媪（谁家的白发老翁老妇。媪音ǎo，老妇）","大儿锄豆溪东：大儿锄豆溪东（大儿子在溪东锄豆田）","中儿正织鸡笼：中儿正织鸡笼（二儿子正在织鸡笼）","最喜小儿亡赖：最喜小儿亡赖（最喜爱小儿子的顽皮。亡赖同「无赖」，此指顽皮可爱）","溪头卧剥莲蓬：溪头卧剥莲蓬（在溪头躺着剥莲蓬）"]
  },
  "最高楼|辛弃疾": {
    s: "上片「吾衰矣。须富贵何时。富贵是危机。暂忘设醴抽身去，未曾得米弃官归。穆先生。陶县令。是吾师」写吾衰矣须富贵何时富贵是危机，暂忘设醴抽身去未曾得米弃官归，穆先生陶县令是吾师，以「富贵是危机」写对富贵的蔑视、以穆生和陶渊明两个典故写归隐之志；下片「待葺个、园儿名佚老。更作个、亭儿名亦好。闲饮酒，醉吟诗。千年田换八百主，一人口插几张匙。休休休，更说甚，是和非」写待葺个园儿名佚老更作个亭儿名亦好，闲饮酒醉吟诗，千年田换八百主一人口插几张匙，休休休更说甚是和非，以「千年田换八百主一人口插几张匙」写世事无常、贪多无益，以「休休休更说甚是和非」写归隐后的旷达，全词用典丰富、语言明快、哲理深刻、情感旷达，「千年田换八百主，一人口插几张匙」成为名句。",
    b: "辛弃疾这首《最高楼》是他被弹劾罢官、归隐瓢泉时所作，写归隐之志与对富贵的蔑视，「千年田换八百主，一人口插几张匙」是名句，是豪放词的名篇。",
    n: ["最高楼：词牌名","吾衰矣：吾衰矣（我衰老了，用孔子「甚矣吾衰也」）","须富贵何时：须富贵何时（要富贵到什么时候呢，用杨恽「人生行乐耳，须富贵何时」）","富贵是危机：富贵是危机（富贵是危机四伏的）","暂忘设醴抽身去：暂忘设醴抽身去（暂时忘记设醴（酒）抽身离去，用楚元王与穆生典故——穆生因楚王忘设醴而知其怠，抽身离去）。醴音lǐ，甜酒","未曾得米弃官归：未曾得米弃官归（未曾得到米就弃官归去，用陶渊明「不为五斗米折腰」典故）","穆先生：穆先生（穆生）","陶县令：陶县令（陶渊明，曾任彭泽令）","是吾师：是吾师","待葺个、园儿名佚老：待葺个园儿名佚老（待修个园子名叫佚老。葺音qì，修补；佚老，安乐养老）","更作个、亭儿名亦好：更作个亭儿名亦好（再建个亭子名叫亦好）","闲饮酒：闲饮酒","醉吟诗：醉吟诗","千年田换八百主：千年田换八百主（千年的田地换了八百个主人，指世事无常）","一人口插几张匙：一人口插几张匙（一张嘴插几把匙，指贪多无益）","休休休：休休休（算了吧）","更说甚：更说甚（还说什么呢）","是和非：是和非（是与非）"]
  },
  "鹧鸪天|辛弃疾": {
    s: "上片「陌上柔条初破芽。东邻蚕种已生些。平冈细草鸣黄犊，斜日寒林点暮鸦」写陌上柔条初破芽东邻蚕种已生些，平冈细草鸣黄犊斜日寒林点暮鸦，以柔条、蚕种、黄犊、暮鸦写农村初春的生机；下片「山远近。路横斜。青旗沽酒有人家。城中桃李愁风雨，春在溪头野荠花」写山远近路横斜青旗沽酒有人家，城中桃李愁风雨春在溪头野荠花，以「城中桃李愁风雨春在溪头野荠花」的对比写——城中的桃李虽娇贵却忧愁风雨，而溪头的野荠花虽平凡却充满春意，以平凡的野花写春天的真正所在，全词意境清新、对比鲜明、哲理深刻、情感真挚，「城中桃李愁风雨，春在溪头野荠花」成为千古名句，是婉约词的千古名篇。",
    b: "辛弃疾这首《鹧鸪天》写农村的初春景色，「城中桃李愁风雨，春在溪头野荠花」是千古名句，以城中桃李与溪头野荠对比，是婉约词的千古名篇。",
    n: ["鹧鸪天：词牌名","陌上柔条初破芽：陌上柔条初破芽（田间小路上柔嫩的枝条刚发芽。库文作「柔条」，通行本作「柔桑」；库文作「初破芽」，通行本作「破嫩芽」）","东邻蚕种已生些：东邻蚕种已生些（东邻的蚕种已经孵化了一些。些音suō，句末语气词）","平冈细草鸣黄犊：平冈细草鸣黄犊（平缓的山冈上细草中黄牛犊在叫。犊音dú，小牛）","斜日寒林点暮鸦：斜日寒林点暮鸦（斜日寒林中点缀着暮鸦）","山远近：山远近（山有远有近）","路横斜：路横斜（路有横有斜）","青旗沽酒有人家：青旗沽酒有人家（青旗卖酒的地方有人家）","城中桃李愁风雨：城中桃李愁风雨（城中的桃李忧愁风雨）","春在溪头野荠花：春在溪头野荠花（春天在溪头的野荠花中。库文作「野荠花」，通行本作「荠菜花」）"]
  },
  "贺新郎|辛弃疾": {
    s: "上片「甚矣吾衰矣。怅平生、交游零落，只今余几。白发空垂三千丈，一笑人间万事。问何物、能令公喜。我见青山多妩媚，料青山、见我应如是。情与貌，略相似」写甚矣吾衰矣怅平生交游零落只今余几，白发空垂三千丈一笑人间万事，问何物能令公喜，我见青山多妩媚料青山见我应如是情与貌略相似，以「我见青山多妩媚料青山见我应如是」写对青山的喜爱与物我两忘；下片「一尊搔首东窗里。想渊明、停云诗就，此时风味。江左沈酣求名者，岂识浊醪妙理。回首叫、云飞风起。不恨古人吾不见，恨古人、不见吾狂耳。知我者，二三子」写一尊搔首东窗里想渊明停云诗就此时风味，江左沈酣求名者岂识浊醪妙理，回首叫云飞风起，不恨古人吾不见恨古人不见吾狂耳，知我者二三子，以陶渊明《停云》写思友、以「浊醪妙理」写饮酒的妙处、以「不恨古人吾不见恨古人不见吾狂耳」写狂放的人生态度，全词用典丰富、意境开阔、狂放不羁、情感深沉，「我见青山多妩媚，料青山、见我应如是」「不恨古人吾不见，恨古人、不见吾狂耳」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《贺新郎》是他归隐瓢泉时所作，写对青山的喜爱与狂放的人生态度，「我见青山多妩媚，料青山、见我应如是」「不恨古人吾不见，恨古人、不见吾狂耳」是千古名句，是豪放词的千古名篇。",
    n: ["贺新郎：词牌名","甚矣吾衰矣：甚矣吾衰矣（我衰老得太厉害了，用孔子「甚矣吾衰也」）","怅平生、交游零落：怅平生交游零落（惆怅平生交游零落）","只今余几：只今余几（如今还剩几个）","白发空垂三千丈：白发空垂三千丈（白发空垂了三千丈，用李白「白发三千丈」）","一笑人间万事：一笑人间万事（对人间万事一笑置之）","问何物、能令公喜：问何物能令公喜（问什么东西能让您高兴呢，用「能令公喜」典故）","我见青山多妩媚：我见青山多妩媚（我看青山多妩媚。妩媚，姿态美好）","料青山、见我应如是：料青山见我应如是（料想青山看我也应该是这样）","情与貌：情与貌（情感与外貌）","略相似：略相似（大略相似）","一尊搔首东窗里：一尊搔首东窗里（一杯酒搔首在东窗里）","想渊明、停云诗就：想渊明停云诗就（想陶渊明《停云》诗写成。《停云》，陶渊明作品，思亲友）","此时风味：此时风味（这时的风味）","江左沈酣求名者：江左沈酣求名者（江东那些沉湎于求名的人。沈同「沉」）","岂识浊醪妙理：岂识浊醪妙理（哪里懂得浊酒的妙理。醪音láo，浊酒）","回首叫、云飞风起：回首叫云飞风起（回首大叫云飞风起，用刘邦「大风起兮云飞扬」）","不恨古人吾不见：不恨古人吾不见（不恨古人我见不到）","恨古人、不见吾狂耳：恨古人不见吾狂耳（恨古人见不到我的狂放）","知我者：知我者（了解我的人）","二三子：二三子（两三个，用孔子「二三子」典故，指少数朋友）"]
  },
  "粉蝶儿|辛弃疾": {
    s: "上片「昨日春如，十三女儿学绣。一枝枝、不教花瘦。甚无情，便下得，雨僝风僽。向园林、铺作地衣红绉」写昨日春如十三女儿学绣一枝枝不教花瘦，甚无情便下得雨僝风僽向园林铺作地衣红绉，以「十三女儿学绣」比喻春的繁盛——像十三岁女儿学刺绣一样，一枝枝都绣得饱满；下片「而今春似，轻薄荡子难久。记前时、送春归后。把春波，都酿作，一江春酎。约清愁、杨柳岸边相候」写而今春似轻薄荡子难久记前时送春归后，把春波都酿作一江春酎约清愁杨柳岸边相候，以「轻薄荡子难久」比喻春的短暂——像轻薄的浪子一样难以长久，全词比喻新奇、语言明快、情感深沉，「昨日春如，十三女儿学绣」「而今春似轻薄荡子难久」成为名句。",
    b: "辛弃疾这首《粉蝶儿》写春天的来去，以「昨日春如十三女儿学绣」「而今春似轻薄荡子难久」两个新奇的比喻写春的盛与衰，是婉约词的名篇。",
    n: ["粉蝶儿：词牌名","昨日春如：昨日春如（昨天春天像）","十三女儿学绣：十三女儿学绣（十三岁的女儿学刺绣）","一枝枝、不教花瘦：一枝枝不教花瘦（一枝枝都不让花瘦，指花开得饱满）","甚无情：甚无情（太无情了）","便下得：便下得（就忍心）","雨僝风僽：雨僝风僽（雨折磨风折磨。僝僽音chánzhòu，折磨）","向园林、铺作地衣红绉：向园林铺作地衣红绉（在园林里铺成红色绉纹的地毯。绉音zhòu，绉纹）","而今春似：而今春似（如今春天像）","轻薄荡子难久：轻薄荡子难久（轻薄的浪子难以长久）","记前时、送春归后：记前时送春归后（记得以前送春归去后）","把春波：把春波（把春天的水波）","都酿作：都酿作（都酿成）","一江春酎：一江春酎（一江春酒。酎音zhòu，醇酒）","约清愁、杨柳岸边相候：约清愁杨柳岸边相候（约清愁在杨柳岸边相候）"]
  },
  "汉宫春|辛弃疾": {
    s: "上片「春已归来。看美人头上，袅袅春幡。无端风雨，未肯收尽余寒。年时燕子，料今宵、梦到西园。浑未办、黄柑荐酒，更传青韭堆盘」写春已归来看美人头上袅袅春幡，无端风雨未肯收尽余寒，年时燕子料今宵梦到西园，浑未办黄柑荐酒更传青韭堆盘，以立春的习俗写春的归来；下片「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人、会解连环。生怕见、花开花落，朝来塞雁先还」写却笑东风从此便薰梅染柳更没些闲，闲时又来镜里转变朱颜，清愁不断问何人会解连环，生怕见花开花落朝来塞雁先还，以「东风薰梅染柳」写春的忙碌、以「镜里转变朱颜」写时光流逝使人衰老、以「解连环」写愁的难解、以「塞雁先还」写自己不能归，全词用典丰富、意境清丽、情感深沉，「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜」成为名句。",
    b: "辛弃疾这首《汉宫春》写立春的景色与对时光流逝的感慨，「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜」是名句，是婉约词的名篇。",
    n: ["汉宫春：词牌名","春已归来：春已归来","看美人头上：看美人头上","袅袅春幡：袅袅春幡（美人头上戴着袅袅的春幡。春幡，立春时戴的彩幡）","无端风雨：无端风雨（无缘无故的风雨）","未肯收尽余寒：未肯收尽余寒（不肯收尽残余的寒气）","年时燕子：年时燕子（去年的燕子）","料今宵、梦到西园：料今宵梦到西园（料想今晚梦到西园）","浑未办、黄柑荐酒：浑未办黄柑荐酒（全没准备黄柑荐酒。黄柑荐酒，立春时的习俗）","更传青韭堆盘：更传青韭堆盘（更传上青韭堆盘。青韭堆盘，立春时的习俗）","却笑东风从此：却笑东风从此（却笑东风从此）","便薰梅染柳：便薰梅染柳（就熏梅染柳，使梅香柳绿）","更没些闲：更没些闲（更没有一点空闲）","闲时又来镜里：闲时又来镜里（空闲时又来到镜里）","转变朱颜：转变朱颜（改变红润的容颜，指使人衰老）","清愁不断：清愁不断","问何人、会解连环：问何人会解连环（问什么人能解连环，用「解连环」典故，指难解的愁）","生怕见、花开花落：生怕见花开花落（生怕看见花开花落）","朝来塞雁先还：朝来塞雁先还（早晨塞雁先回来了）"]
  },
  "太常引|辛弃疾": {
    s: "上片「一轮秋影转金波。飞镜又重磨。把酒问姮娥。被白发、欺人奈何」写一轮秋影转金波飞镜又重磨，把酒问姮娥被白发欺人奈何，以「把酒问姮娥被白发欺人奈何」写对时光流逝的感慨；下片「乘风好去。长空万里。直下看山河。斫去桂婆娑。人道是、清光更多」写乘风好去长空万里直下看山河，斫去桂婆娑人道是清光更多，以「乘风好去长空万里直下看山河」写对祖国山河的热爱、以「斫去桂婆娑清光更多」用杜甫典故暗指要扫除朝廷中的奸邪、使国家政治清明，全词想象奇特、用典贴切、意境开阔、寓意深刻，「斫去桂婆娑，人道是、清光更多」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《太常引》是他中秋夜所作，写对月的遐想与对国事的忧虑，「斫去桂婆娑，人道是、清光更多」用杜甫典故，暗指要扫除朝廷中的奸邪，是豪放词的千古名篇。",
    n: ["太常引：词牌名","一轮秋影转金波：一轮秋影转金波（一轮秋月的影子转动着金色的光波）","飞镜又重磨：飞镜又重磨（飞镜（月亮）又重新磨过）","把酒问姮娥：把酒问姮娥（拿着酒问嫦娥。姮娥音héng'é，嫦娥）","被白发、欺人奈何：被白发欺人奈何（被白发欺负人怎么办呢）","乘风好去：乘风好去（乘风好去）","长空万里：长空万里","直下看山河：直下看山河（直下看山河）","斫去桂婆娑：斫去桂婆娑（砍去婆娑的桂树。斫音zhuó，砍；婆娑，枝叶扶疏的样子）","人道是、清光更多：人道是清光更多（人们说这样清光更多。用杜甫「斫却月中桂，清光应更多」）"]
  },
  "祝英台近|辛弃疾": {
    s: "上片「水纵横。山远近。拄杖占千顷。老眼羞将，水底看山影。试教水动山摇，吾生堪笑，似此个、青山无定」写水纵横山远近拄杖占千顷，老眼羞将水底看山影，试教水动山摇吾生堪笑似此个青山无定，以「水动山摇」写山水的变幻、以「青山无定」比喻人生的无定；下片「一瓢饮。人问翁爱飞泉，来寻个中静。绕屋生喧，怎做静中境。我眠君且归休。维摩方丈，待天女、散花时问」写一瓢饮人问翁爱飞泉来寻个中静，绕屋生喧怎做静中境，我眠君且归休维摩方丈待天女散花时问，以「一瓢饮」用颜回典故写安贫乐道、以「维摩方丈天女散花」用佛典写禅意，全词用典丰富、意境清幽、哲理深刻、情感旷达，「我眠君且归休。维摩方丈，待天女、散花时问」成为名句。",
    b: "辛弃疾这首《祝英台近》写归隐后的山水之乐与对静的追求，用颜回、维摩诘典故，是婉约词的名篇。",
    n: ["祝英台近：词牌名","水纵横：水纵横","山远近：山远近","拄杖占千顷：拄杖占千顷（拄杖占据千顷山水）","老眼羞将：老眼羞将（老眼羞于将）","水底看山影：水底看山影（在水底看山影）","试教水动山摇：试教水动山摇（试让水动山摇）","吾生堪笑：吾生堪笑（我的一生可笑）","似此个、青山无定：似此个青山无定（像这个青山一样无定）","一瓢饮：一瓢饮（一瓢水的饮食，用颜回「一箪食一瓢饮」典故，指安贫乐道）","人问翁爱飞泉：人问翁爱飞泉（人问老翁为什么喜爱飞泉）","来寻个中静：来寻个中静（来寻找其中的静）","绕屋生喧：绕屋生喧（绕屋生出喧闹）","怎做静中境：怎做静中境（怎么能做到静中的境界呢）","我眠君且归休：我眠君且归休（我睡了您暂且回去休息吧）","维摩方丈：维摩方丈（维摩诘的方丈室，用维摩诘「方丈」典故，指小室）","待天女、散花时问：待天女散花时问（等天女散花时再问。天女散花，维摩诘经中天女散花考验菩萨）"]
  },
  "踏莎行|辛弃疾": {
    s: "上片「夜月楼台，秋香院宇。笑吟吟地人来去。是谁秋到便凄凉，当年宋玉悲如许」写夜月楼台秋香院宇，笑吟吟地人来去，是谁秋到便凄凉当年宋玉悲如许，以宋玉悲秋的典故写秋日的凄凉；下片「随分杯盘，等闲歌舞。问他有甚堪悲处。思量却也有悲时，重阳节近多风雨」写随分杯盘等闲歌舞，问他有甚堪悲处，思量却也有悲时重阳节近多风雨，以「重阳节近多风雨」暗喻国事的风雨飘摇——表面写重阳近了多风雨，实则写国家命运的风雨飘摇，全词意境清丽、用典贴切、寓意深刻，「思量却也有悲时，重阳节近多风雨」成为名句。",
    b: "辛弃疾这首《踏莎行》写秋日的感慨，以「重阳节近多风雨」暗喻国事的风雨飘摇，是婉约词中寓含悲愤的名篇。",
    n: ["踏莎行：词牌名","夜月楼台：夜月楼台","秋香院宇：秋香院宇","笑吟吟地人来去：笑吟吟地人来去","是谁秋到便凄凉：是谁秋到便凄凉","当年宋玉悲如许：当年宋玉悲如许（宋玉，战国楚辞赋家，作《九辩》悲秋）","随分杯盘：随分杯盘（随分，随便）","等闲歌舞：等闲歌舞（等闲，平常）","问他有甚堪悲处：问他有甚堪悲处","思量却也有悲时：思量却也有悲时","重阳节近多风雨：重阳节近多风雨"]
  },
  "南乡子|辛弃疾": {
    s: "上片「何处望神州。满眼风光北固楼。千古兴亡多少事，悠悠。不尽长江衮衮流」写何处望神州满眼风光北固楼，千古兴亡多少事悠悠不尽长江衮衮流，以长江滚滚东流写千古兴亡的感慨；下片「年少万兜鍪。坐断东南战未休。天下英雄谁敌手。曹刘。生子当如孙仲谋」写年少万兜鍪坐断东南战未休，天下英雄谁敌手曹刘，生子当如孙仲谋，以孙权年少时统率大军、占据东南、征战不休的英雄气概，讽刺南宋朝廷的苟且偷安——「生子当如孙仲谋」用曹操的话，既是对孙权的赞美，也是对南宋统治者的鞭挞，全词意境壮阔、用典贴切、借古讽今、情感豪迈，「生子当如孙仲谋」成为千古名句，是豪放词的千古名篇。",
    b: "辛弃疾这首《南乡子》是他任镇江知府时登北固亭所作，借古讽今，以孙权的英雄气概讽刺南宋朝廷的苟且偷安，「生子当如孙仲谋」是千古名句，是豪放词的千古名篇。",
    n: ["南乡子：词牌名","何处望神州：何处望神州（神州，中原）","满眼风光北固楼：满眼风光北固楼（北固楼，在今江苏镇江北固山）","千古兴亡多少事：千古兴亡多少事","悠悠：悠悠（漫长无尽）","不尽长江衮衮流：不尽长江衮衮流（衮衮，滚滚，连续不断）","年少万兜鍪：年少万兜鍪（兜鍪，头盔，代指士兵。指孙权年少时统率大军。鍪音móu）","坐断东南战未休：坐断东南战未休（坐断，占据）","天下英雄谁敌手：天下英雄谁敌手","曹刘：曹刘（曹操、刘备）","生子当如孙仲谋：生子当如孙仲谋（孙仲谋，孙权字仲谋。用曹操「生子当如孙仲谋」语）"]
  },
  "诉衷情|陆游": {
    s: "上片「当年万里觅封侯。匹马戍梁州。关河梦断何处，尘暗旧貂裘」写当年万里觅封侯匹马戍梁州，关河梦断何处尘暗旧貂裘，以「当年」与「如今」对比——当年万里从军、匹马戍梁州，如今关河梦断、貂裘尘暗，写壮志未酬的悲愤；下片「胡未灭，鬓先秋。泪空流。此生谁料，心在天山，身老沧洲」写胡未灭鬓先秋泪空流，此生谁料心在天山身老沧洲，以「胡未灭」与「鬓先秋」对比、以「心在天山」与「身老沧洲」对比，写抗金壮志与年老归隐的矛盾——心还在前线，身却已老于沧洲，全词对比鲜明、情感深沉、悲愤激昂，「心在天山，身老沧洲」成为千古名句，是豪放词的千古名篇。",
    b: "陆游这首《诉衷情》是他晚年隐居山阴时所作，回忆当年从军梁州的壮志，抒发壮志未酬、身老沧洲的悲愤，「心在天山，身老沧洲」是千古名句，是豪放词的千古名篇。",
    n: ["诉衷情：词牌名","当年万里觅封侯：当年万里觅封侯（觅封侯，寻求封侯建功）","匹马戍梁州：匹马戍梁州（梁州，今陕西汉中一带，陆游曾在此从军）","关河梦断何处：关河梦断何处（关河，关塞山河；梦断，梦醒）","尘暗旧貂裘：尘暗旧貂裘（貂裘积满灰尘变暗，用苏秦「黑貂之裘弊」典故，指壮志未酬）","胡未灭：胡未灭（金人未灭）","鬓先秋：鬓先秋（鬓发先秋，指鬓发已白）","泪空流：泪空流","此生谁料：此生谁料","心在天山：心在天山（天山，在今新疆，代指西北边疆，指抗金前线）","身老沧洲：身老沧洲（沧洲，水边之地，指隐居之地。陆游晚年隐居绍兴镜湖）"]
  },
  "临安春雨初霁|陆游": {
    s: "首联「世味年来薄似纱，谁令骑马客京华」写世味年来薄似纱、谁令骑马客京华，以「世味薄似纱」写对世态人情的失望、以「谁令骑马客京华」写客居京城的无奈；颔联「小楼一夜听春雨，深巷明朝卖杏花」是千古名句——小楼一夜听春雨，深巷明朝卖杏花，以「一夜听春雨」写失眠、以「明朝卖杏花」写春意，意境清丽、对仗工稳；颈联「矮纸斜行闲作草，晴窗细乳戏分茶」写矮纸斜行闲作草、晴窗细乳戏分茶，以「闲作草」「戏分茶」写客居的无聊与消磨；尾联「素衣莫起风尘叹，犹及清明可到家」写素衣莫起风尘叹、犹及清明可到家，以「莫起风尘叹」自我宽慰、以「清明可到家」写对归家的期盼，全诗意境清丽、对仗工稳、情感深沉，「小楼一夜听春雨，深巷明朝卖杏花」成为千古名句，是七律的千古名篇。",
    b: "陆游这首《临安春雨初霁》是他被召入京、等待任命时所作，写临安春雨初晴的景色与客居的无聊，「小楼一夜听春雨，深巷明朝卖杏花」是千古名句，是七律的千古名篇。",
    n: ["临安春雨初霁：诗题，临安，今杭州；霁，雨停","世味年来薄似纱：世味年来薄似纱（世味，世态人情）","谁令骑马客京华：谁令骑马客京华（京华，京城，指临安）","小楼一夜听春雨：小楼一夜听春雨","深巷明朝卖杏花：深巷明朝卖杏花","矮纸斜行闲作草：矮纸斜行闲作草（矮纸，短纸；作草，写草书）","晴窗细乳戏分茶：晴窗细乳戏分茶（细乳，煎茶时浮起的白色泡沫；分茶，宋代品茶的一种技艺）","素衣莫起风尘叹：素衣莫起风尘叹（素衣，白衣，用陆机「京洛多风尘，素衣化为缁」典故，指不要感叹京城的风尘玷污了素衣）","犹及清明可到家：犹及清明可到家（还赶得上清明时节到家）"]
  },
  "冬夜读书示子聿|陆游": {
    s: "首两句「古人学问无遗力，少壮工夫老始成」写古人做学问不遗余力、少壮时下功夫到老才能有所成就，强调做学问要刻苦努力、坚持不懈；后两句「纸上得来终觉浅，绝知此事要躬行」是千古名句——从书本上得来的知识终究觉得浅薄，要彻底明白这件事必须亲身实践，强调实践的重要性——书本知识是间接经验，只有亲身实践才能真正理解，全诗语言朴素、哲理深刻、对仗工稳，「纸上得来终觉浅，绝知此事要躬行」成为千古名句，是劝学诗的千古名篇。",
    b: "陆游这首《冬夜读书示子聿》是他冬夜读书时写给儿子子聿的劝学诗，「纸上得来终觉浅，绝知此事要躬行」是千古名句，强调实践的重要性，是七绝的千古名篇。",
    n: ["冬夜读书示子聿：诗题，子聿，陆游的小儿子","古人学问无遗力：古人学问无遗力（无遗力，不遗余力）","少壮工夫老始成：少壮工夫老始成（少壮时下功夫，到老才能有所成就）","纸上得来终觉浅：纸上得来终觉浅（从书本上得来的知识终究觉得浅薄）","绝知此事要躬行：绝知此事要躬行（要彻底明白这件事必须亲身实践。躬行，亲身实践）"]
  },
  "关山月|陆游": {
    s: "全诗分三层：第一层「和戎诏下十五年，将军不战空临边。朱门沉沉按歌舞，厩马肥死弓断弦」写和戎诏下十五年将军不战空临边，朱门沉沉按歌舞厩马肥死弓断弦，以「将军不战」「朱门歌舞」「马肥死弓断弦」揭露议和投降的罪恶——将军不战、权贵享乐、军备废弛；第二层「戍楼刁斗催落月，三十从军今白发。笛里谁知壮士心，沙头空照征人骨」写戍楼刁斗催落月三十从军今白发，笛里谁知壮士心沙头空照征人骨，以「三十从军今白发」「壮士心」「征人骨」写将士的悲愤——从军多年、壮志未酬、白骨空存；第三层「中原干戈古亦闻，岂有逆胡传子孙。遗民忍死望恢复，几处今宵垂泪痕」写中原干戈古亦闻岂有逆胡传子孙，遗民忍死望恢复几处今宵垂泪痕，以「岂有逆胡传子孙」写对金人的愤怒、以「遗民忍死望恢复」写沦陷区百姓的期盼，全诗对比鲜明、情感深沉、悲愤激昂，「遗民忍死望恢复，几处今宵垂泪痕」成为名句，是豪放诗的千古名篇。",
    b: "陆游这首《关山月》是他被贬出朝廷、闲居成都时所作，以「和戎诏下十五年」为背景，揭露南宋朝廷议和投降的罪恶，抒发将士和遗民的悲愤，是豪放诗的千古名篇。",
    n: ["关山月：乐府旧题，多写边塞将士的离别之情","和戎诏下十五年：和戎诏下十五年（和戎，与金人议和；诏，皇帝诏书。指隆兴和议已十五年）","将军不战空临边：将军不战空临边（空临边，白白地到边疆）","朱门沉沉按歌舞：朱门沉沉按歌舞（朱门，权贵之家；沉沉，深远的样子；按，按节拍演奏）","厩马肥死弓断弦：厩马肥死弓断弦（厩，马棚；马肥死，马因不征战而肥死；弓断弦，弓因不使用而断弦）","戍楼刁斗催落月：戍楼刁斗催落月（戍楼，边防驻军的瞭望楼；刁斗，军中打更用的铜器）","三十从军今白发：三十从军今白发","笛里谁知壮士心：笛里谁知壮士心（笛声里谁知道壮士的心）","沙头空照征人骨：沙头空照征人骨（沙头，沙滩；征人骨，出征战士的尸骨）","中原干戈古亦闻：中原干戈古亦闻（干戈，战争）","岂有逆胡传子孙：岂有逆胡传子孙（逆胡，指金人；传子孙，传了几代）","遗民忍死望恢复：遗民忍死望恢复（遗民，沦陷区的百姓；忍死，忍痛不死）","几处今宵垂泪痕：几处今宵垂泪痕"]
  },
  "临江仙|陈与义": {
    s: "上片「忆昔午桥桥上饮。坐中多是豪英。长沟流月去无声。杏花疏影里，吹笛到天明」写忆昔午桥桥上饮坐中多是豪英，长沟流月去无声，杏花疏影里吹笛到天明，以「午桥饮」「豪英」「长沟流月」「杏花疏影」「吹笛到天明」写洛阳旧游的欢乐——那时座中多是英雄豪杰，在杏花疏影里吹笛到天明；下片「二十余年如一梦。此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更」写二十余年如一梦此身虽在堪惊，闲登小阁看新晴，古今多少事渔唱起三更，以「二十余年如一梦」写南渡后的沧桑、以「古今多少事，渔唱起三更」写历史兴亡的感慨——古今多少兴亡事，都化作三更天的渔歌，全词意境清丽、对比鲜明、情感深沉、哲理深刻，「古今多少事，渔唱起三更」成为千古名句，是婉约词的千古名篇。",
    b: "陈与义（南宋初诗人，「江西诗派」代表，号简斋）这首《临江仙》是他南渡后回忆洛阳旧游所作，以「古今多少事，渔唱起三更」写历史兴亡的感慨，是婉约词的千古名篇，胡仔评为「清婉奇丽」。",
    n: ["临江仙：词牌名","忆昔午桥桥上饮：忆昔午桥桥上饮（午桥，在今河南洛阳南，是洛阳名胜）","坐中多是豪英：坐中多是豪英","长沟流月去无声：长沟流月去无声（长沟，长河；流月，月光随水流去）","杏花疏影里：杏花疏影里","吹笛到天明：吹笛到天明","二十余年如一梦：二十余年如一梦（陈与义从洛阳避乱到南方已二十余年）","此身虽在堪惊：此身虽在堪惊（此身虽然还在，却令人惊心）","闲登小阁看新晴：闲登小阁看新晴","古今多少事：古今多少事","渔唱起三更：渔唱起三更（渔歌在三更天响起，指历史兴亡都化作渔樵闲话）"]
  },
  "念奴娇|陈亮": {
    s: "上片「危楼远望。叹此意、今古几人曾会。鬼设神施，浑认作、天限南疆北界。一水横陈，莲岗三面，做出争雄势。六朝何事，只成门户私计」写危楼远望叹此意今古几人曾会，鬼设神施浑认作天限南疆北界，一水横陈莲岗三面做出争雄势，六朝何事只成门户私计，以长江的「争雄势」批评朝廷把长江当作「天限南疆北界」的屏障、以六朝「门户私计」批评偏安；下片「因笑王谢诸人，登高怀远，也学英雄涕。凭却长江管不到，河洛腥膻无际。正好长驱，不须反顾，寻取中流誓。小儿破贼，势成宁问疆场」写因笑王谢诸人登高怀远也学英雄涕，凭却长江管不到河洛腥膻无际，正好长驱不须反顾寻取中流誓，小儿破贼势成宁问疆场，以「王谢诸人也学英雄涕」讽刺权贵空流泪无行动、以「河洛腥膻无际」写中原的沦陷、以「中流誓」「小儿破贼」两个典故主张北伐，全词意境壮阔、议论精辟、用典贴切、情感豪迈，「正好长驱，不须反顾，寻取中流誓」成为名句，是豪放词的千古名篇。",
    b: "陈亮（南宋思想家、文学家，「永康学派」代表，号龙川）这首《念奴娇》是他登镇江多景楼所作，批评南宋朝廷偏安江左、只图门户私计，主张长驱北伐、恢复中原，是豪放词的千古名篇。",
    n: ["念奴娇：词牌名","危楼远望：危楼远望（危楼，高楼，指多景楼，在今江苏镇江北固山上）","叹此意、今古几人曾会：叹此意今古几人曾会（感叹这个心意古今几人能理解）","鬼设神施：鬼设神施（鬼斧神工，指自然形势的巧妙）","浑认作、天限南疆北界：浑认作天限南疆北界（全都认作是天然划分南北疆界的地方）","一水横陈：一水横陈（一条长江横陈）","莲岗三面：莲岗三面（山峦三面环绕。库文作「莲岗」，通行本作「连岗」）","做出争雄势：做出争雄势（做出争雄的形势）","六朝何事：六朝何事（六朝做了什么事）","只成门户私计：只成门户私计（只成了门户私计，指南朝偏安江左、只图保全自己）","因笑王谢诸人：因笑王谢诸人（王谢，东晋两大望族，代指当时的权贵）","登高怀远：登高怀远","也学英雄涕：也学英雄涕（也学英雄流泪，指空流泪而无实际行动）","凭却长江管不到：凭却长江管不到（凭着长江却管不到中原）","河洛腥膻无际：河洛腥膻无际（河洛，黄河洛水，指中原；腥膻，金人统治的腥臊气味）","正好长驱：正好长驱","不须反顾：不须反顾（不须回头）","寻取中流誓：寻取中流誓（寻求祖逖中流击楫的誓言。祖逖北伐时中流击楫发誓「不能清中原而复济者，有如大江」）","小儿破贼：小儿破贼（用谢安「小儿辈遂已破贼」典故，指淝水之战）","势成宁问疆场：势成宁问疆场（形势成了难道还要问战场吗。疆场，战场）"]
  },
  "贺新郎|陈亮": {
    s: "上片「老去凭谁说。看几番、神奇臭腐，夏裘冬葛。父老长安今余几，后死无仇可雪。犹未燥、当时生发。二十五弦多少恨，算世间、那有平分月。胡妇弄，汉宫瑟」写老去凭谁说看几番神奇臭腐夏裘冬葛，父老长安今余几后死无仇可雪犹未燥当时生发，二十五弦多少恨算世间那有平分月，胡妇弄汉宫瑟，以「神奇臭腐」「夏裘冬葛」写世事颠倒、以「父老长安余几」「无仇可雪」写中原沦陷的悲愤、以「胡妇弄汉宫瑟」写中原器物落入金人之手；下片「树犹如此堪重别。只使君、从来与我，话头多合。行矣置之无足问，谁唤妍皮痴骨。但莫使、伯牙弦绝。九转丹砂牢拾取，管精金、只是寻常铁。龙共虎，应声裂」写树犹如此堪重别只使君从来与我话头多合，行矣置之无足问谁唤妍皮痴骨，但莫使伯牙弦绝，九转丹砂牢拾取管精金只是寻常铁，龙共虎应声裂，以「树犹如此」写时光流逝、以「话头多合」写与辛弃疾的友谊、以「伯牙弦绝」写不要失去知音、以「九转丹砂」「精金只是寻常铁」写百炼成钢的信念——精金是从寻常铁炼成的，抗金事业也需要百炼成钢，全词用典丰富、意境壮阔、情感深沉、信念坚定，「九转丹砂牢拾取，管精金、只是寻常铁」成为名句，是豪放词的名篇。",
    b: "陈亮这首《贺新郎》是他唱和辛弃疾《贺新郎·把酒长亭说》的词作，写与辛弃疾的友谊和共同的抗金抱负，「九转丹砂牢拾取，管精金、只是寻常铁」写百炼成钢的信念，是豪放词的名篇。",
    n: ["贺新郎：词牌名","老去凭谁说：老去凭谁说（老了向谁诉说）","看几番、神奇臭腐：看几番神奇臭腐（神奇臭腐，用《庄子》「臭腐复化为神奇，神奇复化为臭腐」，指世事变化无常）","夏裘冬葛：夏裘冬葛（夏天穿裘皮、冬天穿葛布，指颠倒黑白、是非混淆）","父老长安今余几：父老长安今余几（长安，代指中原；中原的父老如今还剩几个）","后死无仇可雪：后死无仇可雪（后来死的人没有仇可雪了，指复国无望）","犹未燥、当时生发：犹未燥当时生发（当时出生的人头发还没干，指年轻人。用「生发未燥」典故）","二十五弦多少恨：二十五弦多少恨（二十五弦，指瑟，用「二十五弦弹夜月」写愁恨）","算世间、那有平分月：算世间那有平分月（算世间哪有平分的月亮，指哪有南北平分的天下）","胡妇弄：胡妇弄（胡妇弹奏）","汉宫瑟：汉宫瑟（汉宫的瑟，指中原的器物落入金人之手）","树犹如此堪重别：树犹如此堪重别（树犹如此，用桓温「木犹如此，人何以堪」典故；堪重别，怎能忍受再次离别）","只使君、从来与我：只使君从来与我（使君，指辛弃疾）","话头多合：话头多合（说话的意趣多相合）","行矣置之无足问：行矣置之无足问（走了吧，放下不值得问）","谁唤妍皮痴骨：谁唤妍皮痴骨（谁叫我外表好看内心痴愚。妍皮痴骨，用「妍皮不裹痴骨」反其意）","但莫使、伯牙弦绝：但莫使伯牙弦绝（但不要让伯牙的弦断了，指不要失去知音。伯牙，春秋时善琴者，钟子期死后伯牙破琴绝弦）","九转丹砂牢拾取：九转丹砂牢拾取（九转丹砂，道家炼丹，九转而成；牢拾取，牢牢拾取）","管精金、只是寻常铁：管精金只是寻常铁（管它精金，只是寻常铁炼成的）","龙共虎：龙共虎（龙和虎，道家炼丹术语，指水火）","应声裂：应声裂（随着声音裂开，指丹成）"]
  },
  "村晚|雷震": {
    s: "首两句「草满池塘水满陂，山衔落日浸寒漪」写草满池塘水满陂、山衔落日浸寒漪，以「草满」「水满」「山衔落日」「寒漪」写乡村傍晚的美丽景色；后两句「牧童归去横牛背，短笛无腔信口吹」是名句——牧童归去横坐在牛背上，短笛没有固定曲调随口吹，以「横牛背」「无腔信口吹」写牧童的天真烂漫、悠闲自在，全诗意境清丽、画面生动、情感真挚，「牧童归去横牛背，短笛无腔信口吹」成为名句，是七绝的名篇。",
    b: "雷震（南宋诗人）这首《村晚》写乡村傍晚的景色，「牧童归去横牛背，短笛无腔信口吹」是名句，是七绝的名篇。",
    n: ["村晚：诗题","草满池塘水满陂：草满池塘水满陂（陂，池塘岸。陂音bēi）","山衔落日浸寒漪：山衔落日浸寒漪（山衔落日，山像衔着落日；寒漪，寒冷的水波。漪音yī）","牧童归去横牛背：牧童归去横牛背（横牛背，横坐在牛背上）","短笛无腔信口吹：短笛无腔信口吹（无腔，没有固定的曲调；信口，随口）"]
  },
  "清平乐|黄庭坚": {
    s: "上片「春归何处。寂寞无行路。若有人知春去处，唤取归来同住」写春归何处寂寞无行路，若有人知春去处唤取归来同住，以「春归何处」的追问写惜春、以「唤取归来同住」的奇想写对春的留恋；下片「春无踪迹谁知。除非问取黄鹂。百啭无人能解，因风飞过蔷薇」写春无踪迹谁知除非问取黄鹂，百啭无人能解因风飞过蔷薇，以「问取黄鹂」写寻春、以「百啭无人能解」写无人能懂春的去向、以「飞过蔷薇」暗示春已归去——蔷薇开在春末夏初，黄鹂飞过蔷薇，说明春已经走了，全词意境清丽、想象奇特、情感深沉、含蓄隽永，「若有人知春去处，唤取归来同住」「百啭无人能解，因风飞过蔷薇」成为名句，是婉约词的名篇。",
    b: "黄庭坚（北宋诗人、书法家，「江西诗派」开山，「苏门四学士」之一，号山谷道人）这首《清平乐》写惜春之情，「若有人知春去处，唤取归来同住」「百啭无人能解，因风飞过蔷薇」是名句，是婉约词的名篇。",
    n: ["清平乐：词牌名","春归何处：春归何处","寂寞无行路：寂寞无行路（寂寞地没有了春的踪迹）","若有人知春去处：若有人知春去处","唤取归来同住：唤取归来同住","春无踪迹谁知：春无踪迹谁知","除非问取黄鹂：除非问取黄鹂（黄鹂，黄莺，春天的鸟）","百啭无人能解：百啭无人能解（百啭，黄鹂婉转的叫声；无人能解，没有人能听懂）","因风飞过蔷薇：因风飞过蔷薇（趁着风飞过蔷薇花丛。蔷薇开在春末夏初，暗示春已归去）"]
  },
  "鹧鸪天|黄庭坚": {
    s: "上片「黄菊枝头生晓寒。人生莫放酒杯干。风前横笛斜吹雨，醉里簪花倒著冠」写黄菊枝头生晓寒人生莫放酒杯干，风前横笛斜吹雨醉里簪花倒著冠，以「莫放酒杯干」「风前横笛」「醉里簪花倒著冠」写饮酒的欢乐与狂放；下片「身健在，且加餐。舞裙歌板尽清欢。黄花白发相牵挽，付与时人洗眼看」写身健在且加餐舞裙歌板尽清欢，黄花白发相牵挽付与时人洗眼看，以「身健在且加餐」写保重身体、以「黄花白发相牵挽」写菊花与白发相牵引——黄花（青春）与白发（老年）相伴，以「付与时人洗眼看」写旷达——让时人刮目相看，全词意境明丽、狂放旷达、情感深沉，「黄花白发相牵挽，付与时人洗眼看」成为名句。",
    b: "黄庭坚这首《鹧鸪天》写重阳饮酒的欢乐与旷达，「黄花白发相牵挽，付与时人洗眼看」是名句，是婉约词中寓含旷达的名篇。",
    n: ["鹧鸪天：词牌名","黄菊枝头生晓寒：黄菊枝头生晓寒","人生莫放酒杯干：人生莫放酒杯干（莫放，不要让）","风前横笛斜吹雨：风前横笛斜吹雨","醉里簪花倒著冠：醉里簪花倒著冠（簪花，头上插花；倒著冠，倒戴着帽子。著音zhuó）","身健在：身健在","且加餐：且加餐（姑且多吃饭，用「努力加餐饭」意）","舞裙歌板尽清欢：舞裙歌板尽清欢（歌板，唱歌时打节拍的板）","黄花白发相牵挽：黄花白发相牵挽（黄花，菊花；白发，自己的白发；相牵挽，相牵引）","付与时人洗眼看：付与时人洗眼看（交付给时人刮目相看。洗眼，擦亮眼睛）"]
  },
  "寄黄几复|黄庭坚": {
    s: "首联「我居北海君南海，寄雁传书谢不能」写我居北海君南海、寄雁传书谢不能，以「北海」「南海」写相距之远、以「雁传书谢不能」写通信之难；颔联「桃李春风一杯酒，江湖夜雨十年灯」是千古名句——桃李春风一杯酒，江湖夜雨十年灯，以「桃李春风」与「江湖夜雨」对比、以「一杯酒」与「十年灯」对比，写当年相聚的欢乐与分别十年的思念，对仗工稳、意境深远；颈联「持家但有四立壁，治病不蕲三折肱」写持家但有四立壁、治病不蕲三折肱，以「四立壁」写友人的清贫、以「三折肱」写友人的才能；尾联「想见读书头已白，隔溪猿哭瘴溪藤」写想见读书头已白、隔溪猿哭瘴溪藤，以「读书头已白」写友人的勤学、以「猿哭瘴溪藤」写友人处境的凄凉，全诗用典丰富、对仗工稳、对比鲜明、情感深沉，「桃李春风一杯酒，江湖夜雨十年灯」成为千古名句，是七律的千古名篇。",
    b: "黄庭坚这首《寄黄几复》是他寄给友人黄几复的诗，「桃李春风一杯酒，江湖夜雨十年灯」是千古名句，以对比手法写友人的思念，是七律的千古名篇。",
    n: ["寄黄几复：诗题，黄几复，黄庭坚的友人，名介，字几复","我居北海君南海：我居北海君南海（我住在北海（北方），你住在南海（南方）。用《左传》「北海」「南海」典故）","寄雁传书谢不能：寄雁传书谢不能（托雁传书却推辞不能（雁到衡阳而止，南方更远雁不能到））","桃李春风一杯酒：桃李春风一杯酒","江湖夜雨十年灯：江湖夜雨十年灯","持家但有四立壁：持家但有四立壁（持家，治理家业；但有，只有；四立壁，四堵墙立着，指家徒四壁。用司马相如「家居徒四壁立」典故）","治病不蕲三折肱：治病不蕲三折肱（蕲，祈求；三折肱，三次折断手臂，指阅历多。用「三折肱为良医」典故，指不追求阅历多而成为良医）。肱音gōng","想见读书头已白：想见读书头已白","隔溪猿哭瘴溪藤：隔溪猿哭瘴溪藤（瘴溪，有瘴气的溪水；藤，藤蔓）"]
  },
  "登快阁|黄庭坚": {
    s: "首联「痴儿了却公家事，快阁东西倚晚晴」写痴儿了却公家事、快阁东西倚晚晴，以「痴儿」自称、以「了却公家事」写办完公务后的轻松、以「倚晚晴」写登阁的闲适；颔联「落木千山天远大，澄江一道月分明」是千古名句——落木千山天远大，澄江一道月分明，以「落木千山」「天远大」写山的辽阔、以「澄江一道」「月分明」写水的清澈，意境壮阔、对仗工稳；颈联「朱弦已为佳人绝，青眼聊因美酒横」写朱弦已为佳人绝、青眼聊因美酒横，以「朱弦为佳人绝」用伯牙绝弦典故写无知音、以「青眼因美酒横」用阮籍青白眼典故写只有美酒能让自己正眼相看；尾联「万里归船弄长笛，此心吾与白鸥盟」写万里归船弄长笛、此心吾与白鸥盟，以「归船弄长笛」「与白鸥盟」写归隐之志，全词用典丰富、意境壮阔、对仗工稳、情感深沉，「落木千山天远大，澄江一道月分明」成为千古名句，是七律的千古名篇。",
    b: "黄庭坚这首《登快阁》是他任泰和知县时登快阁所作，「落木千山天远大，澄江一道月分明」是千古名句，是七律的千古名篇。",
    n: ["登快阁：诗题，快阁，在今江西泰和，黄庭坚曾任泰和知县","痴儿了却公家事：痴儿了却公家事（痴儿，呆子，黄庭坚自称；了却，办完；公家事，官府的事）","快阁东西倚晚晴：快阁东西倚晚晴（倚，倚靠；晚晴，傍晚的晴天）","落木千山天远大：落木千山天远大（落木，落叶；千山，群山）","澄江一道月分明：澄江一道月分明（澄江，清澈的江水；一道，一条）","朱弦已为佳人绝：朱弦已为佳人绝（朱弦，红色的琴弦，代指琴；佳人，知音；绝，断。用伯牙「志在高山」钟子期死，伯牙破琴绝弦典故）","青眼聊因美酒横：青眼聊因美酒横（青眼，正眼相看，用阮籍「青白眼」典故；聊，姑且；横，流露）","万里归船弄长笛：万里归船弄长笛（弄，吹奏）","此心吾与白鸥盟：此心吾与白鸥盟（与白鸥盟，与白鸥结盟，指归隐。用「鸥鹭忘机」典故）"]
  },
  "南吕·一枝花杭州景|关汉卿": {
    s: "这首套曲以「普天下锦绣乡，寰海内风流地」开篇，以「锦绣乡」「风流地」总写杭州的繁华；「大元朝新附国，亡宋家旧华夷」写杭州的历史——元朝新归附的国土、亡宋旧时的疆域；「水秀山奇，一到处堪游戏」写杭州的山水之美——水秀山奇，所到之处都可以游玩；「这答儿忒富贵，满城中绣幕风帘，一哄地人烟辏集」写杭州的繁华——这里太富贵了，满城中绣幕风帘，喧闹地人烟密集，全曲语言明快、意境开阔、描写生动，「普天下锦绣乡，寰海内风流地」成为名句，是元曲中写景的名篇。",
    b: "关汉卿（元代杂剧作家，「元曲四大家」之首，号已斋叟）这首《南吕·一枝花·杭州景》写杭州的繁华景色，是元曲中写景的名篇。",
    n: ["南吕·一枝花：曲牌名，南吕宫调","杭州景：题目","普天下锦绣乡：普天下锦绣乡","寰海内风流地：寰海内风流地（寰海，海内）","大元朝新附国：大元朝新附国（元朝新归附的国家，指南宋）","亡宋家旧华夷：亡宋家旧华夷（亡宋，灭亡的宋朝；华夷，华夏与夷狄，指疆域）","水秀山奇：水秀山奇","一到处堪游戏：一到处堪游戏（一到处，所到之处；堪，可以）","这答儿忒富贵：这答儿忒富贵（这答儿，这里；忒，太）","满城中绣幕风帘：满城中绣幕风帘（绣幕，绣花的帷幕；风帘，挡风的帘子）","一哄地人烟辏集：一哄地人烟辏集（一哄地，喧闹地；人烟辏集，人烟密集。辏音còu）"]
  },
  "碧玉箫·乌兔相催，日月走东西。人生别离，白发故人稀。不停闲岁月疾，|关汉卿": {
    s: "这首小令以「乌兔相催，日月走东西」开篇，以「乌兔」代指日月、以「走东西」写日月交替，感叹时光流逝；「人生别离，白发故人稀」写人生的离别与老朋友的稀少——到白发时老朋友已经稀少了；「不停闲岁月疾，光阴似驹过隙」以「白驹过隙」的典故写光阴的迅疾；「君莫痴，休争名利。幸有几杯，且不如花前醉」劝人不要痴愚、不要争名夺利，幸而有几杯酒，姑且不如在花前醉饮，全曲语言明快、用典贴切、哲理深刻、情感旷达，「乌兔相催，日月走东西。人生别离，白发故人稀」成为名句，是元曲中叹世的名篇。",
    b: "关汉卿这首《碧玉箫》写时光流逝、人生无常，劝人不要争名夺利、不如花前醉饮，是元曲中叹世的名篇。",
    n: ["碧玉箫：曲牌名","乌兔相催：乌兔相催（乌，金乌，指太阳；兔，玉兔，指月亮。指日月交替、时光流逝）","日月走东西：日月走东西","人生别离：人生别离","白发故人稀：白发故人稀（白发时老朋友稀少了）","不停闲岁月疾：不停闲岁月疾（岁月不停息地疾逝）","光阴似驹过隙：光阴似驹过隙（光阴像白驹过隙，用《庄子》「人生天地之间，若白驹之过隙」）","君莫痴：君莫痴（你不要痴愚）","休争名利：休争名利（不要争名夺利）","幸有几杯：幸有几杯","且不如花前醉：且不如花前醉（姑且不如在花前醉饮）"]
  },
  "正宫·塞鸿秋浔阳即景|周德清": {
    s: "这首小令前半写浔阳景色：「长江万里白如练，淮山数点青如淀。江帆几片疾如箭，山泉千尺飞如电。晚云都变露，新月初学扇，塞鸿一字来如线」——以七个「如」字比喻（白如练、青如淀、疾如箭、飞如电、变露、学扇、来如线）写浔阳的长江、淮山、江帆、山泉、晚云、新月、塞鸿，比喻新奇、对仗工稳、意境壮阔；后半写冬日的情趣：「灞桥雪拥驴难跨，剡溪水冻船难驾。秦楼美酝添高价，陶家风味都闲话。羊羔饮兴佳，金帐歌声罢，醉魂不到蓝关下」——以灞桥、剡溪、秦楼、陶家四个典故写冬日的饮酒之乐，以「醉魂不到蓝关下」写醉中的旷达——醉梦中不到韩愈被贬的蓝关，全曲比喻新奇、用典丰富、意境开阔、情感旷达，「长江万里白如练，淮山数点青如淀。江帆几片疾如箭，山泉千尺飞如电」成为千古名句，是元曲中写景的千古名篇。",
    b: "周德清（元代音韵学家、曲作家，号挺斋）这首《正宫·塞鸿秋·浔阳即景》写浔阳的景色，以「长江万里白如练」等七个比喻写浔阳的山水，是元曲中写景的千古名篇。",
    n: ["正宫·塞鸿秋：曲牌名，正宫调","浔阳即景：题目，浔阳，今江西九江","长江万里白如练：长江万里白如练（练，白绢。用谢朓「澄江静如练」）","淮山数点青如淀：淮山数点青如淀（淮山，淮水一带的山；淀，蓝靛，染料）","江帆几片疾如箭：江帆几片疾如箭","山泉千尺飞如电：山泉千尺飞如电","晚云都变露：晚云都变露（晚云都变成了露气）","新月初学扇：新月初学扇（新月刚刚学会像扇子一样，指新月如扇）","塞鸿一字来如线：塞鸿一字来如线（塞鸿，塞外的鸿雁；一字，雁阵排成一字）","灞桥雪拥驴难跨：灞桥雪拥驴难跨（灞桥，在今陕西西安，古人送别之地；雪拥，雪拥塞。用韩愈「雪拥蓝关马不前」意）","剡溪水冻船难驾：剡溪水冻船难驾（剡溪，在今浙江嵊州，王子猷雪夜访戴逵处）","秦楼美酝添高价：秦楼美酝添高价（秦楼，指酒楼；美酝，美酒；添高价，涨价）","陶家风味都闲话：陶家风味都闲话（陶家，陶渊明家；风味，情趣；都闲话，都成了闲话）","羊羔饮兴佳：羊羔饮兴佳（羊羔，羊羔酒，美酒；饮兴佳，饮酒的兴致好）","金帐歌声罢：金帐歌声罢（金帐，金色的帐幕；歌声罢，歌声停了）","醉魂不到蓝关下：醉魂不到蓝关下（蓝关，蓝田关，韩愈被贬处。醉魂不到，醉梦中不到那里）"]
  },
  "中吕·普天乐别情|张可久": {
    s: "这首小令以「一点志诚心，百步裴回意」开篇，以「志诚心」「裴回意」写离别的真诚与不舍；「花迎笑眼，柳妒愁眉」以花柳写离别的情态——花迎着笑眼，柳嫉妒愁眉；「亲传旖旎词，自首风流罪」以「旖旎词」「风流罪」写离别的缠绵——亲自传递柔美的词，自己承认风流的罪过；「把似当初休相识，今日倒省得别离」是名句——假如当初不相识，今天倒省得离别，以反语写离别的痛苦——正因为相识太深，所以离别太苦；「天知地知，前程万里，两下分飞」以「天知地知」写情意的真挚、以「前程万里」写对未来的祝愿、以「两下分飞」写离别的现实，全曲语言清丽、情感深沉、反语巧妙，「把似当初休相识，今日倒省得别离」成为名句，是元曲中写别情的名篇。",
    b: "张可久（元代曲作家，号小山，「元曲四大家」之一，与乔吉并称「曲中李杜」）这首《中吕·普天乐·别情》写离别之情，「把似当初休相识，今日倒省得别离」是名句，是元曲中写别情的名篇。",
    n: ["中吕·普天乐：曲牌名，中吕宫调","别情：题目","一点志诚心：一点志诚心（志诚，真诚）","百步裴回意：百步裴回意（裴回，徘徊。百步徘徊的情意）","花迎笑眼：花迎笑眼（花迎着笑眼）","柳妒愁眉：柳妒愁眉（柳嫉妒愁眉）","亲传旖旎词：亲传旖旎词（旖旎，柔美。亲自传递柔美的词）","自首风流罪：自首风流罪（自首，自己承认；风流罪，风流的罪过）","把似当初休相识：把似当初休相识（把似，假如。假如当初不相识）","今日倒省得别离：今日倒省得别离（今天倒省得离别）","天知地知：天知地知","前程万里：前程万里","两下分飞：两下分飞（两下，双方；分飞，分别）"]
  },
  "般涉调·哨遍高祖还乡|睢景臣": {
    s: "这套节选写高祖还乡前的准备场面：「社长排门告示，但有的差使无推故。这差使不寻俗，一壁厢纳草也恨，一边又要差夫，索应付」写社长挨家挨户通知，所有差使都不许借故推脱，这差使不寻常，一边要交纳草料，一边要征发夫役，都须应付；「又言是车驾，都说是銮舆，今日还乡故」写又说是车驾，都说是銮舆，今天还乡——以「车驾」「銮舆」写皇帝的威严，但在乡民口中只是两个名词；「王乡老执定瓦台盘，赵忙郎抱着酒胡芦。新刷来的头巾，恰糨来的绸衫，畅好是妆么大户」写王乡老拿着瓦托盘，赵忙郎抱着酒葫芦，新洗的头巾，刚浆洗的绸衫，真是装模作样的大户人家——以乡民的视角写迎接皇帝的准备，讽刺了皇帝的装腔作势和乡民的装模作样，全曲语言通俗、视角独特、讽刺辛辣、幽默生动，「畅好是妆么大户」成为名句，是元曲中讽刺文学的千古名篇。",
    b: "睢景臣（元代曲作家，字景贤）这首《般涉调·哨遍·高祖还乡》是元曲中最著名的套曲之一，以一个乡民的视角写汉高祖刘邦还乡的场面，讽刺了皇帝的装腔作势，是元曲中讽刺文学的千古名篇，钟嗣成《录鬼簿》评为「制作新奇，诸公者皆出其下」。",
    n: ["般涉调·哨遍：曲牌名，般涉调","高祖还乡：题目，汉高祖刘邦还乡","社长排门告示：社长排门告示（社长，古代乡社的头目；排门告示，挨家挨户通知）","但有的差使无推故：但有的差使无推故（但有的，所有的；推故，借故推脱）","这差使不寻俗：这差使不寻俗（不寻俗，不寻常）","一壁厢纳草也恨：一壁厢纳草也恨（一壁厢，一边；纳草，交纳草料；也恨，又要。「也恨」或作「也根」）","一边又要差夫：一边又要差夫（差夫，征发夫役）","索应付：索应付（须应付）","又言是车驾：又言是车驾（车驾，皇帝的车驾，代指皇帝）","都说是銮舆：都说是銮舆（銮舆，皇帝的车驾）","今日还乡故：今日还乡故（还乡故，还乡）","王乡老执定瓦台盘：王乡老执定瓦台盘（王乡老，乡村长者；执定，拿着；瓦台盘，瓦制的托盘）","赵忙郎抱着酒胡芦：赵忙郎抱着酒胡芦（赵忙郎，乡村年轻人；酒胡芦，酒葫芦）","新刷来的头巾：新刷来的头巾（新刷来，新洗的）","恰糨来的绸衫：恰糨来的绸衫（恰糨来，刚浆洗的。糨音jiàng，浆洗）","畅好是妆么大户：畅好是妆么大户（畅好是，真是；妆么，装模作样；大户，大户人家）"]
  },
  "双调·夜行船|马致远": {
    s: "这套节选以「天地之间人寄居，来生去死嗟吁」开篇，以「人寄居」写人生的短暂——人在天地之间只是寄居的过客，以「来生去死嗟吁」写对生死的叹息；「就里荣枯，暗中贫富，人力不能除取」写其中的荣耀与枯萎、暗中的贫与富，都是人力不能改变的——富贵荣华、贫穷困苦，都不是人力所能左右，全曲语言凝练、哲理深刻、情感深沉，「天地之间人寄居，来生去死嗟吁」成为名句，是元曲中叹世的千古名篇。",
    b: "马致远（元代杂剧作家，「元曲四大家」之一，号东篱，被称为「曲状元」）这首《双调·夜行船》是元曲中最著名的套曲之一，写人生无常、富贵如梦，劝人归隐，是元曲中叹世的千古名篇。",
    n: ["双调·夜行船：曲牌名，双调","天地之间人寄居：天地之间人寄居（人在天地之间只是寄居）","来生去死嗟吁：来生去死嗟吁（来生去死，来生和死去；嗟吁，叹息）","就里荣枯：就里荣枯（就里，其中；荣枯，荣耀与枯萎）","暗中贫富：暗中贫富（暗中的贫富变化）","人力不能除取：人力不能除取（除取，改变。人力不能改变）"]
  },
  "咏煤炭|于谦": {
    s: "首联「凿开混沌得乌金，藏蓄阳和意最深」写凿开混沌得到乌金、藏蓄阳和意最深，以「乌金」喻煤炭、以「阳和」写煤炭的温暖；颔联「爝火燃回春浩浩，洪炉照破夜沉沉」写爝火燃回春浩浩、洪炉照破夜沉沉，以「燃回春浩浩」「照破夜沉沉」写煤炭的功用——带来春意、照亮黑夜；颈联「鼎彝元赖生成力，铁石犹存死后心」写鼎彝元赖生成力、铁石犹存死后心，以「鼎彝赖生成力」写煤炭对国家的贡献、以「铁石犹存死后心」写煤炭的忠心——虽为铁石之类，却保存着死后的忠心；尾联「但愿苍生俱饱暖，不辞辛苦出山林」是千古名句——但愿百姓都饱食暖衣，不推辞辛苦从山林中出来，以「苍生俱饱暖」写为国为民的抱负、以「不辞辛苦出山林」写献身精神，全诗托物言志、比喻巧妙、情感深沉、抱负远大，「但愿苍生俱饱暖，不辞辛苦出山林」成为千古名句，是咏物诗的千古名篇。",
    b: "于谦（明代政治家、军事家，号节庵，「西湖三杰」之一）这首《咏煤炭》以煤炭自喻，抒发为国为民、不辞辛苦的抱负，「但愿苍生俱饱暖，不辞辛苦出山林」是千古名句，是咏物诗的千古名篇。",
    n: ["咏煤炭：诗题","凿开混沌得乌金：凿开混沌得乌金（混沌，指天地未开前的状态，此指地下；乌金，黑色的金子，指煤炭）","藏蓄阳和意最深：藏蓄阳和意最深（阳和，温暖的阳气；意最深，情意最深）","爝火燃回春浩浩：爝火燃回春浩浩（爝火，小火把；浩浩，广大的样子。小火把燃烧起来带回了广大的春意。爝音jué）","洪炉照破夜沉沉：洪炉照破夜沉沉（洪炉，大炉子；沉沉，深沉的样子。大炉子照亮了深沉的黑夜）","鼎彝元赖生成力：鼎彝元赖生成力（鼎彝，古代宗庙祭祀的礼器，代指国家；元赖，本来依靠；生成力，生成的力量）","铁石犹存死后心：铁石犹存死后心（铁石还保存着死后的心，指煤炭虽为铁石之类，却有为国为民的忠心）","但愿苍生俱饱暖：但愿苍生俱饱暖（苍生，百姓；俱，都；饱暖，饱食暖衣）","不辞辛苦出山林：不辞辛苦出山林（不辞，不推辞；出山林，从山林中出来）"]
  },
  "卖柑者言|刘基": {
    s: "全文分三层：第一层写卖柑者的柑橘「出之烨然，玉质而金色」，但「剖之……则干若败絮」，「我」质问卖柑者「甚矣哉，为欺也」；第二层写卖柑者的反驳——「世之为欺者不寡矣，而独我也乎」，然后揭露当时的武将「佩虎符、坐皋比」却「果能授孙、吴之略耶」，文官「峨大冠、拖长绅」却「果能建伊、皋之业耶」，他们「盗起而不知御，民困而不知救，吏奸而不知禁，法斁而不知理，坐糜廪粟而不知耻」，但「坐高堂，骑大马，醉醇醴而饫肥鲜」，「巍巍乎可畏，赫赫乎可象」——「又何往而不金玉其外，败絮其中也哉」；第三层写「予默默无以应」，「退而思其言，类东方生滑稽之流」，「岂其愤世疾邪者耶，而托于柑以讽耶」。全文托物讽世、对比鲜明、语言犀利、寓意深刻，「金玉其外，败絮其中」成为千古成语，是寓言式散文的典范。",
    b: "刘基（明代开国功臣，字伯温，号郁离子）这篇《卖柑者言》通过卖柑者的话，揭露当时文武大臣「金玉其外，败絮其中」的本质，是中国古代寓言式散文的千古名篇，「金玉其外，败絮其中」成为千古成语。",
    n: ["卖柑者言：篇名，刘基作","杭有卖果者：杭有卖果者（杭州有个卖水果的人）","善藏柑：善藏柑（善于收藏柑橘）","涉寒暑不溃：涉寒暑不溃（经过寒暑不腐烂。溃音kuì，腐烂）","出之烨然：出之烨然（拿出它来光彩鲜明。烨音yè，光彩鲜明）","玉质而金色：玉质而金色（质地像玉、颜色像金）","置于市：置于市（放到市场上）","贾十倍：贾十倍（价格十倍。贾同「价」）","人争鬻之：人争鬻之（人们争着买它。鬻音yù，买）","予贸得其一：予贸得其一（我买了其中一个。贸，买）","剖之：剖之（剖开它）","如有烟扑口鼻：如有烟扑口鼻（好像有烟扑向口鼻）","视其中：视其中（看它的里面）","则干若败絮：则干若败絮（却干得像破旧的棉絮。败絮，破棉絮）","予怪而问之曰：予怪而问之曰（我奇怪地问他说）","若所市于人者：若所市于人者（你卖给人的。若，你；市，卖）","将以实笾豆：将以实笾豆（将用来装满笾豆。笾豆，古代祭祀用的礼器。笾音biān）","奉祭祀：奉祭祀（供奉祭祀）","供宾客乎：供宾客乎（招待宾客吗）","将炫外以惑愚瞽也：将炫外以惑愚瞽也（还是炫耀外表来迷惑愚人和瞎子呢。炫音xuàn，炫耀；瞽音gǔ，瞎子）","甚矣哉：甚矣哉（太过分了啊）","为欺也：为欺也（做这种欺骗的事）","卖者笑曰：卖者笑曰","吾业是有年矣：吾业是有年矣（我做这个行业有年头了）","吾赖是以食吾躯：吾赖是以食吾躯（我靠这个来养活自己。食音sì，供养）","吾售之：吾售之","人取之：人取之","未尝有言：未尝有言（不曾有过闲话）","而独不足子所乎：而独不足子所乎（却唯独不能满足你的需要吗。子所，你的需要）","世之为欺者不寡矣：世之为欺者不寡矣（世上做欺骗的事的人不少了）","而独我也乎：而独我也乎（却只有我吗）","吾子未之思也：吾子未之思也（您没有想过这个啊）","今夫佩虎符、坐皋比者：今夫佩虎符、坐皋比者（现在那些佩戴虎符、坐在虎皮椅上的人，指武将。皋比音gāopí，虎皮）","洸洸乎干城之具也：洸洸乎干城之具也（威武的样子像是保卫国家的人才。洸洸音guāngguāng，威武的样子；干城，保卫国家）","果能授孙、吴之略耶：果能授孙、吴之略耶（果真能传授孙武、吴起的谋略吗。孙吴，孙武、吴起，古代军事家）","峨大冠、拖长绅者：峨大冠、拖长绅者（戴着高帽子、拖着长带子的人，指文官。峨，高；绅，古代士大夫束腰的大带）","昂昂乎庙堂之器也：昂昂乎庙堂之器也（气宇轩昂的样子像是朝廷的栋梁。昂昂，气宇轩昂；庙堂，朝廷）","果能建伊、皋之业耶：果能建伊、皋之业耶（果真能建立伊尹、皋陶的功业吗。伊皋，伊尹、皋陶，古代贤臣）","盗起而不知御：盗起而不知御（盗贼起来了却不知道抵御）","民困而不知救：民困而不知救（百姓困苦却不知道救助）","吏奸而不知禁：吏奸而不知禁（官吏奸猾却不知道禁止）","法斁而不知理：法斁而不知理（法度败坏却不知道整顿。斁音dù，败坏）","坐糜廪粟而不知耻：坐糜廪粟而不知耻（坐着耗费国家的粮食却不知道羞耻。糜音mí，耗费；廪粟，仓库里的粮食）","观其坐高堂：观其坐高堂（看他们坐在高堂上）","骑大马：骑大马","醉醇醴而饫肥鲜者：醉醇醴而饫肥鲜者（喝美酒、吃肥肉鲜鱼的人。醇醴，美酒；饫音yù，饱食）","孰不巍巍乎可畏：孰不巍巍乎可畏（谁不高大得令人敬畏。巍巍，高大的样子）","赫赫乎可象也：赫赫乎可象也（显赫得令人效法。赫赫，显赫；象，效法）","又何往而不金玉其外：又何往而不金玉其外（又哪里不是金玉其外）","败絮其中也哉：败絮其中也哉（败絮其中呢）","今子是之不察：今子是之不察（现在你不考察这些）","而以察吾柑：而以察吾柑（却来考察我的柑橘）","予默默无以应：予默默无以应（我默默地无话可答）","退而思其言：退而思其言（回来后思考他的话）","类东方生滑稽之流：类东方生滑稽之流（像是东方朔一类滑稽的人。东方生，东方朔，汉武帝时文学家，以滑稽讽谏著称；滑稽，言语诙谐）","岂其愤世疾邪者耶：岂其愤世疾邪者耶（难道他是愤世嫉邪的人吗）","而托于柑以讽耶：而托于柑以讽耶（而假托柑橘来讽刺吗）"]
  },
  "桃花庵歌|唐寅": {
    s: "全诗分四层：第一层「桃花坞里桃花庵，桃花庵里桃花仙。桃花仙人种桃树，又折花枝当酒钱。酒醒只在花前坐，酒醉还须花下眠。花前花后日复日，酒醉酒醒年复年」以「桃花」反复出现，写桃花仙人的生活——种桃树、折花换酒、花前坐、花下眠，日复日、年复年，逍遥自在；第二层「不愿鞠躬车马前，但愿老死花酒间。车尘马足贵者趣，酒盏花枝贫者缘。若将富贵比贫贱，一在平地一在天。若将贫贱比车马，他得驱驰我得闲」以「不愿鞠躬车马前，但愿老死花酒间」写不愿趋炎附势、安贫乐道的情怀，以「富贵比贫贱，一在平地一在天」「贫贱比车马，他得驱驰我得闲」对比富贵与贫贱的不同——权贵奔走忙碌，贫者逍遥自在；第三层「世人笑我忒风颠，我咲世人看不穿」以「世人笑我风颠」与「我咲世人看不穿」对比，写世人不理解自己的逍遥；第四层「记得五陵豪杰墓，无酒无花锄作田」以五陵豪杰墓「无酒无花锄作田」写富贵的无常——当年的豪杰墓地如今已被锄作田地，全诗语言明快、反复咏叹、对比鲜明、情感旷达、哲理深刻，「不愿鞠躬车马前，但愿老死花酒间」「世人笑我忒风颠，我咲世人看不穿」成为名句，是七言古诗的千古名篇。",
    b: "唐寅（明代画家、文学家，字伯虎，号六如居士，「吴中四才子」之一）这首《桃花庵歌》是他晚年隐居桃花庵时所作，以桃花仙人自喻，抒发不愿趋炎附势、安贫乐道的情怀，「但愿老死花酒间」「世人笑我忒风颠，我咲世人看不穿」是名句，是七言古诗的千古名篇。",
    n: ["桃花庵歌：诗题，桃花庵，唐寅在苏州的居所","桃花坞里桃花庵：桃花坞里桃花庵（桃花坞，在今苏州）","桃花庵里桃花仙：桃花庵里桃花仙","桃花仙人种桃树：桃花仙人种桃树","又折花枝当酒钱：又折花枝当酒钱","酒醒只在花前坐：酒醒只在花前坐","酒醉还须花下眠：酒醉还须花下眠","花前花后日复日：花前花后日复日","酒醉酒醒年复年：酒醉酒醒年复年","不愿鞠躬车马前：不愿鞠躬车马前（不愿在车马前鞠躬，指不愿趋炎附势）","但愿老死花酒间：但愿老死花酒间","车尘马足贵者趣：车尘马足贵者趣（车尘马足，指权贵的生活；趣，志趣）","酒盏花枝贫者缘：酒盏花枝贫者缘（酒盏花枝，指贫者的生活；缘，缘分）","若将富贵比贫贱：若将富贵比贫贱","一在平地一在天：一在平地一在天","若将贫贱比车马：若将贫贱比车马","他得驱驰我得闲：他得驱驰我得闲（驱驰，奔走忙碌）","世人笑我忒风颠：世人笑我忒风颠（忒，太；风颠，疯癫。库文作「风颠」，通行本作「疯颠」）","我咲世人看不穿：我咲世人看不穿（咲同「笑」）","记得五陵豪杰墓：记得五陵豪杰墓（五陵，汉代五个皇帝的陵墓，代指富豪权贵的墓地）","无酒无花锄作田：无酒无花锄作田（没有酒没有花，被锄作田地）"]
  },
  "画鸡|唐寅": {
    s: "首两句「头上红冠不用裁，满身雪白走将来」写头上红冠不用裁、满身雪白走将来，以「红冠」「雪白」写雄鸡的外貌——红冠雪白，威武美丽；后两句「平生不敢轻言语，一叫千门万户开」是千古名句——平生不敢轻易说话，一叫千门万户都开了，以「不敢轻言语」写雄鸡的慎重、以「一叫千门万户开」写雄鸡报晓的威力——不鸣则已，一鸣惊人，全诗托物言志、语言明快、形象生动、寓意深刻，「平生不敢轻言语，一叫千门万户开」成为千古名句，是题画诗的千古名篇。",
    b: "唐寅这首《画鸡》是题画诗，以雄鸡自喻，「平生不敢轻言语，一叫千门万户开」是千古名句，是七绝的千古名篇。",
    n: ["画鸡：诗题","头上红冠不用裁：头上红冠不用裁（裁，裁剪。头上的红冠不用裁剪）","满身雪白走将来：满身雪白走将来（满身雪白走过来）","平生不敢轻言语：平生不敢轻言语（平生不敢轻易说话）","一叫千门万户开：一叫千门万户开（一叫千门万户都开了）"]
  },
  "别云间|夏完淳": {
    s: "首联「三年羁旅客，今日又南冠」写三年羁旅客、今日又南冠，以「三年羁旅」写抗清漂泊的艰辛、以「南冠」写被清军俘虏的屈辱；颔联「无限山河泪，谁言天地宽」写无限山河泪、谁言天地宽，以「山河泪」写亡国之痛、以「天地宽」的反问写无处容身的悲愤——山河破碎，天地虽大却无处容身；颈联「已知泉路近，欲别故乡难」写已知泉路近、欲别故乡难，以「泉路近」写面对死亡的坦然、以「别故乡难」写对故乡的眷恋；尾联「毅魄归来日，灵旗空际看」是千古名句——坚毅的魂魄归来的日子，要在空中看战旗飘扬，以「毅魄归来」写死后也要抗清的决心、以「灵旗空际看」写对抗清事业的期望，全诗情感深沉、悲壮激昂、视死如归，「无限山河泪，谁言天地宽」「毅魄归来日，灵旗空际看」成为千古名句，是五律的千古名篇。",
    b: "夏完淳（明末抗清英雄，诗人，字存古，号小隐，殉国时年仅17岁）这首《别云间》是他被清军俘虏、押解途中告别故乡时所作，抒发亡国之痛和誓死抗清的决心，「毅魄归来日，灵旗空际看」是千古名句，是五律的千古名篇。",
    n: ["别云间：诗题，云间，今上海松江，夏完淳的故乡","三年羁旅客：三年羁旅客（三年做漂泊在外的旅客。夏完淳抗清失败后漂泊三年）","今日又南冠：今日又南冠（南冠，囚犯，用「南冠而絷」典故，指被清军俘虏）","无限山河泪：无限山河泪（无限的山河破碎之泪）","谁言天地宽：谁言天地宽（谁说天地宽广呢——指无处容身）","已知泉路近：已知泉路近（泉路，黄泉路，指死亡。已经知道离死亡近了）","欲别故乡难：欲别故乡难（想要告别故乡却难以割舍）","毅魄归来日：毅魄归来日（毅魄，坚毅的魂魄。指死后魂魄归来的日子）","灵旗空际看：灵旗空际看（灵旗，战旗；空际，空中。指魂魄归来时在空中看战旗飘扬）"]
  },
  "即事|夏完淳": {
    s: "首联「复楚情何极，亡秦气未平」写复楚情何极、亡秦气未平，以「复楚」「亡秦」的典故写恢复明朝、灭亡清朝的壮志——「楚虽三户，亡秦必楚」，情意何其深厚，怒气未平；颔联「雄风清角劲，落日大旗明」写雄风清角劲、落日大旗明，以「雄风」「清角」「落日」「大旗」写抗清军队的威武——威风凛凛，号角凄清，落日下大旗鲜明；颈联「缟素酬家国，戈船决死生」写缟素酬家国、戈船决死生，以「缟素」写为国戴孝、以「戈船决死生」写决一死战的决心；尾联「胡笳千古恨，一片月临城」写胡笳千古恨、一片月临城，以「胡笳」写清军的入侵、以「千古恨」写亡国的遗恨、以「一片月临城」写月光下的孤城——凄凉中蕴含悲壮，全诗用典贴切、意境壮阔、情感深沉、悲壮激昂，「缟素酬家国，戈船决死生」成为名句，是五律的名篇。",
    b: "夏完淳这首《即事》写抗清斗争的壮志和亡国之恨，「缟素酬家国，戈船决死生」是名句，是五律的名篇。",
    n: ["即事：诗题，即事，以当前事物为题","复楚情何极：复楚情何极（复楚，恢复楚国，代指恢复明朝。用「楚虽三户，亡秦必楚」典故。情何极，情意何其深厚）","亡秦气未平：亡秦气未平（亡秦，灭亡秦朝，代指灭亡清朝。气未平，怒气未平）","雄风清角劲：雄风清角劲（雄风，威风；清角，凄清的号角；劲，强劲）","落日大旗明：落日大旗明（落日下大旗鲜明）","缟素酬家国：缟素酬家国（缟素，白色的丧服，指为国家戴孝；酬，报答）","戈船决死生：戈船决死生（戈船，战船；决死生，决一死战）","胡笳千古恨：胡笳千古恨（胡笳，北方少数民族的乐器，代指清军；千古恨，千古的遗恨）","一片月临城：一片月临城（一片月光照临城池）"]
  },
  "送东阳马生序|宋濂": {
    s: "全文（节选）分三层：第一层写幼时求学的艰苦——「余幼时即嗜学，家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书」，以「手自笔录」「天大寒砚冰坚手指不可屈伸弗之怠」「走送之不敢稍逾约」写借书抄书的艰苦；第二层写成年后从师的艰苦——「既加冠，益慕圣贤之道，又患无硕师名人与游，尝趋百里外，从乡之先达执经叩问。先达德隆望尊，门人弟子填其室，未尝稍降辞色。余立侍左右，援疑质理，俯身倾耳以请；或遇其叱咄，色愈恭，礼愈至，不敢出一言以复；俟其欣悦，则又请焉。故余虽愚，卒获有所闻」，以「趋百里外」「立侍左右」「色愈恭礼愈至」写从师请教的艰苦；第三层写从师旅途和生活的艰苦——「当余之从师也，负箧曳屣行深山巨谷中，穷冬烈风，大雪深数尺，足肤皲裂而不知。至舍，四支僵劲不能动，媵人持汤沃灌，以衾拥覆，久而乃和。寓逆旅，主人日再食，无鲜肥滋味之享。同舍生皆被绮绣……烨然若神人；余则缊袍敝衣处其间，略无慕艳意，以中有足乐者，不知口体之奉不若人也」，以「负箧曳屣」「足肤皲裂」「缊袍敝衣」写旅途和生活的艰苦，以「以中有足乐者，不知口体之奉不若人也」写精神的富足——因为心中有足以快乐的事，所以不觉得吃穿不如别人。全文对比鲜明、细节生动、情感真挚、勉励殷切，「以中有足乐者，不知口体之奉不若人也」成为千古名句，是赠序散文的典范。",
    b: "宋濂（明代开国文臣之首，字景濂，号潜溪）这篇《送东阳马生序》是他写给太学生马君则的赠序，通过回忆自己年轻时求学的艰苦经历，勉励马生珍惜优越的学习条件、勤奋学习，是中国古代赠序散文的千古名篇，「以中有足乐者，不知口体之奉不若人也」成为千古名句。",
    n: ["送东阳马生序：篇名，宋濂作，东阳，今浙江东阳；马生，马君则，太学生；序，赠序","余幼时即嗜学：余幼时即嗜学（我小时候就爱好学习。嗜音shì，爱好）","家贫：家贫","无从致书以观：无从致书以观（没有办法得到书来看。致，得到）","每假借于藏书之家：每假借于藏书之家（常常向藏书的人家借。假借，借）","手自笔录：手自笔录（亲手用笔抄写）","计日以还：计日以还（计算着日期归还）","天大寒：天大寒","砚冰坚：砚冰坚（砚台里的冰坚硬）","手指不可屈伸：手指不可屈伸","弗之怠：弗之怠（弗，不；怠，懈怠。即「弗怠之」，不放松抄写）","录毕：录毕（抄完）","走送之：走送之（跑着送还书。走，跑）","不敢稍逾约：不敢稍逾约（不敢稍微超过约定的期限。逾，超过）","以是人多以书假余：以是人多以书假余（因此人们大多把书借给我）","余因得遍观群书：余因得遍观群书（我因此能够广泛阅读各种书籍）","既加冠：既加冠（加冠，古代男子二十岁行加冠礼，表示成年。已经成年后）","益慕圣贤之道：益慕圣贤之道（更加仰慕圣贤的学说）","又患无硕师名人与游：又患无硕师名人与游（又担心没有大师名人交往。硕师，大师；游，交往）","尝趋百里外：尝趋百里外（曾经跑到百里之外。趋，快走）","从乡之先达执经叩问：从乡之先达执经叩问（跟随乡里的前辈拿着经书请教。先达，前辈；叩问，请教）","先达德隆望尊：先达德隆望尊（前辈道德高、声望重）","门人弟子填其室：门人弟子填其室（门人弟子挤满了他的屋子）","未尝稍降辞色：未尝稍降辞色（不曾稍微缓和言辞和脸色。辞色，言辞和脸色）","余立侍左右：余立侍左右（我站着陪侍在左右）","援疑质理：援疑质理（提出疑难，询问道理。援，提出；质，询问）","俯身倾耳以请：俯身倾耳以请（弯下身子侧着耳朵来请教）","或遇其叱咄：或遇其叱咄（有时遇到他的呵斥。叱咄音chìduō，呵斥）","色愈恭：色愈恭（脸色更加恭敬）","礼愈至：礼愈至（礼节更加周到）","不敢出一言以复：不敢出一言以复（不敢说一句话来回复）","俟其欣悦：俟其欣悦（等到他高兴了。俟音sì，等待）","则又请焉：则又请焉（就又去请教）","故余虽愚：故余虽愚（所以我虽然愚笨）","卒获有所闻：卒获有所闻（最终获得了一些教益）","当余之从师也：当余之从师也（当我从师求学的时候）","负箧曳屣：负箧曳屣（背着书箱，拖着鞋子。箧音qiè，书箱；曳音yè，拖；屣音xǐ，鞋子）","行深山巨谷中：行深山巨谷中","穷冬烈风：穷冬烈风（严冬，寒风凛冽。穷冬，严冬）","大雪深数尺：大雪深数尺","足肤皲裂而不知：足肤皲裂而不知（脚上的皮肤冻裂了却不知道。皲音jūn，皮肤冻裂）","至舍：至舍（到了学舍）","四支僵劲不能动：四支僵劲不能动（四肢僵硬不能动弹。支同「肢」）","媵人持汤沃灌：媵人持汤沃灌（服侍的人拿热水浇洗。媵人音yìngrén，服侍的人；汤，热水；沃灌，浇洗）","以衾拥覆：以衾拥覆（用被子裹住。衾音qīn，被子）","久而乃和：久而乃和（很久才暖和过来）","寓逆旅：寓逆旅（住在旅店里。逆旅，旅店）","主人日再食：主人日再食（主人每天供给两顿饭。食音sì，供养）","无鲜肥滋味之享：无鲜肥滋味之享（没有新鲜肥美的滋味享受）","同舍生皆被绮绣：同舍生皆被绮绣（同屋的学生都穿着华丽的丝绸衣服。被同「披」；绮绣，华丽的丝绸衣服）","戴朱缨宝饰之帽：戴朱缨宝饰之帽（戴着红缨宝石装饰的帽子）","腰白玉之环：腰白玉之环（腰上挂着白玉环）","左佩刀：左佩刀","右备容臭：右备容臭（右边挂着香囊。容臭，香囊。臭音xiù，气味）","烨然若神人：烨然若神人（光彩照人像神仙一样。烨音yè）","余则缊袍敝衣处其间：余则缊袍敝衣处其间（我却穿着破旧的衣服处在他们中间。缊袍音yùnpáo，旧絮袍；敝衣，破衣）","略无慕艳意：略无慕艳意（毫无羡慕的意思）","以中有足乐者：以中有足乐者（因为心中有足以快乐的事）","不知口体之奉不若人也：不知口体之奉不若人也（不觉得吃的穿的不如别人。口体之奉，吃穿的供养）","盖余之勤且艰若此：盖余之勤且艰若此（大概我的勤奋和艰苦就是这样）"]
  },
  "湖心亭看雪|张岱": {
    s: "全文分三层：第一层写看雪的时间和环境——「崇祯五年十二月，余住西湖。大雪三日，湖中人鸟声俱绝。是日更定矣，余拏一小舟，拥毳衣炉火，独往湖心亭看雪」，以「大雪三日，湖中人鸟声俱绝」写雪后的寂静、以「独往湖心亭看雪」写独自一人的雅兴；第二层写雪景——「雾凇沆砀，天与云与山与水，上下一白。湖上影子，惟长堤一痕、湖心亭一点、与余舟一芥，舟中人两三粒而已」，以「上下一白」写雪后的洁白、以「一痕」「一点」「一芥」「两三粒」写雪景的苍茫——长堤只有一道痕迹，湖心亭只有一点，小船像一片草叶，船中人只有两三粒，以小见大、意境苍茫；第三层写亭中遇人——「到亭上，有两人铺毡对坐，一童子烧酒炉正沸。见余大喜曰：『湖中焉得更有此人！』拉余同饮。余强饮三大白而别。问其姓氏，是金陵人，客此。及下船，舟子喃喃曰：『莫说相公痴，更有痴似相公者。』」，以「湖中焉得更有此人」写意外的惊喜、以「金陵人，客此」暗喻故国之思——金陵是明朝旧都，客此暗喻明朝遗民，以「莫说相公痴，更有痴似相公者」写「痴」的境界——痴于雪景、痴于故国，全文意境苍茫、细节生动、情感深沉、含蓄隽永，「莫说相公痴，更有痴似相公者」成为千古名句，是小品文的典范。",
    b: "张岱（明末清初文学家，字宗子，号陶庵，「明末四公子」之一）这篇《湖心亭看雪》写他在明亡后回忆西湖看雪的经历，以「莫说相公痴，更有痴似相公者」写故国之思，是中国古代小品文的千古名篇。",
    n: ["湖心亭看雪：篇名，张岱作，湖心亭，在杭州西湖中","崇祯五年十二月：崇祯五年十二月（崇祯五年，1632年。崇祯，明思宗年号）","余住西湖：余住西湖","大雪三日：大雪三日","湖中人鸟声俱绝：湖中人鸟声俱绝（湖中行人、飞鸟的声音都消失了。俱，都；绝，消失）","是日更定矣：是日更定矣（这一天初更以后。更定，初更以后，晚上八点左右。更音gēng）","余拏一小舟：余拏一小舟（我撑着一只小船。拏音ná，撑）","拥毳衣炉火：拥毳衣炉火（穿着毛皮衣，带着火炉。毳音cuì，毛皮）","独往湖心亭看雪：独往湖心亭看雪","雾凇沆砀：雾凇沆砀（雾凇，天冷时雾气凝结在树木上的白色冰晶；沆砀音hàngdàng，白气弥漫的样子）","天与云与山与水：天与云与山与水","上下一白：上下一白（上上下下全白了）","湖上影子：湖上影子","惟长堤一痕：惟长堤一痕（只有长堤的一道痕迹。长堤，西湖白堤）","湖心亭一点：湖心亭一点","与余舟一芥：与余舟一芥（和我的小船像一片小草叶。芥音jiè，小草）","舟中人两三粒而已：舟中人两三粒而已（船中的人像两三粒米粒而已）","到亭上：到亭上","有两人铺毡对坐：有两人铺毡对坐（有两个人铺着毡子相对而坐）","一童子烧酒炉正沸：一童子烧酒炉正沸（一个童子烧酒，炉子正沸腾）","见余大喜曰：见余大喜曰（看见我非常高兴地说）","湖中焉得更有此人：湖中焉得更有此人（湖中怎么还能有这样的人呢。焉得，怎么能）","拉余同饮：拉余同饮","余强饮三大白而别：余强饮三大白而别（我勉强喝了三大杯酒然后告别。强，勉强；大白，大酒杯）","问其姓氏：问其姓氏","是金陵人：是金陵人（是金陵人。金陵，今南京）","客此：客此（客居此地）","及下船：及下船（等到下船）","舟子喃喃曰：舟子喃喃曰（船夫喃喃地说。喃喃音nánnán，小声说话）","莫说相公痴：莫说相公痴（不要说相公您痴。相公，对士人的尊称）","更有痴似相公者：更有痴似相公者（还有像相公您一样痴的人呢）"]
  },
  "五人墓碑记|张溥": {
    s: "全文分五段：第一段写五人的死因和修墓的经过——「五人者，盖当蓼洲周公之被逮，激于义而死焉者也」，「郡之贤士大夫请于当道，即除逆阉废祠之址以葬之，且立石于其墓之门，以旌其所为」；第二段以富贵之子、草野无闻者与五人对比——「凡富贵之子，慷慨得志之徒，其疾病而死，死而湮没不足道者，亦已众矣，况草野之无闻者欤？独五人之皦皦，何也？」，突出五人的光明磊落；第三段写周公被逮和吴民暴动的经过——「予犹记周公之被逮，在丁卯三月之望」，「吾社之行为士先者，为之声义，敛赀财以送其行，哭声震动天地」，「缇骑按剑而前，问：『谁为哀者？』众不能堪，抶而仆之」，「中丞匿于溷藩以免」，「按诛五人，曰颜佩韦、杨念如、马杰、沈扬、周文元」，写五人临刑「意气扬扬，呼中丞之名而詈之，谈笑以死」，「断头置城上，颜色不少变」；第四段议论——「大阉之乱，缙绅而能不易其志者，四海之大，有几人欤？而五人生于编伍之间，素不闻诗书之训，激昂大义，蹈死不顾，亦曷故哉？」，以缙绅与五人对比，突出五人的精神；「卒以吾郡之发愤一击，不敢复有株治，大阉亦逡巡畏义，非常之谋难于猝发，待圣人之出而投缳道路，不可谓非五人之力也」，写五人之死的重大作用；第五段进一步议论——「由是观之，则今之高爵显位，一旦抵罪，或脱身以逃，不能容于远近，而又有剪发杜门，佯狂不知所之者，其辱人贱行，视五人之死，轻重固何如哉？」，以高官显位的辱人贱行与五人之死对比；「不然，令五人者保其首领，以老于户牖之下，则尽其天年，人皆得以隶使之，安能屈豪杰之流，扼腕墓道，发其志士之悲哉？」，以假设反衬五人之死的意义；「故余与同社诸君子，哀斯墓之徒有其石也，而为之记，亦以明死生之大，匹夫之有重于社稷也」，点明主旨——阐明死生的重大意义，普通百姓对国家也有重要作用。全文叙议结合、对比鲜明、情感深沉、气势充沛，「激昂大义，蹈死不顾」「匹夫之有重于社稷也」成为千古名句，是碑记散文的典范。",
    b: "张溥（明末文学家，「复社」领袖，字天如，号西铭）这篇《五人墓碑记》通过记述明末苏州市民暴动中被杀的五人的事迹，歌颂了他们「激昂大义，蹈死不顾」的精神，阐明「匹夫之有重于社稷」的道理，是中国古代碑记散文的千古名篇。",
    n: ["五人墓碑记：篇名，张溥作，五人，明末苏州市民暴动中被杀的五人","五人者：五人者","盖当蓼洲周公之被逮：盖当蓼洲周公之被逮（蓼洲周公，周顺昌，号蓼洲，明末东林党人。蓼音liǎo）","激于义而死焉者也：激于义而死焉者也（被正义所激而死在这里的）","至于今：至于今","郡之贤士大夫请于当道：郡之贤士大夫请于当道（郡里的贤士大夫向当权者请求。当道，当权者）","即除逆阉废祠之址以葬之：即除逆阉废祠之址以葬之（就清理逆阉（魏忠贤）废弃的祠堂的遗址来安葬他们。除，清理；逆阉，指魏忠贤；阉音yān）","且立石于其墓之门：且立石于其墓之门（并且在他们的墓门前立石碑）","以旌其所为：以旌其所为（来表彰他们的所作所为。旌音jīng，表彰）","呜呼：呜呼（感叹词）","亦盛矣哉：亦盛矣哉（也真是盛大啊）","夫五人之死：夫五人之死（这五人的死）","去今之墓而葬焉：去今之墓而葬焉（距离现在修墓安葬他们）","其为时止十有一月耳：其为时止十有一月耳（那时间只有十一个月罢了。止，只；有，又）","夫十有一月之中：夫十有一月之中","凡富贵之子：凡富贵之子（凡是富贵人家的子弟）","慷慨得志之徒：慷慨得志之徒（慷慨得志的人）","其疾病而死：其疾病而死（他们患病而死）","死而湮没不足道者：死而湮没不足道者（死了而埋没不值得称道的。湮没音yānmò，埋没）","亦已众矣：亦已众矣（也已经很多了）","况草野之无闻者欤：况草野之无闻者欤（何况乡间没有声名的人呢。草野，乡间）","独五人之皦皦：独五人之皦皦（唯独这五人光明磊落。皦皦音jiǎojiǎo，光明的样子）","何也：何也（为什么呢）","予犹记周公之被逮：予犹记周公之被逮（我还记得周公被逮捕）","在丁卯三月之望：在丁卯三月之望（在丁卯年三月十五日。丁卯，1627年；望，农历每月十五）","吾社之行为士先者：吾社之行为士先者（我们复社中品行可以作为读书人表率的人。行为士先，品行是士人的表率）","为之声义：为之声义（替他伸张正义。声义，伸张正义）","敛赀财以送其行：敛赀财以送其行（募集钱财来送他启程。敛，募集；赀音zī，同「资」）","哭声震动天地：哭声震动天地","缇骑按剑而前：缇骑按剑而前（缇骑按着剑上前。缇骑音tíjì，明代锦衣卫的骑兵）","问：问","谁为哀者：谁为哀者（谁是为他哀哭的人）","众不能堪：众不能堪（众人不能忍受）","抶而仆之：抶而仆之（把他们打倒在地。抶音chì，鞭打；仆，打倒）","是时以大中丞抚吴者为魏之私人毛一鹭：是时以大中丞抚吴者为魏之私人毛一鹭（这时以大中丞身份巡抚吴地的是魏忠贤的私党毛一鹭。大中丞，官名；抚吴，巡抚吴地；私人，私党）","公之逮所由使也：公之逮所由使也（周公的逮捕就是由他主使的）","吴之民方痛心焉：吴之民方痛心焉（吴地的百姓正痛心于这件事）","于是乘其厉声以呵：于是乘其厉声以呵（于是趁着他厉声呵斥的时候）","则噪而相逐：则噪而相逐（就喊叫着追赶他。噪，喊叫）","中丞匿于溷藩以免：中丞匿于溷藩以免（中丞藏在厕所里才得以逃脱。匿音nì，藏；溷藩音hùnfān，厕所）","既而以吴民之乱请于朝：既而以吴民之乱请于朝（不久以吴地百姓作乱的罪名向朝廷请示）","按诛五人：按诛五人（追究斩杀了五个人。按，追究）","曰颜佩韦、杨念如、马杰、沈扬、周文元：曰颜佩韦、杨念如、马杰、沈扬、周文元","即今之傫然在墓者也：即今之傫然在墓者也（就是现在聚集在墓中的这五个人。傫然音lěirán，聚集的样子）","然五人之当刑也：然五人之当刑也（然而这五人临刑的时候）","意气扬扬：意气扬扬（意气昂扬）","呼中丞之名而詈之：呼中丞之名而詈之（喊着中丞的名字骂他。詈音lì，骂）","谈笑以死：谈笑以死（谈笑着死去）","断头置城上：断头置城上（砍下的头放在城上）","颜色不少变：颜色不少变（脸色一点也没有改变。少，稍微）","有贤士大夫发五十金：有贤士大夫发五十金（有贤士大夫拿出五十两银子）","买五人之脰而函之：买五人之脰而函之（买下五人的头用匣子装起来。脰音dòu，颈项，指头；函，匣子，此指用匣子装）","卒与尸合：卒与尸合（最终和尸体合在一起）","故今之墓中全乎为五人也：故今之墓中全乎为五人也（所以现在墓中是完整的五个人）","嗟乎：嗟乎（感叹词）","大阉之乱：大阉之乱（大宦官（魏忠贤）作乱的时候）","缙绅而能不易其志者：缙绅而能不易其志者（士大夫能够不改变自己志向的人。缙绅音jìnshēn，士大夫）","四海之大：四海之大（天下这么大）","有几人欤：有几人欤（有几个人呢）","而五人生于编伍之间：而五人生于编伍之间（而这五人生于民间。编伍，民间，古代户籍编制五家为伍）","素不闻诗书之训：素不闻诗书之训（向来没有听到过诗书的教诲）","激昂大义：激昂大义（被大义所激励）","蹈死不顾：蹈死不顾（踏上死地也不回头。蹈，踏）","亦曷故哉：亦曷故哉（又是什么缘故呢。曷同「何」）","且矫诏纷出：且矫诏纷出（况且假托的皇帝命令纷纷传出。矫诏，假托的皇帝命令）","钩党之捕遍于天下：钩党之捕遍于天下（牵连东林党人的逮捕遍布天下。钩党，牵连同党）","卒以吾郡之发愤一击：卒以吾郡之发愤一击（最终因为我们吴郡百姓的发愤一击）","不敢复有株治：不敢复有株治（不敢再有所牵连治罪。株治，牵连治罪）","大阉亦逡巡畏义：大阉亦逡巡畏义（魏忠贤也犹豫不决畏惧正义。逡巡音qūnxún，犹豫不决）","非常之谋难于猝发：非常之谋难于猝发（篡夺帝位的阴谋难以突然发动。非常之谋，指篡夺帝位的阴谋；猝音cù，突然）","待圣人之出而投缳道路：待圣人之出而投缳道路（等到崇祯皇帝即位就在路上自缢了。圣人，指崇祯皇帝；投缳，自缢；缳音huán，绳圈）","不可谓非五人之力也：不可谓非五人之力也（不能说不是这五人的力量啊）","由是观之：由是观之（由此看来）","则今之高爵显位：则今之高爵显位（那么现在那些高官显位的人）","一旦抵罪：一旦抵罪（一旦犯罪受惩罚。抵罪，犯罪受惩罚）","或脱身以逃：或脱身以逃（有的脱身逃跑）","不能容于远近：不能容于远近（不能被远近的人容纳）","而又有剪发杜门：而又有剪发杜门（又有剪发出家、闭门不出的。杜门，闭门）","佯狂不知所之者：佯狂不知所之者（假装疯狂不知逃到哪里去的。佯狂，假装疯狂）","其辱人贱行：其辱人贱行（他们可耻的人格、下贱的行为）","视五人之死：视五人之死（比起这五人的死）","轻重固何如哉：轻重固何如哉（轻重到底怎么样呢）","是以蓼洲周公忠义暴于朝廷：是以蓼洲周公忠义暴于朝廷（因此蓼洲周公的忠义显露在朝廷。暴音pù，显露）","赠谥褒美：赠谥褒美（追赠的谥号美好。谥音shì，谥号）","显荣于身后：显荣于身后（在死后显耀荣耀）","而五人亦得以加其土封：而五人亦得以加其土封（而这五人也能够修建坟墓。加其土封，修建坟墓）","列其姓名于大堤之上：列其姓名于大堤之上（在大堤上刻上他们的姓名）","凡四方之士无不有过而拜且泣者：凡四方之士无不有过而拜且泣者（凡是四方的士人没有不经过他们的墓前跪拜并且哭泣的）","斯固百世之遇也：斯固百世之遇也（这真是百代难得的遭遇啊）","不然：不然（不这样的话）","令五人者保其首领：令五人者保其首领（假使这五人保全他们的头颅。首领，头颅）","以老于户牖之下：以老于户牖之下（在家中老死。户牖音hùyǒu，门窗，指家）","则尽其天年：则尽其天年（就能够享尽他们的天年）","人皆得以隶使之：人皆得以隶使之（人人都能够像奴隶一样使唤他们）","安能屈豪杰之流：安能屈豪杰之流（怎么能够使豪杰之流屈身。屈，使……屈身）","扼腕墓道：扼腕墓道（在墓前扼腕叹息。扼腕，用手握腕，表示激动）","发其志士之悲哉：发其志士之悲哉（抒发他们有志之士的悲愤呢）","故余与同社诸君子：故余与同社诸君子（所以我和同社的各位君子）","哀斯墓之徒有其石也：哀斯墓之徒有其石也（哀叹这墓只有那块石碑）","而为之记：而为之记（而为它写了这篇记）","亦以明死生之大：亦以明死生之大（也用来阐明死生的重大意义）","匹夫之有重于社稷也：匹夫之有重于社稷也（普通百姓对国家也有重要作用啊。社稷，国家）","贤士大夫者：贤士大夫者（前面提到的贤士大夫）","冏卿因之吴公：冏卿因之吴公（冏卿吴默，字因之。冏卿音jiǒngqīng，太仆寺卿）","太史文起文公、孟长姚公也：太史文起文公、孟长姚公也（太史文震孟，字文起；姚希孟，字孟长。太史，翰林院编修）"]
  },
  "项脊轩志|归有光": {
    s: "全文（节选）分四层：第一层写项脊轩的修葺和环境——「项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注……又北向，不能得日，日过午已昏」，写轩的破旧狭小；「余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然」，写修葺后的明亮；「又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭阶寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱」，写轩中的清幽可爱；第二层写家庭的变迁——「然余居于此，多可喜，亦多可悲」，承上启下；「先是庭中通南北为一。迨诸父异爨，内外多置小门墙，往往而是。东犬西吠，客逾庖而宴，鸡栖于厅。庭中始为篱，已为墙，凡再变矣」，写家庭的分崩离析；第三层写对亲人的怀念——「家有老妪，尝居于此。妪，先大母婢也，乳二世，先妣抚之甚厚」，通过老妪回忆母亲——「娘以指叩门扉曰：『儿寒乎？欲食乎？』」，「语未毕，余泣，妪亦泣」；通过祖母的回忆——「吾儿，久不见若影，何竟日默默在此，大类女郎也」，「吾家读书久不效，儿之成，则可待乎」，「此吾祖太常公宣德间执此以朝，他日汝当用之」，「瞻顾遗迹，如在昨日，令人长号不自禁」；第四层写对妻子的怀念——「余既为此志，后五年，吾妻来归，时至轩中，从余问古事，或凭几学书」，「吾妻归宁，述诸小妹语曰：『闻姊家有阁子，且何谓阁子也？』」，「其后六年，吾妻死，室坏不修」，「庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣」，以枇杷树的亭亭如盖写对妻子的深切怀念——树已长大，人已逝去，物是人非，含蓄深沉。全文以小见大、细节生动、情感真挚、含蓄深沉，「庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣」成为千古名句，是抒情散文的典范。",
    b: "归有光（明代散文家，字熙甫，号震川，「唐宋派」代表）这篇《项脊轩志》通过记述书斋项脊轩的变迁和家庭琐事，抒发了对亲人的怀念和对家庭兴衰的感慨，「庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣」是千古名句，是中国古代抒情散文的千古名篇。",
    n: ["项脊轩志：篇名，归有光作，项脊轩，作者的书斋名","项脊轩：项脊轩","旧南阁子也：旧南阁子也（是原来的南阁子）","室仅方丈：室仅方丈（屋子只有一丈见方。方丈，一丈见方）","可容一人居：可容一人居","百年老屋：百年老屋","尘泥渗漉：尘泥渗漉（泥土从屋顶漏下。渗漉音shènlù，渗漏）","雨泽下注：雨泽下注（雨水往下流。下注，往下流）","每移案：每移案（每次移动书桌）","顾视无可置者：顾视无可置者（环顾四周没有可以放置的地方）","又北向：又北向（又朝北）","不能得日：不能得日（不能得到阳光）","日过午已昏：日过午已昏（太阳过了中午就昏暗了）","余稍为修葺：余稍为修葺（我稍微修理了一下。修葺音xiūqì，修理）","使不上漏：使不上漏（使它不从上面漏雨）","前辟四窗：前辟四窗（前面开了四扇窗）","垣墙周庭：垣墙周庭（用围墙围绕院子。垣墙音yuánqiáng，围墙）","以当南日：以当南日（来挡住南面射来的日光。当，挡住）","日影反照：日影反照（日光反照）","室始洞然：室始洞然（屋子才明亮了。洞然，明亮的样子）","又杂植兰桂竹木于庭：又杂植兰桂竹木于庭（又在庭院里杂乱地种了兰桂竹木）","旧时栏楯：旧时栏楯（旧时的栏杆。栏楯音lánshǔn，栏杆）","亦遂增胜：亦遂增胜（也就增加了美景。胜，美景）","借书满架：借书满架","偃仰啸歌：偃仰啸歌（俯仰之间，长啸歌吟。偃仰，俯仰）","冥然兀坐：冥然兀坐（静静地端坐。冥然，静静的样子；兀坐，端坐）","万籁有声：万籁有声（各种声音都能听到。万籁，各种声音）","而庭阶寂寂：而庭阶寂寂（而庭院台阶静悄悄的）","小鸟时来啄食：小鸟时来啄食","人至不去：人至不去（人来了也不离开）","三五之夜：三五之夜（农历每月十五的夜晚。三五，十五）","明月半墙：明月半墙（明月照在半墙上）","桂影斑驳：桂影斑驳（桂树的影子错落。斑驳，错落）","风移影动：风移影动","珊珊可爱：珊珊可爱（树影摇曳的样子可爱。珊珊，摇曳的样子）","然余居于此：然余居于此（然而我住在这里）","多可喜：多可喜（有很多可喜的事）","亦多可悲：亦多可悲（也有很多可悲的事）","先是庭中通南北为一：先是庭中通南北为一（在这之前庭院南北相通成为一体）","迨诸父异爨：迨诸父异爨（等到伯父叔父们分家。迨音dài，等到；诸父，伯父叔父；异爨音yìcuàn，分家，各起炉灶）","内外多置小门墙：内外多置小门墙（内外设置了很多小门墙）","往往而是：往往而是（到处都是）","东犬西吠：东犬西吠（东边的狗对着西边叫。吠音fèi，狗叫）","客逾庖而宴：客逾庖而宴（客人越过厨房去赴宴。逾，越过；庖音páo，厨房）","鸡栖于厅：鸡栖于厅（鸡栖息在厅堂上）","庭中始为篱：庭中始为篱（庭院中开始是篱笆）","已为墙：已为墙（后来是墙）","凡再变矣：凡再变矣（总共变了两次了。凡，总共；再，两次）","家有老妪：家有老妪（家里有个老婆婆。妪音yù，老婆婆）","尝居于此：尝居于此（曾经住在这里）","妪：妪（老婆婆）","先大母婢也：先大母婢也（是去世的祖母的婢女。先大母，去世的祖母）","乳二世：乳二世（喂养了两代人。乳，喂养）","先妣抚之甚厚：先妣抚之甚厚（去世的母亲待她很好。先妣音xiānbǐ，去世的母亲）","室西连于中闺：室西连于中闺（房子西边连着内室。中闺，内室）","先妣尝一至：先妣尝一至（去世的母亲曾经来过一次）","妪每谓余曰：妪每谓余曰（老婆婆常常对我说）","某所：某所（某个地方）","而母立于兹：而母立于兹（你的母亲站在这里。而，你；兹，这里）","妪又曰：妪又曰","汝姊在吾怀：汝姊在吾怀（你姐姐在我怀里）","呱呱而泣：呱呱而泣（呱呱地哭。呱呱音gūgū，婴儿哭声）","娘以指叩门扉曰：娘以指叩门扉曰（母亲用手指敲着门说。叩，敲；门扉，门）","儿寒乎：儿寒乎（孩子冷吗）","欲食乎：欲食乎（想吃东西吗）","吾从板外相为应答：吾从板外相为应答（我从门外应答她）","语未毕：语未毕（话还没说完）","余泣：余泣（我哭了）","妪亦泣：妪亦泣（老婆婆也哭了）","余自束发读书轩中：余自束发读书轩中（我从十五岁起在轩中读书。束发，古代男子十五岁束发，表示成童）","一日：一日","大母过余曰：大母过余曰（祖母来看我说。过，探望）","吾儿：吾儿（我的孩子）","久不见若影：久不见若影（很久没见到你的影子。若，你）","何竟日默默在此：何竟日默默在此（为什么整天默默地在这里。竟日，整天）","大类女郎也：大类女郎也（很像个女孩子呢。大类，很像）","比去：比去（等到离开。比，等到）","以手阖门：以手阖门（用手关上门。阖音hé，关）","自语曰：自语曰（自言自语说）","吾家读书久不效：吾家读书久不效（我们家读书很久没有成效了。不效，没有成效，指没人考中功名）","儿之成：儿之成（孩子的成功）","则可待乎：则可待乎（就可以等待了吧）","顷之：顷之（过了一会儿）","持一象笏至：持一象笏至（拿着一个象牙笏板来了。象笏，象牙笏板，古代大臣上朝时拿的手板。笏音hù）","曰：曰","此吾祖太常公宣德间执此以朝：此吾祖太常公宣德间执此以朝（这是我祖父太常公在宣德年间拿着它上朝用的。太常公，归有光祖母的祖父夏昶，曾任太常寺卿；宣德，明宣宗年号）","他日汝当用之：他日汝当用之（将来你应当用它）","瞻顾遗迹：瞻顾遗迹（瞻仰回顾旧物）","如在昨日：如在昨日（就像在昨天一样）","令人长号不自禁：令人长号不自禁（令人忍不住大哭。长号音chángháo，大哭）","轩东故尝为厨：轩东故尝为厨（轩的东边曾经是厨房）","人往：人往（人去那里）","从轩前过：从轩前过（从轩前经过）","余扃牖而居：余扃牖而居（我关着窗户住在里面。扃牖音jiōngyǒu，关窗）","久之：久之（时间长了）","能以足音辨人：能以足音辨人（能够凭脚步声辨别是谁）","轩凡四遭火：轩凡四遭火（轩总共遭遇了四次火灾）","得不焚：得不焚（能够不被烧毁）","殆有神护者：殆有神护者（大概有神灵保护吧。殆，大概）","余既为此志：余既为此志（我已经写了这篇志）","后五年：后五年（过后五年）","吾妻来归：吾妻来归（我的妻子嫁到我家来。来归，嫁到我家）","时至轩中：时至轩中（时常到轩中来）","从余问古事：从余问古事（向我问古代的事）","或凭几学书：或凭几学书（有时靠着几案学写字。几，几案）","吾妻归宁：吾妻归宁（我的妻子回娘家探亲。归宁，回娘家探亲）","述诸小妹语曰：述诸小妹语曰（转述各位小妹的话说）","闻姊家有阁子：闻姊家有阁子（听说姐姐家有个阁子）","且何谓阁子也：且何谓阁子也（那么什么是阁子呢）","其后六年：其后六年（那以后六年）","吾妻死：吾妻死（我的妻子去世了）","室坏不修：室坏不修（屋子坏了没有修理）","其后二年：其后二年（那以后两年）","余久卧病无聊：余久卧病无聊（我长久卧病在床无聊）","乃使人复葺南阁子：乃使人复葺南阁子（才派人重新修理南阁子）","其制稍异于前：其制稍异于前（它的形制稍微和以前不同。制，形制）","然自后余多在外：然自后余多在外（然而从那以后我多在外面）","不常居：不常居（不常居住）","庭有枇杷树：庭有枇杷树（庭院中有一棵枇杷树）","吾妻死之年所手植也：吾妻死之年所手植也（是我妻子去世那年亲手种植的）","今已亭亭如盖矣：今已亭亭如盖矣（现在已经高高耸立像伞盖一样了。亭亭，高高耸立；盖，伞盖）"]
  },
  "马上作|戚继光": {
    s: "首两句「南北驱驰报主情，江花边月笑平生」写南北驱驰报主情、江花边月笑平生，以「南北驱驰」写南征北战的辛劳、以「江花边月笑平生」写对军旅生涯的旷达——江边的花、边关的月，笑看平生；后两句「一年三百六十日，多是横戈马上行」是名句——一年三百六十日，大多是横持戈矛在马上行进，以「三百六十日」「多是」写军旅生活的紧张和辛劳，全诗语言明快、形象生动、情感豪迈、气概雄壮，「一年三百六十日，多是横戈马上行」成为名句，是七绝的名篇。",
    b: "戚继光（明代抗倭名将，军事家，字元敬，号南塘）这首《马上作》写他南征北战的军旅生涯，「一年三百六十日，多是横戈马上行」是名句，是七绝的名篇。",
    n: ["马上作：诗题，在马上所作","南北驱驰报主情：南北驱驰报主情（南北驱驰，在南方北方奔走；报主情，报答君主的恩情）","江花边月笑平生：江花边月笑平生（江边的花、边关的月，笑看平生。边月，边关的月亮）","一年三百六十日：一年三百六十日","多是横戈马上行：多是横戈马上行（大多是横持戈矛在马上行进。横戈，横持戈矛）"]
  },
  "望阙台|戚继光": {
    s: "首两句「十年驱驰海色寒，孤臣于此望宸銮」写十年驱驰海色寒、孤臣于此望宸銮，以「十年驱驰」写抗倭的辛劳、以「海色寒」写环境的艰苦、以「孤臣望宸銮」写对朝廷的忠诚——孤臣在这里遥望朝廷；后两句「繁霜尽是心头血，洒向千峰秋叶丹」是名句——繁霜全是心头的热血，洒向千峰把秋叶都染红了，以「繁霜尽是心头血」的比喻写抗倭的热血、以「洒向千峰秋叶丹」写热血染红了秋叶，比喻奇特、情感深沉、气概雄壮，全诗意境壮阔、比喻奇特、情感深沉、忠诚感人，「繁霜尽是心头血，洒向千峰秋叶丹」成为名句，是七绝的名篇。",
    b: "戚继光这首《望阙台》写他在东南沿海抗倭十年、遥望朝廷的感慨，「繁霜尽是心头血，洒向千峰秋叶丹」是名句，是七绝的名篇。",
    n: ["望阙台：诗题，望阙台，戚继光在福建所建的台名。阙，宫阙，代指朝廷","十年驱驰海色寒：十年驱驰海色寒（十年驱驰，在海上驱驰十年；海色寒，海面景色寒峭）","孤臣于此望宸銮：孤臣于此望宸銮（孤臣，戚继光自称；宸銮，皇帝的车驾，代指朝廷。宸音chén）","繁霜尽是心头血：繁霜尽是心头血（繁霜，浓重的霜；心头血，心中的热血）","洒向千峰秋叶丹：洒向千峰秋叶丹（洒向千峰，秋叶都染红了。丹，红色）"]
  },
  "秋望|李梦阳": {
    s: "首联「黄河水绕汉宫墙，河上秋风雁几行」写黄河水绕汉宫墙、河上秋风雁几行，以黄河、秋风、雁行写秋日的苍茫；颔联「客子过壕追野马，将军弢箭射天狼」写客子过壕追野马、将军弢箭射天狼，以「客子追野马」写游子的漂泊、以「将军弢箭射天狼」写将军的壮志——用屈原「射天狼」典故写抗击敌人的壮志；颈联「黄尘古渡迷飞挽，白月横空冷战场」写黄尘古渡迷飞挽、白月横空冷战场，以「黄尘古渡」「白月横空」写战场的荒凉——黄尘迷漫了古渡的运粮车船，白月横空照着冷寂的战场；尾联「闻道朔方多勇略，只今谁是郭汾阳」写闻道朔方多勇略、只今谁是郭汾阳，以「谁是郭汾阳」的反问写对国事的忧虑——听说北方多勇敢有谋略的人，但现在谁是像郭子仪那样的名将呢？全诗意境苍茫、用典贴切、对仗工稳、情感深沉、忧虑国事，「只今谁是郭汾阳」成为名句，是七律的名篇。",
    b: "李梦阳（明代文学家，「前七子」领袖，字献吉，号空同子）这首《秋望》写秋日远望的景色和对国事的忧虑，「只今谁是郭汾阳」是名句，是七律的名篇。",
    n: ["秋望：诗题，秋日远望","黄河水绕汉宫墙：黄河水绕汉宫墙（汉宫墙，代指明代宫墙）","河上秋风雁几行：河上秋风雁几行","客子过壕追野马：客子过壕追野马（客子，离家在外的人；壕，护城河；野马，指野外的雾气。用《庄子》「野马也，尘埃也」）","将军弢箭射天狼：将军弢箭射天狼（弢箭，把箭装入弓袋。弢音tāo，弓袋，此指装入弓袋；天狼，星名，代指敌人。用屈原「举长矢兮射天狼」）","黄尘古渡迷飞挽：黄尘古渡迷飞挽（黄尘，黄色的尘土；古渡，古老的渡口；飞挽，飞快运送粮草的车船。挽音wǎn）","白月横空冷战场：白月横空冷战场","闻道朔方多勇略：闻道朔方多勇略（朔方，北方；勇略，勇敢有谋略）","只今谁是郭汾阳：只今谁是郭汾阳（郭汾阳，郭子仪，唐代名将，封汾阳郡王。指现在谁是像郭子仪那样的名将呢）"]
  },
  "天平山中|杨基": {
    s: "首两句「细雨茸茸湿楝花，南风树树熟枇杷」写细雨茸茸湿楝花、南风树树熟枇杷，以「细雨湿楝花」「南风熟枇杷」写天平山的初夏景色——细雨蒙蒙打湿了楝花，南风吹熟了树树枇杷，色彩明丽、香气扑鼻；后两句「徐行不记山深浅，一路莺啼送到家」写徐行不记山深浅、一路莺啼送到家，以「徐行不记山深浅」写游山的悠闲——慢慢走，不记得山的深浅，以「一路莺啼送到家」写归途的欢乐——一路黄莺啼叫送我到家，全诗意境明丽、画面生动、情感悠闲、清新自然，「徐行不记山深浅，一路莺啼送到家」成为名句，是七绝的名篇。",
    b: "杨基（明初诗人，「吴中四杰」之一，字孟载，号眉庵）这首《天平山中》写天平山的初夏景色，「一路莺啼送到家」是名句，是七绝的名篇。",
    n: ["天平山中：诗题，天平山，在今江苏苏州","细雨茸茸湿楝花：细雨茸茸湿楝花（茸茸，细雨蒙蒙的样子；楝花，楝树的花，楝音liàn，楝树，初夏开花）","南风树树熟枇杷：南风树树熟枇杷（南风，夏天的风；枇杷，水果名）","徐行不记山深浅：徐行不记山深浅（徐行，慢慢走；不记山深浅，不记得山的深浅）","一路莺啼送到家：一路莺啼送到家（一路黄莺啼叫送我到家）"]
  },
  "朝天子·咏喇叭|王磐": {
    s: "这首小令以「喇叭，唢呐，曲儿小腔儿大」开篇，以「曲儿小腔儿大」写喇叭的特点——曲子短小但嗓门大，暗喻宦官地位低但权势大；「官船来往乱如麻，全仗你抬声价」写官船来往乱如麻、全靠喇叭抬高声价，以「官船乱如麻」写宦官的权势、以「抬声价」写喇叭的作用——宦官出巡时吹喇叭壮声势；「军听了军愁，民听了民怕，哪里去辨甚么真共假」写军听了军愁、民听了民怕、哪里去辨甚么真共假，以「军愁民怕」写喇叭（宦官）给军民带来的痛苦、以「哪里辨真假」写宦官作威作福、真假难辨；「眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢」写眼见的吹翻了这家、吹伤了那家、只吹的水尽鹅飞罢，以「吹翻这家」「吹伤那家」写宦官对百姓的摧残、以「水尽鹅飞」写民穷财尽——水干了鹅飞了，比喻百姓被搜刮一空，全曲语言通俗、比喻贴切、讽刺辛辣、幽默生动，「只吹的水尽鹅飞罢」成为名句，是元明散曲中讽刺文学的千古名篇。",
    b: "王磐（明代散曲家，字鸿渐，号西楼）这首《朝天子·咏喇叭》以喇叭为题，讽刺明代宦官当权、作威作福、鱼肉百姓的现实，「只吹的水尽鹅飞罢」是名句，是元明散曲中讽刺文学的千古名篇。",
    n: ["朝天子：曲牌名","咏喇叭：题目","喇叭：喇叭","唢呐：唢呐（乐器名。唢音suǒ，呐音nà）","曲儿小腔儿大：曲儿小腔儿大（曲子短小但嗓门大）","官船来往乱如麻：官船来往乱如麻（官船来往多得乱如麻）","全仗你抬声价：全仗你抬声价（全靠你抬高声价。你，指喇叭）","军听了军愁：军听了军愁（军队听了军队发愁）","民听了民怕：民听了民怕（百姓听了百姓害怕）","哪里去辨甚么真共假：哪里去辨甚么真共假（哪里去分辨什么真和假呢。共，和）","眼见的吹翻了这家：眼见的吹翻了这家（眼看着吹翻了这家）","吹伤了那家：吹伤了那家","只吹的水尽鹅飞罢：只吹的水尽鹅飞罢（只吹得水干了鹅飞了罢了。水尽鹅飞，比喻民穷财尽）"]
  },
  "白燕|袁凯": {
    s: "首联「故国飘零事已非，旧时王谢见应稀」写故国飘零事已非、旧时王谢见应稀，以「故国飘零」写漂泊之感、以「旧时王谢」用刘禹锡典故写世事变迁——旧时王谢堂前的燕子，现在应该很少见到了；颔联「月明汉水初无影，雪满梁园尚未归」写月明汉水初无影、雪满梁园尚未归，以「月明汉水无影」「雪满梁园未归」写白燕的洁白——月明时汉水上没有影子（白燕与月光融为一体），雪满梁园时还没有归来（白燕与雪融为一体），比喻新奇、对仗工稳；颈联「柳絮池塘香入梦，梨花庭院冷侵衣」写柳絮池塘香入梦、梨花庭院冷侵衣，以「柳絮池塘」「梨花庭院」写白燕的生活环境——柳絮飘飞、梨花盛开，香气入梦、寒冷侵衣；尾联「赵家姊妹多相忌，莫向昭阳殿里飞」写赵家姊妹多相忌、莫向昭阳殿里飞，以「赵家姊妹」「昭阳殿」用赵飞燕典故写避祸之心——宫中妃嫔多相妒忌，不要向昭阳殿里飞，暗喻不要卷入官场纷争，全诗用典丰富、比喻新奇、对仗工稳、情感深沉、含蓄隽永，「月明汉水初无影，雪满梁园尚未归」成为名句，是七律的名篇。",
    b: "袁凯（明初诗人，字景文，号海叟，以《白燕》诗闻名，人称「袁白燕」）这首《白燕》咏白燕，以白燕自喻，抒发漂泊之感和避祸之心，「月明汉水初无影，雪满梁园尚未归」是名句，是七律的名篇。",
    n: ["白燕：诗题","故国飘零事已非：故国飘零事已非（故国，故乡；飘零，漂泊）","旧时王谢见应稀：旧时王谢见应稀（旧时王谢，用刘禹锡「旧时王谢堂前燕」典故，指豪门贵族；见应稀，应该很少见到了）","月明汉水初无影：月明汉水初无影（月明时汉水上最初没有影子）","雪满梁园尚未归：雪满梁园尚未归（雪满梁园时还没有归来。梁园，汉梁孝王的兔园，代指贵族园林）","柳絮池塘香入梦：柳絮池塘香入梦（柳絮飘飞的池塘，香气进入梦中）","梨花庭院冷侵衣：梨花庭院冷侵衣（梨花盛开的庭院，寒冷侵入衣服）","赵家姊妹多相忌：赵家姊妹多相忌（赵家姊妹，赵飞燕、赵合德姊妹，汉成帝的宠妃，多相妒忌。代指宫中妃嫔）","莫向昭阳殿里飞：莫向昭阳殿里飞（昭阳殿，汉代宫殿，赵飞燕所居。不要向昭阳殿里飞）"]
  },
  "京师得家书|袁凯": {
    s: "首两句「江水三千里，家书十五行」写江水三千里、家书十五行，以「三千里」写离家之远、以「十五行」写家信之短——三千里外的家信只有十五行；后两句「行行无别语，只道早还乡」写行行无别语、只道早还乡，以「行行无别语」写家信的内容——每行没有别的话，以「只道早还乡」写家人的期盼——只说早点还乡，全诗语言朴素、情感真挚、以小见大、含蓄深沉，「行行无别语，只道早还乡」成为名句，是五绝的名篇。",
    b: "袁凯这首《京师得家书》写在京城收到家信的感受，「行行无别语，只道早还乡」是名句，是五绝的名篇。",
    n: ["京师得家书：诗题，京师，京城；家书，家信","江水三千里：江水三千里（江水，指长江，从家乡到京城的距离）","家书十五行：家书十五行（家信只有十五行）","行行无别语：行行无别语（每行没有别的话）","只道早还乡：只道早还乡（只说早点还乡）"]
  },
  "满井游记|袁宏道": {
    s: "全文（节选）分三层：第一层写出游前的压抑——「燕地寒，花朝节后，余寒犹厉。冻风时作，作则飞沙走砾。局促一室之内，欲出不得。每冒风驰行，未百步辄返」，以「余寒犹厉」「飞沙走砾」「局促一室」写燕地春天的寒冷和出游的困难；第二层写满井的春色——「廿二日天稍和，偕数友出东直，至满井。高柳夹堤，土膏微润，一望空阔，若脱笼之鹄」，以「若脱笼之鹄」写出游的欣喜；「于时冰皮始解，波色乍明，鳞浪层层，清澈见底，晶晶然如镜之新开而冷光之乍出于匣也」，以「镜之新开」比喻春水的清澈；「山峦为晴雪所洗，娟然如拭，鲜妍明媚，如倩女之靧面而髻鬟之始掠也」，以「倩女靧面」比喻山峦的美丽；「柳条将舒未舒，柔梢披风，麦田浅鬣寸许」，以「浅鬣寸许」比喻麦苗的短密；「游人虽未盛，泉而茗者，罍而歌者，红装而蹇者，亦时时有」，写游人的活动；「风力虽尚劲，然徒步则汗出浃背」，写春游的欢乐；「凡曝沙之鸟，呷浪之鳞，悠然自得，毛羽鳞鬣之间皆有喜气」，以鸟鱼的「喜气」写春天的生机；第三层写感悟——「始知郊田之外未始无春，而城居者未之知也」，以「城居者未之知」写对春天的发现——春天在郊野，不在城里；「夫不能以游堕事，潇然于山石草木之间者，惟此官也」，以「惟此官」写自己的闲职和旷达；「而此地适与余近，余之游将自此始，恶能无纪」，点明作记的缘由。全文比喻新奇、描写生动、情感真挚、旷达自然，「始知郊田之外未始无春，而城居者未之知也」成为名句，是游记散文的典范，「公安派」「独抒性灵」的代表作。",
    b: "袁宏道（明代文学家，「公安派」领袖，字中郎，号石公）这篇《满井游记》写他在北京满井的春游，以「始知郊田之外未始无春，而城居者未之知也」写对春天的发现，是中国古代游记散文的千古名篇，「公安派」「独抒性灵」的代表作。",
    n: ["满井游记：篇名，袁宏道作，满井，在北京东直门东北","燕地寒：燕地寒（燕地，北京一带；寒，寒冷）","花朝节后：花朝节后（花朝节，农历二月十二，百花生日）","余寒犹厉：余寒犹厉（余寒，残余的寒气；犹厉，还很猛烈）","冻风时作：冻风时作（冻风，冷风；时作，时常刮起）","作则飞沙走砾：作则飞沙走砾（一刮就飞沙走石。砾音lì，小石子）","局促一室之内：局促一室之内（局促，拘束。拘束在一间屋子里面）","欲出不得：欲出不得（想出去也不能）","每冒风驰行：每冒风驰行（每次冒着风快走）","未百步辄返：未百步辄返（不到百步就返回了。辄音zhé，就）","廿二日天稍和：廿二日天稍和（廿二日，二十二日；稍和，稍微暖和。廿音niàn，二十）","偕数友出东直：偕数友出东直（偕，同；东直，东直门）","至满井：至满井","高柳夹堤：高柳夹堤（高大的柳树夹着堤岸）","土膏微润：土膏微润（土地肥沃微微湿润。土膏，肥沃的土地）","一望空阔：一望空阔","若脱笼之鹄：若脱笼之鹄（像逃出笼子的天鹅。鹄音hú，天鹅）","于时冰皮始解：于时冰皮始解（在这时冰面开始融化。冰皮，冰面）","波色乍明：波色乍明（水波的颜色刚刚明亮。乍，刚刚）","鳞浪层层：鳞浪层层（像鱼鳞一样的波浪层层叠叠）","清澈见底：清澈见底","晶晶然如镜之新开而冷光之乍出于匣也：晶晶然如镜之新开而冷光之乍出于匣也（亮晶晶的像刚打开的镜子，冷光刚刚从镜匣中射出。晶晶然，亮晶晶的样子）","山峦为晴雪所洗：山峦为晴雪所洗（山峦被晴天的积雪洗过）","娟然如拭：娟然如拭（美好的样子像擦过一样。娟然，美好的样子）","鲜妍明媚：鲜妍明媚（鲜艳明媚）","如倩女之靧面而髻鬟之始掠也：如倩女之靧面而髻鬟之始掠也（像美丽的女子洗了脸、刚刚梳好发髻。倩女，美丽的女子；靧音huì，洗脸；髻鬟音jìhuán，发髻；掠，梳理）","柳条将舒未舒：柳条将舒未舒（柳条将要舒展还没有舒展）","柔梢披风：柔梢披风（柔软的柳梢在风中散开。披风，在风中散开）","麦田浅鬣寸许：麦田浅鬣寸许（麦田里的麦苗像短短的鬃毛，一寸左右。鬣音liè，兽类的鬃毛）","游人虽未盛：游人虽未盛（游人虽然还不多）","泉而茗者：泉而茗者（用泉水煮茶的人。茗，茶，此指煮茶）","罍而歌者：罍而歌者（端着酒杯唱歌的人。罍音léi，酒杯）","红装而蹇者：红装而蹇者（穿着艳装骑驴的人。蹇音jiǎn，驴）","亦时时有：亦时时有（也时时有）","风力虽尚劲：风力虽然还强劲","然徒步则汗出浃背：然徒步则汗出浃背（然而走路就汗流浃背。浃音jiā，湿透）","凡曝沙之鸟：凡曝沙之鸟（凡是在沙滩上晒太阳的鸟。曝音pù，晒太阳）","呷浪之鳞：呷浪之鳞（在波浪中吸水的鱼。呷音xiā，吸；鳞，代指鱼）","悠然自得：悠然自得","毛羽鳞鬣之间皆有喜气：毛羽鳞鬣之间皆有喜气（毛羽鳞鬣之间都有喜气。鬣，鱼鳍）","始知郊田之外未始无春：始知郊田之外未始无春（才知道郊野之外未尝没有春天）","而城居者未之知也：而城居者未之知也（而住在城里的人不知道啊）","夫不能以游堕事：夫不能以游堕事（不能因为游玩而耽误公事。堕音duò，耽误）","潇然于山石草木之间者：潇然于山石草木之间者（潇洒地在山石草木之间游玩的人）","惟此官也：惟此官也（只有我这个官啊。袁宏道当时任顺天府学教授，是个闲职）","而此地适与余近：而此地适与余近（而这个地方正好和我近）","余之游将自此始：余之游将自此始（我的游玩将从这里开始）","恶能无纪：恶能无纪（怎么能没有记录呢。恶音wū，怎么；纪同「记」，记录）","己亥之二月也：己亥之二月也（己亥年二月。己亥，1599年）"]
  },
  "明日歌|钱福": {
    s: "全诗分三层：第一层「明日复明日，明日何其多。我生待明日，万事成蹉跎」以「明日复明日」写拖延的习惯、以「明日何其多」写对明天的幻想、以「我生待明日，万事成蹉跎」写拖延的后果——一生等待明天，万事都虚度光阴；第二层「世人若被明日累，春去秋来老将至。朝看水东流，暮看日西坠」以「春去秋来老将至」写拖延的危害——春去秋来老年就到了，以「朝看水东流，暮看日西坠」写时间的流逝——早晨看水向东流，傍晚看太阳向西落，时间一去不复返；第三层「百年明日能几何，请君听我明日歌」以「百年明日能几何」的反问写明天的有限——人的一生能有多少个明天呢，以「请君听我明日歌」点明主旨，全诗语言通俗、反复咏叹、对比鲜明、哲理深刻、劝勉殷切，「明日复明日，明日何其多。我生待明日，万事成蹉跎」成为千古名句，是劝学名篇。",
    b: "钱福（明代文学家，字与谦，号鹤滩）这首《明日歌》劝人珍惜时间、不要拖延，「明日复明日，明日何其多。我生待明日，万事成蹉跎」是千古名句，是劝学名篇。",
    n: ["明日歌：诗题","明日复明日：明日复明日（明天又一个明天）","明日何其多：明日何其多（明天是多么多啊）","我生待明日：我生待明日（我一生等待明天）","万事成蹉跎：万事成蹉跎（万事都虚度光阴。蹉跎音cuōtuó，虚度光阴）","世人若被明日累：世人若被明日累（世人如果被明天拖累）","春去秋来老将至：春去秋来老将至（春去秋来老年就要到了）","朝看水东流：朝看水东流（早晨看水向东流）","暮看日西坠：暮看日西坠（傍晚看太阳向西落。坠，落下）","百年明日能几何：百年明日能几何（人的一生能有多少个明天呢。几何，多少）","请君听我明日歌：请君听我明日歌"]
  },
  "渡易水|陈子龙": {
    s: "首两句「并刀昨夜匣中鸣，燕赵悲歌最不平」写并刀昨夜匣中鸣、燕赵悲歌最不平，以「并刀匣中鸣」写杀伐的征兆——刀在匣中鸣叫，预示将有杀伐之事，以「燕赵悲歌」写慷慨悲壮的气概——燕赵多慷慨悲歌之士，最有不平之气；后两句「易水潺湲云草碧，可怜无处送荆卿」写易水潺湲云草碧、可怜无处送荆卿，以「易水潺湲」「云草碧」写易水的景色——易水慢慢流，云下的草碧绿，以「可怜无处送荆卿」用荆轲典故写悲凉——荆轲刺秦王前在易水告别，如今易水犹在，但已无人可送，暗喻抗清事业的艰难和无人可与同仇的悲凉，全诗用典贴切、意境苍凉、情感深沉、悲壮激昂，「可怜无处送荆卿」成为名句，是七绝的名篇。",
    b: "陈子龙（明末抗清英雄，文学家，「云间派」领袖，字卧子，号大樽）这首《渡易水》写渡易水时的感慨，以荆轲的典故抒发抗清的壮志和无人可送的悲凉，「可怜无处送荆卿」是名句，是七绝的名篇。",
    n: ["渡易水：诗题，易水，在今河北易县，荆轲刺秦王前在此告别","并刀昨夜匣中鸣：并刀昨夜匣中鸣（并刀，并州出产的刀，以锋利闻名；匣中鸣，刀在匣中鸣叫，古人认为刀鸣是将有杀伐之事的征兆）","燕赵悲歌最不平：燕赵悲歌最不平（燕赵，燕国赵国，今河北一带，古称「燕赵多慷慨悲歌之士」；悲歌，悲壮的歌声；不平，不平之气）","易水潺湲云草碧：易水潺湲云草碧（潺湲音chányuán，水慢慢流的样子；云草碧，云下的草碧绿）","可怜无处送荆卿：可怜无处送荆卿（荆卿，荆轲。可怜没有地方送别荆轲了——指荆轲已去，易水犹在，但已无人可送）"]
  },
  "点绛唇·春日风雨有感|陈子龙": {
    s: "上片「满眼韶华。东风惯是吹红去。几番烟雾。只有花难护」写满眼韶华、东风惯是吹红去，几番烟雾、只有花难护，以「东风吹红去」写春光的流逝、以「花难护」写对美好事物的无力保护——东风惯于把红花吹落，几番风雨烟雾，只有花难以保护，暗喻明朝的灭亡——美好的事物（明朝）难以保护；下片「梦里相思。故国王孙路。春无主。杜鹃啼处，泪洒胭脂雨」写梦里相思、故国王孙路，春无主、杜鹃啼处、泪洒胭脂雨，以「故国」写对明朝的思念、以「春无主」暗喻明朝灭亡后故国无主、以「杜鹃啼」写不如归去的悲思、以「泪洒胭脂雨」写亡国之痛——泪水洒在落花如雨的春天里，全词意境凄清、用典贴切、寓意深刻、情感深沉，「春无主！杜鹃啼处，泪洒胭脂雨」成为名句，是婉约词中寓含亡国之痛的名篇。",
    b: "陈子龙这首《点绛唇·春日风雨有感》写春日风雨中的感慨，以「春无主」暗喻明朝灭亡、故国无主，「泪洒胭脂雨」是名句，是婉约词中寓含亡国之痛的名篇。",
    n: ["点绛唇：词牌名","春日风雨有感：题目","满眼韶华：满眼韶华（韶华，美好的春光）","东风惯是吹红去：东风惯是吹红去（东风惯于把红花吹落。红，代指花）","几番烟雾：几番烟雾（几番风雨烟雾）","只有花难护：只有花难护（只有花难以保护）","梦里相思：梦里相思","故国王孙路：故国王孙路（故国，指明朝；王孙路，王孙公子的路，代指明朝的遗迹）","春无主：春无主（春天没有主人）","杜鹃啼处：杜鹃啼处（杜鹃啼叫的地方。杜鹃，鸟名，叫声似「不如归去」，古人以为杜鹃啼血）","泪洒胭脂雨：泪洒胭脂雨（泪水洒在胭脂般的雨里。胭脂雨，落花如雨）"]
  },
  "牧牛词|高启": {
    s: "全诗分三层：第一层「尔牛角弯环，我牛尾秃速。共拈短笛与长鞭，南陇东冈去相逐」写牧童的欢乐——你的牛角弯弯，我的牛尾秃速，共同拿着短笛和长鞭，到南陇东冈去互相追逐，以「角弯环」「尾秃速」写牛的特征、以「拈短笛长鞭」「南陇东冈相逐」写牧童的欢乐；第二层「日斜草远牛行迟，牛劳牛饥唯我知。牛上唱歌牛下坐，夜归还向牛边卧」写牧童与牛的亲密——太阳西斜草远牛走得慢，牛劳累牛饥饿只有我知道，在牛背上唱歌在牛下坐，夜晚回来还在牛边卧，以「牛劳牛饥唯我知」写牧童对牛的了解、以「牛上唱歌牛下坐」「夜归牛边卧」写牧童与牛的亲密；第三层「长年牧牛百不忧，但恐输租卖我牛」写牧童的忧虑——长年牧牛百样不忧愁，只怕交租要卖掉我的牛，以「百不忧」与「但恐」对比，写赋税剥削的残酷——牧童与牛相依为命，但赋税可能迫使他卖掉牛，全诗语言通俗、描写生动、情感真挚、对比鲜明、控诉深刻，「长年牧牛百不忧，但恐输租卖我牛」成为名句，是乐府诗的名篇。",
    b: "高启（明初诗人，「吴中四杰」之首，字季迪，号青丘子）这首《牧牛词》写牧童的生活，以「但恐输租卖我牛」写对赋税剥削的控诉，是乐府诗的名篇。",
    n: ["牧牛词：诗题","尔牛角弯环：尔牛角弯环（你的牛角弯弯的。尔，你）","我牛尾秃速：我牛尾秃速（我的牛尾巴稀疏短秃。秃速，稀疏短秃的样子）","共拈短笛与长鞭：共拈短笛与长鞭（共同拿着短笛和长鞭。拈音niān，拿）","南陇东冈去相逐：南陇东冈去相逐（到南边的田垄、东边的山冈去互相追逐。陇，田垄；冈，山冈）","日斜草远牛行迟：日斜草远牛行迟（太阳西斜草远牛走得慢）","牛劳牛饥唯我知：牛劳牛饥唯我知（牛劳累牛饥饿只有我知道）","牛上唱歌牛下坐：牛上唱歌牛下坐（在牛背上唱歌在牛下坐）","夜归还向牛边卧：夜归还向牛边卧（夜晚回来还在牛边卧着）","长年牧牛百不忧：长年牧牛百不忧（长年牧牛百样不忧愁）","但恐输租卖我牛：但恐输租卖我牛（只怕交租要卖掉我的牛。输租，交租）"]
  },
  "登泰山记|姚鼐": {
    s: "全文（节选）分五段：第一段写泰山的地理形势——「泰山之阳，汶水西流；其阴，济水东流。阳谷皆入汶，阴谷皆入济。当其南北分者，古长城也。最高日观峰，在长城南十五里」，以汶水、济水、古长城、日观峰写泰山的地理位置；第二段写登山的经过——「余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至于泰安」，写从京城到泰安的行程；「是月丁未，与知府朱孝纯子颍由南麓登。四十五里，道皆砌石为磴，其级七千有余」，写登山的路线和台阶；「泰山正南面有三谷……余始循以入，道少半，越中岭，复循西谷，遂至其巅」，写登山的具体路线；第三段写山顶的雪景——「及既上，苍山负雪，明烛天南。望晚日照城郭，汶水、徂徕如画，而半山居雾若带然」，以「苍山负雪，明烛天南」写雪后泰山的壮丽——青山背负白雪，明亮地照耀南天，以「半山居雾若带然」写半山腰的雾气像带子；第四段写日观亭看日出——「戊申晦，五鼓，与子颍坐日观亭，待日出。大风扬积雪击面。亭东自足下皆云漫。稍见云中白若樗蒱数十立者，山也。极天云一线异色，须臾成五采。日上，正赤如丹，下有红光动摇承之。或曰，此东海也。回视日观以西峰，或得日或否，绛皓驳色，而皆若偻」，以「极天云一线异色，须臾成五采」写日出前的天边——天边云有一线异色，一会儿变成五彩，以「正赤如丹」「红光动摇承之」写日出的壮丽，以「绛皓驳色，而皆若偻」写日出后山峰的景象——红白错杂，都像弯腰驼背；第五段写泰山的特点——「山多石，少土。石苍黑色，多平方，少圜。少杂树，多松，生石罅，皆平顶。冰雪，无瀑水，无鸟兽音迹。至日观数里内无树，而雪与人膝齐」，以「多石少土」「多松生石罅」「雪与人膝齐」写泰山的特点。全文描写生动、意境壮阔、语言精炼、结构严谨，「苍山负雪，明烛天南」「极天云一线异色，须臾成五采」成为千古名句，是游记散文的典范，「桐城派」的代表作。",
    b: "姚鼐（清代散文家，「桐城派」集大成者，字姬传，号惜抱轩）这篇《登泰山记》写他冬日登泰山的经历和所见景色，以「苍山负雪，明烛天南」「极天云一线异色，须臾成五采」写泰山雪景和日出，是中国古代游记散文的千古名篇，「桐城派」的代表作。",
    n: ["登泰山记：篇名，姚鼐作，泰山，在今山东泰安","泰山之阳：泰山之阳（泰山的南面。阳，山南水北为阳）","汶水西流：汶水西流（汶水向西流。汶水，大汶河）","其阴：其阴（泰山的北面。阴，山北水南为阴）","济水东流：济水东流（济水向东流。济水，古水名）","阳谷皆入汶：阳谷皆入汶（南面山谷的水都流入汶水。阳谷，南面山谷的水）","阴谷皆入济：阴谷皆入济（北面山谷的水都流入济水）","当其南北分者：当其南北分者（在那南北分界的地方）","古长城也：古长城也（是古长城）","最高日观峰：最高日观峰（最高的日观峰）","在长城南十五里：在长城南十五里","余以乾隆三十九年十二月：余以乾隆三十九年十二月（我在乾隆三十九年十二月。乾隆三十九年，1774年）","自京师乘风雪：自京师乘风雪（从京城冒着风雪。京师，北京）","历齐河、长清：历齐河、长清（经过齐河、长清）","穿泰山西北谷：穿泰山西北谷（穿过泰山西北谷）","越长城之限：越长城之限（越过长城的界限。限，界限）","至于泰安：至于泰安（到达泰安）","是月丁未：是月丁未（这月丁未日。丁未，农历二十八日）","与知府朱孝纯子颍由南麓登：与知府朱孝纯子颍由南麓登（和知府朱孝纯字子颍从南面山脚登山。知府，官名；南麓，南面山脚。麓音lù）","四十五里：四十五里","道皆砌石为磴：道皆砌石为磴（道路都是用石头砌成的台阶。磴音dèng，台阶）","其级七千有余：其级七千有余（台阶有七千多级）","泰山正南面有三谷：泰山正南面有三谷","中谷绕泰安城下：中谷绕泰安城下（中谷环绕泰安城下）","郦道元所谓环水也：郦道元所谓环水也（就是郦道元所说的环水。郦道元，北魏地理学家，《水经注》作者）","余始循以入：余始循以入（我开始沿着中谷进去）","道少半：道少半（路走了一小半）","越中岭：越中岭（越过中岭）","复循西谷：复循西谷（又沿着西谷）","遂至其巅：遂至其巅（就到达了山顶。巅音diān，山顶）","古时登山：古时登山","循东谷入：循东谷入（沿着东谷进去）","道有天门：道有天门（路上有天门）","东谷者：东谷者（东谷）","古谓之天门溪水：古谓之天门溪水（古时候叫它天门溪水）","余所不至也：余所不至也（是我没有到的地方）","今所经中岭及山巅：今所经中岭及山巅（现在所经过的中岭和山顶）","崖限当道者：崖限当道者（像门槛一样挡在路上的山崖。崖限，像门槛一样的山崖）","世皆谓之天门云：世皆谓之天门云（世人都叫它天门。云，语气词）","道中迷雾冰滑：道中迷雾冰滑（路上迷雾冰滑）","磴几不可登：磴几不可登（台阶几乎不能登）","及既上：及既上（等到已经登上山顶）","苍山负雪：苍山负雪（青山背负着白雪。负，背负）","明烛天南：明烛天南（明亮地照耀着南面的天空。烛，照耀）","望晚日照城郭：望晚日照城郭（远望夕阳照耀城郭。城郭，城内外）","汶水、徂徕如画：汶水、徂徕如画（汶水、徂徕山如画。徂徕音cúlái，山名，在泰安东南）","而半山居雾若带然：而半山居雾若带然（而半山腰停留的雾气像一条带子一样。居，停留）","戊申晦：戊申晦（戊申日月末。晦，农历每月最后一天）","五鼓：五鼓（五更。五鼓，五更天）","与子颍坐日观亭：与子颍坐日观亭（和子颍坐在日观亭）","待日出：待日出（等待日出）","大风扬积雪击面：大风扬积雪击面（大风扬起积雪打在脸上）","亭东自足下皆云漫：亭东自足下皆云漫（亭东从脚下起都是云雾弥漫。漫，弥漫）","稍见云中白若樗蒱数十立者：稍见云中白若樗蒱数十立者（渐渐看见云中白色的像樗蒱一样的几十个立着的东西。樗蒱音chūpú，古代博戏用具，像骰子）","山也：山也（是山）","极天云一线异色：极天云一线异色（天边的云有一线奇异的颜色。极天，天边）","须臾成五采：须臾成五采（一会儿变成五彩。须臾，一会儿；五采，五彩）","日上：日上（太阳升起）","正赤如丹：正赤如丹（纯红像朱砂。丹，朱砂）","下有红光动摇承之：下有红光动摇承之（下面有红光晃动托着它。承，托）","或曰：或曰（有人说）","此东海也：此东海也（这是东海）","回视日观以西峰：回视日观以西峰（回头看日观峰以西的山峰）","或得日或否：或得日或否（有的被太阳照到有的没有）","绛皓驳色：绛皓驳色（红白颜色错杂。绛音jiàng，红色；皓音hào，白色；驳，错杂）","而皆若偻：而皆若偻（都像弯腰驼背的样子。偻音lǚ，弯腰驼背）","亭西有岱祠：亭西有岱祠（亭西有岱祠。岱祠，祭祀泰山神的祠庙。岱音dài，泰山的别称）","又有碧霞元君祠：又有碧霞元君祠（又有碧霞元君祠。碧霞元君，道教女神，泰山神之女）","皇帝行宫在碧霞元君祠东：皇帝行宫在碧霞元君祠东（皇帝行宫在碧霞元君祠东。行宫，皇帝出行时的住所）","是日观道中石刻：是日观道中石刻（这一天观看路上的石刻）","自唐显庆以来：自唐显庆以来（从唐显庆年间以来。显庆，唐高宗年号）","其远古刻尽漫失：其远古刻尽漫失（那些远古的石刻都模糊缺失了。漫失，模糊缺失）","僻不当道者：僻不当道者（偏僻不在路上的）","皆不及往：皆不及往（都来不及去）","山多石：山多石（山上多石头）","少土：少土","石苍黑色：石苍黑色（石头苍黑色）","多平方：多平方（多是平方的形状）","少圜：少圜（少圆形的。圜同「圆」）","少杂树：少杂树","多松：多松","生石罅：生石罅（生在石头缝隙里。罅音xià，缝隙）","皆平顶：皆平顶（都是平顶）","冰雪：冰雪（有冰雪）","无瀑水：无瀑水（没有瀑布）","无鸟兽音迹：无鸟兽音迹（没有鸟兽的声音和踪迹）","至日观数里内无树：至日观数里内无树（到日观峰几里内没有树）","而雪与人膝齐：而雪与人膝齐（而雪和人的膝盖一样齐）","桐城姚鼐记：桐城姚鼐记（桐城姚鼐记。桐城，今安徽桐城，姚鼐的籍贯）"]
  },
  "为学|彭端淑": {
    s: "全文（节选）分四段：第一段提出论点——「天下事有难易乎？为之，则难者亦易矣；不为，则易者亦难矣。人之为学有难易乎？学之，则难者亦易矣；不学，则易者亦难矣」，以天下事的难易引出为学的难易——做就容易，不做就困难；第二段以昏庸与聪敏对比——「吾资之昏，不逮人也，吾材之庸，不逮人也；旦旦而学之，久而不怠焉，迄乎成，而亦不知其昏与庸也。吾资之聪，倍人也，吾材之敏，倍人也；屏弃而不用，其与昏与庸无以异也。圣人之道，卒于鲁也传之。然则昏庸聪敏之用，岂有常哉」，以昏庸者勤学可成、聪敏者不学则败，说明昏庸聪敏不是固定不变的；第三段用蜀地二僧的故事论证——「蜀之鄙有二僧：其一贫，其一富。贫者语于富者曰：『吾欲之南海，何如？』富者曰：『子何恃而往？』曰：『吾一瓶一钵足矣。』富者曰：『吾数年来欲买舟而下，犹未能也。子何恃而往！』越明年，贫者自南海还，以告富者，富者有惭色。西蜀之去南海，不知几千里也，僧富者不能至而贫者至焉。人之立志，顾不如蜀鄙之僧哉」，以贫僧「一瓶一钵」到南海、富僧「买舟而下」犹未能的对比，说明立志的重要——贫者有志竟成，富者无志不成；第四段总结——「是故聪与敏，可恃而不可恃也；自恃其聪与敏而不学者，自败者也。昏与庸，可限而不可限也；不自限其昏与庸而力学不倦者，自力者也」，以「聪敏可恃不可恃」「昏庸可限不可限」总结全文——聪明敏捷可以凭借又不可以凭借，昏庸平庸可以限制又不可以限制，关键在于是否立志勤学。全文论点鲜明、对比鲜明、故事生动、论证严密、语言精炼、勉励殷切，「天下事有难易乎？为之，则难者亦易矣；不为，则易者亦难矣」成为千古名句，是论说文的典范。",
    b: "彭端淑（清代文学家，字乐斋，号仪一）这篇《为学》通过蜀地二僧的故事，阐明「为学」的道理——天下事「为之则难者亦易，不为则易者亦难」，勉励人们立志勤学、努力不懈，是中国古代论说文的千古名篇。",
    n: ["为学：篇名，彭端淑作，为学，做学问","天下事有难易乎：天下事有难易乎（天下的事情有困难和容易的吗）","为之：为之（做它）","则难者亦易矣：则难者亦易矣（那么困难的也容易了）","不为：不为（不做）","则易者亦难矣：则易者亦难矣（那么容易的也困难了）","人之为学有难易乎：人之为学有难易乎（人们做学问有困难和容易的吗）","学之：学之（学习它）","则难者亦易矣：则难者亦易矣","不学：不学","则易者亦难矣：则易者亦难矣","吾资之昏：吾资之昏（我的资质昏庸。资，资质；昏，昏庸）","不逮人也：不逮人也（比不上别人。逮音dài，及，比得上）","吾材之庸：吾材之庸（我的才能平庸。材，才能；庸，平庸）","不逮人也：不逮人也","旦旦而学之：旦旦而学之（天天学习它。旦旦，天天）","久而不怠焉：久而不怠焉（长久而不懈怠。怠音dài，懈怠）","迄乎成：迄乎成（到成功。迄音qì，到）","而亦不知其昏与庸也：而亦不知其昏与庸也（也就不知道它的昏庸和平庸了）","吾资之聪：吾资之聪（我的资质聪明）","倍人也：倍人也（是别人的一倍）","吾材之敏：吾材之敏（我的才能敏捷）","倍人也：倍人也","屏弃而不用：屏弃而不用（摒弃而不用。屏音bǐng，摒弃）","其与昏与庸无以异也：其与昏与庸无以异也（那和昏庸平庸没有什么不同了）","圣人之道：圣人之道（圣人的学说）","卒于鲁也传之：卒于鲁也传之（最终由鲁（曾子，孔子认为鲁钝的学生）传下来了。卒，最终；鲁，鲁钝，指曾子）","然则昏庸聪敏之用：然则昏庸聪敏之用（那么昏庸平庸聪明敏捷的作用）","岂有常哉：岂有常哉（难道有固定不变的吗。常，固定不变）","蜀之鄙有二僧：蜀之鄙有二僧（蜀地的边境有两个和尚。鄙音bǐ，边境）","其一贫：其一贫（其中一个贫穷）","其一富：其一富（其中一个富有）","贫者语于富者曰：贫者语于富者曰（贫穷的对富有的说。语音yù，告诉）","吾欲之南海：吾欲之南海（我想要到南海去。之，到；南海，指普陀山，佛教圣地）","何如：何如（怎么样）","富者曰：富者曰","子何恃而往：子何恃而往（你凭什么去呢。恃音shì，凭借）","曰：曰","吾一瓶一钵足矣：吾一瓶一钵足矣（我一个水瓶一个饭钵就够了。钵音bō，和尚盛饭的器具）","富者曰：富者曰","吾数年来欲买舟而下：吾数年来欲买舟而下（我几年来想要雇船顺流而下。买舟，雇船）","犹未能也：犹未能也（还没能做到）","子何恃而往：子何恃而往","越明年：越明年（到了第二年。越，到了）","贫者自南海还：贫者自南海还（贫穷的从南海回来）","以告富者：以告富者（把这件事告诉富有的）","富者有惭色：富者有惭色（富有的脸上露出惭愧的神色。惭色，惭愧的神色）","西蜀之去南海：西蜀之去南海（西蜀距离南海。去，距离）","不知几千里也：不知几千里也（不知道有几千里）","僧富者不能至而贫者至焉：僧富者不能至而贫者至焉（富和尚不能到达而穷和尚到达了。焉，那里）","人之立志：人之立志（人树立志向）","顾不如蜀鄙之僧哉：顾不如蜀鄙之僧哉（难道还不如蜀地边境的和尚吗。顾，难道）","是故聪与敏：是故聪与敏（所以聪明和敏捷）","可恃而不可恃也：可恃而不可恃也（可以凭借又不可以凭借）","自恃其聪与敏而不学者：自恃其聪与敏而不学者（自己凭借聪明敏捷而不学习的人）","自败者也：自败者也（是自己失败的人）","昏与庸：昏与庸（昏庸和平庸）","可限而不可限也：可限而不可限也（可以限制又不可以限制）","不自限其昏与庸而力学不倦者：不自限其昏与庸而力学不倦者（不被自己的昏庸平庸所限制而努力学习不知疲倦的人）","自力者也：自力者也（是自己努力成功的人）"]
  },
  "好了歌|曹雪芹": {
    s: "全诗分四段，每段以「世人都晓神仙好」开头，分别写功名、金银、姣妻、儿孙的虚幻：第一段写功名——「世人都晓神仙好，惟有功名忘不了。古今将相在何方？荒冢一堆草没了」，以「古今将相在何方，荒冢一堆草没了」写功名的虚幻——古今的将相如今在哪里？只剩荒坟一堆被草埋没了；第二段写金银——「世人都晓神仙好，只有金银忘不了。终朝只恨聚无多，及到多时眼闭了」，以「终朝只恨聚无多，及到多时眼闭了」写金银的虚幻——整天只恨聚得不多，等到聚多了眼睛闭上了（死了）；第三段写姣妻——「世人都晓神仙好，只有姣妻忘不了。君生日日说恩情，君死又随人去了」，以「君生日日说恩情，君死又随人去了」写姣妻的虚幻——你活着时天天说恩情，你死了又跟别人去了；第四段写儿孙——「世人都晓神仙好，只有儿孙忘不了。痴心父母古来多，孝顺儿孙谁见了」，以「痴心父母古来多，孝顺儿孙谁见了」写儿孙的虚幻——痴心的父母自古以来多，孝顺的儿孙谁见过呢。全诗反复咏叹、对比鲜明、语言通俗、哲理深刻、悲凉透彻，以「好」与「了」的辩证关系写人生的虚幻——「好」便是「了」，「了」便是「好」，只有看破一切才能「好」，是《红楼梦》的主题歌，千古名篇。",
    b: "曹雪芹（清代小说家，名霑，字梦阮，号雪芹，《红楼梦》作者）这首《好了歌》是《红楼梦》第一回中跛足道人所唱，以「好」与「了」的辩证关系写人生的虚幻——功名、金银、姣妻、儿孙都是虚幻的，只有「了」才能「好」，是《红楼梦》的主题歌，千古名篇。",
    n: ["好了歌：篇名，《红楼梦》第一回中跛足道人所唱","世人都晓神仙好：世人都晓神仙好（世人都知道神仙好）","惟有功名忘不了：惟有功名忘不了（只有功名忘不了）","古今将相在何方：古今将相在何方（古今的将相在哪里）","荒冢一堆草没了：荒冢一堆草没了（荒坟一堆被草埋没了。冢音zhǒng，坟墓）","世人都晓神仙好：世人都晓神仙好","只有金银忘不了：只有金银忘不了","终朝只恨聚无多：终朝只恨聚无多（整天只恨聚得不多。终朝，整天）","及到多时眼闭了：及到多时眼闭了（等到聚多了眼睛闭上了——死了）","世人都晓神仙好：世人都晓神仙好","只有姣妻忘不了：只有姣妻忘不了（姣妻，美貌的妻子。姣音jiāo，美好）","君生日日说恩情：君生日日说恩情（你活着时天天说恩情）","君死又随人去了：君死又随人去了（你死了又跟别人去了）","世人都晓神仙好：世人都晓神仙好","只有儿孙忘不了：只有儿孙忘不了","痴心父母古来多：痴心父母古来多（痴心的父母自古以来多）","孝顺儿孙谁见了：孝顺儿孙谁见了（孝顺的儿孙谁见过呢）"]
  },
  "赴戍登程口占示家人·其二|林则徐": {
    s: "首联「力微任重久神疲，再竭衰庸定不支」写力微任重久神疲、再竭衰庸定不支，以「力微任重」「衰庸不支」自谦，写自己的疲惫和力不从心；颔联「苟利国家生死以，岂因祸福避趋之」是千古名句——如果有利于国家，生死都由它，怎么能因为祸福而逃避或追求呢，以「苟利国家生死以」用《左传》典故写以国家利益为重、以「岂因祸福避趋之」写不计个人祸福，表达了崇高的爱国精神和无私的胸怀；颈联「谪居正是君恩厚，养拙刚于戍卒宜」写谪居正是君恩厚、养拙刚于戍卒宜，以「谪居正是君恩厚」写对贬谪的旷达——贬谪正是君恩深厚，以「养拙刚于戍卒宜」写对戍边的坦然——守拙正好与戍卒相宜；尾联「戏与山妻谈故事，试吟断送老头皮」写戏与山妻谈故事、试吟断送老头皮，以杨朴「断送老头皮」的典故写与妻子的戏谑——姑且和妻子谈旧事，试着吟诵「断送老头皮」，以幽默化解悲凉，全诗用典贴切、对仗工稳、情感深沉、旷达幽默、崇高感人，「苟利国家生死以，岂因祸福避趋之」成为千古名句，是七律的千古名篇。",
    b: "林则徐（清代政治家、民族英雄，字元抚，号少穆）这首《赴戍登程口占示家人》是他因虎门销烟被革职、发配伊犁时启程前所作，「苟利国家生死以，岂因祸福避趋之」是千古名句，表达了他以国家利益为重、不计个人祸福的崇高精神，是七律的千古名篇。",
    n: ["赴戍登程口占示家人：诗题，赴戍，赴伊犁戍边；登程，启程；口占，随口吟诵；示家人，给家人看。其二，第二首","力微任重久神疲：力微任重久神疲（力量微小责任重大长久精神疲惫）","再竭衰庸定不支：再竭衰庸定不支（再竭尽衰庸的能力一定支持不住。衰庸，衰朽平庸）","苟利国家生死以：苟利国家生死以（如果有利于国家，生死都由它。苟，如果；以，由，用。用《左传》「苟利社稷，死生以之」典故）","岂因祸福避趋之：岂因祸福避趋之（怎么能因为祸福而逃避或追求呢。避趋，逃避或追求）","谪居正是君恩厚：谪居正是君恩厚（贬谪居住正是君恩深厚。谪音zhé，贬谪）","养拙刚于戍卒宜：养拙刚于戍卒宜（守拙正好与戍卒相宜。养拙，守拙，指才能低下；刚，正好）","戏与山妻谈故事：戏与山妻谈故事（姑且和妻子谈旧事。山妻，对自己妻子的谦称；故事，旧事，指宋真宗时杨朴「断送老头皮」的故事）","试吟断送老头皮：试吟断送老头皮（试着吟诵「断送老头皮」。用宋真宗时杨朴的典故——杨朴被召，妻子作诗「更休落魄耽杯酒，且莫猖狂爱咏诗。今日捉将官里去，这回断送老头皮」）"]
  },
  "口技|林嗣环": {
    s: "全文（节选）分五层：第一层写表演前的准备——「京中有善口技者。会宾客大宴，于厅事之东北角，施八尺屏障，口技人坐屏障中，一桌、一椅、一扇、一抚尺而已。众宾团坐。少顷，但闻屏障中抚尺一下，满堂寂然，无敢哗者」，以「一桌、一椅、一扇、一抚尺」写道具的简单、以「满堂寂然，无敢哗者」写宾客的期待；第二层写一家四口深夜被惊醒的声音——「遥遥闻深巷中犬吠，便有妇人惊觉欠伸，其夫呓语。既而儿醒，大啼。夫亦醒。妇抚儿乳，儿含乳啼，妇拍而呜之。又一大儿醒，絮絮不止。当是时，妇手拍儿声，口中呜声，儿含乳啼声，大儿初醒声，夫叱大儿声，一时齐发，众妙毕备」，以各种声音「一时齐发，众妙毕备」写口技的精妙；「满坐宾客无不伸颈，侧目，微笑，默叹，以为妙绝」，以宾客的反应侧面烘托口技的精彩；第三层写一家人复睡的声音——「未几，夫齁声起，妇拍儿亦渐拍渐止。微闻有鼠作作索索，盆器倾侧，妇梦中咳嗽。宾客意少舒，稍稍正坐」，以「夫齁声起」「鼠作作索索」「妇梦中咳嗽」写深夜的寂静，以「宾客意少舒，稍稍正坐」写宾客心情的放松；第四层写失火救火的声音——「忽一人大呼『火起』，夫起大呼，妇亦起大呼，两儿齐哭。俄而百千人大呼，百千儿哭，百千犬吠。中间力拉崩倒之声，火爆声，呼呼风声，百千齐作；又夹百千求救声，曳屋许许声，抢夺声，泼水声。凡所应有，无所不有。虽人有百手，手有百指，不能指其一端；人有百口，口有百舌，不能名其一处也」，以「凡所应有，无所不有」写声音的繁多、以「虽人有百手……不能名其一处」的夸张写口技的精妙；「于是宾客无不变色离席，奋袖出臂，两股战战，几欲先走」，以宾客「变色离席」「两股战战」「几欲先走」的反应侧面烘托口技的逼真——宾客以为真的失火了；第五层写表演结束——「忽然抚尺一下，群响毕绝。撤屏视之，一人、一桌、一椅、一扇、一抚尺而已」，以「群响毕绝」写表演的结束、以「一人、一桌、一椅、一扇、一抚尺而已」呼应开头，写道具的简单，反衬口技艺人的高超技艺。全文正面描写与侧面烘托相结合、声音描写层次分明、宾客反应生动、结构严谨、首尾呼应，「凡所应有，无所不有」「虽人有百手，手有百指，不能指其一端；人有百口，口有百舌，不能名其一处也」成为千古名句，是散文的典范。",
    b: "林嗣环（清代文学家，字铁崖）这篇《口技》通过描写一场精彩的口技表演，展现了口技艺人的高超技艺，以「凡所应有，无所不有」「虽人有百手，手有百指，不能指其一端；人有百口，口有百舌，不能名其一处也」写口技的精妙，是中国古代散文的千古名篇。",
    n: ["口技：篇名，林嗣环作，口技，一种杂技，用口模仿各种声音","京中有善口技者：京中有善口技者（京城中有擅长口技的人）","会宾客大宴：会宾客大宴（正赶上有一家大摆酒席宴请宾客。会，正赶上）","于厅事之东北角：于厅事之东北角（在厅堂的东北角。厅事，厅堂）","施八尺屏障：施八尺屏障（设置八尺高的屏障。施，设置）","口技人坐屏障中：口技人坐屏障中","一桌、一椅、一扇、一抚尺而已：一桌、一椅、一扇、一抚尺而已（一张桌子、一把椅子、一把扇子、一块醒木罢了。抚尺，醒木，艺人表演时用的木块）","众宾团坐：众宾团坐（宾客们围坐在一起。团坐，围坐）","少顷：少顷（一会儿。少顷音shǎoqǐng）","但闻屏障中抚尺一下：但闻屏障中抚尺一下（只听见屏障中醒木一拍。但，只）","满堂寂然：满堂寂然（全场静悄悄的）","无敢哗者：无敢哗者（没有敢喧哗的人。哗音huá，喧哗）","遥遥闻深巷中犬吠：遥遥闻深巷中犬吠（远远听见深巷中狗叫。吠音fèi，狗叫）","便有妇人惊觉欠伸：便有妇人惊觉欠伸（便有妇人惊醒打哈欠伸懒腰。欠伸，打哈欠伸懒腰）","其夫呓语：其夫呓语（她的丈夫说梦话。呓音yì，梦话）","既而儿醒：既而儿醒（不久孩子醒了。既而，不久）","大啼：大啼（大声哭。啼音tí，哭）","夫亦醒：夫亦醒","妇抚儿乳：妇抚儿乳（妇人拍着孩子喂奶。抚，拍；乳，喂奶）","儿含乳啼：儿含乳啼（孩子含着奶头哭）","妇拍而呜之：妇拍而呜之（妇人拍着孩子轻声哼着哄他。呜，轻声哼）","又一大儿醒：又一大儿醒","絮絮不止：絮絮不止（唠唠叨叨不停。絮絮，唠叨）","当是时：当是时（在这个时候）","妇手拍儿声：妇手拍儿声","口中呜声：口中呜声","儿含乳啼声：儿含乳啼声","大儿初醒声：大儿初醒声","夫叱大儿声：夫叱大儿声（丈夫呵斥大儿的声音。叱音chì，呵斥）","一时齐发：一时齐发（同时一齐发出）","众妙毕备：众妙毕备（各种妙处都具备。毕，全）","满坐宾客无不伸颈：满坐宾客无不伸颈（全场宾客没有不伸长脖子的）","侧目：侧目（斜着眼看，形容听得入神）","微笑：微笑","默叹：默叹（默默赞叹）","以为妙绝：以为妙绝（认为妙极了。绝，极）","未几：未几（不久）","夫齁声起：夫齁声起（丈夫的鼾声响起。齁音hōu，打鼾）","妇拍儿亦渐拍渐止：妇拍儿亦渐拍渐止（妇人拍孩子也渐渐拍渐渐停止）","微闻有鼠作作索索：微闻有鼠作作索索（微微听见有老鼠窸窸窣窣的声音。作作索索，老鼠活动的声音）","盆器倾侧：盆器倾侧（盆器倾斜翻倒。倾侧，倾斜翻倒）","妇梦中咳嗽：妇梦中咳嗽（妇人在梦中咳嗽）","宾客意少舒：宾客意少舒（宾客的心情稍微放松了些。少，稍微；舒，放松）","稍稍正坐：稍稍正坐（渐渐坐正了身子）","忽一人大呼「火起」：忽一人大呼「火起」（忽然一个人大喊「起火了」）","夫起大呼：夫起大呼","妇亦起大呼：妇亦起大呼","两儿齐哭：两儿齐哭","俄而百千人大呼：俄而百千人大呼（一会儿成百上千人大喊。俄而，一会儿）","百千儿哭：百千儿哭","百千犬吠：百千犬吠","中间力拉崩倒之声：中间力拉崩倒之声（中间夹杂着噼里啪啦房屋倒塌的声音。力拉，房屋倒塌的声音）","火爆声：火爆声（火爆裂的声音）","呼呼风声：呼呼风声","百千齐作：百千齐作（成百上千种声音一齐响起）","又夹百千求救声：又夹百千求救声（又夹杂着成百上千求救的声音）","曳屋许许声：曳屋许许声（拉倒房屋的呼喊声。曳音yè，拉；许许音hǔhǔ，众人共同用力的呼喊声）","抢夺声：抢夺声","泼水声：泼水声","凡所应有：凡所应有（凡是应该有的声音）","无所不有：无所不有（没有不有的）","虽人有百手：虽人有百手（即使人有一百只手）","手有百指：手有百指","不能指其一端：不能指其一端（不能指明其中的一种。端，种，类）","人有百口：人有百口","口有百舌：口有百舌","不能名其一处也：不能名其一处也（不能说出其中的一处。名，说出）","于是宾客无不变色离席：于是宾客无不变色离席（在这时宾客没有不变了脸色离开座位的）","奋袖出臂：奋袖出臂（捋起袖子露出手臂。奋袖，捋起袖子）","两股战战：两股战战（两条腿发抖。股，大腿；战战，发抖的样子）","几欲先走：几欲先走（几乎想要抢先跑掉。几音jī，几乎；走，跑）","忽然抚尺一下：忽然抚尺一下","群响毕绝：群响毕绝（各种声音全都停止了。毕，全；绝，停止）","撤屏视之：撤屏视之（撤去屏障看里面）","一人、一桌、一椅、一扇、一抚尺而已：一人、一桌、一椅、一扇、一抚尺而已"]
  },
  "舟夜书所见|查慎行": {
    s: "首两句「月黑见渔灯，孤光一点萤」写月黑见渔灯、孤光一点萤，以「月黑」写夜晚的黑暗、以「孤光一点萤」写渔灯的微弱——没有月亮的黑夜，只见渔船上的灯，孤零零的灯光像一点萤火虫；后两句「微微风簇浪，散作满河星」写微微风簇浪、散作满河星，以「风簇浪」写微风聚起波浪、以「散作满河星」写渔灯在波浪中的倒影——微风聚起波浪，渔灯的倒影散开变成满河的星星，比喻新奇、意境优美，全诗语言精炼、比喻新奇、意境优美、画面生动，「微微风簇浪，散作满河星」成为名句，是五绝的名篇。",
    b: "查慎行（清代诗人，字悔余，号初白，「清初六家」之一）这首《舟夜书所见》写夜晚在船上所见的景色，「散作满河星」是名句，是五绝的名篇。",
    n: ["舟夜书所见：诗题，在船上夜晚写下所见","月黑见渔灯：月黑见渔灯（月黑，没有月亮的黑夜；渔灯，渔船上的灯）","孤光一点萤：孤光一点萤（孤零零的灯光像一点萤火虫。萤，萤火虫）","微微风簇浪：微微风簇浪（微微的风聚起波浪。簇，聚集）","散作满河星：散作满河星（散开变成满河的星星）"]
  },
  "题秋江独钓图|王士祯": {
    s: "全诗四句，每句都有「一」字，连用九个「一」字——「一蓑一笠一扁舟，一丈丝纶一寸钩。一曲高歌一樽酒，一人独钓一江秋」，以「一蓑一笠一扁舟」写渔人的装束和船、以「一丈丝纶一寸钩」写钓鱼的器具、以「一曲高歌一樽酒」写渔人的欢乐、以「一人独钓一江秋」写渔人的孤独和旷达——一个人独自钓一江的秋天，「一江秋」意境开阔，将秋天的江水都纳入垂钓之中，全诗连用九个「一」字、语言精炼、意境开阔、旷达自然、画面生动，「一人独钓一江秋」成为名句，是七绝的名篇。",
    b: "王士祯（清代诗人，「神韵派」领袖，字贻上，号阮亭，又号渔洋山人）这首《题秋江独钓图》为《秋江独钓图》题诗，「一人独钓一江秋」是名句，是七绝的名篇。",
    n: ["题秋江独钓图：诗题，为《秋江独钓图》题诗","一蓑一笠一扁舟：一蓑一笠一扁舟（一件蓑衣一顶斗笠一只小船。蓑音suō，蓑衣；笠音lì，斗笠；扁舟，小船）","一丈丝纶一寸钩：一丈丝纶一寸钩（一丈长的钓鱼线一寸长的鱼钩。丝纶，钓鱼线）","一曲高歌一樽酒：一曲高歌一樽酒（唱一曲高歌喝一樽酒。樽音zūn，酒杯）","一人独钓一江秋：一人独钓一江秋（一个人独自钓一江的秋天）"]
  },
  "河中石兽|纪昀": {
    s: "全文（节选）分四层：第一层写石兽沉没和寻找的经过——「沧州南一寺临河干，山门圮于河，二石兽并沉焉。阅十余岁，僧募金重修，求石兽于水中，竟不可得。以为顺流下矣，棹数小舟，曳铁钯，寻十余里无迹」，写石兽沉河十多年后，和尚在下游寻找没有找到；第二层写讲学家的观点——「一讲学家设帐寺中，闻之笑曰：『尔辈不能究物理，是非木杮，岂能为暴涨携之去？乃石性坚重，沙性松浮，湮于沙上，渐沉渐深耳。沿河求之，不亦颠乎？』众服为确论」，讲学家认为石兽坚重、沙性松浮，应该埋没在原地沙中，越沉越深，沿河寻找是荒唐的，大家信服；第三层写老河兵的观点——「一老河兵闻之，又笑曰：『凡河中失石，当求之于上流。盖石性坚重，沙性松浮，水不能冲石，其反激之力，必于石下迎水处啮沙为坎穴，渐激渐深，至石之半，石必倒掷坎穴中。如是再啮，石又再转，转转不已，遂反溯流逆上矣。求之下流，固颠；求之地中，不更颠乎？』如其言，果得于数里外」，老河兵根据实际经验分析——水的反冲力在石下冲刷沙子形成坑穴，石头倒倒进坑穴，不断转动，反而逆流而上，按照他的话果然在上游几里外找到了石兽；第四层点明主旨——「然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？」，以「但知其一，不知其二者多矣」写主观臆断的危害、以「可据理臆断欤」的反问点明主旨——不能根据道理主观判断，要根据实际情况分析。全文故事生动、对比鲜明、论证严密、哲理深刻、语言精炼，「然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？」成为千古名句，是寓言散文的典范。",
    b: "纪昀（清代文学家，字晓岚，号石云，《阅微草堂笔记》作者，曾任《四库全书》总纂官）这篇《河中石兽》通过寻找河中石兽的故事，阐明「天下之事，但知其一，不知其二者多矣，可据理臆断欤」的道理——不能主观臆断，要根据实际情况分析，是中国古代寓言散文的千古名篇。",
    n: ["河中石兽：篇名，纪昀作，石兽，石制的兽像","沧州南一寺临河干：沧州南一寺临河干（沧州南面有一座寺庙靠近河岸。沧州，今河北沧州；河干，河岸。干音gān）","山门圮于河：山门圮于河（寺庙的大门倒塌在河里。山门，寺庙的大门；圮音pǐ，倒塌）","二石兽并沉焉：二石兽并沉焉（两只石兽一起沉到河里。并，一起）","阅十余岁：阅十余岁（经过十多年。阅，经过）","僧募金重修：僧募金重修（和尚募集资金重新修建。募，募集）","求石兽于水中：求石兽于水中（在水中寻找石兽）","竟不可得：竟不可得（最终没有找到。竟，最终）","以为顺流下矣：以为顺流下矣（以为石兽顺着水流冲到下游了）","棹数小舟：棹数小舟（划着几只小船。棹音zhào，划船）","曳铁钯：曳铁钯（拖着铁钯。曳音yè，拖；钯音pá，同「耙」，农具）","寻十余里无迹：寻十余里无迹（寻找了十多里没有踪迹）","一讲学家设帐寺中：一讲学家设帐寺中（一位讲学家在寺庙中设馆教书。讲学家，讲学的人；设帐，设馆教书）","闻之笑曰：闻之笑曰（听说了这件事笑着说）","尔辈不能究物理：尔辈不能究物理（你们这些人不能推究事物的道理。尔辈，你们这些人；究，推究；物理，事物的道理）","是非木杮：是非木杮（这不是木片。是，这；木杮音mùfèi，木片）","岂能为暴涨携之去：岂能为暴涨携之去（怎么能被暴涨的洪水带走呢。暴涨，暴涨的洪水）","乃石性坚重：乃石性坚重（是石头的性质坚硬沉重）","沙性松浮：沙性松浮（沙子的性质松软浮动）","湮于沙上：湮于沙上（埋没在沙上。湮音yān，埋没）","渐沉渐深耳：渐沉渐深耳（越沉越深罢了。耳，罢了）","沿河求之：沿河求之（沿着河边寻找它）","不亦颠乎：不亦颠乎（不也是荒唐吗。颠，荒唐，颠倒）","众服为确论：众服为确论（大家信服认为是正确的言论。确论，正确的言论）","一老河兵闻之：一老河兵闻之（一位老河兵听说了这件事。河兵，守河的士兵）","又笑曰：又笑曰","凡河中失石：凡河中失石（凡是河中丢失的石头）","当求之于上流：当求之于上流（应当到上游去寻找它）","盖石性坚重：盖石性坚重（因为石头的性质坚硬沉重。盖，因为）","沙性松浮：沙性松浮","水不能冲石：水不能冲石","其反激之力：其反激之力（水的反冲的力量）","必于石下迎水处啮沙为坎穴：必于石下迎水处啮沙为坎穴（一定在石头下面迎水的地方冲刷沙子形成坑穴。啮音niè，咬，此指冲刷；坎穴，坑穴）","渐激渐深：渐激渐深（越冲越深）","至石之半：至石之半（到石头的一半）","石必倒掷坎穴中：石必倒掷坎穴中（石头一定倒倒进坑穴中。倒掷，倒倒）","如是再啮：如是再啮（像这样再冲刷）","石又再转：石又再转（石头又再转动）","转转不已：转转不已（转动不停。已，停止）","遂反溯流逆上矣：遂反溯流逆上矣（于是反而逆流而上了。溯流，逆流。溯音sù）","求之下流：求之下流（到下游寻找它）","固颠：固颠（固然荒唐。固，固然）","求之地中：求之地中（在原地深处寻找它）","不更颠乎：不更颠乎（不更荒唐吗）","如其言：如其言（按照他的话）","果得于数里外：果得于数里外（果然在几里外找到了）","然则天下之事：然则天下之事（既然这样那么天下的事）","但知其一：但知其一（只知道其中一方面）","不知其二者多矣：不知其二者多矣（不知道另一方面的多了）","可据理臆断欤：可据理臆断欤（可以根据道理主观判断吗。臆断，主观判断；欤音yú，语气词）"]
  },
  "长相思·山一程|纳兰性德": {
    s: "上片「山一程，水一程，身向榆关那畔行，夜深千帐灯」写山一程水一程、身向榆关那畔行、夜深千帐灯，以「山一程，水一程」写路途的遥远——走了一程山路又一程水路，以「身向榆关那畔行」写行进的方向——向山海关那边行进，以「夜深千帐灯」写夜晚的壮观——夜深了千顶帐篷都亮着灯，以壮观的场景反衬思乡的孤独；下片「风一更，雪一更，聒碎乡心梦不成，故园无此声」写风一更雪一更、聒碎乡心梦不成、故园无此声，以「风一更，雪一更」写风雪的肆虐——刮了一更的风又下了一更的雪，以「聒碎乡心梦不成」写思乡的痛苦——风雪声吵碎了思乡的心，梦也做不成，以「故园无此声」写对故乡的思念——故乡没有这种风雪声，全词语言精炼、对比鲜明、情感真挚、意境凄清、思乡感人，「聒碎乡心梦不成，故园无此声」成为名句，是婉约词的千古名篇。",
    b: "纳兰性德（清代词人，字容若，号楞伽山人，「清初第一词人」）这首《长相思》写他随康熙东巡山海关时的思乡之情，「聒碎乡心梦不成，故园无此声」是名句，是婉约词的千古名篇。",
    n: ["长相思：词牌名","山一程：山一程（走了一程山路）","水一程：水一程（走了一程水路）","身向榆关那畔行：身向榆关那畔行（身子向榆关那边行进。榆关，山海关；那畔，那边）","夜深千帐灯：夜深千帐灯（夜深了千顶帐篷都亮着灯）","风一更：风一更（刮了一更的风。更音gēng，古代夜间计时单位，一夜五更）","雪一更：雪一更（下了一更的雪）","聒碎乡心梦不成：聒碎乡心梦不成（风雪声吵碎了思乡的心，梦也做不成。聒音guō，声音嘈杂）","故园无此声：故园无此声（故乡没有这种声音）"]
  },
  "木兰花·拟古决绝词柬友|纳兰性德": {
    s: "上片「人生若只如初见，何事秋风悲画扇。等闲变却故人心，却道故心人易变」写人生若只如初见、何事秋风悲画扇，等闲变却故人心、却道故心人易变，以「人生若只如初见」写对初次见面的怀念——人生如果只像初次见面那样美好，以「何事秋风悲画扇」用班婕妤「秋扇见捐」典故写被抛弃的悲哀——为什么会有秋风悲画扇的事呢，以「等闲变却故人心，却道故心人易变」写人心的易变——轻易地变了故人的心，却说故心人容易变；下片「骊山语罢清宵半，泪雨零铃终不怨。何如薄幸锦衣郎，比翼连枝当日愿」写骊山语罢清宵半、泪雨零铃终不怨，何如薄幸锦衣郎、比翼连枝当日愿，以「骊山语罢」用唐玄宗杨贵妃骊山盟誓的典故写曾经的誓言、以「泪雨零铃」用唐玄宗《雨霖铃》的典故写最终的悲剧——泪雨像铃声一样零落终究不怨恨，以「何如薄幸锦衣郎，比翼连枝当日愿」写决绝——怎么比得上薄情的锦衣郎呢，比翼鸟连理枝只是当日的愿望罢了，全词用典丰富、情感深沉、语言精炼、意境凄婉、决绝动人，「人生若只如初见，何事秋风悲画扇」成为千古名句，是婉约词的千古名篇。",
    b: "纳兰性德这首《木兰花·拟古决绝词柬友》以女子的口吻写决绝之情，「人生若只如初见」是千古名句，用班婕妤、唐玄宗杨贵妃的典故，写爱情的易变和决绝，是婉约词的千古名篇。",
    n: ["木兰花：词牌名，即「玉楼春」","拟古决绝词柬友：题目，模仿古乐府决绝词写给友人。决绝词，断绝关系的词；柬，给……写信","人生若只如初见：人生若只如初见（人生如果只像初次见面那样）","何事秋风悲画扇：何事秋风悲画扇（为什么会有秋风悲画扇的事呢。用汉班婕妤「秋扇见捐」典故——班婕妤失宠后作《怨歌行》，以秋扇自喻，秋天扇子被抛弃）","等闲变却故人心：等闲变却故人心（轻易地变了故人的心。等闲，轻易）","却道故心人易变：却道故心人易变（却说故心人容易变。故心人，本心不变的人）","骊山语罢清宵半：骊山语罢清宵半（骊山的话儿说完在清宵半夜。骊山，在今陕西临潼，唐玄宗和杨贵妃在此盟誓「在天愿作比翼鸟，在地愿为连理枝」；清宵，清静的夜晚）","泪雨零铃终不怨：泪雨零铃终不怨（泪雨像铃声一样零落终究不怨恨。用唐玄宗在马嵬坡赐死杨贵妃后，雨中闻铃声作《雨霖铃》的典故）","何如薄幸锦衣郎：何如薄幸锦衣郎（怎么比得上薄情的锦衣郎呢。薄幸，薄情；锦衣郎，指唐玄宗）","比翼连枝当日愿：比翼连枝当日愿（比翼鸟连理枝是当日的愿望。用白居易「在天愿作比翼鸟，在地愿为连理枝」）"]
  },
  "浣溪沙·谁念西风独自凉|纳兰性德": {
    s: "上片「谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳」写谁念西风独自凉、萧萧黄叶闭疏窗、沉思往事立残阳，以「西风独自凉」写孤独凄凉、以「萧萧黄叶闭疏窗」写秋天的萧瑟、以「沉思往事立残阳」写对往事的沉思——站在残阳中沉思往事，以凄凉的秋景烘托悼亡的悲痛；下片「被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常」写被酒莫惊春睡重、赌书消得泼茶香、当时只道是寻常，以「被酒莫惊春睡重」写夫妻生活的温馨——醉酒后不要惊醒春睡正浓的妻子，以「赌书消得泼茶香」用李清照赵明诚「赌书泼茶」的典故写夫妻生活的风雅——赌书赢得了泼茶的香气，以「当时只道是寻常」写对亡妻的深切怀念——当时只以为是寻常的事，如今却再也无法重现，以乐景写哀、以寻常写悲痛，全词意境凄清、用典贴切、情感真挚、含蓄深沉、悼亡感人，「当时只道是寻常」成为千古名句，是婉约词中悼亡词的千古名篇。",
    b: "纳兰性德这首《浣溪沙》是悼念亡妻卢氏的作品，「当时只道是寻常」是千古名句，用李清照赵明诚「赌书泼茶」的典故，写对亡妻的深切怀念，是婉约词中悼亡词的千古名篇。",
    n: ["浣溪沙：词牌名","谁念西风独自凉：谁念西风独自凉（谁想到在西风中独自凄凉呢。念，想到）","萧萧黄叶闭疏窗：萧萧黄叶闭疏窗（萧萧的黄叶关上了稀疏的窗户。萧萧，风声；疏窗，稀疏的窗户）","沉思往事立残阳：沉思往事立残阳（沉思往事站在残阳中。残阳，夕阳）","被酒莫惊春睡重：被酒莫惊春睡重（醉酒后不要惊醒春睡正浓。被酒，醉酒；春睡重，春睡正浓）","赌书消得泼茶香：赌书消得泼茶香（赌书赢得了泼茶的香气。用李清照赵明诚「赌书泼茶」的典故——李清照和赵明诚比赛记忆力，赌书饮茶，赢得的人举杯大笑，茶泼在怀中）","当时只道是寻常：当时只道是寻常（当时只以为是寻常的事）"]
  },
  "苔|袁枚": {
    s: "首两句「白日不到处，青春恰自来」写白日不到处、青春恰自来，以「白日不到处」写苔藓生长的环境——阳光照不到的阴暗地方，以「青春恰自来」写苔藓的生命力——春天的生机恰好自己来了，不需要阳光的恩赐；后两句「苔花如米小，也学牡丹开」写苔花如米小、也学牡丹开，以「苔花如米小」写苔花的微小——像米粒一样小，以「也学牡丹开」写苔藓的自信和努力——也学牡丹一样开放，以牡丹的富贵反衬苔花的自信，全诗语言精炼、对比鲜明、寓意深刻、积极向上、自信感人，「苔花如米小，也学牡丹开」成为名句，是五绝的名篇。",
    b: "袁枚（清代诗人，「性灵派」领袖，字子才，号简斋，又号随园老人）这首《苔》写苔藓在阳光照不到的地方也努力开花，「苔花如米小，也学牡丹开」是名句，是五绝的名篇。",
    n: ["苔：诗题，苔藓","白日不到处：白日不到处（阳光照不到的地方）","青春恰自来：青春恰自来（春天的生机恰好自己来了。青春，春天的生机）","苔花如米小：苔花如米小（苔藓的花像米粒一样小）","也学牡丹开：也学牡丹开（也学牡丹一样开放）"]
  },
  "马嵬|袁枚": {
    s: "首两句「莫唱当年长恨歌，人间亦自有银河」写莫唱当年长恨歌、人间亦自有银河，以「莫唱长恨歌」写对唐玄宗杨贵妃爱情悲剧的态度——不要唱《长恨歌》了，以「人间亦自有银河」用牛郎织女的典故写普通百姓的苦难——人间也自有银河，普通百姓也有夫妻分离的悲剧；后两句「石壕村里夫妻别，泪比长生殿上多」写石壕村里夫妻别、泪比长生殿上多，以「石壕村」用杜甫《石壕吏》的典故写普通百姓的苦难——石壕村里老妇被抓去服役与丈夫离别，以「泪比长生殿上多」对比——普通百姓的眼泪比长生殿上唐玄宗杨贵妃的眼泪还多，以帝王的爱情悲剧反衬普通百姓的苦难，全诗用典丰富、对比鲜明、立意深刻、同情百姓、语言精炼，「石壕村里夫妻别，泪比长生殿上多」成为名句，是七绝的名篇。",
    b: "袁枚这首《马嵬》通过对比唐玄宗杨贵妃的爱情悲剧和普通百姓的苦难，写「石壕村里夫妻别，泪比长生殿上多」，是七绝的名篇。",
    n: ["马嵬：诗题，马嵬坡，在今陕西兴平，唐玄宗在此赐死杨贵妃","莫唱当年长恨歌：莫唱当年长恨歌（不要唱当年的《长恨歌》了。《长恨歌》，白居易作，写唐玄宗和杨贵妃的爱情悲剧）","人间亦自有银河：人间亦自有银河（人间也自有银河。银河，用牛郎织女被银河隔开的典故，指夫妻分离）","石壕村里夫妻别：石壕村里夫妻别（石壕村里的夫妻离别。用杜甫《石壕吏》的典故——石壕村老妇被抓去服役，与丈夫离别）","泪比长生殿上多：泪比长生殿上多（眼泪比长生殿上的还多。长生殿，唐玄宗和杨贵妃在骊山盟誓的地方）"]
  },
  "黄生借书说|袁枚": {
    s: "全文（节选）分四段：第一段提出论点——「黄生允修借书，随园主人授以书而告之曰：『书非借不能读也。』」，以「书非借不能读也」提出中心论点——书不是借来的就不能好好读；第二段论证论点——「子不闻藏书者乎？七略四库，天子之书，然天子读书者有几？汗牛塞屋，富贵家之书，然富贵人读书者有几？其他祖父积、子孙弃者无论焉」，以天子、富贵人家藏书多但读书少的例子论证——天子有七略四库但读书的有几个，富贵人家汗牛塞屋但读书的有几个，祖父积累子孙丢弃的就不用说了；「非独书为然，天下物皆然。非夫人之物而强假焉，必虑人逼取，而惴惴焉摩玩之不已，曰：『今日存，明日去，吾不得而见之矣。』若业为吾所有，必高束焉，庋藏焉，曰：『姑俟异日观云尔。』」，以借来的东西和自己的东西对比——借来的东西担心别人催要，惴惴不安地摩玩不已，自己的东西则高高束起收藏起来，等以后再看，论证「非借不能读」的道理；第三段以自己的经历论证——「余幼好书，家贫难致。有张氏藏书甚富，往借，不与，归而形诸梦，其切如是。故有所览辄省记。通籍后，俸去书来，落落大满，素蟫灰丝时蒙卷轴。然后叹借者之用心专，而少时之岁月为可惜也」，以自己幼时家贫借书难、借书读用心专一、做官后有书反而不读的对比，论证「书非借不能读」的道理——借书的人用心专一，少年时的岁月值得珍惜；第四段勉励黄生——「今黄生贫类予，其借书亦类予；惟予之公书与张氏之吝书若不相类。然则予固不幸而遇张乎，生固幸而遇予乎？知幸与不幸，则其读书也必专，而其归书也必速。为一说，使与书俱」，以黄生的幸运（遇到愿意借书的袁枚）和自己的不幸（遇到吝书的张氏）对比，勉励黄生知道幸运与不幸，读书必专、归书必速。全文论点鲜明、对比鲜明、论证严密、语言精炼、勉励殷切，「书非借不能读也」成为千古名句，是论说文的典范。",
    b: "袁枚这篇《黄生借书说》通过黄生借书的事，阐明「书非借不能读也」的道理——借书读才会用心专一，拥有书反而会束之高阁，勉励人们珍惜读书的机会、专心读书，是中国古代论说文的千古名篇。",
    n: ["黄生借书说：篇名，袁枚作，黄生，姓黄的年轻人；借书说，关于借书的论说","黄生允修借书：黄生允修借书（年轻人黄允修来借书。生，年轻人）","随园主人授以书而告之曰：随园主人授以书而告之曰（随园主人把书交给他并且告诉他说。随园主人，袁枚自称，因居江宁随园）","书非借不能读也：书非借不能读也（书不是借来的就不能好好读。这是本文的中心论点）","子不闻藏书者乎：子不闻藏书者乎（你没有听说过藏书的人吗。子，你）","七略四库：七略四库（七略，西汉刘歆编的书目；四库，经史子集四部，指《四库全书》。代指皇家藏书）","天子之书：天子之书（天子的书）","然天子读书者有几：然天子读书者有几（然而天子读书的有几个呢）","汗牛塞屋：汗牛塞屋（形容书籍极多——搬运时牛累得出汗，放置时塞满屋子。汗牛，牛累得出汗；塞屋，塞满屋子）","富贵家之书：富贵家之书（富贵人家的书）","然富贵人读书者有几：然富贵人读书者有几（然而富贵人读书的有几个呢）","其他祖父积、子孙弃者无论焉：其他祖父积、子孙弃者无论焉（其他祖父积累、子孙丢弃的就不用说了。祖父，祖父和父亲；无论，不用说）","非独书为然：非独书为然（不只是书是这样。然，这样）","天下物皆然：天下物皆然（天下的事物都是这样）","非夫人之物而强假焉：非夫人之物而强假焉（不是那个人自己的东西而勉强借来。夫音fú，那；强假，勉强借来）","必虑人逼取：必虑人逼取（一定担心别人催着要回。虑，担心；逼取，催着要回）","而惴惴焉摩玩之不已：而惴惴焉摩玩之不已（而惴惴不安地抚摸玩赏它不停。惴惴音zhuìzhuì，不安的样子；摩玩，抚摸玩赏）","曰：曰","今日存：今日存（今天还在我这里）","明日去：明日去（明天就要被拿走了）","吾不得而见之矣：吾不得而见之矣（我不能再看到它了）","若业为吾所有：若业为吾所有（如果已经被我拥有了。业，已经）","必高束焉：必高束焉（一定高高地捆起来。高束，高高地捆起来）","庋藏焉：庋藏焉（收藏起来。庋音guǐ，放置，收藏）","曰：曰","姑俟异日观云尔：姑俟异日观云尔（姑且等以后再看吧。姑，姑且；俟音sì，等待；异日，以后；云尔，罢了）","余幼好书：余幼好书（我小时候喜欢书）","家贫难致：家贫难致（家里贫穷难以得到。致，得到）","有张氏藏书甚富：有张氏藏书甚富（有个姓张的人家藏书很丰富。富，丰富）","往借：往借（去借）","不与：不与（不给。与，给）","归而形诸梦：归而形诸梦（回来后在梦中还出现借书的情景。形诸梦，形之于梦，在梦中出现）","其切如是：其切如是（那种迫切的心情像这样。切，迫切）","故有所览辄省记：故有所览辄省记（所以有看过的书就记住了。辄音zhé，就；省记，记住）","通籍后：通籍后（做官以后。通籍，做官，名字记在宫门外的竹牒上）","俸去书来：俸去书来（俸禄花出去书买进来。俸，俸禄）","落落大满：落落大满（堆得满满的。落落，堆集的样子）","素蟫灰丝时蒙卷轴：素蟫灰丝时蒙卷轴（白色的蠹鱼和灰尘蛛丝时常蒙在书卷上。素蟫音yín，白色的蠹鱼；灰丝，灰尘蛛丝；卷轴，书卷）","然后叹借者之用心专：然后叹借者之用心专（然后感叹借书的人用心专一）","而少时之岁月为可惜也：而少时之岁月为可惜也（而少年时的岁月是值得珍惜的。可惜，值得珍惜）","今黄生贫类予：今黄生贫类予（现在黄生贫穷像我一样。类，像）","其借书亦类予：其借书亦类予（他借书也像我一样）","惟予之公书与张氏之吝书若不相类：惟予之公书与张氏之吝书若不相类（只是我把书公开借给人和张氏吝惜书好像不一样。公书，把书公开借给人；吝书，吝惜书）","然则予固不幸而遇张乎：然则予固不幸而遇张乎（那么我本来不幸遇到了张氏吗。固，本来）","生固幸而遇予乎：生固幸而遇予乎（黄生本来幸运遇到了我吗）","知幸与不幸：知幸与不幸（知道幸运和不幸）","则其读书也必专：则其读书也必专（那么他读书一定专心）","而其归书也必速：而其归书也必速（而他还书也一定快。归，还）","为一说：为一说（写了这篇论说）","使与书俱：使与书俱（让它和书一起交给黄生。俱，一起）"]
  },
  "狱中题壁|谭嗣同": {
    s: "首两句「望门投止思张俭，忍死须臾待杜根」写望门投止思张俭、忍死须臾待杜根，以「望门投止思张俭」用张俭的典故写对逃亡的康有为、梁启超的思念——张俭被通缉时人们都冒险收留他，希望康有为、梁启超也能得到人们的帮助，以「忍死须臾待杜根」用杜根的典故写对变法事业的期待——杜根装死逃脱后最终等到了太后还政，希望变法事业也能等到成功的一天；后两句「我自横刀向天笑，去留肝胆两昆仑」是千古名句——我自己横刀向天大笑，离去的和留下的肝胆相照，都像昆仑山一样崇高，以「横刀向天笑」写就义时的豪迈——横拿着刀向天大笑，视死如归，以「去留肝胆两昆仑」写对同志的敬意——离去的（康有为、梁启超）和留下的（自己）肝胆相照，都像昆仑山一样崇高，全诗用典贴切、对仗工稳、情感深沉、豪迈激昂、视死如归、崇高感人，「我自横刀向天笑，去留肝胆两昆仑」成为千古名句，是七绝的千古名篇。",
    b: "谭嗣同（清末维新派政治家、思想家，「戊戌六君子」之一，字复生，号壮飞）这首《狱中题壁》是他在戊戌变法失败后被捕入狱、就义前所作，「我自横刀向天笑，去留肝胆两昆仑」是千古名句，表达了他为变法献身的崇高精神和豪迈气概，是七绝的千古名篇。",
    n: ["狱中题壁：诗题，在监狱中题在墙壁上","望门投止思张俭：望门投止思张俭（望门投止，看到人家就去投宿；张俭，东汉人，因弹劾宦官被通缉，人们敬重他的名望，都冒险收留他。用《后汉书·张俭传》典故）","忍死须臾待杜根：忍死须臾待杜根（忍死，忍死等待；须臾，片刻；杜根，东汉人，因上书要求邓太后还政安帝，被太后下令装在袋中摔死，执法者敬其为人，故意不摔死，后装死逃脱。用《后汉书·杜根传》典故）","我自横刀向天笑：我自横刀向天笑（我自己横刀向天大笑。横刀，横拿着刀，指就义）","去留肝胆两昆仑：去留肝胆两昆仑（离去的和留下的肝胆相照，都像昆仑山一样崇高。去，指逃亡的康有为、梁启超；留，指自己留下；两昆仑，指康有为和自己，一说指大刀王五和自己）"]
  },
  "论诗|赵翼": {
    s: "首两句「李杜诗篇万口传，至今已觉不新鲜」写李杜诗篇万口传、至今已觉不新鲜，以「李杜诗篇万口传」写李白杜甫的成就——诗篇万人传诵，以「至今已觉不新鲜」写对创新的主张——即使是李杜的诗篇，到现在也觉得不新鲜了，需要创新；后两句「江山代有才人出，各领风骚数百年」写江山代有才人出、各领风骚数百年，以「江山代有才人出」写人才的代代涌现——江山代代有有才的人出现，以「各领风骚数百年」写各自的成就——各自引领文学潮流数百年，全诗论点鲜明、语言精炼、哲理深刻、主张创新、积极向上，「江山代有才人出，各领风骚数百年」成为千古名句，是七绝的名篇。",
    b: "赵翼（清代史学家、诗人，字云崧，号瓯北）这首《论诗》论诗歌创作，主张创新——「江山代有才人出，各领风骚数百年」，是七绝的名篇。",
    n: ["论诗：诗题，论诗的诗","李杜诗篇万口传：李杜诗篇万口传（李白杜甫的诗篇万人传诵。李杜，李白、杜甫）","至今已觉不新鲜：至今已觉不新鲜（到现在已经觉得不新鲜了）","江山代有才人出：江山代有才人出（江山代代有有才的人出现。才人，有才的人）","各领风骚数百年：各领风骚数百年（各自引领风骚数百年。风骚，《诗经》的《国风》和《楚辞》的《离骚》，代指文学）"]
  },
  "精卫|顾炎武": {
    s: "全诗分三层：第一层「万事有不平，尔何空自苦。长将一寸身，衔木到终古」以旁人的口吻问精卫——万事有不平的事，你为什么白白地自讨苦吃，长久地用一寸长的身子，衔木石到永远呢；第二层「我愿平东海，身沉心不改。大海无平期，我心无绝时」以精卫的口吻回答——我愿意填平东海，身子沉了心也不改，大海没有填平的日子，我的心没有断绝的时候，以「身沉心不改」「我心无绝时」写精卫填海的坚定意志和不屈精神——即使身子沉了，心也不改，即使大海没有填平的日子，心也没有断绝的时候；第三层「呜呼！君不见西山衔木众鸟多，鹊来燕去自成窠」以众鸟的对比写精卫的孤独和崇高——你没看见西山衔木的众鸟很多吗，喜鹊来燕子去各自筑成窠巢，以众鸟「自成窠」的自私对比精卫「填东海」的无私，以众鸟的平凡对比精卫的崇高。全诗用典贴切、对比鲜明、情感深沉、坚定不屈、崇高感人，「我愿平东海，身沉心不改。大海无平期，我心无绝时」成为名句，是古体诗的名篇。",
    b: "顾炎武（明末清初思想家、学者，「清学开山」，字宁人，号亭林）这首《精卫》以精卫填海的神话自喻，「我愿平东海，身沉心不改。大海无平期，我心无绝时」是名句，表达了他抗清复明的坚定意志和不屈精神，是古体诗的名篇。",
    n: ["精卫：诗题，精卫，古代神话中的鸟，相传是炎帝的女儿女娃溺死于东海后化为精卫鸟，衔西山木石填东海","万事有不平：万事有不平（万事有不平的事）","尔何空自苦：尔何空自苦（你为什么白白地自讨苦吃。尔，你，指精卫）","长将一寸身：长将一寸身（长久地用一寸长的身子。将，用）","衔木到终古：衔木到终古（衔木石到永远。终古，永远）","我愿平东海：我愿平东海（我愿意填平东海。精卫的口吻）","身沉心不改：身沉心不改（身子沉了心也不改）","大海无平期：大海无平期（大海没有填平的日子）","我心无绝时：我心无绝时（我的心没有断绝的时候）","呜呼：呜呼（感叹词）","君不见西山衔木众鸟多：君不见西山衔木众鸟多（你没看见西山衔木的众鸟很多吗）","鹊来燕去自成窠：鹊来燕去自成窠（喜鹊来燕子去各自筑成窠巢。窠音kē，巢穴）"]
  },
  "村居|高鼎": {
    s: "首两句「草长莺飞二月天，拂堤杨柳醉春烟」写草长莺飞二月天、拂堤杨柳醉春烟，以「草长莺飞」写春天的生机——青草生长黄莺飞舞，以「拂堤杨柳醉春烟」写春天的美景——拂着堤岸的杨柳陶醉在春天的烟雾中；后两句「儿童散学归来早，忙趁东风放纸鸢」写儿童散学归来早、忙趁东风放纸鸢，以「散学归来早」写儿童的欢乐——放学回来得早，以「忙趁东风放纸鸢」写儿童放风筝的欢乐——忙着趁东风放风筝，全诗意境优美、画面生动、情感欢乐、清新自然、童趣盎然，「儿童散学归来早，忙趁东风放纸鸢」成为名句，是七绝的名篇。",
    b: "高鼎（清代诗人，字象一，又字拙吾）这首《村居》写乡村春天的景色和儿童放风筝的欢乐，「儿童散学归来早，忙趁东风放纸鸢」是名句，是七绝的名篇。",
    n: ["村居：诗题，在乡村居住","草长莺飞二月天：草长莺飞二月天（青草生长黄莺飞舞的二月天。莺，黄莺）","拂堤杨柳醉春烟：拂堤杨柳醉春烟（拂着堤岸的杨柳陶醉在春天的烟雾中。拂，拂拭；春烟，春天的烟雾）","儿童散学归来早：儿童散学归来早（儿童放学回来得早。散学，放学）","忙趁东风放纸鸢：忙趁东风放纸鸢（忙着趁东风放风筝。纸鸢，风筝。鸢音yuān）"]
  },
  "杂感|黄景仁": {
    s: "首联「仙佛茫茫两未成，只知独夜不平鸣」写仙佛茫茫两未成、只知独夜不平鸣，以「仙佛茫茫两未成」写一生的失意——成仙成佛都茫茫然没有成功，以「独夜不平鸣」写内心的悲愤——只知道在孤独的夜晚发出不平的鸣声；颔联「风蓬飘尽悲歌气，泥絮沾来薄幸名」写风蓬飘尽悲歌气、泥絮沾来薄幸名，以「风蓬飘尽悲歌气」写漂泊的艰辛——风中的蓬草飘尽了悲歌的气概，以「泥絮沾来薄幸名」写心境的沉寂——泥中的柳絮沾来了薄情的名声；颈联「十有九人堪白眼，百无一用是书生」是千古名句——十个人中有九个人可以给白眼，百样之中没有一样有用的是书生，以「十有九人堪白眼」用阮籍「青白眼」典故写对世俗的蔑视——十个人中有九个人可以给白眼，以「百无一用是书生」写书生的无奈和悲愤——百样之中没有一样有用的是书生，是封建社会中失意文人的悲愤呐喊；尾联「莫因诗卷愁成谶，春鸟秋虫自作声」写莫因诗卷愁成谶、春鸟秋虫自作声，以「莫因诗卷愁成谶」写自我安慰——不要因为诗卷中的忧愁成为谶语，以「春鸟秋虫自作声」写坚持自我——春天的鸟秋天的虫自己发出声音，即使忧愁也要坚持创作，全诗用典贴切、对仗工稳、情感深沉、悲愤激昂、无奈感人，「十有九人堪白眼，百无一用是书生」成为千古名句，是七律的名篇。",
    b: "黄景仁（清代诗人，字汉镛，号仲则，「毗陵七子」之一，一生贫困潦倒）这首《杂感》写他一生的失意和悲愤，「十有九人堪白眼，百无一用是书生」是千古名句，是七律的名篇。",
    n: ["杂感：诗题，杂感，各种感想","仙佛茫茫两未成：仙佛茫茫两未成（成仙成佛都茫茫然没有成功。仙佛，成仙成佛）","只知独夜不平鸣：只知独夜不平鸣（只知道在孤独的夜晚发出不平的鸣声。独夜，孤独的夜晚；不平鸣，不平则鸣）","风蓬飘尽悲歌气：风蓬飘尽悲歌气（风中的蓬草飘尽了悲歌的气概。风蓬，风中的蓬草，比喻漂泊）","泥絮沾来薄幸名：泥絮沾来薄幸名（泥中的柳絮沾来了薄情的名声。泥絮，泥中的柳絮，比喻心境沉寂；薄幸，薄情）","十有九人堪白眼：十有九人堪白眼（十个人中有九个人可以给白眼。白眼，用阮籍「青白眼」典故，对不喜欢的人翻白眼）","百无一用是书生：百无一用是书生（百样之中没有一样有用的是书生）","莫因诗卷愁成谶：莫因诗卷愁成谶（不要因为诗卷中的忧愁成为谶语。谶音chèn，谶语，预言）","春鸟秋虫自作声：春鸟秋虫自作声（春天的鸟秋天的虫自己发出声音。用韩愈「以鸟鸣春，以虫鸣秋」的意思）"]
  },
  "己亥杂诗·其二百二十|龚自珍": {
    s: "首两句「九州生气恃风雷，万马齐喑究可哀」写九州生气恃风雷、万马齐喑究可哀，以「九州生气恃风雷」写对社会变革的渴望——九州的生气依靠风雷，只有风雷激荡才能带来生机，以「万马齐喑究可哀」写对社会沉闷的忧虑——万马都沉默终究是可悲的，比喻社会沉闷、人们都不敢说话；后两句「我劝天公重抖擞，不拘一格降人才」写我劝天公重抖擞、不拘一格降人才，以「我劝天公重抖擞」写对天公的劝勉——我劝天公重新振作精神，以「不拘一格降人才」写对人才的渴望——不拘泥于一种规格降下人才，打破常规、选拔人才，全诗比喻新奇、对比鲜明、情感深沉、忧国忧民、渴望变革、崇高感人，「我劝天公重抖擞，不拘一格降人才」成为千古名句，是七绝的千古名篇。",
    b: "龚自珍（清代思想家、文学家，字璱人，号定庵，近代思想启蒙的先驱）这首《己亥杂诗·其二百二十》写他对社会沉闷的忧虑和对人才的渴望，「我劝天公重抖擞，不拘一格降人才」是千古名句，是七绝的千古名篇。",
    n: ["己亥杂诗：诗题，己亥，1839年；杂诗，组诗，共315首","九州生气恃风雷：九州生气恃风雷（九州的生气依靠风雷。九州，中国；生气，生机；恃，依靠；风雷，风神雷神，比喻社会变革）","万马齐喑究可哀：万马齐喑究可哀（万马都沉默终究是可悲的。喑音yīn，沉默；万马齐喑，比喻社会沉闷、人们都不敢说话）","我劝天公重抖擞：我劝天公重抖擞（我劝天公重新振作精神。天公，天帝；抖擞，振作精神）","不拘一格降人才：不拘一格降人才（不拘泥于一种规格降下人才。不拘一格，不拘泥于一种规格）"]
  },
  "病梅馆记|龚自珍": {
    s: "全文（节选）分四段：第一段写产梅之地和「病梅」的标准——「江宁之龙蟠，苏州之邓尉，杭州之西溪，皆产梅」，写三大产梅之地；「或曰：梅以曲为美，直则无姿；以欹为美，正则无景；以疏为美，密则无态。固也」，写文人画士对梅花的审美标准——以曲、欹、疏为美，以直、正、密为无姿态；第二段写「病梅」的成因——「此文人画士，心知其意，未可明诏大号，以绳天下之梅也；又不可以使天下之民，斫直、删密、锄正，以夭梅病梅为业以求钱也」，写文人画士心里知道这个意思，但不可以公开宣告来衡量天下的梅花，也不可以使百姓以摧残梅花为业求钱；「有以文人画士孤癖之隐，明告鬻梅者，斫其正，养其旁条，删其密，夭其稚枝，锄其直，遏其生气，以求重价，而江浙之梅皆病。文人画士之祸之烈至此哉」，写有人把文人画士孤癖的隐情告诉卖梅的人，卖梅的人砍正枝、养旁条、删密枝、摧嫩枝、锄直枝、遏生机，以求高价，结果江浙的梅花都病了，文人画士的祸害惨烈到了这个地步；第三段写疗救病梅——「予购三百盆，皆病者，无一完者。既泣之三日，乃誓疗之：纵之顺之，毁其盆，悉埋于地，解其棕缚，以五年为期，必复之全之」，写作者买了三百盆病梅，哭了三天，发誓疗救——放纵它们顺应它们，毁坏花盆，都埋在地里，解开棕绳捆绑，以五年为期，一定使它们恢复完整；「予本非文人画士，甘受诟厉，辟病梅之馆以贮之」，写作者甘愿受辱骂，开辟病梅馆贮藏病梅；第四段写愿望——「呜呼！安得使予多暇日，又多闲田，以广贮江宁、杭州、苏州之病梅，穷予生之光阴以疗梅也哉」，以「安得」的感叹写作者的愿望——怎么能使我多有闲暇的日子和空闲的田地，大量贮藏病梅，穷尽一生的光阴来疗救梅花呢。全文以梅喻人、托物言志、对比鲜明、寓意深刻、情感深沉、要求改革、追求解放，「纵之顺之，毁其盆，悉埋于地，解其棕缚，以五年为期，必复之全之」成为名句，是寓言散文的典范。",
    b: "龚自珍这篇《病梅馆记》以病梅为喻，揭露和批判了封建统治阶级对人才的摧残和束缚，表达了作者要求改革政治、追求个性解放的强烈愿望，「纵之顺之」「必复之全之」是名句，是中国古代寓言散文的千古名篇。",
    n: ["病梅馆记：篇名，龚自珍作，病梅馆，作者为疗救病梅而建的馆舍","江宁之龙蟠：江宁之龙蟠（江宁的龙蟠里。江宁，今南京；龙蟠，龙蟠里，在南京清凉山下）","苏州之邓尉：苏州之邓尉（苏州的邓尉山。邓尉，山名，在今苏州吴中区，因汉代邓尉隐居于此得名，多梅）","杭州之西溪：杭州之西溪（杭州的西溪。西溪，在今杭州西湖区，多梅）","皆产梅：皆产梅（都产梅花）","或曰：或曰（有人说）","梅以曲为美：梅以曲为美（梅花以弯曲为美）","直则无姿：直则无姿（直了就没有姿态）","以欹为美：以欹为美（以倾斜为美。欹音qī，倾斜）","正则无景：正则无景（正了就没有景致。景同「影」）","以疏为美：以疏为美（以稀疏为美）","密则无态：密则无态（密了就没有姿态）","固也：固也（本来是这样。固，本来）","此文人画士：此文人画士（这些文人画士）","心知其意：心知其意（心里知道这个意思）","未可明诏大号：未可明诏大号（不可以公开宣告大声号召。明诏，公开宣告；大号，大声号召）","以绳天下之梅也：以绳天下之梅也（来衡量天下的梅花。绳，衡量）","又不可以使天下之民：又不可以使天下之民（又不可以使天下的百姓）","斫直、删密、锄正：斫直、删密、锄正（砍直的、删密的、锄正的。斫音zhuó，砍）","以夭梅病梅为业以求钱也：以夭梅病梅为业以求钱也（以摧残梅花使梅花病残为职业来求钱。夭，摧残；病梅，使梅花病残）","梅之欹之疏之曲：梅之欹之疏之曲（梅花的倾斜、稀疏、弯曲）","又非蠢蠢求钱之民：又非蠢蠢求钱之民（又不是愚蠢的求钱的百姓）","能以其智力为也：能以其智力为也（能够用他们的智力做到的）","有以文人画士孤癖之隐：有以文人画士孤癖之隐（有人把文人画士孤癖的隐情。孤癖，孤高的癖好；隐，隐情）","明告鬻梅者：明告鬻梅者（明白地告诉卖梅的人。鬻音yù，卖）","斫其正：斫其正（砍去它的正枝）","养其旁条：养其旁条（培养它的旁枝）","删其密：删其密（删去它的密枝）","夭其稚枝：夭其稚枝（摧残它的嫩枝。夭，摧残；稚枝，嫩枝）","锄其直：锄其直（锄去它的直枝）","遏其生气：遏其生气（遏制它的生机。遏音è，遏制）","以求重价：以求重价（来求高价）","而江浙之梅皆病：而江浙之梅皆病（而江浙的梅花都病了）","文人画士之祸之烈至此哉：文人画士之祸之烈至此哉（文人画士的祸害的惨烈到了这个地步啊。烈，惨烈）","予购三百盆：予购三百盆（我买了三百盆梅花）","皆病者：皆病者（都是病梅）","无一完者：无一完者（没有一盆是完好的）","既泣之三日：既泣之三日（已经为它们哭了三天。泣，哭）","乃誓疗之：乃誓疗之（于是发誓疗救它们）","纵之顺之：纵之顺之（放纵它们顺应它们。纵，放纵；顺，顺应）","毁其盆：毁其盆（毁坏那些花盆）","悉埋于地：悉埋于地（都埋在地里。悉，都）","解其棕缚：解其棕缚（解开它们的棕绳捆绑。棕缚，棕绳的捆绑）","以五年为期：以五年为期（以五年为期限）","必复之全之：必复之全之（一定使它们恢复完整。复，恢复；全，使完整）","予本非文人画士：予本非文人画士（我本来不是文人画士）","甘受诟厉：甘受诟厉（甘愿受到辱骂。诟厉音gòulì，辱骂）","辟病梅之馆以贮之：辟病梅之馆以贮之（开辟病梅馆来贮藏它们。辟，开辟；贮，贮藏）","呜呼：呜呼（感叹词）","安得使予多暇日：安得使予多暇日（怎么能使我多有闲暇的日子。安得，怎么能；暇日，闲暇的日子）","又多闲田：又多闲田（又多有空闲的田地）","以广贮江宁、杭州、苏州之病梅：以广贮江宁、杭州、苏州之病梅（来大量贮藏江宁、杭州、苏州的病梅。广贮，大量贮藏）","穷予生之光阴以疗梅也哉：穷予生之光阴以疗梅也哉（穷尽我一生的光阴来疗救梅花呢。穷，穷尽）"]
  },
  "少年中国说（节选）|梁启超": {
    s: "全文（节选）分五层：第一层提出问题——「日本人之称我中国也，一则曰老大帝国，再则曰老大帝国。是语也，盖袭译欧西人之言也。呜呼！我中国其果老大矣乎？梁启超曰：恶！是何言！是何言！吾心目中有一少年中国在」，以「老大帝国」的论调引出问题——我们中国果真老大了吗，以「吾心目中有一少年中国在」提出中心论点——我的心目中有一个少年中国存在；第二层以人之老少喻国之老少——「欲言国之老少，请先言人之老少。老年人常思既往，少年人常思将来……」，以老年人和少年人的对比——老年人思既往、生留恋、保守、永旧、灰心、怯懦、苟且、厌事，少年人思将来、生希望、进取、日新、盛气、豪壮、冒险、喜事，写老少的不同；「老年人如夕照，少年人如朝阳。老年人如瘠牛，少年人如乳虎……」，以一连串的比喻写老少的不同——老年人像夕照、瘠牛、僧、字典、鸦片烟、陨石、金字塔、秋后之柳、死海之潴，少年人像朝阳、乳虎、侠、戏文、白兰地、珊瑚岛、西伯利亚铁路、春前之草、长江之初发源；「人固有之，国亦宜然」，以人的老少推及国家的老少——人本来有这种不同，国家也应该是这样；第三层点明责任——「故今日之责任，不在他人，而全在我少年。少年智则国智，少年富则国富，少年强则国强，少年独立则国独立，少年自由则国自由，少年进步则国进步，少年胜于欧洲则国胜于欧洲，少年雄于地球则国雄于地球」，以排比句写少年与国家的关系——少年智慧国家就智慧，少年富裕国家就富裕，少年强大国家就强大，少年独立国家就独立，少年自由国家就自由，少年进步国家就进步，少年胜于欧洲国家就胜于欧洲，少年雄于地球国家就雄于地球，气势磅礴、振奋人心；第四层以比喻歌颂少年中国——「红日初升，其道大光。河出伏流，一泻汪洋。潜龙腾渊，鳞爪飞扬。乳虎啸谷，百兽震惶。鹰隼试翼，风尘吸张。奇花初胎，矞矞皇皇。干将发硎，有作其芒。天戴其苍，地履其黄。纵有千古，横有八荒。前途似海，来日方长」，以一连串的比喻歌颂少年中国的朝气蓬勃——像红日初升、河出伏流、潜龙腾渊、乳虎啸谷、鹰隼试翼、奇花初胎、干将发硎，前途似海、来日方长；第五层总结——「美哉我少年中国，与天不老！壮哉我中国少年，与国无疆！」，以「美哉」「壮哉」的感叹歌颂少年中国和中国少年——美啊我们的少年中国，和天一样不老；壮啊我们的中国少年，和国家一样万寿无疆。全文排比磅礴、比喻丰富、情感激昂、气势雄浑、振奋人心、鼓舞斗志，「少年智则国智，少年富则国富，少年强则国强」「美哉我少年中国，与天不老；壮哉我中国少年，与国无疆」成为千古名句，是中国近代散文的千古名篇。",
    b: "梁启超（近代思想家、政治家、学者，「戊戌变法」领袖之一，字卓如，号任公，又号饮冰室主人）这篇《少年中国说》写于1900年，通过批判「老大帝国」的论调，歌颂「少年中国」的朝气蓬勃，勉励中国少年担当起振兴中华的责任，「少年智则国智，少年富则国富，少年强则国强」「美哉我少年中国，与天不老；壮哉我中国少年，与国无疆」是千古名句，是中国近代散文的千古名篇。",
    n: ["少年中国说：篇名，梁启超作，少年中国，年轻的中国","日本人之称我中国也：日本人之称我中国也（日本人称呼我们中国）","一则曰老大帝国：一则曰老大帝国（一则叫老大帝国。老大，年老体衰）","再则曰老大帝国：再则曰老大帝国（再则叫老大帝国）","是语也：是语也（这句话）","盖袭译欧西人之言也：盖袭译欧西人之言也（大概是沿袭翻译欧西人的话。袭译，沿袭翻译；欧西，欧洲西方）","呜呼：呜呼（感叹词）","我中国其果老大矣乎：我中国其果老大矣乎（我们中国果真老大了吗。果，果真）","梁启超曰：梁启超曰（梁启超说）","恶：恶（哪里，怎么。恶音wū）","是何言：是何言（这是什么话）","是何言：是何言","吾心目中有一少年中国在：吾心目中有一少年中国在（我的心目中有一个少年中国存在）","欲言国之老少：欲言国之老少（要说国家的老少）","请先言人之老少：请先言人之老少（请先说说人的老少）","老年人常思既往：老年人常思既往（老年人常想过去。既往，过去）","少年人常思将来：少年人常思将来（少年人常想将来）","惟思既往也：惟思既往也（因为想过去）","故生留恋心：故生留恋心（所以产生留恋心）","惟思将来也：惟思将来也（因为想将来）","故生希望心：故生希望心（所以产生希望心）","惟留恋也：惟留恋也（因为留恋）","故保守：故保守（所以保守）","惟希望也：惟希望也（因为希望）","故进取：故进取（所以进取）","惟保守也：惟保守也（因为保守）","故永旧：故永旧（所以永远陈旧）","惟进取也：惟进取也（因为进取）","故日新：故日新（所以天天更新）","惟思既往也：惟思既往也","事事皆其所已经者：事事皆其所已经者（事事都是他已经经历过的）","故惟知照例：故惟知照例（所以只知道照例）","惟思将来也：惟思将来也","事事皆其所未经者：事事皆其所未经者（事事都是他没有经历过的）","故常敢破格：故常敢破格（所以常常敢打破常规）","老年人常多忧虑：老年人常多忧虑","少年人常好行乐：少年人常好行乐（少年人常喜欢行乐）","惟多忧也：惟多忧也（因为多忧虑）","故灰心：故灰心（所以灰心）","惟行乐也：惟行乐也（因为行乐）","故盛气：故盛气（所以气盛）","惟灰心也：惟灰心也","故怯懦：故怯懦（所以怯懦。怯懦音qiènuò，胆小懦弱）","惟盛气也：惟盛气也","故豪壮：故豪壮（所以豪壮）","惟怯懦也：惟怯懦也","故苟且：故苟且（所以苟且。苟且，得过且过）","惟豪壮也：惟豪壮也","故冒险：故冒险","惟苟且也：惟苟且也","故能灭世界：故能灭世界（所以能灭世界）","惟冒险也：惟冒险也","故能造世界：故能造世界（所以能造世界）","老年人常厌事：老年人常厌事（老年人常厌弃事情）","少年人常喜事：少年人常喜事（少年人常喜欢事情）","惟厌事也：惟厌事也","故常觉一切事无可为者：故常觉一切事无可为者（所以常觉得一切事没有可以做的）","惟喜事也：惟喜事也","故常觉一切事无不可为者：故常觉一切事无不可为者（所以常觉得一切事没有不可以做的）","老年人如夕照：老年人如夕照（老年人像夕阳）","少年人如朝阳：少年人如朝阳","老年人如瘠牛：老年人如瘠牛（老年人像瘦牛。瘠音jí，瘦）","少年人如乳虎：少年人如乳虎（少年人像幼虎。乳虎，幼虎）","老年人如僧：老年人如僧（老年人像和尚）","少年人如侠：少年人如侠（少年人像侠客）","老年人如字典：老年人如字典","少年人如戏文：少年人如戏文（少年人像戏曲）","老年人如鸦片烟：老年人如鸦片烟","少年人如泼兰地酒：少年人如泼兰地酒（少年人像白兰地酒。泼兰地，白兰地）","老年人如别行星之陨石：老年人如别行星之陨石（老年人像别的行星的陨石）","少年人如大洋海之珊瑚岛：少年人如大洋海之珊瑚岛","老年人如埃及沙漠之金字塔：老年人如埃及沙漠之金字塔","少年人如西比利亚之铁路：少年人如西比利亚之铁路（少年人像西伯利亚的铁路。西比利亚，西伯利亚）","老年人如秋后之柳：老年人如秋后之柳","少年人如春前之草：少年人如春前之草","老年人如死海之潴为泽：老年人如死海之潴为泽（老年人像死海的积水成湖。潴音zhū，积水）","少年人如长江之初发源：少年人如长江之初发源","此老年与少年性格不同之大略也：此老年与少年性格不同之大略也（这是老年与少年性格不同的大概。大略，大概）","梁启超曰：梁启超曰","人固有之：人固有之（人本来有这种不同。固，本来）","国亦宜然：国亦宜然（国家也应该是这样。宜然，应该这样）","故今日之责任：故今日之责任（所以今天的责任）","不在他人：不在他人","而全在我少年：而全在我少年（而全在我们少年）","少年智则国智：少年智则国智（少年智慧国家就智慧）","少年富则国富：少年富则国富（少年富裕国家就富裕）","少年强则国强：少年强则国强","少年独立则国独立：少年独立则国独立","少年自由则国自由：少年自由则国自由","少年进步则国进步：少年进步则国进步","少年胜于欧洲则国胜于欧洲：少年胜于欧洲则国胜于欧洲","少年雄于地球则国雄于地球：少年雄于地球则国雄于地球","红日初升：红日初升（红太阳刚刚升起）","其道大光：其道大光（它的道路大放光芒。道，道路）","河出伏流：河出伏流（黄河从地下流出。伏流，地下暗流）","一泻汪洋：一泻汪洋（一泻千里成为汪洋）","潜龙腾渊：潜龙腾渊（潜伏的龙从深渊腾起。渊，深渊）","鳞爪飞扬：鳞爪飞扬（鳞爪飞扬）","乳虎啸谷：乳虎啸谷（幼虎在山谷中咆哮。啸，咆哮）","百兽震惶：百兽震惶（百兽震惊惶恐。震惶，震惊惶恐）","鹰隼试翼：鹰隼试翼（鹰隼试飞翅膀。隼音sǔn，一种猛禽）","风尘吸张：风尘吸张（风尘一合一张。吸张，收缩扩张）","奇花初胎：奇花初胎（奇花刚开始孕育。胎，孕育）","矞矞皇皇：矞矞皇皇（光明盛大的样子。矞矞音yùyù，光明盛大；皇皇，盛大）","干将发硎：干将发硎（干将剑刚从磨刀石上磨出来。干将，古代宝剑名；发硎，刚从磨刀石上磨出来。硎音xíng，磨刀石）","有作其芒：有作其芒（发出它的光芒。芒，光芒）","天戴其苍：天戴其苍（头顶着苍天。戴，顶着；苍，苍天）","地履其黄：地履其黄（脚踏着黄土。履，踏着；黄，黄土）","纵有千古：纵有千古（纵向有千古的历史）","横有八荒：横有八荒（横向有八方的荒野。八荒，八方荒远之地）","前途似海：前途似海（前途像大海一样广阔）","来日方长：来日方长（未来的日子还长）","美哉我少年中国：美哉我少年中国（美啊我们的少年中国）","与天不老：与天不老（和天一样不老）","壮哉我中国少年：壮哉我中国少年（壮啊我们的中国少年）","与国无疆：与国无疆（和国家一样万寿无疆。无疆，没有疆界，无穷无尽）"]
  },
  "蝶恋花·百尺朱楼临大道|王国维": {
    s: "上片「百尺朱楼临大道，楼外轻雷，不间昏和晓。独倚阑干人窈窕，闲中数尽行人小」写百尺朱楼临大道、楼外轻雷不间昏和晓，独倚阑干人窈窕、闲中数尽行人小，以「百尺朱楼临大道」写楼的位置——百尺高的红楼临着大道，以「楼外轻雷，不间昏和晓」写大道的喧嚣——楼外的车声像轻雷，不分黄昏和拂晓，以「独倚阑干人窈窕」写思妇的孤独——独自倚着栏杆的人窈窕美丽，以「闲中数尽行人小」写思妇的无聊——在闲适中数尽了路上的行人，行人都变得渺小；下片「一霎车尘生树杪，陌上楼头，都向尘中老。薄晚西风吹雨到，明朝又是伤流潦」写一霎车尘生树杪、陌上楼头都向尘中老，薄晚西风吹雨到、明朝又是伤流潦，以「一霎车尘生树杪」写车尘的飞扬——一霎时车尘生在树梢，以「陌上楼头，都向尘中老」写人生的感慨——路上的行人和楼头的思妇，都在尘土中老去，以「薄晚西风吹雨到，明朝又是伤流潦」写对未来的伤感——傍晚西风吹雨到来，明天又要为路上的积水而伤感，全词意境凄清、寓意深刻、情感深沉、人生哲理、婉约感人，「陌上楼头，都向尘中老」成为名句，是婉约词中寓含人生哲理的名篇。",
    b: "王国维（近代学者、词人，字静安，号观堂，「清华四大导师」之一，《人间词话》作者）这首《蝶恋花》写楼头思妇的孤独和对人生的感慨，「陌上楼头，都向尘中老」是名句，是婉约词中寓含人生哲理的名篇。",
    n: ["蝶恋花：词牌名","百尺朱楼临大道：百尺朱楼临大道（百尺高的红楼临着大道。朱楼，红楼）","楼外轻雷：楼外轻雷（楼外的轻雷，指车声）","不间昏和晓：不间昏和晓（不分黄昏和拂晓。间音jiàn，间断，区分）","独倚阑干人窈窕：独倚阑干人窈窕（独自倚着栏杆的人窈窕美丽。阑干，栏杆；窈窕音yǎotiǎo，美好）","闲中数尽行人小：闲中数尽行人小（在闲适中数尽了路上的行人——行人都变得渺小）","一霎车尘生树杪：一霎车尘生树杪（一霎时车尘生在树梢。一霎，一霎时；树杪音miǎo，树梢）","陌上楼头：陌上楼头（路上楼头。陌，路）","都向尘中老：都向尘中老（都在尘土中老去）","薄晚西风吹雨到：薄晚西风吹雨到（傍晚西风吹雨到来。薄晚，傍晚）","明朝又是伤流潦：明朝又是伤流潦（明天又要为路上的积水而伤感。流潦音liúlǎo，路上的积水）"]
  },
  "对酒|秋瑾": {
    s: "首两句「不惜千金买宝刀，貂裘换酒也堪豪」写不惜千金买宝刀、貂裘换酒也堪豪，以「不惜千金买宝刀」写对革命的追求——不吝惜千金买宝刀，以「貂裘换酒也堪豪」写豪迈的气概——用貂皮大衣换酒也足以豪迈；后两句「一腔热血勤珍重，洒去犹能化碧涛」写一腔热血勤珍重、洒去犹能化碧涛，以「一腔热血勤珍重」写对热血的珍重——一腔热血要珍重，以「洒去犹能化碧涛」用「苌弘化碧」典故写献身精神——洒出去还能化作碧绿的波涛，即使牺牲了，热血也能化为革命的波涛，全诗用典贴切、语言精炼、情感激昂、豪迈雄壮、献身精神、崇高感人，「一腔热血勤珍重，洒去犹能化碧涛」成为名句，是七绝的名篇。",
    b: "秋瑾（近代民主革命志士，「鉴湖女侠」，字璿卿，号竞雄）这首《对酒》写她的革命豪情和献身精神，「一腔热血勤珍重，洒去犹能化碧涛」是名句，是七绝的名篇。",
    n: ["对酒：诗题，对着酒","不惜千金买宝刀：不惜千金买宝刀（不吝惜千金买宝刀）","貂裘换酒也堪豪：貂裘换酒也堪豪（用貂皮大衣换酒也足以豪迈。貂裘，貂皮大衣；堪，足以）","一腔热血勤珍重：一腔热血勤珍重（一腔热血要珍重。勤，努力，恳切）","洒去犹能化碧涛：洒去犹能化碧涛（洒出去还能化作碧绿的波涛。用「苌弘化碧」典故——苌弘是周朝忠臣，被杀后血化为碧玉。碧涛，碧绿的波涛）"]
  },
  "满江红·小住京华|秋瑾": {
    s: "上片「小住京华，早又是中秋佳节。为篱下黄花开遍，秋容如拭。四面歌残终破楚，八年风味徒思浙。苦将侬强派作蛾眉，殊未屑」写小住京华、早又是中秋佳节，为篱下黄花开遍、秋容如拭，四面歌残终破楚、八年风味徒思浙，苦将侬强派作蛾眉、殊未屑，以「小住京华，早又是中秋佳节」写时间地点——在京城小住，早又是中秋佳节，以「为篱下黄花开遍，秋容如拭」写中秋景色——篱笆下菊花开遍，秋天的景色像擦过一样明净，以「四面歌残终破楚」用「四面楚歌」典故写民族危机——四面歌声残败最终攻破了楚国，比喻中国被列强包围、民族危机严重，以「八年风味徒思浙」写对家乡的思念——八年的风味白白思念浙江，以「苦将侬强派作蛾眉，殊未屑」写对女子身份的不屑——苦苦地把我勉强派作女子，实在不屑；下片「身不得，男儿列；心却比，男儿烈。算平生肝胆，因人常热。俗子胸襟谁识我？英雄末路当磨折。莽红尘，何处觅知音？青衫湿」写身不得男儿列、心却比男儿烈，算平生肝胆、因人常热，俗子胸襟谁识我、英雄末路当磨折，莽红尘何处觅知音、青衫湿，以「身不得，男儿列；心却比，男儿烈」写巾帼英雄的壮志——身子不能列入男儿的行列，心却比男儿刚烈，是千古名句，以「算平生肝胆，因人常热」写自己的热血——算我平生的肝胆，因为别人常常热血沸腾，以「俗子胸襟谁识我」写不被理解的苦闷——世俗之人的胸襟谁能了解我，以「英雄末路当磨折」写对磨难的坦然——英雄在末路时应当受磨难，以「莽红尘，何处觅知音？青衫湿」用白居易「青衫湿」典故写寻找知音的渴望——茫茫的红尘，到哪里寻找知音，青衫湿了，落泪了。全词用典丰富、情感激昂、气势雄浑、巾帼英雄、壮志难酬、知音难觅、感人至深，「身不得，男儿列；心却比，男儿烈」成为千古名句，是豪放词中巾帼英雄的千古名篇。",
    b: "秋瑾这首《满江红·小住京华》写于1903年中秋节，她在京城小住时写下这首词，抒发了她身为女子却心怀壮志、不被理解的苦闷和寻找知音的渴望，「身不得，男儿列；心却比，男儿烈」是名句，是豪放词中巾帼英雄的千古名篇。",
    n: ["满江红：词牌名","小住京华：小住京华（在京城小住。京华，京城）","早又是：早又是（早又是）","中秋佳节：中秋佳节","为篱下：为篱下（篱笆下。用陶渊明「采菊东篱下」典故）","黄花开遍：黄花开遍（菊花开遍）","秋容如拭：秋容如拭（秋天的景色像擦过一样明净。拭，擦）","四面歌残终破楚：四面歌残终破楚（四面歌声残败最终攻破了楚国。用「四面楚歌」典故——项羽被围垓下，四面楚歌，最终兵败。这里比喻中国被列强包围、民族危机严重）","八年风味徒思浙：八年风味徒思浙（八年的风味白白思念浙江。秋瑾1896年结婚，1904年赴日本留学，前后八年；浙，浙江，秋瑾的家乡）","苦将侬：苦将侬（苦苦地把我。侬音nóng，我）","强派作蛾眉：强派作蛾眉（勉强派作女子。蛾眉，代指女子）","殊未屑：殊未屑（实在不屑。殊，实在；未屑，不屑）","身不得：身不得（身子不能）","男儿列：男儿列（列入男儿的行列）","心却比：心却比（心却比）","男儿烈：男儿烈（男儿刚烈）","算平生肝胆：算平生肝胆（算我平生的肝胆。肝胆，指真心诚意）","因人常热：因人常热（因为别人常常热血沸腾）","俗子胸襟谁识我：俗子胸襟谁识我（世俗之人的胸襟谁能了解我。俗子，世俗之人）","英雄末路当磨折：英雄末路当磨折（英雄在末路时应当受磨难。末路，走投无路；磨折，磨难）","莽红尘：莽红尘（茫茫的红尘。莽，茫茫；红尘，人世间）","何处觅知音：何处觅知音（到哪里寻找知音）","青衫湿：青衫湿（青衫湿了。用白居易「江州司马青衫湿」典故——青衫湿了，指落泪）"]
  },
  "自题小像|鲁迅": {
    s: "首两句「灵台无计逃神矢，风雨如磐暗故园」写灵台无计逃神矢、风雨如磐暗故园，以「灵台无计逃神矢」用罗马神话丘比特的箭写对祖国的热爱——心灵没有办法逃脱爱神的箭，比喻对祖国的热爱无法逃避，以「风雨如磐暗故园」写对祖国命运的忧虑——风雨像巨石一样压着使故乡昏暗，比喻祖国在列强侵略下的黑暗；后两句「寄意寒星荃不察，我以我血荐轩辕」写寄意寒星荃不察、我以我血荐轩辕，以「寄意寒星荃不察」用屈原「荃不察」典故写不被理解的苦闷——把心意寄托给寒星但国君不察觉，以「我以我血荐轩辕」写献身祖国的决心——我用我的血献给轩辕（黄帝，代指中华民族），即使不被理解，也要献身祖国，全诗用典丰富、比喻新奇、情感深沉、忧国忧民、献身精神、崇高感人，「我以我血荐轩辕」成为千古名句，是七绝的千古名篇。",
    b: "鲁迅（近代文学家、思想家、革命家，原名周树人，字豫才，「中国现代文学的奠基人」）这首《自题小像》是1903年他在日本留学时剪辫后摄影题诗，「我以我血荐轩辕」是千古名句，表达了他献身祖国的崇高精神，是七绝的千古名篇。",
    n: ["自题小像：诗题，为自己的小像题诗。1903年鲁迅在日本留学时剪辫后摄影题诗","灵台无计逃神矢：灵台无计逃神矢（心灵没有办法逃脱爱神的箭。灵台，指心；神矢，爱神的箭，用罗马神话丘比特的箭，比喻对祖国的热爱）","风雨如磐暗故园：风雨如磐暗故园（风雨像巨石一样压着使故乡昏暗。磐音pán，巨石；故园，故乡，指祖国）","寄意寒星荃不察：寄意寒星荃不察（把心意寄托给寒星但国君不察觉。荃音quán，香草，代指国君，用屈原「荃不察余之中情兮」典故）","我以我血荐轩辕：我以我血荐轩辕（我用我的血献给轩辕。轩辕，黄帝，代指中华民族。荐，奉献）"]
  },
  "自嘲|鲁迅": {
    s: "首联「运交华盖欲何求，未敢翻身已碰头」写运交华盖欲何求、未敢翻身已碰头，以「运交华盖」写自己的处境——交了华盖运，以「未敢翻身已碰头」写处境的艰难——还没敢翻身就已经碰了头；颔联「破帽遮颜过闹市，漏船载酒泛中流」写破帽遮颜过闹市、漏船载酒泛中流，以「破帽遮颜过闹市」写在白色恐怖下的处境——戴着破帽遮着脸经过闹市，以「漏船载酒泛中流」写在危险中的从容——乘着漏船载着酒在中流泛舟；颈联「横眉冷对千夫指，俯首甘为孺子牛」是千古名句——横眉冷对千夫的指责，低下头甘愿做孺子的牛，以「横眉冷对千夫指」写对敌人的蔑视——怒目而视，冷对千夫的指责，以「俯首甘为孺子牛」用「孺子牛」典故写对人民的热爱——低下头甘愿做孺子的牛，甘愿为人民大众服务，对敌人恨、对人民爱，对比鲜明、崇高感人；尾联「躲进小楼成一统，管他冬夏与春秋」写躲进小楼成一统、管他冬夏与春秋，以「躲进小楼成一统」写自己的战斗方式——躲进小楼自成一统，在自己的小天地里战斗，以「管他冬夏与春秋」写对世事的蔑视——管他什么冬夏与春秋，世事变化与我无关，全诗用典贴切、对仗工稳、对比鲜明、情感深沉、蔑视敌人、热爱人民、崇高感人，「横眉冷对千夫指，俯首甘为孺子牛」成为千古名句，是七律的千古名篇。",
    b: "鲁迅这首《自嘲》写于1932年，「横眉冷对千夫指，俯首甘为孺子牛」是千古名句，表达了他对敌人的蔑视和对人民的热爱，是七律的千古名篇。",
    n: ["自嘲：诗题，自我嘲讽。1932年作","运交华盖欲何求：运交华盖欲何求（交了华盖运还想要求什么。华盖，星名，迷信认为华盖运是不好的运，鲁迅《华盖集》题记说「人是有时要交华盖运的……这运，在和尚是好运……但在俗人，却是坏运」）","未敢翻身已碰头：未敢翻身已碰头（还没敢翻身就已经碰了头）","破帽遮颜过闹市：破帽遮颜过闹市（戴着破帽遮着脸经过闹市）","漏船载酒泛中流：漏船载酒泛中流（乘着漏船载着酒在中流泛舟。中流，河流中央）","横眉冷对千夫指：横眉冷对千夫指（横眉冷对千夫的指责。横眉，怒目而视；千夫指，被千人所指，指敌人的指责）","俯首甘为孺子牛：俯首甘为孺子牛（低下头甘愿做孺子的牛。孺子牛，用《左传》「孺子牛」典故——齐景公与儿子嬉戏，口衔绳子装牛让儿子牵着，儿子跌倒扯掉了景公的牙齿。后比喻甘愿为人民大众服务）","躲进小楼成一统：躲进小楼成一统（躲进小楼自成一统。一统，统一的天下，指自己的小天地）","管他冬夏与春秋：管他冬夏与春秋（管他什么冬夏与春秋。冬夏春秋，指世事变化）"]
  },
  "无题·惯于长夜过春时|鲁迅": {
    s: "首联「惯于长夜过春时，挈妇将雏鬓有丝」写惯于长夜过春时、挈妇将雏鬓有丝，以「惯于长夜」写在黑暗中的长期生活——习惯于在漫长的黑夜中度过春天，以「挈妇将雏鬓有丝」写自己的处境——带着妻子领着孩子，鬓角已经有了白发；颔联「梦里依稀慈母泪，城头变幻大王旗」写梦里依稀慈母泪、城头变幻大王旗，以「梦里依稀慈母泪」写对烈士母亲的同情——梦里依稀看到慈母的眼泪，以「城头变幻大王旗」写军阀混战的现实——城头上变幻着大王的旗帜；颈联「忍看朋辈成新鬼，怒向刀丛觅小诗」写忍看朋辈成新鬼、怒向刀丛觅小诗，以「忍看朋辈成新鬼」写对烈士牺牲的悲痛——怎忍看朋友们变成新鬼，以「怒向刀丛觅小诗」写在白色恐怖下的战斗——愤怒地向刀丛中寻找小诗，即使在刀丛中也要用诗歌战斗，悲痛与愤怒交织；尾联「吟罢低眉无写处，月光如水照缁衣」写吟罢低眉无写处、月光如水照缁衣，以「吟罢低眉无写处」写诗歌无处发表的苦闷——吟罢低下头没有地方写，以「月光如水照缁衣」写孤独的身影——月光如水照着黑色的衣服，以景结情、含蓄深沉，全诗用典贴切、对仗工稳、情感深沉、悲痛愤怒、白色恐怖、战斗精神、含蓄感人，「忍看朋辈成新鬼，怒向刀丛觅小诗」成为名句，是七律的千古名篇。",
    b: "鲁迅这首《无题·惯于长夜过春时》写于1931年，是为纪念左联五烈士（柔石、胡也频、殷夫、李伟森、冯铿）被国民党杀害而作，「忍看朋辈成新鬼，怒向刀丛觅小诗」是名句，是七律的千古名篇。",
    n: ["无题：诗题，无题。1931年作，纪念左联五烈士","惯于长夜过春时：惯于长夜过春时（习惯于在漫长的黑夜中度过春天。长夜，比喻国民党统治下的黑暗）","挈妇将雏鬓有丝：挈妇将雏鬓有丝（带着妻子领着孩子鬓角有了白发。挈音qiè，带着；将，领着；雏音chú，孩子；鬓有丝，鬓角有白发）","梦里依稀慈母泪：梦里依稀慈母泪（梦里依稀看到慈母的眼泪。依稀，仿佛）","城头变幻大王旗：城头变幻大王旗（城头上变幻着大王的旗帜。大王旗，指军阀的旗帜）","忍看朋辈成新鬼：忍看朋辈成新鬼（怎忍看朋友们变成新鬼。忍看，怎忍看；朋辈，朋友们，指左联五烈士柔石、胡也频、殷夫、李伟森、冯铿）","怒向刀丛觅小诗：怒向刀丛觅小诗（愤怒地向刀丛中寻找小诗。刀丛，比喻国民党的白色恐怖）","吟罢低眉无写处：吟罢低眉无写处（吟罢低下头没有地方写。无写处，没有地方发表）","月光如水照缁衣：月光如水照缁衣（月光如水照着黑色的衣服。缁音zī，黑色）"]
  }
};
